\subsection{Proof of \Cref{thm:classical-security}}
\label{sub:proof_of_classical-security}

In this appendix, we present the full proof of \Cref{thm:classical-security}.
The proof uses notations and tools in probabilistic graphical models,
of which background is provided in \Cref{sec:background_on_probabilistic_graphical_models}.

\begin{proof}[Proof of \Cref{thm:classical-security}]
	Let us fix any scheduler $S$ of the system.
	Since we allow the program $P$ to be probabilistic (e.g., $P_v$ in \Cref{fig:userv} is already probabilistic),
	the value of any register can be regarded as a random variable.
	%where the randomness comes from all subjects using random numbers.
	For example, $A(t)$, the value of the register $A$ at time $t$,
	is a random variable.
	Similarly, $\alpha(t)$, the request at time $t$ in the history,
	can also be seen as a random variable.

	Let us first identify several time points $t_1,t_{v,j},t_v,t_2$ with respect to program $P_v$ in \Cref{fig:userv}, by supposing:
	\begin{itemize}
		\item 
			At $t=t_1-1$: $v$ issues the write request in Line $1$
		\item
			At $t=t_{v,j}-1$: $v$ issues the write request for $j$ in Line $3$.
		\item
			At $t=t_v-1$: $v$ issues the write request in Line $5$.
		\item
			At $t=t_2-1$: $v$ issues the write request in Line $6$.
	\end{itemize}

	For convenience, let us denote $D_j:=C_j,L\bracks*{w_j}$.
	Note that from $M_0,M_1,M_2$, we have
	\begin{equation*}
		\Obs\parens*{w_j,t}=
		\begin{cases}
			D_j\parens*{t}, & t\leq t_2,\\
			B\parens*{t},D_j(t), & t\geq t_2+1.
		\end{cases}
	\end{equation*}
	where we denote a set by an ordered list and will use this convention throughout the proof.

	We can restrict $t_u=t_1$ and $t_w\geq t_2+1$ in \Cref{thm:classical-security}.
	This is because if $t_u\neq t_1$ and $A\parens*{t_u}\neq A\parens*{t_1}$, or if $t_w\leq t_2$,
	then there is no information flow from $A\parens*{t_u}$ to $\Obs\parens*{w_j,t_w}$ and thus $A\parens*{t_u}\CI\Obs\parens*{w_j,t_w}$.
	%In this case, the secret information of $u$ never leaks to any $w_j$.
	Moreover, since the access matrix $\Macc$ (taking values in $M_0,M_1,M_2$) is always symmetric for all $w_j$,
	we can only prove for the case $j=1$ without loss of generality.
	%without loss of generality, our goal can be reduced to proving
	Now proving \Cref{thm:classical-security} reduces to proving
	\begin{equation}
		I\parens*{A\parens*{t_1}; B\parens*{t_w},D_1\parens*{t_w}} \leq 2^{-\parens*{n-7}/2}
		\label{eq:classical-goal}
	\end{equation}
	for any $t_w\geq t_2+1$.

	We identify and define all random variables of concern in our proof as follows.
	\begin{itemize}
		\item 
			$A(t_1)$ stores the secret information written by $u$ into $A$.
		\item
			Let $X_j:=C_j^1(t_{v,j})$,
			where $C_j^1$ denotes the first bit of $C_j$.
			Let $\Lambda_j:=C_j^{\overline{1}}(t_{v,j}),L\bracks*{w_j}\parens*{t_{v,j}}$,
			where $C_j^{\overline{1}}$ denotes the remaining bits (except for the first bit) of $C_j$.
		\item
			$B(t_{v})$ stores the information written by $v$ into $B$, which also encodes the secret information of $u$. 
		\item
			For each $j\in [n]$, let 
			\begin{equation*}
				Y_j:= \abs*{\braces*{t\in [t_v+1,t_2-1]:\alpha(t)=(w_j, \texttt{flip},B)}}\bmod 2
			\end{equation*}
			denote the parity of the number of \texttt{flip} exercised by $w_j$ on $B$ for $t\in [t_v+1,t_2-1]$.
		\item
			$B(t_2)$ is obtained from $B\parens*{t_v}$ after each $w_j$ exercises a number of \texttt{flip}.
		\item
			$B(t_w)$ and $D_j(t_w)$ contain all information accessible to $w_j$ at time $t_w\geq t_2+1$.
	\end{itemize}

	For convenience, we also define the following notations:
	\begin{itemize}
		\item 
			Let $X:=X_1, \ldots, X_n$. %The same convention applies to $Y$ and $\Lambda$.
		\item
			Let $X_{\overline{j}}:=X_1,\ldots, X_{j-1},X_{j+1},\ldots,X_n$ for $j\in [n]$.
		\item
			Let $X'=X_{\overline{1}}$.
	\end{itemize}
	The above notations apply when $X$ is replaced by $Y$ or $\Lambda$.

	By the program $P_v$ of $v$ described in~\Cref{fig:userv},
	the change of access matrix $\Macc(t)$ in~\Cref{fig:acc-matrix-1,fig:acc-matrix-2,fig:acc-matrix-3},
	and the temporal ordering of requests,
	the relations between concerned random variables can be summarised in the probabilistic graphical model in~\Cref{fig:graphical}.

	\begin{figure*}
		\centering
		%\includegraphics[width=0.3\textwidth]{Bayesian.pdf}~
		\includegraphics[width=0.6\textwidth]{Graphical.pdf}
		\caption{
			Probabilistic graphical model of concerned random variables in the system described in~\Cref{sub:problem_setting}.
                As usual, a directed edge represents a causal relation, and a bidirected edge represents a mutual dependence.
			The LHS depicts the relations between $A\parens*{t_1},D_j\parens*{t_{v,j}},Y_j,B\parens*{t_v},B\parens*{t_2},B\parens*{t_w},D_j\parens*{t_w}$.
			The RHS depicts the relations between $X,Y,\Lambda$, where nodes in each gray area (e.g., $X_1,\ldots,X_n$) are fully connected (by bidirected edges).
		}
		\label{fig:graphical}
	\end{figure*}

	Let us also fix some $a,b\in \braces*{0,1}$ and integer $d$.
	From~\Cref{fig:graphical}, we can decompose the joint probability distribution of these concerned random variables as
	\begin{align}
		\label{eq:joint-original}
        \begin{split}
		&\Pr[A(t_1)=a,B(t_v)=b_1, B(t_2)=b,X=x,\\
        &\qquad\qquad\qquad\qquad\qquad \qquad \Lambda=\lambda,Y=y, D_1(t_w)=d]
        \end{split}\\
		\begin{split}
			=&\Pr\bracks*{A(t_1)=a}\Pr\bracks*{B(t_v)=b_1\midv A(t_1)=a,X=x}\\
            &\quad \Pr\bracks*{X=x,Y=y, \Lambda=\lambda}\Pr\bracks*{B(t_2)=b\midv B(t_v)=b_1,Y=y}\\
			&\qquad\Pr\bracks*{D_1(t_w)=d\midv B(t_2)=b,X=x,\Lambda=\lambda}.
		\end{split}
		\label{eq:joint-pr}
	\end{align}
	Additionally, from~\Cref{fig:graphical}, the following conditional independence relations hold:
	\begin{itemize}
		\item 
			$D_1(t_w)\CI X_{\overline{1}},\Lambda_{\overline{1}}\mid B(t_2),X_1,\Lambda_1$; 
		\item
			$X\CI \Lambda$; and
		\item
			For any $j\in [n]$,
			\begin{equation}
				Y_j\CI X_{\overline{j}},Y_{\overline{j}},\Lambda_{\overline{j}} \mid X_j,\Lambda_j\text{\ \ and\ \ }
				Y_{\overline{j}} \CI X_j,Y_j,\Lambda_j \mid X_{\overline{j}}, \Lambda_{\overline{j}}.
				\label{eq:CI-XY}
			\end{equation}
			%where $X_{\overline{j}}=X_1,\ldots,X_{j-1},X_{j+1},\ldots, X_n$ and $Y_{\overline{j}}, \Lambda_{\overline{j}}$ are similarly defined.
	\end{itemize}
	By the fixed program $P_v$ of user $v$ in \Cref{fig:userv}, we further have:
	\begin{itemize}
		\item 
			$\Pr\bracks*{X=x}=\frac{1}{2^{n-1}}$ for $x\in \braces*{0,1}^n$ with $\abs*{x}\bmod 2 = 0$.
		\item
			$B(t_v)=A(t_1)\oplus \parens*{\frac{\abs*{X}}{2}\bmod 2}$.
			As a result,
            \begin{equation*}
                \Pr\bracks*{B(t_v)=b_1\midv A(t_1)=a,X=x}\neq 0
            \end{equation*}
		  iff $\parens*{-1}^{b_1}=\parens*{-1}^{a+\abs*{x}}$.
		\item 
			$B(t_v)=B(t_2)\oplus \bigoplus_j Y_j$.
			As a result,
            \begin{equation*}
                \Pr\bracks*{B(t_2)=b \midv B(t_v)=b_1,Y=y}\neq 0
            \end{equation*}
			iff $\parens*{-1}^{\abs*{y}}=\parens*{-1}^{b+b_1}$.

			%$\Pr\bracks*{B(t_2)=b\midv \parens*{-1}^{B(t_2)}=\parens*{-1}^{a+\sum_j x_j/2 +y_j},Y=y}$
			%is non-zero only when $\parens*{-1}^{\sum_j x_j/2+y_j}=\parens*{-1}^{a+b}$.
	\end{itemize}

	Combining the above observations,
	\Cref{eq:joint-pr} can be simplified as
	\begin{equation}
		\label{eq:joint-simp}
		\begin{split}
			&\Pr\bracks*{A(t_1)=a}\Id\bracks*{\parens*{-1}^{b_1}=\parens*{-1}^{a+\abs*{x}}} \Pr\bracks*{X=x,Y=y, \Lambda=\lambda}\\
			&\quad\Id\bracks*{\parens*{-1}^{\abs*{y}}=\parens*{-1}^{b+b_1}}\Pr\bracks*{D_1(t_w)=d\midv B(t_2)=b,X_1=x_1,\Lambda_1=\lambda_1}.
		\end{split}
	\end{equation}

	To prove our goal in \Cref{eq:classical-goal}, let us start with calculating the quantity
	\begin{align}
		&\Pr\bracks*{A(t_1)=a, B(t_w)=b,D_1(t_w)=d}\\
        \begin{split}
            =&\sum_{x,y,\lambda,b_1}\Pr\big[A(t_1)=a,B(t_v)=b_1,B(t_w)=b,X=x,\\
            &\qquad\qquad\qquad\qquad\qquad\qquad\Lambda=\lambda, Y=y,D_1(t_w)=d\big]
        \end{split}\\
		\begin{split}
			=&\Pr\bracks*{A(t_1)=a}\sum_{x,y,\lambda}\Id\bracks*{\parens*{-1}^{\abs*{x}/2+\abs*{y}+a+b}=1}\Pr\bracks*{X=x,Y=y, \Lambda=\lambda}\\
			 &\qquad\qquad\qquad\Pr\bracks*{D_1(t_w)=d\midv B(t_2)=b,X_1=x_1,\Lambda_1=\lambda_1},
		\end{split}
		\label{eq:ABC-sum}
	\end{align}
	where in the last equality we replace the joint probability distribution \Cref{eq:joint-original} by \Cref{eq:joint-simp}.
	%Let $X':=X_2,\ldots ,X_n$,
	%$Y':=Y_2,\ldots ,Y_n$
	%and $\Lambda':=\Lambda_2\ldots \Lambda_n$.
	%Moreover, as
	%\begin{align*}
	%	&\Pr\bracks*{X=x}\Pr\bracks*{\Lambda=\lambda}\Pr\bracks*{Y'=y'\midv X'=x',\Lambda'=\lambda'}\Pr\bracks*{Y_1=y_1\midv X_1=x_1,\Lambda_1=\lambda_1}\\
	%	\begin{split}
	%		=&\Pr\bracks*{X'=x'\midv X_1=x_1}\Pr\bracks*{\Lambda'=\lambda'\midv \Lambda_1=\lambda_1}\Pr\bracks*{Y'=y'\midv X'=x',\Lambda'=\lambda'}\\
	%		 &\qquad\qquad \Pr\bracks*{X_1=x_1}\Pr\bracks*{\Lambda_1=\lambda_1}\Pr\bracks*{Y_1=y_1\midv X_1=x_1,\Lambda_1=\lambda_1}
	%	\end{split}
	%	\\
	%	=&\Pr\bracks*{X'=x',Y'=y',\Lambda'=\lambda'\midv X_1=x_1,\Lambda_1=\lambda_1}\Pr\bracks*{X_1=x_1,Y_1=y_1,\Lambda_1=\lambda_1}
	%\end{align*}

	Using the conditions in \Cref{eq:CI-XY} gives the term
	\begin{align*}
		&\Pr\bracks*{X=x,Y=y,\Lambda=\lambda}\\
        \begin{split}
            =&\Pr\bracks*{X'=x',Y'=y',\Lambda'=\lambda'\midv X_1=x_1,Y_1=y_1,\Lambda_1=\lambda_1}\\
		&\qquad\qquad \qquad\qquad\qquad\qquad\Pr\bracks*{X_1=x_1,Y_1=y_1,\Lambda_1=\lambda_1}
        \end{split}
		\\
        \begin{split}
            =&\Pr\bracks*{X'=x',Y'=y',\Lambda'=\lambda'\midv X_1=x_1,\Lambda_1=\lambda_1}\\
		&\qquad\qquad\qquad\qquad\qquad\qquad\Pr\bracks*{X_1=x_1,Y_1=y_1,\Lambda_1=\lambda_1}.
        \end{split}
	\end{align*}
	Consequently, \Cref{eq:ABC-sum} can be rewritten as 
	\begin{align}
		\begin{split}
		&\Pr\bracks*{A(t_1)=a}\sum_{x,y,\lambda}\Id\bracks*{\parens*{-1}^{\abs*{x}/2+\abs*{y}+a+b}=1}\\
        &\qquad\Pr\bracks*{X_1=x_1,Y_1=y_1,\Lambda_1=\lambda_1}\\
        &\qquad\qquad\Pr\bracks*{X'=x',Y'=y',\lambda'=\lambda'\midv X_1=x_1,\Lambda_1=\lambda_1}\\
		&\qquad\qquad\qquad\Pr\bracks*{D_1(t_w)=d\midv B(t_2)=b, X_1=x_1,\Lambda_1=\lambda_1}.
		\end{split}
		%\begin{split}
		%	=&\Pr\bracks*{A(t_1)=a}\sum_{x_1,y_1,\lambda_1}\sum_{x',y',\lambda'}\Id\bracks*{\parens*{-1}^{\abs*{x}/2+\abs*{y}+a+b}=1}\Pr\bracks*{X'=x',Y'=y',\Lambda'=\lambda'\midv X_1=x_1,\Lambda_1=\lambda_1}\\
		%	 &\qquad\qquad\Pr\bracks*{X_1=x_1,Y_1=y_1,\Lambda_1=\lambda_1}\Pr\bracks*{C_1(t_w)=c\midv B(t_2)=b, X_1=x_1,\Lambda_1=\lambda_1}
		%\end{split}
		\label{eq:split-X1}
	\end{align}
	For convenience, let us define
	\begin{align}
        \begin{split}
            &f_a(x_1,y_1,\lambda_1):=
		\sum_{x',y',\lambda'}\Id\bracks*{\parens*{-1}^{\abs*{x}/2+\abs*{y} +a+b}=1}\\
        &\qquad\qquad\Pr\bracks*{X'=x',Y'=y',\Lambda'=\lambda'\midv X_1=x_1,\Lambda_1=\lambda_1},\label{eq:f-def}
        \end{split}
		\\
		&g:=
			\frac{4\Pr\bracks*{D_1(t_w)=d, B(t_2)=b}}
		{\sum_{x_1,\lambda_1}\Pr\bracks*{\Lambda_1=\lambda_1}\Pr\bracks*{D_1(t_w)=d\midv B(t_2)=b, X_1=x_1,\Lambda_1=\lambda_1}}.
		\label{eq:g-def}
	\end{align}
	Then, using the technical \Cref{lmm:f-bound,lmm:g-bound},
	we can rewrite \Cref{eq:split-X1} as
	\begin{align}
		\begin{split}
			&\Pr\bracks*{A(t_1)=a}\sum_{x_1,y_1,\lambda_1} f_a(x_1,y_1,\lambda_1)\Pr\bracks*{X_1=x_1,Y_1=y_1,\Lambda_1=\lambda_1}\\
			&\qquad\qquad\qquad\Pr\bracks*{D_1(t_w)=d\midv B(t_2)=b,X_1=x_1,\Lambda_1=\lambda_1}
		\end{split}
		\label{eq:ABC-rewrite}\\
		\begin{split}
			=& \Pr\bracks*{A\parens*{t_1}=a}\parens*{\frac{1}{2}+\delta}
			 \sum_{x_1,\lambda_1}\Pr\bracks*{X_1=x_1}\Pr\bracks*{\Lambda_1=\lambda_1}\\
			 &\qquad\qquad
			 \Pr\bracks*{D_1(t_w)=d\midv B(t_2)=b,X_1=x_1,\Lambda_1=\lambda_1}
		\end{split}
		\label{eq:replace-f}
		\\
		=& \Pr\bracks*{A\parens*{t_1}=a}\parens*{1+2\delta}\Pr\bracks*{D_1\parens*{t_w}=d,B\parens*{t_2}=b} g^{-1} \label{eq:plug-in-g}\\
		=& \parens*{1+2\delta}\parens*{1+\epsilon}^{-1}\Pr\bracks*{A\parens*{t_1}=a}\Pr\bracks*{D_1\parens*{t_w}=d,B\parens*{t_2}=b}
		\label{eq:replace-g}
	\end{align}
	for some $\abs*{\delta}\leq 2^{-(n-1)/2}$ and $\abs*{\epsilon}\leq 2^{-(n-3)/2}$.
	Here, \Cref{eq:replace-f} comes from \Cref{lmm:f-bound} and $X_1\CI \Lambda_1$;
	\Cref{eq:plug-in-g} comes from $\Pr\bracks*{X_1=x_1}=\frac{1}{2}$;
	and \Cref{eq:replace-g} comes from \Cref{lmm:g-bound}.

	All the above together yield $\Pr\bracks*{A(t_1)=a,B(t_w)=b,D_1(t_w)=d}=\Cref{eq:replace-g}$.
	Now we are ready to compute
	\begin{align*}
		&\frac{\Pr\bracks*{A(t_1)=a\midv B(t_w)=b,D_1(t_w)=d}}{\Pr\bracks*{A(t_1)=a}}\\
		=&\frac{\Pr\bracks*{A(t_1)=a,B(t_w)=b,D_1(t_w)=d}}{\Pr\bracks*{A(t_1)=a}\Pr\bracks*{B(t_w)=b,D_1(t_w)=d}}\\
		=&\parens*{1+2\delta}\parens*{1+\epsilon}^{-1},
	\end{align*}
	which can be upper bounded by $\frac{1+2^{-(n-3)/2}}{1-2^{-(n-3)/2}}\leq 1+2^{-(n-7)/2}$.
	Finally, using the inequality $\log\parens*{1+z}\leq z$ and the definition of mutual information leads to \Cref{eq:classical-goal}.
\end{proof}

In the following are two technical lemmas used in the proof of \Cref{thm:classical-security}.
Intuitively, \Cref{lmm:f-bound} says $f_a(x_1,y_1,\lambda_1)$ is close to $1/2$,
and \Cref{lmm:g-bound} says $g$ is close to $1$.

\begin{lemma}
	\label{lmm:f-bound}
	Let $f_a(x_1,y_1,\lambda_1)$ be defined as in \Cref{eq:f-def}.
	Then, for any $x_1,y_1\in \braces*{0,1}$, 
	\begin{equation}
		\abs*{f_a(x_1,y_1,\lambda_1)-\frac{1}{2}}\leq 2^{-(n-1)/2}.
		\label{eq:f_a-bound}
	\end{equation}
\end{lemma}

\begin{proof}
	Using \Cref{eq:CI-XY} and $X\CI \Lambda$, we have
	\begin{align*}
				&\Pr\bracks*{X'=x', Y'=y',\Lambda'=\lambda'\midv X_1=x_1,\Lambda_1=\lambda_1}\\
		=&\Pr\bracks*{Y'=y'\midv X'=x',\Lambda'=\lambda'}\\
        &\qquad\qquad\qquad\Pr\bracks*{X'=x'\midv X_1=x_1}\Pr\bracks*{\Lambda'=\lambda'\midv \Lambda_1=\lambda_1}.
	\end{align*}
	Let $X'',\Lambda''$ be random variables such that
        \begin{align*}
    	\Pr\bracks*{X''=x'}&=\Pr\bracks*{X'=x'\midv X_1=x_1}\\
    	\Pr\bracks*{\Lambda''=\lambda'}&=\Pr\bracks*{\Lambda'=\lambda'\midv \Lambda_1=\lambda_1}.
        \end{align*}
	It is easy to see that the probability distribution of $X''$ is uniform over the set 
	\begin{equation*}
		\braces*{x'\in \braces*{0,1}^{n-1}: \abs*{x'}\bmod 2 =x_1}.
	\end{equation*}
	In this case, we can rewrite \Cref{eq:f-def} as
	\begin{equation}
		\label{eq:f_a-rewrite}
		f_a(x_1,y_1,\lambda_1)=\Pr_{\Lambda''}\bracks*{\parens*{-1}^{\abs*{X''}/2+\abs*{Y'}+a+b+x_1/2+y_1}=1},
	\end{equation}
	where we use the subscript $\Lambda''$ to indicate this hidden random variable.
	%where $X'$ is uniformly chosen from $\overline{\calX}$.

	Let us write $X''=X_2''\ldots X_n''$
	and the same convention applies to $\Lambda''$.
	Similar to \Cref{eq:CI-XY},
	we have $Y_j\CI X_{\overline{j}}'',Y_{\overline{j}}'',\Lambda_{\overline{j}}''\mid X_j'',\Lambda_j''$,
	and consequently
	\begin{align*}
		\Pr\bracks*{Y'=y'\midv X''=x',\Lambda''=\lambda'}
				&=\prod_{j\geq 2}\Pr\bracks*{Y_j=y_j\mid X''=x',\Lambda''=\lambda'}\\
				&=\prod_{j\geq 2}\Pr\bracks*{Y_j=y_j\midv X_j''=x_j,\Lambda_j''=\lambda_j}.
	\end{align*}

	Hence, the conditions in \Cref{lmm:Mermin} are satisfies.
	By Mermin inequality in \Cref{lmm:Mermin}, we have 
	\begin{equation*}
		\abs*{\E\bracks*{\parens*{-1}^{\abs*{X''}/2+\abs*{Y'}+x_1/2}}}\leq 2^{-(n-1)/2+1}.
	\end{equation*}
	Note that 
	\begin{align*}
		&\Pr\bracks*{\parens*{-1}^{\abs*{X''}/2+\abs*{Y'}+x_1/2}=1}-\Pr\bracks*{\parens*{-1}^{\abs*{X''}/2+\abs*{Y'}+x_1/2}=-1}\\
        =&\E\bracks*{\parens*{-1}^{\abs*{X''}/2+\abs*{Y'}+x_1/2}}
        \end{align*}
        and
        \begin{equation*}
        \Pr\bracks*{\parens*{-1}^{\abs*{X''}/2+\abs*{Y'}+x_1/2}=1}+\Pr\bracks*{\parens*{-1}^{\abs*{X''}/2+\abs*{Y'}+x_1/2}=-1}
        =1.
        \end{equation*}
	Therefore, we can derive for any $a\in \braces*{0,1}$:
	\begin{equation}
		\abs*{\Pr\bracks*{\parens*{-1}^{\abs*{X''}/2+\abs*{Y'}+x_1/2+a+b+y_1}=1}-\frac{1}{2}}\leq 2^{-(n-1)/2},
		\label{eq:Mermin-pr}
	\end{equation}
	and \Cref{eq:f_a-bound} immediately follows from \Cref{eq:f_a-rewrite}.
	%we have $\abs*{f_a(x_1,y_1)-\frac{1}{2}}\leq 2^{-(n-1)/2}$.
\end{proof}

\begin{lemma}
	\label{lmm:g-bound}
	Let $g$ be defined as in \Cref{eq:g-def}.
	Then, we have
	\begin{equation}
		\abs*{g-1}\leq 2^{-(n-3)/2}.
		\label{eq:random-B}
	\end{equation}
\end{lemma}

\begin{proof}
	Note that 
	\begin{align*}
				&\Pr\bracks*{B(t_2)=b\midv X_1=x_1,\Lambda_1=\lambda_1}\\
		=&\Pr\bracks*{\parens*{-1}^{\abs*{X}/2+\abs*{Y}+A(t_1)+b}=1\midv X_1=x_1,\Lambda_1=\lambda_1}\\
        \begin{split}
            =&\sum_{a',y_1}\Pr\Big[\parens*{-1}^{\abs*{X'}/2+\abs*{Y'}+a'+b+x_1/2+y_1}=1\Big\vert\\ &\qquad\qquad A(t_1)=a', Y_1=y_1, X_1=x_1,\Lambda_1=\lambda_1\Big]\\
            &\qquad\qquad\qquad\Pr\bracks*{A(t_1)=a',Y_1=y_1\midv X_1=x_1,\Lambda_1=\lambda_1}
        \end{split}\\  
		=&\sum_{a',y_1} f_{a'}(x_1,y_1,\lambda_1) \Pr\bracks*{A(t_1)=a',Y_1=y_1\midv X_1=x_1,\Lambda_1=\lambda_1}.
	\end{align*}
	Thus, using \Cref{lmm:f-bound},
	we have 
        \begin{equation*}
            \abs*{\Pr\bracks*{B(t_2)=b\midv X_1=x_1,\Lambda_1=\lambda_1}-\frac{1}{2}}\leq 2^{-(n-1)/2}.
        \end{equation*}

	Next, by $X_1\CI \Lambda_1$, we can write
	\begin{align*}
		&\Pr\bracks*{D_1(t_w)=d, B(t_2)=b}\\
		%=&\sum_{x_1}\Pr\bracks*{C_1(t_w)=c,B(t_2)=b\midv X_1=x_1}\Pr\bracks*{X_1=x_1}\\
		=&\sum_{x_1,\lambda_1}\Pr\bracks*{D_1(t_w)=d\midv B(t_2)=b, X_1=x_1,\Lambda_1=\lambda_1}\\
		 &\qquad\Pr\bracks*{B(t_2)=b\midv X_1=x_1,\Lambda_1=\lambda_1}\Pr\bracks*{X_1=x_1}\Pr\bracks*{\Lambda_1=\lambda_1}.
	\end{align*}
	Combining the above with $\Pr\bracks*{X_1=x_1}=\frac{1}{2}$ and the definition of $g$ in \Cref{eq:g-def},
	our goal \Cref{eq:random-B} easily follows.
\end{proof}

\subsection{Proof of \Cref{lmm:Mermin}}
\label{sub:proof_of_Mermin}

In this subsection we provide a proof of the variant of Mermin inequality in \Cref{lmm:Mermin} for completeness.
The proof idea is almost the same as the one in~\cite{Mermin90}.

\begin{proof}[Proof of \Cref{lmm:Mermin}]
	First note that
	\begin{equation*}
		\E\bracks*{(-1)^{\abs*{X}/2 +\abs*{Y}+b/2}}=\sum_{\lambda} \Pr\bracks*{\Lambda=\lambda} \E\bracks*{\parens*{-1}^{\abs*{X}/2+\abs*{Y}+b/2}\midv \Lambda=\lambda}.
	\end{equation*}
	To prove the target inequality \Cref{eq:Mermin-ex}, it suffices to prove that
	\begin{equation}
		\abs*{\E\bracks*{\parens*{-1}^{\abs*{X}/2+\abs*{Y}+b/2}\midv \Lambda=\lambda}}\leq 2^{-n/2+1}.
		\label{eq:mermin-suffice}
	\end{equation}

	%Note that for any $k\in [n]$,
	%$\Ex\bracks*{(-1)^{Y_k}\midv X_k=x_k}=\Pr\bracks*{Y_k=0\midv X_k=x_k}-\Pr\bracks*{Y_k=1\midv X_k=x_k}$.
	%Let $\overline{x}=x_2\ldots x_k$.
	Let us consider the quantity
	\begin{equation}
		F_b:=
		\begin{cases}
            \begin{aligned}
                &\reop\Big(\prod_{j\in [n]} \big(\Ex\bracks*{(-1)^{Y_j}\midv X_j=0,\Lambda_j=\lambda_j}+\\
                &\qquad\qquad i\Ex\bracks*{(-1)^{Y_j}\midv X_j=1,\Lambda_j=\lambda_j}\big)\Big),
            \end{aligned}
			& b=0,\\
            \begin{aligned}
                &-\imop\Big(\prod_{j\in [n]} \big(\Ex\bracks*{(-1)^{Y_j}\midv X_j=0,\Lambda_j=\lambda_j}+\\
                &\qquad\qquad\Ex\bracks*{(-1)^{Y_j}\midv X_j=1,\Lambda_j=\lambda_j}\big)\Big),
            \end{aligned}
			& b=1.\\
		\end{cases}
		\label{eq:F-form-1}
	\end{equation}

	Since each term $\E\bracks*{\parens*{-1}^{Y_j}\midv X_j=a,\Lambda_j=\lambda_j}\in [-1,1]$,
	it is easy to see that
	\begin{equation}
		\abs*{F_b}\leq \parens*{\sqrt{2}}^n=2^{n/2}.
		\label{eq:F-bound}
	\end{equation}

	On the other hand, by calculation, we obtain
	\begin{equation}
		F_b=\sum_{x\in \calX_b}\parens*{-1}^{\abs*{x}/2+b/2}\prod_{j}\Ex\bracks*{\parens*{-1}^{Y_j}\midv X_j=x_j,\Lambda_j=\lambda_j}.
		\label{eq:F-b}
	\end{equation}
	Since $\E\bracks*{(-1)^{Y_j}\midv X_j=x_j,\Lambda_j=\lambda_j}=\Pr\bracks*{Y_j=0\midv X_j=x_j,\Lambda_j=\lambda_j}-\Pr\bracks*{Y_j=1\midv X_j=x_j,\Lambda_j=\lambda_j}$, we further have
	\begin{align}
		\Cref{eq:F-b} &=\sum_{x\in \calX_b}\parens*{-1}^{\abs*{x}/2+b/2}\sum_{y\in \calY} \parens*{-1}^{\abs*{y}}\Pr\bracks*{Y=y\midv X=x,\Lambda=\lambda} \\
					  &=\sum_{x\in \calX_b}\Ex\bracks*{\parens*{-1}^{\abs*{x}/2+ \abs*{Y}+b/2}\midv X=x,\Lambda=\lambda}.
					  \label{eq:F-form-2}
	\end{align}
	As $\Lambda$ is independent of $X$,
	$\Pr\bracks*{X=x\midv \Lambda=\lambda}=\Pr\bracks*{X=x}=\frac{1}{2^{n-1}}$ for any $x\in \calX$.
	Consequently, 
	\begin{align*}
		\Cref{eq:F-form-2}&=2^{n-1}\sum_{x\in \calX_b}\Ex\bracks*{\parens*{-1}^{\abs*{x}/2+\abs*{Y}+b/2}\midv X=x,\Lambda=\lambda}\Pr\bracks*{X=x\midv \Lambda=\lambda}\\ %\label{eq:F-form-2}
						  &=2^{n-1}\E\bracks*{\parens*{-1}^{\abs*{X}/2+\abs*{Y}+b/2}\midv \Lambda=\lambda}.
	\end{align*}
	Finally, combining the above with \Cref{eq:F-bound} yields \Cref{eq:mermin-suffice}.
\end{proof}

\subsection{Proof of Lemmas about Flexibility}
\label{sub:proof_of_lemmas_about_flexibility}

In this subsection, we present detailed proofs of several lemmas about flexibility in \Cref{sub:comparison_of_flexibility}.

\subsubsection{Proof of \Cref{thm:flex-hierarchy}}
\label{sub:proof_of_flex_hierarchy}

Let us first prove the remaining parts of \Cref{thm:flex-hierarchy},
which can be broken into the following two lemmas for $\mathsf{M}=\GRP$ and $\mathsf{M}=\ENT$, respectively.
%Let us prove them one by one.

%\begin{lemma}
%	\label{lmm:flex-subsystem}
%	For any $k\geq 2$, $\SUBSYS^{k-1}<\SUBSYS^{k}$.
%\end{lemma}

\begin{lemma}
	\label{lmm:flex-grp}
	For any $k\geq 2$, $\GRP^{k-1}<\GRP^k$.
\end{lemma}

\begin{proof}
	\qquad
	\begin{enumerate}
		\item 
			We first prove that $\GRP^k \not\leq \GRP^{k-1}$.
			The proof idea is by noticing that
			a system in $\GRP^k$ can assign all quantum registers into $k$ groups,
			while a system in $\GRP^{k-1}$ can only assign them into $k-1$ groups.
			Using the pigeonhole principle, 
			there will be two quantum registers that belong to different groups in the former system,
			and to the same group in the latter system.
			Then, intuitively, we can show that latter system authorise strictly more requests than the former.

			Let us consider a system $\calA=\parens*{\Sub,\Obj,\Rt, \Atr,\Rule}\in \GRP^k$,
			where $\Rtc=\emptyset$, $\Rtq=\braces*{\texttt{CNOT}}$,
			$\Sub=\braces*{u,v}$, $\Objc=\emptyset$, and $\Objq=\braces*{X_1,\ldots, X_{2k}}$.
			Here, $\texttt{CNOT}$ means the ability to perform a $\mathit{CNOT}$ gate.
			%Denote subsystem $q=\Objq$.
			Attributes $\Mcc,\Mq, G\in \Atr$ are initialised as follows.
			Since $\Objc=\emptyset$, we set $\Mcc=\emptyset$.
			For $s\in \Sub, o\in \Objq$:
			\begin{equation*}
				\Mq\bracks*{s,o}=
				\begin{cases}
					\braces*{\texttt{CNOT}}, & s=u,\\
					0, & o.w.
				\end{cases}
			\end{equation*}
			Let $G\bracks*{X_j}=\floor*{\parens*{j+1}/2}$ for $j\in [2k]$.

			Assume for contradiction that there exists another system $\calA'=\parens*{\Sub,\Obj',\Rt', \Atr',\Rule'}\in \GRP^{k-1}$ 
			with $\Mcc',\Mq', G'\in \Atr$ such that $\calA\simeq \calA'$. % Our goal is to prove $\calA\not\simeq \calA'$.
			We can further assume that $\Objc'=\emptyset$ and $\Rtc'=\emptyset$,
			because otherwise $\calA$ and $\calA'$ will be obviously inequivalent.
			Using similar reasoning to that in the proof of $\SUBSYS^{k}\not\leq\SUBSYS^{k-1}$ in \Cref{thm:flex-hierarchy},
			we can also restrict that $\Rtq'=\braces*{\texttt{CNOT}}$.

			Consider an execution $\parens*{S,P}$
			with 
            \begin{equation*}
                P_u\equiv \mathbf{for}\ l\in [k]\ \mathbf{do}\ \mathit{CNOT}\bracks*{X_{2l-1},X_{2l}}\ \mathbf{od}
            \end{equation*}
			and $P_v\equiv \bot$.
			By our construction of $\calA$,
			the history generated by $\parens*{S,P}$
			in $\calA$ is $\parens*{u,\braces*{X_{1},X_{2}}, \texttt{CNOT}},\ldots, \parens*{u,\parens*{X_{2k-1},X_{2k}},\texttt{CNOT}}$
			and authorised according to \Cref{def:group-control}.
			Since we assume $\calA\simeq\calA'$, the history generated by $\parens*{S,P}$ in $\calA'$
			is also authorised, which implies $\texttt{CNOT}\in \Mq'\bracks*{u,X_j}$ for $j\in [2k]$.

			Observe that by the pigeonhole principle,
			there must exist distinct $j_1,j_2,j_3\in [2k]$ such that 
			$G'\bracks*{X_{j_1}}=G'\bracks*{X_{j_2}}=G'\bracks*{X_{j_3}}$
			and $G\bracks*{X_{j_1}}\neq G\bracks*{X_{j_2}}$.

			Now consider another execution $\parens*{S,P'}$ with
			$P_u'\equiv \mathit{CNOT}\bracks*{X_{j_1},X_{j_2}}$ and $P_v'\equiv \bot$.
			The histories generated by $\parens*{S,P'}$ in $\calA$ and $\calA'$
			are the same $\parens*{u, \braces*{X_{j_1}, X_{j_2}},\texttt{CNOT}}$.
			By our construction of $\calA$, this history is unauthorised in $\calA$ as $G\bracks*{X_{j_1}}\neq G\bracks*{X_{j_2}}$ 
			(see the authorisation rule in \Cref{def:group-control}).
			However, it is authorised in $\calA'$ because $G'\bracks*{X_{j_1}}= G'\bracks*{X_{j_2}}$.
			Hence, we obtain a contradiction and the conclusion follows.
		\item
			Next we prove that $\GRP^{k-1}< \GRP^k$.

			Suppose that $\calA=\parens*{\Sub, \Obj,\Rt,\Atr, \Rule}\in \GRP^{k-1}$ with $\Mcc,\Mq,G\in \Atr$.
			Then, we can define another system $\calA'=\parens*{\Sub,\Obj,\Rt, \Atr',\Rule}\in \GRP^{k}$ with $\Mcc',\Mq',G'\in \Atr$,
			such that $\Mcc'=\Mcc$, $\Mq'=\Mq$, 
			and $G'\bracks*{o}=G\bracks*{o}$ for any $o\in \Objq$.
			It is easy to see that $\calA\simeq \calA'$ in this case.
	\end{enumerate}
\end{proof}

\begin{lemma}
	\label{lmm:flex-ent}
	$\ENT^1< \ENT^2$.
\end{lemma}

\begin{proof}
	\qquad
	\begin{enumerate}
		\item 
			First we prove $\ENT^2\not\leq \ENT^1$.
			The proof idea is by observing that 
			the attribute $\Me$ of a system in $\ENT^2$ records whether two quantum registers can be entangled,
			while $\Me$ of a system in $\ENT^1$ only records whether a quantum register can be entangled with others.
			Therefore, a system in $\ENT^2$ has a more fine-grained control of entanglement than a system in $\ENT^1$.

			Let us consider a system $\calA=\parens*{\Sub,\Obj, \Rt,\Atr,\Rule}\in \ENT^2$,
			where $\Rtc=\emptyset$, $\Rtq=\braces*{\texttt{CNOT},\texttt{measure}}$,
			$\Sub=\braces*{u,v}$, $\Objc=\emptyset$, and $\Objq=\braces*{X_1,X_2,X_3,X_4}$.
			Here, $\texttt{measure}$ means the ability to perform a complete measurement.
			Attributes $\Mcc,\Mq,\Me,D\in \Atr$ are initialised as follows.
			As $\Objc=\emptyset$, we set $\Mcc=\emptyset$.
			%\begin{equation*}
			%	\Mcc\bracks*{s,o} =
			%	\begin{cases}
			%		\braces*{\texttt{read},\texttt{write}}, & s=u,\\
			%		\emptyset, & o.w.
			%	\end{cases}
			%\end{equation*}
			%for $s\in \Sub, o\in \Objc$,
			%and 
			For $s\in \Sub, o\in \Objq$:
			$\Mq\bracks*{s,o}=\braces*{\texttt{CNOT},\texttt{measure}}$
			and $D\bracks*{o}=\mathit{true}$.
			For $s\in \Sub,o\in \calP_2\parens*{\Objq}$:
			\begin{equation*}
				\Me\bracks*{o}=
				\begin{cases}
					\mathit{true}, & o=\braces*{X_1,X_2}\vee o=\braces*{X_3,X_4},\\
					\mathit{false}, & o.w.
				\end{cases}
			\end{equation*}

			Assume for contradiction that there exists another system $\calA'=\parens*{\Sub,\Obj',\Rt',\Atr',\Rule'}\in \ENT^1$
			with $\Mcc',\Mq',\Me',D'\in \Atr'$ such that $\calA\simeq$
			We can further assume that $\Objc'=\emptyset$ and $\Rtc'=\emptyset$,
			because otherwise $\calA$ and $\calA'$ will be obviously inequivalent.
			Using similar reasoning to that in the proof of $\SUBSYS^{k}\not\leq\SUBSYS^{k-1}$ in \Cref{thm:flex-hierarchy},
			we can also restrict that $\Rtq'=\braces*{\texttt{CNOT},\texttt{measure}}$.

			Consider an execution $\parens*{S,P}$ with
            \begin{equation*}
                P_u\equiv \mathit{CNOT}\bracks*{X_1,X_2}; \mathit{CNOT}\bracks*{X_3,X_4}
            \end{equation*}
			and $P_v\equiv \bot$. 
			By our construction of $\calA$,
			the history generated by $\parens*{S,P}$ in $\calA$ is 
			$\parens*{u,\braces*{X_1,X_2},\texttt{CNOT}},\parens*{u,\braces*{X_3,X_4},\texttt{CNOT}}$
			and authorised according to \Cref{def:2-ent-control}.

			On the other hand, since we assume $\calA\simeq \calA'$,
			the history generated by $\parens*{S,P}$ in $\calA'$ is also authorised.
			By \Cref{def:1-ent-control}, this implies that $\Me'\bracks*{o}=\mathit{true}$ for $o\in \braces*{X_1,X_2,X_3,X_4}$
			(meaning any quantum register in $\calA'$ can be entangled with others)
			and $\texttt{CNOT}\in \Mq'\bracks*{u,X_1}\cap \Mq'\bracks*{u,X_3}$.
			%Moreover, there are two cases:
			%either $\texttt{CNOT}\in \Mq\bracks*{u,X_1},\Mq\bracks*{u,X_3}$; or $\Rt'$ contains some rights to performs
			%quantum circuits $U_1,\ldots, U_m$ such that $U_m\ldots U_1=\mathit{CNOT}$. 
			%The latter case is similar to the one in the proof of \Cref{lmm:flex-subsystem},
			%and will yields $\calA\simeq\calA'$. It suffices to consider the former case.

			Now consider another execution $\parens*{S,P'}$
			with $P_u'\equiv \mathit{CNOT}\bracks*{X_1,X_3}$ and $P_v'\equiv \bot$.
			The histories generated by $\parens*{S,P'}$ in $\calA$ and $\calA'$ 
			are the same $\parens*{u,\braces*{X_1,X_3},\texttt{CNOT}}$.
			By our construction of $\calA$, this history is unauthorised in $\calA$ 
			because $\Me\bracks*{X_1,X_3}=\mathit{false}$ (see the authorisation rule in \Cref{def:2-ent-control}).
			However, it is authorised in $\calA'$ due to $\Me'\bracks*{X_1}=\Me'\bracks*{X_2}=\mathit{true}$
			and $\texttt{CNOT}\in \Mq'\bracks*{u,X_1}\cap \Mq'\bracks*{u,X_3}$ (see the authorisation rule in \Cref{def:1-ent-control}).
			Hence, we obtain a contradiction and the conclusion follows.
		\item
			Next we prove $\ENT^1\leq \ENT^2$.
			Consider a system $\calA=\parens*{\Sub,\Obj,\Rt,\Atr,\Rule}\in \ENT^1$ with $\Mcc,\Mq,\Me,D\in \Atr$.
			Then, we can define $\calA'=\parens*{\Sub,\Obj,\Rt,\Atr',\Rule'}\in \ENT^2$ with $\Mcc',\Mq',\Me',D'\in \Atr'$
			such that $\Mcc'=\Mcc$, $\Mq'=\Mq$, and for any $o_1\neq o_2\in \Objq$: 
			$\Me'\bracks*{o_1,o_2}=\Me\bracks*{o_1}\wedge \Me\bracks*{o_2}$
			and $D'\bracks*{o_1,o_2}=D\bracks*{o_1}\vee D\bracks*{o_2}$.
			It is easy to see that $\calA\simeq\calA'$.
	\end{enumerate}
\end{proof}

\subsubsection{Proof of \Cref{thm:flex-compare}~\Cref{thm:subsys-not-leq-grp-ent,thm:grp-not-leq-ent-subsys}}
\label{sub:proof_of_flex_compare}

Now we prove \Cref{thm:subsys-not-leq-grp-ent,thm:grp-not-leq-ent-subsys} of \Cref{thm:flex-compare}.
First, \Cref{thm:subsys-not-leq-grp-ent} in \Cref{thm:flex-compare} can be restated as the following lemma.

\begin{lemma}
	\label{lmm:subsys-comp-grp-ent}
	$\SUBSYS\not\leq \GRP,\ENT$.
\end{lemma}

\begin{proof}
	\quad
	\begin{itemize}
		\item 
			We first prove that $\SUBSYS\not\leq \GRP$.
			The proof idea is similar to that for proving $\ENT^2\not\leq \ENT^1$. 
			Intuitively, the attribute $\Mq$ in a system in $\SUBSYS$ records 
			information about subsystems which consists of multiple quantum registers,
			while the attributes $\Mq, G$ in a system in $\GRP$ only records
			information about each individual quantum register.
			In some cases, the former provides a more fine-grained control of quantum operations than the latter.

			Let us consider a system $\calA=\parens*{\Sub, \Obj, \Rt, \Atr, \Rule}\in \SUBSYS$, 
			where $\Rtc=\emptyset$, $\Rtq=\braces*{\texttt{CNOT}}$,
			$\Sub= \braces*{u,v}$, $\Objc=\emptyset$, and $\Objq=\braces*{X_1,X_2,X_3}$.
			Attributes $\Mcc,\Mq\in \Atr$ are initialised as follows.
			As $\Objc=\emptyset$, we set $\Mcc=\emptyset$.
			For $s\in \Sub,o\subseteq \Objq$.
			\begin{equation*}
				\Mq\bracks*{s,o}= 
				\begin{cases}
					\braces*{\texttt{CNOT}}, & s=u \wedge \parens*{o= \braces*{X_1,X_2}\vee o =\braces*{X_2,X_3}},\\
					\emptyset, & o.w.
				\end{cases}
				%\label{eq:sub-minus-grp}
			\end{equation*}

			Assume for contradiction that there exists another system 
			$\calA'=\parens*{\Sub,\Obj',\Rt',\Atr',\Rule'}\in \GRP$
			with $\Mcc',\Mq',G'\in \Atr'$ such that $\calA'\simeq \calA$.
			We can further assume that $\Objc'=\emptyset$ and $\Rtc'=\emptyset$,
			because otherwise $\calA$ and $\calA'$ will be obviously inequivalent.
			Using similar reasoning to that in the proof of $\SUBSYS^{k}\not\leq\SUBSYS^{k-1}$ in \Cref{thm:flex-hierarchy},
			we can also restrict that $\Rtq'=\braces*{\texttt{CNOT}}$.

			Consider an execution $\parens*{S,P}$
			with 
            \begin{equation*}
                P_u\equiv \mathit{CNOT}\bracks*{X_1,X_2}; \mathit{CNOT}\bracks*{X_2,X_3}
            \end{equation*}
			and $P_v\equiv \bot$.
			By our construction of $\calA$,
			the history generated by $\parens*{S,P}$
			in $\calA$ is $\parens*{u,\braces*{X_1,X_2},\texttt{CNOT}},\braces*{u,\braces*{X_2,X_3}, \texttt{CNOT}}$ and authorised.
			Since we assume $\calA\simeq \calA'$,
			the history generated by $\parens*{S,P}$ in $\calA'$
			is also be authorised.
			By the authorisation rule in \Cref{def:group-control}, 
			this implies that $\texttt{CNOT}\in \Mq'\bracks*{X_1}\cap \Mq'\bracks*{X_3}$ and $G'\bracks*{X_1}=G'\bracks*{X_2}=G'\bracks*{X_3}$.
			%Moreover, there are two cases:
			%either $\texttt{CNOT}\in\Mq\bracks*{u,X_1}, \Mq\bracks*{u,X_3}$;
			%or $\Rt'$ contains some rights to perform quantum circuits $U_1,\ldots, U_m$
			%such that $U_m\ldots U_1=\mathit{CNOT}$.
			%The latter case is similar to the one in the proof of \Cref{lmm:flex-subsystem},
			%and will yield $\calA'\simeq \calA$,
			%so it suffices to consider the former case.

			Now we consider another execution $\parens*{S,P'}$,
			with $P_u'\equiv \mathit{CNOT}\bracks*{X_1,X_3}$ and $P_v'\equiv \bot$.
			The histories generated by $\parens*{S,P'}$ in $\calA$ and $\calA'$ 
			are the same $\parens*{u,\braces*{X_1,X_3}, \texttt{CNOT}}$.
			By our construction of $\calA$, this history is unauthorised in $\calA$ as $\texttt{CNOT}\notin \Mq\bracks*{u,\braces*{X_1,X_3}}$ (see the authorisation rule in \Cref{def:subsys-control}).
			However, it is authorised in $\calA'$ because $\texttt{CNOT}\in \Mq'\bracks*{X_1}\cap \Mq'\bracks*{X_3}$ and $G'\bracks*{X_1}=G'\bracks*{X_3}$ (see the authorisation rule in \Cref{def:group-control}).
			Hence, we obtain a contradiction and the conclusion follows.
		\item
			Next we prove that $\SUBSYS \not\leq \ENT$.
			The proof idea is essentially using the difference between control of quantum operations and control of entanglement.
			In particular, a system in $\SUBSYS$ controls whether a quantum operation is authorised or unauthorised,
			and does not force a measurement to be applied before modifying $\Mq$.
			In contrast, a system in $\ENT$ controls whether entanglement is allowed to exist between quantum registers,
			and a measurement has to be applied if there is no promise of disentanglement,
			before we modify $\Me$ to disentangle two objects.

			Specifically, let us prove $\SUBSYS \not\leq \ENT^2$.
			Consider a system $\calA=\parens*{\Sub, \Obj, \Rt, \Atr, \Rule}\in \SUBSYS$, 
			where $\Rtc=\braces*{\texttt{read},\texttt{write}}$, $\Rtq=\braces*{\texttt{H},\texttt{CNOT},\texttt{measure}}$,
			$\Sub=\braces*{u,v}$, $\Objc=\braces*{\Mq}$, and $\Objq=\braces*{X_1,X_2,X_3}$.
			Here, $\Objc=\braces*{\Mq}$ implies that $\Mq$ can be dynamically modified.
			Attributes $\Mcc,\Mq\in \Atr$ are initialised as follows.
			For $s\in \Sub, o\in \Objc$:
			\begin{equation*}
				%\label{eq:sub-minus-ent-mc}
				\Mcc\bracks*{s,o} =
				\begin{cases}
					\braces*{\texttt{read},\texttt{write}}, & s=u,\\
					\emptyset, & o.w.
				\end{cases}
			\end{equation*}
			For $s\in \Sub, o\subseteq \Objq$:
			$\Mq\bracks*{s,o}=\braces*{\texttt{H},\texttt{CNOT}}$.
			%\begin{equation*}
			%	%\label{eq:sub-minus-ent-mq}
			%	\Mq\bracks*{s,o} = 
			%	\begin{cases}
			%		%\braces*{\texttt{H}}, & o = \braces*{X_1},\\
			%		\braces*{\texttt{CNOT}}, & o= \braces*{X_1,X_2}\vee o= \braces*{X_2,X_3},\\
			%		\emptyset, & o.w.
			%	\end{cases}
			%\end{equation*}

			Assume for contradiction that there exists another system $\calA'=\parens*{\Sub,\Obj',\Rt',\Atr',\Rule'}\in \ENT^2$
			with $\Obj'=\Objc'\cup \Objq$ and $\Mcc',\Mq',\Me',D'\in \Atr'$ such that $\calA'\simeq \calA$.
			Using similar reasoning to that in the proof of $\SUBSYS^{k}\not\leq\SUBSYS^{k-1}$ in \Cref{thm:flex-hierarchy},
			we can further restrict that $\Rtq'=\braces*{\texttt{H},\texttt{CNOT},\texttt{measure}}$.

			Consider an execution $\parens*{S,P}$.
			Here, the scheduler $S$ is defined by
			$S\parens*{\alpha\parens*{0},\ldots, \alpha\parens*{t-1}}=s\parens*{t}$,
			where $s\parens*{0}=s\parens*{1}=s\parens*{2}=u$ and $s\parens*{3}=s\parens*{4}=v$.
			The program $P$ is defined by
			\begin{equation*}
				P_u\equiv H\bracks*{X_1};\mathit{CNOT}\bracks*{X_1,X_2}; \mathit{forbid}\parens*{v,\braces*{X_1,X_2}}
			\end{equation*}
			and $P_v\equiv \bot$,
			where $\mathit{forbid}\parens*{v,\braces*{X_1,X_2}}$ 
			means to modify attributes such that future request $\parens*{v,\braces*{X_1,X_2},r}$
			will be unauthorised for any right $r$.
			By our construction of $\calA$,
			the history $\alpha$ generated by $\parens*{S,P}$
			in $\calA$ is 
			\begin{equation*}
                \begin{split}
                    &\parens*{u, \braces*{X_1}, \texttt{H}}, \parens*{u,\braces*{X_1,X_2},\texttt{CNOT}},\\
                    &\qquad\braces*{u,\Mq\bracks*{v,\braces*{X_1,X_2}},\texttt{read}}, \parens*{u, \Mq\bracks*{v,\braces*{X_1,X_2}},\texttt{write}}
                \end{split}
			\end{equation*}
			and authorised.
			%However, it is not authorised in $\calA'$, no matter how we choose $\Mq',\Me',E'$.

			On the other hand, since we assume $\calA'\simeq \calA$,
			the history $\alpha'$ generated by $\parens*{S, P}$ in $\calA'$ is also authorised.
			Note that according to the authorisation rule in~\Cref{def:2-ent-control},
			whether the future request $\parens*{v,\braces*{X_1,X_2},r}$ will be authorised in $\calA'$ is determined 
			by the attributes $\Me'\bracks*{X_1,X_2}$, $\Mq'\bracks*{v,X_1}$ and $\Mq'\bracks*{v,X_2}$.
			As $P_u$ contains $\mathit{forbid}\parens*{v,\braces*{X_1,X_2}}$,
			the above implies the following two cases:
			\begin{itemize}
				\item 
					Either there exists $t_3\in\N$ such that $\alpha'\parens*{t_3}=\parens*{u,\Me'\bracks*{X_1,X_2},r}$ 
					for some right $r$ that modifies (e.g., \texttt{write}) $\Me'\bracks*{X_1,X_2}$ to $\mathit{false}$.
					In this case, after $\mathit{CNOT}\bracks*{X_1,X_2}$ in $P_u$ is executed,
					the quantum state of $X_1,X_2$ becomes 
                    \begin{equation*}
                        \frac{1}{\sqrt{2}}\parens*{\ket{0}_{X_1}\ket{0}_{X_2}+\ket{1}_{X_1}\ket{1}_{X_2}},
                    \end{equation*}
					%Since $u$ performs $\mathit{CNOT}\bracks*{X_1,X_2}$ at the beginning,
					and we also have $D'\bracks*{X_1,X_2}=\mathit{false}$ at some time $t_1<t_3$
					(meaning that $X_1,X_2$ are not promised to be disentangled),
					due to the post-update rule in \Cref{def:2-ent-control}.
					Moreover, according to~\Cref{def:2-ent-control},
					this implies that there exists $t_2\in (t_1,t_3)$ with $\alpha'\parens*{t_2}=\parens*{s,X,\texttt{measure}}$
					for some $s\in \Sub$ and $X\in \braces*{X_1,X_2}$.
					However, such $\alpha'$ cannot be generated from program $P$,
					because $P$ does not contain measurement.
				\item
					Or there exists $t\in \N$ such that $\alpha'\parens*{t}=\parens*{u,\Mq'\bracks*{v,X},r}$
					for some right $r$ that modifies (e.g., \texttt{write}) $\Mq'\bracks*{v,X}$ and removes $\texttt{CNOT}$ from it,
					where $X\in \braces*{X_1,X_2}$.
					In this case, after the final request of $\alpha'$, we have $\texttt{CNOT}\notin\Mq'\bracks*{v,X}$.

					Now consider another execution $\parens*{S,P'}$ with $P_u'= P_u$
					and $P_v'\equiv \mathit{CNOT}\bracks*{X_2,X_3}; \mathit{CNOT}\bracks*{X_1,X_3}$.
					By the construction of the scheduler $S$,
					the history generated by $\parens*{S,P'}$ in $\calA$ is $\beta=\alpha,\parens*{v,\braces*{X_2,X_3},\texttt{CNOT}},\parens*{v,\braces*{X_1,X_3},\texttt{CNOT}}$,
					where $\alpha$ is the history generated by $\parens*{S,P}$ in $\calA$ previously.
					Since after $\alpha$, we still have $\texttt{CNOT}\in \Mq\bracks*{v,\braces*{X_1,X_3}}\cap \Mq\bracks*{v,\braces*{X_2,X_3}}$,
					the history $\beta$ is authorised in $\calA$ (see the authorisation rule in \Cref{def:subsys-control}).
					Similarly, the history generated by $\parens*{S,P'}$ in $\calA'$ is
                    \begin{equation*}
                        \beta'=\alpha',\parens*{v,\braces*{X_2,X_3},\texttt{CNOT}},\parens*{v,\braces*{X_1,X_3},\texttt{CNOT}},
                    \end{equation*}
					where $\alpha'$ is the history generated by $\parens*{S,P}$ in $\calA'$ previously.
					However, $\beta'$ is unauthorised in $\calA'$,
					because after $\alpha'$, we have $\texttt{CNOT}\notin\Mq'\bracks*{v,X}$ for some $X\in \braces*{X_1,X_2}$ 
					(see the authorisation rule in \Cref{def:2-ent-control}).
			\end{itemize}
			In either case, we obtain a contradiction and the conclusion follows.
	\end{itemize}
\end{proof}

Second, \Cref{thm:grp-not-leq-ent-subsys} in \Cref{thm:flex-compare} can be restated as the following lemma.

\begin{lemma}
	\label{lmm:grp-comp-ent-subsys}
	$\GRP \not\leq \ENT,\SUBSYS^{<N}$ and $\GRP\leq \SUBSYS$,
\end{lemma}

\begin{proof}
	\quad
	\begin{itemize}
		\item 
			We first prove that $\GRP\not\leq \SUBSYS^{< N}$.
			The proof idea is by noticing that a system in $\SUBSYS^{<N}$ only allows
			quantum operations on subsystem of size $<\abs*{\Objq}$,
			while a system in $\GRP$ can allow quantum operations on subsystem of size $\abs*{\Objq}$.

			Let us consider a system $\calA =\parens*{\Sub, \Obj, \Rt,\Atr, \Rule}\in \GRP$,
			where $\Rtc=\emptyset$, $\Rtq=\braces*{\texttt{QFT}_k}$,
			$\Sub=\braces*{u,v}$, $\Objc=\emptyset$, and $\Objq=\braces*{X_1,\ldots, X_k}$.
			Here, $\texttt{QFT}_k$ means the ability to perform a quantum Fourier transform circuit $\mathit{QFT}_k$ on $k$ qubits.
			Attributes $\Mcc,\Mq,G\in \Atr$ are initialised as follows.
			Since $\Objc=\emptyset$, we set $\Mcc=\emptyset$.
			For any $s\in \Sub, o\in \Objq$:
			\begin{equation*}
				%\label{eq:grp-minus-subsys-mq}
				\Mq\bracks*{s,o}=
				\begin{cases}
					\texttt{QFT}_k, & s=u,\\
					\emptyset, & o.w.
				\end{cases}
				%\label{eq:grp-minus-subsys-g}
			\end{equation*}
			and $G\bracks*{o}=1$.

			Consider another system $\calA'=\parens*{\Sub,\Obj,\Rt',\Atr',\Rule'}\in \SUBSYS^{<N}$
			with $\Mcc',\Mq'\in \Atr'$.
			Suppose that $\calA' \in \SUBSYS^{k'}$ for some $k'<\abs*{\Objq}=k$.

			Consider an execution $\parens*{S,P}$ with $P_u\equiv \mathit{QFT}_k$ and $P_v\equiv \bot$.
			By our construction of $\calA$,
			the history generated by $\parens*{S,P}$ in $\calA$ is 
			simply $\parens*{u,\braces*{X_1,\ldots, X_k},\texttt{QFT}_k}$ and authorised.
			Now consider the history $\alpha$ generated by $\parens*{S,P}$ in $\calA'$.
			There are two cases:
			either $\alpha$ contains multiple requests like in the proof of $\SUBSYS^k \not\leq \SUBSYS^{k-1}$ in~\Cref{thm:flex-hierarchy},
			and then we can derive $\calA\not\simeq \calA'$;
			or $\alpha=\parens*{u,\braces*{X_1,\ldots,X_k},\texttt{QFT}_k}$, which is unauthorised
			due to the authorisation rule in~\Cref{def:subsys-control} and $k=\abs*{\Objq}>k'$.
			In either case, $\calA\not\simeq \calA'$ and the conclusion follows.
		\item
			Next we prove $\GRP \not\leq \ENT$.
			Like in the proof of $\SUBSYS\not\leq \ENT$ in \Cref{lmm:subsys-comp-grp-ent},
			the idea is essentially using the difference between control of quantum operations and control of entanglement.
			Specifically, let us prove $\GRP \not\leq \ENT^2$.

			Consider a system $\calA=\parens*{\Sub, \Obj, \Rt, \Atr,\Rule}\in \GRP$,
			where $\Rtc=\braces*{\texttt{read},\texttt{write}}$, $\Rtq=\braces*{\texttt{H},\texttt{CNOT},\texttt{measure}}$,
			$\Sub=\braces*{u,v}$, $\Objc=\braces*{G}$, and $\Objq=\braces*{X_1,X_2,X_3,X_4}$.
			Note that $\Objc=\braces*{G}$ means $G$ can be dynamically modified. 
			Attributes $\Mcc,\Mq,G\in \Atr$ are initialised as follows.
			For $s\in \Sub, o\in \Objc$:
			\begin{equation}
				\Mcc\bracks*{s,o}= 
				\begin{cases}
					\braces*{\texttt{read},\texttt{write}}, & s=u,\\
					\emptyset,  & o.w.
				\end{cases}
			\end{equation}
			For $s\in \Sub,o\in \Objq$:
			$\Mq\bracks*{s,o}=\braces*{\texttt{H},\texttt{CNOT}}$.
			Let $G\bracks*{X_1}=G\bracks*{X_2}=G\bracks*{X_3}=1$ and $G\bracks*{X_4}=2$.

			Assume for contradiction that there exists another system $\calA'=\parens*{\Sub, \Obj', \Rt', \Atr', \Rule'}\in \ENT^2$
			with $\Obj'=\Objc'\cup \Objq$ and $\Mcc',\Mq',\Me',D'\in \Atr'$ such that $\calA'\simeq \calA$.
			Using similar reasoning to that in the proof of $\SUBSYS^{k}\not\leq\SUBSYS^{k-1}$ in \Cref{thm:flex-hierarchy},
			we can further restrict that $\Rtq'=\braces*{\texttt{H},\texttt{CNOT},\texttt{measure}}$.

			Consider an execution $\parens*{S,P}$.
			Here, the scheduler $S$ is defined by
			$S\parens*{\alpha\parens*{0},\ldots, \alpha\parens*{t-1}}=s\parens*{t}$,
			where $s\parens*{0}=s\parens*{1}=s\parens*{2}=u$ and $s\parens*{3}=s\parens*{4}=v$.
			The program $P$ is defined by
			\begin{equation*}
				P_u\equiv H\bracks*{X_1};\mathit{CNOT}\bracks*{X_1,X_2}; \mathit{newgrp}\parens*{X_1,X_4}
			\end{equation*}
			and $P_v\equiv \bot$, where $\mathit{newgrp}\parens*{X_1}$ means to modify attributes such that
			$X_1,X_4$ are put into a new group and any quantum operation on $X_1$ or $X_4$ should act within this group;
			i.e., for future request $\parens*{s,o,r}$, if $o\cap \braces*{X_1,X_4}\neq \emptyset$,
			then $o\subseteq \braces*{X_1,X_4}$.
			By our construction of $\calA$,
			the history generated by $\parens*{S,P}$ in $\calA$ is 
			\begin{equation*}
                \begin{split}
                    &\parens*{u,\braces*{X_1},\texttt{H}},\parens*{u,\braces*{X_1,X_2},\texttt{CNOT}},\parens*{u,G\bracks*{X_1},\texttt{read}},\\
                    &\qquad\parens*{u,G\bracks*{X_1},\texttt{write}},\parens*{u,G\bracks*{X_4},\texttt{read}},\parens*{u,G\bracks*{X_4},\texttt{write}}
                \end{split}
			\end{equation*}
			and authorised.

			The remaining reasoning is similar to the proof of $\SUBSYS\not\leq \ENT^2$ in \Cref{lmm:subsys-comp-grp-ent}.
			Since we assume $\calA\simeq \calA'$,
			the history $\alpha'$ generated by $\parens*{S,P}$ in $\calA'$ is also authorised.
			This implies initially $\Mq'\bracks*{X_1,X_2}=\mathit{true}$.
			According to the authorisation rule in \Cref{def:group-control},
			whether the future request $\parens*{s,o,r}$ with $o\cap \braces*{X_1,X_4}\neq \emptyset$
			will be authorised is determined by the attributes $\Me'\bracks*{X_1,X}$ for $X\neq X_1$,
			$\Me'\bracks*{X_4,X}$ for $X\neq X_4$,
			$\Mq'\bracks*{X_1}$ and $\Mq'\bracks*{X_4}$.
			As $P_u$ contains $\mathit{newgrp}\parens*{X_1,X_4}$, 
			which forbids future request like $\parens*{v,\braces*{X_1,X_2},r}$,
			the above implies the following two cases:
			\begin{itemize}
				\item 
					Either there exists $t\in \N$ such that $\alpha'\parens*{t}=\parens*{u,\Me'\bracks*{X_1,X_2},r}$ for some right $r$
					that modifies $\Me'\bracks*{X_1,X_2}$ to $\mathit{false}$.
					In this case, using the same reasoning as in the proof of $\SUBSYS\not\leq \ENT^2$,
					we can derive $\calA\not\simeq \calA'$.
				\item
					Or there exists $t\in \N$ such that $\alpha'\parens*{t}=\parens*{u, \Mq'\bracks*{v,X},r}$ for some right $r$
					that modifies (e.g., $\texttt{write}$) $\Mq'\bracks*{v,X}$ and removes $\texttt{CNOT}$ from it,
					where $X\in \braces*{X_1,X_2}$.
					In this case, after the final request of $\alpha'$, we have $\texttt{CNOT}\notin \Mq'\bracks*{v,X}$.

					Now consider another execution $\parens*{S,P'}$ with $P_u'=P_u$
					and $P_v'\equiv \mathit{CNOT}\bracks*{X_1, X_4}; \mathit{CNOT}\bracks*{X_2,X_3}$.
					By the construction of the scheduler $S$, 
					the history generated by $\parens*{S,P'}$ in $\calA$ is
                    \begin{equation*}
                        \beta=\alpha,\parens*{v,\braces*{X_1, X_4},\texttt{CNOT}},\parens*{v, \braces*{X_2,X_3},\texttt{CNOT}}.
                    \end{equation*}
					Since after $\alpha$, we still have $\texttt{CNOT}\in \Mq\bracks*{v,Y}$ for $Y\in \braces*{X_1,X_2,X_3,X_4}$,
					$G\bracks*{X_1}=G\bracks*{X_4}$ and $G\bracks*{X_2}=G\bracks*{X_3}$,
					the history $\beta$ is authorised in $\calA$ (see the authorisation rule in \Cref{def:group-control}).
					Similarly, the history $\beta'$ generated by $\parens*{S,P'}$ in $\calA'$ is
                    \begin{equation*}
                        \beta'=\alpha', \parens*{v, \braces*{X_1,X_4},\texttt{CNOT}},\parens*{v,\braces*{X_2,X_3},\texttt{CNOT}}.
                    \end{equation*}
					However, $\beta'$ is unauthorised in $\calA'$,
					because after $\alpha'$, we have $\texttt{CNOT}\notin \Mq'\bracks*{v,X}$ for some $X\in \braces*{X_1,X_2}$
					(see the authorisation rule in \Cref{def:2-ent-control}), .
			\end{itemize}
			In either case, we obtain a contradiction and the conclusion follows.
		\item
			Finally we prove $\GRP\leq \SUBSYS$.
			Consider a system $\calA=\parens*{\Sub, \Obj, \Rt,\Atr,\Rule}\in \GRP$ with $\Mcc,\Mq,G\in \Atr$.
			Then, we can define $\calA'=\parens*{\Sub, \Obj,\Rt,\Atr',\Rule'}\in \SUBSYS$,
			where $\Mcc',\Mq'\in \Atr'$ are defined by $\Mcc'=\Mcc$, and
			for $s\in \Sub,o\subseteq \Objq$:
			\begin{equation*}
				\Mq'\bracks*{s,o} = 
				\begin{cases}
					\bigcap_{X\in o}\Mq\bracks*{s,X}, & \forall X,Y\in o, G\bracks*{X}=G\bracks*{Y},\\
					\emptyset, & o.w.
				\end{cases}
			\end{equation*}
			It is easy to see that $\calA\simeq \calA'$ from this construction.
	\end{itemize}
\end{proof}

\section{Background on Probabilistic Graphical Models}
\label{sec:background_on_probabilistic_graphical_models}

In this section, we briefly introduce the notations and tools
in probabilistic graphical models, used in \Cref{sub:proof_of_classical-security}.
The readers are referred to the textbook~\cite{Pearl00} for a more thorough introduction.

\paragraph{Probabilities}

For a random variable $A$, we use $\Pr\bracks*{A=a}\in [0,1]$ to denote the probability of $A$ taking the value $a$.
It holds that $\sum_a \Pr\bracks*{A=a}=1$.
The joint probability 
\begin{equation*}
    \Pr\bracks*{A=a,B=b}=\Pr\bracks*{A=a\cap B=b}
\end{equation*}
denotes the probability of $A$ taking the value $a$
and another random variable $B$ taking the value $b$.
For simplicity, sometimes we simply write $A,B$ for the random variable $(A,B)$.

%If $\Pr\bracks*{B=b}>0$, the conditional probability $\Pr\bracks*{A=a\midv B=b}=\frac{\Pr\bracks*{A=a,B=b}}{\Pr\bracks*{B=b}}$
Let the conditional probability $\Pr\bracks*{A=a\mid B=b}$
be the probability of $A$ taking the value $a$ given that $B$ takes the value $b$. 
The joint probability $\Pr\bracks*{A=a,B=b}$ can be calculated by
\begin{equation}
    \label{eq:pr-product}
    \Pr\bracks*{A=a,B=b}=\Pr\bracks*{A=a\mid B=b}\cdot \Pr\bracks*{B=b}.
\end{equation}
By summing over $a$, we have the following decomposition of $\Pr\bracks*{A=a}$ by conditioning on different $B=b$:
\begin{equation}
    \Pr\bracks*{A=a}=\sum_b \Pr\bracks*{A=a\mid B=b}\cdot\Pr\bracks*{B=b}.
\end{equation}

A useful generalisation of \Cref{eq:pr-product} is the following \textit{chain rule}:
\begin{equation}
    \label{eq:chain-rule}
    \begin{split}
        &\Pr\bracks*{A_1=a_1,\ldots, A_n=a_n}\\
        =&\Pr\bracks*{A_n=a_n\mid A_{n-1}=a_{n-1},\ldots, A_1=a_1}\\
        &\qquad\qquad\ldots \Pr\bracks*{A_2=a_2\mid A_1=a_1}\Pr\bracks*{A_1=a_1}.
    \end{split}
\end{equation}

If $\Pr\bracks*{A=a\mid B=b}=\Pr\bracks*{B=b}$ whenever $\Pr\bracks*{B=b}>0$,
then $A$ and $B$ are said to be \textit{independent}, denoted by $A\CI B$.
More generally, if
\begin{equation*}
    \Pr\bracks*{A=a\mid B=b, C=c}=\Pr\bracks*{B=b\mid C=c}
\end{equation*}
whenever $\Pr\bracks*{B=b,C=c}>0$,
then $A$ and $B$ are said to be \textit{conditionally independent} given $C$, denoted by $A\CI B\mid C$.
Intuitively, it means that if we know the value of $C$, we cannot learn extra information about $A$ from learning the value of $B$.
We mention two useful properties of conditional independence:
\begin{itemize}
    \item 
        (Symmetry) $A\CI B\mid C$ implies $B\CI A \mid C$.
    \item 
        (Decomposition) $A\CI B,C \mid D$ implies $A\CI B\mid D$.
\end{itemize}
The concept of conditional independence plays an important role in probabilistic graphical models.
%$A$ and $B$ are said to be independent, if $\Pr\bracks*{A=a,B=b}=\Pr\bracks*{A=a}\cdot \Pr\bracks*{B=b}$
%for any $a$ and $b$.

As usual, we use $\E\bracks*{A}=\sum_a a\cdot \Pr\bracks*{A=a}$ to denote the expectation of $A$.

\paragraph{Probabilistic Graphical Models}

A graph can be used to represent the relations between multiple random variables.
Each vertex represents a random variable.
A \textit{directed} edge between random variables represents a \textit{causal relation};
i.e., $A\rightarrow B$ means that $A$ can influence $B$.
A \textit{bidirected} edge between random variables represent a \textit{mutual dependence},
often due to an unobserved common cause;
i.e., $A \leftrightarrow B$ means that $A$ and $B$ are dependent.
For example, in \Cref{fig:graphical},
the directed edge $A(t_1)\rightarrow B(t_v)$ comes from that 
$B(t_v)$ is written by user $v$, who reads the secret $A(t_1)$ written by user $u$;
the undirected edges between $X_1,\ldots, X_n$ comes from that
the values of these $X_j$ are randomly drawn by user $v$ from a distribution (see \Cref{fig:userv}).
Recall that in \Cref{fig:graphical}, vertices within a gray area are fully connected by bidirected edges. 

%If the graph is directed and acyclic, then
Based on the graph structure,
the joint probability of random variables corresponding to all vertices
can be decomposed into a product of conditional probabilities,
In particular, we can refine the chain rule in \Cref{eq:chain-rule} to 
\begin{equation}
    \begin{split}
        &\Pr\bracks*{A_1=a_1,\ldots, A_n=a_n}\\
        =&\prod_j \Pr\bracks*{A_j=a_j\midv \forall k, (A_k\rightarrow A_j\wedge k<j) \Rightarrow (A_k=a_k) },
    \end{split}
\end{equation}
where $A_k\rightarrow A_j$ denotes a directed edge.
%where $\operatorname{Parents}(X):=\braces*{Y:Y\rightarrow X}$ 
%stands for the set of parents of $X$.
We have used this decomposition rule to decompose \Cref{eq:joint-original} into \Cref{eq:joint-pr}
in \Cref{sub:proof_of_classical-security}.

Moreover, the graph structure allow us to
conveniently infer the conditional independence of random variables.
Let $X,Y,Z$ be sets of random variables. 
$X$ is said to be $d$-separated from $Y$ by $Z$ if,
for any (undirected) path $p$ from a node $A\in X$ to a node $B\in Y$,
one of the following conditions hold:
\begin{itemize}
    \item 
        $p$ contains $C\rightarrow D \rightarrow E$ or $C\leftarrow D\rightarrow E$ with $D\in Z$; or
    \item 
        $p$ contains $C\rightarrow D\leftarrow E$ such that for any $F$, if $D\rightarrow^* F$, then $F\notin Z$.
\end{itemize}
If $X$ is $d$-\textit{separated} from $Y$ by $Z$,
then we have $X\CI Y \mid Z$.
In \Cref{sub:proof_of_classical-security}, 
we have derived several conditional independence relations from \Cref{fig:graphical}
using this notion.

