\section{Introduction and main results}

{\em Given integers $m$ and $n,$ we define $\mb{R}^{[m,n]}:$ the set of $m$th-order $n$-dimensional tensors; $\mb{R}_{+}^{n}:$ the set of all nonnegative vectors in $\mb{R}^{n}.$ For $\mc{A}\in\mb{R}^{I_{1}\times I_{2}\times \cdots \times I_{m}}$ and $B\in\mb{R}^{J\times I_{k}}$ where $1\leq k\leq m$ is an integer, the $k$-mode product is denoted by $\mc{A}\times_k B$ and defined elementwise as
\begin{equation*}
	(\mc{A}\times_{k}B)_{i_{1}i_{2}\ldots i_{k-1} j i_{k+1} \ldots i_{m}}=\sum_{i_{k}=1}^{I_{k}}\mc{A}_{i_{1}i_{2}\ldots i_{k-1} i_{k} i_{k+1} \ldots i_{m}}B_{ji_{k}}.
\end{equation*}}
\smallskip

Given integers $m$ and $n$, a tensor $\mc{A}=(a_{i_{1}i_{2}\ldots i_{m}})\in\mb{R}^{[m,n]}$ is said to be {\it symmetric} if its entries are invariant under any permutation of their indices. A symmetric tensor $\mc{A}\in\mb{R}^{[m,n]}$ is positive semidefinite (positive definite) if $\mc{A}x^{m}\geq 0 ~(\mc{A}x^{m}> 0)$ for all $0\neq x\in \mb{R}^{n}$. Clearly, positive semidefiniteness vanishes when the order of the tensor is odd. %Thus, to study the positivity of the tensor, we consider only even-order tensors. 
Positive definite and semidefinite even-order tensors have rich applications in several branches of science and engineering including stochastic processes, polynomial theory, spectral hypergraph theory, automatic control, magnetic resonance imaging \cite{benson2017, bose1976, chang2016,  chen2012, chen2013,  cui2014, hu2012, hu2016, huq2012, hu2015, jiang2016,  qi2010}. 

In 2013, Hillar--Lim \cite{hillar2013} showed that verifying the positive definiteness of a tensor is an NP-hard problem. Since then, the positive semidefiniteness of various structured tensors has been studied in the literature. Qi--Song \cite{qi2014a} showed that the class of an even-order $B$- ($B_{0}$-) tensor is positive definite (positive semidefinite). In \cite{li2014}, Li--Wang--Zhao--Zhu--Li proved that an even-order symmetric strong $H$-tensor with positive diagonal entries is a positive definite tensor. Furthermore, in 2015, Kannan--Shaked-Monderer--Berman \cite{kannan2015} showed that a symmetric $H$-tensor with nonnegative diagonal entries is positive semidefinite. In the same year, Qi \cite{qi2015} proved that an even-order strong Hankel tensor is positive semi-definite (PSD). Chen--Qi \cite{haibin2015} showed that an even-order symmetric Cauchy tensor is PSD if and only if its generating vector is positive.

In this work, we explore the positivity of greatest common divisor tensors (GCD tensors). We need some basic definitions and notations to continue our discussion.
\begin{definition}\label{def:gcdtnsr2}
Throughout the manuscript, let $m, n \geq 2$ be integers.
\begin{enumerate}[(i)]  
    \item Let $S=\{s_{1},s_{2},\ldots,s_{n}\}$ be a set of $n$ distinct positive integers. Then the $m$th-order $n$-dimensional tensor $\mc{T}_{[S]}=(t_{i_{1}i_{2}\ldots i_{m}})\in\mb{R}^{[m,n]},$ such that 
	\[t_{i_{1}i_{2}\ldots i_{m}}=\GCD(s_{i_{1}},s_{i_{2}},\ldots,s_{i_{m}})\]
	is called the greatest common divisor (GCD) tensor on $S$.
    \item Euler's totient function $\Phi(n)$ counts the number of positive integers less than or equal to $n$ that are coprime to $n$.
\end{enumerate}

\end{definition}

The GCD matrices (second-order GCD tensors) were first studied by H.J.S. Smith in 1876. In \cite{smith1876}, he showed that for $S=\{1,2,\ldots,n\}$ the determinant of the GCD matrix $\mc{T}_{[S]}=(t_{i_{1}i_{2}})\in\mb{R}^{[2,n]}$ is $\Phi(1)\cdot \Phi(2)\cdots\Phi(n)$. A classical 1990 result of Beslin--Ligh \cite{beslin1989} showed that GCD matrices $\mc{T}_{[S]}\in\mb{R}^{[2,n]}$ are positive definite for any set $S=\{s_{1},s_{2},\ldots,s_{n}\}$ of distinct positive integers. The GCD matrices and their generalizations have since attracted the attention of number theorists and linear algebraists  \cite{ercan2017,bhat1991,haukkanen2018,haukkanen1997,ilmonen2018,lindstrom1969,mattila2014,wilf1968}. Recently, Guillot--Wu \cite{guillot2019} studied the total nonnegativity of GCD matrices.

In this short note, we study the positive definiteness of higher-order GCD tensors. To state our main results, we need the following definitions.
\begin{definition}\cite{qi2014}\label{dfn:cptnsr} Let $\mc{A}=(a_{i_{1}i_{2}\ldots i_{m}})\in\mb{R}^{[m,n]}$ be a symmetric tensor. Then
 $\mc{A}$ is said to be \textit{completely positive (CP}) if there exist $v_{1},v_{2},\ldots,v_{r}\in\mb{R}^{n}_{+}$ such that $\mc{A}=(v_{1})^{\otimes m} + (v_{2})^{\otimes m} + \cdots +(v_{r})^{\otimes m},$ where $\otimes$ denotes the outer product, and $(\cdot)^{\otimes m}=\underbrace{(\cdot)\otimes (\cdot)\otimes \cdots\otimes(\cdot)}_{m~{\rm times}}$. Moreover, if ${\rm span}\{v_{1},v_{2},\ldots,v_{r}\}=\mb{R}^{n}$, then $\mc{A}$ is called a \textit{strongly completely positive (CP)} tensor. 	
\end{definition}

Our first main result shows that every even-order GCD tensor is strongly CP.
\begin{theorem}\label{thm:gcdcpt}
	Let $S=\{s_{1},s_{2},\ldots, s_{n}\}$ be a set of $n$ distinct positive integers. 
    Then the $m$th-order $n$-dimensional GCD tensor $\mc{T}_{[S]}$ on $S$ is a strongly completely positive tensor.
\end{theorem}
As an immediate consequence of this result, we provide an algorithm for computing the strongly CP decomposition of GCD tensors.

We next study the infinite divisibility of the GCD tensor. 
\begin{definition}
Let $\mc{A}=(a_{i_{1}i_{2}\ldots i_{m}})\in\mb{R}^{[m,n]}$ be a positive semideﬁnite tensor with $a_{i_{1}i_{2}\ldots i_{m}}\geq 0$ for all $i_{1},i_{2},\ldots, i_{m}$. Then $\mc{A}$ is called inﬁnitely divisible if for every $r\in \mb{R}_+$, the fractional Hadamard power $\mc{A}^{\circ r}:=(a_{i_{1}i_{2}\ldots i_{m}}^{r})$ is positive semideﬁnite. 
\end{definition}
Infinite divisible matrices and kernels are extensively studied in the literature. These matrices and kernels attracted renewed attention in 1966 when Loewner \cite{loewner1966} showed that under certain conditions the Green's function for Laplace's equation is an infinitely divisible kernel.  In \cite{luo2016}, Luo--Qi showed that the positive Cauchy tensor, symmetric Pascal tensor, and several classes of mean tensors are infinitely divisible -- more strongly, the fractional Hadamard powers of these classes of tensors are strongly completely positive. We obtain a similar result for GCD tensors.
\begin{theorem}\label{thrmfractpwr}
Let $S=\{s_{1},s_{2},\ldots, s_{n}\}$ be a set of distinct positive integers. Let $\mc{T}_{[S]}$ be the $m$th-order $n$-dimensional GCD tensor on $S$. Then $\mc{T}_{[S]}^{\circ r}$ is strongly completely positive for every nonnegative real number $r$.
\end{theorem}

We now turn our attention to the determinant of the GCD tensor. The study of hyperdeterminants of tensors was initiated by Cayley \cite{cayley1845} in 1845, and was revived a century later in 1994 by  Gelfand--Kapranov--Zelevinsky \cite{gelfand2008}. In 2005, Qi \cite{qi2005}  introduced the notion of symmetric hyperdeterminant of symmetric tensors to study the eigenvalues of symmetric tensors.  In 2013, Hu--Huang--Ling--Qi \cite{hu2013}  defined the determinant of all $m$th-order $n$-dimensional tensors using the resultant of multivariate polynomials. To define the determinant of a tensor, we need the following notation. Let $\mc{A}\in\mb{R}^{[m,n]}$ and $x=(x_1,\ldots,x_n)^T\in\mb{R}^{n}$. Then
\[\mc{A}x^{m-1}
=\mc{A}\times_{2}x^{T}\times_{3}\cdots\times_{m}x^{T}=\left(\sum_{i_{2},\ldots,i_{m}=1}^{n}a_{i_{1}i_{2}\ldots i_{m}}x_{i_{2}}\cdots x_{i_{m}}\right)\in \mb{R}^{n}.\]  Now define the multivariate homogeneous polynomials of degree $m-1$
\[F_{k}(x_{1},x_{2},\ldots,x_{n}):=\sum_{i_{2},\ldots,i_{m}=1}^{n}a_{ki_{2}\ldots i_{m}}x_{i_{2}}\cdots x_{i_{m}} \hbox{ for } 1\leq k\leq n.\]
Equipped with these $n$ polynomials, we are now ready to define the determinant of a tensor.
\begin{definition}\label{defndet}
Let $\mc{A}\in\mb{R}^{[m,n]}$ with $m\geq 2$. Let $F_1,\ldots,F_n\in \mathbb{R}[x_1,\ldots,x_n]$ be homogeneous polynomials of degree $m-1$ as defined above. Then the determinant of $\mc{A}$, denoted by $\det(\mc{A})$, is the resultant of the ordered set of polynomials $F_1,\ldots, F_n$.  
\end{definition}
From the above definition, it is easy to verify that the tensor determinant generalizes the well-known matrix determinant and symmetric hyperdeterminant studied by Qi \cite{qi2005}. 


We now obtain the determinant of the GCD tensor. To state our next main result, we first recall the following basic definition.
\begin{definition}
 A set $S$ of positive integers is said to be {\it factor-closed} (FC), if whenever $d$ divides $s\in S$, then $d\in S.$ 
\end{definition}

Our final main result gives the determinant of the GCD tensor $\mc{T}_{[S]}$ on a factor-closed $S$ in terms of the Euler totient function.

\begin{theorem}\label{detgcd}
Let $S=\{s_{1},s_{2},\ldots, s_{n}\}$ be a factor-closed set of distinct positive integers. Let $\mc{T}_{[S]}$ be the $m$th-order $n$-dimensional GCD tensor on $S$.  Then 
\[\det{(\mc{T}_{[S]})}=\prod_{i=1}^{n} \Phi(s_{i})^{(m-1)^{(n-1)}}.\]
\end{theorem}

We now explain the organization of the paper. In the next section, we present the proofs of Theorems \ref{thm:gcdcpt} and \ref{thrmfractpwr}, and provide an algorithm for computing the strongly CP decomposition of GCD tensors. Section \ref{sec:det} is dedicated to studying the determinant of the GCD tensor. In this section, we establish our final main result, Theorem \ref{detgcd}, by developing a new factorization of the GCD tensor. Furthermore, we discuss the determinants of the GCD tensor on a generalization of the factor-closed set. The paper concludes by extending the concept of the GCD tensor on the meet semi-lattice in Section \ref{sec:poset}.

\section{Strongly completely positivity of GCD tensors}\label{sec:cp}
In this section, we prove two of our main results -- Theorems \ref{thm:gcdcpt} and \ref{thrmfractpwr}, and outline the additional work required to complete their proofs.  We begin by proving Theorem \ref{thm:gcdcpt}. This requires a basic lemma due to Gauss for Euler's totient function.

% The next preliminary result is the well-known result of Gauss for Euler's totient function.
\begin{lemma}\label{gauss}
For any positive integer $k$, $\sum\limits_{d\mid k}\Phi(d)=k$.
\end{lemma} 



%The Lemma \ref{lma:symsum} implies that every supersymmetric tensor is a sum of rank-1 supersymmetric tensors. Since the GCD tensor, $\mc{T}_{[S]},$ on the set $S=\{s_{1},s_{2},\ldots, s_{m}\}$ of distinct positive integers is a supersymmetric tensor, so we have the following result. In the proof, we use Theorem 63 given on page 64 of \cite{hardy1954}, i.e., for any positive integer $n$, $\sum_{d\mid n}\Phi(d)=n$, where $\Phi(\cdot)$ is the Euler's totient function. Recall that, a set $S$ of positive integers is said to be {\it factor-closed} (FC) \cite{beslin1989}, whenever $d$ divides $s\in S$, then $d\in S.$
\begin{proof}[Proof of Theorem \ref{thm:gcdcpt}]
We begin by showing that $\mc{T}_{[S]}$ is completely positive. Let $F=\{f_{1},f_{2},\ldots,f_{l}\}$ be a factor-closed set containing $S.$ Define the matrix $E:=(e_{ij})\in\mb{R}^{n\times l}$ such that
\begin{equation}\label{matrixE}
	e_{ij}:=\begin{cases}
		1,&\mathrm{if }~f_{j}|s_{i},\\
		0,&\mathrm{otherwise.}
	\end{cases}
\end{equation}
We claim that the $m$th-order $n$-dimensional GCD tensor $\mc{T}_{[S]}$ can be decomposed as
\begin{equation}\label{eqn:mre}
	\mc{T}_{[S]}=\sum_{k=1}^{l}\Phi(f_{k})(E_{k})^{\otimes m},
\end{equation}
where $E_{k}$ denotes the $k$th column of $E$. Fix $1\leq i_1,\ldots,i_m\leq n$.  To prove the equality \eqref{eqn:mre} it suffices to show that the $(i_{1},i_{2},\ldots,i_{m})$th element of the summation  $\sum\limits_{k=1}^{l}\Phi(f_{k})(E_{k})^{\otimes m}$ agrees with the $(i_{1},i_{2},\ldots,i_{m})$th element of  $\mc{T}_{[S]}$.  But notice that for $1\leq k\leq l$, the $(i_{1},i_{2},\ldots,i_{m})$th element of $(E_{k})^{\otimes m}$ is $e_{i_{1}k} e_{i_{2}k}\cdots e_{i_{m}k}$ which is equal to $1$ if $f_{k}|s_{i_{1}}, f_{k}|s_{i_{2}}, \ldots ,f_{k}|s_{i_{m}}$, otherwise $0$. Thus,
\begin{eqnarray*}
	\left(\sum_{k=1}^{l}\Phi(f_{k})(E_{k})^{\otimes m}\right)_{i_{1}\ldots i_{m}}&=&\sum_{f_{k}\mid s_{i_{1}},f_{k}\mid s_{i_{2}},\ldots,f_{k}\mid s_{i_{m}}}\Phi(f_{k})\\
	&=&\sum_{f_{k}\mid \GCD(s_{i_{1}},s_{i_{2}},\ldots,s_{i_{m}})}\Phi(f_{k})\\	
	&=&\GCD(s_{i_{1}},s_{i_{2}},\ldots,s_{i_{m}}).
\end{eqnarray*}
The last equality follows from Lemma \ref{gauss}. Thus $\mc{T}_{[S]}$ is completely positive, since $\Phi(f_{k})>0$ for all $1\leq k \leq n$. 

We next show that ${\rm span} \{E_1,\ldots,E_l\}=\mathbb{R}^n$. Let $S'=\{s_{r_1},\ldots, s_{r_n}\}$ be the rearrangement of the elements of $S$ such that $s_{r_1}<s_{r_2}<\cdots< s_{r_n}$ and let $F'=\{f_{r_1},f_{r_2},\ldots,f_{r_l}\}$ be obtained by rearranging the elements of  $F$ such that $f_{r_1}=s_{r_1}, f_{r_2}=s_{r_2},\ldots, f_{r_n}=s_{r_n}$. Define the matrix $E':=(e'_{ij})\in\mb{R}^{n\times l}$ elementwise as follows:
\begin{equation}
	e'_{ij}:=\begin{cases}
		1,&\text{if } f_{r_j} \text{ divides }s_{r_i},\\
		0,&\text{otherwise.}
	\end{cases}
\end{equation}
Then there exist permutation matrices $P\in \mathbb{R}^{n \times n}$ and $Q\in \mathbb{R}^{l \times l}$ such that $E'=PEQ$. Thus ${\rm rank}(E')={\rm rank}(E).$ To show that the columns of $E$ span $\mb{R}^{n}$, it is sufficient to show that $E'$ has rank $n$. Now, on writing the first $n (\leq p)$ columns of the matrix $E'$ explicitly we have
\begin{equation*}
	E'=\begin{pmatrix}
		1&0&0&\cdots&0&0&*&\cdots&*\\
		*&1&0&\cdots&0&0&*&\cdots&*\\
		*&*&1&\cdots&0&0&*&\cdots&*\\
		\vdots&\vdots&\vdots&\ddots&\vdots&\vdots&*&\cdots&*\\
		*&*&*&\cdots&1&0&*&\cdots&*\\
		*&*&*&\cdots&*&1&*&\cdots&*
	\end{pmatrix}_{n\times p}.
\end{equation*}
Thus the first $n$ columns of the matrix $E'\in\mb{R}^{n\times p}$ are linearly independent. Since $n\leq p$,  ${\rm rank}(E')=n$.  Hence $\mc{T}_{[S]}$ is strongly completely positive. 
\end{proof}
In the above proof, we provided a strongly CP decomposition \eqref{eqn:mre} of GCD tensors. We now provide an algorithm to derive such a decomposition.
% $\spadesuit$ Algorithm 1
\begin{algorithm}[H]
\scriptsize
\caption{Strongly CP decomposition of a GCD tensor}
\begin{algorithmic}[1]
\State Enter a set of $n$ distinct positive integers $S=\{s_{1},\ldots,s_{n}\}$.
\State Construct a factor-closed set $F=\{f_{1},\ldots,f_{l}\}$ containing $S.$
% \State Construct an $m$th order $n$-dimension tensor $\mc{T}_{[S]}$
\State Construct an $n\times l$ zero matrix $E=(e_{ij})$.
\For {$i=1:n$}
\For {$j=1:l$}
\If{$f_{j}|s_{i}$}
\State  $e_{ij}=1$;
\Else
\State $e_{ij}=0$;
\EndIf
\EndFor
\EndFor
\State $E_{k}:=$ $k$th column of the matrix $E;$
\State \Return $\mc{T}_{[S]}=\sum_{k=1}^{l}\Phi(f_{k})(E_k)^{\otimes m}.$
\end{algorithmic}
\end{algorithm}
