\chapter*{Part I}

\begin{center}
\huge{General solutions, skew braces and Rota--Baxter groups} 
\end{center}



\chapter{Set-theoretic solutions to the Yang--Baxter equation}\label{chapter solution of YBE}

\begin{quote} 
In this chapter, we develop a comprehensive theory of set-theoretic solutions to the Yang--Baxter equation, building upon foundational contributions in the field. Our study includes numerous examples of such solutions and a thorough examination of the structure group associated with a solution, highlighting its key properties. Additionally, we explore braiding operators on groups and their significant implications. The chapter further presents results on indecomposable solutions, and investigates both linear and affine solutions within the framework of abelian groups.
\end{quote}
\bigskip

\section{Yang--Baxter equation and its solutions}

The theoretical physics and statistical mechanics witnessed the initial emergence of the quantum Yang--Baxter equation through the influential works of Yang \cite{MR0261870} and Baxter \cite{MR0290733, MR0690578}. Since then, this equation has sparked numerous intriguing applications in quantum groups, Hopf algebras, knot theory, tensor categories, and integrable systems, to name a few. 
\para 

A \index{monoidal category}{monoidal category} is a category $\mathcal{M}$ equipped with a functor $\otimes: \mathcal{M} \times \mathcal{M} \to \mathcal{M}$, called the {\it tensor product}, from the product category $\mathcal{M} \times \mathcal{M}$ to $\mathcal{M}$, such that $\mathcal{M}$ admits a unit object and the tensor product is associative. Given a monoidal category $\mathcal{M}$ and an object $V \in \mathcal{M}$, a quantum Yang--Baxter operator is a morphism $R: V \otimes V \to V \otimes V$ which satisfies the following \index{quantum Yang--Baxter equation}{\it quantum Yang--Baxter equation}
\begin{equation} \label{YBE}
R_{12} \,R_{13} \,R_{23} = R_{23} \,R_{13} \,R_{12}
\end{equation}
in $\End(V \otimes V \otimes V)$. Here, $R_{ij}$ denotes the morphism $V\otimes V \otimes V \to V\otimes V \otimes V$ that acts as $R$ on the $(i,j)$-th tensor factors and as the identity on the remaining third factor. The morphism $R$ is referred to as a solution to the quantum Yang--Baxter equation. When $\mathcal{M}$ is the category of vector spaces, then a solution to the quantum Yang--Baxter equation is also referred to as an \index{$R$-matrix} {\it $R$-matrix}.
\para 

Let $V$ be a vector space over a field. The linear map $\mathtt{t}: V \otimes V  \to V \otimes V$ given by $\mathtt{t}(v \otimes w)= w \otimes v$ is clearly a solution to the quantum Yang--Baxter equation. A direct check shows that a linear map $R: V \otimes V  \to V \otimes V$ is a solution to the quantum Yang--Baxter equation if and only if the linear map $S = \mathtt{t}~ R$ satisfies the following equation
\begin{equation} \label{BE}
S_{12} \,S_{23} \,S_{12} = S_{23} \,S_{12} \,S_{23}.
\end{equation}
In the literature, equation \eqref{BE} is commonly referred to as the \index{Yang--Baxter equation}{\it Yang--Baxter equation} or the \index{braid equation}{\it braid equation}. Further, $S$ is said to be a solution to the Yang--Baxter equation or the braid equation.  In this monograph, we will adopt the term ``Yang--Baxter equation'' for this  equation and focus on exploring set-theoretic solutions to it. Let $X$ be a basis of the vector space $V$. Then a map $r : X \times X \to X \times X$ satisfying the equation
\begin{equation}\label{set-theoretic solution of quantum YBE}
r_{12} \,r_{23}  \,r_{12} = r_{23}  \,r_{12} \, r_{23},
\end{equation}
where $r_{ij}: X \times X \times X \to X \times X \times X$ acts as $r$ on the $(i,j)$-th factors and as the identity on the remaining third factor, induces a solution to the Yang--Baxter equation on the vector space $V$. The pair $(X,r)$ is called a \index{set-theoretic solution}{\it set-theoretic solution} to the Yang--Baxter equation. Interest in the study of set-theoretic solutions to the quantum Yang--Baxter equation was intrigued by the paper \cite{MR1183474}  of Drinfel'd, published in 1992. Note that this is equivalent to studying set-theoretic solutions to the Yang--Baxter equation. However, such solutions had already appeared before Drinfel'd formulated his question. Notably, the work of Joyce \cite{MR2628474, MR0638121} and Matveev~\cite{MR0672410} introduced quandles as invariants of knots and links, which provide non-degenerate, bijective, set-theoretic solutions to the Yang--Baxter equation.
\para

In the interest of brevity, if $(X,r)$ is a set-theoretic solution to the Yang--Baxter equation, we commonly refer to it simply as a {\it solution to the Yang--Baxter equation} or a \index{braided pair}{\it braided pair}. Furthermore, the map $r$ is sometimes referred to as a \index{braiding }{\it braiding}.
\para

As the most elementary solution, if $X$ is any set, then the flip map $\mathtt{t}: X \times X \to X \times X$ given by $$\mathtt{t}(x, y)=(y, x)$$ is 
a solution to the Yang--Baxter equation, referred to as the \index{trivial solution}{\it trivial solution}. Now, let us explore some more intriguing examples.


\begin{example}\label{group commuting element example}
{\rm Let $G$ be a group and $a, b \in G$ two commuting elements. Then the map $r: G\times G \to G \times G$ given by
$$
r(x, y) = (ya, xb^{-1})
$$
is a solution to the Yang--Baxter equation.}
\end{example}

\begin{example}\label{self-dist example}
{\rm 
Let $X$ be a set with a binary operation $*$ such that $(x*y)*z=(x*z)*(y*z)$ holds for all $x, y, z \in X$. Then the map $r: X\times X \to X \times X$ given by
$$
r(x, y) = (y, x*y)
$$
is a solution to the Yang--Baxter equation.}
\end{example}

\begin{example} \label{YBEexamples} 
{\rm 
Let $\mathbb{k}$ be a commutative ring with unity $1$. Let $a,b \in \mathbb{k}$ be units  such that $(1-a)(1-b)=0$. 
Then a straightforward computation shows that if $r= \left[ \begin{array}{cc} 1-a & a \\ b & 1-b \end{array} \right]$, that is,
$$ r\big( (x, y) \big) = \big((1-a)x + ay, ~bx + (1-b)y \big)$$
for $x, y \in \mathbb{k},$ then $(\mathbb{k}, r)$ is a solution to the Yang--Baxter equation. 
\para
We now generalise the preceding example to matrices.  Let $r: \mathbb{k}^n \times \mathbb{k}^n \rightarrow  \mathbb{k}^n \times \mathbb{k}^n$ be defined by a matrix $\displaystyle r= \left[ \begin{array}{cc}I - Y & Y \\ Z & I-Z \end{array} \right]$, where $I$ is the identity matrix and $Y, Z$ are invertible  $n \times n$ matrices over $\mathbb{k}$ such that $YZ=ZY$ and $(I-Y)(I-Z)=0$. Then $(\mathbb{k}^n, r)$ is a solution to the Yang--Baxter equation. See \cite{MR2402508, MR2128040} for further matrix solutions to the Yang--Baxter equation.
} 
\end{example}
\para 

Let $X$ be a set and $r: X \times X \to X \times X$ a map. Then we can write $r$ in the form
$$
r(x, y) = \big(\sigma_x(y), \,\tau_y(x)\big),
$$
where $\sigma_x, \tau_y : X \to X$ are maps given by
$$
y \mapsto \sigma_x (y) \quad \textrm{and} \quad x \mapsto \tau_y(x)
$$
for $x, y \in X$.


\begin{proposition} \label{component conditions for a solution}
Let $X$ be a non-empty set and $r : X \times X \to X \times X$ a map given by
$$
r(x, y) = \big(\sigma_x(y), \,\tau_y(x)\big).
$$
Then $(X, r)$ is a solution to the Yang--Baxter equation if and only if the conditions
\begin{eqnarray}
\label{condition for solution 1} \sigma_{\sigma_x(y)} \big(\sigma_{\tau_y(x)} (z) \big) &=& \sigma_x \big( \sigma_y(z) \big),\\
\label{condition for solution 2} \tau_{\sigma_{\tau_y(x)}(z)}  \big( \sigma_x(y) \big) &=&\sigma_{\tau_{\sigma_y(z)}(x)}  \big( \tau_z(y) \big),\\
\label{condition for solution 3} \tau_{\tau_z(y)} \big(\tau_{\sigma_y(z)} (x) \big) &=& \tau_z \big( \tau_y(x) \big),
\end{eqnarray}
 hold for all $x, y, z \in X$.
\end{proposition}

\begin{proof}
Computing $r_{12}r_{23} r_{12}$, we obtain
\begin{eqnarray*}
r_{12}r_{23} r_{12}(x, y, z) &=& r_{12}r_{23} \big(\sigma_x(y), ~\tau_y(x),~ z \big)\\
&=& r_{12} \big(\sigma_x(y), ~\sigma_{\tau_y(x)}(z),~ \tau_z(\tau_y(x)) \big)\\
&=& \big(\sigma_{\sigma_x(y)}(\sigma_{\tau_y(x)}(z)), ~\tau_{\sigma_{\tau_y(x)}(z)}(\sigma_x(y)),~ \tau_z(\tau_y(x)) \big).
\end{eqnarray*}
Similarly, computing $r_{23} r_{12} r_{23}$ gives
\begin{eqnarray*}
r_{23} r_{12} r_{23}(x, y, z) &=& r_{23} r_{12} \big(x,~ \sigma_y(z),~ \tau_z(y) \big)\\
&=& r_{23} \big(\sigma_x(\sigma_y(z)), ~\tau_{\sigma_y(z)}(x), ~\tau_z(y)\big)\\
&=& \big(\sigma_x(\sigma_y(z)), ~\sigma_{\tau_{\sigma_y(z)}(x)}(\tau_z(y)), ~\tau_{\tau_z(y)}(\tau_{\sigma_y(z)}(x)) \big),
\end{eqnarray*}
which proves the assertion. $\blacksquare$
\end{proof}
\para

\begin{corollary}
Let $X$ be a non-empty set and $r : X \times X \to X \times X$ given by $r(x, y) = \big(\sigma_x(y), ~\tau_y(x) \big)$. Then the following  assertions hold:
\begin{enumerate}
\item If $\sigma_x = \id_X$ for all $x \in X$, then the pair $(X, r)$ is a solution to the Yang--Baxter equation if and only if 
$$
\tau_{\tau_z(y)} \big(\tau_{z} (x) \big) = \tau_z \big( \tau_y(x) \big)
$$
for all $x, y, z \in X$.
\item If $\tau_x = \id_X$ for all $x \in X$, then the pair $(X, r)$ is a solution to the Yang--Baxter equation if and only if
$$
\sigma_{\sigma_x(y)} \big(\sigma_{x} (z) \big) = \sigma_x \big( \sigma_y(z) \big)
$$
for all $x, y, z \in X$.
\end{enumerate}
\end{corollary}
\para

The subsequent classes of solutions hold specific significance within the subject.

\begin{definition}
A solution $(X, r)$ to the Yang--Baxter equation is said to be: 
\begin{enumerate}
\item bijective if $r : X\times X \to X\times X$ is a bijection;
\item \index{left  non-degenerate solution}{left  non-degenerate} if each $\tau_x$ is a bijection;
\item \index{right non-degenerate solution}{right non-degenerate} if each $\sigma_x$ is a bijection; 
\item \index{non-degenerate solution}{non-degenerate} if it is both left and right non-degenerate; 
\item \index{square-free solution}{square-free} if $r(x, x) = (x, x)$ for all $x \in X$; 
\item \index{involutive solution}{involutive}  if $r^2 = \id_{X\times X}$.
\item \index{finite solution}{finite}  if the set $X$ is finite.
\end{enumerate}
\end{definition}

An involutive solution $(X, r)$ to the Yang--Baxter equation is also called a \index{symmetric pair}{\it symmetric pair}.

\begin{example}\label{firs-examples}
{\rm Let us consider some examples:
\begin{enumerate}
\item The solution $(X,r)$, where $r(x, y)=(x, y)$, is bijective but neither left nor right non-degenerate.
\item The solutions in Examples \ref{group commuting element example} and \ref{self-dist example} are bijective as well as non-degenerate.
\item The solution $(X,r)$ with $r(x, y)=\big(y, ~y^{-1}x y\big)$, is bijective, square-free and non-degenerate.
\item The solution $(\mathbb{Z},r)$ with $r(a, b)=\big((-1)^ab, ~(-1)^ba\big)$, is involutive and non-degenerate.
\item Let $G$ be a non-trivial group with identity $1$. Then the solution $(X, r)$, where $r(x, y) = (1, x y)$, is non-bijective,  left  non-degenerate and  right degenerate.
\end{enumerate}
}
\end{example}

It is known that for finite left non-degenerate solutions, bijectivity and non-degeneracy are equivalent \cite[Theorem B]{MR4466104}.

\begin{theorem}
If $(X, r)$ is a finite left non-degenerate solution, then it is bijective if and only if it is right non-degenerate.
\end{theorem}

\begin{proposition}\label{involutive sol condition}
Let $(X, r)$ be a non-degenerate solution to the Yang--Baxter equation. Then $(X, r)$ is involutive if and only if
$$
\sigma_x(y) = \tau^{-1}_{\tau_y(x)}(y) \quad \textrm{and} \quad \tau_y(x) = \sigma^{-1}_{\sigma_x(y)}(x)
$$
for all $x, y \in X$. 
\end{proposition}

\begin{proof}
The proof follows from the identity $r^2 = \id_{X \times X}$ and  the non-degeneracy  of $\sigma_x$ and $\tau_y$.  
$\blacksquare$
\end{proof}

\begin{definition}
A solution $(X, r)$ to the Yang--Baxter equation with $r(x, y) = \big(\sigma_x(y),\, \tau_y(x)\big)$ is said to be an \index{elementary solution of first type}{elementary solution of first type} if $\tau_y = \id_X$ for all $y \in X$; and said to be an \index{elementary solution of second type}{elementary solution of second type} if $\sigma_x = \id_X$ for all $x \in X$.
\end{definition}

For instance, Example \ref{group commuting element example} gives an elementary solution of first type if we take $b=1$. Similarly, Example \ref{group commuting element example} and Example \ref{self-dist example} for $a=1$ give elementary solutions of second type.
\para

We now define a morphism between two solutions to the Yang--Baxter equation. 

\begin{definition}
Let $(X, r)$ and $(X', r')$ be solutions to the Yang--Baxter equation. A map $\varphi : X \to X'$ is called a \index{morphism of solutions}{morphism of solutions} if the following diagram commutes.
$$ \begin{CD}
X \times X @> r>> X \times X \\
@V{\varphi \times \varphi}VV @VV{\varphi \times \varphi}V \\
X' \times X' @> r' >> X' \times X'.
\end{CD}
$$
If $\varphi$ is bijective, then it is called an isomorphism of solutions.
\end{definition}

It is clear that the class of all set-theoretic solutions to the Yang--Baxter equation forms a category with the above definition of a morphism. Note that, if $r(x, y) = \big(\sigma_{x}(y), \,\tau_{y}(x)\big)$ and $r'(u, v) = \big(\sigma'_{u}(v), \,\tau'_{v}(u)\big)$, then 
$\varphi$ is a morphism of solutions if and only if 
$$\varphi \big(\sigma_{x}(y) \big) = \sigma'_{\varphi(x)} \big(\varphi(y) \big)\quad \textrm{and} \quad 
\varphi \big(\tau_{y}(x) \big) = \tau'_{\varphi(y)} \big(\varphi(x) \big)$$ for all $x, y \in X$.

\begin{definition}\label{conjugate sol definition}
Two solutions $(X,r)$ and $(X,r')$ to the Yang--Baxter equation are said to be \index{conjugate solutions}{conjugate} if there exists a bijection 
$T: X \times X \to X \times X$ such that $r' = T r T^{-1}$.
\end{definition}

Let $\mathtt{t}:X \times X \to X \times X$ be the flip map given by $\mathtt{t}(x, y)=(y, x)$. Then $(X, r)$ is an elementary solution of second type if and only if $ \mathtt{t} r \mathtt{t}$ is an elementary  solution of first type. Hence, there exists a one-to-one correspondence between elementary solutions of the first and second types.
\para

A set endowed with a single binary operation is referred to as a \index{groupoid}{\it groupoid}, while one equipped with two binary operations is termed a \index{bi-groupoid}{\it bi-groupoid}. There is an alternate approach to describe solutions to the  Yang--Baxter equation using bi-groupoids. A solution $(X, r)$ to the Yang--Baxter equation  defines a bi-groupoid $(X, \cdot, *)$ with binary operations
$$
y \cdot x =\sigma_x (y) \quad \textrm{and} \quad x * y = \tau_y(x)
$$
for $x, y \in X$. Thus, Proposition \ref{component conditions for a solution} takes the following form.

\begin{proposition} \label{f1}
Let $(X, \cdot, *)$ be a bi-groupoid  and $r : X \times X \to X \times X$ given by
$$
r(x, y) = (y \cdot x, ~x * y)
$$
for $x, y \in X$. Then, $(X, r)$ is a solution to the  Yang--Baxter equation if and only if the conditions
\begin{eqnarray*}
\big(z \cdot (x * y) \big)  \cdot (y \cdot x)&=&(z \cdot y) \cdot x,\\
(y\cdot x) * \big(z \cdot (x*y) \big)&=&(y*z) \cdot \big(x*(z \cdot y) \big),\\
(x*y)*z&= &\big(x*(z \cdot y) \big) *(y*z),
\end{eqnarray*}
hold for all $x, y, z \in X$.
\end{proposition}


In the general case, it is challenging to make definitive statements about bi-groupoids that satisfy these axioms. However, when we focus on elementary solutions, it is sufficient to examine certain groupoids.

\begin{corollary}
Let  $(X, \cdot, *)$ be a bi-groupoid such that $y \cdot x = y$ for all $x, y \in X$. Then the groupoid  $(X, *)$ defines a solution $r(x, y) = (y, x * y)$  if and only if the condition
\begin{equation}\label{right distributive condition}
(x * y) * z = (x*z) * (y * z)
\end{equation}
hold for all $x, y, z \in X$.
\end{corollary}

\begin{remark}
{\rm 
A groupoid satisfying condition \eqref{right distributive condition} is called a \index{distributive groupoid}{\it (right)~distributive groupoid} or a \index{shelf}{\it shelf}. A distributive groupoid $(X, *)$ in which the map $x \mapsto x*y$ is a bijection for each $y \in X$ is called a \index{rack}{\it rack}. If, in addition, $x*x=x$ for all $x \in X$, then $(X, *)$ is called a \index{quandle}{\it quandle}. In Part-II of the monograph, we will delve deeper into the intricate details of racks and quandles.}
\end{remark}


A non-degenerate elementary solution $(X,r)$ of the second type  with $r(x,y)=\big(y,\tau_y(x) \big)$ is said to be of \index{rack type solution}{\it rack type} if the groupoid $(X, *)$ with $x*y = \tau_y(x)$ is a rack. If $(X,*)$ is a quandle, then we say that the solution is of \index{quandle type solution}{\it quandle type}. The following result is immediate from the definitions.


\begin{proposition}
Let $X$ be a set and $r: X\times X\to X\times X$ a map given by $r(x,y) = \big(y, \tau_y(x)\big)$. Then the following  assertions hold:
\begin{enumerate}
\item $(X, r)$ is a~non-degenerate solution to the Yang--Baxter equation if and only if $(X,*)$ with $x*y = \tau_y(x)$ is a rack.
\item $(X, r)$ is a~non-degenerate square-free solution to the Yang--Baxter equation if and only if $(X,*)$ with $x*y = \tau_y(x)$ is a  quandle.
\end{enumerate}
\end{proposition}


In \cite[Theorem 2.3(iv)]{MR1809284}, Soloviev proved that every non-degenerate solution is conjugate to an elementary solution. This implies that instead of studying bi-groupoids corresponding to solutions, one can focus on studying groupoids.


\begin{proposition}\label{SolTh}
Let $(X, r)$ with $r(x,y) = \big(\sigma_x(y), \tau_y(x)\big)$ be a right non-degenerate solution to the Yang--Baxter equation. Then it is conjugate to the solution $(X, r^\star)$ with
$$
r^\star(x,y) = \left(y,~ \sigma_y(\tau_{\sigma^{-1}_x(y)}(x))\right).
$$
Further, the solution $(X,r^\star)$ is non-degenerate if and only if, for all $a, b \in X$, there exists a unique $x \in X$ such that
\begin{equation}\label{cond}
\sigma_a \big(\tau_{\sigma^{-1}_x(a)}(x) \big) = b.
\end{equation}
\end{proposition}

\begin{proof}
Since $(X, r)$ is right non-degenerate, $\sigma_x$ is bijective for each $x \in X$. Let $T_2: X \times X \to X \times X$ be the map defined by  $T_2(x, y) = \big(x, ~\sigma_x(y)\big)$ for $x, y \in X$. Then $T_2$ is invertible with $T_2^{-1}(x, ~y) = \big(x, ~\sigma^{-1}_x(y)\big)$ and 
$$
T_2  \,r  \,T_2^{-1}(x,~ y)
 = T_2 \,r \big(x, ~\sigma^{-1}_x(y) \big)
 = T_2 \big( \sigma_x(\sigma^{-1}_x(y)),~\tau_{\sigma^{-1}_x(y)}(x)\big)
 = \big(y, ~\sigma_y(\tau_{\sigma^{-1}_x(y)}(x)) \big)
 = r^\star(x,~y).
$$
Let us check  that $(X,r^\star)$ is a solution, that is,
$$
r_{12}^\star  \,r_{23}^\star  \,r_{12}^\star = r_{23}^\star  \,r_{12}^\star  \,r_{23}^\star
$$
where
$$
r_{12}^\star(x, y, z) = \left(y, ~\sigma_y(\tau_{\sigma^{-1}_x(y)}(x)), z\right) \quad \textrm{and}\quad r_{23}^\star(x, y, z) = \left(x,~z, ~\sigma_z(\tau_{\sigma^{-1}_y(z)}(y)) \right).
$$
Let $T_3 : X^3 \to X^3$ be given by 
$$T_3(x, y, z) = \big(x, ~\sigma_x(y),~ \sigma_x(\sigma_y(z)\big)$$
for $x, y, z \in X$. Then, its inverse is given by
$$
T_3^{-1} (x, y, z) = \left(x, ~\sigma^{-1}_x(y), ~\sigma^{-1}_{\sigma^{-1}_x(y)} (\sigma^{-1}_x(z)) \right).
$$
We claim that
$$
T_3  \,r_{12} \, T_3^{-1} = r_{12}^\star \quad \textrm{and}\quad T_3 \, r_{23}  \,T_3^{-1} = r_{23}^\star. 
$$
Since $(X, r)$ is a solution, this implies that $(X, r^\star)$ is also a solution.  We have 
$$
T_3  \,r_{12} (x, y, z) = T_3 \big(\sigma_x(y), \tau_y(x), z \big) =  \big(\sigma_x(y), ~ \sigma_{\sigma_x(y)}(\tau_y(x)), ~ \sigma_{\sigma_x(y)}(\sigma_{\tau_y(x)}(z)) \big)
$$
and
$$
 r_{12}^\star   \,T_3 (x, y, z) =  r_{12}^\star \big(x, \sigma_x(y), \sigma_x(\sigma_y(z))\big) =  \big(\sigma_x(y), ~ \sigma_{\sigma_x(y)}(\tau_y(x)), ~ \sigma_x (\sigma_y(z)) \big).
$$
By \eqref{condition for solution 1}, we have
$$ 
\sigma_{\sigma_x(y)} \big(\sigma_{\tau_y(x)} (z) \big) =  \sigma_x \big( \sigma_y(z) \big)
$$
for all $x, y, z \in X$, and hence the equality $T_3 r_{12} T_3^{-1} = r_{12}^\star$ holds. The proof of the equality $T_3 r_{23} T_3^{-1} = r_{23}^\star$ is similar, which establishes our claim. Further, the solution $(X, r^\star)$ is non-degenerate   if and only if, for every $a, b \in X$, there exists a~unique $x \in X$ such that
$\sigma_a \big(\tau_{\sigma^{-1}_x(a)}(x)\big) = b$. This completes the proof of the proposition. $\blacksquare$
\end{proof}


Next, we consider some more examples of solutions. 

\begin{example}\cite[Section 9]{MR1183474} 
{\rm   Let $X$ be a non-empty set and $r: X \times X \to X \times X$ given by $r(x, y) = \big(f(y), ~g(x)\big)$ for some maps $f, g : X \to X.$ 
Then the following  assertions hold:
\begin{enumerate}
\item $(X, r)$  is a solution to the Yang--Baxter equation if and only if $fg = gf$.
\item $(X, r)$ is non-degenerate if and only if  $f, g$ are bijective.
\item $(X, r)$ is involutive if and only if $g = f^{-1}$.
\end{enumerate}
\par

A solution of the preceding type is called a \index{permutation solution}{\it permutation solution}. If $f, g$ are cyclic permutations, then we  say that $(X, r)$ is a \index{cyclic permutation solution}{\it cyclic  permutation solution}. It is clear that two permutation solutions are isomorphic as solutions if and only if the corresponding permutations are conjugate.}
\end{example}

\begin{example}   \label{DirProd}
{\rm
If $(X, r)$ and $(Y, s)$ are two solutions, then  $(X \times Y, r  \times s)$  is a solution, called the \index{product solution}{\it product solution}.}
\end{example}



\begin{example} \label{OnGr}{\rm 
If  $G$ is a group, then we can define some elementary solutions on $G$ as follows:
\begin{enumerate}
\item $(x, y) \mapsto \big(y,~ y^{-k} x y^k \big)$ for $x, y \in G$ and fixed integer $k$.
\item $(x, y) \mapsto \big(y, ~y x^{-1} y \big)$ for $x, y \in G$.
\item $(x, y) \mapsto \big(y, ~\varphi(x y^{-1}) y \big)$ for $x, y \in G$ and fixed automorphism $\varphi \in \Aut(G)$.
\end{enumerate}
\para
One can check that all the preceding solutions are non-degenerate, elementary and square-free. In fact, all these solutions are of quandle type.}
\end{example}

The next example gives a family of non-elementary and non-square-free solutions.

\begin{example} \label{NonEl}
{\rm 
Let $G$ be a group and $\varphi:G \to G$ a homomorphism. Then $(G, r)$ with
$$
r(x, y) = \big(x y \varphi(x)^{-1}, ~\varphi(x)\big)
$$
is a solution to the Yang--Baxter equation. Further, $(G, r)$ is non-degenerate if and only if $\varphi \in \Aut(G)$.}
\end{example}

The next example is analogous to the preceding example. 

\begin{example} \label{NonEl2}
{\rm 
Let $G$ be a group and $\varphi:G \to G$ a homomorphism. Then $(G, r)$ with
$$
r(x, y) = \big(\varphi(y),~\varphi(y)^{-1} \, x y \big)
$$
is a solution to the Yang--Baxter equation. If $\varphi$ is the identity automorphism, then $r(x, y) = (y,~ y^{-1} x y)$ (see Example \ref{firs-examples}(3)). If $\varphi$ is the trivial homomorphism, then $r(x, y) = (1,~ x y)$ (see Example \ref{firs-examples}(5)). }
\end{example}



\begin{example}\cite[Example 3, p. 203]{MR1722951}
{\rm 
 Let $A$ be a ring with unity $1$ (not necessarily commutative) and $c\in A$ such that $1 + cx$ is invertible for any $x \in  A$. Define a new binary operation on $A$ by 
$$
x \circ y = x+y+xcy. 
$$
It is easy to check that the operation is associative and the zero element 0 of the ring $A$ acts as the identity element with respect to $\circ$. In fact, $(A, \circ)$ is a group, since for any $x \in A$, there exists
$$
x^{-1} = -x(1 + cx)^{-1}
$$
such that
$x\circ x^{-1} = x^{-1} \circ x = 0$.  Taking
$$
r(x, y) = \big(y(1 + cx + cxcy)^{-1}, ~x(1 + cy) \big),
$$
we see that $(A, r)$ is  a non-degenerate involutive solution to the Yang--Baxter equation. Further, $r$ defines a non-degenerate involutive solution on any right ideal of $A$.}
\end{example}


As we bring this section to a close, we examine how a solution to the Yang--Baxter equation  gives rise to  representations of braid groups. 

\begin{definition}
 The \index{braid group}{\it braid group} $\B_n$ on $n \ge 2$ strands is defined as the group generated by $n-1$ elements $\sigma_1,\ldots,\sigma_{n-1}$ with defining relations
\begin{align}
 \label{eq1}\sigma_i\sigma_{i+1}\sigma_i& = \sigma_{i+1}\sigma_i\sigma_{i+1} \quad \textrm{for}\quad 1 \le i \le n-2,\\
\label{eq2}\sigma_i\sigma_j &= \sigma_j\sigma_i \quad \textrm{for}\quad |i-j|\geq 2. 
\end{align}
\end{definition}
One can see that the braid equation \eqref{BE} resembles relations in the braid group $\B_n$.  Let $(X, r)$ be a bijective solution to the Yang--Baxter equation. Then, for each $1 \le i \le n-1$, we can define permutations $r_i : X^n \to X^n$ by setting
$$
r_i = \id_{X^{i-1}} \times r \times \id_{X^{n-i-1}}.
$$

The proof of the following proposition is immediate. 

\begin{proposition}\label{action of bn and sn via solution}
Let $X$ be a non-empty set and $r: X \times X \to X \times X$ a bijection. Then the following assertions  hold:
\begin{enumerate}
\item The assignment $\sigma_i \mapsto r_i$, for $1 \le i \le n-1$, extends to a representation $\B_n \to \Sigma_{X^n}$ if and only if $(X, r)$ is a solution to the Yang--Baxter equation.
\item The assignment $\sigma_i \mapsto r_i$, for $1 \le i \le n-1$, extends to a representation $\Sigma_n \to \Sigma_{X^n}$ if and only if $(X, r)$ is an involutive solution to the Yang--Baxter equation.
\end{enumerate}
\end{proposition}


\begin{exercise}{\rm 
Determine the representation of $\B_n$ corresponding to the solution $(\mathbb{Z}, r)$ with $r(a, b) = (b+1, a-1)$.}
\end{exercise}
\para

If $(X, r)$ is a solution to the Yang--Baxter equation such that $r(x,y) = \big(\sigma_x(y), \tau_y(x) \big)$ is bijective,  then we have a representation $\B_n \to \Sigma_{X^n}$  given by $\sigma_i \mapsto r_i$. It follows from Proposition \ref {SolTh} that $(X, r^\star)$, where  $$r^\star(x,y) = \left(y,~ \sigma_y(\tau_{\sigma^{-1}_x(y)}(x))\right),$$ is also a solution to the Yang--Baxter equation. Thus, we have another representation  $\B_n \to  \Sigma_{X^n}$ given by $\sigma_i \mapsto r_i^\star$, where
$$
r_i^\star = \id_{X^{i-i}} \times r^\star \times \id_{X^{n-i-i}}
$$
for each $1 \le i \le n-1$. Using the idea as in the proof of Proposition \ref {SolTh}, we can prove that these two representations of the braid group are conjugate  \cite[Theorem 2.3(iv)]{MR1809284}.

\begin{proposition} \label{SolRack} 
For each integer $n \geq 2$, there exists a bijection $T_n \colon X^n \to X^n$ such that
$$
T_n  \,r_i  \,T_n^{-1} = r_i^\star
$$
for all $1 \le i \le n-1$.
\end{proposition}
\para

Next, we consider an example from \cite{MR1918864} (see also \cite[Chapter 8]{MR1988550}), for which the induced action of the braid group has a nice geometrical meaning.

\begin{example}{\rm  
Consider the non-degenerate solution $(\mathbb{R}_+^{2}, r)$ to the Yang--Baxter equation, where $r$ is given by
$$
r(a, b, c, d) = \left( a+ ab + bc,~ \frac{bcd}{bc+a(1+b)(1+d)}, ~\frac{acd}{a+c+ad}, ~\frac{bc+a(1+b)(1+d)}{c} \right).
$$
To be precise, we have
$$
\sigma_{(a, b)}(c, d) = \left( a+ ab + bc,~ \frac{bcd}{bc+a(1+b)(1+d)} \right) \quad \textrm{and}\quad 
\tau_{(c, d)}(a, b) = \left(  \frac{acd}{a+c+ad}, ~\frac{bc+a(1+b)(1+d)}{c} \right).
$$

Replacing the triplet of operations $(\cdot, /, +)$ by $(+, -, \max)$, we obtain the non-degenerate solution $(\mathbb{R}^{2}, s)$ to the Yang--Baxter equation, where $s$ is given by
\begin{eqnarray*}
s(a, b, c, d) &=& \Big( \max\{a, a + b, b + c \}, ~d - \max \big\{0, a - b - c + \max\{0, b\} + \max\{0, d\} \big\},\\ 
&&  a + c + d - \max\{a, c, a + d\},~ \max \big\{b, a - c + \max\{0, b\} + \max\{0, d\} \big\}\Big).
\end{eqnarray*}
The two solutions give actions $\rho^r$ and $\rho^s$ of the braid group $\B_n$ on $\mathbb{R}_+^{2n}$ and $\mathbb{R}^{2n}$, respectively. It turns out that these actions have nice geometric meanings. To understand that, we restrict the action $\rho^s$ of $\B_n$ on the integer lattice $\mathbb Z^{2n}$ in $\mathbb R^{2n}$.  For each $x \in \mathbb Z$, let $x^+ = \max \{ 0, x \}$ and $x^- = \min \{ x, 0 \} $. We define right-actions
$$
\sigma, \, \sigma^{-1} : \mathbb Z^4 \to \mathbb Z^4
$$
on $(a,b,c,d) \in \mathbb Z^{4}$ as follows:
\begin{equation}
(a, b, c, d) \cdot  \sigma  = \big(a + b^+ + (d^+ - e)^+,  \, d - e^+,  \, c + d^- + (b^- + e)^-,  \, b + e^+ \big) \label{action-by-sigma}
\end{equation}
and
\begin{equation}
(a,b,c,d) \cdot  \sigma^{-1} = \big(a - b^+ - (d^+ + f)^+,  \, d + f^-,  \, c - d^-  - (b^- - f)^-,  \, b - f^- \big),  \label{action-by-sigma-inverse}
\end{equation}
where
\begin{equation}
e = a - b^- - c + d^+ \quad \textrm{and} \quad  f = a + b^- - c - d^+ . \label{definition-e-f}
\end{equation}
Let $(a_1, b_1, \ldots, a_n, b_n) \in \mathbb Z^{2n}$ and $\sigma_i^{\varepsilon} \in \B_{n}$, where $1 \le i \le n-1$ and $\varepsilon \in \{1, -1 \}$. We define the right-action of $\sigma_i^{\varepsilon} \in \B_{n}$ by
\begin{equation}
(a_1, b_1, \ldots, a_n, b_n) \cdot \sigma_i^{\varepsilon} = (a_1', b_1', \ldots, a_n', b_n'),  \label{action-by-generator-sigma-1}
\end{equation}
where $a_k' = a_k$ and $b_k' = b_k$ for $k \neq i, i+1$, and
\begin{equation}
(a_i', b_i', a_{i+1}', b_{i+1}') = \begin{cases}
\begin{array}{ll}
(a_i, b_i, a_{i+1}, b_{i+1}) \cdot \sigma & \mbox{if } \, \varepsilon = 1, \cr
(a_i, b_i, a_{i+1}, b_{i+1}) \cdot \sigma^{-1} & \mbox{if } \, \varepsilon = -1. \cr
\end{array}
\end{cases} \label{action-by-generator-sigma-2}
\end{equation}
For a word $w \in \B_n$ in the alphabet $\{ \sigma_1^{\pm 1}, \ldots, \sigma_{n-1}^{\pm 1}  \}$, we define the action of $w$ by
\begin{equation}
(a_1, b_1, \ldots,  a_n, b_n) \cdot w = \begin{cases}
\begin{array}{ll}
(a_1, b_1, \ldots, a_n, b_n) & \mbox{if } \, w= 1, \cr
((a_1, b_1, \ldots,  a_n, b_n)  \cdot \sigma_i^{\varepsilon}) \cdot w' & \mbox{if } \, w = \sigma_i^{\varepsilon} w'. \cr
\end{array}
\end{cases}
\end{equation}
It can be checked that the above action by $\B_n$ on $\mathbb Z^{2n}$ is well-defined. By  the \index{Dynnikov coordinates}{Dynnikov coordinates} of a braid $w \in \B_n$, we mean the vector $(0,1, \ldots, 0, 1) \cdot w$. The utilization of Dynnikov coordinates comes into  play when discerning the \index{positive braid}{positivity} or \index{negative braid}{negativity} of a braid \cite[Proposition 2]{MR1918864}, which is intimately related to ordering of braids \cite{MR1214782}.}
\end{example}
