\section{Structure group of solutions}
Following \cite{MR1722951}, we now associate a group to a solution to the Yang--Baxter equation. The investigation of solutions will heavily rely on this group's pivotal role.

\begin{definition}
Let $(X,r)$ be a solution to the Yang--Baxter equation with $r(x, y)=\big(\sigma_x(y), \tau_y(x)\big)$. The \index{structure group}{\it  structure group} $G(X, r)$ of the solution $(X, r)$ is the group with the following presentation
$$
G(X, r)= \big\langle X  \, \mid \,  xy= \sigma_x(y) \tau_y(x)~\textrm{for all}~x, y \in X \big\rangle.
$$
\end{definition}
\para

\begin{example}{\rm 
Let $(X,r)$ be a solution to the Yang--Baxter equation.
\begin{enumerate}
\item If $r(x, y) = (x, y)$ is the identity map, then $G(X, r) \cong F(X)$, the free group with basis $X$.
\item If $r(x, y) = \mathtt{t}(x, y)=(y, x)$, then $G(X, r) \cong \mathbb{Z}^{X}$, the free abelian group of rank $|X|$.
\item If $X$ is a monoid with the identity element $e$, then $r(x, y) = (e, x y)$ is a solution and  $G(X, r) \cong F(X)$, the free group with basis $X$.
\end{enumerate}}
\end{example}


The following result gives a characterisation of a solution in terms of two compatible actions of the structure group on the underlying set of the solution \cite[Proposition 2.1]{MR1722951}.

\begin{proposition} \label{p122}
Let $X$ be a non-empty set and $r: X \times X \to X \times X$ a map given by $r(x, y)=\big(\sigma_x(y), \,\tau_y(x)\big)$ such that $\sigma_z$ and $ \tau_z$ are bijective for all $z\in X$. Then $(X, r)$  is a solution to the Yang--Baxter equation if and only if the following conditions are simultaneously satisfied:
\begin{enumerate}
\item The assignment $x \mapsto \tau_x$ is a right-action of $G(X, r)$ on  $X$.
\item The assignment $x \mapsto \sigma_x$ is a left-action of $G(X, r)$ on  $X$.
\item The linking relation
$$
\tau_{\sigma_{\tau_y(x)}(z)}  \big(\sigma_x(y)\big) = \sigma_{\tau_{\sigma_y(z)}(x)} \big(\tau_z(y)\big)
$$
holds for all $x, y, z \in X$.
\end{enumerate}
\end{proposition}

\begin{proof}
The assignment $x \mapsto \sigma_x$ defines a left-action of the group $G(X, r)$ on  $X$ if and only if 
$$\sigma_{\sigma_x(y)} \left(\sigma_{\tau_y(x)} (z) \right) = \sigma_x \big( \sigma_y(z) \big).$$
Similarly, $x \mapsto \tau_x$ defines a right-action of $G(X, r)$ on  $X$ if and only if
$$\tau_{\tau_z(y)} \big(\tau_{\sigma_y(z)} (x) \big) = \tau_z \big( \tau_y(x) \big).$$
Thus, by Proposition \ref{component conditions for a solution},  $(X, r)$  is a solution to the Yang--Baxter equation if and only if (1)-(3) hold simultaneously. $\blacksquare$
\end{proof}

Next, we have the following result \cite[Proposition 2.2]{MR1722951}. 

\begin{proposition} \label{p123}
The following  assertions hold:
\begin{enumerate}[(a)]
\item Let $X$ be a non-empty set and $r: X \times X \to X \times X$ with $r(x, y)=\big(\sigma_x(y), \,\tau_y(x)\big)$ an involution such that each $\tau_x$ is bijective and satisfy condition (1) in Proposition \ref{p122}. If $T : X \to X$ is the map given by $T(y) = \tau^{-1}_y(y)$, then 
\begin{equation}\label{equality of tau T and T sigma}
\tau_x^{-1}  \,T = T  \,\sigma_x.
\end{equation}
\item[] Suppose that, in addition, each $\sigma_x$ is bijective. Then we have the following:
\item The map $T$ is bijective. Consequently, the left-actions of $G(X, r)$ on $X$ given by $x \mapsto \tau^{-1}_x$ and $x \mapsto \sigma_x$  are isomorphic to each other.
\item  Condition (1) in Proposition \ref{p122} implies conditions (2) and (3) in Proposition \ref{p122}. Consequently, $(X, r)$ is a non-degenerate involutive solution if and only if the assignment $x \mapsto \tau_x$ is a right-action of $G(X, r)$ on $X$.
\end{enumerate}
\end{proposition}

\begin{proof}
Since $r$ is an involution, we have 
\begin{equation} \label{eqinvol}
\tau_{\tau_y(x)} \sigma_x(y) = y.
\end{equation} 
This together with condition (1) of Proposition \ref{p122} gives
$$
\tau_x^{-1} T(y) = \tau_x^{-1} \tau_y^{-1} (y) = \tau^{-1}_{\sigma_x(y)} \tau^{-1}_{\tau_y(x)} (y) = \tau^{-1}_{\sigma_x(y)} \sigma_{x} (y) = T \sigma_x(y),
$$
which is assertion (a).
\para 
Suppose that, in addition, each $\sigma_x$ is bijective. Taking $S(x) = \sigma_x^{-1}(x)$, we see that
\begin{equation}\label{equality of sigma S and S tau}
\sigma_x^{-1} S = S \tau_x.
\end{equation}
Now, using \eqref{equality of tau T and T sigma} and \eqref{equality of sigma S and S tau}, we obtain
$$TS(x)=T \sigma_x^{-1}(x)= \tau_x T (x)= \tau_x \tau^{-1}_x(x)=x=\sigma_x \sigma_x^{-1}(x)= \sigma_x S(x)=S\tau^{-1}_x(x) =ST(x),$$
which establishes assertion (b).
\para

The implication  $(1) \Rightarrow (2)$ follows from (a) and (b). Let us prove the implication $(1) \Rightarrow (3)$. Since $r$ is an involution, \eqref{eqinvol} holds and we can rewrite the linking relation in the form
$$
\tau_{\tau_{\tau_z \tau_y(x)}^{-1}(z)} \tau^{-1}_{\tau_y(x)}(y) = \tau^{-1}_{\tau_{\tau_z(y)} \tau_{\sigma_y(z)}(x)} \tau_z(y).
$$
Condition (1) of Proposition \ref{p122} gives $\tau_z \tau_y = \tau_{\tau_z(y)} \tau_{\sigma_y(z)}$. Setting $u = \tau_z \tau_y(x) = \tau_{\tau_z(y)} \tau_{\sigma_y(z)}(x)$, the preceding modified linking relation  takes the form
$$
\tau_{\tau_{u}^{-1}(z)} \tau^{-1}_{\tau^{-1}_z(u)} = \tau^{-1}_{u} \tau_{z},
$$
which proves assertion (c).
$\blacksquare$ 
\end{proof}
\para


Let $(X, r)$ be a non-degenerate bijective solution to the Yang--Baxter equation. We define another solution $(\overline{X}, \bar{r})$ as follows. For $x, y \in  X$, we write $x \sim y$ if $\sigma_x = \sigma_y$ and $\tau_x = \tau_y$. It is clear that $\sim$ is an equivalence relation on $X$. Let $\overline{X} = X /_\sim$ be the set of equivalence classes, and $\bar{x} \in \overline{X}$ denote the image of $x \in X$. A direct check yields the following result  \cite[Lemma 8.4]{MR3974961}.

\begin{proposition}
Let $(X, r)$ be a non-degenerate bijective solution to the Yang--Baxter equation. Then $(\overline{X}, \bar{r})$ is a non-degenerate bijective solution to the Yang--Baxter equation, where 
$$\bar{r}(\bar{x}, \bar{y}) = \big(\,\overline{\sigma_x(y)}, \, \overline{\tau_y(x)} \,\big)$$ 
for $\bar{x}, \bar{y} \in \overline{X}$. Further, the map $(X, r) \to (\overline{X}, \bar{r})$ given by $x\mapsto \bar{x}$ is a morphism of solutions.    
\end{proposition}

The solution $(\overline{X}, \bar{r})$ is called the \index{retraction}{\it retraction} of $(X, r)$, and is denoted by $\Ret(X, r)$. Setting $\Ret^1(X, r)=\Ret(X, r)$, we can repeat the process and define $\Ret^{n+1}(X, r) = \Ret \big(\Ret^{n}(X, r) \big)$ for each $n \ge 1$.
\para

\begin{remark}
{\rm The retraction of a solution was first defined for involutive solutions in \cite[Section 3.2]{MR1722951}. Note that, if $(X, r)$ is involutive, then by \eqref{equality of tau T and T sigma}, we have  $\tau_x = \tau_y$ iff $\sigma_x = \sigma_y$.}
\end{remark}
\para


\begin{definition}
A non-degenerate bijective solution  $(X, r)$ to the Yang--Baxter equation is said to be  a \index{multipermutation solution}{multipermutation solution} of level $n$ if $n$ is the smallest non-negative integer such that the underlying set of $\Ret^n(X, r)$ is a singleton set. Further,  $(X, r)$ is said to be  \index{irretractable solution}{irretractable} if $\Ret(X, r) = (X, r)$.
\end{definition}
\para

\begin{example}
A multipermutation solution of level zero is the trivial solution over a singleton set, while a multipermutation solution of level one is a permutation solution over a non-empty set. 
\end{example}

Several attempts have been made to classify solutions based on their multipermutation levels. Multipermutation solutions of level two can be characterized in a straightforward manner, thanks to results by Gateva-Ivanova  \cite[Proposition 4.7]{MR3861714}.

\begin{theorem}
Let $(X, r)$ be a non-degenerate involutive solution to the Yang--Baxter equation with $|X| \ge 2$. Then  $(X, r)$ is a multipermutation solution of level two if and only if 
$$\sigma_{\sigma_y(x)}=\sigma_{\sigma_z(x)}$$
for all $x, y, z \in X$.
\end{theorem}

Recall that, a group $G$ is called \index{poly-$\mathbb{Z}$ group}{\it poly-$\mathbb{Z}$} if it admits a subnormal series
$$1 = G_0  \triangleleft G_1 \triangleleft \cdots \triangleleft  G_n = G$$
such that $G_i/G_{i-1} \cong \mathbb{Z}$. Further, a group $G$ is \index{left-orderable group}{\it left-orderable} if there is a total order $<$ on $G$ such that 
$x < y$ implies $zx < zy$ for all $x, y, z \in G$. In general, finite non-degenerate involutive multipermutation solutions can be characterized in terms of their structure groups \cite[Theorem 2.1]{MR3815290}. 

\begin{theorem}
Let $(X, r)$ be a finite non-degenerate involutive solution to the Yang--Baxter equation. Then the following statements are equivalent:
\begin{enumerate}
\item $(X, r)$ is a multipermutation solution.
\item $G(X, r)$ is left-orderable.
\item $G(X, r)$ is poly-$\mathbb{Z}$.
\end{enumerate}
\end{theorem}

We note that the implication $(1) \Rightarrow (3)$ was already proved in  \cite{MR2189580}.


\begin{remark}
{\rm 
There is a continuously evolving  body of work on multipermutation solutions of finite levels:
\begin{enumerate}
\item In \cite[Theorem 4.21]{MR3861714}, several characterizations of solutions of finite multipermutation level are given.
\item In \cite{MR4123749}, a  classification of involutive solutions of multipermutation level two is given, with a bound on the number of such solutions. In the follow-up work \cite{MR4568107}, a complete characterization, up to isomorphism, of all indecomposable involutive solutions of multipermutation level two is given. 
\end{enumerate}}
\end{remark}
\para



Let $\Sigma_X$ be the group of permutations of $X$ and $\mathbb{Z}^X$ the free abelian group generated by $X$. We denote the generator of $\mathbb{Z}^X$ corresponding to $x \in X$ by $t_x$. Let $$M(X, r) = \Sigma_X \ltimes \mathbb{Z}^X$$  be the semi-direct product associated to the action of $\Sigma_X$ on $\mathbb{Z}^X$. For $\alpha \in \Sigma_X$ and $t_x \in \mathbb{Z}^X$, the relation $$\alpha t_x = t_{\alpha(x)} \alpha$$ holds in $M(X, r)$. With this set-up, we have the following result \cite[Proposition 2.3]{MR1722951}. 

\begin{proposition} \label{p129}
If $(X, r)$ is a non-degenerate involutive solution to the Yang--Baxter equation,  then the assignment $x \mapsto \tau^{-1}_{x} t_{x}$ extends to a group homomorphism $$\varphi_{\tau}: G(X, r) \to M(X, r).$$
\end{proposition}

\begin{proof}
The assignment $x \mapsto \tau^{-1}_{x} t_{x}$ gives a group homomorphism from the free group on $X$ to the group $M(X, r)$. For brevity, let us write   $r(x, y) = (u, v)$. Then we need to show that
 \begin{equation} \label{eq126}
\tau^{-1}_{x} t_{x} \tau^{-1}_{y} t_{y} = \tau^{-1}_{u} t_{u} \tau^{-1}_{v} t_{v}.
 \end{equation}
Using the relations in $M(X, r)$, we obtain
\begin{equation}\label{eq127}
\tau^{-1}_{x} t_{x} \tau^{-1}_{y} t_{y} = \tau^{-1}_{x} \tau^{-1}_{y}  t_{\tau_y(x)} t_{y}
\end{equation}
and
\begin{equation}\label{eq128}
\tau^{-1}_{u} t_{u} \tau^{-1}_{v} t_{v} = \tau^{-1}_{u} \tau^{-1}_{v}  t_{\tau_v(u)} t_{v}.
\end{equation}
Since $u = \sigma_x(y)$ and $v = \tau_y(x)$, the involutivity of $r$ gives $\tau_v(u) = y$. By Proposition \ref{p123}(3), the map $x \mapsto \tau_x$ is a right-action of $G(X, r)$ on $X$, which is equivalent to $\tau_y \tau_x = \tau_v \tau_u$. Using all this information on the right hand sides of \eqref{eq127} and \eqref{eq128} establishes \eqref{eq126}, which is desired. $\blacksquare$ 
\end{proof}


\begin{remark}{\rm 
If $(X, r)$ is a non-degenerate involutive solution to the Yang--Baxter equation, then we analogously have a homomorphism $$\varphi_{\sigma} : G(X, r) \to M(X, r)$$ defined by $x \mapsto  t_x \sigma_x$. Let $T:X \to X$ be the permutation given by $T(x)=\tau_x^{-1}(x)$ and $\hat{T}$ the automorphism of $M(X, r)$ induced by $T$. By Proposition \ref{p123}, we have $\tau_x^{-1} T = T \sigma_x$, which implies that $\hat{T}$ conjugates $\varphi_{\tau}$ to $\varphi_{\sigma}$. Hence, it is enough to study the properties of $\varphi_{\tau}$, and we denote it simply by $\varphi$ \cite[Section 2.2]{MR1722951}.}
\end{remark}

Let $\pi : G(X,r) \to \mathbb{Z}^X$  be the map defined by $\pi(g) = \pi_2\varphi(g)=t$, where $\varphi(g) = \alpha\, t$ for $\alpha \in \Sigma_X$ and $t \in \mathbb{Z}^X$, and $\pi_2: M(X, r)\to \mathbb{Z}^X$ is the projection onto the second factor. The assignment $x \mapsto \tau_x^{-1}$ gives a left-action of $G(X,r)$ on $X$, which further extends to a left $G(X,r)$-module structure on $\mathbb{Z}^X$. With this background, we have the following result \cite[Proposition 2.5]{MR1722951}.


\begin{proposition}  \label{p130}
Let $(X, r)$ be a non-degenerate involutive solution to the Yang--Baxter equation. Then the following  assertions hold:
\begin{enumerate}
\item $\pi : G(X,r) \to \mathbb{Z}^X$  is a group 1-cocycle of $G(X,r)$  with coefficients in the $ G(X,r)$-module $\mathbb{Z}^X$, that is,
$$\pi(g h) = \pi(g) + g \cdot \pi(h)$$
for any $g, h \in G$.
\item $\pi$ is bijective.
\end{enumerate}
\end{proposition}

\begin{proof}
Let $g, h \in G(X, r)$. Suppose that $\varphi(g)=\alpha \, s$ and $\varphi(h)=\beta \, t$ for $\alpha, \beta \in \Sigma_X$ and $s, t \in \mathbb{Z}^X$. Using the fact that $\varphi$ is a group homomorphism and the definition of a semi-direct product, we have 
$$\pi(gh)= \pi_2\varphi(gh)=\pi_2 \big(\varphi(g) \varphi(h) \big)= \pi_2 \big((\alpha \, s)(\beta \, t) \big)= \pi_2 \big((\alpha\beta) (s+ \alpha(t)) \big)= s+ \alpha(t)=\pi(g)+ g \cdot \pi(h),$$
which proves assertion (1). The proof of assertion (2) involves constructing an explicit inverse to the map $\pi$, and we refer the reader to \cite[Section 2.3]{MR1722951} for details. $\blacksquare$ 
\end{proof}

As an immediate consequence of Proposition \ref{p130}, we have the following result.

\begin{corollary}
Let $(X, r)$ be a non-degenerate involutive solution to the Yang--Baxter equation. Then the homomorphism $\varphi: G(X, r) \to M(X, r)$ is injective.
\end{corollary}
\medskip


\begin{remark}\label{remark on bij 1 cocycle}
{\rm 
Groups with bijective 1-cocycles have a nice geometrical interpretation. Namely, a bijective 1-cocycle on a simply connected Lie group $G$ with coefficients in some real representation is equivalent to a left-invariant affine structure on $G$ as a manifold, which identifies $G$ with an affine space. To admit such a structure, the group must be contractible as a topological space. It is known that many solvable Lie groups admit left-invariant affine structures as above \cite{MR1411303}. In fact, Milnor had conjectured that any solvable simply connected Lie group admit a left-invariant affine structure, but it was disproved by Burde \cite{MR1411303} by finding a nilpotent group that admit no such structure. Further, bijective cocycles on finite groups have been used by Etingof and Gelaki \cite{MR1653340} to construct new examples of semisimple Hopf algebras.}
\end{remark}

\begin{remark}\label{the g0 group}
{\rm 
Let $(X, r)$ be a non-degenerate involutive solution to the Yang--Baxter equation. Consider the group $$\Gamma =  G(X,r) \cap \mathbb{Z}^X,$$ where we consider $ G(X,r)$ as a subgroup of $M(X, r)$ via $\varphi$. Since $\Gamma$ is the kernel of the homomorphism $\rho :  G(X,r) \to \Sigma_X$, defined by the action of $ G(X,r)$ on $X$, it follows that $\Gamma$ is a normal subgroup of $ G(X,r)$. We set 
$$ G^0(X,r) =  G(X,r) / \Gamma \quad \textrm{and} \quad A = \mathbb{Z}^X / \Gamma.$$
Then we see that  $G^0(X,r)$ is the image of $G(X,r)$ in $\Sigma_X$. In particular, if the set $X$ is finite, then $G^0(X,r)$ is finite and $A$ is a finite abelian group with $|A| = |G^0(X,r)|$.}   
\end{remark}
\bigskip

Next, we associate another group $A(X, r)$ to each solution $(X, r)$ to the Yang--Baxter equation.

\begin{definition}
Let $(X,r)$ be a solution to the Yang--Baxter equation with $r(x, y)=\big(\sigma_x(y), \tau_y(x)\big)$. The \index{derived structure group}{\it derived structure group} $A(X, r)$ of the solution $(X, r)$ is a group with the following presentation
$$
A(X, r) = \big\langle X \, \mid \, x \; \sigma_x(y)  = \sigma_x(y) \; \sigma_{\sigma_x(y)}\left( \tau_y(x) \right)~ \textrm{for all}~ x, y \in X \big\rangle.
$$
\end{definition}
\para

\begin{example}\label{examples of derived str group}
{\rm 
Let $(X,r)$ be a solution to the Yang--Baxter equation.
\begin{enumerate}
\item If $r(x, y) = (x, y)$ is the identity map, then $A(X, r) \cong G(X, S) \cong F(X)$, the free group with basis $X$.
\item If $r(x, y) = (y, x)$, then $A(X, r) \cong G(X, r)\cong \mathbb{Z}^{X}$, the free abelian group generated by $X$.
\item If $(X, r)$ is an involutive solution and $r$ is not the identity map, then 
$$
r^2(x, y) = \big( \sigma_{\sigma_x(y)}\left( \tau_y(x) \right),  ~ \tau_{\tau_y(x)}\left( \sigma_x(y) \right) \big) = (x, y)
$$
and 
$$
A(X, r)= \big\langle X  \, \mid \, x \, \sigma_x(y)  = \sigma_x(y) \, x ~ \textrm{for all}~ x, y \in X \big\rangle.
$$
If $(X, r)$ is right non-degenerate, then  $A(X, r)\cong \mathbb{Z}^{X}$, the free abelian group of rank $|X|$.
\item If $X$ is a quandle and $r(x, y) = (y, \,x*^{-1}y)$, then $A(X, r) = G(X, r)$.
\end{enumerate}}
\end{example}
\para

Given a solution $(X, r)$ to the Yang--Baxter equation, let 
$$i_X : X \to G(X, r) \quad \textrm{and} \quad j_X : X \to A(X, r)$$ denote the two natural maps that send each element of $X$ to the corresponding generator of the group. We note that these maps are not always injective. 

\begin{example}{\rm 
Let $X = \mathbb{Z}$ and $r: X \times X \to X \times X$ be given by $r(i, j) = (j+1, i)$. Then $(X, r)$ is a non-degenerate bijective but non-involutive solution to the Yang--Baxter equation. Note that $G(X, r)$ is generated by elements $\{x_i \,\mid \; i \in \mathbb{Z} \}$
and has defining relations
$$
x _i \, x_j = x_{j+1}\,  x_i
$$
for $i,j \in \mathbb{Z}$. These relations imply  that $x_i = x_j$ for all $i, j \in \mathbb{Z}$, and hence $G(X, r) = \langle x_0 \rangle$
is the infinite cyclic group. Clearly, the natural map $i_X : X \to G(X, r)$ is not injective.}
\end{example}

In general, we have the following example (see \cite[Section 9]{MR1183474} and \cite[p. 171]{MR1722951}).

\begin{example}{\rm 
Let $X$ be a non-empty set, and $f$ and $g$ two commuting permutations of $X$. Then the map $$r(x,y) = \big(g(y),f(x) \big)$$ is a non-degenerate solution to the Yang--Baxter equation. In this case, we have the relation $xy = fg(x) \, fg(y)$ in $G(X,r)$ for all $x, y \in X$. Thus, if $fg$ has at least one fixed point in $X$, then we have relations $fg(y) = y$ in $G(X,r)$ for all $y \in X$, although it may not be so in $X$.}
\end{example}
\medskip

Example \ref{examples of derived str group}(4) supply infinitely many cases where $i_X$ fails to be injective, as well as infinitely many cases where $i_X$ is injective. See Theorem \ref{injectivity-dehn-eta} for a complete characterisation of quandles for which $i_X$ is injective. However, if the solution is involutive, then  $i_X: X \to G(X, r)$ is always injective (see Remark \ref{injectivity of eta remark}).
\medskip

\begin{example}{\rm 
Let $X$ be a monoid with the identity element $e$  and $r: X \times X \to X \times X$ be given by $r(x, y) = (e, x y)$. Then $(X, r)$ is a non-bijective, left  non-degenerate and right degenerate  solution to the Yang--Baxter equation. Note that $A(X, r)$ is the trivial group, and hence the natural map $j_X : X \to A(X, r)$ is not injective.}
\end{example}

For a non-degenerate solution $(X, r)$, let us write 
\begin{equation}\label{left-actions of the structure group}
x \circ y = \sigma_x(y) \quad \textrm{and} \quad  y * x = \tau_y^{-1}(x)
\end{equation}
for $x, y \in X$. By Proposition \ref{p122}, these operations can be extended to left-actions of the structure group $G(X, r)$ on $X$. We denote the action of an element $g \in  G(X,r)$ on an element $x \in  X$ by $g \circ x$ and $g * x$, respectively. 
Define the maps
$$
\phi: X \times X \to X \quad \textrm{by} \quad \phi(x, y)=y \circ \big( (x^{-1} \circ y)^{-1} * x \big)
$$
and
$$
r^\star: X \times X \to X \times X \quad \textrm{by} \quad r^\star(x, y)=\big(y, \phi(x, y)\big)
$$
for $x, y \in X$. Here, for $z \in X$, the element $z^{-1}$ is the inverse of $z$ when viewed as a generator of $G(X, r)$. Then we have the following result \cite[Theorem 2.3]{MR1809284}. 
\para

\begin{theorem} \label{deribed sol derived group}
Let $(X, r)$ be a non-degenerate solution to the Yang--Baxter equation. Then the following  assertions hold:
\begin{enumerate}
\item $\phi$ is $G(X, r)$-equivariant with respect to the $\circ$-action. In other words,
$$
g \circ \phi(y, z) = \phi(g \circ y, g \circ z)
$$
holds for all $g \in G(X, r)$ and $x, y \in X$.
\item  $(X, r^\star)$ is a non-degenerate solution to the Yang--Baxter equation (called the \index{derived solution}{\it derived solution} of $(X, r)$).
\item The structure group of the derived solution is the derived structure group.
\end{enumerate}
\end{theorem}

\begin{proof}
For assertion (1), it is enough to prove that
$$
t \circ \phi(y, z)  = \phi(t \circ y, t\circ z)
$$
for all $t, y, z \in X$. By definition of $\phi$, it is equivalent to proving that
\begin{equation} \label{eq-2.3}
t \circ \big( z \circ ( (y^{-1} \circ z)^{-1} * y ) \big)= 
(t \circ z) \circ  \big( ((t \circ y)^{-1} \circ (t \circ z) )^{-1} * (t \circ y) \big)
\end{equation}
for all $t, y, z \in X$. Since $(X, r)$ is a solution to the Yang--Baxter equation, the linking relation of Proposition \ref{p122} holds, that is, 
\begin{equation} \label{eq-2.4}
\big((y^{-1} * x) \circ t \big)^{-1} * (x \circ y) =  \big(( y \circ t)^{-1} * x \big) \circ (t^{-1} * y)
\end{equation}
for all $x, y, t \in X$. Putting $t = y^{-1} \circ z$ on the left hand side of  \eqref{eq-2.4} gives
$$
 \big((y^{-1} * x) \circ t \big)^{-1} * (x \circ y) =  \big((y^{-1} * x) \circ (y^{-1}x^{-1} \circ (x \circ z)) \big)^{-1} * (x \circ y),
$$
where $y^{-1}x^{-1}$ is the product  in the group $G(X, r)$. Since $$y^{-1}x^{-1} = \tau_y(x)^{-1}\sigma_x(y)^{-1}=(y^{-1} *x)^{-1} (x \circ y)^{-1}$$ in  $G(X, r)$, we have
$$
 \big((y^{-1} * x) \circ t \big)^{-1} * (x \circ y) =  \big((y^{-1} * x) \circ ((y^{-1} *x)^{-1} (x \circ y)^{-1} \circ (x \circ z)) \big)^{-1} * (x \circ y)= \big((x \circ y)^{-1} \circ (x \circ z)\big)^{-1} * (x \circ y).
$$
Hence, relation \eqref{eq-2.4} is equivalent to the relation
\begin{equation} \label{eq-2.5}
\big((x \circ y)^{-1} \circ (x \circ z) \big)^{-1} * (x \circ y) =(z^{-1} * x) \circ \big((y^{-1} \circ z)^{-1} * y \big)
\end{equation}
Using \eqref{eq-2.5} in the right hand side term of \eqref{eq-2.3} gives 
$$(t \circ z) \circ  \big( ((t \circ y)^{-1} \circ (t \circ z) )^{-1} * (t \circ y) \big)=(t \circ z) \circ \big( (z^{-1} * t) \circ ((y^{-1} \circ z)^{-1} * y)\big)=\big((t \circ z)(z^{-1} * t)\big) \circ \big((y^{-1} \circ z)^{-1} * y\big).$$
Using the relation
$$
tz = \sigma_t(z)\tau_z(t)= (t \circ z)(z^{-1} * t)
$$
in group $G(X,  r)$,  the preceding equation can be written as 
$$(t \circ z) \circ  \big( ((t \circ y)^{-1} \circ (t \circ z) )^{-1} * (t \circ y) \big)=t \circ \big( z \circ ((y^{-1} \circ z)^{-1} * y) \big),$$
which is desired.
\para 

Since $\phi(x, y)=\sigma_y \big(\tau_{\sigma^{-1}_x(y)}(x) \big)$, assertion (2) follows from Theorem  \ref{SolTh}. Finally, assertion (3) follows from the definitions of the structure group, the derived structure group and the map $\phi$. $\blacksquare$
\end{proof}

Let $\Aut_X \big(A(X, r) \big)$ denote the group of automorphisms of $A(X, r)$ that map the generating set $X$ onto itself. The next result shows that the natural map $j_X:X \to A(X, r)$ is $G(X, r)$-equivariant with respect to a suitable $G(X, r)$-action on $A(X, r)$ \cite[Theorem 2.4]{MR1809284}.

\begin{theorem} \label{action of str group on der str group}
Let $(X, r)$ be a non-degenerate solution to the Yang--Baxter equation. Then the group homomorphism  $\circ : G(X, r) \to \Sigma_X$  can be uniquely lifted to the group homomorphism  $\hat{\circ}: G(X, r) \to  \Aut_X \big(A(X, r)\big)$ such that $j_X:X \to A(X, r)$ is $G(X, r)$-equivariant. More precisely,
$$j_X(g \circ x) = g \,\hat{\circ}\, j_X(x)$$
for all  $g \in G(X, r)$ and $x \in X$.
\end{theorem}

\begin{proof}
It is clear that the homomorphism $\circ: G(X, r) \to \Sigma_X$ can be uniquely extended to a homomorphism from $G(X,r)$ to the group of automorphisms of the free group $F(X)$ on $X$. By Theorem \ref{deribed sol derived group}, each such automorphism of $F(X)$ arising from the $G(X, r)$-action  preserves relations in $A(X, r)$, and hence gives a homomorphism $\hat{\circ}: G(X, r) \to  \Aut_X \big(A(X, r)\big)$. The last assertion is immediate from the construction.  $\blacksquare$
\end{proof}

We have the following results (see \cite[Theorem 2.15]{MR1722951} and \cite[Proposition 6 and Proposition 10]{MR1769723}).

\begin{theorem} \label{CentSub} 
Let $(X, r)$ be a finite solution to the Yang--Baxter equation. Then the following assertions hold:
\begin{enumerate}
\item If  $(X, r)$ is non-degenerate or bijective, then $G(X, r)$ has a finitely generated abelian normal subgroup of finite index.
\item If $(X, r)$ is non-degenerate involutive, then $G(X, r)$ is solvable.
\end{enumerate}
\end{theorem} 


Proposition \ref{deribed sol derived group}(3) and Theorem \ref{CentSub}(1) give the following result.

\begin{corollary}  \label{CentSubDer}
Let $(X, r)$ be a finite non-degenerate solution to the Yang--Baxter equation. Then $A(X, r)$ has a finitely generated abelian normal
subgroup of finite index. Moreover, $A(X,r)$ has a central subgroup of finite index.
\end{corollary} 

The next result gives equivalent conditions for the group $A(X, r)$ to be abelian (see \cite[Proposition 3.15]{MR3835326} and \cite[Proposition 4]{MR1769723}).

\begin{proposition} \label{AbelGr}
Let $(X, r)$ be a non-degenerate solution to the Yang--Baxter equation. Then the following statements are equivalent:
\begin{enumerate}
\item $A(X, r)$ is abelian.
\item $A(X, r)$ is free abelian with basis $X$.
\item $(X,r)$ is involutive.
\end{enumerate}
\end{proposition}

\begin{proof}
The implication $(2) \Rightarrow  (1)$ is obvious. Recall the presentation
$$A(X, r) = \big\langle X ~\mid ~x \; \sigma_x(y)  = \sigma_x(y) \; \sigma_{\sigma_x(y)}\left( \tau_y(x) \right)~ \textrm{for all}~ x, y \in X \big\rangle.$$
Further, note that $(X,r)$ is involutive if and only if 
$$\left( \sigma_{\sigma_x(y)}\left( \tau_y(x) \right),  ~ \tau_{\tau_y(x)}\left( \sigma_x(y) \right) \right) = (x, y)$$
for all $x, y \in X$. Since $(X, r)$ is a non-degenerate solution, the implication $(1) \Leftrightarrow (3)$ is now evident. Let us prove the implication $(1)  \Rightarrow  (2)$. Consider the map
$$
X \to H:=\big\langle j_X(X)~|~j_X(x) \, j_X(y) = j_X(y) \, j_X(x) ~\textrm{for all}~x, y \in X \big\rangle  \cong \mathbb{Z}^{j_X(X)}
$$
given by $x \mapsto j_X(x)$. We claim that it induces a group homomorphism $A(X, r) \to  H$. Since $A(X, r)$ is abelian, $(X,r)$ is involutive, which implies that
$$
j_X \left( \sigma_{\sigma_x(y)} (\tau_y(x))\right) = j_X(x)
$$
for all $x, y \in X$. Thus, if we apply $j_X$ to the  relation
$$
\sigma_x(y)^{-1} \, x^{-1} \, \sigma_x(y) \, \left( \sigma_{\sigma_x(y)} (\tau_y(x))\right) 
$$
of $A(X, r)$, then we obtain
$$
j_X \left( \sigma_x(y) \right)^{-1} \, j_X(x)^{-1} \, j_X(\sigma_x(y)) \, j_X\left( \sigma_{\sigma_x(y)} (\tau_y(x))\right) =
j_X \left( \sigma_x(y) \right)^{-1} \, j_X(x)^{-1} \, j_X(\sigma_x(y)) \, j_X (x) = 1.
$$
The homomorphism is in fact an isomorphism with its  inverse induced by the inclusion map $j_X(X) \to  A(X, r)$. $\blacksquare$ 
\end{proof}

For a finite solution $(X, r)$,  it is possible to characterize precisely when the group $A(X, r)$ is torsion-free \cite[Proposition 3.16]{MR3835326}.

\begin{proposition}
Let $(X, r)$ be a finite non-degenerate solution to the Yang--Baxter equation. Then $A(X, r)$ is torsion free if and only if $A(X, r)$ is abelian.
\end{proposition}

\begin{proof}
By Proposition \ref{AbelGr}, it is enough to show that $A(X, r)$ is torsion-free if and only if it is free abelian. Since $(X, r)$ is finite, by Corollary \ref{CentSubDer}, $A(X, r)$ is a finitely generated group containing an abelian normal subgroup of finite index. By \index{Schreier's lemma}{Schreier's lemma}, all finite index subgroups of finitely generated groups are also finitely generated \cite[Proposition 4.2]{MR1812024}. If $A(X, r)$ is torsion-free, we conclude that it contains a central finitely generated free abelian group of finite index. Hence, by \cite[Proposition 7.13]{MR1812024}, $A(X, r)$ is itself free abelian. $\blacksquare$
\end{proof}
\para

A group $G$ is called a \index{Bieberbach group}{\it Bieberbach group} if it is finitely generated, torsion free and abelian-by-finite. In other words, $G$ is an extension of a finitely generated free abelian group by a finite group. We conclude this section with the following result (see \cite[Theorem 1.6]{MR1637256} and \cite[Corollary 8.2.7]{MR2301033}).

\begin{theorem}
If $(X, r)$ is an involutive solution, then $G(X, r)$ is a Bieberbach group and is of $I$-type. 
\end{theorem}
\bigskip
\bigskip

