\section{Solutions and braiding operators on groups}

In this section, our focus lies on exploring solutions to the Yang--Baxter equation within the context of groups. We begin with the following result \cite[Theorem 1]{MR1769723}.

\begin{theorem} \label{CompAct}
Let $G$ be a group. Let $\sigma$ and $\tau$ be left- and right-actions of $G$ on itself, denoted by $(x, y) \mapsto \sigma_x(y)$ and $(x, y) \mapsto \tau_y(x)$, respectively. If the two actions satisfy the compatibility condition
\begin{equation} \label{compat}
x y = \sigma_x(y) \tau_y(x)
\end{equation}
for all $x, y \in G$ and $r: G \times G \to  G \times G $ is the map given by
$$
r(x, y)= \big(\sigma_x(y), \, \tau_y(x)\big)
$$
for all $x, y \in G$, then $(G, r)$ is a non-degenerate bijective solution to the Yang--Baxter equation.
\end{theorem}

\begin{proof}
Recall that, by Proposition \ref{component conditions for a solution}, $(G, r)$ is a solution to the Yang--Baxter equation if and only if
\begin{eqnarray}
\sigma_{\sigma_x(y)} \big(\sigma_{\tau_y(x)} (z) \big) &=& \sigma_x \big( \sigma_y(z) \big), \label{CompAct (1)}\\
 \tau_{\sigma_{\tau_y(x)}(z)}  \big( \sigma_x(y) \big) &=&\sigma_{\tau_{\sigma_y(z)}(x)}  \big( \tau_z(y) \big), \label{CompAct (2)} \\
\tau_{\tau_z(y)} \big(\tau_{\sigma_y(z)} (x) \big) &=& \tau_z \big( \tau_y(x) \big), \label{CompAct (3)}
\end{eqnarray}
 hold for all $x, y, z \in X$. Using the fact that $(x, y) \mapsto \sigma_x(y)$ is a left-action and the compatibility condition \eqref{compat}, we have
$$ \sigma_{\sigma_x(y)} \big(\sigma_{\tau_y(x)} (z)\big)= \sigma_{\sigma_x(y)\tau_y(x)} (z)= \sigma_{xy} (z)= \sigma_{x} \sigma_y (z),$$
which establishes \eqref{CompAct (1)}. Similarly, using the fact that $(x, y) \mapsto \tau_y(x)$ is a right-action, we can prove \eqref{CompAct (3)}. A repeated use of the compatibility condition \eqref{compat} shows that the product of elements on the right hand side of \eqref{CompAct (1)}-\eqref{CompAct (3)} equals the element $xyz$, which further equals the product of elements on the left hand side of \eqref{CompAct (1)}-\eqref{CompAct (3)}. This shows that \eqref{CompAct (2)} also hold, and hence $(G,r)$ is a solution to the Yang--Baxter equation. 
\para
To see that $r$ is bijective, let $r(x, y) = \big(\sigma_x(y), \tau_y(x) \big)=(u, v)$. Then, the compatibility condition becomes $xy=uv$ and we get
$$
\left(\sigma_v(y^{-1}) \right) x = \sigma_v(y^{-1})  \tau_{y^{-1}}(v) = vy^{-1} = u^{-1} x.
$$
This implies that $y^{-1} =  \sigma_{v^{-1}}(u^{-1})$. Similarly, we have $x^{-1} = \tau_{u^{-1}}(v^{-1})$, and hence $r(v^{-1}, u^{-1})=(y^{-1}, x^{-1})$. It means that  if we put $s(x, y)=(y^{-1}, x^{-1})$, then
$(s r)^2 = \id_{X \times X}$, which implies that $r$ is bijective.
$\blacksquare$    \end{proof}          

Example \ref{OnGr} gives some elementary solutions on groups. Let us see which of these solutions satisfy the conditions of Theorem \ref{CompAct}.

\begin{example}{\rm 
Let $G$ be a group.
\begin{enumerate}
\item Consider the braiding given by $(x, y) \mapsto (y, y^{-k} x y^k)$. Then $\sigma_x = \id_G$ and $\tau_y(x) = y^{-k} x y^k$. We see that each $\tau_y$ is an automorphism of $G$. But,
$$
\tau_{y_1 y_2}(x) = (y_1 y_2)^{-k} x (y_1 y_2)^{k} \quad \textrm{and}\quad \tau_{y_2} \left(\tau_{y_1}(x) \right) = y_2^{-k} y_1^{-k} x y_1^{k} y_2^{k}.
$$
Hence, $\tau$ defines a right-action on any group if and only if $k=0, 1$. Further, the actions are compatible if and only if $k=1$.

\item For the braiding given by $(x, y) \mapsto (y, y x^{-1} y)$, we have $\sigma_x = \id_G$ and $\tau_y(x) =y x^{-1} y$. We see that in general $\tau_y$ is not an automorphism of $G$.
\item For the braiding given by $(x, y) \mapsto \big(y, \, \varphi(x y^{-1}) y \big)$, where $\varphi \in \Aut(G)$, we have $\sigma_x = \id_G$ and $\tau_y(x) =\varphi(x y^{-1}) y$. In this case, $ \tau_y$ is an automorphism of $G$ if and only if $y=1$.
\end{enumerate}}
\end{example} 

We now give an alternate description of solutions constructed in Theorem \ref{CompAct}.


\begin{definition}\label{def braiding operator}
 Let $G$ be a group with multiplication $m$. A \index{braiding operator}{\it braiding operator} on $G$ is a bijective map $r : G \times  G \to G \times G$ satisfying the following conditions:
\begin{enumerate}
\item For any $u, v, w \in G$,
\begin{equation} \label{braiding4}
r(u v, w)=(\id_G \times m) \, r_{12} \, r_{23}  \,(u, v, w), 
\end{equation}
\begin{equation} \label{braiding5}
r(u, v w)=(m \times \id_G)  \,r_{23}  \,r_{12} \, (u, v, w). 
\end{equation}

\item For any $u \in G$,
\begin{equation} \label{braiding6}
r(1, u)=(u, 1) \quad \textrm{and} \quad r(u, 1)=(1, u).
\end{equation}
\item For any $u, v \in G$,
\begin{equation} \label{braiding7}
m  \,r(u, v) = uv. 
\end{equation}
\end{enumerate}
\end{definition}


\begin{example}{\rm 
If $G$ is a group, then $r(u, v)=(v,  v^{-1} u v)$ is a braiding operator, called the \index{conjugate braiding}{\it conjugate braiding}. This braiding  comes from the Artin representation of the braid group $\B_n$ by automorphisms of the free group $F_n$ of rank $n$.}
\end{example} 


\begin{definition}
Let $G$ and $A$ be groups. Let $G$ acts on $A$ on the left by automorphisms, denoted by $(g, a) \mapsto g \cdot a$ for $g \in G$ and $a \in A$. A bijective $1$-cocycle of $G$ with coefficient in $A$ is a bijection $\pi : G \to A$ such that 
$$
\pi (g h) = \pi(g) \, \big(g \cdot \pi(h) \big).
$$
holds for any $g, h \in G$.
\end{definition}

The following result gives a connection between braiding operators and bijective 1-cocycles \cite[Theorem 2]{MR1769723}.

\begin{theorem}\label{conjugate braiding thm}
The following statements are equivalent for any group $G$:
\begin{enumerate}
\item There exists a pair  $(\sigma, \tau)$ of compatible  left- and right-actions of $G$ on itself by automorphisms. 
\item There exists a braiding operator $r : G\times G \to G\times G$.
\item There exists a group $A$ on which $G$ acts on the left by  automorphisms and a bijective 1-cocycle $\pi : G \to A$. 
\end{enumerate}
\end{theorem}

\begin{proof} 
Let $(\sigma, \tau)$ be a pair of compatible  left- and right-actions of $G$ on itself by automorphisms. Let  $r : G\times G \to G\times G$ be given by
$$
r(u, v) = \big(\sigma_u(v), ~\tau_v(u) \big)
$$
for $u, v \in G$. To prove that $r$ is a braiding operator, we write
$$
r(u v, w) = (u_1, v_1) \quad \textrm{and} \quad (\id \times m)  \,r_{12} \, r_{23} \, (u, v, w) = (u_2, v_2).
$$
Direct calculations give
$$
u_1 = \sigma_{uv}(w)\quad \textrm{and} \quad u_2 = \sigma_{u} \sigma_{v}(w),
$$
which are equal since $\sigma$ is a left-action. Repeated use of the compatibility condition \eqref{compat} gives $uvw=u_1 v_1$ and $uvw=u_2 v_2$, which in turn implies that $v_1=v_2$. Similarly, one can prove that $r(u, v w)=(m \times \id_G)  \,r_{23}  \,r_{12} \, (u, v, w).$ Identities $r(1, u)=(u, 1)$ and $r(u, 1)=(1, u)$ are obvious, and  $m r(u, v) = uv$ is a direct  consequence of \eqref{compat}. Thus, assertion (1) implies assertion (2). 
\para
Conversely, suppose that $r$ is a braiding operator on $G$. We can write $r(x, y)= \big(\sigma_x(y), \tau_y(x)\big)$ for some maps $\sigma_x, \tau_y:G \to G$. It follows from \eqref{braiding4} that $\sigma_{uv}(w) = \sigma_{u} \sigma_{v}(w)$ for all $u, v,w \in G$. Moreover, \eqref{braiding6} implies that $\sigma_{1}(u) =u$ for all $u \in G$. Hence, $\sigma$ defines a left-action of $G$ on itself by automorphisms. Similarly, $\tau$ defines a right-action of $G$ on itself by automorphisms. The compatibility condition follows from \eqref{braiding7}. This proves that assertions (1) and (2) are equivalent.
\para

Let us prove that assertion  (1) implies assertion (3). Let $(\sigma, \tau)$ be a pair of  compatible actions of $G$ on itself by automorphisms. We take $A = G$ with the product
\begin{equation} \label{formula9}
u\star v = u \,\sigma_{u^{-1}}(v)
\end{equation}
for $u, v \in A$. By replacing $v$ in \eqref{formula9} with $\sigma_u (v)$, we obtain
$$
uv = u\star \sigma_u (v).
$$
Taking $\pi = \id_G : G \to A$, the preceding equation reads as
$$\pi(uv) = \pi(u)\star \big(u \cdot \pi(v) \big),$$
and hence $\pi$ is a bijective 1-cocycle. 
\para
It remains to show that $(A, \star)$ is indeed a group, and that $\sigma$ gives an action of $G$ on $A$ by automorphisms. 
Clearly, the identity 1 of the group $G$ is also the identity element of the groupoid $(A,\star)$. Further, $\sigma_{u} (u^{-1})$ is a right inverse of $u$ in $(A, \star)$. By the compatibility condition \eqref{compat}, we can rewrite $\star$ as
\begin{equation} \label{f10}
u \star v = u \big(\sigma_{u^{-1}}(v) \big) = v \big( \tau_v (u^{-1}) \big)^{-1}. 
\end{equation}
Then it is easy to see that $\left( \tau_{u^{-1}} (u)\right)^{-1}$ is a left inverse of $u$ in $(A, \star)$. But, by the compatibility condition \eqref{compat}, we have $\sigma_{u} (u^{-1})=\left( \tau_{u^{-1}} (u)\right)^{-1}$, and hence each element has an inverse in $(A, \star)$. A repeated use of the compatibility condition \eqref{compat} gives
\begin{equation} \label{f11}
\sigma_u (v x)  \tau_{v x} (u) =  u v x = \sigma_u (v)  \big(\tau_{v } (u)\big) x =
\big(\sigma_u (v) \big)  \big(\sigma_{\tau_{v } (u)} (x) \big)  \big(\tau_{x}(\tau_v (u)) \big).
\end{equation}
Since $\tau$ is a right-action, the rightmost factors on both sides are the same, and hence we  cancel this factor.  Taking  $x = \sigma_{v^{-1}}(w)$, we have
\begin{equation} \label{f12}
\sigma_u (v \star w) = \sigma_u (v x) \overset{(\ref{f11})}{=} \sigma_u (v)  \sigma_{\tau_v(u)}(x)\overset{(a)}{=} 
\sigma_u (v)  \sigma_{\tau_v(u)v^{-1}}(w)\overset{(\ref{compat})}{=} \sigma_u (v)  \sigma_{(\sigma_u(v))^{-1}u}(w)\overset{(a)}{=}
\sigma_u (v) \star \sigma_u (w),
\end{equation}
where $(a)$ means that we use the fact that $\sigma$ is a left-action. Further, we have
$$
u \star (v \star w) = u \big(\sigma_{u^{-1}}(v \star w) \big)  \overset{(\ref{f12})}{=} u \big(\sigma_{u^{-1}}(v)\big) 
\big( \sigma_{(\sigma_{u^{-1}}(v))^{-1}u^{-1}}(w) \big) = (u \star v) \big(\sigma_{(u \star v)^{-1}}(w)\big) =( u \star v ) \star w.
$$
Hence, $(A, \star)$ is a group and $\sigma$ is a left-action of $G$ on $(A, \star)$ by automorphisms.
\para 
To prove that assertion  (3) implies assertion (1), we use $\pi$ to identify $A$ with $G$. We take $\sigma$ to be the pullback of the action of $G$ on $A$ via the bijection $\pi$, defining an action of $G$ on itself. Let $\star$ denote  the pullback of the product of $A$ to $G$. Then $\sigma$ defines an action of $G$ on $(G, \star)$ as well. The 1-cocycle condition implies that \eqref{formula9} holds in $(G, \star)$. Defining $\tau$ as $\tau_v(u)=(\sigma_u(v))^{-1} u v$ according to the compatibility condition, we see  that \eqref{f10} also holds. It remains to show that $\tau$ defines a right-action of $G$ on itself. Since $\sigma$ is a left-action and $\pi(1)=1$, we have 
$$
1 \star u = u=u \star 1
$$
for all $u \in G$, and hence $1$ is also the identity of $(G,\star)$. Taking $v=1$ in \eqref{f10}, we get $\tau_1(u) = u$ for all $u \in G$. Note that, by the compatibility condition for $\sigma$ and $\tau$, we have the equality 
\eqref{f11}. Moreover, since $\sigma$ acts on $(G, \star)$, by taking  $x = \sigma_{v^{-1}}(w)$, we have
\begin{eqnarray*}
\sigma_{u}(v x) &=& \sigma_{u}(v \star w)\\
&=&  \sigma_{u}(v)  \star \sigma_{u}(w) \\
&=&  \sigma_{u}(v) \sigma_{(\sigma_{u}(v))^{-1}} \big(\sigma_{u}(w) \big)\\
&=&  \sigma_{u}(v) \sigma_{(\sigma_{u}(v))^{-1} u}(w)\\
&=& \sigma_{u}(v) \sigma_{(\tau_{v}(u)) v^{-1}}(w)\\
&=& \sigma_{u}(v)  \sigma_{\tau_v(u)}(x).
\end{eqnarray*}
It now follows from \eqref{f11} that $\tau_{v x} (u) = \tau_x \big(\tau_v(u) \big)$, and hence $\tau$ is a right-action of $G$ on itself.
$\blacksquare$   
 \end{proof}          

\begin{corollary}
Any braiding operator $r$ on a group $G$ defines a  non-degenerate bijective solution $(G, r)$ to the Yang--Baxter equation.
\end{corollary}

\begin{proposition}\label{commutative star product}
Let  $r$ be a braiding operator on a group $G$ such that $r(x, y)=\big(\sigma_x(y), \tau_y(x)\big)$.  Then  $r^2 =\id_{G \times G}$ if and only if
the product $\star$ given by
$$
u\star v = u \big(\sigma_{u^{-1}}(v) \big)
$$
 is commutative.
\end{proposition}

\begin{proof}
For each $u, v \in G$, we have
$$
r^{-1}(u, v) = \left( (\tau_{u^{-1}}(v^{-1}))^{-1},~  (\sigma_{v^{-1}}(u^{-1}))^{-1}\right)
$$
from the proof of bijectivity of $r$ in Theorem  \ref{CompAct}. Hence, the condition $r^2 = \id_{G \times G}$ is equivalent to
$$
\sigma_u(v) \tau_{u^{-1}}(v^{-1}) = 1.
$$
We have $u\star v = u \big(\sigma_{u^{-1}}(v) \big)$ and the compatibility condition for the pair $(\sigma, \tau)$ implies that $$v\star u = u  \big(\tau_{u}(v^{-1})\big)^{-1}.$$
Hence, the product $\star$ is commutative if and only if
$$
\sigma_{u^{-1}}(v) \tau_u(v^{-1}) = 1,
$$
which proves the proposition.
$\blacksquare$   
 \end{proof} 


 \begin{proposition}\label{braidings on inverse}
 Let $r$ be a braiding operator on a group $G$. 
 If $ r(u, v) = (y, x)$, then 
 $$
 r(x^{-1}, y^{-1}) = (v^{-1}, u^{-1}),\quad r(u^{-1}, y) = (v, x^{-1}) \quad \textrm{and}\quad r(x, v^{-1}) = (y^{-1}, u).
 $$
 \end{proposition}

\begin{proof}
The proof of the equality $ r(x^{-1}, y^{-1}) = (v^{-1}, u^{-1})$  can be found in the proof of the invertibility of $r$ in Theorem \ref{CompAct}. To prove $ r(u^{-1}, y) = (v, x^{-1}),$ we note that $\sigma_{u^{-1}}(y) = v$ implies that $r(u^{-1}, y) = (v, z)$ for some $z$. Then from the compatibility condition \eqref{braiding7}, we have $u^{-1} y = v z$. On the other hand, applying the compatibility condition to
$r(u, v) = (y, x)$ gives $u v = y x$. Thus, we conclude that $z = x^{-1}$. The proof of the last equality is similar. $\blacksquare$   
 \end{proof} 


Given a braiding operator $r$ on a group $G$, we constructed a new group $(G, \star)$ in the proof of Theorem \ref{conjugate braiding thm}. Define $r^\star: G \times G \to G \times G$  by setting
$$
r^{\star}(u, v) = (v, ~v^{\star(-1)} \star u \star v)
$$
for $u,v \in G$, where
$$
v^{\star(-1)} = \sigma_v(v^{-1}) = \big(\tau_{v^{-1}}(v) \big)^{-1}
$$
is the inverse of $v$ under the operation $\star$. Since $(G, \star)$ is a group, $r^\star$ is clearly a braiding operator (of quandle type) on $(G, \star)$, and called the \index{induced braiding operator}{\it induced braiding operator}. We now have the following result \cite[Theorem 6]{MR1769723}.



\begin{theorem}
Let $r$ be a braiding operator on a group $G$ and $r^{\star}$ the induced braiding operator on $(G, \star)$, where $r(u, v)=\big(\sigma_u(v),\, \tau_v(u)\big)$ for $u, v \in G$. Then the map $T_n: G^n \to G^n$ given by
$$
T_n(u_1, u_2, \ldots, u_{n-1}, u_n) = \big(u_1, ~\sigma_{u_1}(u_2),~ \ldots,~ \sigma_{u_1 \ldots u_{n-2}}(u_{n-1}), ~ \sigma_{u_1 \ldots u_{n-1}}(u_{n})\big)
$$
is an equivalence between the two representations $\B_n \to \Sigma_{G^n}$ of the braid group induced by $r$ and $r^{\star}$.
\end{theorem}

\begin{proof}
Since $r$ is a braiding operator on $G$, it follows from Theorem \ref{conjugate braiding thm} that $uv=\sigma_u(v) \tau_v(u)$ for all $u, v \in G$. Using this fact, the proof is now similar to that of Proposition \eqref{SolTh} and Proposition \ref{SolRack}. $\blacksquare$   
\end{proof}

\begin{remark}{\rm 
Although the braid group actions corresponding to the solutions $(G, r)$ and $(G, r^\star)$ to the Yang--Baxter equation are equivalent, the solutions themselves are not necessarily equivalent.}
\end{remark}

We conclude with the universal property satisfied by the structure group of a non-degenerate bijective solution to the  Yang--Baxter equation. The result is due to Lu, Yan, and Zhu \cite[Theorem 9]{MR1769723}, who also gave an elegant graphical interpretation of the maps involved.

\begin{theorem}\label{univ property non-deg solution st group}
Let $(X, r)$ be a  non-degenerate bijective solution to the Yang--Baxter equation. Let $G(X, r)$ be the structure group of the solution $(X, r)$ and $i_X: X \to G(X, r)$ the natural map. Then the following  assertions hold:
\begin{enumerate}
\item There is a unique braiding operator $r_G$ on $G(X, r)$ such that $r_G \,(i_X \times i_X) = (i_X\times i_X) \,r$, that is, $i_X$ is a morphism of solutions.
\item The group $G(X,r)$ and the braiding operator $r_G$ satisfy the following universal property: If $s$ is a braiding operator on a group $H$ and $\varphi: X \to H$ is a braiding-preserving map, then there is a unique braiding-preserving group homomorphism $\tilde{\varphi}:G(X, r) \to H$ such that $\varphi=\tilde{\varphi}\, i_X$.
\end{enumerate}
\end{theorem}

\begin{proof}
Let $(X, r)$ be a non-degenerate bijective solution to the Yang--Baxter equation. Denote
\begin{equation} \label{formula solution}
r(u, v) = (y, x)
\end{equation}
of $u, v, y, x \in X$. Since $r$ is  bijective, let $r^{-1} : X \times X \to X \times X$ be such that
$$
r^{-1} (y, x) = (u, v).
$$
It follows from the non-degeneracy of $(X,r)$ that for each $(u, y)$, there is a unique $(v, x)$ such that \eqref{formula solution} holds. Similarly, for each $(v, x)$, there is a unique $(u, y)$ such that \eqref{formula solution} holds. If we begin with a triple $(u, v, w)$, then
$$
r_{12}  \,r_{23}  \,r_{12}  \,(u, v, w) = (z, y, x)
=
r_{23}  \,r_{12} \, r_{23}  \,(u, v, w).
$$

We claim that  $r$ can be extended to a braiding operator $r_G:G(X, r)\times G(X, r) \to G(X, r) \times G(X, r)$.  Let $X'$ be another copy of $X$, with $x' \in X'$ denoting the element corresponding to the element $x \in X$. Let $\bar{X}$ be the disjoint union of $X$ and $X'$, and let
$$
U(X) = \bigsqcup_{i=0}^{\infty} \bar{X}^i = \{ e \} \bigsqcup \bar{X} \bigsqcup \bar{X} \times \bar{X} \bigsqcup \bar{X}  \times \bar{X}  \times  \bar{X} \bigsqcup \cdots
$$
be the free monoid generated by $\bar{X}$. Let $\sim $ be the equivalence relation on $U(X)$ generated by 
$$
g u u' h \sim  gh,~~ g u' u h \sim  gh,~~ g u v h \sim  g y x h~~\textrm{whenever}~~r(u, v) = (y, x),
$$
where $g, h \in  U(X)$ and $u, v, x, y \in X$. Then we have $G(X, r) = U(X) / \sim $.
\para

We begin the construction of $r_G$ by first extending $r$ to a solution $\bar{r} : \bar{X} \times \bar{X} \to \bar{X} \times \bar{X}$. Note that each $x' \in X'$ becomes $x^{-1}$ in $G(X, r)$.  Thus, in view of Proposition \ref{braidings on inverse}, the extension
$\bar{r}$ can be defined as follows. If $r(u, v) = (y, x)$ for $u, v, x, y \in X$, then we define
$$
\bar{r} (u, v) = (y, x),\quad \bar{r} (x', y') = (v', u'),\quad \bar{r} (u', y) = (v, x')\quad \textrm{and}\quad \bar{r} (x, v') = (y', u).
$$
It is not difficult to see that $(\bar{X},\bar{r})$ is a solution to the Yang--Baxter equation (see \cite[Proposition 8]{MR1769723} for a proof). 
\para 

Next, we extend $\bar{r}$ to a solution $r_U:U(X) \times U(X) \to U(X) \times U(X)$. The idea for the definition of $r_U$ comes from the formulas
$$
r(u v, w)=(\id_G \times m) \,r_{12} \,r_{23}  \,(u, v, w) 
\quad \textrm{and}\quad 
r(u, v w)=(m \times \id_G) \,r_{23} \,r_{12}  \,(u, v, w) 
$$
in Definition \ref{def braiding operator}. Note that the product of $u, v \in \bar{X}$ in $U(X)$ is the pair $(u, v) \in \bar{X}\times \bar{X}$. Hence, if $r_U$ satisfies the preceding two formulas, then we  have
$$
r_U \big((u, v), w \big) = \bar{r}_{12} \,\bar{r}_{23} \, (u, v, w) \quad \textrm{and}\quad r_U \big(u, (v, w)\big) = \bar{r}_{23} \,\bar{r}_{12}  \,(u, v, w),
$$
where the triples on the right sides are considered in $\bar{X} \times (\bar{X}\times \bar{X})$ and $(\bar{X}\times \bar{X}) \times \bar{X}$, respectively, since
$$
(\id_X \times m) (u, v, w) =  \big(u, (v, w)\big) \quad \textrm{and}\quad (m \times \id_X) (u, v, w) = \big((u, v), w\big) 
$$
in $U(X)$. This leads us to define $r_U \big((u_1, \ldots, u_m), (v_1, \ldots, v_n) \big)$. For instance,
$$
r_U \big((u_1, u_2, u_3), (v_1, v_2) \big) = \bar{r}_{23} \,\bar{r}_{12} \,\bar{r}_{34} \,\bar{r}_{23} \,\bar{r}_{45}\, \bar{r}_{34} \,\big((u_1, u_2, u_3), (v_1, v_2) \big).
$$
In general, we define $ r_U : U(X) \times U(X) \to U(X) \times U(X)$ 
by
$$r_U (e, u) = (u, e)\quad \textrm{and} \quad r_U (u, e) = (e, u),$$
and on $\bar{X}^m \times \bar{X}^n$ with $m, n \geq 1$ by
$$
r_U = (\bar{r}_{n,n+1} \ldots  \bar{r}_{23} \,\bar{r}_{12})  (\bar{r}_{n+1,n+2} \ldots  \bar{r}_{34}\, \bar{r}_{23}) \ldots  (\bar{r}_{n+m-1,n+m} \ldots  \bar{r}_{m+1,m+2} \,\bar{r}_{m,m+1}),
$$
where the image is considered to be in $\bar{X}^n \times \bar{X}^m$. It is easy to see  that the definition above is equivalent to the requirement that the first two conditions for $r_U$ to be a braiding operator on $U(X)$ (\eqref{braiding4}, \eqref{braiding5}, \eqref{braiding6}) are satisfied. Moreover, $\big(U(X),r_U\big)$ is a solution to the Yang--Baxter equation. 
\para 

It remains to prove that $r_U$ induces a braiding operator $r_G: G(X, r) \times G(X, r) \to G(X, r) \times G(X, r)$. We first consider the reduction with respect to the relations 
$$
g u u' h \sim  g h \quad \textrm{and} \quad g u' u h \sim  g h
$$
 in $U(X)$. Note that, if $r(u, v) = (y, x)$, then it is easy to see that 
$$
r_U \big((u, u'), y \big) = \big(y, (x, x') \big).
$$
Further,  $r_U(g u u' h, k)$  is obtained from $r_U(g h, k)$ by inserting some $x x'$ at appropriate places. Similarly, $r_U(g,  h u u' k)$, $r_U(g u' u h, k)$ and $r_U(g,  h u' u  k)$  are obtained from $r_U(g,  h k)$ and/or $r_U(g h, k)$ by inserting some $x x'$ and/or $x' x$ at appropriate places. This implies that $r_U$ is consistent with the relations
$$
g u u' h \sim  g h \quad \textrm{and} \quad g u' u h \sim  g h.
$$
\para 
Next, we consider the reduction with respect to the relation $g u v h \sim  g y x h$  whenever
$r(u, v) = (y, x)$. We first consider the simplest case. Suppose that $u, v, w \in X$, 
$ r(u, v) = (y, x)$,
$$
r_U \big((u, v), w \big) = (p_1, s_1, t_1) \quad \textrm{and} \quad r_U \big((y, x), w \big) = (p_2, s_2, t_2).
$$
Since $\big(U(X), r_U\big)$ is a solution to the Yang--Baxter equation, we conclude that $p_1 = p_2$ and $r(s_1, t_1) = (s_2, t_2)$.  Moreover, since $(\bar{X}, \bar{r})$ is a solution to the Yang--Baxter equation, the argument above also applies to the case when some of $u, v, w$ are in $X'$. We can show that $r_U(g y x h, k)$ is obtained from $r_U(g u v h, k)$ by applying $r$ at an appropriate adjacent
pair of coordinates. Similar statements can be proved regarding $r_U(g, h u v k)$ and $r_U(g, h y x k)$. This implies that $r_U$ is consistent with the relation  $g u v h \sim g y x h$. Hence, we have shown that $r_U$ can be reduced to an operator $r_G: G(X, r) \times G(X, r) \to G(X, r) \times G(X, r)$. Since $r_U$ satisfies the conditions \eqref{braiding4}, \eqref{braiding5} and \eqref{braiding6}, it follows that $r_G$ also satisfies the same conditions. 
\para 
To conclude that $r_G$ is a braiding operator on $G(X, r)$, it remains to show that $r_G$ satisfies the compatibility condition \eqref{braiding7}. By definition, the element $(g,h) \in  U(X) \times U(X)$ and $r_U (g, h)$ differ by successive applications of $r$ on some adjacent pairs of coordinates in the words (that is, ignoring the parentheses). Such applications of $r$ are considered as identity in $G(X, r)$. Thus, we conclude that $g h \in  G(X, r)$ is equal to the multiplication of the two coordinates in $r_G(g, h)$. This completes the construction of $r_G$. The uniqueness follows from the conditions  \eqref{braiding4}, \eqref{braiding5} and \eqref{braiding6}. Finally, the universal property is also obvious from the construction.
$\blacksquare$
\end{proof}

\begin{remark}{\rm 
It follows from Theorem \ref{univ property non-deg solution st group} that a solution $(X, r)$ to the Yang--Baxter equation is embedded in a group with a braiding operator if and only if the canonical map $i_X : X \to G(X,r)$ is an embedding. However, the canonical map is not always an embedding. In fact, we shall see in Part-II that solutions of quandle type do not always embed into their structure groups.}
\end{remark}

\begin{remark}\label{injectivity of eta remark}
{\rm 
In Theorem \ref{univ property non-deg solution st group}, if  we take $(X,r)$ to be a non-degenerate involutive solution, then it follows from the construction of $r_G$ that $\big(G(X, r), r_G\big)$ is also involutive. Further, by Proposition \ref{commutative star product}, the product $\star$ on $G(X,r)$ is commutative. Then it is not difficult to show that $\big(G(X,r),\star\big)$ is in fact a free abelian group with $X$ as a basis. This implies that the map $i_X$ is an embedding, recovering the classification theorem in \cite{MR1722951}.}
\end{remark}
\bigskip
\bigskip

