\section{Indecomposable solutions}
To gain insight into the structure of solutions to the Yang--Baxter equation, we consider their invariant subsets.

\begin{definition}
Let $(X, r)$ be a solution to the Yang--Baxter equation. A subset $Y$ of $X$ is called \index{invariant subset}{invariant} if $r(Y\times Y) \subseteq Y \times Y$. Further, an invariant subset $Y$ of $X$ is said to be \index{non-degenerate invariant subset}{\it non-degenerate} if $(Y,~ r|_{Y \times Y})$ is a non-degenerate solution.
\end{definition}

The preceding definition leads to the following.

\begin{definition}
A solution $(X, r)$ to the Yang--Baxter equation is said to be \index{decomposable solution}{\it decomposable} if it is a union of two non-empty disjoint invariant subsets. Otherwise, $(X, r)$ is said to be \index{indecomposable solution}{\it indecomposable}.
\end{definition}

For example, a permutation solution to the Yang--Baxter equation is indecomposable if and only if it is cyclic.

\begin{remark}{\rm 
If $(X, r)$ is a finite non-degenerate involutive solution, then for an invariant subset $Y$ of $X$, the solution $(Y,~ r|_{Y \times Y})$ is also finite non-degenerate involutive. Indeed, since $r^2= \id_{X \times X}$, the map $r|_{Y\times Y}$ is bijective. Further, for each $y\in Y$, the maps $\sigma_y,\tau_y:Y \to Y$ are injective (by non-degeneracy of $X$), and hence bijective since $X$ is finite. Thus, $(Y,~ r|_{Y \times Y})$ is non-degenerate and involutive.}
\end{remark}

The next result gives a characterisation of indecomposability of a non-degenerate involutive solution \cite[Proposition 2.12]{MR1722951}.

\begin{proposition} \label{indecomposable vs transitivity}
A non-degenerate involutive solution $(X, r)$ is indecomposable if and only if $G(X, r)$ acts transitively on $X$.
\end{proposition} 

\begin{proof} 
Let $(X, r)$ be a non-degenerate involutive solution. We first claim that if $(X, r)$ is a union of two non-degenerate invariant subsets $X_1$ and $X_2$, then $r$ defines bijections $X_1 \times X_2 \to X_2 \times X_1$ and $X_2 \times X_1 \to  X_1 \times X_2$. Since $X_1$ and $X_2$ are invariant subsets, it follows that $r$ is a permutation of the set $X_1 \times X_2 \cup X_2 \times X_1$. Suppose that for $x_1 \in X_1$ and $x_2 \in X_2$, we have $r(x_1, x_2) = (y_1, y_2)$, where $y_1 \in X_1$ and $y_2 \in X_2$. Thus, $\sigma_{x_1}(x_2) = y_1$. By non-degeneracy of $X_1$, there exists $z_1 \in X_1$ such that $\sigma_{x_1}(z_1) = y_1$. But, this contradicts the non-degeneracy of $(X,r)$. Hence, our claim holds. 
\para 
It follows from the claim  that if $G(X, r)$ acts transitively on $X$, then $(X, r)$ is indecomposable. Conversely, if the action $x \mapsto \tau_x^{-1}$  is not transitive, then there exist two non-empty $G(X,r)$-invariant subsets $X_1$ and $X_2$ of $X$. Since the sets are invariant under each $\tau_x$, they are invariant under $T$, where $T(y) =  \tau_y^{-1}(y)$. Thus, by Proposition \ref{p123}(b), they are invariant under each $\sigma_x$. Hence, $X_1$ and $X_2$ are invariant subsets of $X$, which are clearly non-degenerate. This shows that  $(X, r)$ is decomposable.  $\blacksquare$ 
\end{proof}


Recall that, if a group $G$ acts on a set $X$ and $x\in X$, then the subgroup $\{g \in G \, \mid \, g\cdot x=x \}$ of $G$ is called the \index{stabilizer} \textit{stabilizer} of $x$ in $G$.  The next result  classifies finite indecomposable non-degenerate involutive solutions on a  set with $p$ elements, where $p$ is a prime \cite[Theorem 2.13]{MR1722951}.

\begin{theorem}
 Let $(X, r)$ be an indecomposable non-degenerate involutive solution  such that $|X| = p$, where $p$ is a prime. Then $(X, r)$ is isomorphic to the cyclic permutation solution $(\mathbb{Z}_p, r_0)$, where $r_0(x, y) = (y - 1,~ x + 1)$.
\end{theorem} 

\begin{proof}
Recall from Remark \ref{the g0 group} that $G^0(X, r)=G(X, r)/\Gamma$ and $A=\mathbb{Z}^X/\Gamma$, where $\Gamma$ is the kernel of the action of $G(X, r)$ on $X$. Then, by Proposition \ref{indecomposable vs transitivity},  the group $G^0(X, r)$ acts transitively on $X$ and its order is divisible by $p$. By Remark \ref{the g0 group}, $G^0(X, r)$ can be identified as a subgroup of $\Sigma_X$, and hence its order divides $p!$. This gives $|A|=|G^0(X,r)| = pn$, where $n$ is coprime to $p$, and  hence $A \cong \mathbb{Z}_ p  \oplus A_0$, where $|A_0|$ is coprime to $p$. Since $A_0$ is the group of all elements of $A$ whose order is not divisible by $p$, it follows that $A_0$ is invariant under the action of $G^0(X,r)$. The group 1-cocycle $\pi:G(X, r) \to \mathbb{Z}^X$ of Proposition \ref{p130} induces a group 1-cocycle $\bar{\pi} \colon G^0(X,r) \to A$. This further defines a group 1-cocycle $\pi' \colon G^0(X,r) \to  \mathbb{Z}_ p$. Set $H = (\pi')^{-1}(0) = \bar{\pi}^{-1}(A_0)$. It is easy to see that $H$ is a subgroup of $G^0(X, r)$ of order $n$. For an element $x \in  X$, let  $H_x$ be the stabilizer of $x$ in $G^0(X,r)$. Then $H_x$ is a subgroup of $G^0(X, r)$ of order $n$ and index $p$. 
\para 
We claim that  $H_x = H$ for all $x \in X$. Since $|H_x| = |H|$,  it is enough to show that $\pi'(H_x) = 0$. Let $\bar{t}_x \in  A / A_0$ be the image of the element $t_x \in \mathbb{Z}^X$. Then the set $\{ \bar{t}_x~\mid ~x \in X \}$ generates $A / A_0$ and each $\bar{t}_x$ is by definition fixed by $H_x$. Thus, $H_x$ acts trivially on $A/A_0=\mathbb{Z}_ p$. This implies that $\pi' |_{H_x}:H_x \to  \mathbb{Z}_ p$ is a group homomorphism. Since $|H_x| = n$ is coprime to $p$, this implies that $\pi'(H_x) =0$. It remains to prove that the image $\bar{t}_x \in  A / A_0$ of $t_x \in \mathbb{Z}^X$  is non-zero. Suppose  that $\bar{t}_x = 0$. Since $G(X,r)$ acts transitively on $X$, we get $\bar{t}_y = 0$ for all $y \in X$. This implies that the natural map $\mathbb{Z}^X \to  A / A_0$ is zero, which is a contradiction. Hence, $\bar{t}_x \neq 0$ for each $x \in X$ and the claim follows. It follows that $H$ acts trivially on $X$. This implies that $H=1$, and  hence $A_0 = 1$. Thus, $G^0(X,r) \cong A \cong  \mathbb{Z}_ p$, the action of $G^0(X,r)$ on $A$ is trivial and $\bar{\pi} = \id$.
\para
To conclude the proof, it is enough to observe that $\bar{t}_x = \bar{t}_y$ for any $x, y \in  X$. This follows from the fact that there exists $g \in  G^0(X,r)$ such that  $g \cdot x = y$, while the action of $G^0(X,r)$ on $A$ is trivial. Thus, $\bar{t}_x$ does not depend on $x$, and hence $\bar{\pi}^{-1} (\bar{t}_x) \in  G^0(X,r)$ does not depend on $X$. This proves that $(X, r)$ is a permutation solution.  $\blacksquare$
\end{proof}
\para

Let $(X, r_X)$ and $(Y, r_Y)$ be non-degenerate involutive solutions. Let $\Ext(X, Y)$ denote the set of all decomposable solutions $(Z, r)$ which are unions of $X$ and $Y$. We refer to elements of $\Ext(X, Y)$ as \index{extension of solutions}{\it extensions} of $X$ by $Y$. An element $(Z, r) \in \Ext(X, Y)$  is completely determined by the map
$$
r : X \times Y \to Y \times X.
$$
Let us write $r(x, y) = \big(\sigma_x(y), \tau_y(x)\big)$. Since $G(X, r_X)$ and $G(Y, r_Y)$ are subgroups of $G(Z, r)$, the following result is immediate  \cite[Proposition 2.17]{MR1722951}.
\para

\begin{proposition} 
If $(Z, r) \in \Ext(X, Y)$, then the assignments 
$$
x  \mapsto \sigma_x \quad \textrm{and} \quad  y  \mapsto \tau_y^{-1}
$$
are left-actions of  $(G, r_X)$ on $Y$ and of $G(Y, r_Y)$ on $X$, respectively.
\end{proposition} 
\para

\begin{definition}
An element $(Z, r) \in \Ext(X, Y)$ is called a \index{right-extension of solutions}{right-extension} of $X$ by $Y$ if $r(x, y) = \big(y, \tau_y(x)\big)$ for $x \in X$ and $y \in Y$. Similarly, $(Z, r)$ is called a \index{left-extension of solutions}{left-extension} of $X$ by $Y$ if $r(x, y) = \big(\sigma_x(y), x\big)$ for $x \in X$ and $y \in Y$.  The set of right- and left-extensions of $X$ by $Y$ will be denoted by $\Ext_+(X, Y)$ and $\Ext_-(X, Y)$, respectively.
\end{definition}
\para

It is clear that $\Ext_+(X, Y) =\Ext_-(Y, X)$. The following result gives a group-theoretic description of $\Ext_+(X, Y)$ \cite[Proposition 2.18]{MR1722951}.  
\para

\begin{proposition}
Let $Z= X \cup Y$ and $r: Z \times Z \to Z \times Z$ be such that $r(x, y) = \big(y, \tau_y(x)\big)$ for $x \in X$ and $ y \in Y$. Then, $(Z, r) \in \Ext_+(X, Y)$ if and only if  the assignment 
$$
y  \mapsto \tau_y^{-1}
$$
defines a left-action of  $G(Y, r_Y)$ on $X$.
\end{proposition}

\begin{proof} We have
$$
r_{12} r_{23} r_{12} (x_1, x_2, y) = \big(y, ~\tau_y \sigma_{x_1}(x_2),  ~ \tau_y  \tau_{x_2}(x_1) \big)
$$
and
$$
r_{23} r_{12} r_{23} (x_1, x_2, y) = \big(y, ~\sigma_{\tau_y(x_1)} \tau_{y}(x_2),  ~ \tau_{\tau_y(x_2)} \tau_y(x_1) \big)
$$
for $x_1, x_2 \in X$ and $y \in Y$. Equating the preceding equations shows that $\tau_y$ preserves $X$.
$\blacksquare$ 
\end{proof}
\para
\begin{corollary}
If $(Z,r) \in \Ext_+(X, Y)$,  then $$G(Z, r) \cong G(Y, r_Y) \ltimes G(X, r_X),$$ where $G(Y, r_Y)$-action on $G(X, r_X)$ is induced by the $G(Y, r_Y)$-action on $X$ via $y \mapsto \tau_y^{-1}$.
\end{corollary}
\para

We conclude this section with the following result \cite[Proposition 2.20]{MR1722951}.

\begin{proposition}  
Let $Z= X \cup Y$. Then the map $r(x, y) = \big(\sigma_x(y), \tau_y(x)\big)$ defines an element $(Z,r) \in \Ext(X, Y)$ if and only if the following conditions are simultaneously satisfied:
\begin{enumerate}
\item The assignments $x \mapsto\sigma_x$ and $y \mapsto \tau_y^{-1}$ are left-actions of $G(X, r_X)$ on $Y$ and of $G(Y, r_Y)$ on $X$.
\item The homomorphisms 
$$
\rho_X : G(X, r_X) \to \Sigma_Y \quad \textrm{and} \quad \rho_Y : G(Y, r_Y) \to \Sigma_X
$$
defined by assertion (1) are invariant under  $G(Y, r_Y)$ and $G(X, r_X)$, respectively. Here, the actions of  $G(X, r_X)$ on $\Sigma_X$ and  $G(Y, r_Y)$ on  $\Sigma_Y$ are trivial, and the actions of $G(X, r_X)$ and  $G(Y, r_Y)$ on each other are by $\rho_X$ and $\rho_Y$, respectively.
\end{enumerate}
\end{proposition} 
\bigskip 
