\section{Linear  and affine  solutions on abelian groups}
In this section, we study non-degenerate solutions to the Yang--Baxter equation on abelian groups arising from their (affine) linear transformations
\para

We begin with the following definition.

\begin{definition}
Let $G$ be an abelian group. A solution $(G, r)$ to the Yang--Baxter equation is called a \index{linear solution}{\it linear solution} if $r$ has the form
\begin{equation} \label{linear solution expression}
r(x,y) = \big(ax + by,~ cx + dy \big)
\end{equation}
for some $a, b, c, d \in \End(G)$, where $\End(G)$ is the endomorphism ring of $G$.
\end{definition}

\begin{proposition}\label{nec suff condition for non-deg linear sol}
Let $G$ be an abelian group and $r : G \times G \to G \times G$ a map of the form \eqref{linear solution expression}. Then $(G, r)$ is a non-degenerate linear solution to the Yang--Baxter equation if and only if the following  conditions hold:
\begin{equation}\label{liner solution non-degen}
b, c \in \Aut(X),
\end{equation}
\begin{equation} \label{leq1}
a(1-a) = bac, \quad  d(1-d) = cdb,
\end{equation}
\begin{equation} \label{leq2}
ab = ba(1-d), \quad  ca = (1-d)ac, \quad  dc = cd(1-a),
\end{equation}
\begin{equation} \label{leq3}
bd = (1-a) db, \quad cb - bc = ada - dad.
\end{equation}
\end{proposition}

\begin{proof}
The proof follows immediately by evaluating $r_{12}r_{23} r_{12}(x, y, z)$ and $r_{23}r_{12} r_{23}(x, y, z)$, and using the condition of non-degeneracy. $\blacksquare$
\end{proof}

The following result determines non-degenerate linear solutions on abelian groups \cite[Lemma 8]{MR1809284}.

\begin{proposition} 
Let $G$ be an abelian group. Then non-degenerate linear solutions $(G, r)$ are in bijective correspondence with the quadruples $(a, b, d, s) \in \End(G)^4$ such that the following conditions hold:
\begin{enumerate}
\item $1-a$, $1-d$, $b$ and $1+s$ are invertible,
\item $s$ commutes with $a,b,d$ and $sa = sd = 0$,
\item $bdb^{-1} = (1-a)d$ and $b^{-1}ab = a(1-d)$. 
\end{enumerate}
In fact,  the bijective correspondence is given by $(a, b,c, d) \mapsto (a, b, d, s)$, where
\begin{equation}\label{linear and affine relation eq}
s=bc -(1-d+ad)(1-a).
\end{equation}
\end{proposition}

\begin{proof}
Let $(G, r)$ be a non-degenerate linear solution to the Yang--Baxter equation with
$$
r(x,y) = \big(ax + by,~ cx + dy \big).
$$
By Proposition \ref{nec suff condition for non-deg linear sol}, the quadruple $(a, b, c, d) \in \End(G)^4$ satisfies \eqref{liner solution non-degen}-\eqref{leq3}. The first equation of \eqref{leq3} implies that
$$
b d b^{-1}= (1-a) d,
$$
which further gives 
\begin{equation} \label{leq6a}
b (1 - d) b^{-1}= 1- d + a d.
\end{equation}
Multiplying the first equation of  \eqref{leq2} by $b^{-1}$ on the right gives $a = b a b^{-1} b (1 - d) b^{-1}$. Using \eqref{leq6a}, this further gives
\begin{equation} \label{leq6}
a=b a b^{-1} (1-d + ad).
\end{equation}
Similarly, using the second and the third equation of \eqref{leq2}, we obtain
\begin{equation} \label{leq7}
c a c^{-1}  = (1-d)a \quad \textrm{and} \quad c d c^{-1}  (1 - a + da) = d.
\end{equation}

Let $s$ be the endomorphism of $G$ defined by \eqref{linear and affine relation eq}. We claim that $s a = s d = 0$. Indeed, multiplying \eqref{linear and affine relation eq} by $a$ on the right and using the first relation of \eqref{leq1} and the second relation of \eqref{leq2}, we obtain
\begin{equation} \label{leq7a}
s a = b c a - (1 - d + ad) (1 - a) a = b (1 - d) a c - (1 - d + ad) b a c. 
\end{equation}
By \eqref{leq6a}, we have $b (1 - d) = (1 - d + a d)b$,  and using it in \eqref{leq7a} gives $sa=0$.
Similarly, we can show that $as = 0$.  The last equation of \eqref{leq3} implies that
\begin{equation} \label{leq8}
c b  =   (1 - a + da) (1 -  d) + s.
\end{equation}
Multiplying the preceding equation  by $d$  gives $sd = ds = 0$. We claim that the endomorphsims $1 - a$, $1 + s$ and $1 - d$ are invertible. Indeed, $b$ and $c$ are invertible by \eqref{liner solution non-degen}. Since
$$
b c = (1 -d + s + a d) (1 - a) = (1 - a) (1 -d + s +d a),
$$
$$
b c = (1 -d + a d) (1 - a + s) = (1 - a + s) (1 -d +  a d),
$$
$$
c b = (1 - a + s +  d a) (1 - d) = (1 - d) (1 - a + s + a d),
$$
we deduce that $1 - a$, $1 - a + s$ and $1 - d$  invertible. Considering the relation $1 - a + s = (1 - a) (1 + s)$,  it follows that $1 + s$ is also invertible. Our final claim is that $s$ commutes with $b$. We conjugate the equation \eqref{linear and affine relation eq} by $c$ and use equations \eqref{leq7} to conclude that
\begin{equation} \label{leq9}
c b  =   (1 - a + da) (1 -  d) + c s c^{-1}.
\end{equation}
Comparing \eqref{leq8} with \eqref{leq9} gives  $sc = c s$. Now, the equation \eqref{linear and affine relation eq}) implies that $s$ commutes with $b$ as well. Hence, starting with the quadruple $(a, b, c, d) \in \End(G)^4$ satisfying \eqref{liner solution non-degen}-\eqref{leq3}, we have constructed the quadruple $(a, b, d, s) \in \End(G)^4$ satisfying conditions (1)-(3) of the proposition.
\para 
Conversely, suppose that $(a, b, d, s) \in \End(G)^4$ satisfies conditions (1)-(3). Define $c$ by the formula 
$$c=b^{-1} \big(s+ (1-d+ad)(1-a) \big).$$
It is not difficult to check that the quadruple $(a, b, c, d) \in \End(G)^4$ satisfies the relations \eqref{liner solution non-degen}-\eqref{leq3}, which is desired. $\blacksquare$
\end{proof}

We can generalize linear solutions to affine solutions.

\begin{definition}
Let $G$ be an abelian group. A solution $(G, r)$ to the Yang--Baxter equation is called an \index{affine solution}{\it affine solution} if $r$ has the form
\begin{equation} \label{aff}
r(x,y) = \big(ax + by+z,~ cx + dy+t \big)
\end{equation}
for some $a, b, c, d \in \End(G)$ and $t, z \in G$.
\end{definition}

As in the linear case, the following result holds for affine solutions.

\begin{proposition}\label{prop affine solution condition}
Let $G$ be an abelian group and $r : G \times G \to G \times G$ a map of the form \eqref{aff}. Then $(G, r)$ is an affine solution to the Yang--Baxter equation  if and only if the conditions \eqref{liner solution non-degen}-\eqref{leq3} and 
\begin{equation} \label{affine solution condition}
cdz+dt = 0,\quad az+bat=0 \quad \textrm{and}\quad (c+d-ad-1)z + (da+1-a-b)t=0
\end{equation}
hold.
\end{proposition}

It follows from Proposition \ref{prop affine solution condition} that an affine solution $(G, r)$ gives rise to a linear solution $(G, r^*)$ with $r^*(x, y) = (ax + by, cx + dy)$. We refer to  $(G, r^*)$ as the linear part of the affine solution $(G, r)$. Similarly, we refer to $(G, r)$ as the affine solution associated with the linear solution $(G, r^*)$. We conclude with the following result \cite[Theorem 3.3 (1)]{MR1809284}.

\begin{proposition} 
Let $G$ be an abelian group and $(G, r^*)$ a non-degenerate linear solution with $r^*(x, y) = (ax + by, cx + dy)$. Then, $(G, r)$ given by 
$$
r(x, y)=\big(ax + by+z, \, cx + dy+t \big),
$$
where $a, b, c, d \in \End(G)$ and $z, t \in G$, is an affine solution associated with $(G, r^*)$ if and only if 
$$
ak = dk = 0 \quad \textrm{and}\quad (b-1)k = sz,
$$
where $s=bc -(1-d+ad)(1-a)$ and $k=c(1-a)^{-1}z +t $.
\end{proposition}

\begin{proof}
It follows from the first equation of \eqref{leq1} and the third equation of \eqref{leq2} that
$$
c d z + d t = d \big(c(1-a)^{-1} z + t \big) \quad \textrm{and} \quad az + bat = a \big(z + (1-a) c^{-1} t \big).
$$
Hence, we can rewrite the first two  equations of \eqref{affine solution condition} as
$$
d \big(c (1 - a)^{-1} z + t \big) = 0 \quad \textrm{and} \quad a \big(z +  (1 - a) c^{-1} t \big) = 0.
$$
If we define
\begin{equation} \label{leg13}
k=c (1 - a)^{-1} z +t,
\end{equation}
then it follows from \eqref{leq1} that $a k = d k = 0$. Now, \eqref{leq7} implies that
$$
c (1 - a)^{-1} c^{-1} = (1 - a + d a)^{-1},
$$
and we can modify \eqref{leg13} into
$$
(1 - a + d a) t = - c z + (1 - a + d a) k = - c z + k.
$$
We rewrite the last equation of  \eqref{affine solution condition} as 
\begin{equation} \label{leg14}
 (d - a d - 1) z - b t  + k = 0.
\end{equation}
If we substitute $t$ from \eqref{leg13} into \eqref{leg14} and use \eqref{linear and affine relation eq}, we obtain
$$
(b - 1) k = s z,
$$
which is the last desired equation. $\blacksquare$
\end{proof}
