We conclude this section by briefly explaining the idea of Kurosh \cite[Section 10]{MR0080089}, which led to the concept of a brace. Let $(\mathbb{k}, +, \cdot)$ be an associative ring not necessarily with unity. Define an adjoint multiplication in $(\mathbb{k}, +, \cdot)$ by
$$
a \circ b = a + b - a \cdot b.
$$
Let $0$ be the zero element of the ring $(\mathbb{k}, +, \cdot)$. Since $ a \circ 0 = a= 0 \circ a,$ the element $0$ is the identity element with respect to the adjoint multiplication. Further, we see that
\begin{eqnarray*}
(a \circ b) \circ c 
&=& (a+b-a \cdot b) + c - (a + b - a \cdot b) \cdot c\\
&=& a + b + c -a \cdot b -a \cdot c-b \cdot c+(a \cdot b) \cdot c \\
&=& a+(b+c-b \cdot c)-a \cdot (b+c-b \cdot c)\\
&=& a \circ (b \circ c),
 \end{eqnarray*}
and hence the adjoint multiplication is associative. Thus, $(\mathbb{k}, \circ)$ is a semigroup with the identity element,  called the \index{adjoint semigroup of a ring}{\it adjoint semigroup} of the ring $(\mathbb{k}, +, \cdot)$.  The group of all invertible elements of $(\mathbb{k}, \circ)$ is called the \index{adjoint group of a ring}{\it adjoint group} of $(\mathbb{k}, +, \cdot)$. An associative ring $(\mathbb{k}, +, \cdot)$ is called a \index{radical ring}{\it radical ring} if $(\mathbb{k}, \circ)$ is a group. A ring is called \index{nilpotent ring}{\it nilpotent} if the product of arbitrary $n$ elements is zero for some positive integer $n$. 

\begin{proposition}
Every nilpotent ring is a radical ring.
\end{proposition}
\begin{proof}
Let $\mathbb{k}$ be a nilpotent ring and $a \in \mathbb{k}$ an arbitrary element. Consider the element
$$
x  = -a - a^2 - a^3 - \cdots,
$$
where $a^k= a \cdot a \cdot \cdots \cdot a$ ($k$-times). Since $\mathbb{k}$ is nilpotent, the element $x$ has only finitely many terms and 
$$
a \circ x =  a + x - a \cdot x = a+ (-a - a^2 - a^3 -\cdots )- (-a^2 - a^3 - a^4 -\cdots)=0.
$$
This shows that $x$ is the inverse of $a$ with respect to $\circ$, and hence  $\mathbb{k}$ is a radical ring. $\blacksquare$
\end{proof}


\begin{proposition}
If $(\mathbb{k}, +, \cdot)$ is a radical ring, then  $(\mathbb{k}, +, \circ)$ is a two-sided brace. Conversely, if $(\mathbb{k}, +, \circ)$ is a two-sided brace, then $(\mathbb{k}, +, \cdot)$ is a radical ring, where $a \cdot b= a +b - a \circ b$.
\end{proposition} 

\begin{proof}
If $(\mathbb{k}, +, \cdot)$ is a radical ring, then both $(\mathbb{k}, +)$ and $(\mathbb{k},\circ)$ are groups. Further, we have
$$ (a + b) \circ c = a \circ c + b \circ c - c \quad \textrm{and} \quad  c \circ (a + b) = c \circ a + c \circ b - c$$
for all $a, b, c \in \mathbb{k}$, and hence $(\mathbb{k}, +, \circ)$ is a two-sided brace.  
\para

Conversely, if $(\mathbb{k}, +, \circ)$ is a two-sided brace, then taking $a \cdot b= a +b - a \circ b$, a direct check shows that
$$(a+b) \cdot c= a \cdot c + b \cdot c, \quad  c \cdot (a + b)=  c \cdot a +  c \cdot b \quad \textrm{and} \quad  (a \cdot b) \cdot c= a \cdot (b \cdot c)$$
for all $a, b, c \in \mathbb{k}$. Hence,  $(\mathbb{k}, +, \cdot)$ is a radical ring. $\blacksquare$
\end{proof}
