\section{Properties and constructions of skew braces}
This section delves into the characteristics of skew  left braces, some of their constructions and maps linked to them.

\subsection{Maps associated to skew braces}

Let $(G, \cdot, \circ)$ be a skew left brace. For each $a \in G$, define $\lambda_a : G \to G$ by 
$$\lambda_a (b) = a^{-1 } \cdot (a \circ b)$$
for all $b \in G$. A direct check shows that each $\lambda_a$ is a bijection, with its inverse given by 
\begin{equation}\label{def lambda map}
\lambda_a^{-1} (b) = \bar{a} \circ(a \cdot b)
\end{equation}
for all $b \in G$.  This leads to the map $\lambda: G \to \Sigma_G$ given by $\lambda(a)= \lambda_a$. Equation \ref{def lambda map} allows us to write the two group operations in $(G, \cdot, \circ)$ in terms of each other, that is,
\begin{equation}\label{circ and dot by lambda}
a \circ b = a \cdot \lambda_a (b) \quad \textrm{and}\quad a \cdot b = a \circ \lambda_a^{-1} (b)    
\end{equation}
for $a, b \in G$.
\para

The following result characterises a skew left brace in terms of the map $\lambda$ \cite[Proposition 1.9]{MR3647970}.

\begin{proposition} \label{lambda-map}
Let $G$ be a set with two binary operations $\cdot$ and $\circ$ such that both $(G, \cdot)$ and $(G, \circ)$ are groups. Let $\lambda : G \to \Sigma_G$ be the map given by $\lambda(a) =  \lambda_a$, where $\lambda_a(b) =  a^{-1} \cdot (a \circ b)$ for $a, b \in G$. Then the following assertions are equivalent:
\begin{enumerate}
\item $(G, \cdot, \circ)$ is a skew left brace.
\item $\lambda_{a\circ b}(c) =\lambda_a \lambda_b(c)$ for all $a, b, c \in G$.
\item $\lambda_{a} (b  \cdot c) =\lambda_a (b) \cdot \lambda_a (c)$ for all $a, b, c \in G$.
\end{enumerate}
\end{proposition}

\begin{proof}
Let $(G, \cdot, \circ)$ be a skew left brace and $a, b, c \in G$. By Lemma \ref{idbr}(2), we have
$$
a \circ b^{-1} = a \cdot(a \circ b)^{-1}  \cdot a.
$$
This gives 
\begin{eqnarray*}
\lambda_a \lambda_b(c) 
&=& a^{-1}\cdot \big(a \circ \lambda_b(c) \big)\\
&=& a^{-1}  \cdot \big(a \circ (b^{-1} \cdot (b \circ c)) \big) \\
&=& a^{-1}\cdot  (a \circ b^{-1})\cdot  a^{-1} \cdot (a \circ b \circ c)\\
&=& (a \circ b)^{-1} \cdot (a \circ b \circ c)\\
&=& \lambda_{a\circ b}(c),
\end{eqnarray*}
which establishes the implication (1) $\Rightarrow$ (2).
\para 

Suppose that assertion (2) holds. Using the identity $ a \cdot b = a \circ \lambda_a^{-1} (b)$, we get
\begin{eqnarray*}
\lambda_{a} (b\cdot c) &=&  \lambda_{a} \big(b \circ \lambda_{b}^{-1} (c)\big) \\
&=&  a^{-1} \cdot \big(a \circ b  \circ \lambda_b^{-1}(c)\big) \\
&=&  a^{-1} \cdot (a \circ b)  \cdot (a \circ b)^{-1} \cdot \big(a \circ b \circ \lambda_b^{-1}(c)\big) \\
&=&  \lambda_a(b) \cdot \lambda_{a \circ b} \lambda_b^{-1}(c) \\
&=&  \lambda_a(b) \cdot \lambda_a \lambda_b \lambda_b^{-1}(c)\\
&=&  \lambda_a (b) \cdot \lambda_a (c),
\end{eqnarray*}
which proves the implication (2) $\Rightarrow$ (3).
\para 

Suppose that assertion (3) holds. Then, for $a, b, c \in G$, we have
$$
a^{-1} \cdot \big(a \circ (b \cdot c)\big) =  \lambda_a(b \cdot c)  =  \lambda_a(b) \cdot \lambda_a(c) = a^{-1} \cdot (a \circ b) \cdot a^{-1} \cdot (a \circ c),
$$
which proves the implication (3) $\Rightarrow$ (1). $\blacksquare$ 
\end{proof}

As a consequence, we have the following result.

\begin{corollary}
Let $(G, \cdot, \circ)$ be a skew left brace. Then  the map
$$
\lambda : (G, \circ) \to \Aut(G, \cdot)
$$
given by $a \mapsto \lambda_a$ is a group homomorphism.
\end{corollary}

Let $(G, \cdot, \circ)$ be a skew left brace. Then,  for each $b \in G$, define a map $\gamma_b : G \to G$  by 
$$\gamma_b(a) = \lambda^{-1}_{\lambda_a(b)} \left( (a \circ b)^{-1} \cdot a \cdot (a \circ b)\right)$$
for $a \in G$. These maps satisfy some interesting properties \cite[Lemma 2.4]{MR3835326}.

\begin{proposition}\label{gamma-map}
Let $(G, \cdot, \circ)$ be a skew left brace. Then, for any $a, b \in G$, the following  assertions hold:
\begin{enumerate}
\item $\gamma_b(a) = \big(\bar{b} \circ (\bar{a} \cdot b) \big)^{\circ(-1)} = \big((\bar{b} \circ \bar{a} ) \cdot (\bar{b})^{-1} \big)^{\circ(-1)}.
$
\item $\gamma_b$ is a bijection with $\gamma_{\bar{b}}$ as its inverse.
\item $\gamma_a \gamma_b = \gamma_{b \circ a}$.
\end{enumerate}
\end{proposition}

\begin{proof}
For $a, b \in G$, we have
$$
\lambda^{-1}_{\lambda_a(b)} \left( \lambda_a(b)^{-1} \cdot a \cdot \lambda_a(b) \right) = \lambda^{-1}_{\lambda_a(b)} \left( (a \circ b)^{-1} \cdot a \cdot a \cdot a^{-1} \cdot (a \circ b) \right) =\lambda^{-1}_{\lambda_a(b)} \left( (a \circ b)^{-1} \cdot a \cdot (a \circ b)\right) = \gamma_b(a).
$$
Writing $\gamma_b$ in terms of the operations of $G$, we see that
\begin{eqnarray*}
\gamma_b(a) &=& \lambda^{-1}_{\lambda_a(b)} \big( \lambda_a(b)^{-1} \cdot a \cdot \lambda_a(b) \big)\\
&=& \overline{\lambda_a(b)} \circ \big(\lambda_a(b) \cdot \lambda_a(b)^{-1} \cdot a \cdot \lambda_a(b) \big), \quad \textrm{using} ~\eqref{circ and dot by lambda}\\
&=& \overline{\lambda_a(b)} \circ \big(a \cdot \lambda_a(b)\big) \\
&=& \overline{\lambda_a(b)} \circ a \circ b \\
&=& \big(\bar{b} \circ \bar{a} \circ \lambda_a(b) \big)^{\circ(-1)}\\
&=& \big(\bar{b} \circ (\bar{a} \cdot b) \big)^{\circ(-1)},\quad \textrm{using}~ \eqref{circ and dot by lambda}\\
&=& \big((\bar{b} \circ \bar{a}) \cdot (\bar{b})^{-1} \big)^{\circ(-1)},\quad \textrm{using the defining condition of a skew left brace,}
\end{eqnarray*}
which proves assertion (1).
\para 

A direct check shows that $\gamma_b$ is invertible, with inverse given by
$$
a \mapsto \big(b \circ (\bar{a} \cdot \bar{b}) \big)^{\circ(-1)}, 
$$
which establishes assertion (2).
\para 

Now, we check that $\gamma: (G, \circ) \to \Sigma_G$  is an anti-homomorphism. For $a, b, c \in G$, we see that 
\begin{eqnarray*}
\gamma_{b \circ a}(c) &=& \big((\bar{a} \circ \bar{b} \circ \bar{c}) \cdot (\bar{a} \circ\bar{b})^{-1}\big)^{\circ(-1)}\\
&=& \big((\bar{a} \circ \bar{b} \circ \bar{c}) \cdot (\bar{a} \cdot \lambda_{\bar{a}}(\bar{b}))^{-1}\big)^{\circ(-1)}\\
&=&  \big((\bar{a} \circ \bar{b} \circ \bar{c}) \cdot \lambda_{\bar{a}}(\bar{b})^{-1} \cdot (\bar{a})^{-1}\big)^{\circ(-1)}\\
&=&  \big((\bar{a} \circ \bar{b} \circ \bar{c}) \cdot  \lambda_{\bar{a}}((\bar{b})^{-1}) \cdot (\bar{a})^{-1} \big)^{\circ(-1)} \\
&=& \big((\bar{a} \circ \bar{b} \circ \bar{c}) \cdot  (\bar{a})^{-1} \cdot  (\bar{a} \circ (\bar{b})^{-1}) \cdot (\bar{a})^{-1}\big)^{\circ(-1)}.
\end{eqnarray*}
On the other hand, we have
$$
\gamma_a \big(\gamma_b(c)\big) = \gamma_a\big(\big(\bar{b} \circ \bar{c}) \cdot (\bar{b})^{-1}\big)^{\circ(-1)}\big) = 
\big((\bar{a} \circ ((\bar{b} \circ \bar{c}) \cdot (\bar{b})^{-1})) \cdot (\bar{a})^{-1}\big)^{\circ(-1)} = 
\big((\bar{a} \circ \bar{b} \circ \bar{c})  \cdot (\bar{a})^{-1} \cdot (\bar{a} \circ (\bar{b})^{-1}) \cdot (\bar{a})^{-1}\big)^{\circ(-1)},
$$
which proves assertion (3). $\blacksquare$ 
\end{proof}


Given a skew left brace $(G, \cdot, \circ)$, we can define the semi-direct product $(G, \cdot) \rtimes (G, \circ)$ by the action $\lambda : (G, \circ) \to \Aut(G, \cdot)$. We have the following observation regarding this group \cite[Lemma 2.5]{MR3835326}.

\begin{proposition} \label{theta-map}
Let $(G, \cdot, \circ)$ be a skew left brace. Consider the map
$$
\theta : (G, \cdot) \rtimes (G, \circ) \to \Aut(G, \cdot)$$
given by $(a, b) \mapsto \theta_{(a, b)}$, where $\theta_{(a, b)}(c) = a \cdot \lambda_b(c) \cdot a^{-1}$ for $a, b, c \in G$. Then $\theta$ is a group homomorphism. 
\end{proposition}

\begin{proof}
Since $\theta_{(a, b)}$ is just the composition of $\lambda_b$ with the inner automorphism induced by $a$, it follows that $\theta_{(a, b)} \in \Aut(G, \cdot)$ for each $a, b \in G$. For $a_1, b_1, a_2, b_2, c \in G$, we have
\begin{eqnarray*}
\theta_{(a_1, b_1) (a_2, b_2)}(c) &=&  \theta_{(a_1 \cdot \lambda_{b_1}(a_2), \,b_1 \circ b_2)}(c)\\
&=& \big(a_1 \cdot \lambda_{b_1}(a_2) \big) \cdot \lambda_{b_1 \circ b_2}(c) \cdot  \big(a_1 \cdot \lambda_{b_1}(a_2)\big)^{-1}\\
&=& a_1 \cdot \lambda_{b_1}(a_2) \cdot \lambda_{b_1 \circ b_2}(c) \cdot \lambda_{b_1}(a_2)^{-1} \cdot a_1^{-1}\\
&=&  a_1 \cdot \lambda_{b_1} \big(a_2 \cdot \lambda_{b_2}(c) \cdot a_2^{-1} \big) \cdot a_1^{-1}\\
&=&  \theta_{(a_1, b_1)} \theta_{(a_2, b_2)}(c),
\end{eqnarray*}
and hence $\theta$ is a homomorphism. $\blacksquare$ 
\end{proof}


Recall from Definition \ref{def skew brace homomorphism kernal ideal} that, an ideal of a skew left brace $(G, \cdot, \circ)$ is a subset $I$ such that $(I, \cdot)$ is a~normal subgroup of  $(G, \cdot)$, $(I, \circ)$ is a normal subgroup of $(G, \circ)$ and $\lambda_a(b) \in I$ for any $a \in G$ and $b \in I$. Ideals of  skew left braces enjoy the following properties \cite[Lemma 2.3]{MR3647970}.

\begin{proposition} 
The following  assertions hold for an ideal~$I$ of a skew left brace $(G, \cdot, \circ)$:
\begin{enumerate}
\item  $a \circ I = a \cdot I$ for all $a \in G$.
\item  $I$ and $G/I$ are skew left braces.
\end{enumerate}
\end{proposition}

\begin{proof}
Assertion (1) is immediate from \eqref{circ and dot by lambda}. Clearly, $I$ is a skew left brace. By assertion (1),  the set of left cosets of $(I, \cdot)$ in $(G, \cdot)$ is the same as the set of left cosets of $(I, \circ)$ in $(G, \circ)$. Hence,  $G/I$ has the natural induced skew left brace structure. $\blacksquare$ 
\end{proof}
\para

\begin{definition}
The \index{socle}{socle} of a skew left brace $(G, \cdot, \circ)$ is defined as
$$
\Soc(G) = \{ a \in G \, \mid \,  \lambda_a = \id ~~ \textrm{and}~~ a \cdot b = b \cdot a~\mbox{for all}~ b \in G \} = \ker(\lambda) \cap \Z(G, \cdot).
$$
\end{definition}
\para

The following result gives some interesting properties of the socle of a skew left brace \cite[Proposition 2.8]{MR3835326}.

\begin{proposition} 
Let $(G, \cdot, \circ)$ be a skew left brace. Then the following  assertions hold:
\begin{enumerate}
\item $\Soc(G)$ is an ideal of $G$ contained in the center of $(G, \cdot)$. If $a \in G$ and $y \in \Soc(G)$, then $$\lambda_a(y) = a \circ y \circ \bar{a}.$$  Moreover, $\Soc(G)$ is a trivial brace, and consequently an abelian group.
\item $\Soc(G)$ coincides with the kernel of the homomorphism
$$
\varphi : (G, \circ) \to \Aut(G, \cdot) \times \Sigma_G
$$
given by
$$\varphi(a) = (\lambda_a, \gamma_a^{-1}).$$
\item $\Soc(G)$ coincides with the kernel of the homomorphism
$$
\Phi : (G, \circ) \to \Aut(G, \cdot) \times \Aut(G, \cdot)
$$
given by
$$\Phi(a) = (\lambda_a, h_a),$$
where $h_a(b) = a \cdot \lambda_a(b) \cdot a^{-1}$.
\end{enumerate}
\end{proposition}

\begin{proof}
For $x, y \in \Soc(G)$, we have 
$$
x \circ y = x \cdot \lambda_x(y) = x \cdot \id(y) = x \cdot y.
$$
Hence, the two group operations coincide on $\Soc(G)$. Let $x, y \in \Soc(G)$ and $a, b \in G$. We have $\lambda_{x \circ y} = \lambda_x \, \lambda_{y} = \id$ and
$$
a \cdot (x \circ y) \cdot a^{-1} = a \cdot x \cdot y \cdot a^{-1} = x \cdot y = x \circ y.
$$
This implies that $x \circ y \in \Soc(G)$. We also have $\lambda_{\bar{x}} = \lambda_{x}^{-1} = \id$ and
$$
a \cdot \bar{x} \cdot a^{-1} = a \cdot \lambda_{\bar{x}}(x)^{-1} \cdot a^{-1} = a \cdot x^{-1} \cdot a^{-1} = x^{-1} = \bar{x}.
$$
This shows that $\bar{x} \in \Soc(G)$, and hence $\Soc(G)$  is a subgroup of $(G, \circ)$. Moreover, we have
$$
\lambda_{b \circ x \circ \bar{b}} = \lambda_b \lambda_x \lambda_{\bar{b}} = \lambda_b \,  \id \, \lambda_{\bar{b}} = \id.
$$
Further, since
\begin{eqnarray*}
\bar{b} \circ \big(a \cdot  (b \circ x \circ \bar{b}) \cdot a^{-1} \big) &=& (\bar{b} \circ a) \cdot (\bar{b})^{-1} \cdot  (x \circ \bar{b})  \cdot (\bar{b})^{-1} \cdot (\bar{b} \circ a^{-1}) \\
&=& (\bar{b} \circ a) \cdot (\bar{b})^{-1} \cdot x \cdot (\bar{b} \cdot a^{-1}) \\
&=& x \cdot (\bar{b} \circ a) \cdot (\bar{b})^{-1} \cdot  (\bar{b} \circ a^{-1})\\
& =& x \cdot \bar{b} \circ (a \cdot a^{-1}) \\
&= & x \cdot \bar{b} \\
&=& x \circ \bar{b},
\end{eqnarray*}
we obtain
$$
a \cdot (b \circ x \circ \bar{b}) \cdot a^{-1} = b \circ x \circ \bar{b}.
$$
Hence, $\Soc(G)$ is a normal subgroup  of $(G, \circ)$. Further,
$$
\lambda_b(x) = b^{-1} \cdot  (b \circ x \circ \bar{b}) \cdot b =  b \circ x \circ \bar{b},
$$
and hence $\Soc(G)$  is invariant under $\lambda_b$ for each $b \in G$. Being closed under $\circ$ implies that $\Soc(G)$ is closed under $\cdot$, and hence it is a normal subgroup of $(G, \cdot)$. Finally, since the operations $\circ$ and $\cdot$  coincide in $\Soc(G)$, it  is a trivial brace, which proves assertion (1).
\para 

By Propositions \ref{lambda-map} and \ref{gamma-map},  the map $\varphi$ is well-defined and is a group homomorphism. Recall that
$\gamma_a(b) = \big((\bar{a} \circ \bar{b} \big) \cdot (\bar{a})^{-1} )^{\circ(-1)}$. Hence, if $\lambda_a = \id$, then 
$$
\gamma_a(b) = \big((\bar{a} \circ \bar{b} \big) \cdot (\bar{a})^{-1} \big)^{\circ(-1)} = 
\big((\bar{a} \cdot \bar{b} \big) \cdot (\bar{a})^{-1} \big)^{\circ(-1)} = \big(\bar{a} \cdot \bar{b}  \cdot (\bar{a})^{-1} \big)^{\circ(-1)}. 
$$
Thus, $\gamma_a(b) = b$ if and only $\bar{a} \cdot \bar{b} = \bar{b} \cdot \bar{a}$. Hence, we have
$$
\ker(\varphi) = \{ a \in G~|~\lambda_a = \gamma_a = \id \} = 
\{ a \in G~|~\lambda_a = \id~\textrm{and}~b \cdot a = a \cdot b~\mbox{for any}~ b \in G \} = \Soc(G),$$
proving assertion (2).
\para 

The proof of assertion (3) is analogous to (2) and follows from Proposition \ref{theta-map}.
$\blacksquare$ 
\end{proof}

