\subsection{Skew braces via exact factorisations of groups} \label{ExactFact}

We begin with the following definition.

\begin{definition}
A \index{factorization of a group}{factorization} of a group $G$ is the decomposition $$G = H L =\{ h l \, \mid \, h \in H ~~ \textrm{and}~ l \in L \}$$ of $G$ by two subgroups $H$ and $L$.  The factorization  is said to be \index{proper factorization}{proper} if $H$ and $L$ are proper subgroups of $G$, and is called \index{exact factorisation}{exact} if $H \cap L = 1$.
\end{definition}

For an exact factorization $G = H L$, it is not necessary that any of  the subgroups $H$ or $L$ is normal in $G$.  For example, the alternating group $A_5$ does not have proper normal subgroups, but admits a proper exact factorisation $A_5 = A_4 \big\langle (12345) \big\rangle$ by $A_4$ and a cyclic subgroup of order 5. 
\para

We have the following result \cite[Theorem 2.3]{MR3763907}.

\begin{theorem}  \label{skew left brace exact factor}
Let $(G, \cdot)$ be a group with an exact factorisation $G = H L$. Then $(G, \cdot, \circ)$ is a skew left brace, where
\begin{equation} \label{efeqn1}
a \circ b= h \cdot b \cdot l 
\end{equation}
for $a = h \cdot l, b\in HL$. Further, the group $(G, \circ)$ is isomorphic to the direct product  $H \times L$.
\end{theorem}

\begin{proof}
Let $\phi: H \times L \to G$ be the bijection given by $\phi(h, l)=h \cdot l^{-1}$. For elements $a=h \cdot l$ and $b=h_1 \cdot l_1$ of $G$, we see that
\begin{eqnarray*}
a \circ b &=& h \cdot b \cdot l\\
&=& h \cdot h_1\cdot l_1\cdot l\\
&=& \phi(h \cdot h_1, l^{-1} \cdot l_1^{-1})\\
&=& \phi \big((h, l^{-1})( h_1, l_1^{-1}) \big)\\
&=& \phi \big(\phi^{-1}(h\cdot l) \phi^{-1}(h_1\cdot l_1) \big)\\
&=& \phi \big(\phi^{-1}(a) \phi^{-1}(b) \big).
\end{eqnarray*}
Since $\phi$ is a bijection, it follows that $(G, \circ)$ is a group isomorphic to the direct product $ H \times L$. Let $a = h\cdot l \in HL$ and $b, c \in G$. Then we have
\begin{eqnarray*}
a \circ (b \cdot c) &=& h \cdot (b\cdot  c) \cdot l\\
&=& h \cdot b \cdot l \cdot (l^{-1} \cdot h^{-1}) \cdot h \cdot c \cdot l\\
&=& (h \cdot b \cdot l)\cdot  a^{-1} \cdot (h \cdot c \cdot l)\\
&=& (a \circ b) \cdot a^{-1} \cdot (a \circ c),
\end{eqnarray*}
and hence $(G, \cdot, \circ)$ is a skew left brace.  $\blacksquare$ 
\end{proof}

The following example gives an illustration of the preceding result \cite[Example 2.4]{MR3763907}.

\begin{example}
The general linear group $\GL(n, \mathbb{C})$ admits an exact factorization through subgroups $\Uu(n, \mathbb{C})$ and $\Tt(n, \mathbb{C})$, where 
$\Uu(n, \mathbb{C})$ is the unitary group and $\Tt(n, \mathbb{C})$ is the group of upper triangular matrices with positive diagonal entries. Thus, there exists a skew left brace $(G, \cdot, \circ)$ with
$(G, \cdot) \cong  \GL(n, \mathbb{C})$ and $(G, \circ) \cong \Uu(n, \mathbb{C}) \times \Tt(n, \mathbb{C})$.
\end{example}

\begin{proposition}\label{free product exact factorization}
A free product of non-trivial groups admits an exact factorization. 
\end{proposition}

\begin{proof}
Let $C$ and  $B$ be non-trivial groups and $G = C \ast B$  their free product. Let $D$ be the kernel of the natural homomorphism  $C \ast B \to C \times B$. Taking  $A=\langle  C, D  \rangle$, a direct check gives
$$
G=AB \quad \textrm{and}\quad A\cap B=1,
$$
and hence  $G$ admits an exact factorization. $\blacksquare$ 
\end{proof}
\para 

We have the following result  \cite[Proposition 5.11]{MR4346001}.

\begin{proposition}\label{exact factorisation of free group} 
There exists a skew  left brace $(G, \cdot, \circ)$ such that $(G, \cdot)$ is finitely generated, but $(G, \circ)$ is not.
\end{proposition}

\begin{proof}
Let $F_n=\langle x_1,\ldots,x_n \rangle$ be the free group of rank $n \ge 2$. Take  $C = F_{n-1} = \langle x_1, \ldots, x_{n-1} \rangle$ and $B = \langle  x_n \rangle$. Then $F_n = C \ast B$ and $A = \big\langle C, [x_n, F_n] \big\rangle$. By Proposition \ref{free product exact factorization}, we have
$$
F_n=AB \quad \textrm{and}\quad A \cap B=1,
$$
and hence $F_n$ admits an exact factorization. It follows from Theorem \ref{skew left brace exact factor} that $(F_n, \cdot, \circ)$ is a skew left brace with  $\circ$ defined by \eqref{efeqn1} and $(F_n, \circ) \cong A \times B$. Since the operations $\circ$ and $\cdot$ coincide on $A$ as well as on  $B$, it follows that $A\cong F_{\infty}$, the free group of countably infinite rank.  $\blacksquare$ 
\end{proof}

\begin{definition}
A \index{matched pair}{\it matched pair} of groups is a quadruple $(H, L, \rightharpoonup, \leftharpoonup)$, where $H, L$ are groups and $\rightharpoonup, \leftharpoonup$ are two actions
$$
L \overset{\leftharpoonup}{\longleftarrow} L \times H  \quad \textrm{and} \quad  L \times H  \overset{\rightharpoonup}{\longrightarrow} H
$$
satisfying the conditions
$$
l \rightharpoonup (h h') = (l \rightharpoonup  h) \big( (l \leftharpoonup h) \rightharpoonup  h' \big) \quad \textrm{and} \quad
(l l') \leftharpoonup h = \big(l \leftharpoonup (l' \rightharpoonup h) \big)(l' \leftharpoonup h)
$$
for all $h, h' \in H$ and $l, l' \in L$. Here, the notation $l \rightharpoonup h$ means that $l$ acts on $h$ from the left, and similarly, $l \leftharpoonup h$ means that $h$ acts on $l$ from the right.
\end{definition}



If $(H, L, \rightharpoonup, \leftharpoonup)$ is a matched pair of groups, then $H \times L$ is a group with multiplication
$$
(h, l) (h', l') = \big(h(l \rightharpoonup h'), (l \leftharpoonup h')l'\big)
$$
for $h, h' \in H$ and $l,  l' \in L$. The inverse of $(h, l)$ in this group is
$$
(h, l)^{-1} = \big(l^{-1} \rightharpoonup h^{-1}, (l \leftharpoonup (l^{-1} \rightharpoonup h^{-1}))^{-1}\big).
$$
This group is denoted by $H \bowtie L$, and known as the \index{biproduct}{\it biproduct} of $H$ and $L$. Note that the biproduct $H \bowtie L$  admits an exact factorization through its subgroups $H \bowtie 1 \cong H$ and $1 \bowtie L \cong L$. As a consequence of Theorem \ref{skew left brace exact factor},  we obtain the following result \cite[Corollary 2.7]{MR3763907}.

\begin{corollary}\label{skew left brace match product}
Let $(H, L, \rightharpoonup, \leftharpoonup)$ be a matched pair of groups. Then the biproduct $H \bowtie L$ is a skew left brace with
$$
(h, l) (h', l') = \big(h (l \rightharpoonup h'), (l \leftharpoonup h') l' \big) \quad \textrm{and} \quad  (h, l) \circ (h', l') = (h h', l l')
$$
for $h, h' \in H$ and $l,  l' \in L$.
\end{corollary}


We use exact factorization to prove that the knot group of a knot admits a non-trivial skew left brace structure. 

\begin{proposition}
 Let $K$ be a  knot  in $\mathbb{S}^3$ and $G(K) = \pi_1(\mathbb{S}^3 \setminus K)$ its knot group.  Then there is a non-trivial skew left brace structure on $G(K)$.
\end{proposition}

\begin{proof}
We set $G = G(K)$. Since $G / [G, G] \cong \mathbb{Z}$,  there exists  a factorization $G = H L$ with $H=[G, G]$, $L \cong \mathbb{Z}$ and $H \cap L = 1$. Hence, by Theorem \ref{skew left brace exact factor},  we can define a binary operation $\circ$ on $G$ such that $(G, \cdot, \circ)$ is a non-trivial skew left brace.
$\blacksquare$ 
\end{proof}

Another application of exact factorization  yields a  skew left brace whose additive group is solvable but not nilpotent, while its multiplicative group is abelian \cite[Proposition 5.13]{MR4346001}.


\begin{proposition}
There is a skew left brace $(G, \cdot, \circ)$ such that $(G, \cdot)$ is a metabelian group which is not nilpotent, while $(G,  \circ)$ is a free abelian group of countably infinite rank.
\end{proposition}

\begin{proof}
Let $G$ be the group with the following presentation
$$
G=\big\langle\,  x, y_i, \, i\in \mathbb{Z}   \, \mid \,    xy_i x^{-1}=y_{i+1} ~~ \textrm{and} ~~  [y_i,y_j]=1  ~~ \textrm{for all} ~~ i,j\in \mathbb{Z}\,\big\rangle.
$$
It follows that $G$ is the \index{wreath product}{wreath product}  $\mathbb{Z} \wr \mathbb{Z}$ of two infinite cyclic groups, and hence is  metabelian. Consider the subgroups
$$
H = \big\langle\,  y_i, \,i\in \mathbb{Z}   \, \mid \,     [y_i,y_j]=1 ~~ \textrm{for all} ~~ i,j\in \mathbb{Z}\,\big\rangle \cong \mathbb{Z}^{\infty}   ~~ \textrm{and} ~~ L = \langle x \rangle \cong \mathbb{Z}
$$
of $G$. Then $G = H \rtimes L$ is an exact factorization of $G$. Hence, Theorem \ref{skew left brace exact factor} gives a binary operation $\circ$ on $G$ such that $(G, \cdot, \circ)$ is a  skew left brace and
$$
(G, \circ) \cong H \times L \cong \mathbb{Z}^{\infty}  \times \mathbb{Z} \cong \mathbb{Z}^{\infty}.
$$
Further, $\gamma_2(G, \cdot)=\gamma_3(G, \cdot)$ is non-trivial abelian, and hence $(G, \cdot)$ is metabelian but not nilpotent. $\blacksquare$
\end{proof}
