\subsection{Skew braces, bijective 1-cocycles and regular subgroups}
Let $G$ and $\Gamma$ be groups such that the map $\Gamma \times G \to G$ given by $(\gamma, a) \mapsto \gamma \sbullet a$,
is a left-action of $\Gamma$ on $G$ by automorphisms. A bijective \index{1-cocycle}{1-cocycle} or \index{crossed homomorphism}{a crossed homomorphism} is a bijective map $\pi : \Gamma \to G$ such that
$$\pi(x y) = \pi(x) \, \big(x \sbullet \pi(y) \big)$$
for all $x,y\in \Gamma$. 
\para

The following result gives an intimate connection between bijective 1-cocycles and skew braces on a given group \cite[Proposition 1.11]{MR3647970}.

\begin{proposition}\label{bijective 1-cocycle and skew brace}
Let $(G, \cdot)$ be a group. Then there is a one-to-one correspondence between bijective 1-cocycles with values in $(G, \cdot)$ and skew left braces $(G, \cdot, \circ)$.
\end{proposition}

\begin{proof}
Let $(G, \cdot)$ and $\Gamma$ be groups such that $\Gamma \times G \to G$ given by $(\gamma, a) \mapsto \gamma \sbullet a$,
is a left-action of $\Gamma$ on $G$. Let $\pi : \Gamma \to G$ be a bijective 1-cocycle with respect to this action. Then the binary operation $\circ$ by
\begin{equation} \label{1-cocycle condtion}
a \circ b = \pi\big(\pi^{-1}(a) \,\pi^{-1}(b) \big)
\end{equation}
for $a,b \in G$, gives rise to a group $(G, \circ)$. Further, for $a, b, c \in G$, we have
\begin{eqnarray*}
a \circ (b \cdot c) &=& \pi \big(\pi^{-1}(a)\, \pi^{-1}(b \cdot c)\big)\\
&=& a \cdot \big(\pi^{-1}(a) \sbullet (b \cdot c) \big)\\
&=& a \cdot \big((\pi^{-1}(a) \sbullet b) \cdot (\pi^{-1}(a)\sbullet c)\big)\\
&=& a \cdot (\pi^{-1}(a) \sbullet b) \cdot a^{-1} \cdot a \cdot (\pi^{-1}(a)\sbullet c)\\
&=& \pi \big(\pi^{-1}(a) \pi^{-1}(b) \big) \cdot a^{-1} \cdot \pi \big(\pi^{-1}(a) \pi^{-1}(c) \big)\\
&=& (a \circ b) \cdot a^{-1} \cdot (a \circ c),
\end{eqnarray*}
and hence $(G, \cdot, \circ)$ is a~skew left brace.
\para
Conversely, let $(G, \cdot, \circ)$  be a skew left brace. Taking $\Gamma = (G, \circ)$, the map $\lambda:\Gamma \to \Aut(G, \cdot)$ is an action of $\Gamma$ on $(G, \cdot)$ by automorphisms, which we write as $a \sbullet b= \lambda_a(b)$ for $a \in \Gamma$ and $b \in G$. Taking $\pi:\Gamma \to G$ to be the identity map, we see that $\pi (a \circ b)= a \circ b= a \cdot \lambda_a(b) =a \cdot (a \sbullet b )= \pi(a) \cdot \big(a \sbullet \pi(b) \big)$ for all $a, b \in \Gamma$. Hence, $\pi : \Gamma \to G$ is a bijective 1-cocycle. $\blacksquare$ 
\end{proof}
\bigskip

The \index{holomorph}{\it holomorph} of a group $G$ is defined to be the group $\Hol(G) = \Aut(G) \ltimes G$, in which the product is given by
$$
(f,a)(g,b)=\big(fg,~af(b) \big)
$$
for all $a,b \in G$ and $f,g \in \Aut(G)$. Each subgroup $H$ of $\Hol(G)$ admits a left-action on $G$ given by
$$
(f,a) \sbullet b = af(b)
$$
for $a,b \in G$ and $f \in \Aut(G)$. A subgroup $H$ of $\Hol(G)$ is said to be \index{regular subgroup}{\it regular} if the action of $H$ on $G$ is free and transitive. Regularity is equivalent to the fact that for each $a \in G$ there exists a unique $(f,x) \in H$ such that $xf(a)=1$.  Let $\pi_2 : \Hol(G) \to G$ denote the projection onto the second factor, that is, $\pi_2((f, a) )=a$ for all $(f, a) \in \Hol(G)$. Then we have the following result.

\begin{proposition}\label{reg sub to group bijection}
Let $G$ be a group and $H$ a regular subgroup of $\Hol(G)$. Then the restriction $\pi_2|_H : H \to G$ is bijective.
\end{proposition}

\begin{proof}
Let $(f, a),(g, b) \in H$ be such that $\pi_2 \big((f, a) \big) = \pi_2 \big((g, b) \big)$. This gives $a = b$. Since $H$ is a subgroup, both the elements $(f, a)^{-1}= \big(f^{-1}, f^{-1}(a^{-1}) \big)$ and $(g, b)^{-1}= \big(g^{-1}, g^{-1}(b^{-1}) \big)$ lie in $H$. Since $f^{-1}(a^{-1})f^{-1}(a)=g^{-1}(b^{-1})g^{-1}(b)=1$ and $H$ is a regular subgroup, it follows that $f=g$, and hence $\pi_2$ is injective. For surjectivity, let $a \in G$. The regularity of $H$ implies
the existence of an automorphism $f \in \Aut(G)$ such that $\big(f,f(a^{-1}) \big) \in H$. Then $(f^{-1}, a) \in H$ and the proposition  follows. $\blacksquare$ 
\end{proof}

The following theorem  provides a connection between skew left braces and regular subgroups of the holomorph \cite[Theorem 4.2]{MR3647970}. The result goes back to Bachiller for left braces \cite{MR3465351} and also generalises a result of Catino and Rizzo \cite{MR2486886}.


\begin{theorem}\label{gv2017}
Let $(G, \cdot)$ be a group. Then the following assertions  hold:
\begin{enumerate}
\item  If $(G, \cdot, \circ)$ is a skew left brace, then $ \{(\lambda_a, a) \, \mid \, a \in G  \}$
is a regular subgroup of $\Hol(G)$, where $\lambda_a(b) = a^{-1} \cdot (a \circ b)$ for all $a, b \in G$.
\item If $H$ is a regular subgroup of $\Hol (G, \cdot)$, then $(G, \cdot, \circ)$ is a skew left brace with $(G, \circ) \cong H$, where $a \circ b=a f(b)$ for some $f \in \Aut(G, \cdot)$ such that  $(\pi_2|_H)^{-1}(a)=(f, a)$.
\end{enumerate}
\end{theorem}

\begin{proof}
Let $(G, \cdot, \circ)$ be a skew left brace. Since $\lambda: (G, \circ) \to \Aut(G, \cdot)$ is a group homomorphism and $a \cdot \lambda_a(b)=a\circ b$ for all $a,b\in G$, it follows that $\{(\lambda_a,a)  \, \mid \,  a\in G\}$ is a subgroup of $\Hol(G,\cdot)$. Further, since $(G,\circ)$ is a group, the regularlity of $H$ also follows.
\para

Now, let $H$ be a regular subgroup of $\Hol(G, \cdot)$. By Proposition \ref{reg sub to group bijection}, $\pi_2|_H:H \to G$ is a bijection. Hence, we can transport the group structure on $H$ onto $G$  by defining 
$$ a\circ b=\pi_2|_H\big((\pi_2|_H)^{-1}(a)\, (\pi_2|_H)^{-1}(b)\big)=a \cdot f(b),$$
where $a,b\in G$ and $(\pi_2|_H)^{-1}(a)=(f,a)\in H$. Since
$$ a\circ (b \cdot c)=a \cdot f(b \cdot c)=a \cdot f(b) \cdot f(c)=a\cdot f(b)\cdot a^{-1}\cdot a\cdot f(c)=(a\circ b)\cdot a^{-1}\cdot (a\circ c)$$
for all $a,b,c\in G$, it follows that $(G, \cdot, \circ)$ is a skew left brace. $\blacksquare$ 
    \end{proof}

\begin{proposition}
Let $(G, \cdot)$ be a group.  Then there is a bijective correspondence between skew left brace structures on $(G, \cdot)$ and regular subgroups of
	$\Hol(G, \cdot)$. Moreover, isomorphic skew left braces structures on $(G, \cdot)$ correspond to conjugate subgroups of $\Hol(G, \cdot)$ by elements of $\Aut(G, \cdot)$.
\end{proposition}

\begin{proof}
Suppose that the group $(G, \cdot)$ has two skew left brace structures, for which the multiplicative groups are given by $(a,b)\mapsto a\circ b$ and $(a,b)\mapsto a\times b$. Let $\phi\in\Aut(G, \cdot)$ such that $\phi(a\circ b)=\phi(a)\times\phi(b)$ for	 all $a,b\in G$. Let $\lambda_a(b)=a^{-1}\cdot (a\circ b)$ and $\mu_a(b)=a^{-1}\cdot (a\times b)$ for all $a,b\in G$. We claim that the regular subgroups $\{(\lambda_a,a) \, \mid \, a\in G$\} and 	$\{(\mu_a,a) \, \mid\, a\in G\}$ are conjugate by the element $\phi$. Since
$$    \phi\lambda_a\phi^{-1}(b)=\phi \big(a^{-1}\cdot (a\circ\phi^{-1}(b))\big)=\phi(a)^{-1}\cdot \big(\phi(a)\times b \big)=\mu_{\phi(a)}(b), $$
we see that $(\phi, 1)(\lambda_a,a)(\phi, 1)^{-1}=\big(\mu_{\phi(a)},\phi(a)\big)$, and hence the claim follows.
\para

Conversely, let $H$ and $K$ be regular subgroups of $\Hol(G, \cdot)$ such that there exists $\phi\in\Aut(G, \cdot)$ with $(\phi, 1)H(\phi, 1)^{-1}=K$. For $a \in G$, let $(f,a)=(\pi_2|_H)^{-1}(a)\in H$ and $(g,a)=(\pi_2|_K)^{-1}(a)\in K$. Write  $a\circ b=a \cdot f(b)$ and 
$a\times b=a \cdot g(b)$ for $a, b \in G$. It follows from Theorem \ref{gv2017} that both $(G, \cdot, \circ)$ and $(G, \cdot, \times)$ are skew left braces.
Since  $(\phi, 1)(f,a)(\phi, 1)^{-1}= \big(\phi f\phi^{-1},\phi(a) \big)\in K$, it follows that  $ (\pi_2|_K)^{-1}(\phi(a))= \big(\phi f\phi^{-1}, \phi(a)\big)$. This gives
$$ \phi(a)\times\phi(b)=\phi(a) \cdot  (\phi f\phi^{-1})\big(\phi(b)\big)=\phi(a) \cdot \phi \big(f(b)\big)=\phi \big(a \cdot  f(b)\big)=\phi(a\circ b),$$
and hence the skew left braces corresponding to $H$ and $K$ are isomorphic. $\blacksquare$ 
\end{proof}
\bigskip
\bigskip

