\section{Solutions arising from skew  braces}

In this section, we study solutions to the Yang--Baxter equation that arise from skew left braces. Recall from Definition \ref{def braiding operator} the notion of a braiding operator on a group. According to Theorem \ref{conjugate braiding thm}, every braiding operator yields a non-degenerate bijective solution to the Yang--Baxter equation. The following theorem is due to Guarnieri and Vendramin \cite[Theorem 3.1]{MR3647970}. 

\begin{theorem} \label{solution from a skew brace}
Let $(G,\cdot, \circ)$ be a~skew left brace and $r_G:G \times G \to G \times G$ given by
\begin{equation} \label{BraceToYBE}
r_G(a, b) = \left(\lambda_a(b), ~\lambda^{-1}_{\lambda_a(b)}\big((a \circ b)^{-1} \cdot a\cdot (a \circ b)\big) \right)= \big(\lambda_a(b), ~ \overline{\lambda_a(b)} \circ (a \circ b)\big)
\end{equation}
for $a, b \in G$. Then $(G, r_G)$ is a non-degenerate bijective solution to the Yang--Baxter equation.
\para 
If $(G,\cdot, \circ)$ is a left brace (that is, $(G, \cdot)$ is abelian), then
\begin{equation}
r_G(a, b) = \left(\lambda_a(b), ~\lambda^{-1}_{\lambda_a(b)}(a) \right).
\end{equation}
\para 
Moreover, $r_G$ is involutive if and only if $(G, \cdot)$ is abelian.
\end{theorem}

\begin{proof} 
 For convenience of notation, we denote $r_G$ by $r$.  By Theorem \ref{conjugate braiding thm}, every braiding operator on a group is a non-degenerate bijective solution to the Yang--Baxter equation. Thus, it is enough to prove that $r$ is a braiding operator on $(G, \circ)$. Since $\lambda_a^{-1}(b) = \bar{a} \circ (a \cdot b)$ for all $a, b \in G$, we have 
$$
\lambda_{\lambda_a(b)}^{-1}\big((a \circ b)^{-1} \cdot a \cdot (a \circ b)\big) = \overline{\lambda_a(b)} \circ \big(\lambda_a(b) \cdot (a \circ b)^{-1} \cdot a\cdot  (a \circ b)\big) = \overline{\lambda_a(b)} \circ (a \circ b)
$$
 for all $a, b \in G$. Thus, if $m$ is the multiplication in $(G, \circ)$, then $m \, r(a, b) = a \circ b$  for all $a, b \in G$. Clearly, $r(a, 1) = (1, a)$ and $r(1, a) = (a, 1)$ for all $a \in G$. Since $\lambda : (G, \circ) \to \Aut(G, \cdot)$ is a group homomorphism, we have
\begin{eqnarray*}
(\id \times m)\, r_{12} \,r_{23} \,(a, b, c) &=& (\id \times m) \, r_{12}\, \big(a, ~\lambda_b(c),  ~\overline{\lambda_b(c)}  \circ b \circ c \big)\\
&=& (\id \times m) \, \big(\lambda_a\lambda_b(c), ~\overline{\lambda_a\lambda_b(c)}  \circ a \circ \lambda_b(c),~  \overline{\lambda_b(c)}  \circ b \circ c \big)\\ 
&=& \big(\lambda_a\lambda_b(c),~ \overline{\lambda_a\lambda_b(c)}  \circ a \circ b \circ c \big)\\
&=& r(a \circ b, ~c).
\end{eqnarray*}
For $a, b, c \in G$, since $b \circ c=b \cdot \lambda_b(c)$, we have
$$
\lambda_a (b \circ c) = \lambda_a (b) \cdot \lambda_{a \circ b} (c).
$$
This gives
$$\lambda_a (b) \circ \lambda_{\overline{\lambda_a(b)} \circ a \circ b} (c) = \lambda_a (b) \circ \lambda^{-1}_{\lambda_{a}(b)} \lambda_{a}\lambda_{b}(c)= \lambda_a (b) \cdot \lambda_{a \circ b} (c)=\lambda_{a}(b  \circ c)$$
for $a, b, c \in G$. Thus, 
\begin{eqnarray*}
(m \times \id) \,r_{23}\, r_{12} \,(a, b, c) 
&=&  (m \times \id)\, r_{23}\, \big(\lambda_a (b),~ \overline{\lambda_a (b)} \circ a \circ b, ~c \big) \\
&=&   (m \times \id) \, \big(\lambda_a (b),  ~\lambda_{\overline{\lambda_a (b)} \circ a \circ b} (c), ~\overline{\lambda_{\overline{\lambda_a (b)} \circ a \circ b}(c)} \circ \overline{\lambda_a (b)} \circ a \circ b \circ c \big) \\
&=&  \big(\lambda_a (b) \circ  \lambda_{\overline{\lambda_a (b)} \circ a \circ b} (c), ~\overline{\lambda_{\overline{\lambda_a (b)} \circ a \circ b}(c)} \circ
\overline{\lambda_a (b)} \circ a \circ b \circ c \big)\\
&=&  \big(\lambda_a (b\circ c), ~\overline{\lambda_a (b\circ c)} \circ a \circ b \circ c \big) \\
&=&  r(a, ~b \circ c)
\end{eqnarray*}
for all $a, b, c \in G$. Finally, we prove that $r$ is bijective. Suppose that  $r(a, b)=r(c, d)$. This gives $\lambda_a(b)=  \lambda_c(d)$ and $\overline{\lambda_a(b)} \circ (a \circ b)= \overline{\lambda_c(d)} \circ (c \circ d)$, from which we deduce that $a \circ b= c \circ d$. Now, $a^{-1} \cdot (a \circ b)= \lambda_a(b)=  \lambda_c(d)= c^{-1} \cdot (c \circ d)$ implies that $a=c$. Plugging this back into  $\lambda_a(b)=  \lambda_c(d)$ implies that $b=d$, and hence $r$ is injective. For surjectivity of $r$, if $(x, y) \in X \times X$, then a direct check  shows that 
$$r\big((x \circ y) \cdot x^{-1},~ (\,\overline{(x \circ y) \cdot x^{-1})} \circ x \circ y \big)= (x, y),$$
and hence $r$  is a braiding operator on $(G, \circ)$. The remaining two assertions are immediate, which completes the proof. $\blacksquare$ 
\end{proof} 

\begin{remark}
{\rm 
Bachiller, Ced\'{o}, and Jespers showed in \cite{MR3527540} that non-degenerate involutive solutions can be explicitly generated using left braces. Subsequently, Bachiller further established in \cite{MR3835326} that non-degenerate bijective solutions can be derived from skew left braces. This reduces the problem of classifying all non-degenerate bijective solutions to that of classifying skew left braces.
}
\end{remark}

\begin{example}
{\rm 
Let $(G, \cdot, \circ)$ be a skew left brace such that the map $\lambda$ is trivial, that is, $\lambda_a = \id$ for all $a \in G$. The identity $\lambda_a(b) = a^{-1} \cdot (a \circ b) = b$ implies that $a \circ b = a \cdot b$, and hence $(G, \cdot, \circ)$ is a trivial skew left brace. Then the formula (\ref{BraceToYBE}) has the form
\begin{equation} \label{trivBr}
s_G(a, b) = (b, ~b^{-1} \cdot a \cdot  b)
\end{equation}
for $a, b \in G$. Note that this is a solution of quandle type on the group $(G, \cdot)$.}
\end{example}

\begin{example}{\rm 
Let $G$ and $K$ be groups and $\alpha : G \to \Aut(K)$  a group homomorphism.  Consider the skew left brace structure on $G \times K$ as in Example \eqref{examples of solutions}(5). Then the solution to the Yang--Baxter equation corresponding to the skew left brace $(G \times K, \cdot, \circ)$ has braiding
$$
r : (G \times K) \times  (G \times K)  \to (G \times K) \times  (G \times K)
$$
is given by
$$
r\big((a_1, b_1), ~(a_2, b_2)\big) = \left( \big(a_2, \alpha_{a_1}(b_2) \big), ~\big(a_2^{-1} a_1 a_2, b_2^{-1} \alpha_{a_2^{-1}}(b_1 \alpha_{a_1}(b_2) ) \big) \right)
$$
for $a_1, a_2 \in G$ and $b_1, b_2 \in K$.}
\end{example}
\para 

Next, we show that the solution to the Yang--Baxter equation arising from a skew left brace as in \eqref{BraceToYBE}  is conjugate to the solution of the form \eqref{trivBr} \cite[Proposition 3.7]{MR3647970}.

\begin{proposition} \label{GV}
Let $(G,\cdot,\circ)$ be a skew left brace. Then the solution to the Yang--Baxter equation given by \eqref{BraceToYBE} is conjugate to the solution of quandle type on the group $(G, \cdot)$ given by \eqref{trivBr}.
\end{proposition}

\begin{proof}
Let $T : G\times G  \to G\times G $ be defined by
$$
T(a, b) = \big(a, ~\lambda_a(b) \big)
$$
for $a, b \in G$. Then $T$ is invertible with inverse
$$
T^{-1}(a, b) = \big(a, ~\lambda^{-1}_a(b) \big)
$$
for $a, b \in G$. Let $r_G$ be the solution given by ~\eqref{BraceToYBE} and $s_G$ the solution of quandle type given by \eqref{trivBr}.
A direct calculation gives
\begin{eqnarray*}
T \, r_G \, (a, b) &=& T \,\big(\lambda_a(b), ~\lambda^{-1}_{\lambda_a(b)}((a \circ b)^{-1} \cdot a\cdot (a \circ b))\big)\\
&=& \big(\lambda_a(b),~ (a \circ b)^{-1} \cdot a\cdot (a \circ b)\big)\\
&=& \big(\lambda_a(b), ~\lambda_a(b)^{-1} \cdot a \cdot \lambda_a(b) \big)\\ 
&=& s_G \, \big(a, ~\lambda_a(b)\big)\\ 
 &=& s_G \, T \,(a, b)
\end{eqnarray*}
for all $a, b \in G$, which proves the proposition. $\blacksquare$  
\end{proof}          

\begin{remark}
{\rm The preceding proposition also follows from Proposition \ref{SolTh} by taking $\sigma_a(b)=\lambda_a(b)$ and $\tau_b(a)=\overline{\lambda_a(b)} \circ (a \circ b)$ for $a,  b \in G$.
}    
\end{remark}
\para


Recall that, to each solution $(X,r)$ to the Yang--Baxter equation, we can associate its structure group $G(X, r)$ and its derived structure group $A(X, r)$. Also, we have natural maps $i_X: X \to G(X, r)$ and $j_X: X \to A(X, r)$. By Theorem \ref{action of str group on der str group}, if $(X, r)$ is a non-degenerate solution, then the left-action $G(X, r) \to \Sigma_X$, given by $x \mapsto \sigma_x$, lifts uniquely to a left-action $$\lambda:G(X, r) \to  \Aut\big(A(X, r)\big).$$ In other words, 
$$\lambda_{x}(y)=\sigma_x(y)$$
for all $x, y \in X$. The next result gives the structure  of a skew left brace on the structure group $G(X, r)$ of a non-degenerate solution $(X, r)$ (see \cite[Theorem 3.7]{MR3835326} and \cite[Theorem 9]{MR1769723}).


\begin{theorem} \label{skew brace on structure group}
Let $(X, r)$ be a  non-degenerate bijective solution to the Yang--Baxter equation and $G(X, r)$ its structure group with group operation $\circ$. Then there is another group operation $\cdot$ on the set $G(X, r)$ and a group isomorphism $\varphi : \big(G(X, r), \cdot \big) \to A(X, r)$ with $\varphi(x) = x$ for all $x \in X$, such that $\big(G(X, r), \cdot, \circ \big)$ is a skew left brace, where 
\begin{equation}\label{bijective 1-cocycle inverse}
a \cdot b = a \circ \varphi^{-1} \big(\lambda_a^{-1}(\varphi(b)) \big)    
\end{equation}
for $a, b\in G(X, r)$.
\end{theorem}


Note that \eqref{bijective 1-cocycle inverse} is equivalent to the map $$\varphi : \big(G(X, r), \circ \big) \to A(X, r)$$ being a bijective 1-cocycle. By Theorem \ref{univ property non-deg solution st group}, the structure group of a non-degenerate bijective solution to the Yang--Baxter equation satisfies a universal property, which can be rephrased in terms of skew left braces as follows  \cite[Theorem 3.9]{MR3647970}.

\begin{theorem}
Let $(X,r)$ be a non-degenerate bijective solution to the Yang--Baxter equation and $i_X  : X \to G(X, r)$ the natural map. Then the following  assertions hold:
\begin{enumerate}
\item There exists a unique skew left brace structure on the group $G(X, r)$ such that $i_X$ becomes a morphism of solutions. In other words, if $r_G$ is the solution corresponding to the skew left brace on the group $G(X, r)$, then
$$
(i_X \times i_X) \, r= r_G \,(i_X \times i_X).
$$
\item If $(A, \cdot, \circ)$ is any skew left brace with corresponding solution $r_A$ and $\varphi : X \to A$ is a morphism of solutions, that is,
$$
(\varphi \times \varphi)\, r = r_A \, (\varphi \times \varphi),
$$
then there exists a unique skew brace homomorphism $\tilde{\varphi} : G(X, r) \to A$ such that $\varphi = \tilde{\varphi} \,i_X$ and
$$
(\tilde{\varphi} \times \tilde{\varphi}) \,r_G = r_A \,(\tilde{\varphi} \times \tilde{\varphi}).
$$
\end{enumerate}
\end{theorem} 

\begin{remark}
{\rm 
It follows from Proposition \ref{involutive sol condition} that if  $(X, r)$ is an involutive solution, then
$$
\sigma_{\sigma_x(y)} \big(\tau_y(x) \big) = x \quad \textrm{and}\quad \tau_{\tau_y(x)} \big(\sigma_x(y) \big) = y
$$ 
for all $x, y \in X$. In addition, if $(X, r)$ is non-degenerate, then  $\tau_y(x) = \sigma^{-1}_{\sigma_x(y)}(x)$ and we can write
$$
r(x, y) = \big(\sigma_x(y),~ \sigma^{-1}_{\sigma_x(y)}(x)\big).
$$
Under these conditions, the derived structure group has the presentation 
$$
A(X, r) = \big\langle X  \, \mid \, x  \sigma_x(y) = \sigma_x(y) \sigma_{\sigma_x(y)}(\tau_y(x)) \big\rangle = \big\langle X  \, \mid \, x \sigma_x(y) = \sigma_x(y) x \big\rangle =
 \big\langle X  \, \mid \, x  y= y  x  \big\rangle, 
$$
and hence is a free abelian group generated by $X$. This implies that the natural map $j_X : X \to A(X, r)$ is injective. Theorem \ref{skew brace on structure group} gives an isomophism $\varphi : \big(G(X, r), \cdot \big) \to A(X, r)$ with $\varphi(x) = x$ for all $x \in X$. This implies  that for non-degenerate involutive solutions $(X, r)$, the map $i_X:X \to G(X, r)$ is injective. In other words, no two elements of $X$ coincide as generators of $G(X, r)$.
}    
\end{remark}
\bigskip
