\chapter{Skew braces and associated actions} \label{chapter skew braces and solution of YBE}

\begin{quote} 
The structure of a skew left brace $(G, \cdot, \circ)$ is governed by its associated left-action $\lambda: (G, \circ) \to \Aut(G, \cdot)$. In this chapter, we focus on skew left braces for which the map $\lambda: (G, \cdot) \to \Aut(G, \cdot)$ is also a left-action and whose image is cyclic. These additional constraints have significant implications on the structure of the skew left brace.  We present several constructions of such skew left braces on free abelian groups and investigate the associated solutions to the Yang--Baxter equation that emerge from these structures.
\end{quote}
\bigskip


\section{Lambda-homomorphic skew braces} \label{lambda}

We begin with the following definition.

\begin{definition}
A skew left brace $(G, \cdot, \circ)$ is said to be \index{$\lambda$-homomorphic skew left brace}{$\lambda$-homomorphic} if the map $\lambda : (G, \cdot) \to \Aut(G, \cdot)$, defined  by  $\lambda_a(b) = a^{-1} \cdot  (a \circ b)$ for $a, b \in G$, is a group homomorphism.
\end{definition}

Given a group  $(G, \cdot)$, we desire to define a homomorphism $\lambda : (G, \cdot) \to \Aut(G, \cdot)$ such that $(G, \cdot, \circ)$ is a skew left brace, where  $a \circ b = a \cdot \lambda_a (b)$ for all $a, b \in G$. In this regard, we prove the following result \cite[Theorem 2.3]{MR4346001}.

\begin{theorem}  \label{t1}
Let $(G, \cdot)$ be a group and $\lambda : (G, \cdot) \to \Aut(G, \cdot)$ a group homomorphism. Then $ H_{\lambda} = \{ (\lambda_a, a) \,\mid \, a \in G \}$ is a subgroup of $\Hol(G)$ if and only if
\begin{equation} \label{inc}
[G, \lambda(G)] = \big\{ b^{-1} \cdot \lambda_a (b) \, \mid \, a, b \in G \big\} \subseteq \ker(\lambda).
\end{equation}
Moreover, if  $H_{\lambda}$ is a subgroup of $\Hol(G)$, then it is regular.
\end{theorem}

\begin{proof}
Suppose that  $H_{\lambda}$ is a subgroup of  $\Hol(G)$. Then, for $a, b \in G $, we have
$$ (\lambda_a, a)(\lambda_b, b)=\big(\lambda_a \lambda_b, ~a \cdot \lambda_{a} (b)\big) =\big(\lambda_{a \cdot b}, ~a \cdot \lambda_a (b)\big) \in H_{\lambda}.$$
This implies that
\begin{equation}
a \cdot \lambda_a(b)=a\cdot b,
\end{equation}
and hence
\begin{equation} \label{2}
\lambda \big(a \cdot \lambda_a(b) \big)=\lambda(a\cdot b).
\end{equation}
Since $\lambda$ is a group homomorphism, we get
\begin{equation} \label{3}
\lambda \big(\lambda_a(b)\big)=\lambda(b),
\end{equation}
which is equivalent to
\begin{equation} \label{4}
\lambda \big(b^{-1} \cdot \lambda_a(b)\big) = \id.
\end{equation}
This proves that $[G, \lambda(G)]  \subseteq \ker(\lambda)$.
\para

Conversely, suppose that $[G, \lambda(G)] \subseteq \ker(\lambda)$. Then  (\ref{4}), (\ref{3}) and (\ref{2}) hold, which implies that
$H_{\lambda}$ is closed under the product in $\Hol(G)$. It remains  to check that  $H_{\lambda}$ is closed under inversion in $\Hol(G)$. Note that, for   $(f, x)\in \Hol(G)$, we have  $(f, x)^{-1}= \big(f^{-1}, ~f^{-1}(x^{-1})\big)$, and hence
$$
(\lambda_a, a)^{-1}=\left( \lambda_a^{-1},~ \lambda_a^{-1}(a^{-1})    \right).
$$
By \eqref{3}, we have   $\lambda\left( \lambda_{a^{-1}}(a^{-1})  \right)=\lambda_{a^{-1}}$.
Since $\lambda$ is a homomorphism, we get
$$
(\lambda_a, a)^{-1}=\left( \lambda_{a^{-1}}, ~\lambda_{a^{-1}}(a^{-1})  \right)=
\left( \lambda ( \lambda_{a^{-1}}(a^{-1}) ), ~\lambda_{a^{-1}}(a^{-1})  \right) \in H_{\lambda},
$$
which proves that $H_{\lambda}$ is a subgroup of $\Hol(G)$.
\para 

Now, suppose that  $H_{\lambda}$ is a subgroup of $\Hol(G)$. By definition, the projection $\pi_2 : H_{\lambda} \to G$
given by $\pi_2 \big((\lambda_a, a)\big) = a$ is a bijection. Given $a \in G$, we see that $(\lambda_a, a)$ is the unique element such that  $(\lambda_a, a)\sbullet 1= a \cdot \lambda_a(1)= a$. Hence, the action of $H_{\lambda}$ on  $G$ is free and  transitive, and it is a regular subgroup of $\Hol(G)$. $\blacksquare$ 
\end{proof}


\begin{corollary} \label{c1}
Let $(G, \cdot)$ be a group and $\lambda : (G, \cdot) \to \Aut(G, \cdot)$ a group homomorphism. If  $G$ is non-trivial and $\lambda$ is injective, then $H_{\lambda}$ is not a group.
\end{corollary}

\begin{proof}
If $H_{\lambda}$ is a group, then injectivity of $\lambda$ together with \eqref{inc} gives  $\lambda_a = \id$ for all $a \in G$. But, this implies that   $\ker(\lambda)=G$,  a contradiction.  $\blacksquare$ 
\end{proof}
\para

 The following example shows that $H_{\lambda}$ can be a subgroup of $\Hol(G)$ for an injective anti-homomorphism $\lambda : G \to \Aut(G)$.

\begin{example}{\rm 
For a group $G$ with trivial center, consider the subset $H_\lambda= \{(\lambda_{a}, a) \, \mid \,  a \in   G \}$  of $\Hol(G)$, where $\lambda_{a}(b)=a^{-1}ba$ for all $b \in G$. Note that $\lambda : G \to \Aut(G)$ given by $a \mapsto \lambda_a$, is an injective anti-homomorphism. Since
$$
(\lambda_{a},a)(\lambda_{b},b)=\big(\lambda_{a}\lambda_{b},a \, \lambda_{a}(b)\big)=
(\lambda_{ba},ba),
$$
it follows that  $H$ is a subgroup of $\Hol(G)$. Further, the group operation  $\circ$ on the set  $G$ defined by
$$
a\circ b=a  \, \lambda_{a}(b)=ba,
$$
gives a  skew  left brace $(G, \cdot, \circ)$.}
\end{example}
\para

We introduce the following definition to describe the structure of a $\lambda$-homomorphic skew left brace.

\begin{definition}
A skew left brace $(G, \cdot, \circ )$ is said to be  \index{meta-trivial skew left brace}{\it meta-trivial}  if the following conditions hold:
\begin{enumerate}
\item There exists a trivial sub skew left brace $(H, \cdot, \circ )$ of $(G, \cdot, \circ )$.
\item $(H, \cdot)$ is normal in $(G,\cdot)$ and $(H, \circ)$ is normal in $(G, \circ)$.
\item $H \cdot a = H \circ a$ for all $a \in G$.
\item The quotient $G/H$  is a trivial skew left brace.
\end{enumerate}
\end{definition}

We have the following result \cite[Theorem 2.12]{MR4346001}.

\begin{theorem} 
Any $\lambda$-homomorphic skew left brace is meta-trivial.
\end{theorem}

\begin{proof}
Let $(G, \cdot, \circ )$ be a $\lambda$-homomorphic skew left brace, that is, $\lambda : (G, \cdot) \to \Aut(G, \cdot)$ is a group homomorphism. Recall that  $\lambda : (G, \circ) \to \Aut(G, \cdot)$ is always a group homomorphism. Note that
$$\ker (\lambda) = \{ a \in G \, \mid \, a \circ b = a \cdot b \, \mbox{  for all } b \in G \}.$$
Setting $H = \ker (\lambda)$, we see that $(H, \cdot)=(H, \circ)$ is a normal subgroup of both $(G, \cdot)$ as well as $(G, \circ)$. Clearly, $(H, \cdot, \circ)$  is a trivial sub skew left brace of $(G, \cdot, \circ )$. Set $(\overline{G}, \cdot) = (G, \cdot)/(H, \cdot)$, the set of right cosets of $(H, \cdot)$ in $(G, \cdot)$. Then
we see that 
$$H\cdot b = \{a \cdot b \, \mid \, a \in H\} = \{a \circ b \, \mid \, a \in H\}  = H \circ b$$
for all $b \in G$. Hence, we also have the group $(\overline{G}, \circ) = (G, \circ)/(H, \circ)$. Clearly, we have
$$ (H \cdot a) \cdot (H \cdot b)= H \cdot(a \cdot b )$$
and 
$$ (H \circ a) \circ (H \circ b) =  H \circ (a \circ b)$$
for all $a, b \in G$. By Theorem \ref{t1}, we have
$$ b^{-1} \cdot \lambda_a(b) \in \ker(\lambda)=H$$
for all $a, b \in G$. Since $a \circ b= \big(a \cdot  \lambda_a(b) \cdot b^{-1} \cdot a^{-1} \big) \cdot a \cdot b$ and $(H, \cdot)$ is normal in $(G, \cdot)$, it follows that 
$$ (H \circ a) \circ (H \circ b) =  H \circ (a \circ b)=H \cdot (a \circ b) = H \cdot \big(a \cdot  \lambda_a(b) \cdot b^{-1} \cdot a^{-1}\big) \cdot a \cdot b= H \cdot  (a \cdot b)= (H \cdot  a) \cdot (H \cdot b).$$
 This proves that $(\overline{G}, \cdot, \circ)$ is a trivial skew brace, which completes the proof.
$\blacksquare$ 
\end{proof}

\begin{remark}
{\rm 
It is natural to ask whether every meta-trivial skew left brace is $\lambda$-homomorphic. It turns out to be false in general. For example, consider the symmetric group $\Sigma_3$ on three letters with group operations $a \cdot b=ab$ and $a\circ b=ba$. Then $(\Sigma_3, \cdot, \circ)$ is a meta-trivial skew left brace that is not $\lambda$-homomorphic. 
}
\end{remark}

The following result gives a reduction argument, which allows us to verify  condition of Theorem \ref{t1} on generators of a given group and on the images of the generators under the map $\lambda$ \cite[Proposition 2.14]{MR4346001}. 

\begin{proposition}\label{redprop}
Let $G$ be a group generated by  $X=\left\{ x_i \,\mid\, i\in I\right\}$ and $\lambda : G \to \Aut (G)$, given by $a \mapsto \lambda_a$,  a group homomorphism.
If $\lambda_{x_i} = \varphi_i$ and $x_i^{-1} \varphi_j(x_i) \in \ker(\lambda)$ for $i, j \in I$, then
\begin{equation*} \label{7}
b^{-1} \lambda_a (b) \in \ker(\lambda)
\end{equation*}
for all $a, b \in G$.
\end{proposition}

\begin{proof}
Suppose that $x_i^{-1} \varphi_j(x_i) \in \ker(\lambda)$ for all $i, j \in I$. Let $\alpha \in \Aut(G)$.
Since $x\alpha(x^{-1}) = x \big(\alpha(x) \big)^{-1}=x \big(x^{-1}\alpha(x) \big)^{-1} x^{-1}$ for all $x \in G$, it follows that
\begin{equation}\label{eqn1sec2}
x^{-1}\alpha(x) \in \ker (\lambda) \Longleftrightarrow x\alpha(x^{-1})  \in \ker(\lambda).
\end{equation}
 Next, since
$x^{-1}\alpha^{-1}(x)= \left( \alpha^{-1}(x^{-1}) \alpha (\alpha^{-1}(x)) \right)^{-1}$ for all $x \in G$, we have
\begin{equation}\label{eqn2sec2}
z^{-1}\alpha(z)  \in \ker(\lambda) \Longleftrightarrow x^{-1}\alpha^{-1}(x)  \in \ker(\lambda),
\end{equation}
where $z = \alpha^{-1}(x)$.
\para
We claim that $x_i^{-1}\varphi_j^{-1}(x_i) \in \ker(\lambda)$ for all $i, j \in I$. Let us fix a pair $i, j \in I$. In view of \eqref{eqn2sec2}, we only need to show that $z_1^{-1}\varphi_j(z_1) \in \ker(\lambda)$, where $z_1 = \varphi_j^{-1}(x_i)$. Let $z_1 = x_{i_{1}}^{e_1} \cdots  x_{i_{t}}^{e_t}$ for some positive integer $t$, where $i_1,\ldots,i_t \in I$ and $e_1, \ldots, e_t  \in \{1, -1 \}$. If $t = 1$, then we are done by the given hypothesis along with \eqref{eqn1sec2}. We now apply induction on $t$. Note that 
$$(xy)^{-1}\alpha(xy) = \big(y^{-1}(x^{-1}\alpha(x))y \big)  \big(y^{-1}\alpha(y) \big)$$
 for all $x, y \in G$ and $\alpha \in \Aut(G)$. As a consequence,  if both $x^{-1}\alpha(x)$ and $y^{-1}\alpha(y)$ lie in  $\ker(\lambda)$ for  given $x, y \in G$, then $(xy)^{-1}\alpha(xy)  \in \ker(\lambda)$. Using this fact for $\alpha = \varphi_j$, $x = x_{i_{1}}^{e_1}$ and $y = x_{i_{2}}^{e_2} \cdots  x_{i_{t}}^{e_t}$, our claim follows by induction.
\para
Let $a=x_{i_{1}}^{\epsilon_1} \cdots  x_{i_{k}}^{\epsilon_k}$ and $b=x_{j_{1}}^{\varepsilon_1} \cdots  x_{j_{m}}^{\varepsilon_m}$ be non-trivial elements of  $G$, where  $i_1,\ldots,i_k,j_1,\ldots,j_m \in I$ and $\epsilon_1,\ldots,\epsilon_k,\varepsilon_1,\ldots,\varepsilon_m \in \{1, -1 \}$. Then, we have
$$
b^{-1}\lambda_a(b)=x_{j_{m}}^{-\varepsilon_m} \cdots  x_{j_{1}}^{-\varepsilon_1} \,
\varphi_{i_{1}}^{\epsilon_1} \cdots  \varphi_{i_{k}}^{\epsilon_k} \, 
x_{j_{1}}^{\varepsilon_1}\cdots  x_{j_{m}}^{\varepsilon_m}.
$$
\para
If $k=m=1$, then the assertion holds by the given hypothesis, \eqref{eqn1sec2} and the preceding claim. Assume that at least one of $k$ or $m$ is larger than $1$. As explained above,  if both $x^{-1}\alpha(x)$ and $y^{-1}\alpha(y)$ lie in  $\ker(\lambda)$ for  given $x, y \in G$, then $(xy)^{-1}\alpha(xy)  \in \ker(\lambda)$. Consequently, we can assume, without loss of generality, that $m=1$. Let $\beta \in \Aut(G)$ be another automorphism. Note that 
$$x^{-1} (\alpha\beta)(x)= \big(x^{-1}\beta(x) \big) \big(\beta(x)^{-1} (\alpha \beta)(x) \big)$$
for all $x \in G.$  Thus, if both $x^{-1}\beta(x)$ and $\beta(x)^{-1}\alpha(\beta(x))$  lie in $\ker(\lambda)$  for a given $x \in G$, then $x^{-1} (\alpha \beta)(x)  \in \ker(\lambda)$. Take $x = b = x_{j_{1}}^{\varepsilon_1}$, $\alpha = \varphi_{i_{1}}^{\epsilon_1}$ and $\beta = \varphi_{i_{2}}^{\epsilon_2} \cdots  \varphi_{i_{k}}^{\epsilon_k}$. Using the arguments mentioned above, it is easy to conclude that  $\beta(x)^{-1}\alpha(\beta(x)) \in \ker(\lambda)$.  It now remains to prove that $x^{-1}\beta(x) \in \ker(\lambda)$. But this follows by the  iterative process replacing, successively, $\alpha$ by $\varphi_{i_{r}}^{\epsilon_r}$ and $\beta$ by  $\varphi_{i_{r+1}}^{\epsilon_{r+1}} \cdots  \varphi_{i_{k}}^{\epsilon_k}$ for $2 \le r \le k-1$, and using the given hypothesis, \eqref{eqn1sec2}  and the above claim.  This completes the proof.
$\blacksquare$ 
\end{proof}

We construct skew  left braces on  groups admitting subgroups of index two. 

\begin{proposition} \label{abgr}
Let $(G, \cdot)$ be a group,  $B$  an index two subgroup of $G$ and $\phi \in \Aut(G, \cdot)$ an involution such that $\phi(B) = B$.  Then $(G, \cdot , \circ)$ is a skew  left brace, where 
$$
a \circ b =
\left\{
\begin{array}{ll}
a \cdot b \quad \quad  \textrm{if}~ a \in B~\textrm{and}~ b \in G,\\
a \cdot \phi(b) \quad   \textrm{if}~a \not\in B~\textrm{and}~ b \in G. &
\end{array}
\right.
$$
\end{proposition}

\begin{proof}
Consider the map $\lambda : (G, \cdot) \to \Aut(G, \cdot)$ given by
$$
\lambda_a =
\left\{
\begin{array}{ll}
\id \quad \textrm{if}~ a \in B, \\
\phi \quad \textrm{if}~ a \not\in B. &
\end{array}
\right.
$$
Note that $\lambda$ is a homomorphism. A straightforward calculation shows that $b^{-1} \cdot \lambda_a(b) \in \ker (\lambda)$ for all $a, b \in G$. Hence, by Theorem \ref{t1}, it follows that $H_{\lambda}$ is a regular subgroup of $\Hol (G, \cdot)$. Consequently, by Theorem \ref{gv2017}, $(G, \cdot, \circ)$ is a skew left brace with $\circ$ as given in the statement.
$\blacksquare$ 
\end{proof}
\para


Next, we construct some non-trivial $\lambda$-homomorphic left braces on free abelian groups. 

\begin{example}
{\rm The infinite cyclic group $(\mathbb{Z}, +)$ admits a non-trivial left brace structure with its multiplicative group structure given by
$$
m \circ n = m + (-1)^m n
$$
for $m, n \in \mathbb{Z}$  \cite{MR3957824, MR4003478}. Note that $\Aut(\mathbb{Z}, +) \cong \{ 1, -1\}$, where $1$ denotes the identity automorphism and $-1$ denotes multiplication by $-1$. Further,
$$
\lambda : (\mathbb{Z}, +) \to \Aut(\mathbb{Z}, +)
$$
is given by $\lambda_m = (-1)^m$, and  is a group homomorphism. It follows from Theorem \ref{t1} that $(\mathbb{Z}, +, \circ)$ is a $\lambda$-homomorphic left brace.}
\end{example}
\para

\begin{example}\label{fag}
{\rm We now construct  $\lambda$-homomorphic left braces on higher rank free abelian groups. Let $A  \cong \mathbb{Z}^n$ be the free abelian group of rank $n$ with free basis  $\{ x_1, \ldots, x_n \}$. For each $1 \le i \le n-1$, define $\varphi_i \in \Aut(A)$ by
$$
\varphi_i :
\left\{
\begin{array}{ll}
x_i \to x_i + x_n, &  \\
x_j \to x_j & ~\mbox{for} ~j \not= i,
\end{array}
\right.
$$
and let
$$\varphi_n = \id.$$
Note that, these automorphisms  are pairwise commuting, and hence the map $\lambda  : (A, +) \to \Aut(A, +)$ given by $\lambda_{x_i}=\varphi_i$ for each $i$, is a group homomorphism. Further, we have
$$
\lambda \big(\varphi_i(x_j)-x_j \big)=\id
$$
for all $1 \le i, j \le n$. Hence, it follows from Proposition \ref{redprop} and  Theorem \ref{t1} that
$$
H_{\lambda }= \big\{  (\lambda_a, a) \, \mid \, a \in A   \big\}=
 \left\{ \, \left(\prod_{i=1}^{n-1} \varphi_i^{\alpha_i}, ~\sum_{i=1}^n \alpha_i x_i \right)  \, \mid \,  \alpha_i \in \mathbb{Z}  \, \right\}
$$
is a regular subgroup of  $\Hol(A, +)$, where $a = \sum_{i=1}^n \alpha_i x_i$. Thus, by Theorem \ref{gv2017}, we obtain a $\lambda$-homomorphic left brace $(A, + , \circ )$, where $a \circ b = a+ \lambda_a(b)$ for $a, b \in A$.
\para 
Next, we investigate  the structure of the multiplicative group  $(A, \circ )$. Note that the two operations  $+$ and  $\circ$ agree on $ \ker(\lambda) =\left\langle x_n\right\rangle \cong \mathbb{Z}$. Further, for elements $a =  \sum_{i=1}^n \alpha_i x_i$ and $b = \sum_{i=1}^n \beta_i x_i$ of $(A, +)$, we have
\begin{eqnarray*}
a \circ b &=& a + \lambda_a(b) \\
&=& (\alpha_1 + \beta_1) x_1 + (\alpha_2 + \beta_2) x_2 + \cdots +(\alpha_{n-1} + \beta_{n-1}) x_{n-1} +\\
& & (\alpha_n + \beta_n + \alpha_1 \beta_1 + \alpha_2 \beta_2 + \cdots + \alpha_{n-1} \beta_{n-1}) x_n\\
& =&  b \circ a,
\end{eqnarray*}
which implies that $(A, \circ)$ is an abelian group. Moreover, the powers of the generators $x_i$ with respect to $\circ$ are given by
$$
x_i^{\circ k} = k x_i + \frac{k(k-1)}{2}x_n
$$
for each $1 \le i \le n-1$ and
$$
x_n^{\circ k} = k x_n
$$
for each $k \in \mathbb{Z}$. Thus, any element  $b = \sum_{i=1}^n \beta_i x_i$ of $(A,+)$ has the unique form
$$
b = x_1^{\circ \alpha_1} \circ \cdots \circ x_n^{\circ \alpha_n},
$$
where $\alpha_i = \beta_i$ for $ 1 \le  i \le n-1$ and
$$
\alpha_n = \beta_n - \sum_{j=1}^{n-1} \frac{\beta_j (\beta_j - 1 )}{2}.
$$
Hence,  we have $(A, \circ) \cong (A, +)$, and  there is a short exact sequence
$$
1 \to \ker(\lambda) \to (A, \circ) \to \mathbb{Z}^{n-1} \to 1.
$$}
\end{example}
\para


We now construct some $\lambda$-homomorphic skew left braces on non-abelian free groups.  

\begin{example}\label{homomorphic skew brace on free group}
{\rm 
Let $F_n = \langle x_1,\ldots,x_n \rangle$  be the free group of rank $n$. Let  $\varphi_1, \ldots, \varphi_n \in \Aut(F_n)$ be a set of pairwise commuting automorphisms such that
$$
x_i^{-1}\varphi_j(x_i)\in F_n'
$$
for all $1 \le i,j \le n.$ Let  $\lambda : F_n \to \Aut(F_n)$ be the homomorphism defined on the generators by
$$
\lambda_{x_i} = \varphi_i
$$
for  $1 \le i  \le n$. Clearly, $\ker(\lambda)$ contains the commutator subgroup  $[F_n, F_n]$ of $F_n$, and hence
$$
x_i^{-1}\varphi_j(x_i)\in \ker(\lambda)
$$
for all $1 \le i,j \le n$. It follows from Proposition \ref{redprop} that $b^{-1} \lambda_a (b)\in \ker(\lambda)$ for all  $a, b \in F_n$. Hence, by Theorem \ref{t1}, $H_{\lambda}= \{ (\lambda_a, a) \, \mid \, a \in F_n \}$ is a regular subgroup of  $\Hol(F_n)$. Thus, $( F_n, \cdot, \circ  )$ is a $\lambda$-homomorphic skew left brace with $a \circ b=a \cdot \lambda_a(b)$ for $a, b\in F_n$, where $\cdot$ is the product in $F_n$.}
\end{example}
\para

An automorphism $\alpha$ of a group $G$ is called an \index{IA-automorphism}{\it IA-automorphism} if $a^{-1}\alpha(a) \in [G, G]$ for all $a \in G$. The set $\IA(G)$ of all IA-automorphisms forms a subgroup of $\Aut(G)$.  Thus, the preceding construction  is valid for  any choice of pairwise commuting automorphisms $\varphi_1, \ldots, \varphi_n\in \IA(F_n)$. We now carry-out  this construction concretely for $n=4$.

\para

\begin{example} \label{fIA}
{\rm 
Let $F_4 = \langle x_1, x_2, x_3, x_4 \rangle$ be the free group of rank 4. For $u, v \in [F_4, F_4]$, let $\varphi_1, \varphi_2, \varphi_3, \varphi_4$ be automorphisms of  $F_4$ defined on free generators as 
$$
\varphi_1=\varphi_2 : \left\{
\begin{array}{ll}
x_1 \to x_1 u, &  \\
x_i \to x_i & \mbox{for} ~i \not= 1,
\end{array}
\right.
\quad \textrm{and}\quad
\varphi_3=\varphi_4 : \left\{
\begin{array}{ll}
x_i \to x_i & \mbox{for} ~i \not= 4.\\
x_4 \to x_4 v. &  \\
\end{array}
\right.
$$
It is not difficult to check that $\varphi_1 \varphi_3 = \varphi_3 \varphi_1$. Hence, by Example \ref{homomorphic skew brace on free group}, we get a skew left brace $(F_4, \cdot \; , \circ)$, for which the operation $\circ$ on free generators is given by
\begin{eqnarray*}
& x_1 \circ x_1=x_1^2u, \quad x_1 \circ x_2=x_1x_2,\quad x_1 \circ x_3=x_1x_3,\quad x_1 \circ x_4=x_1x_4,\\
& x_2 \circ x_1=x_2x_1u,\quad x_2 \circ x_2=x_2^2,\quad x_2 \circ x_3=x_2x_3,\quad x_2 \circ x_4=x_2x_4,\\
&x_3 \circ x_1=x_3x_1,\quad x_3 \circ x_2=x_3x_2,\quad x_3 \circ x_3=x_3^2,\quad x_3 \circ x_4=x_3x_4v,\\
&x_4 \circ x_1=x_4x_1,\quad x_4 \circ x_2=x_4x_2,\quad x_4 \circ x_3=x_4x_3,\quad x_4 \circ x_4=x_4^2v.
\end{eqnarray*}
The operations  $\cdot$ and  $\circ$ coincide  on  $[F_4, F_4]$. Note that the inverse $\bar x$ of an element $x$ with respect to $\circ$ is given by $\bar x =\lambda_x^{-1}(x^{-1})$. Hence, we have
$$
\bar x_1 = ux_1^{-1},\quad
\bar x_2 = x_2^{-1},\quad
\bar x_3 = x_3^{-1},\quad
\bar x_4 = v x_4^{-1}.
$$
We can write
$$
F_4= \sqcup~ x_1^{a_1}x_2^{a_2}x_3^{a_3}x_4^{a_4} \, [F_4, F_4],
$$
where  $a_1, a_2, a_3, a_4 \in \mathbb{Z}$ and
$$
x_1^{a_1}\circ x_2^{a_2}\circ x_3^{a_3}\circ x_4^{a_4}\equiv
x_1^{a_1}x_2^{a_2}x_3^{a_3}x_4^{a_4}\, \mod \, [F_4, F_4].
$$
Hence, it follows that
$$
(F_4, \circ)= \sqcup~ x_1^{a_1}\circ x_2^{a_2}\circ x_3^{a_3}\circ x_4^{a_4} \,[(F_4, \circ), (F_4, \circ)]
$$
is a decomposition of  $(F_4, \circ)$ into disjoint union of left cosets of $[(F_4, \circ), (F_4, \circ)]$, which gives
$$
(F_4, \circ)/[(F_4, \circ), (F_4, \circ)] \cong \mathbb{Z}^4.
$$}
\end{example}
