\section{Lambda-cyclic skew braces} \label{lambda-cyc}

We begin this section with the following definition.

\begin{definition}
A $\lambda$-homomorphic skew  left brace $(G, \cdot, \circ)$ is said to be \index{$\lambda$-cyclic skew brace}{$\lambda$-cyclic} if the image of $\lambda$ is a cyclic subgroup of $\Aut (G, \cdot)$.
\end{definition}

Let $G$ be a group with a presentation $G = \langle S\mid R \rangle,$ where $S= \{ g_1, g_2,g_3, \ldots \}$ is the set of generators and $R = \{ r_1, r_2, r_3, \ldots \}$ is the set of defining relations. Then any element  $w\in G$ can be written as
\begin{equation} \label{w}
w = g_{i_1}^{\alpha_1} g_{i_2}^{\alpha_2} \ldots g_{i_s}^{\alpha_s}
\end{equation}
for some $g_{i_j} \in S$ and $\alpha_j \in \mathbb{Z}$. We define the \index{logarithm of a word}{\it logarithm} $\mathfrak{L}(w)$ of $w$ as 
$$
\mathfrak{L}(w) = \sum_{j=1}^s \alpha_j.
$$

A presentation $G = \langle S\mid R \rangle$ is called a \index{homogeneous presentation}{\it homogeneous presentation} if  $\mathfrak{L}(r_i) = 0$ for all $r_i \in R$. A group is said to be a \index{homogeneous group}{\it homogeneous group} if it admits a homogeneous presentation. It is not difficult to see that for a homogeneous group $G$, the logarithm $$\mathfrak{L} : G \to \mathbb{Z}$$ is well-defined. In fact, the map $\mathfrak{L} : G \to \mathbb{Z}$ is well-defined for each group $G$ which is free in some variety. Note that a homogeneous group can have torsion. For example, the relation $(g_i g_j^{-1})^2 = 1$ has zero logarithm,  but the element $g_i g_j^{-1}$ has finite order.

\begin{example}{\rm 
Consider the following examples:
\begin{enumerate}
\item Any free group, free solvable group and free nilpotent group is homogeneous.
\item If $L$ is a link in  $\mathbb{S}^3$, then the Wirtinger presentation of the link group $G(L) = \pi_1(\mathbb{S}^3 \setminus L)$ is homogeneous.
\end{enumerate}}
\end{example}

\begin{lemma} \label{l1}
Let $G$ be a homogeneous group admitting a homogeneous presentation $G=\langle S\mid R \rangle$. Let $\varphi \in \Aut (G)$ be such that
$\mathfrak{L}(\varphi (g_i)) = 1$ for all $g_i \in S.$ Then the following  assertions hold for all $u, v, w \in G$:
\begin{enumerate}
\item  $\mathfrak{L}(u v) = \mathfrak{L}(u) + \mathfrak{L}(v)$.
\item  $\mathfrak{L}(u^{-1}) = -\mathfrak{L}(u)$.
\item  $\mathfrak{L} (\varphi^k (w)) = \mathfrak{L}(w)$ for any integer $k$.
\end{enumerate}
\end{lemma}

\begin{proof}
The first and second assertions follow directly from the definition of the logarithm. Clearly, it is sufficient to prove the  third assertion for  $k=1$. Suppose that $w = g_{i_1}^{\alpha_1} g_{i_2}^{\alpha_2} \ldots g_{i_s}^{\alpha_s}$ for some $g_{i_j} \in S$ and $\alpha_j \in \mathbb{Z}$. Since 
$$\varphi(w) = \varphi(g_{i_1})^{\alpha_1} \varphi(g_{i_2})^{\alpha_2} \cdots \varphi(g_{i_s})^{\alpha_s},$$
using the first two assertions and the property of  $\varphi$, we get
\begin{eqnarray*}
\mathfrak{L} \big(\varphi(w) \big) &=& \alpha_1 \mathfrak{L} \big(\varphi(g_{i_1})\big) + \alpha_2 \mathfrak{L} \big(\varphi(g_{i_2})\big) + \cdots + \alpha_s \mathfrak{L} \big(\varphi(g_{i_s})\big) \\
&=& \alpha_1  + \alpha_2  + \cdots + \alpha_s\\
& =& \mathfrak{L}(w),
\end{eqnarray*}
which is desired. $\blacksquare$ 
\end{proof}


\begin{proposition} \label{lcb}
Let $G$ be a homogeneous group admitting a homogeneous presentation $G= \langle S\mid R\rangle$. Let $\varphi \in \Aut (G)$ be such that $\mathfrak{L}(\varphi (g_i)) = 1$ for all $g_i \in S.$ Then the set
$
H_{\lambda} = \big\{ (\varphi^{\mathfrak{L}(w)}, w)  \, \mid \, w \in G \big\}
$
is a regular subgroup of $\Hol (G)$.
\end{proposition}

\begin{proof}
By Lemma \ref{l1}(1), the map
$$
\lambda : G \to \Aut (G),
$$
given  by  $\lambda(w) = \varphi^{\mathfrak{L}(w)}$, is a group homomorphism. By Lemma \ref{l1}(3), we  get   $\lambda \big(w^{-1}\cdot  \lambda_u(w)\big) = \id$ for all $u, w \in G$.  It now follows from  Theorem \ref{t1} that   $H_{\lambda} = \big\{(\varphi^{\mathfrak{L}(w)}, w) \, \mid \, w \in G \big\}$ is a regular subgroup of
$\Hol (G)$. $\blacksquare$ 
\end{proof}

Let us see an example satisfying the hypothesis of Proposition \ref{lcb}.

\begin{example}{\rm 
The free group $F_n=\langle x_1, \ldots, x_n \rangle$ of rank $n$ is homogeneous. Let $\theta$ be an $\IA$-automorphism of  $F_n$. It follows that $\mathfrak{L}(\theta(x_i)) = 1$ for all $i$. Let $\lambda : F_n \to \Aut(F_n)$ be the homomorphism defined on the free generators as
 $$
\lambda(x_i)=\theta
$$
for all $1 \le i  \le n$. Hence, by Proposition \ref{lcb}, the set $H_{\lambda}$ is a regular subgroup of  $\Hol(F_n)$.}
\end{example}

The following example shows that Proposition \ref{lcb} does not work for all automorphisms of $F_n$.


\begin{example}{\rm 
Let   $\theta$ be the automorphism of $F_n=\langle x_1, \ldots, x_n \rangle$ defined on its free generators as
$$
\theta(x_i)= 
\left\{
\begin{array}{ll}
x_1x_2 & ~\mbox{if} ~i=1, \\
x_i & ~\mbox{if} ~i \neq 1.
\end{array}
\right.
$$
Then, we have
$$
\lambda \big(x_1^{-1}\lambda_{x_2}(x_1)\big) = \lambda \big(x_1^{-1} \theta(x_1)\big) = \lambda(x_2) = \theta \ne \id.
$$
Hence, by Theorem \ref{t1}, $H_{\lambda}$ is not a subgroup of $\Hol( F_n)$. Note that, in this case,  $\mathfrak{L}(\theta(x_1)) = 2$.}
\end{example}

The subsequent result is straightforward.

\begin{proposition}\label{impprop}
Let   $\theta$ be the automorphism of $F_n=\langle x_1, \ldots, x_n \rangle$ defined on its free generators as
\begin{eqnarray*}
\theta(x_i) &=&  x_{\sigma(i)} u_i\,  \mbox{for some } u_i \in F_n'\; \mbox{and some permutation } \sigma \in \Sigma_n\\
\textrm{or} &  &\\
\theta(x_i) &=&  x_{\sigma(i)}^{-1} u_i\,  \mbox{for some } u_i \in F_n'\; \mbox{and some permutation } \sigma \in \Sigma_n \; \mbox{and } \theta^2 =1.
\end{eqnarray*}
Let $\lambda : F_n\to \Aut(F_n)$ be the homomorphism given by $\lambda(x_i)=\theta$ for all $i$. Then $H_\lambda$ is a regular subgroup of $\Hol(F_n)$.
\end{proposition}

\begin{proof}
Let $\theta(x_i) =  x_{\sigma(i)} u_i$ for some $u_i \in F_n'$ and some permutation $\sigma \in \Sigma_n$. Let $\lambda : F_n \to \Aut (F_n)$
be the homomorphism given by $\lambda(w) = \theta^{\mathfrak{L}(w)}$. If $\lambda_a(b) = \theta^{\mathfrak{L}(a)}(b) = c$, then we see that $\mathfrak{L}(c) = \mathfrak{L}(b)$. This gives
$$
\lambda \big(b^{-1}\lambda_a(b) \big)= \lambda (b^{-1} c) = \theta^{\mathfrak{L}(b^{-1} c)}  =\theta^{-\mathfrak{L}(b)} \, \theta^{\mathfrak{L}(c)} = \theta^{-\mathfrak{L}(b)}\,  \theta^{\mathfrak{L}(b)}
= 1.
$$
Hence, by Theorem \ref{t1}, $H_{\lambda}$ is a regular subgroup of $\Hol( F_n)$. The second case is similar.  $\blacksquare$ 
\end{proof}
\para


The rest of the section is focussed on constructing Lambda-cyclic skew left braces on the free group of rank two with respect to specific automorphisms. We begin with the following result \cite[Proposition 3.10]{MR4346001}.

\begin{proposition} \label{fp}
Let $F_2=\langle x, y \rangle$ be the free group of rank two and $\theta\in \Aut(F_2)$  such that  $\theta(x)=y$ and $\theta(y)=x$. Let $H_0$ be the kernel of the homomorphism  $F_2 \to  \Aut(F_2)$ given by $x,y \mapsto \theta$. If $\cdot$ denote the product in $F_2$ and
$$
a\circ b=
\left\{
\begin{array}{ll}
  ab & \textrm{if}~ a\in H_0~\textrm{and}~b \in F_2,\\
  a\theta(b) & \textrm{if}~ a\not\in H_0~\textrm{and}~b \in F_2, \\
\end{array}
\right.
$$
then $(F_2, \cdot, \circ )$ is a skew left brace with $(F_2, \circ) \cong (F_2, \cdot)$.
\end{proposition}

\begin{proof}
Let $\lambda : (F_2, \cdot)\to \Aut(F_2, \cdot)$ be the homomorphism given by $\lambda(x)=\lambda(y)=\theta$. Then $\theta$ satisfies the hypothesis of Proposition \ref{impprop}, and therefore $H_{\lambda}$ is a regular subgroup of  $\Hol(F_2, \cdot)$.  By Reidemeister-Schreier method \cite[Theorem 2.6]{MR0207802}, it follows that $H_0 = \langle xy, yx, x^2, y^2 \rangle$. Note that  $(H_0, \cdot)$ is a free group with free generators $\{xy, x^2,xy^{-1} \}$, and has index two in $(F_2, \cdot)$. Since $(F_2, \cdot)$ is a normal subgroup of $\Hol(F_2, \cdot)$, it follows that $H_{\lambda}$ and $F_2$ are not conjugate in $\Hol(F_2, \cdot)$. Further, since $\lambda_a = \id$ for $a \in H_0$, we see that $( F_2, \cdot, \circ )$ is a skew  left brace with
$$
a\circ b=
\left\{
\begin{array}{ll}
  ab & \textrm{if}~ a\in H_0 ~\textrm{and}~b \in F_2,\\
  a\theta(b) & \textrm{if}~ a\not\in H_0~\textrm{and}~b \in F_2. \\
\end{array}
\right.
$$
Note that the binary operations $\circ$ and $\cdot$ coincide on $H_0$, and hence $(H_0, \circ)$ is a free group of rank three. We claim that $(F_2, \circ)$ is torsion-free. Note that  $H_0$  is a normal and free subgroup of  $(F_2,  \circ)$ of index two. Thus, if $(F_2,  \circ)$ has an element of finite order, then it must be an element of order two. Let $1 \ne a \in F_2$ such that $a\circ a= 1$.
Then $a=xa_0$ for some $a_0 \in H_0$  and $xa_0y \theta(a_0)= a \circ a = 1$. Since $\mathfrak{L} \big(xa_0y \theta(a_0)\big)=\mathfrak{L}(1)$, we have
$$
2+ \mathfrak{L}(a_0) + \mathfrak{L} \big(\theta(a_0)\big)=0.
$$
Noting that $\mathfrak{L}(a_0)+ \mathfrak{L} \big(\theta(a_0)\big)\equiv 0 \mod 4$, we get $2\equiv 0 \mod 4$, which is absurd. Hence, $(F_2,  \circ)$ does not admit any torsion element. It is a well-known result that a finitely generated torsion free group admitting a free subgroup of finite index is itself free (see \cite{MR0228573} and \cite[Theorem B]{MR0240177}). Hence, $(F_2, \circ)$ is a free group. Using the facts that $\mathrm{rank}(H_0, \circ)=3$, $|(F_2,  \circ): (H_0, \circ)|=2$ and the well-known formula
$$
\mathrm{rank}(H_0, \circ)=1+\big(\mathrm{rank}(F_2,  \circ)-1\big)~ |(F_2,  \circ): (H_0, \circ)|,
$$
we see that  $\mathrm{rank}(F_2,  \circ)=2$. This proves that $(F_2, \circ) \cong (F_2, \cdot)$.
$\blacksquare$ 
\end{proof}

\begin{proposition} \label{fi}
Let  $F_2 = \langle x, y \rangle$ be the free group of rank two and  $\theta \in \Aut(F_2)$  such that $\theta(x)= x^{-1}$ and $\theta(y)= y^{-1}$. Let
$H_0$ be  the kernel of the homomorphism  $F_2 \to \Aut(F_2)$ given by $x, y \mapsto \theta$. If $\cdot$ denote the product in $F_2$ and
$$
a\circ b=
\left\{
\begin{array}{ll}
  ab &    \textrm{if}~ a\in H_0~\textrm{and}~b \in F_2,\\
  a\theta(b) & \textrm{if}~ a\not\in H_0~\textrm{and}~b \in F_2, \\
\end{array}
\right.
$$
then $(F_2, \cdot, \circ )$ is a skew left brace. Moreover, 
$$
(F_2, \circ) \cong F_3 \rtimes \mathbb{Z}_2 \cong \left\langle\, p,q,r,s  \, \mid \,  s^2=1,\,\, sps=p^{-1},\,\, sqs=q^{-1},\,\, srs=pr^{-1}p^{-1}\, \right\rangle.
$$
\end{proposition}

\begin{proof}
Let $\lambda :  (F_2, \cdot) \to \Aut(F_2, \cdot)$ be the homomorphism given by $\lambda(x) = \lambda(y)=\theta$. Then, by Proposition \ref{impprop}, $H_{\lambda}$ is a regular subgroup of  $\Hol(F_2, \cdot)$. Note that the subgroup   $(H_0, \cdot)$ consists of words of even length. Since $(F_2, \cdot)$ is a normal subgroup of $\Hol(F_2, \cdot)$, it follows that  $H_{\lambda}$ and $F_2$ are not conjugate in $\Hol(F_2, \cdot)$. Since $\lambda_a = \id$ for all $a \in H_0$, it follows that $( F_2, \cdot, \circ )$ is a skew left brace with
$$
a\circ b=
\left\{
\begin{array}{ll}
  ab &  \textrm{if}~ a\in H_0~\textrm{and}~b \in F_2,\\
  a\theta(b) &   \textrm{if} ~ a\not\in H_0~\textrm{and}~b \in F_2. \\
\end{array}
\right.
$$
We now determine  the structure of  $(F_2, \circ)$. Note  that $x \circ x = 1= y \circ y$ and $(F_2, \circ)$ is generated by $\{H_0, x\}$. Since $x \circ x=1$ and $H_0$ is normal in  $(F_2, \circ)$, it follows that
$$
(F_2, \circ) \cong H_0 \rtimes \mathbb{Z}_2,
$$
where $\mathbb{Z}_2 \cong \left\langle s \right\rangle$ for $s \not\in H_0$. Note that  $H_0$ is freely generated by $\{p, q, r \}$, where
$$
p= xy,\quad q=x^2\quad \textrm{and}\quad r=y^2.
$$
To avoid confusion, let us denote $x$ in $(F_2, \circ)$ by $s$. Then, we have the conjugation relations
$$
sps=p^{-1},\quad sqs=q^{-1}\quad \textrm{and}\quad  srs=pr^{-1}p^{-1}.
$$
Hence,  $(F_2, \circ)$ has the  presentation
$$
(F_2, \circ)  \cong \left\langle\, p,q,r,s  \, \mid \,  s^2=1,\,\, sps=p^{-1},\,\, sqs=q^{-1},\,\, srs=pr^{-1}p^{-1}\, \right\rangle,
$$
and the proof is complete. $\blacksquare$ 
\end{proof}

\begin{remark}
{\rm 
Propositions \ref{fp} and \ref{fi} provide examples satisfying the hypothesis of Proposition \ref{abgr}. Further, the $\lambda$-cyclic skew  left braces constructed in  Propositions \ref{fp} and \ref{fi} are not isomorphic. In fact, in the first case $(F_2, \circ) \cong F_2$, while in the second case $(F_2, \circ) \cong F_3 \rtimes \mathbb{Z}_2$. But the socles and the quotients by the socles for these skew  left braces are isomorphic.
}
\end{remark}


For abelian groups, we have the following result.

\begin{proposition} \label{abgr1}
Let $(A, + )$ be an abelian group admitting a subgroup $B$ of index two such that $A=B \cup (a_0 + B)$
for some  $a_0 \in A$.  Then $(A, + , \circ)$ is a left brace, where
$$
a \circ b =
\left\{
\begin{array}{ll}
a + b & \textrm{if}~ a \in B~\textrm{and}~b \in A,\\
a - b &   \textrm{if}~ a \not\in B~\textrm{and}~b \in A. 
\end{array}
\right.
$$
Moreover,  $(A, \circ) \cong (B, +) \rtimes \mathbb{Z}_2$.
\end{proposition}

\begin{proof}
Let $( A, +)$ be an abelian group and  $\theta$ the automorphism given by  $\theta (a)=-a$ for all $a \in A$. Since $\theta^2 = \id$  and $\theta(B) = B$, it follows from Proposition \ref{abgr} that $(A, + , \circ)$ is a left brace, where $\circ$ is as given in the statement of the proposition. Note that $a_0 \circ a_0 = 0$, where $0$ is the identity element of $(A, +)$. Thus, we have $\bar a_0 = a_0$, and therefore $\bar a_0 \circ b \circ a_0 = -b$ for all $b \in B$. Since the operations $\circ$ and $+$ coincide on $B$, it follows that $(A, \circ) \cong (B, +) \rtimes \mathbb{Z}_2$.
$\blacksquare$ 
\end{proof}

Let $A = \mathbb{Z}_2 \times \mathbb{Z}_4$, where $\mathbb{Z}_2= \langle a \rangle$ and  $\mathbb{Z}_4=\langle b \rangle$. Let $B_1 = \langle b \rangle = \mathbb{Z}_4$ and $B_2 = \langle a \rangle \times \langle b^2 \rangle = \mathbb{Z}_2 \times \mathbb{Z}_2$. Obviously, $B_1$ and $B_2$ are not isomorphic, and hence  the left braces constructed from $B_1$ and $B_2$ using Proposition \ref{abgr1} are not isomorphic. We conclude this section with the following questions.

\begin{question}
Under what conditions are the left braces, constructed from two subgroups of index two in an abelian group, isomorphic?
\end{question}

\begin{question} 
Is it possible to construct a skew left brace merely with the information that its additive group admits  a subgroup of index two?
\end{question}
