\section{Lambda-cyclic braces on free abelian groups} \label{cyc-ab}

Consider the free abelian group
$$
\mathbb{Z}^n=\big\{ \, m_1x_1+\cdots + m_nx_n  \, \mid \,  m_1, \ldots , m_n \in   \mathbb{Z}    \big\}
$$
 of rank  $n$ with free basis  $\{x_1,\ldots, x_n\}$. For $a = m_1x_1+ \cdots + m_n x_n \in \mathbb{Z}^n$, we define 
 $$\mathfrak{L}(a) = \sum_{i=1}^{n}m_i.$$ 
Let $\varphi$ be an automorphism of $\mathbb{Z}^n$ and $\lambda: \mathbb{Z}^n \to \Aut(\mathbb{Z}^n)$ the map given by $a \mapsto \lambda_a= \varphi^{\mathfrak{L}(a)}$. Then $\lambda_{x_i} = \varphi$ for each $1 \le i \le n$. Let $H_{\lambda} = \{\,(\lambda_a, a) \, \mid \, a \in \mathbb{Z}^n \,\}$ and 
$$\mathbb{Z}_0^n = \big\{ a \in \mathbb{Z}^n \, \mid \, \mathfrak{L}(a) = 0  \big\}.$$
Note that $\mathbb{Z}_0^n$ is a subgroup of $\mathbb{Z}_0$.
\para


\begin{proposition} \label{cycprop1}
Let $\mathbb{Z}^n$ be the free abelian group of rank $n$ with free basis  $\{x_1,\ldots, x_n\}$ and $\varphi \in \Aut(\mathbb{Z}^n)$. If $\varphi(x_i) \equiv x_i \mod \mathbb{Z}^n_0$ for each $1 \le i \le n$, then  $H_{\lambda}$ is a regular subgroup of  $\Hol(\mathbb{Z}^n)$. Conversely, if $\varphi$ is of infinite order such that   $H_{\lambda}$ is a regular subgroup of  $\Hol(\mathbb{Z}^n)$, then $\varphi(x_i) \equiv x_i \mod \mathbb{Z}^n_0$ for each $1 \le i \le n$.
\end{proposition}

\begin{proof}
If $\varphi(x_i) \equiv x_i \mod \mathbb{Z}^n_0$ for each $1 \le i \le n$, then it follows from Proposition \ref{lcb} that $H_{\lambda}$ is a regular subgroup of  $\Hol(\mathbb{Z}^n)$.
\para
Suppose that $H_{\lambda}$ is a subgroup of $\Hol(\mathbb{Z}^n)$. Then
$$
(\varphi, x_i) (\varphi, x_j)=\big(\varphi^2,~ x_i+\varphi(x_j) \big)\in H_{\lambda}
$$
for each $1 \le i, j \le n$, which implies that $\mathfrak{L}(x_i+\varphi(x_i)) = 2$ for each $1 \le i \le n$. Hence, if
\begin{equation}\label{varphix expression}
\varphi(x_i)=m_{i1}x_1 + \cdots + m_{in}x_n   
\end{equation}
for some $m_{i1},\ldots , m_{in}\in \mathbb{Z}$, then  $m_{i1} + \cdots + m_{in}=1$ for each $1 \le i \le n$.  Subtracting $x_i$ on both the sides of \eqref{varphix expression} gives
$$
\varphi(x_i)\equiv x_i \mod \mathbb{Z}^n_0
$$
for each $1 \le i \le n$, which proves the converse. $\blacksquare$ 
\end{proof}


\begin{example}{\rm 
The converse statement in Proposition \ref{cycprop1} does not hold if $\varphi$ is of finite order. Let $\mathbb{Z}^2$ be the free abelian group with free basis $\{x_1, x_2 \}$. Consider the automorphism $\psi$ of $\mathbb{Z}^2$ given by $\psi(x_1) = x_1$ and $\psi(x_2) = -x_2.$ Then $H_{\lambda}$ is a regular subgroup of  $\Hol(\mathbb{Z}^2)$, but $\psi(x_2) \not\equiv x_2 \mod \mathbb{Z}^2_0$.}
\end{example}
\para

Our next result is the following theorem \cite[Theorem 4.10]{MR4346001}.

\begin{theorem} 
Let $A \cong (\mathbb{Z}^n, +)$ be the free abelian group of rank $n\geq 2$ with free basis $\{x_1,  \ldots,x_n\}$ and  $\psi \in \Aut(A)$ the  automorphism defined by
$$
\psi :
\left\{
\begin{array}{ll}
x_i \to x_{i+1} &    \textrm{if}~ i \ne n,\\
x_n \to x_1. &
\end{array}
\right.
$$
Let $\lambda : A \to \Aut(A)$ be the group homomorphism given by  $a \mapsto \lambda_a= \psi^{\mathfrak{L}(a)}$ for all $a \in A$.  Then $(A, +, \circ)$ is a $\lambda$-cyclic left brace with
$$
a\circ b=a+\psi^{\mathfrak{L}(a)} (b)
$$
for $a , b \in A.$ Moreover,
$$
(A, \circ) = \big\langle \, x,\,z  \, \mid \,  [x^{\circ n},z] = 1,\,(z \circ x)^{\circ n}=x^{\circ n}, \,
[z,x^{\circ k}, z]=1 ~~ \textrm{for all}~~  1 \le k \le n-2 \big\rangle,
$$
where  $x=x_1$ and $z=x_2-x_1$.
\end{theorem}

\begin{proof}
Note that $A$ is a homogeneous group such that $\mathfrak{L} \big(\psi (x_i) \big) = 1$ for each $1 \le i \le n$. Then, by Proposition \ref{lcb}, $H_{\lambda}$ is a regular subgroup of $\Hol(A)$.  Thus, we obtain a $\lambda$-cyclic left brace $(A, +, \circ)$, where 
$$
a \circ b = a+\psi^{\mathfrak{L}(a)}(b)
$$
for all $a , b  \in A$.
\para 
We now determine the structure of the multiplicative group $(A, \circ)$. Note that
$$
x_1 \circ x_2=x_1+x_3 \;\;\mbox{ and } \;\; x_2 \circ x_1=2x_2,
$$
and hence $(A, \circ)$ is a non-abelian group. Consider the subgroup
$$
A_0 =
\left\{ \, \sum\limits_{i=1}^{n} \alpha_i x_i \in A  \, \mid \, 
\sum\limits_{i=1}^{n} \alpha_i \equiv 0 \mod n  \, \right\}
$$
of $A$. It is not difficult to see that $A_0 = \ker( \lambda)$, and hence the two operations $+$ and $\circ$ coincide on $A_0$. We have the decomposition 
$$
A =A_0 \cup (x_1 + A_0) \cup (2x_1 + A_0) \cup \cdots \cup \big((n-1) x_1 + A_0 \big)
$$
of  $A$ as a union of cosets of $A_0$. Since $\psi(A_0)=A_0$, it follows that
$$
(kx_1)\circ A_0 =(kx_1) + A_0
$$
for each $k\in \mathbb{Z}$. Hence, we obtain the decomposition 
$$
(A, \circ)= A_0 \cup (x_1 \circ A_0) \cup (2x_1 \circ A_0) \cup \cdots \cup \big((n-1)x_1 \circ A_0 \big)
$$
of   $(A, \circ)$  as a union of cosets  of $A_0$. Observe that
$$
kx_1\equiv x_1^{\circ k} \mod A_0
$$
for each $1 \le k \le n$. Hence, we can write
$$
(A, \circ) = A_0 \cup (x_1\circ A_0) \cup (x_1^{\circ 2} \circ A_0) \cup \cdots \cup (x_1^{\circ (n-1)} \circ A_0),
$$
and  therefore $(A, \circ)$ is generated by the element  $x_1$ and the subgroup  $(A_0, \circ)$. We take
$$
\big\{z_1:=x_1+\cdots+x_n, ~~ z_2:=x_2-x_1, \ldots,  z_n:=x_n-x_{n-1} \big\}
$$
as a set of free generators of  $(A_0, \circ)$. Let $[a, b]$ denote the element $\bar a \circ \bar b \circ a \circ b$ for all $a , b \in (A, \circ)$. A direct check shows that we have the relations
\begin{eqnarray*}
x_1^{\circ n}  & =& z_1,\\
\left[ z_i, z_j \right] & =& 1 \quad \textrm{for}~~ 1 \le i, j \le n,\\
x_1\circ z_k & =& x_1\circ (x_k-x_{k-1})=x_1+ x_{k+1}-x_k =z_{k+1}+x_1=z_{k+1}\circ x_1 \quad \textrm{for}~~2 \le k \le n-1,\\
x_1\circ z_n & =& x_1\circ (x_n-x_{n-1})=x_1+x_1-x_n=(x_1-x_n) \circ x_1= (\overline{z_2+z_3+\cdots+z_n}) \circ x_1= \bar z_2\circ \bar z_3\circ \cdots \circ \bar z_n \circ x_1.
\end{eqnarray*}
This shows that  $(A, \circ)$ has a presentation
\begin{eqnarray*}
(A, \circ) &= & \Big\langle x_1,z_1,\ldots,z_n  \, \mid \,  z_1=x_1^{\circ n},~~x_1 \circ z_n  \circ \bar x_1 = \bar z_2 \circ \bar z_3 \circ \cdots \circ \bar z_n,~~ [z_i,z_j]=1 ~~\textrm{for}~~1 \le i,j \le n,\\
& &  x_1 \circ z_k \circ \bar x_1=z_{k+1}
~~\textrm{for}~~2 \le k \le n-1 \Big\rangle.
\end{eqnarray*}
To simplify the presentation of $(A, \circ)$, we note that
\begin{eqnarray*}
(A, \circ) &=& \Big\langle \, x_1,z_2,\ldots,z_n  \, \mid \,  [x_1^{\circ n},z_2]= \cdots  = [x_1^{\circ n},z_n]=1,\,\, [z_i,z_j]=1 ~~\textrm{for}~~2 \le i,j \le n, \\
& & z_3=x_1 \circ z_2 \circ \bar x_1, \ldots, z_n=x_1 \circ z_{n-1} \circ \bar x_1,\,\,
x_1 \circ z_n \circ \bar x_1 = \bar z_2 \circ \bar z_3 \circ \cdots \bar \circ z_n \Big\rangle\\
&=& \left\langle \, x_1,\,\,z_2 ~ \, \mid \, ~
[x_1^{\circ n},z_2]=[x_1^{\circ n},x_1\circ z_2 \circ \bar x_1]= \cdots = [x_1^{\circ n},x_1^{\circ(n-2)} \circ z_2 \circ \bar x_1^{\circ (n-2)}]=1, \right.\\
& &
[z_2,x_1 \circ z_2 \circ \bar x_1]= \cdots = [z_2,x_1^{\circ (n-2)} \circ z_2 \circ \bar x_1^{\circ (n-2)}]=1, \;\ldots,\\
& &[x_1^{\circ(n-3)} \circ z_2 \circ \bar x_1^{\circ(n-3)},x_1^{\circ (n-2)}\circ z_2\circ \bar x_1^{\circ(n-2)}]=1,\\
& & \left. x_1^{\circ (n-1)}\circ z_n \circ \bar x_1^{\circ (n-1)}=\overline{z_2 \circ x_1\circ z_2 \circ \bar x_1 \circ \cdots \circ x_1^{\circ (n-2)}\circ z_2 \circ \bar x_1^{\circ (n-2)}}
\,\right\rangle.
\end{eqnarray*}
Setting  $x = x_1$ and $z = z_2$, we get
\begin{eqnarray*}
(A, \circ) &=& \left\langle \, x,\, z  \, \mid \,  [x^{\circ n},z]=1,\, [z, x\circ z \circ \bar x]= \cdots =[z, x^{\circ (n-2)}\circ z \circ \bar x^{\circ (n-2)}]=1, \right.\\
& & \left. \bar x \circ z \circ  x= \overline{(z \circ x)^{\circ (n-1)} \circ \bar x^{\circ (n-1)}}
\,\right\rangle\\
&=& \Big\langle \, x,\, z  \, \mid \,  [x^{\circ n},z]=1,\, [z, x^{\circ k}\circ z \circ \bar x^{\circ k}]=1 ~~\textrm{for}~~1 \le k \le n-2, \\
& &\bar x \circ z \circ x = x^{\circ (n-1)} \circ (\overline{z \circ x})^{\circ (n-1)} \Big\rangle\\
& = &
\big\langle \, x,\,z  \, \mid \,  [x^{\circ n}, z]=1,\, [z, x^{\circ k}\circ z \circ \bar x^{\circ k}]=1 ~~\textrm{for}~~1 \le k \le n-2,~~ (\overline{z \circ x})^{\circ n}=\overline{x}^{\circ n} \big\rangle.
\end{eqnarray*}
Observing that
\begin{eqnarray*}
[z,x^{\circ k}\circ z\circ \bar x^{\circ k}] = x^{\circ k} \circ [\bar x^{\circ k}\circ z\circ x^{\circ k}, z]\circ \bar x^{\circ k} = x^{\circ k} \circ [z, [z, x^{\circ k}], z] \circ \bar x^{\circ k}
=x^{\circ k}\circ [z,x^{\circ k}, z] \circ \bar x^{\circ k},
\end{eqnarray*}
 we obtain 
$$
(A, \circ) = \big\langle \, x,\,z  \, \mid \,  [x^{\circ n},z] = 1,\,(z \circ x)^{\circ n}=x^{\circ n},\,
[z,x^{\circ k}, z]=1 ~~\textrm{for all}~~1 \le k \le n-2 \big\rangle.
$$
This completes the proof of the theorem. $\blacksquare$ 
\end{proof}
\para


We conclude this section by  constructing some non-isomorphic $\lambda$-cyclic left braces on $\mathbb{Z}^2$ \cite[Theorem 4.9]{MR4346001}.

\begin{theorem}\label{cyclic left braces on Z2}
Let $(\mathbb{Z}^2, +)$ be the free abelian group with free basis  $\{x_1,x_2\}$ and $\varphi \in \Aut (\mathbb{Z}^2, +)$ such that
\begin{equation}\label{varphi x cong x condition}
\varphi(x_1) \equiv x_1 \mod \mathbb{Z}^2_0 \quad \textrm{and} \quad \varphi(x_2) \equiv x_2 \mod \mathbb{Z}^2_0.
\end{equation}
Let  $\lambda :\mathbb{Z}^2 \to \Aut (\mathbb{Z}^2)$ be the group homomorphism defined by $a \mapsto \lambda_a = \varphi^{\mathfrak{L}(a)}$ for all $a \in \mathbb{Z}^2$. Then $(\mathbb{Z}^2, +, \circ)$ is a $\lambda$-cyclic left brace such that either $(\mathbb{Z}^2, \circ) \cong (\mathbb{Z}^2 , +)$ or $(\mathbb{Z}^2, \circ)$ is isomorphic to the fundamental group of the Klein bottle. 
\par
Moreover, for an automorphism of $(\mathbb{Z}^2, +)$ satisfying \eqref{varphi x cong x condition}, these are the only possibilities for the multiplicative group of a $\lambda$-cyclic left brace $(\mathbb{Z}^2, +, \circ)$.
\end{theorem}

\begin{proof}
Observe that  $\mathbb{Z}^2_0$ is generated by $x_1-x_2$. Since $\varphi$ satisfies
$$
\varphi(x_1) \equiv x_1 \mod \, \mathbb{Z}^2_0 \quad   \textrm{and} \quad \varphi(x_2) \equiv x_2 \mod \, \mathbb{Z}^2_0,
$$
we can write
$$
\varphi(x_1)=x_1+p(x_1-x_2) \quad   \textrm{and} \quad \varphi(x_2)=x_2+q(x_1-x_2)
$$
for some integers  $p$ and $q$. Since $\varphi$ is an automorphism, we have
$$
\det \big([\varphi]\big)=p-q+1=\pm 1,
$$
where $[\varphi]$ is the matrix of $\varphi$ with respect to  the basis $\{x_1, x_2\}$. Hence, we have either $q=p$ or $q=p+2$, and therefore
$$
[\varphi]=\left(%
\begin{array}{cc}
  1+p & -p \\
  p & 1-p
\end{array}%
\right)
\quad
\mbox{or}
\quad
[\varphi]=\left(%
\begin{array}{cc}
  1+p & -p \\
  p+2 & -1-p
\end{array}%
\right).
$$
\para

In the first case,  $\varphi$ has infinite order and takes the form
\begin{equation}\label{sec4eqn1}
\varphi : \left\{
\begin{array}{l}
x_1 \mapsto (1+p) x_1 - p x_2,\\
x_2 \mapsto p x_1 + (1-p) x_2.\\
\end{array}
\right.
\end{equation}
Using induction on $k$, we can prove that
$$
\varphi^k : \left\{
\begin{array}{l}
x_1 \mapsto (1 + k p) x_1 - k p x_2,\\
x_2 \mapsto k p x_1 + (1 - k p) x_2,\\
\end{array}
\right.
$$
and hence
$$
[\varphi]^k = \left(%
\begin{array}{cc}
  1 + k p & -k p \\
  k p & 1 - k p \\
\end{array}%
\right).
$$
\para

Let $a=\alpha_1x_1+\alpha_2x_2$ and  $b=\beta_1x_1+\beta_2x_2$ be elements in $\mathbb{Z}^2$. Then, we have
$$
a\circ b=a+\varphi^{\alpha_1+\alpha_2}(b) = a + b + p (\alpha_1 + \alpha_2)(\beta_1 + \beta_2)  (x_1 - x_2).
$$
We see that if $\alpha_1+\alpha_2=0$, then $a\circ b=a+b$. Note that  ${\bf 0} = 0x_1 + 0x_2$ is the identity element of $(\mathbb{Z}^2, \circ)$. Suppose that $a \circ b = {\bf 0}$. Then we have the equations
$$ \alpha_1 + \beta_1 +  p (\alpha_1+\alpha_2) (\beta_1 + \beta_2) = 0 \quad \textrm{and} \quad  \alpha_2 + \beta_2 -  p (\alpha_1+\alpha_2) (\beta_1 + \beta_2) = 0.$$
This implies that the right inverse $\bar a$ of $a$ has the form
$$
\bar a = -a + p (\alpha_1+\alpha_2)^2 (x_1 - x_2).
$$
Since $\bar a$ is also the left inverse of  $a$, it is the inverse of $a$. 
\para

We now determine the structure of $(\mathbb{Z}^2, \circ)$. Note that
$$
(\alpha_1 x_1 + \alpha_2 x_2) \circ (m x_1) = \big(\alpha_1 + m + m p(\alpha_1 + \alpha_2) \big) x_1 + \big(\alpha_2 - m p (\alpha_1 + \alpha_2) \big) x_2.
$$
Thus, if $\alpha_1 + \alpha_2 = 0$, then
$$
(\alpha_1 x_1 + \alpha_2 x_2) \circ (m x_1) = (\alpha_1 + m) x_1 + \alpha_2 x_2.
$$
This gives a decomposition
$$
\mathbb{Z}^2=\sqcup_{m\in \mathbb{Z}} ~ \mathbb{Z}^2_0 \circ (m x_1)
$$
of $\mathbb{Z}^2$ as a union of cosets of $\mathbb{Z}^2_0$. Note that the $m$-th power of  $x_1$ in $(\mathbb{Z}^2, \circ)$ has a form
$$
x_1^{\circ m}=x_1\circ \cdots \circ x_1 = \big( \id + \varphi + \cdots + \varphi^{m-1} \big)(x_1).
$$
Since
$$
I + [\varphi]+ \cdots + [\varphi]^{m-1}=
\left(%
\begin{array}{cc}
  m+\frac{m(m-1)}{2} p & -\frac{m(m-1)}{2} p \\
  & \\
  \frac{m(m-1)}{2} p & m-\frac{m(m-1)}{2}p \\
\end{array}%
\right),
$$
we obtain
$$
x_1^{\circ m}= \left(m + \frac{m(m-1)}{2} p \right) x_1  - \frac{m(m-1)}{2} p x_2,
$$
which further gives
$$
x_1^{\circ m}-mx_1 = \frac{m(m-1)}{2} p  x_1  - \frac{m(m-1)}{2} p x_2 = \frac{m(m-1)}{2} p (x_1 - x_1).
$$
We also have
\begin{equation}\label{x1 and x1-x2 relation}
 x_1 \circ (x_1 - x_2) = 2 x_1 - x_2 =  (x_1 - x_2) \circ  x_1.
 \end{equation}
This gives a decomposition
$$
(\mathbb{Z}^2, \circ) = \sqcup_{m\in \mathbb{Z}}  ~\mathbb{Z}^2_0 \circ (m x_1)
$$
 of $(\mathbb{Z}^2, \circ)$ as a union of cosets of $\mathbb{Z}^2_0$. In particular,
$(\mathbb{Z}^2, \circ)$ is generated by $\{x_1, x_1 - x_2 \}$. In view of \eqref{x1 and x1-x2 relation}, it follows that $(\mathbb{Z}^2, \circ)$ is the free abelian group of rank two.
\para

In the second  case, $\varphi$ is of order two and takes the form
\begin{equation}\label{sec4eqn2}
\varphi : \left\{
\begin{array}{l}
x_1 \mapsto (1+p) x_1 -p x_2,\\
x_2 \mapsto (2+p) x_1 - (1+p) x_2.\\
\end{array}
\right.
\end{equation}

Let  $a=\alpha_1x_1+\alpha_2x_2$ and $b=\beta_1x_1+\beta_2x_2$ be elements of $\mathbb{Z}^2$. Then, we have
$$
a\circ b = a + \varphi^{\alpha_1+\alpha_2}(b)  =
\left\{\begin{array}{ll}
  a+b & \textrm{if}~ \alpha_1+\alpha_2 \equiv 0 \mod 2,  \\
  a + b + \big(2 \beta_2 + p (\beta_1 + \beta_2)\big) (x_1 - x_2) & \textrm{if}~ \alpha_1+\alpha_2 \equiv 1 \mod 2. \\
\end{array}
\right.
$$
A direct computation along the lines of the first case shows that the inverse of $a=\alpha_1x_1+\alpha_2x_2$ in $(\mathbb{Z}^2, \circ)$ has the form
$$
\bar a =
\left\{\begin{array}{ll}
-a & \textrm{if} ~  \alpha_1+\alpha_2 \equiv 0 \mod 2 ,  \\
  -a  +  \big(2 \alpha_2 + p (\alpha_1 + \alpha_2) \big) (x_2 - x_1) & \textrm{if} ~ \alpha_1+\alpha_2\equiv 1 \mod 2. \\
\end{array}
\right.
$$
\para

Given $a=\alpha_1x_1+\alpha_2x_2 \in \mathbb{Z}^2_0$, we can write it as
$$
a= \frac{\alpha_1+\alpha_2}{2}(x_1+x_2)+\frac{\alpha_1-\alpha_2}{2}(x_1-x_2).
$$
This shows that $\mathbb{Z}^2_0$ is generated by the elements $z_1 = x_1 + x_2$ and $z_2 = x_1 - x_2$. The group $(\mathbb{Z}^2, +)$ has the coset decomposition
$$
(\mathbb{Z}^2, +)=\mathbb{Z}^2_{0} ~\sqcup~(x_1+ \mathbb{Z}^2_{0}).
$$
Since $\varphi(\mathbb{Z}^2_{0})=\mathbb{Z}^2_{0}$, we get
$$
x_1+ \mathbb{Z}^2_{0}=x_1+\varphi(\mathbb{Z}^2_{0})=x_1\circ \mathbb{Z}^2_{0}.
$$
Hence, we have the coset decomposition
$$
(\mathbb{Z}^2, \circ) =\mathbb{Z}^2_{0} ~\sqcup~(x_1\circ \mathbb{Z}^2_{0})
$$
of $(\mathbb{Z}^2, \circ )$.
\para

To determine the structure of $(\mathbb{Z}^2, \circ )$, observe that it is generated by $\{x_1, z_1, z_2\}$ and has relations
$$
z_1 \circ z_2 = z_2 \circ z_1 \quad \textrm{and}\quad x_1 \circ x_1 = z_1 + (p+1) z_2.
$$
Since $\mathbb{Z}^2_{0}$ is normal in $(\mathbb{Z}^2, \circ )$, the conjugation relations
$$
\bar x_1 \circ z_1 \circ x_1 =  z_1 + 2(1 + p) z_2~~\textrm{and}~~~\bar x_1 \circ z_2 \circ x_1 = - z_2
$$
hold. Hence, the group $(\mathbb{Z}^2, \circ)$ has the presentation
\begin{eqnarray*}
(\mathbb{Z}^2, \circ) &= &\Big\langle x_1, z_1, z_2  \, \mid \,  z_1 \circ z_2 = z_2 \circ z_1, \quad x_1 \circ x_1 = z_1 \circ z_2^{\circ (p+1)},\\
& &  \;\; \bar x_1 \circ z_1 \circ x_1 =  z_1 + 2(1 + p) z_2, \quad \bar x_1 \circ z_2 \circ x_1 = \bar z_2 \Big\rangle.
\end{eqnarray*}
Since  $x_1^{\circ 2} \circ {\bar z_2}^{\circ (p+1)} = z_1$, we obtain
$$
(\mathbb{Z}^2, \circ) = \big\langle x_1, z_2  \, \mid \,  \bar x_1 \circ z_2 \circ x_1 = \bar z_2  \big\rangle,
$$
which  is the fundamental group of the Klein bottle. $\blacksquare$
\end{proof}

\begin{remark}
{\rm 
It is conceivable that two distinct tuples of integers could result in isomorphic left braces. It would be intriguing to ascertain the conditions under which this occurs.}    
\end{remark}
\bigskip
