\section{Solutions arising from Lambda-homomorphic skew braces} 
In this section, we discuss solutions to the Yang--Baxter equation arising from Lambda-homomorphic skew braces constructed in the preceding sections.
Our first result is the following theorem  \cite[Theorem 7.4]{MR4346001}.

\begin{theorem}\label{lambda homomorphic solution 1}
Let $A \cong (\mathbb{Z}^n, +)$ be the free abelian group with free basis $\{x_1, \ldots, x_n \}$. For elements $a = \sum_{i=1}^n \alpha_i x_i$ and $b = \sum_{j=1}^n \beta_j x_j$ of $A$, let  $\langle a, b \rangle = \sum_{i=1}^{n-1} \alpha_i \beta_i$ denote their restricted scalar product and $r: A \times A \to A \times A$ the map given by
$$
r(a, b) = \big(b~ + \langle a, b \rangle x_n, ~a~ -  \langle a, b \rangle x_n \big).
$$
Then $(A, r)$ is a non-degenerate involutive solution to the Yang--Baxter equation.
\end{theorem}

\begin{proof}
Let $\varphi_1,  \ldots, \varphi_n \in \Aut( A)$ be pairwise commuting automorphisms of $A$ given by
 $$
\varphi_i : \left\{
  \begin{array}{ll}
x_i \to x_i + x_n, & \\
x_j \to x_j & \textrm{if} \quad j \not= i
  \end{array}
\right.
$$
for $1 \le i \le n-1$ and $\varphi_n = \id$. Then the map  $\lambda : A \to \Aut( A)$ defined on the generators by
$$
\lambda_{x_i}  = \varphi_i
$$
for $1 \le i \le n$, gives a group homomorphism. Let $a = \sum_{i=1}^n \alpha_i x_i$ and $b = \sum_{j=1}^n \beta_j x_j$ be elements of $A$. Then we have 
$$
\lambda_a = \varphi_1^{\alpha_1} \varphi_2^{\alpha_2} \ldots \varphi_{n-1}^{\alpha_{n-1}} :
\left\{
  \begin{array}{ll}
x_i \to x_i + \alpha_i x_n & \textrm{if} \quad i \ne n,\\
x_n \to x_n. &
  \end{array}
\right.
$$
Thus, we can write $\lambda_a(b) = b + \langle a, b \rangle x_n$. It follows from Proposition \ref{redprop} and  Theorem \ref{t1} that
$$
a \circ b = a + \lambda_a(b) =  a + b~ + \langle a, b \rangle x_n
$$
defines a $\lambda$-homomorphic left brace $(A, +, \circ)$. By Theorem \ref{solution from a skew brace}, the left brace gives a non-degenerate involutive solution to the Yang--Baxter equation with braiding
$$
r(a, b) = \big( \lambda_a(b), ~\lambda^{-1}_{\lambda_a(b)}(a)\big).
$$
It is not difficult to see that $\lambda^{-1}_{c} = \lambda_{-c}$ for all $c \in A$. Using this, we obtain 
$$
r(a, b) = \big(b~ +  \langle a, b \rangle x_n, ~a~ -  \langle a, b \rangle x_n \big),
$$
which is desired. $\blacksquare$    
\end{proof}          
\para

Let $A \cong (\mathbb{Z}^n, +)$ be the free abelian group with free basis $\{x_1, \ldots, x_n \}$.  Consider the subgroup
$$
B = \Big\{ \sum_{i=1}^n \alpha_i x_i \in A  \, \mid \, \sum_{i=1}^n \alpha_i  = 0 \Big\}
$$
of $A$ and the automorphism $\varphi \in \Aut(A)$ such that
$$
\varphi (x_i) \equiv x_i \mod B
$$
for each $1 \le i \le n$. Then the binary operation
$$
a \circ b = a + \varphi^{\mathfrak{L}(a)}(b),
$$
for $a, b \in A$, gives a left brace $(A, +, \circ)$. By Theorem \ref{solution from a skew brace}, the braiding given by
$$
r(a, b) = \big(\varphi^{\mathfrak{L}(a)}(b),~ \varphi^{-\mathfrak{L}(b)}(a)\big),
$$
gives a non-degenerate involutive solution $(A, r)$ to the Yang--Baxter equation.  The next result extends the preceding observation \cite[Proposition 7.8]{MR4346001}. 

\begin{proposition}
Let $G$ be an abelian group admitting a homogeneous presentation $G= \langle S\mid R\rangle$. Let $\varphi \in \Aut (G)$ be such that $\mathfrak{L}(\varphi (g)) = 1$ for all $g \in S$. Then the map
$r : G \times G \to G \times G$ given by
$$
r(a, b) = \big(\varphi^{\mathfrak{L}(a)} (b), ~\varphi^{\mathfrak{L}(\varphi^{\mathfrak{L}(a)}(b^{-1}))} (a)\big)
$$
gives a non-degenerate involutive solution $(G, r)$ to the Yang--Baxter equation.
\para 
In addition, if $\varphi$ satisfies $\mathfrak{L} \big(\varphi(b)\big) = \mathfrak{L}(b)$ for each $b \in G$, then
$$
r(a, b) = \big(\varphi^{\mathfrak{L}(a)} (b), ~\varphi^{-\mathfrak{L}(b)} (a)\big).
$$
\end{proposition}

\begin{proof}
Since $G$ is homogeneous and $\mathfrak{L}(\varphi (g_i)) = 1$ for all $g_i \in S$, it follows from Proposition \ref{lcb} that $(G, \cdot, \circ)$ 
is a $\lambda$-cyclic skew left brace. Here, the map $\lambda : G \to \Aut(G^{(\cdot)})$ is given by $\lambda_a (b) = \varphi^{\mathfrak{L}(a)} (b)$. Hence, the first component of the induced braiding has the desired form. For the second component, note that
$$
\lambda_a^{-1} (b) = \varphi^{-\mathfrak{L}(a)} (b) = \varphi^{\mathfrak{L}(a^{-1})} (b) = \lambda_{a^{-1}} (b).
$$
Thus, we have
$$
\lambda_{\lambda_a (b)}^{-1} (a) = \lambda_{\varphi^{\mathfrak{L}(a)} (b)}^{-1} (a) =
\lambda_{\varphi^{\mathfrak{L}(a)} (b^{-1})} (a) =
\varphi^{\mathfrak{L}(\varphi^{\mathfrak{L}(a)}(b^{-1}))} (a),
$$
which is desired. The last assertion is immediate. $\blacksquare$    
\end{proof}          
\para

Next, we construct some specific solutions on $\mathbb{Z}^2$. 

\begin{proposition}
Let $A \cong (\mathbb{Z}^2, +)$, $p$ an integer and $r:A \times A \to A \times A$ the map given by
$$r(a, b) = \big(b + p \mathfrak{L}(a) \mathfrak{L}(b) (x_1 - x_2),~ a - p \mathfrak{L}(a) \mathfrak{L}(b) (x_1 - x_2)\big).$$
Then  $(A, r)$ is a non-degenerate involutive solution  to the Yang--Baxter equation.
\end{proposition}

\begin{proof}
Consider the automorphism $\varphi$ of $A$ given by 
$$
\varphi : \left\{
  \begin{array}{l}
x_1 \to (1+p) x_1 - p x_2, \\
x_2 \to p x_1 + (1-p) x_2.
  \end{array}
\right.
$$
By Theorem \ref{cyclic left braces on Z2}, $(A, +, \circ)$ is a $\lambda$-cyclic left brace, where  $\lambda :A \to \Aut (A)$ is the group homomorphism given by $a \mapsto \lambda_a = \varphi^{\mathfrak{L}(a)}$ for all $a \in A$. By Theorem \ref{solution from a skew brace}, the left brace gives a non-degenerate involutive solution to the Yang--Baxter equation with braiding
$$
r(a, b) = \big( \lambda_a(b), ~\lambda^{-1}_{\lambda_a(b)}(a)\big).
$$
For elements $a = \alpha_1 x_1 + \alpha_2 x_2$ and $b = \beta_1 x_1 + \beta_2 x_2$ of $A$, we have
$$ \lambda_a(b) = \varphi^{\alpha_1 + \alpha_2}(b) = b + p (\alpha_1  + \alpha_2) (\beta_1 + \beta_2)(x_1 - x_2)=b + p \mathfrak{L}(a) \mathfrak{L}(b) (x_1 - x_2) $$
and 
$$ \lambda_{\lambda_a (b)}^{-1} (a) =\varphi^{\mathfrak{L}(\varphi^{\mathfrak{L}(a)}(b^{-1}))} (a)=a - p (\alpha_1  + \alpha_2) (\beta_1 + \beta_2) (x_1 - x_2) =a - p \mathfrak{L}(a) \mathfrak{L}(b) (x_1 - x_2).$$
This completes the proof.  $\blacksquare$
\end{proof}

Considering the automorphism $\varphi$ of $A \cong (\mathbb{Z}^2, +)$ given by 
$$
\varphi : \left\{
  \begin{array}{l}
x_1 \to (1+p) x_1 - p x_2, \\
x_2 \to (2 + p) x_1 - (1+p) x_2,
  \end{array}
\right.
$$
gives the following result.

\begin{proposition}
Let $A \cong (\mathbb{Z}^2, +)$ and $p$ an integer. For elements $a = \alpha_1 x_1 + \alpha_2 x_2$ and $b = \beta_1 x_1 + \beta_2 x_2$ of $A$, let $r:A \times A \to A \times A$ be the map given by
$$
r(a, b) =  \left\{
  \begin{array}{ll}
(b, a) & \textrm{if}~ \mathfrak{L}(a) \equiv \mathfrak{L}(b) \equiv 0 \mod~2, \\
\big(b + (2 \beta_2 + p \mathfrak{L}(b)) (x_1 - x_2),~ a \big)  &\textrm{if} ~ \mathfrak{L}(a) \equiv 1 \mod~2~\textrm{and}~\mathfrak{L}(b) \equiv 0 \mod~2,\\
\big(b, ~a + (2 \alpha_2 - p \mathfrak{L}(b)) (x_1 - x_2) \big)  &\textrm{if} ~ \mathfrak{L}(a) \equiv 0 \mod~2~\textrm{and}~\mathfrak{L}(b) \equiv 1 \mod~2,\\
\big(b + (2 \beta_2 + p \mathfrak{L}(b)) (x_1 - x_2), ~a + (2 \alpha_2 - p \mathfrak{L}(b)) (x_1 - x_2) \big)  &\textrm{if} ~ \mathfrak{L}(a) \equiv \mathfrak{L}(b) \equiv 1 \mod~2.\\
  \end{array}
\right.
$$
Then  $(A, r)$ is a non-degenerate involutive solution  to the Yang--Baxter equation.
\end{proposition}
\para

Similarly, considering the automorphism $\varphi$ of $A \cong (\mathbb{Z}^2, +)$ given by 
$$
\psi : \left\{
  \begin{array}{l}
x_1 \to  x_{2},  \\
x_2 \to  x_1,
  \end{array}
\right.
$$
gives the following result.


\begin{proposition}
Let $A \cong (\mathbb{Z}^2, +)$. For elements $a = \alpha_1 x_1 + \alpha_2 x_2$ and $b = \beta_1 x_1 + \beta_2 x_2$ of $A$, let $r:A \times A \to A \times A$ be the map given by
$$
r(a, b) =  \left\{
  \begin{array}{ll}
(b, a) & \textrm{if}~ \mathfrak{L}(a) \equiv \mathfrak{L}(b) \equiv 0 \mod~2, \\
\big(b + (\beta_1 - \beta_2) (x_1 - x_2), ~a\big)  &\textrm{if}~ \mathfrak{L}(a) \equiv 1 \mod~2~\textrm{and}~\mathfrak{L}(b) \equiv 0 \mod~2,\\
\big(b, ~a + (\alpha_1 + \alpha_2) (x_1 - x_2)\big)   &\textrm{if}~ \mathfrak{L}(a) \equiv 0 \mod~2~\textrm{and}~\mathfrak{L}(b) \equiv 1 \mod~2,\\
\big(b + (\beta_1 - \beta_2) (x_1 - x_2), ~a + (\alpha_1 + \alpha_2) (x_1 - x_2)\big)  &\textrm{if}~ \mathfrak{L}(a) \equiv \mathfrak{L}(b) \equiv 1 \mod~2.\\
  \end{array}
\right.
$$
Then  $(A, r)$ is a non-degenerate involutive solution  to the Yang--Baxter equation.
\end{proposition}
\para

As a final example,  we consider the solution arising from a left brace with non-solvable multiplicative group \cite[Proposition 7.16]{MR4346001}.

\begin{proposition}
Let $\mathbb{Z}\langle\langle X_1, \ldots, X_n \rangle\rangle$ be the ring of formal power series in non-commuting variables $X_1, \ldots, X_n$ over $\mathbb{Z}$, where $n \ge 2$. Let $B$ be the two-sided ideal of $\mathbb{Z}\langle\langle X_1, \ldots, X_n \rangle\rangle$  generated by $X_1, \ldots, X_n$. Let $r:B \times B \to B \times B$ be the map given by
$$
r(a, b) = \big(b + a b,~ a + (\overline{b+ba}) a \big)
$$
for $a, b \in B$, where $\overline{c}= -c + c^2 - c^3 + \cdots$. Then $(B, r)$ is a non-degenerate involutive solution to the Yang--Baxter equation.
\end{proposition}

\begin{proof}
It follows from the proof of Proposition \ref{p7.1} that  $(B, +, \circ)$ is a two-sided brace with
$$
a \circ b = ab + a + b
$$
for $a, b \in B$. We know that the left brace gives a non-degenerate involutive solution with braiding
$$
r(a, b) = \big(\lambda_a (b), ~\lambda^{-1}_{\lambda_a (b)} (a)\big)
$$
for all $a, b \in B$. In this case, we have
$$
\lambda_a (b) = -a + a \circ b = b + ab.
$$
Further, $\lambda_a^{-1} = \lambda_{\overline{a}}$, where
$$
\overline{a} = -a + a^2 - a^3 + \cdots.
$$
 Hence, we have
$$
r(a, b) = \big(\lambda_a (b), ~\lambda^{-1}_{\lambda_a (b)} (a)\big)  = \big(b + a b,~ a + (\overline{b+ba}) a \big)
$$
for all $a, b \in B$, which is desired. $\blacksquare$
\end{proof}          
