\chapter{Rota--Baxter operators on groups }\label{chap RBO on groups}

\begin{quote}
This chapter develops the foundational theory of Rota--Baxter operators on groups. We begin by introducing the definition, key examples, and basic properties of Rota--Baxter groups. Various constructions of these structures are then explored in detail.  Furthermore, we examine the problem of extending set-theoretic maps to Rota--Baxter operators on groups. We also investigate extensions of Rota--Baxter groups and examine the relationship between Rota--Baxter operators on groups and their corresponding Lie rings.
\end{quote}
\bigskip

\section{Properties of Rota--Baxter groups} 
The first appearance of Rota--Baxter operators on commutative algebras can be traced back to Baxter's seminal paper \cite{MR0119224} in 1960. Since then, the theory of Rota--Baxter operators has undergone extensive development by various authors, with comprehensive details available in the monograph \cite{MR3025028}. These operators play a pivotal role due to their connections with several mathematical concepts, including the Yang--Baxter equation \cite{MR0674005,MR0725413}, Loday algebras \cite{MR3021790}, double Poisson algebras \cite{MR2568415}, and others. Rota--Baxter operators on Lie algebras were first studied by Belavin, Drinfel'd, and Semenov-Tian-Shansky as operator forms of the classical Yang--Baxter equation.  In their work \cite{MR4271483}, Guo, Lang and Sheng  introduced the notion of a Rota--Baxter operator on a group.  Integrating the Rota--Baxter operators on Lie algebras, they introduced the notion of Rota--Baxter operators on Lie groups and more generally on (abstract) groups.
\para


Let $A$ be an algebra over a field~$\Bbbk$. A linear operator $R:A \to A$ is called
a Rota--Baxter operator of weight~$\lambda\in \Bbbk$ if
\begin{equation}\label{RBAlgebra}
R(x)R(y) = R\big( R(x)y + xR(y) + \lambda xy \big)
\end{equation}
for all $x,y\in A$. An algebra endowed with a Rota--Baxter operator is called a \index{Rota--Baxter algebra}{\it Rota--Baxter algebra}. Following \cite{MR4271483}, we consider an analogue of a Rota--Baxter operator of weight~$\pm1$ on a group.


\begin{definition}
Let $G$ be a group.
\begin{enumerate}
\item A map $B: G\to G$ is called a \index{Rota--Baxter operator}{Rota--Baxter operator} of weight~1 if
\begin{equation}\label{RB}
B(g)B(h) = B\big(g B(g) h B(g)^{-1} \big)
\end{equation}
for all $g,h\in G$.
\item A map $C: G\to G$ is called a {\it Rota--Baxter operator} of weight~$-1$ if
$$
C(g) C(h) = C\big( C(g) h C(g)^{-1} g \big)
$$
for all $g,h\in G$.
\end{enumerate}
\end{definition}

A group endowed with a Rota--Baxter operator is called a \index{Rota--Baxter group}{\it Rota--Baxter group}. 

\begin{example}{\rm 
Let $G$ be a group.
\begin{enumerate}
\item The map given by $B_0(g) = 1$ is a Rota--Baxter operator on $G$.
\item The map given by $B_{-1}(g) = g^{-1}$ is a  Rota--Baxter operator on $G$.
\end{enumerate}}
\end{example}

The Rota--Baxter operators $B_0$ and $B_{-1}$ are referred to as \index{elementary Rota--Baxter operator}{\it elementary Rota--Baxter operators}. A~group $G$ is called \index{Rota--Baxter elementary group}{\it Rota--Baxter elementary} if any Rota--Baxter operator on $G$ is elementary.
\para

The following result provides a method for constructing new Rota--Baxter operators from existing ones \cite[Proposition 2.4]{MR4271483}.

\begin{proposition}\label{RBO from old ones}
Let $G$ be a group, $B: G \to G$ a Rota--Baxter operator of weight~1 and $C: G \to G$ a Rota--Baxter operator of weight $-1$. Then the following  assertions hold:
\begin{enumerate}
\item The map $\widetilde{C}:G \to G$ given by $\widetilde{C}(g) = g C(g^{-1})$ is a Rota--Baxter operator of weight $-1$.
\item The map $\widetilde{B}:G \to G$ given by $\widetilde{B}(g) = g^{-1}B(g^{-1})$
is a Rota--Baxter operator of weight $1$.
\item The map $\bar{B}:G \to G$  given by $\bar{B}(g) = B(g^{-1})$ is a Rota--Baxter operator of weight $-1$.
\item The map $B_{+}:G \to G$  given by $B_{+}(g) = g B(g)$ is a Rota--Baxter operator of weight $-1$.
\end{enumerate}
\end{proposition}

\begin{proof}
All the assertions follow by direct calculations. For instance, we have
$$
B_{+}(g)B_{+}(h)= g B(g) h B(h)
$$
and
$$B_{+}\big( B_{+}(g) h B_{+}(g)^{-1} g \big)=B_{+}\big( gB(g) h B(g)^{-1} \big)= \big( gB(g) h B(g)^{-1} \big)B\big(gB(g) h B(g)^{-1} \big)$$
for all $g, h \in G$. Since $B$ is a Rota--Baxter operator of weight 1, we have $B_{+}(g)B_{+}(h)= B_{+}\big( B_{+}(g) h B_{+}(g)^{-1} g \big)$,
which is assertion (4).
$\blacksquare$ 
\end{proof}

Proposition \ref{RBO from old ones} shows that there is a bijection between Rota--Baxter operators of weight 1 and $-1$ on a given group. Thus, we consider only Rota--Baxter operators of weight 1, and refer them simply as Rota--Baxter operators.
\para

Given a group $G$ and subgroups $H, L$ of $G$,  let $[H,L]$ be the subgroup of $G$ generated by the set
$$\big\{[h,l] = h^{-1}l^{-1}hl  \, \mid \,  h\in H~\textrm{and}~l\in L \big\}.$$
Next, we observe some elementary facts about Rota--Baxter operators on groups.

\begin{lemma}\label{lem:elementary}
Let $B$ be a Rota--Baxter operator on a group $G$. Then the following  assertions hold:
\begin{enumerate}
\item $B(1) = 1$.
\item $B(g)B(g^{-1}) = B\big([g^{-1},B(g)^{-1}] \big)$ for all $g \in G$.
\item $B(g)B(B(g)) =  B\big(g B(g)\big)$  for all $g \in G$.
\item  $B(g)^{-1} = B \big(B(g)^{-1}g^{-1}B(g)\big)$  for all $g \in G$. 
\end{enumerate}
\end{lemma}

\begin{proof}
Assertion (1) follows from~\eqref{RB} by taking $g = h = 1$. Assertion (2) follows from~\eqref{RB} by taking $h = g^{-1}$, and assertion (3) follows by taking $h = B(g)$. Finally, since
$$B(g)B \big(B(g)^{-1}g^{-1}B(g)\big)= B\big(g B(g)B(g)^{-1}g^{-1}B(g)B(g)^{-1}\big) = B(1) = 1,$$
we obtain assertion (4).
$\blacksquare$ 
\end{proof}

The following result is a simple yet important observation \cite[Lemma 3.2]{MR4271483}.

\begin{lemma}\label{KerImSub}
Let $B$ be a Rota--Baxter operator on a group~$G$. Then the following  assertions hold:
\begin{enumerate}
\item $\ker(B)$ is a subgroup of $G$.
\item $\im (B)$ is a subgroup of $G$.
\end{enumerate}
\end{lemma}

\begin{proof}
Recall from Lemma~\ref{lem:elementary}(1) that $B(1) = 1$. For $g,h\in \ker(B)$, by~\eqref{RB}, we have
$$
B(g^{-1}) = B(g)B(g^{-1}) = B \big(gB(g)g^{-1}B(g)^{-1}\big) = B(g g^{-1})=B(1) = 1$$
and
$$B(gh)= B \big(gB(g)hB(g)^{-1}\big)= B(g)B(h) =  1,
$$
which proves assertion (1).
\para 
It is clear from \eqref{RB} that if $g,h\in \im(B)$, then $gh\in \im (B)$. Further, if $g\in \im (B)$, then by Lemma \ref{lem:elementary}(4), we have $g^{-1}\in \im (B)$. This proves assertion (2).
$\blacksquare$ 
\end{proof}

A direct check yields the following observation.

\begin{lemma} \label{kernelCosets}
Let $B$ be a Rota--Baxter operator on a group~$G$. If $B(g) =  1$ for some $g\in G$, then $B(h) = B(gh)$ for any $h\in G$. In particular, if $G = \sqcup_{i \in I}~ \ker(B)g_i$ is the decomposition of $G$ as right cosets of $\ker(B)$, then $B(x) = B(y)$ if $x$ and $y$ lie in the same coset.
\end{lemma}


The next result is crucial from the point of  view of classification of Rota--Baxter operators on a given group \cite[Lemma 9 and Lemma 10]{MR4556953}.

\begin{lemma}\label{lem:Aut}
Let $B$ be a Rota--Baxter operator on a group~$G$ and $\varphi \in \Aut(G)$ an automorphism. Then the following  assertions hold:
\begin{enumerate}
\item $B^{(\varphi)} = \varphi^{-1}B\varphi$
is a~Rota--Baxter operator on $G$.
\item $(\widetilde{B})^{(\varphi)} = \widetilde{B^{(\varphi)}}$.
\end{enumerate}

\end{lemma}

\begin{proof}
Direct computations give
\begin{eqnarray*}
\varphi \big( B^{(\varphi)}(g) B^{(\varphi)}(h) \big)
 &=& \varphi \big( \varphi^{-1}(B(\varphi(g))) \,\varphi^{-1}(B(\varphi(h))) \big)\\
 &=&  B \big(\varphi(g)\big) \, B \big(\varphi(h)\big) \\
 &=&  B\big(\varphi(g)B(\varphi(g))\varphi(h)B(\varphi(g))^{-1} \big)\\
 &=&  \varphi\varphi^{-1}B\varphi \big( g\varphi^{-1}B(\varphi(g))h\varphi^{-1}(B(\varphi(g))^{-1}) \big) \\
 &=&  \varphi\big( B^{(\varphi)} \big(gB^{(\varphi)}(g)h(B^{(\varphi)}(g))^{-1} \big) \big)
\end{eqnarray*}
for all $g, h \in G$, which is assertion (1).
\para 
Further, we see that
$$
(\widetilde{B})^{(\varphi)} (g)
 = \varphi^{-1} \big( \widetilde{B} (\varphi(g)) \big)
 = \varphi^{-1} \big( \varphi(g)^{-1}B( \varphi(g)^{-1} ) \big)
 = g^{-1}B^{(\varphi)}(g^{-1})
 = \widetilde{B^{(\varphi)}}(g), 
$$
which is assertion (2). $\blacksquare$ 
\end{proof}

The following result shows how a Rota--Baxter operator gives rise to an alternative group structure  \cite[Section 3]{MR4271483}.

\begin{proposition}\label{prop:Derived}
Let $B$ be a Rota--Baxter operator on a group~$(G, \cdot)$. Then the following  assertions hold:
\begin{enumerate}
\item The set $G$ with the binary operation
\begin{equation}\label{R-product}
g\circ h = gB(g)hB(g)^{-1}
\end{equation}
for $g,h\in G$, is a group.
\item The map $B: (G,\circ) \to (G,\cdot)$ is a homomorphism of groups.
\item The map $B$ is a Rota--Baxter operator on the group $(G,\circ)$.
\end{enumerate}
\end{proposition}

\begin{proof}
Let $g, h, k \in G$. Using \eqref{RB}, we see that
$$(g \circ h) \circ k=  \big(gB(g)hB(g)^{-1} \big) \circ k= g B(g) h B(h) k B(h)^{-1} B(g)^{-1} =g \circ \big(h B(h) k B(h)^{-1} \big)= g \circ (h \circ k).$$
Further, if 1 is the identity element of $(G, \cdot)$, then we see that $g \circ 1=g= 1 \circ g$ and $g^{\circ (-1)}= B(g)^{-1} g^{-1} B(g)$ for all $g \in G$. Thus, $(G, \circ)$ is a group, which proves assertion (1).
\para
If $g, h \in G$, then using \eqref{RB}, we have
$$B(g \circ h)=B \big(gB(g)hB(g)^{-1}\big)= B(g) B(h).$$
Thus, $B: (G, \circ) \to (G, \cdot)$ is a group homomorphism, which proves assertion (2). 
\para 
Using assertion (2), we see that $$B(g) \circ B(h)= B(g) B \big(B(g)\big) B(h) B \big(B(g)\big)^{-1}= B \big(g \circ B(g) \circ h \circ B(g)^{\circ (-1)}\big),$$
which is assertion (3). $\blacksquare$ 
\end{proof}

We shall denote the group $(G,\circ)$ by $G_B$. Given a Rota--Baxter group $(G,B)$,  consider the map $B_+:G \to G$ defined as $B_+(g) = gB(g)$ for $g \in G$. Then $B_+$ is a group homomorphism from $G_B$ to $G$. It follows from Lemma~\ref{lem:elementary}(3)  that $B_+B = BB_+$.

\begin{exercise}{\rm 
Let $B$ be a Rota--Baxter operator on a group $(G, \cdot)$. Then the following  assertions hold:
\begin{enumerate}
\item  If $B = B_0$, then
$$
g\circ h = gB_0(g)hB_0(g)^{-1} = g h.
$$
Hence, the group operations $\circ$ and $\cdot$ coincide.
\item  If $B = B_{-1}$, then
$$
g\circ h = gB_{-1}(g) h B_{-1}(g)^{-1} = h g.
$$
Hence, $(G, \circ)$ is the opposite group of $(G, \cdot)$.
\item  If $G$ is abelian, then $g\circ h = g\cdot h$ for all $g,h\in G$.    
\end{enumerate}}
\end{exercise}

The following result of Guo, Lang, and Sheng \cite[Proposition 3.3]{MR4271483} is analogous
to the one established by Semenov-Tyan-Shanskii for Lie algebras \cite{MR0725413}.

\begin{proposition} Let $(G, B)$ be a Rota--Baxter group. Then the following  assertions hold: 
\begin{enumerate}
\item $\ker(B)$ and $\ker(B_+)$ are normal subgroups of $G_B$.
\item $\ker(B)$ is a normal subgroup of $\im(B_+)$.
\item $\ker(B_+)$ is a normal subgroup of $\im(B)$.
\item  There is an isomorphism of groups
$$ \im(B_+)/\ker(B)\cong \im(B)/\ker(B_+). $$
\item There is a factorization of $G$ as
\begin{equation}\label{ImageFactorization}
G = \im(B_+)\im(B).
\end{equation}
\end{enumerate}
\end{proposition}
\para

Let $(G, B)$ be a Rota--Baxter group and $a \in G$. Given an integer~$k$, let $a^{\circ(k)}$ denote the $k$-th power of $a$ with respect to $\circ$. The following result gives a precise formula for a word written in terms of the group operation in $G_B$ \cite[Proposition 14]{MR4556953}. 

\begin{proposition} \label{for} Let $(G, B)$ be a Rota--Baxter group and $A$ a subset of $G$. Let
$$
w = a_{i_1}^{\circ(k_1)} \circ a_{i_2}^{\circ(k_2)} \circ \cdots
    \circ a_{i_s}^{\circ(k_s)},
$$
where $a_{i_j} \in A$ and $k_j \in \mathbb{Z}$, be an element presented with respect to the group operation $\circ$. Then
$$
w = \big(a_{i_1}B(a_{i_1})\big)^{k_1}
    \big(a_{i_2}B(a_{i_2})\big)^{k_2} \ldots
    \big(a_{i_s}B(a_{i_s})\big)^{k_s}
    B(a_{i_s})^{-k_s}
    B(a_{i_{s-1}})^{-k_{s-1}} \ldots
    B(a_{i_1})^{-k_1}.
$$
In particular, $a^{\circ(-1)} = B(a)^{-1} a^{-1} B(a)$ and $a^{\circ(k)} = B_+(a)^k B(a)^{-k}$ for each $k \in \mathbb{Z}$.
\end{proposition}

\begin{proof}
We first show using induction on $n$ that $a^{\circ(n)} = B_+(a)^n B(a)^{-n}$. Indeed, for $n = 0$, the assertion is vacuous. The induction step follows from the equalities
$$
a^{\circ(n)}
 = a\circ (a^{\circ(n-1)})
 = aB(a)a^{\circ(n-1)}B(a)^{-1}
 = \big(aB(a)\big)^n B(a)^{-n}=B_+(a)^n B(a)^{-n}.
$$
We can check directly that $B(a)^{-1}a^{-1}B(a)$
is the inverse element to~$a$ in the group $G_B$.
Again, using induction on $n$ and
Lemma~\ref{lem:elementary}(4), we obtain
\begin{eqnarray*}
a^{\circ(-n)}
 &=& a^{\circ(-1)}\circ(a^{\circ(-(n-1))}) \\
&=& B(a)^{-1}a^{-1} B(a) \, B\big( B(a)^{-1}a^{-1}B(a) \big) \big(aB(a)\big)^{-(n-1)} B(a)^{n-1} \,\big(B( B(a)^{-1}a^{-1}B(a) ) \big)^{-1} \\
&=& \big(aB(a)\big)^{-1} \big(aB(a)\big)^{-(n-1)} B(a)^{n-1}B(a)\\
 &=& \big(aB(a)\big)^{-n} B(a)^{n}\\
&=& B_+(a)^{-n} B(a)^{n}.
\end{eqnarray*}
We write $w' = a_{i_2}^{\circ(k_2)} \circ \cdots \circ a_{i_s}^{\circ(k_s)}$.
Using the fact that $B: G_B \to G$ is a group homomorphism, we get
$$
w = a_{i_1}^{\circ(k_1)}\circ w'
  = \big(B_+(a_{i_1}) \big)^{k_1} \big(B(a_{i_1})\big)^{-k_1}
  B(a_{i_1}^{\circ(k_1)})w'B(a_{i_1}^{\circ(k_1)})^{-1}
  = \big(B_+(a_{i_1})\big)^{k_1}w' \big(B(a_{i_1})\big)^{-k_1}.
$$
Thus, using induction on~$s$, we derive the desired expression.
$\blacksquare$ 
\end{proof}
