\section{Constructions of Rota--Baxter operators on groups}

In this section, we present some constructions of Rota--Baxter operators on groups. 

\subsection{Constructions via factorizations}
The following example allows us to construct non-elementary Rota--Baxter operators.

\begin{example}\label{exm:split} {\rm 
Let $G$ be a group with an exact factorization $G = HL$. Then the map $B: G\to G$ defined as
$$
B(hl) = l^{-1}
$$
is a Rota--Baxter operator on~$G$.}
\end{example}

We refer to such Rota--Baxter operators as ~\index{splitting Rota--Baxter operator}{\it splitting Rota--Baxter operators}. In this case, it follows from the definition of the group operation in $G_B$ that  $G_B\cong H\times L^{\rm op}$, where $L^{\rm op}$ is the opposite group of $L$. We now have the following result \cite[Proposition 16]{MR4556953}.

\begin{proposition}\label{SplittingCond}
Let $B$ be a Rota--Baxter operator on a group $G$. Then $B$ is a splitting Rota--Baxter operator on~$G$
if and only if $B \big(gB(g) \big) = 1$ for all $g\in G$.
\end{proposition}

\begin{proof}
Suppose that $B$ is a splitting Rota--Baxter operator on~$G$. Then there exist subgroups $H, L$ of $G$ giving an exact factorisation $G=HL$.
Let $g = hl \in G$, where $h\in H$ and $l\in L$. Then we have
$$
B \big(gB(g) \big) = B \big(hlB(hl) \big) = B(hll^{-1}) = B(h) = 1.
$$

Conversely, suppose that $B \big(gB(g)\big) = 1$ for all $g\in G$. We claim that $G = \ker(B)\im(B)$ is an exact factorization. Firstly, let $a\in \ker(B)\cap\im(B)$. Then $B(a) = 1$ and there exists $g\in G$ such that $a = B(g)$.
By the hypothesis, we have $1 = B \big(gB(g)\big) = B(ga)$. Since $a, ga\in \ker(B)$, by Lemma~\ref{KerImSub}(1) we conclude that $g\in \ker(B)$. Thus, we have $a = 1$. Secondly, let $g\in G$. Then the equality $B \big(gB(g)\big) = 1$ implies that $gB(g) \in\ker(B)$.
Thus, by Lemma~\ref{KerImSub}(2), we can write $g = ab$ for some $a \in \ker(B)$ and $b = B(g)^{-1}\in \im(B)$. $\blacksquare$ 
\end{proof}

\begin{corollary}
Let $G = H\times H\times L$ be a direct product of groups, where $H$ is a non-trivial group. Then the map $B: G\to G$ defined by
$B \big((h_1,h_2,l)\big) = (1,h_1,1)$ is a non-splitting Rota--Baxter operator on $G$.
\end{corollary}

\begin{proof}
A direct check shows that $B$ is a Rota--Baxter operator on $G$. Let $g = (h_1,h_2,l) \in G$. Since $B \big(gB(g)\big) = (1,h_1,1) \ne (1, 1, 1)$ for $h_1\neq 1$, it follows from Proposition~\ref{SplittingCond} that  $B$ is non-splitting. $\blacksquare$ 
\end{proof}


\begin{remark}{\rm 
By Lemma~\ref{lem:elementary}, the condition $B\big(gB(g)\big) = 1$ is equivalent to the relation $B(g) B^2 (g) = 1$ or $B^2 (g) = B(g)^{-1}$. It means that if $B$ is a splitting Rota--Baxter operator, then it inverts all elements of $\im(B)$.}
\end{remark}

The following result extends Example~\ref{exm:split} to  triple factorizations \cite[Proposition 18]{MR4556953}.

\begin{proposition}\label{triangular}
Let $G$ be a group such that $G = HLM$, where $H$, $L$ and $M$ are subgroups of $G$ with pairwise trivial intersections.
Let $C$ be a Rota--Baxter operator on~$L$ and suppose that $[H,L] = [C(L),M] = 1$.
Then the map $B: G\to G$ defined by
$$
B(hlm) = C(l)m^{-1}
$$
is a Rota--Baxter operator on~$G$.
\end{proposition}

\begin{proof}
Let $h,h'\in H$, $l,l'\in L$ and $m,m'\in M$. Then we have
\begin{eqnarray*}
B(hlm)B(h'l'm') &=& C(l)m^{-1}C(l')m'^{-1}\\
&=& C(l)C(l')m^{-1}m'^{-1}\\
&=& C \big(lC(l)l'C(l)^{-1} \big)(m'm)^{-1}, \quad \textrm{since $C$ is a Rota--Baxter operator}\\
&=& B \big(hh' l C(l)l'C(l)^{-1}m'm \big), \quad \textrm{by definition of $B$}\\
 &=& B \big(hlm C(l) m^{-1} h'l'm' m C(l)^{-1} \big), \quad \textrm{since $[H,L] = [C(L),M] = 1$}\\
 &=& B \big(hlm B(hlm) (h'l'm')B(hlm)^{-1} \big),
\end{eqnarray*}
and hence $B$ is a Rota--Baxter operator on $G$.
$\blacksquare$ 
\end{proof}

Note that, in the case of Proposition \ref{triangular}, we have 
$$G_B\cong H\times L_C\times M^{\rm op},$$ where $M^{\rm op}$ is the opposite group of $M$.

\begin{corollary}
Let $G = \langle a,b \rangle$ be a 2-generated 2-step nilpotent group and let $c = [b,a]$. Then the following assertions hold:
\begin{enumerate}
\item  $G = \langle a \rangle \langle c \rangle \langle b \rangle$.
\item For any integer~$k$, the map $B:G \to G$ given by
$$
B(a^{\alpha} c^{\beta} b^{\gamma})
 = c^{k\beta} b^{-\gamma}
$$
for $\alpha,\beta,\gamma \in \mathbb{Z}$, is a Rota--Baxter operator on~$G$.
\end{enumerate}
\end{corollary}

Given a~splitting Rota--Baxter operator $B$ on a~group~$G$, we have an exact factorization
\begin{equation}\label{KerImFactor}
G = \ker(B)\im(B).
\end{equation}
It is easy to see that if $G$~is abelian, then
there exists a non-splitting Rota--Baxter operator~$B$ on~$G$ such that~\eqref{KerImFactor} holds. Indeed, if $G = H \times L$, where $H, K$ are abelian groups, then any map $hl\mapsto \varphi(l)$, where $\varphi$~is an endomorphism of~$L$, defines a Rota--Baxter operator on~$G$ satisfying~\eqref{KerImFactor}. The following result generalizes this observation \cite[Proposition 20]{MR4556953}.

\begin{proposition}\label{semi-direct}
Let $G = H\rtimes L$ be a semi-direct product and let $C$ be a~Rota--Baxter operator on $L$. Then the map $B: G\to G$ defined by  $B(hl) = C(l)$, where $h\in H$ and $l\in L$, is a~Rota--Baxter operator on $G$.
\end{proposition}

\begin{proof}
Let $h,h'\in H$ and $l,l'\in L$. Then we have
\begin{eqnarray*}
B(hl)B(h'l') &=& C(l)C(l')\\
&=& C \big(lC(l)l'C(l)^{-1} \big)\\
&=& B \big(hh'^{C(l)^{-1}l^{-1}}l C(l)l'C(l)^{-1} \big) \\
&=& B \big(hl C(l)h'l'C(l)^{-1} \big)\\
&=& B \big(hlB(hl)h'l'B(hl)^{-1} \big),
\end{eqnarray*}
which is desired. $\blacksquare$ 
\end{proof}

Note that, in the case of Proposition \ref{semi-direct}, we have $G_B\cong H\rtimes L_C$.
