\subsection{Constructions via homomorphisms and exact formulas}

Note that, if $G$ is an abelian group, then each endomorphism of $G$ is a Rota--Baxter operator on~$G$.


\begin{proposition}\label{prop:RB-Hom}
The following assertions hold:
\begin{enumerate}
 \item If $G$ is a group and $H$ is an abelian subgroup of $G$, then any homomorphism (or anti-homomorphism) $B: G \to H$ is a Rota--Baxter operator on $G$.
 \item If $B$ is a Rota--Baxter operator on $G$ which is also an automorphism of $G$, then  $G$ is abelian.
\end{enumerate}
\end{proposition}

\begin{proof}
If $H$ is abelian and $B: G \to H$ is a homomorphism, then
$$
B \big(gB(g)hB(g)^{-1} \big)= B(g)B^2(g) B(h) \big(B^2(g)\big)^{-1}= B(g)B(h).  
$$
The case of anti-homomorphism is similar, which proves assertion (1).
\para

If $B$ is a Rota--Baxter operator on $G$ which is also an endomorphism, then
$$
B(g)B(h)
 = B \big(gB(g)hB(g)^{-1} \big)
 =B(g)B^2(g) B(h) \big(B^2(g)\big)^{-1}
$$
for all $g,h \in G$. It is equivalent to the relation
\begin{equation}\label{RB-Hom}
[B^2(g), B(h)] = 1.
\end{equation}
for all $g,h \in G$. Thus, if $B$ is an automorphism, then $G$ is abelian, which proves assertion (2).  $\blacksquare$ 
\end{proof}



\begin{corollary}
Let $G$ be a group and $a,b\in G$. Then the map $B: G\to G$ defined as 
$B(g) = agb$, is a Rota--Baxter operator on $G$
if and only if $G$ is abelian and $b = a^{-1}$.
\end{corollary}

\begin{proof}
If $G$ is abelian, then every endomorphism of $G$ is a Rota--Baxter operator on $G$, including the identity map. Conversely, suppose that $B:G \to G$ defined as
$B(g) = agb$ is a~Rota--Baxter operator on $G$.
Since $B(1) = 1$, we obtain $b = a^{-1}$. Thus, $B$ is an (inner) automorphism of~$G$. It follows from Proposition~\ref{prop:RB-Hom}(2) that $G$ is abelian, and hence $b = a^{-1}$.
$\blacksquare$ 
\end{proof}


Given an integer~$k$, a group $G$ is called \index{$k$-abelian group}{$k$-abelian} if $(gh)^k = g^k h^k$ for all $g,h\in G$.

\begin{proposition}\label{prop:n-abelian}
Let $G$ be a group and $n \ge 1$ an integer. Then the map $B: G\to G$ defined by
$B(g) = g^n$ is a Rota--Baxter operator on $G$ if and only if $G$ is $(n+1)$-abelian.
\end{proposition}

\begin{proof}
Given $g,h\in G$, the Rota--Baxter defining identity~\eqref{RB} for $B$ has the form
$$
g^n h^n
 = (g^{n+1}hg^{-n})^n
 = g^{n+1}hg^{-n} \, g^{n+1}hg^{-n} \cdots g^{n+1}hg^{-n}
 = g^n(gh)^n g^{-n}.
$$
This gives
$(gh)^n = h^n g^n$, which is further equivalent to
$$
(hg)^{n+1} = h(gh)^n g = h^{n+1}g^{n+1}.
$$
Thus, $B$ is a Rota--Baxter operator on $G$ if and only if $G$ is $(n+1)$-abelian.
$\blacksquare$ 
\end{proof}

\begin{remark}{\rm 
Since every $k$-abelian group is also $(1-k)$-abelian, the group operation in $G_B$ is given by
$$
g\circ h
 = gg^nhg^{-n}
 = g^{n+1}h^{n+1}h^{-n}g^{-n}
 = (gh)^{n+1}(hg)^{-n}
$$
for all $g, h \in G$.}
\end{remark}

\begin{proposition}\cite[Proposition 24]{MR4556953}\label{prop:center-conj}
Let $G$ be a group and $g \in G$. Then the map $B_g(x) = g^{-1} x^{-1} g$ is a Rota--Baxter operator on $G$ if and only if $[g,G]\subseteq \Z(G)$.
\end{proposition}

\begin{proof}
Suppose that $B_g$ is a Rota--Baxter operator on $G$. This gives
$$
g^{-1} x^{-1}y^{-1} g
 = g^{-1}( x g^{-1}x^{-1}g y g^{-1} x g )^{-1}g
 = g^{-1}g^{-1}x^{-1}gy^{-1}g^{-1}xg x^{-1}g
$$
for all $x,y\in G$. The preceding identity is equivalent to
$$
x^{-1}y^{-1}
 = [g,x]x^{-1}y^{-1}[g,x^{-1}].
$$
Writing $s = x^{-1}y^{-1}$, we have
$[x,g]^s = [g,x^{-1}]$ for all $x,s\in G$.
Fixing $x\in G$, we conclude that $[g,x]\in \Z(G)$ for each $x\in G$.
\para 
Conversely, suppose that $g\in G$ such that $[g,x]\in \Z(G)$ for each $x\in G$. By the preceding argument, it is enough to prove that $[x,g] = [g,x^{-1}]$ for all $x\in G$.
Since
$$
[g,x^{-1}]
 = g^{-1}xgx^{-1}
 = x^{-1}g^{-1}xg[g^{-1}xg,x^{-1}]
 = [x,g]\, [x^g,x^{-1}],
$$
we need to prove that $[x^g,x^{-1}] = 1$. Writing $c = [g,x^{-1}]$, we see that
$$
[x^g,x^{-1}]
 = [[g,x^{-1}]x,x^{-1}]
 = [cx,x^{-1}]
 = x^{-1}c^{-1}xcxx^{-1}
 = 1, 
$$
which is desired. $\blacksquare$ 
\end{proof}

\begin{corollary}\label{coro:2step}
Let $G$ be a 2-step nilpotent group and $g \in G$. Then the map $B_g(x) = g^{-1} x^{-1} g$ is a Rota--Baxter operator.
\end{corollary}


\begin{remark}
{\rm 
Let $G$ be a group and $g \in G$ such that $[g,G]\subset \Z(G)$. If $B_g$ is the Rota--Baxter operator as defined in Proposition \ref{prop:center-conj}, then it is evident that $B_g$ is a bijection. Further, computing the group operation in $G_B$, we see that
$$
x\circ y
 = xB(x)yB(x)^{-1}
 = xg^{-1} x^{-1} gyg^{-1} xg
 = yxg^{-1} x^{-1} gg^{-1} xg
 = yx.
$$
Thus, the group structure induced by $B_g$ coincides with the group structure induced by the Rota--Baxter operator $B_{-1}$.}
\end{remark}


Let $F_n = \langle x_1, \ldots, x_n  \rangle$ be the free group of rank $n$ and $\pi_1 : F_n \to \langle x_1 \rangle$ be the projection given by
$$
\pi_1(x_1) = x_1 \quad \textrm{and} \quad \pi_1(x_i) = 1\quad \textrm{for} \quad i\neq1.
$$
Then we can write $F_n = \ker(\pi_1) \langle x_1 \rangle$. Further, for any integer $k$, the map $B: F_n \to F_n$ given by $B(g) = \pi_1(g)^k$ is a Rota--Baxter operator on $F_n$. The following result generalizes this observation.

\begin{proposition}\label{fr}
Let $G = K * L$ be a free product of two groups, where $L$ is abelian, and let $\pi_1: G \to L$ be the projection onto $L$. Then for any endomorphism $\chi$ of $L$, the map $B:G \to G$
 given by $B(g) = \chi(\pi_1(g))$ is a~Rota--Baxter operator on $G$.
\end{proposition}

We conclude this subsection with the following question.

\begin{question}
Let $G$ be a group and $H$ its proper subgroup. Under what conditions does there exist a Rota--Baxter operator $B$ on $G$ such that $B(G) = H$? In particular, if $F$ is a non-abelian free group, does there exist a Rota--Baxter operator on $F$ whose image is the commutator subgroup of $F$?
\end{question}
