\subsection{Constructions via direct products}

Rota--Baxter operators on direct products of groups can be constructed from Rota--Baxter operators on the component groups \cite[Proposition 30]{MR4556953}.

\begin{proposition} \label{direct}
Let $G = H\times L$ be a direct product of groups $H$ and $L$. Then the following assertions hold: 
\begin{enumerate}
\item Let $B_H$ be a Rota--Baxter operator on $H$ and $B_L$ a Rota--Baxter operator on $L$.
Then the map $B: G\to G$ defined by
$B(hl) = B_H(h)B_L(l)$, where $h\in H$ and $l\in L$, is a Rota--Baxter operator.
\item If $L$ is abelian and $|L|>2$, then
there exists a non-splitting Rota--Baxter operator on $G$.

\end{enumerate}
\end{proposition}

\begin{proof}
The proof of assertion (1) is straightforward. For assertion (2), suppose that every Rota--Baxter operator on $G$ is splitting. Let $\psi$ be an automorphism of $L$. Define $B_\psi : G \to G$ by $B_\psi \big((h,l)\big) = \psi(l)$. Then, by Proposition~\ref{prop:RB-Hom}(1), $B_\psi$ is a~Rota--Baxter operator on~$G$. Further, by Proposition~\ref{SplittingCond}, we should have
$B_\psi \big(lB_\psi(l) \big) = \psi(l)\psi^2(l) = 1$ for all $l\in L$. Taking $\psi = \id$, we have $l^2 = 1$ for all $l\in L$. Since $L$ is abelian, we see that $L$ is a~direct sum of some copies of $\mathbb{Z}_2$. The condition $|L|>2$ implies that we can find two distinct non-trivial elements $l_1,l_2\in L$. Consider the automorphism~$\psi$ of~$L$ which interchanges $l_1$ and $l_2$ and fixes all other elements. Then, it is easy to see that $B_\psi$ is non-splitting, which is a~contradiction.
$\blacksquare$ 
\end{proof}

\begin{example} \label{exm:direct}
{\rm
Let $G$ be a group and $G^n = G\times \cdots \times G$. Then the maps 
$$ B \big((g_1,\ldots,g_n) \big) = \big(1,g_1,g_2g_1,g_3g_2g_1,\ldots,g_{n-1}g_{n-2}\ldots g_1 \big)$$
and
$$\widetilde{B} \big((g_1,\ldots,g_n) \big) = \big(g_1^{-1},g_2^{-1}g_1^{-1},g_3^{-1}g_2^{-1}g_1^{-1},\ldots, g_n^{-1}g_{n-1}^{-1}g_{n-2}^{-1}\ldots g_1^{-1} \big)$$
are Rota--Baxter operators on $G^n$.}
\end{example}



Next, consider the following example from 
 \cite{MR2450698,MR0448155}. Let $\Bbbk$ be a field and $\Bbbk^n = \Bbbk e_1 \oplus \cdots \oplus \Bbbk e_n$, where $e_ie_j = \delta_{ij}e_i$, viewed as an associative $\Bbbk$-algebra. A~linear operator $R:\Bbbk \to \Bbbk$ given by 
$R(e_i) = \sum\limits_{k=1}^n r_{ik}e_k$, where 
$r_{ik}\in \Bbbk$, is a Rota--Baxter operator of weight~1 on~$\Bbbk^n$
if and only if the following conditions are satisfied:
\begin{enumerate}
\item $r_{ii} = 0$ and $r_{ik}\in\{0,1\}$
or $r_{ii} = -1$ and $r_{ik}\in\{0,-1\}$ for all $k\neq i$.
\item If $r_{ik} = r_{ki} = 0$ for $i\neq k$,
then $r_{il}r_{kl} = 0$ for all $l\not\in\{i,k\}$.
\item If $r_{ik}\neq0$ for $i\neq k$,
then $r_{ki} = 0$ and
$r_{kl} = 0$ or $r_{il} = r_{ik}$ for all $l\not\in\{i,k\}$.
\end{enumerate}
We can assume that the matrix of $R$ is upper-triangular~\cite{MR0448155,MR4120095}. We use the preceding example to construct a Rota--Baxter operator on $G^n$ for any group $G$ \cite[Theorem 32]{MR4556953}.

\begin{theorem} \label{theo:directProduct}
Let $G$ be a group, $\Bbbk$ a field and $n \ge 1$ an integer. Let $R$ be a~Rota--Baxter operator of weight~1 on $\Bbbk^n$, given by $R(e_i) = \sum\limits_{i=1}^n r_{ik}e_k$, such that the matrix of $R$ is upper-triangular. Define a~map $B: G^n\to G^n$ by
\begin{equation} \label{RBOnDirectProduct}
B \big((g_1,\ldots,g_n) \big) = (t_1,\ldots,t_n),~~ \textrm{where}~~
t_i = g_i^{r_{ii}}g_{i-1}^{r_{i-1\,i}}\ldots g_1^{r_{1i}}.
\end{equation}
Then $B$ is a Rota--Baxter operator on $G^n$.
\end{theorem}

\begin{proof}
We write  the left and the right hand sides of the Rota--Baxter identity \eqref{RB} for~$B$. Let 
$g = (g_1,\ldots,g_n)$ and $h = (h_1,\ldots,h_n)$ be elements of $G^n$. Then we have
\begin{small}
\begin{eqnarray}
B(g)B(h)
& = &\big(g_1^{r_{11}}h_1^{r_{11}},g_2^{r_{22}}g_1^{r_{12}}h_2^{r_{22}}h_1^{r_{12}},\ldots,
 g_n^{r_{nn}}g_{i-1}^{r_{n-1\,n}}\ldots g_1^{r_{1n}}
 h_n^{r_{nn}}h_{i-1}^{r_{n-1\,n}}\ldots h_1^{r_{1n}}\big), \label{LeftRBSumFields} \\
B\big(gB(g)hB(g)^{-1}\big)
 &= & \big(t_1^{r_{11}},t_2^{r_{22}}t_1^{r_{12}},\ldots,
 t_n^{r_{nn}}t_{n-1}^{r_{n-1\,n}}\ldots t_1^{r_{1n}}\big), \label{RightRBSumFields}
\end{eqnarray}
\end{small}
where
\begin{eqnarray*}
t_1 &=& g_1g_1^{r_{11}}h_1g_1^{-r_{11}},\\
t_2 &=& g_2g_2^{r_{22}}g_1^{r_{12}}h_2g_1^{-r_{12}}g_2^{r_{22}},\\
&& \vdots \\
t_n  &=& g_n g_n^{r_{nn}}g_{n-1}^{r_{n-1\,n}}\ldots g_1^{r_{1n}}h_n g_1^{-r_{1n}}\ldots
 g_{n-1}^{-r_{n-1\,n}}g_n^{-r_{nn}}.
\end{eqnarray*}

We prove by induction on $i$ that the $i$-th coordinates of~\eqref{LeftRBSumFields} and~\eqref{RightRBSumFields} are equal.
For $i = 1$, we desire that
$$
g_1^{r_{11}}h_1^{r_{11}}
 = \big(g_1g_1^{r_{11}}h_1g_1^{-r_{11}}\big)^{r_{11}}.
$$
When $r_{11} = 0$, the equality becomes $1=1$,
and when $r_{11} = -1$, then we get $g_1^{-1}h_1^{-1} = (h_1g_1)^{-1}$. This proves the base step of the induction. Suppose that the $i$-coordinates
of~\eqref{LeftRBSumFields} and~\eqref{RightRBSumFields} are equal
for all $i<k$, where $2\leq k\leq n$. We prove the equality
$$
g_i^{r_{ii}}g_{i-1}^{r_{i-1\,i}}\ldots g_1^{r_{1i}}
h_i^{r_{ii}}h_{i-1}^{r_{i-1\,i}}\ldots h_1^{r_{1i}}
 = t_i^{r_{ii}}t_{i-1}^{r_{i-1\,i}}\ldots t_1^{r_{1i}}
$$
for $i = k$. If $r_{ii} = 0$, then we apply the induction hypothesis for $i-1$ and
for the coefficients $r'_{s\,i-1} = r_{si}$.
If $r_{ii} = -1$, then we apply the induction hypothesis for $i-1$ and
for the coefficients $r'_{s\,i-1} = r_{si}$ to derive
\begin{eqnarray*}
t_i^{r_{ii}}t_{i-1}^{r_{i-1\,i}}\ldots t_1^{r_{1i}}
 &=& (\underline{g_i g_i^{-1}}g_{i-1}^{r_{i-1\,i}}\ldots g_1^{r_{1i}}h_i g_1^{-r_{1i}}
 \ldots g_{i-1}^{-r_{i-1\,i}}g_i)^{-1}
 t_{i-1}^{r_{i-1\,i}}\ldots t_1^{r_{1i}} \\
 &=& g_i^{-1}g_{i-1}^{r_{i-1\,i}}\ldots g_1^{r_{1i}}h_i^{-1}\underline{g_1^{-r_{1i}}
 \ldots g_{i-1}^{-r_{i-1\,i}}
 g_{i-1}^{r_{i-1\,i}}\ldots g_1^{r_{1i}}}h_{i-1}^{r_{i-1\,i}}\ldots h_1^{r_{1i}} \\
 &=& g_i^{r_{ii}}g_{i-1}^{r_{i-1\,i}}\ldots g_1^{r_{1i}}
h_i^{r_{ii}}h_{i-1}^{r_{i-1\,i}}\ldots h_1^{r_{1i}}. 
\end{eqnarray*}
This proves the theorem.
$\blacksquare$ 
\end{proof}

It is not difficult to see that $G^n_B\cong G^n$ in Theorem \ref{theo:directProduct}.

\begin{corollary}
Let $G$ be a group and $\psi_2,\ldots,\psi_n\in\Aut(G)$. Then the map $P: G^n\to G^n$
given by 
$$ P \big((g_1,\ldots,g_n) \big) = (t_1,\ldots,t_n),$$
where 
$$t_1 = g_1^{r_{11}}\quad \textrm{and} \quad t_i = g_i^{r_{ii}}\psi_i\big(g_{i-1}^{r_{i-1\,i}}\psi_{i-1}\big(g_{i-2}^{r_{i-2\,i}}
 \ldots \psi_2\big(g_1^{r_{1i}}\big)\big)\big)$$
 for $i\geq2$, is a Rota--Baxter operator on $G^n$.
\end{corollary}

\begin{proof}
Define an automorphism $\varphi$ of $G^n$ by
$$
\varphi \big((g_1,\ldots,g_n)\big)
 = \big(g_1,\psi_2^{-1}(g_2),\psi_2^{-1}\psi_3^{-1}(g_3),\ldots,\psi_2^{-1}\ldots \psi_n^{-1}(g_n)\big).
$$
It follows from Lemma~\ref{lem:Aut}(1) that $B^{(\varphi)}$ is a Rota--Baxter operator on $G^n$, where $B$ is defined by \eqref{RBOnDirectProduct}. Since $P = B^{(\varphi)}$, the assertion follows.
$\blacksquare$ 
\end{proof}
\bigskip
\bigskip

