\section{Extending maps to Rota--Baxter operators on groups}

Let $(G, B)$ be a Rota--Baxter group.  A natural problem is to identify a minimal subset $A$ of $G$ such that the values of $B$ on $A$ uniquely determine the values of $B$ on the entirety of $G$. Given a subset $A$ of $G$, let $\langle A \rangle_{B}$ denote the subgroup of $G_B$ generated by $A$. The following result addresses the preceding problem \cite[Theorem 36]{MR4556953}.

\begin{theorem}  \label{t}
Let $G$ be a group, $A$ a subset of $G$ and $B$ a Rota--Baxter operator on $G$. Then the following assertions hold:
\begin{enumerate}
\item The values of $B$ on elements of $A$ determine the values of $B$ on elements of $\langle A \rangle_{B}$.  In particular,  $B(\langle A \rangle_{B})$ is generated by $B(A)$.
\item  If $A$ is a generating subset of $G_B$, then the values of $B$ on elements of $A$ uniquely determine the values of~$B$ on the entirety of $G$.
\end{enumerate}
\end{theorem}

\begin{proof}
Let $A = \{a_i \,\mid \, i \in I\}$ and  $B(a_i) = u_i$ for each $i\in I$. Suppose that $g \in \langle A \rangle_{B}$, which is written as
$$
g = a_{i_1}^{\circ(k_1)} \circ a_{i_2}^{\circ(k_2)} \circ \cdots \circ a_{i_s}^{\circ(k_s)},
$$
where $a_{i_j}\in A$ and $k_{i_j} \in \mathbb{Z}$. Since $B$ is a group homomorphism from $G_B$ to $G$, we have
$$
B(g) = B\big(a_{i_1}^{\circ(k_1)}\big) B\big(a_{i_2}^{\circ(k_2)}\big)
 \cdots B\big(a_{i_s}^{\circ(k_s)}\big) = u_{i_1}^{k_1} u_{i_2}^{k_2} \ldots u_{i_s}^{k_s}.
$$
Hence, we can determine the values of $B$ on the subgroup $\langle A\rangle_B $, which proves assertion (1). In particular, if $\langle A \rangle_{B}$ equals $G_B$, then we can also determine values of $B$ on elements of $G$, which establishes assertion (2).
$\blacksquare$ 
\end{proof}

Next, we consider the general situation. Let $G$ be a~group generated by a~set $A = \{ a_i \mid i \in I \}$. Let $U = \{u_i \, \mid \, i \in I \}$ be a subset of~$G$ with the same cardinality as that of $A$ and $\beta : A \to U$ the map defined by $\beta(a_i) = u_i$ for each $i \in I$. Consider a set $\bar{A} = \{\bar{a_i} \,\mid \, i \in I \}$ which is disjoint from $A$ and has the same cardinality as that of $A$.
Let $F(\bar{A})$ be the free group with basis $\bar{A}$, and denote the group operation in $F(\bar{A})$ by~$\circ$. An element $w$ of $F(\bar{A})$ can be uniquely presented by a~reduced word as
$$
w = \bar{a}_{i_1}^{\circ(k_1)} \circ \bar{a}_{i_2}^{\circ(k_2)}
 \circ \cdots \circ \bar{a}_{i_s}^{\circ(k_s)},
$$
where $\bar{a}_{i_j} \in \bar{A}$ and $k_{i_j} \in \mathbb{Z} \setminus \{0\}$.
Define a~map $\bar{\beta} : F(\bar{A}) \to G$ by
$$
\bar{\beta}(w) = \beta(a_{i_1})^{k_1} \beta(a_{i_2})^{k_2} \cdots \beta(a_{i_s})^{k_s}
 = u_{i_1}^{k_1}  u_{i_2}^{k_2}  \cdots u_{i_s}^{k_s}.
$$
Then $\bar{\beta}$ is a group homomorphism with image $\langle U \rangle$. Define a map $\pi : F(\bar{A}) \to G$ by 
$$
\pi(w) = \big(a_{i_1}\beta(a_{i_1})\big)^{k_1}
    \big(a_{i_2}\beta(a_{i_2}) \big)^{k_2} \cdots
    \big(a_{i_s}\beta(a_{i_s}) \big)^{k_s}
    \beta(a_{i_s})^{-k_s}
    \beta(a_{i_{s-1}})^{-k_{s-1}} \cdots
    \beta(a_{i_1})^{-k_1}.
    $$
The following result clarifies the connection between the maps $\pi$ and $\bar{\beta}$.

\begin{lemma} \label{l7.3}
Let $w, w' \in F(\bar{A})$. Then the following  assertions hold:
\begin{enumerate}
\item $\pi(w^{\circ({-1})}) = \bar{\beta}(w)^{-1} \pi(w)^{-1} \bar{\beta}(w)$.
\item $\pi(w \circ w' ) =  \pi(w) \bar{\beta}(w) \pi(w')   \bar{\beta}(w)^{-1}$.
\item $\pi \big((w')^{\circ(-1)} \circ w \circ w' \big) = \bar{\beta}(w')^{-1} \pi(w')^{-1} \pi(w)
 \bar{\beta}(w) \pi(w') \bar{\beta}(w)^{-1} \bar{\beta}(w')$.
\end{enumerate}
\end{lemma}

\begin{proof}
If $w = \bar{a}_{i_1}^{\circ(k_1)} \circ \bar{a}_{i_2}^{\circ(k_2)}
 \circ \cdots \circ \bar{a}_{i_s}^{\circ(k_s)},
$ then its inverse is
$$
w^{\circ({-1})} = \bar{a}_{i_s}^{\circ(-k_s)}
 \circ \bar{a}_{i_{s-1}}^{\circ(-{k_{s-1}})}
 \circ \cdots \circ \bar{a}_{i_1}^{\circ(-k_1)}
$$
and
$$
\pi(w^{\circ({-1})})
= \big(a_{i_s}\beta(a_{i_s})\big)^{-k_s}
    \big(a_{i_{s-1}}\beta(a_{i_{s-1}})\big)^{-k_{s-1}} \cdots
    \big(a_{i_1}\beta(a_{i_1})\big)^{-k_1}
    \beta(a_{i_1})^{k_1}
    \beta(a_{i_{2}})^{k_{2}} \cdots
    \beta(a_{i_s})^{k_s}.
$$
This gives
$$
\pi(w^{\circ({-1})})
 = \beta(a_{i_s})^{-k_s} \cdots \beta(a_{i_1})^{-k_1} \pi(w)^{-1}
 \beta(a_{i_1})^{k_1} \cdots \beta(a_{i_s})^{k_s}=\bar{\beta}(w)^{-1} \pi(w)^{-1} \bar{\beta}(w),
$$
which establishes assertion (1).
\para 
Given $w' = \bar{a}_{j_1}^{\circ(l_1)} \circ \bar{a}_{j_2}^{\circ(l_2)}
   \circ \cdots \circ \bar{a}_{j_t}^{\circ(l_t)},
$
we have
$$
w \circ w'
 = \bar{a}_{i_1}^{\circ(k_1)}  \circ \cdots \circ \bar{a}_{i_s}^{\circ(k_s)}
  \circ \bar{a}_{j_1}^{\circ(l_1)}  \circ \cdots \circ \bar{a}_{j_t}^{\circ(l_t)}
$$
and
\begin{eqnarray*}
\pi(w \circ w')
 &=& \big(a_{i_1}\beta(a_{i_1})\big)^{k_1} \cdots \big(a_{i_s}\beta(a_{i_s})\big)^{k_s} \,
  \big(a_{j_1}\beta(a_{j_1}) \big)^{l_1} \cdots  \big(a_{j_t}\beta(a_{j_t})\big)^{l_t} \\
 &&\beta(a_{j_t})^{-l_t} \cdots \beta(a_{j_1})^{-l_1}\, \beta(a_{i_s})^{-k_s} \cdots \beta(a_{i_1})^{-k_1}.
\end{eqnarray*}
Hence, we have
$$
\pi(w \circ w' )
 = \pi(w) \beta(a_{i_1})^{k_1} \cdots \beta(a_{i_s})^{k_s}
   \pi(w') \, \beta(a_{i_s})^{-k_s} \cdots \beta(a_{i_1})^{-k_1}
 = \pi(w) \bar{\beta}(w) \pi(w') \bar{\beta}(w)^{-1},
$$
which proves assertion (2).
\para 

Considering the product $(w')^{\circ(-1)} \circ w \circ w'$, we see that
\begin{eqnarray*}
&& \pi \big((w')^{\circ(-1)} \circ w \circ w' \big)\\
 &=& \beta(a_{j_l})^{-l_t} \cdots \beta(a_{j_1})^{-l_1}
 \big( \pi(w')^{-1} \pi(w) \beta(a_{i_1})^{k_1} \cdots \beta(a_{i_s})^{k_s} \pi(w')
  \beta(a_{i_s})^{-k_s} \cdots \beta(a_{i_1})^{-k_1} \big)
 \beta(a_{j_1})^{l_1} \cdots \beta(a_{j_t})^{l_t} \\
 &=& \bar{\beta}(w')^{-1} \pi(w')^{-1} \pi(w) \bar{\beta}(w)
 \pi(w') \bar{\beta}(w)^{-1} \bar{\beta}(w'),
\end{eqnarray*}
which is assertion (3).
$\blacksquare$ 
\end{proof}

Lemma \ref{l7.3} immediately yields the following result.

\begin{lemma}
Let $R = \{ w \in F(\bar{A}) \, \mid \, \pi(w) = 1 \}$.  
\begin{enumerate}
\item $R$ is a~subgroup of $F(\bar{A})$. 
\item Suppose that $\pi$ and $\bar{\beta}$ satisfy the following implication:
\begin{equation} \label{condition ab}
\pi(w) = \pi(w') \Rightarrow \bar{\beta}(w) = \bar{\beta}(w').
\end{equation}
Then $R$~is a normal subgroup of $F(\bar{A})$.
\end{enumerate}
\end{lemma}

\begin{lemma}\label{lem:RB-extCond}
Let $w, w' \in F(\bar{A})$ be such that $\pi(w) = \pi(w')$ and $\bar{\beta}(w) \neq \bar{\beta}(w')$. Then the map $\beta$~has no extension to a Rota--Baxter operator on $G$.
\end{lemma}

\begin{proof}
Suppose that $B$~is an extension of~$\beta$ to a Rota--Baxter operator~on~$G$. Let
$$
w = \bar{a}_{i_1}^{\circ(k_1)} \circ \bar{a}_{i_2}^{\circ(k_2)}
 \circ \cdots \circ \bar{a}_{i_s}^{\circ(k_s)}\quad \textrm{and}\quad
w' = \bar{a}_{j_1}^{\circ(l_1)} \circ \bar{a}_{j_2}^{\circ(l_2)}
 \circ \cdots \circ \bar{a}_{j_t}^{\circ(l_t)}.
$$
Consider the elements
$$
u = a_{i_1}^{\circ(k_1)} \circ a_{i_2}^{\circ(k_2)}
 \circ \cdots \circ a_{i_s}^{\circ(k_s)} \quad \textrm{and}\quad
u' = a_{j_1}^{\circ(l_1)} \circ a_{j_2}^{\circ(l_2)}
 \circ \cdots \circ a_{j_t}^{\circ(l_t)}
$$
of $G_B$. Then we have
$$
B(u) = \beta(a_{i_1})^{k_1}\cdots \beta(a_{i_s})^{k_s}
 = \bar{\beta}(w)
 \neq \bar{\beta}(w')
 = \beta(a_{j_1})^{l_1}\cdots \beta(a_{j_t})^{l_t}
 = B(u').
$$
On the other hand, in view of Proposition \ref{for}, we have
$$
B(u)
 = B \big(\pi(w)\big)
 = B \big(\pi(w')\big)
 = B(u'),
$$
which is a contradiction.
$\blacksquare$ 
\end{proof}


If $R$ is a~normal subgroup of $F(\bar{A})$,
then we can define the group $$\bar{G}_{\beta} = F(\bar{A}) / R.$$
Let $[w]$ denote the element of $\bar{G}_{\beta}$ represented by an element $w \in F(\bar{A})$. Then we write the product in $\bar{G}_{\beta}$ as $[w] \circ [w']  = [w \circ w']$. Note that $\bar{G}_{\beta}$ is generated by $\big\{ [\bar{a_i}] \, \mid \,  i\in I \big\}$ and has defining relations $[w] = [w']$ for all words
$$
w = \bar{a}_{i_1}^{\circ(k_1)} \circ \bar{a}_{i_2}^{\circ(k_2)}
 \circ \cdots \circ \bar{a}_{i_s}^{\circ(k_s)} \quad \textrm{and}\quad
w' = \bar{a}_{j_1}^{\circ(l_1)} \circ \bar{a}_{j_2}^{\circ(l_2)}
 \circ \cdots \circ \bar{a}_{j_t}^{\circ(l_t)}
$$
such that $\pi(w) = \pi(w')$. In other words, $[w] = [w']$ if and only if the relation
\begin{eqnarray*}
&& \big(a_{i_1}\beta(a_{i_1})\big)^{k_1}
    \big(a_{i_2}\beta(a_{i_2})\big)^{k_2} \ldots
    \big(a_{i_s}\beta(a_{i_s})\big)^{k_s}
    \beta(a_{i_s})^{-k_s}
    \beta(a_{i_{s-1}})^{-k_{s-1}} \ldots
    \beta(a_{i_1})^{-k_1} \\
& =&  \big(a_{j_1}\beta(a_{j_1})\big)^{l_1}
    \big(a_{j_2}\beta(a_{j_2})\big)^{l_2} \ldots
    \big(a_{j_t}\beta(a_{j_t})\big)^{l_t}
    \beta(a_{j_l})^{-l_t}
    \beta(a_{j_{t-1}})^{-l_{t-1}} \ldots
    \beta(a_{j_1})^{-l_1}
\end{eqnarray*}
holds in  $G$.
\para
If condition~\eqref{condition ab} is satisfied, then the homomorphism
$\bar{\beta} : F(\bar{A}) \to \langle U \rangle \leq G$
induces a homomorphism
$\bar{G}_{\beta} \to \langle U \rangle$, which we again denote by $\bar{\beta}$.
Also, the map $\pi : F(\bar{A}) \to G$ induces a map
$\bar{\pi}:\bar{G}_{\beta} \to G$. It is easy to see that $\im(\pi) = \im(\bar{\pi})$. Let us consider an illustration of Lemma~\ref{lem:RB-extCond}.

\begin{example}{\rm 
Consider the symmetric group
$$
\Sigma_3 = \big\langle s_1, s_2  \, \mid \,  s_1^2 = s_2^2 = 1~~\textrm{and} ~~s_1 s_2 s_1 = s_2 s_1 s_2 \big\rangle
$$
on three symbols. 
\begin{enumerate}
\item If we take the map $\beta : \{ s_1, s_2 \} \to \{ s_1, s_2 \}$
such that $\beta(s_1)= s_1$ and $\beta(s_2)= s_2$, then it has an extension to the Rota--Baxter operator
$B_{-1}(g) = g^{-1}$ on $\Sigma_3$. Let us determine the group $\bar{G}_{\beta}$.
Let $F(\bar{A})$ be the free group with basis $\bar{A} = \{ t_1, t_2 \}$. We have the map $\pi : F(\bar{A}) \to G$ defined by 
$$
\pi \big(t_1^{\circ(k_1)} \circ t_2^{\circ(l_1)} \circ
 \cdots \circ t_1^{\circ(k_s)} \circ t_2^{\circ(l_s)}\big)
 = s_2^{-l_s} s_1^{-k_s} \cdots s_2^{-l_1} s_1^{-k_1}.
$$
In this case, $R = \{ w \in F(\bar{A}) \, \mid \, \pi (w) = 1 \}$ is normal in $F(\bar{A})$ and the product in $\bar{G}_{\beta}$ is opposite to the product in~$G$.
\item  Note that $\Sigma_3$ is also generated by the elements $\tau_1 = s_1$,
$\tau_2 = s_2$ and $\tau_3 = s_1 s_2 s_1$. Suppose that
$$
\beta(\tau_1) = \tau_1,\quad
\beta(\tau_2) = \tau_2 \quad \textrm{and} \quad
\beta(\tau_3) = \tau_2 \tau_1.
$$
Let  $F(\bar{A})$ be the free group with basis $\bar{A} =\{t_1,t_2,t_3\}$.
Then we have
\begin{gather*}
\pi(t_1 \circ t_1) = \pi(t_2 \circ t_2) = \pi(t_3 \circ t_1) = 1, \quad
\pi(t_1 \circ t_2 \circ t_1) = \pi(t_2 \circ t_1 \circ t_2) = \tau_1 \tau_2 \tau_1, \\
\pi(t_1 \circ t_2) = \pi(t_2 \circ t_3) = \pi(t_3 \circ t_3) =  \tau_2 \tau_1 \quad \textrm{and} \quad
\pi(t_2 \circ t_1) = \pi(t_3 \circ t_2) = \pi(t_1 \circ t_3) = \tau_1 \tau_2.
\end{gather*}
Hence, we have $\pi(F(\bar{A}))  = \Sigma_3$. On the other hand, we have
$$
1 = \bar{\beta}(t_1 \circ t_1)  \not= \bar{\beta}(t_3 \circ t_1) = t_2.
$$
Thus,  by Lemma~\ref{lem:RB-extCond}, the map $\beta$ has no extension to a~Rota--Baxter operator on $\Sigma_3$.
\end{enumerate}}
\end{example}

We now formulate the main result of this subsection \cite[Theorem 41]{MR4556953}.

\begin{theorem} \label{thm:RBextension}
Let $G$ be a~group generated by a~set $A = \{ a_i \, \mid\, i \in I \}$. Let $U = \{u_i \,\mid \, i \in I\}$ be a subset of~$G$ with the same cardinality as that of $A$ and $\beta : A \to U$ the map given by $\beta(a_i) = u_i$ for each $i \in I$. If condition~\eqref{condition ab} is satisfied and the map $\bar{\pi} : \bar{G}_{\beta} \to G$ is bijective, then $\beta$~can be extended to a Rota--Baxter operator on~$G$ with $G_B\cong \bar{G}_{\beta}$.
\end{theorem}

\begin{proof}
Let $g \in G$ be an element. Since $\bar{\pi}$ is invertible, there exists a~unique element
$\bar{g} \in \bar{G}_{\beta}$ such that $\bar{\pi}(\bar{g}) = g$. Suppose that $\bar{g} = [w]$, where
$$
w = \bar{a}_{i_1}^{\circ(k_1)} \circ \bar{a}_{i_2}^{\circ(k_2)}
 \circ \cdots \circ \bar{a}_{i_s}^{\circ(k_s)}
$$
is a~word in the free group $F(\bar{A})$. We define $B:G \to G$ by
$$
B(g)
 = B \big(\bar{\pi}(\bar{g})\big)
 = B \big(\pi(w)\big)
 = \bar{\beta}(w)
 =  u_{i_1}^{k_1} u_{i_2}^{k_2} \cdots  u_{i_s}^{k_s}.
$$
Condition~\eqref{condition ab} implies that $B$ does not depend on the choice of~$w$.
\para 
Next we prove that~$B$ is a~Rota--Baxter operator on~$G$. For $g' \in G$, there exists
$$
w' = \bar{a}_{j_1}^{\circ(l_1)} \circ \bar{a}_{j_2}^{\circ(l_2)}
 \circ \cdots \circ \bar{a}_{j_t}^{\circ(l_t)}
$$
such that $\pi(w') = \bar{\pi}([w']) = g'$. Thus, we have $B(g') = u_{j_1}^{l_1} u_{j_2}^{l_2} \ldots  u_{j_t}^{l_t}$. On the other hand, by Lemma \ref{l7.3}(2), we get
$$
\pi(w \circ w') = \pi(w) \bar{\beta}(w) \pi(w') \bar{\beta}(w)^{-1},
$$
and consequently
\begin{eqnarray*}
B\big( gB(g)g'B(g)^{-1} \big)
 &=& B \big(\pi(w \circ w') \big)\\
 &=& \bar{\beta}(w \circ w')\\
 &=& \bar{\beta}(w) \bar{\beta}(w') \\
 &=& u_{i_1}^{k_1} u_{i_2}^{k_2} \cdots  u_{i_s}^{k_s}\cdot u_{j_1}^{l_1} u_{j_2}^{l_2} \ldots  u_{j_t}^{l_t}\\
 &=& B(g)B(g').
\end{eqnarray*}
Hence, $B$ is indeed a Rota--Baxter operator on $G$, which extends $\beta$.
$\blacksquare$ 
\end{proof}

The next result shows that condition~\eqref{condition ab} is not sufficient for extending a given map to a  Rota--Baxter operator.

\begin{proposition}
Let $\Sigma_3$ be the symmetric group on 3 symbols. Then the following  assertions hold:
\begin{enumerate}
\item The map $\beta$ given by $\beta(s_1)= s_1$ and  $\beta(s_2)= 1$ defines the group
$\bar{G}_{\beta}$, which is isomorphic to $\mathbb{Z}_2\times \mathbb{Z}_2$.
\item There is no~Rota--Baxter operator on $\Sigma_3$ extending the map $\beta$.
\end{enumerate}
\end{proposition}

\begin{proof}
Consider the free group $\langle t_1, t_2 \rangle$ of rank two. Then, we have
$$
\pi(t_1 \circ t_1) = \pi(t_2\circ t_2) = 1 \quad \textrm{and}\quad \pi(t_1 \circ t_2) = \pi(t_2\circ t_1) = s_2 s_1.
$$
It follows from the equalities
$$
\bar{\beta}(t_1 \circ t_1) = \bar{\beta}(t_2\circ t_2) = 1 \quad \textrm{and}\quad
\bar{\beta}(t_1 \circ t_2) = \bar{\beta}(t_2\circ t_1) =  s_1
$$
that \eqref{condition ab} holds, and 
$$
\bar{G}_{\beta}  = \big\langle [t_1], [t_2]  \, \mid \,  [t_1] \circ [t_1] = [t_2] \circ [t_2] = 1~\textrm{and}~[t_1] \circ [t_2] = [t_2]\circ [t_1] \big\rangle \cong \mathbb{Z}_2 \times \mathbb{Z}_2.
$$
\para 
Suppose that there is a Rota--Baxter operator $B$ extending the map $\beta$. Since $B(s_2) = 1$, by Lemma \ref{kernelCosets}, we have
$$
B(s_1 s_2) = B(s_2s_1s_2) = B(s_1 s_2 s_1).
$$
Noting that
$$
s_1 B(s_1s_2)
 = B(s_1)B(s_1s_2)
 = B(s_1 s_1 s_1s_2 s_1)
 = B(s_1 s_2 s_1)
 = B(s_1s_2), 
$$
we arrive at a contradiction. $\blacksquare$ 
\end{proof}

The following result gives some elementary Rota--Baxter operators on free groups \cite[Proposition 43]{MR4556953}. 

\begin{proposition} 
Let $F(A)$ be a free group with a basis $A = \{a_i \, \mid \, i \in I\}$.  Then the following  assertions hold:
\begin{enumerate}
\item The map $\beta$, given by $\beta(a_i) = 1$ for all $i \in I$, has the unique extension to the trivial Rota--Baxter operator $B_0$ on $F(A)$. 
\item The map $\beta$, given by $\beta(a_i)=  a_i^{-1}$ for all $i \in I$, has the unique extension to the Rota--Baxter operator $B_{-1}$ on $F(A)$. 
\end{enumerate}
\end{proposition}

\begin{proof}
Let $B$ be an extension of $\beta$ to a Rota--Baxter operator on $F(A)$, where $\beta(a_i)=1$ for all $i \in I$. We use $\circ$ to denote the product  given by \eqref{R-product}. In this case, $a_i^{\circ (k)} = a_i^k$, and hence $B(a_i^{\circ (k)}) = 1$
for all $i \in I$ and $k \in \mathbb{Z}$. If
$$
w = a_{i_1}^{\circ(k_1)} \circ a_{i_2}^{\circ(k_2)} \circ \cdots
 \circ a_{i_s}^{\circ(k_s)},
$$
where $a_{i_j} \in A$ and $k_{i_j} \in \mathbb{Z}$, is an arbitrary element, then we have
$$
B(w)
 = B\big(a_{i_1}^{\circ(k_1)}\big)
   B\big(a_{i_2}^{\circ(k_2)}\big)
   \cdots B\big(a_{i_s}^{\circ(k_s)}\big)
 = 1,
$$
which proves assertion (1). The proof of assertion (2) is similar. $\blacksquare$ 
\end{proof}

The following problem seems natural at this point.

\begin{problem}
Determine all Rota--Baxter operators on non-abelian free groups.
\end{problem}
\para

The following example shows that the values of~$\beta$ on the generators of $F_n$ do not determine the values of~$\beta$ on all elements of $F_n$.

\begin{example} \label{e7.8}
{\rm 
Let $F_2 = \langle a, b \rangle$ be the free group of rank two. We take $\beta(a) = a$ and $\beta(b) = 1$.
By Proposition \ref{fr}, there exists a Rota--Baxter operator on $F_2$ which is extension of the map~$\beta$. In fact, the Rota--Baxter operator $B$ is the endomorphism of $F_2$ given by $B(a) = \beta(a) = a$ and $B(b) = \beta(b) = 1$. As usual, we write the product in $F_2$ as the juxtaposition and the product in $(F_2)_B$ as $\circ$. We attempt do define the binary operation~$\circ$ on~$F_2$ by applying only the map~$\beta$.
We have
\begin{eqnarray*}
a^{\circ(k)} &=& a^k,\\
b^{\circ(l)} &=& b^l,\\
\beta(a^{\circ(k)}) &=& \beta(a)^k = a^k,\\
\beta(b^{\circ(l)}) &=&  \beta(b)^l = 1
\end{eqnarray*}
for all $k, l \in \mathbb{Z}$. For words of syllable length two, we have
$$ a^{\circ(k)} \circ b^{\circ(l)} = a^{2k} b^l a^{-k}\quad \textrm{and} \quad b^{\circ(l)} \circ a^{\circ(k)} =  b^l a^{k}$$
for all $k,l \in \mathbb{Z}$. By Proposition~\ref{for}, for a word of arbitrary length, we have
$$
w = a^{\circ(k_1)} \circ b^{\circ(l_1)} \circ a^{\circ(k_2)} \circ b^{\circ(l_2)}
  \circ \cdots \circ a^{\circ(k_s)} \circ b^{\circ(l_s)}
  = a^{2k_1} b^{l_1} a^{2k_2} b^{l_2}\cdots a^{2k_s} b^{l_s} a^{-\sum k_i}.
$$
Further, we see that
$$
\beta(w) = a^{\sum k_i}.
$$
Hence, we can construct an extension of~$\beta$ to the subgroup~$S = \langle a,b  \rangle_B$ of $(F_2)_B$ generated by $a$ and~$b$. Thus, $\ker(\beta) = \{ w  \, \mid \,  \sum k_i = 0 \}$
is the normal closure of~$b$ in $S$. Hence, $S \neq F_2$ and $ab \not\in S$. Let us add the element $ab$ to the generating set $\{a, b\}$ and put
$$
\beta_1(a) = \beta_1(ab) = a \quad \textrm{and} \quad \beta_1(b) =  1.
$$
Then, by Proposition~\ref{for}, for each $m \in \mathbb{Z}$, we have
$$
(ab)^{\circ (m)} = (aba)^m a^{-m} 
$$
in the group $T = \langle a, b, ab \rangle_B$. In particular, $ab, a^{-1} b^{-1}\in T$, and $T$ also consists of elements
\begin{eqnarray*}
 && a^{\circ(k_1)} \circ b^{\circ(l_1)} \circ (ab)^{\circ(m_1)}
 \circ a^{\circ(k_2)} \circ b^{\circ(l_2)} \circ  (ab)^{\circ(m_2)} \circ \cdots
  \circ a^{\circ(k_s)} \circ b^{\circ(l_s)} \circ (ab)^{\circ(m_s)} \\
  &=& a^{2k_1}  b^{l_1} (aba)^{m_1} a^{2k_2} b^{l_2} (aba)^{m_2}
  \cdots  a^{2k_s}  b^{l_s} (aba)^{m_s} a^{-\sum (k_i+m_1)}
\end{eqnarray*}
for integers $k_i, l_i, m_i$. It is not difficult to see that $T\neq F_2$.}
\end{example}

