\section{Rota--Baxter operators on groups and associated Lie rings}

In \cite{MR4271483}, motivated by Rota--Baxter operators on Lie algebras arising from Lie groups,  Guo et al. introduced Rota--Baxter operators on (abstract) groups. We see that this connection can be extended to the \index{Lie ring}{Lie ring} of any group.

\begin{definition}
Let $G$ be a group and $\{\gamma_n(G) \}_{n \ge 1}$ be its lower central series, where $\gamma_1(G) = G$ and $\gamma_{n+1}(G) = [G,\gamma_n(G)]$ for each $n \ge 1$. The Lie ring $L(G)$ of $G$
is the associated graded abelian group
$$L(G) = \bigoplus_{n\geq1} \gamma_n(G)/ \gamma_{n+1}(G)$$
equipped with the Lie bracket
$[x \gamma_{i+1}(G), \, y \gamma_{j+1}(G)] = [x,y] \gamma_{i+j+1}(G)$, where $[x,y]$ is the usual commutator in $G$. 
\end{definition}

We have the following result  \cite[Theorem 46]{MR4556953}. 

\begin{proposition} \label{prop:LieRing}
Let $B$ be a Rota--Baxter operator on a group $G$ such that $B\big(\gamma_n(G)\big)\subseteq \gamma_n(G)$ for all $n\geq1$.
Then the map $R:L(G) \to L(G)$ defined by $R \big(x \gamma_{i+1}(G)\big) = B(x) \gamma_{i+1}(G)$ is a Rota--Baxter operator
of weight~1 on the Lie ring $L(G)$.
\end{proposition}

\begin{proof}
Given $h\in \gamma_i(G)$ and $g\in \gamma_{i+1}(G)$, it follows from Lemma~\ref{lem:elementary}(4) that
$B(h)^{-1}B(hg)\in \gamma_{i+1}(G)$, and hence $R$ is well-defined. For $x\in \gamma_i(G)$ and $y\in \gamma_j(G)$, we need to prove that
$$
\big[R(x \gamma_{i+1}(G)),R(y \gamma_{j+1}(G)) \big]
 = R\big( [R(x \gamma_{i+1}(G)),y \gamma_{j+1}(G)] + [x \gamma_{i+1}(G), R(y \gamma_{j+1}(G))] + [x \gamma_{i+1}(G),y \gamma_{j+1}(G)] \big),
$$
which in terms of $B$ is equivalent to 
\begin{equation}\label{LieRing}
B(x)^{-1}B(y)^{-1}B(x)B(y) \gamma_{i+j+1}(G)
 = B\big( [B(x),y] + [x,B(y)] + [x,y] \big)\gamma_{i+j+1}(G).
\end{equation}
Applying the commutator properties and the fact that each $\gamma_{i+j}(G)/\gamma_{i+j+1}(G)$ is abelian,
we rewrite the expression inside the brackets on the right-hand side of~\eqref{LieRing}  as
\begin{eqnarray*}
&& [B(x),y] + [x,B(y)] + [x,y] \\
 &=&  [B(x),y]^{B(y)}  + [x,B(y)]^{B(x)} + [x,y]^{B(y)B(x)} 
 +  [B(x),B(y)] + [B(y),B(x)] \\
 &=& [x,yB(y)]^{B(x)}  +  [B(x),yB(y)] + [B(y),B(x)]\\
 &=& [xB(x),yB(y)] + [B(y),B(x)] \quad \mod \gamma_{i+j+1}(G).
\end{eqnarray*}
Finally, equation \eqref{LieRing} is a consequence of the Rota--Baxter identities satisfied in $G$, that is,
\begin{eqnarray*}
&& B(y)B(x) ~ B\big([xB(x),yB(y)] \, [B(y),B(x)]\big) \\
 &=& B \big(yB(y)xB(y)^{-1}\big) ~ B \big([xB(x),yB(y)] \, [B(y),B(x)] \big) \\
 &=& B\Big( yB(y)x B(y)^{-1}~B(y) B(x)~(xB(x))^{-1}(yB(y))^{-1}xB(x)y B(y)~B(y)^{-1} B(x)^{-1}B(y)B(x)~B(x)^{-1}B(y)^{-1} \Big) \\
 &= & B \big( yB(y)xB(x)B(x)^{-1}x^{-1} B(y)^{-1}y^{-1}xB(x)yB(x)^{-1}B(y)B(y)^{-1} \big) \\
 &=& B \big(yB(y)B(y)^{-1}y^{-1}xB(x)yB(x)^{-1} \big)\\
 &=& B(x)B(y),
\end{eqnarray*}
and the proof is complete.
$\blacksquare$ 
\end{proof}

\begin{example}{\rm 
Let $G$ be a 2-step nilpotent group and $B$ a Rota--Baxter operator on~$G$ defined as in Proposition~\ref{prop:center-conj}.
Then by Proposition~\ref{prop:LieRing}, we get a Rota--Baxter operator
$R: L(G)\to L(G)$, where $L(G) = G/[G,G]\oplus [G,G]$. A direct check shows that $R = -\id$.}
\end{example}
\para

An automorphism of a group  is called \index{fixed-point free automorphism}{\it fixed-point free} if it does not fix any non-trivial element. We now state a group theoretic analogue of \cite[Proposition 2.21]{MR3977738}, which was proven therein for Lie algebras (see also~\cite{MR0674005}).

\begin{theorem} \cite[Theorem 50]{MR4556953} \label{thm:invertibleRB}
Let $G$ be a finite non-abelian simple group and $B$ a Rota--Baxter operator on~$G$ such that $\ker(B) = 1$.
Then $B(g) = g^{-1}$ for all $g \in G$.
\end{theorem}

\begin{proof}
Since $B$ is a group homomorphism from $G_B$ to $G$ with trivial kernel, we conclude that $G_B\cong G$, and hence $G_B$ is also simple.
Suppose that $\ker(B_+)\neq G_B$, where $B_+(g) = gB(g)$ is a~homomorphism from $G_B$ to $G$. It follows from the simplicity of $G_B$ that $\ker(B_+) =1$. Thus, we have an automorphism $\varphi = B^{-1}B_+$ of the simple group $G_B$. Note that $\varphi$ is fixed-point free. Indeed, $g = \varphi(g) = B^{-1} \big(gB(g)\big)$ would imply that $B(g) = gB(g)$, that is, $g = 1$ By \cite{MR1334233}, a finite group admitting a fixed-point free automorphism is solvable, which is a contradiction. Hence, $\ker(B_+)= G_B$, that is, $B(g) = g^{-1}$ for all $g \in G$. $\blacksquare$ 
\end{proof}

\begin{corollary}
Let $G$ be a finite group and $B$ a Rota--Baxter operator on~$G$. If  $G_B$ is a non-abelian simple group, then $B$ is elementary and $G\cong G_B$.
\end{corollary}

\begin{proof}
Since $\ker(B)$ is a normal subgroup of $G_B$ and $G_B$ is simple, we have either $\ker(B) = G$ or $\ker(B)=1$. If $\ker(B) = G$, then $B$ is elementary and $G\cong G_B$. If $\ker(B)=1$, then $G\cong G_B$ by Theorem~\ref{thm:invertibleRB}.
$\blacksquare$ 
\end{proof}

\begin{corollary}\label{coro:invertibleRB}
Let $G$ be a finite non-abelian simple group. If $G$ is not factorizable, then $G$ is Rota--Baxter elementary.
\end{corollary}

\begin{proof}
Let $B$ be a non-elementary Rota--Baxter operator on $G$. By Theorem~\ref{thm:invertibleRB}, we have a proper factorization~\eqref{ImageFactorization},
which is a contradiction.
$\blacksquare$ 
\end{proof}

