\chapter{Rota--Baxter groups and skew braces }\label{chap RBG and YBE}

\begin{quote}
This chapter investigates the relationship between Rota--Baxter groups and skew left braces. We show that every Rota--Baxter group naturally gives rise to a skew left brace, and conversely, any skew left brace with a complete additive group can be constructed in this way. The chapter also examines set-theoretic solutions to the Yang--Baxter equation that emerge from Rota--Baxter groups, along with the structure and characteristics of symmetric skew left braces. Additionally, we show that the obstruction to induction of a skew left brace from a Rota--Baxter operator lies in certain second group cohomology.
\end{quote}
\bigskip


\section{Relations between Rota--Baxter groups and skew braces}

We begin with the following result that gives a connection between Rota--Baxter groups and skew left braces \cite[Proposition 3.1]{MR4370524}.

\begin{proposition} \label{RBToSLB}
Let  $B$ be a Rota--Baxter operator on a group $(G,\cdot)$. If we set $x \circ_B y = xB(x)yB(x)^{-1}$ for all $x, y \in G$, then $(G, \cdot, \circ_B)$ is a skew left brace.
\end{proposition}

\begin{proof}
By~Proposition~\ref{prop:Derived}(1), $(G,\circ_B)$ is a group. Writing the product in $(G, \cdot)$ as juxtaposition, we see that
$$
(x\circ_B y) x^{-1}(x\circ_B z)
 = xB(x) y \, B(x)^{-1} x^{-1}xB(x) z B(x)^{-1}
 = xB(x)y z B(x)^{-1}
 = x\circ_B(yz)
$$
for all $x, y, z \in G$, which is desired. $\blacksquare$ 
\end{proof}

For brevity,  the skew left brace $(G, \cdot, \circ_B)$ induced by the Rota--Baxter group $(G, B)$ will be denoted by $G(B)$.

\begin{corollary}
Let  $B$ be a Rota--Baxter operator on a group $(G,\cdot)$.  If $\im (B)\subseteq \Z(G)$, then the skew left brace $(G, \cdot, \circ_B)$ is trivial.
\end{corollary}


\begin{example}{\rm 
Let $G$ be a group and $B_0(g)=1$ and $B_{-1}(g)=g^{-1}$ for all $g \in G$. Then $G(B_0)$ is a trivial skew left brace. Similarly, $G(B_{-1})$ is a trivial skew left brace, since $x \circ y = y \cdot x$ for all $x, y \in G$.}
\end{example}

For Rota--Baxter operators of weight $-1$, we have the following analogue of Proposition~\ref{RBToSLB}.

\begin{proposition}
Let $C$ be a~Rota--Baxter operator of weight $-1$ on a group $(G,\cdot)$. If we set $x \circ_C y = C(x)yC(x)^{-1}x$ for all $x,y \in G$, then $(G, \cdot, \circ_C)$ is a~skew left brace. If $(G, \cdot)$ is an abelian group, then
$(G, \cdot, \circ_C)$ is a trivial skew left brace.
\end{proposition}


\begin{proposition}
Let  $B$ be a Rota--Baxter operator on a group $(G,\cdot)$. Then the group $(G, \circ_B)$ is abelian if and only if 
\begin{equation} \label{RBlsbAbelianCirc}
[x^{-1}, B(y)] \,[B(x), y^{-1}] = [x^{-1}, y^{-1}]
\end{equation}
 for all $x, y \in G$.
\end{proposition}

\begin{proof}
By the definition of $\circ_B$, the identity
$x\circ_B y = y\circ_B x$ is equivalent to the identity
$$
x B(x) y B(x)^{-1} = y B(y) x B(y)^{-1}.
$$
If $[a, b]$ denotes $aba^{-1}b^{-1}$, then we rewrite the preceding identity as
$$
x y [y^{-1}, B(x)] = y x [x^{-1},B(y)]
$$
Since, $yx = xy[y^{-1}, x^{-1}]$,  we get
$$
[y^{-1}, B(x)] = [y^{-1}, x^{-1}] \,[x^{-1}, B(y)],
$$
which is equivalent to~\eqref{RBlsbAbelianCirc}. $\blacksquare$ 
\end{proof}

\begin{proposition}
Let $B$ be a Rota--Baxter operator on a group $(G,\cdot)$. Then $(G,\circ_B)\cong (G,\circ_{\widetilde{B}})\cong (G,\circ_{B^{(\varphi)}})$ for each $\varphi\in\Aut(G, \cdot)$.
\end{proposition}

\begin{proof} 
For $g, h \in G$, we have
$$
g\circ_{\widetilde{B}}h
 = g \big(g^{-1}B(g^{-1}) \big) h \big(g^{-1}B(g^{-1})\big)^{-1}
 = B(g^{-1})h B(g^{-1})^{-1}g
 = (g^{-1}\circ_B h^{-1})^{-1},
$$
and hence $x\to x^{-1}$ is an isomorphism of groups $(G,\circ_B)$ and $(G,\circ_{\widetilde{B}})$.
Similarly,
\begin{eqnarray*}
g\circ_{B^{(\varphi)}}h &=& g\varphi^{-1} \big(B(\varphi(g))\big) h \big(\varphi^{-1} \big(B(\varphi(g))) \big)^{-1}\\
 &=& \varphi^{-1} \big( \varphi(g)B(\varphi(g))\varphi(h)B(\varphi(g))^{-1} \big) \\
 &=& \varphi^{-1} \big(\varphi(g)\circ_B\varphi(h)\big),
\end{eqnarray*}
and hence $\varphi(g\circ_{B^{(\varphi)}}h) = \varphi(g)\circ_B \varphi(h)$,
and the corresponding groups are isomorphic. In fact, $\varphi$ is an isomorphism of skew left braces
$(G,\cdot,\circ_B)$ and $(G,\cdot,\circ_{B^{(\varphi)}})$. $\blacksquare$ 
\end{proof} 



The next result relates any skew left brace to a Rota--Baxter group \cite[Theorem 3.6]{MR4370524}.

\begin{theorem}  \label{Embedding}
Every skew left brace can be embedded into a Rota--Baxter group.
\end{theorem}

\begin{proof}
Let $(G,\cdot,\circ)$ be a skew left brace.
Consider the semi-direct product $\widetilde{G} = G\ltimes G$ with the group operation
\begin{equation}\label{CircProduct}
(x,y)*(z,t) = \big(x\circ z, ~y\lambda_x(t)\big).
\end{equation}
Consider the subgroups
$H = \{(g,g) \, \mid \, g\in G\}$ and $L = \{(g,1) \,\mid \, g\in G\}$ of $\widetilde{G}$.
Since $(x,y) = (y,y)*(y^{\circ(-1)}\circ x,1)$, we can write $\widetilde{G} = H*L$.  We define a splitting Rota--Baxter operator $B: \widetilde{G} \to \widetilde{G}$ by $B(h*l) = l^{*(-1)}$ for $h \in H$ and $l \in L$. Thus, $B \big((x,y)\big) = (x^{\circ(-1)}\circ y,1)$, and  $\widetilde{G}$ is a Rota--Baxter group.
\para

Define $\psi: G \to \widetilde{G}$ by $\psi(g)= (1,g)$. We claim that $\psi$ is an isomorphism of skew left braces $(G, \cdot, \circ)$ and $\im(\psi)$, where $\im(\psi)$ is considered
as a~subbrace of
$\widetilde{G}(B) = (\widetilde{G},*,\circ_B)$. Indeed, we have
$$
\psi(g)*\psi(h)
 = (1,g)*(1,h)
 = (1,g\cdot h)
 = \psi(g\cdot h)
$$
and
\begin{eqnarray*}
\psi(g) \circ_B \psi(h)
 &=& (1,g)*B \big((1,g)\big)*(1,h) * \big(B((1,g)) \big)^{-1} \\
 &=& (1,g)*(g,1)*(1,h)*(g^{\circ(-1)},1)\\
 &=& (g,g)*(g^{\circ(-1)},h)\\
 &=& \big(1,g\lambda_g(h)\big)\\
 &=& (1,g\circ h)\\
 &=& \psi(g\circ h)
\end{eqnarray*}
for all $g, h \in G$, which is desired. $\blacksquare$ 
\end{proof}

The following example illustrates Theorem \ref{Embedding}.

\begin{example}{\rm 
Let $G = (\mathbb{Z}, +, \circ)$ be the left brace, where $+$ is the usual addition of integers and
$$a \circ b = a + (-1)^a b$$ for  $a, b \in \mathbb{Z}$. Note that the inverse of an element $a$ under $\circ$ is given by $a^{\circ(-1)} = (-1)^{a+1} a$.
We now construct a Rota--Baxter group containing the left brace $G$. Define a group operation on the set
$\widetilde{G} = \mathbb{Z} \times \mathbb{Z}$ by setting
$$
(a, b) * (c, d) = \big(a+(-1)^a c,~ b +(-1)^a d \big)
$$
for $(a, b),(c, d) \in \widetilde{G}$. For each $a \in \mathbb{Z}$, the inverse of $(a, 0)$ in $\widetilde{G}$ is
$$
(a, 0)^{*(-1)} = \big((-1)^{a+1} a, 0 \big) = (a^{\circ(-1)}, 0).
$$
Consider the subgroups $H = \{(g,g) \,\mid \, g\in \mathbb{Z}\}$ and $L = \{(g,0) \,\mid \, g\in \mathbb{Z}\}$ of $\widetilde{G}$.
Since
$$
(x,y)
 = (y,y)*(y^{\circ(-1)}\circ x,0)
 = (y, y)* \big((-1)^{y+1}(y-x), 0\big),
$$
we can write $\widetilde{G} = H*L$. Define a Rota--Baxter operator $B: \widetilde{G} \to \widetilde{G}$ by
$$
B \big((g, h)\big)
 = \big((-1)^{h+1}(h-g),0\big)^{*(-1)}
 = \big((-1)^{g+1}(h-g),0\big)
$$
for $(g,h)\in G$. Hence, $G$ embeds into the Rota--Baxter group $(\widetilde{G}, *,B)$ via the map $g\mapsto(0,g)$.}
\end{example}

\begin{remark} \label{tilde{G}Nilpotent}
{\rm
The construction of the group $\widetilde{G}$ appeared first in~\cite[Section 4]{MR3957824} in the context of nilpotent skew left braces. More precisely, we can define a new binary operation~$*$ on a~skew left brace~$(G, \cdot, \circ)$ by
$$g* h = g^{-1} \cdot (g\circ h) \cdot h^{-1}.$$
Note that, in terms of the group~$\widetilde{G}$, we have
$$
[(1,h),(g,1)]
 = (1,g* h).
$$
This observation helped Ced\'{o}, Smoktunowicz, and Vendramin \cite{MR3957824} to clarify the construction of left and right series of~$G$, and hence led to the definition of left (right) nilpotency of~$G$. Note that, if the skew left brace arise from a Rota--Baxter group $(G,B)$, then $g* h = [B(g)^{-1},h^{-1}]$.}
\end{remark}

In \cite[Problem 19.90(d)]{Kourovka}, the question was posed whether a finite skew left brace can exist with a non-solvable additive group and a nilpotent multiplicative group. This question was negatively answered by Tsang and Qin in \cite{MR4077413}. An alternative proof of this result can be obtained using Theorem \ref{Embedding}.

\begin{corollary}\label{coro:Kegel}
Let $(G,\cdot,\circ)$ be a finite skew left brace. If $(G, \circ)$ is nilpotent, then $(G, \cdot)$ is solvable.
\end{corollary}

\begin{proof}
Given a finite skew left brace~$(G,\cdot,\circ)$, we construct $(\widetilde{G}, *)$ as in the proof of Theorem~\ref{Embedding}.
We also have the decomposition $\widetilde{G} = H*L$, where
$H = \{(g,g) \,\mid\,  g\in G\}$ and $L = \{(g,1)\,\mid\, g\in G\}$.
Note that $H\cong L\cong (G,\circ)$. Since $(G, \circ)$ is nilpotent, it follows from Kegel's theorem \cite{MR0133365} that $(\widetilde{G}, *)$ is solvable. Thus, its subgroup $\{(1,g) \,\mid \, g\in G\}\cong (G, \cdot)$ is also solvable.
$\blacksquare$ 
\end{proof}

Another interesting application of Theorem~\ref{Embedding} is the following result \cite{MR4003478,MR4077413}.

\begin{corollary}
Let $(G,\cdot,\circ)$ be a skew left brace. If $(G, \circ)$ is abelian, then $(G, \cdot)$ is metabelian.
\end{corollary}

\begin{proof}
We have the factorization $\widetilde{G} = H*L$. By Ito's theorem~\cite{MR0071426}, $(\widetilde{G}, *)$ is metabelian.
Thus, its subgroup $\{(1,g)\, \mid \, g\in G\}\cong (G, \cdot)$ is also metabelian.
$\blacksquare$ 
\end{proof}

A group $G$ is called \index{complete group}{\it complete} if both its center $\Z(G)$ and its outer automorphism group $\Out(G)$ are trivial.


\begin{proposition}\label{complete SLB is RBO}
Let $(G,\cdot,\circ)$ be a skew left brace such that $(G, \cdot)$ is complete. Then there exists a Rota--Baxter operator~$B$ on $(G, \cdot)$ inducing $(G,\cdot,\circ)$.
\end{proposition}

\begin{proof}
Since $\Out(G,\cdot)$ is trivial, for each $g \in G$, there exists $\tilde{g}\in G$ such that
$\lambda_g(x) = \tilde{g} x {\tilde{g}}^{-1}$ for all $x \in G$. Since $\Z(G)$ is trivial, such an element $\tilde{g}$ is unique. Define $B:G \to G$ by $$B(g)=\tilde{g}$$ for all $g \in G$. We claim that $B$ is the desired Rota--Baxter operator on $(G, \cdot)$. For $g, h\in G$, we see that 
$$\widetilde{(g \circ h)} \, x \,{\widetilde{(g \circ h)}}^{-1}= \lambda _{g \circ h} (x)=\lambda _g \lambda_h (x)= \lambda_g(\tilde{h} x \tilde{h}^{-1})=\tilde{g} (\tilde{h} x \tilde{h}^{-1} )\tilde{g}^{-1}= (\tilde{g} \tilde{h}) x (\tilde{g}\tilde{h})^{-1}$$
for all $x \in G$. Since $\Z(G)$ is trivial, it follows that $\widetilde{g \circ h} = \tilde{g} \tilde{h}$. This means that  $B(g \circ h)= B(g) B(h)$ for all $g, h \in G$. Further, $g \circ h= g  \lambda_g(h)=g (\tilde{g} h\tilde{g} ^{-1})= g B(g) h B(g)^{-1}= g \circ_B h$ for all $g, h \in G$. This completes the proof. $\blacksquare$ 
\end{proof}


\begin{remark}\label{remark lambda RBO}
{\rm 
If $B$ is a Rota--Baxter operator on a group $(G,\cdot)$. Then the map $\lambda: (G, \circ_B) \to \Aut(G, \cdot)$ is given by $\lambda_g(h) = B(g)hB(g)^{-1}$ for all $g, h \in G$. Thus, for a skew left brace arising from a Rota--Baxter group, the map $\lambda$ takes values in the  inner automorphism group.}
\end{remark}


In~\cite[Problem~12]{MR3974481}, Vendramin  posed the problem of describing a free skew left brace. The following result provides some insight into the structure of a skew left brace arising from a free Rota--Baxter group \cite[Proposition 3.14]{MR4370524}.

\begin{proposition} 
Let $(G,B)$ be a free Rota--Baxter group generated by a~set~$X$. Let $S$ denote the skew left subbrace of $G(B)$ generated by~$X$.
Then $S$~is a~free skew left brace generated by~$X$.
\end{proposition}

\begin{proof}
Let $(A,\cdot,\circ)$ be a~skew left brace generated by~$X$.
By Theorem~\ref{Embedding}, $A$~embeds into the Rota--Baxter group~$\tilde{A}$,
which itself is generated by the set~$X$ as a Rota--Baxter group.
Thus, there exists a surjective homomorphism $\psi: G \to \tilde{A}$ of Rota--Baxter groups.
Hence, $\psi$~is a~surjective homomorphism from $S$ onto $A$
considered as a~subbrace of~$\tilde{A}$.
Since $A$ is an arbitrary skew left brace generated by~$X$, $S$ is also generated by~$X$ and $A$ is a homomorphic image of~$S$,
we conclude that $S$~is the free skew left brace generated by~$X$.
$\blacksquare$ 
\end{proof}

In the preceding chapter, we gave some constructions of Rota--Baxter groups. We now analyse skew left braces induced by these Rota--Baxter groups. 

\begin{example}
{\rm 
Let $G = HL$ be an exact factorization. Let $B$ be the splitting Rota--Baxter operator on $G$, that is, $B(hl) = l^{-1}$ for all $h \in H$ and $l \in L$. Then the multiplicative group structure of the skew left brace $G(B)$ is given by
$$
x \circ_B y
 = (hl)\circ_B y
 = hlB(hl)yB(hl)^{-1}
 = hyl.
$$ 
Such skew left braces appeared in several works, for instance, \cite[Example~1.6]{MR3647970},
~\cite[Theorem~2.3]{MR3763907} and~\cite[p. 19]{MR4346001}.}
\end{example}


\begin{example}
{\rm 
Recall the Rota--Baxter operator given by Proposition \ref{triangular}. Let $G$ be a group such that $G = HLM$, where $H$, $L$ and $M$ are subgroups of $G$ with pairwise trivial intersections. Let $C$ be a Rota--Baxter operator on~$L$ and  $[H,L] = [C(L),M] = 1$. Then the map $B: G\to G$ defined by 
$$
B(hlm) = C(l)m^{-1}
$$
is a Rota--Baxter operator on~$G$. For $x=hlm$ and $y=h'l'm'$, we have
\begin{eqnarray*}
x\circ_B y  &=& (hlm)\circ_B (h'l'm')\\
 &=& (hlm)B(hlm)h'l'm'B(hlm)^{-1}\\
 &=& hlmC(l)m^{-1}h'l'm'mC(l)^{-1} \\
 &=& hl mm^{-1}C(l)h'l'm'mC(l)^{-1}\\
 &=& hh'lC(l)l'm'mC(l)^{-1}\\
 &=& hh'(l\circ_C l') m'm.
\end{eqnarray*}
Hence, we have $(G,\circ_B)\cong H\times (L, \circ_C)\times M^{\rm op}$, where $M^{\rm op}$ is the opposite group of $M$.}
\end{example}


\begin{example}
{\rm 
Consider the Rota--Baxter operator given by Proposition \ref{semi-direct}. Let $G = H\rtimes L$ be a semi-direct product and $C$ a~Rota--Baxter operator on $L$. Then the map $B: G\to G$ defined by  $B(hl) = C(l)$, where $h\in H$ and $l\in L$, is a~Rota--Baxter operator on $G$.
For $x=hl$ and $y=h'l'$, we have
\begin{eqnarray*}
x\circ_B y &=& (hl)\circ_B (h'l')\\
 &=& hlB(hl)h'l'B(hl)^{-1}\\
 &=& hlC(l)h'l'C(l)^{-1}\\
 &=& hh'^{C(l)^{-1}l^{-1}}lC(l)l'C(l)^{-1} \\
 &=& hh'^{C(l)^{-1}l^{-1}}(l\circ_C l'),
\end{eqnarray*}
and hence $(G, \circ_B)\cong H\rtimes (L, \circ_C)$.}
\end{example}


\begin{example}\label{iso slb induced by differnt rbo}
{\rm 
Let $\Sigma_3$ be the symmetric group generated by two transpositions $s_1$ and $s_2$.
\begin{enumerate}
\item Consider the  factorisation $\Sigma_3 = \langle s_2 \rangle A_3$ and the splitting Rota--Baxter operator $B_1 : \Sigma_3 \to \Sigma_3$ given by $B_1(c a) = a^{-1}$ for $c\in \langle s_2 \rangle$ and $a \in A_3$. More precisely, we have
$$
B_1(s_1) = s_1 s_2,\quad
B_1(s_2) = 1,\quad
B_1(s_1 s_2) = s_2 s_1, \quad
B_1(s_2 s_1) = s_1s_2 \quad \textrm{and} \quad
B_1(s_1 s_2 s_1) = s_2 s_1.
$$
If $(\Sigma_3, \cdot, \circ)$ is the skew left brace  induced by $B_1$, then $(\Sigma_3, \circ)$ is the cyclic group of order six generated by $s_1$ such that
$$
s_1^{\circ 2} = s_1 \circ s_1 = s_1 s_2,\quad
s_1^{\circ 3} = s_2, \quad
s_1^{\circ 4} = s_2 s_1, \quad
s_1^{\circ 5} = s_1 s_2 s_1  \quad \textrm{and} \quad
s_1^{\circ 6} = 1.
$$
\item Consider the Rota--Baxter operator $B_2 : \Sigma_3 \to \Sigma_3$ given by
$$
B_2(s_1) = s_1, \quad
B_2(s_2) = s_1, \quad
B_2(s_1 s_2 s_1) = s_1, \quad
B_2(s_2 s_1) = 1 \quad \textrm{and} \quad
B_2(s_1 s_2) = 1.
$$
If $(\Sigma_3, \cdot, \circ)$ is the skew left brace  induced by $B_2$, then we see that the group $(\Sigma_3, \circ)$ is the cyclic group of order six generated by $s_2$ such that
$$
s_2^{\circ 2} = s_1 s_2, \quad
s_3^{\circ 3} = s_1, \quad
s_2^{\circ 4} = s_2 s_1, \quad
s_5^{\circ 5} = s_1 s_2 s_1 \quad \textrm{and} \quad
s_2^{\circ 6} = 1.
$$
\item[]  It is not difficult to see that the Rota--Baxter groups considered above are non-isomorphic, yet they induce isomorphic skew left braces.
\end{enumerate}}
\end{example}


Recall the Definition \ref{definition of hom of RBG} of a homomorphism of Rota--Baxter groups.


\begin{proposition}
Let $\varphi: (G_1, B_1) \to (G_2, B_2)$ be a homomorphism of Rota--Baxter groups with underlying groups $(G_1, \cdot_1)$ and $(G_2, \cdot_2)$. Then $\varphi: (G_1, \cdot_1, \circ_{B_1}) \to (G_2, \cdot_2, \circ_{B_2})$ is a homomorphism of induced skew left braces. In particular, an isomorphism of Rota--Baxter groups gives rise to an isomorphism of induced skew left braces.
\end{proposition}

\begin{proof}
It only needs to be shown that $\varphi$ preserves the group structure induced by  the Rota--Baxter operators. Indeed, for $g, h \in G_1$, we have
\begin{eqnarray*}
\varphi (g \circ_{B_1} h) &=& \varphi \big(g \cdot_1{B_1}(g) \cdot_1h \cdot_1 {B_1}(g)^{-1} \big)\\
&=& \varphi (g) \cdot_2 \varphi \big(B_1(g)\big)\cdot_2 \varphi(h)\cdot_2 \varphi \big(B_1(g)^{-1}\big)\\
&=& \varphi (g) \cdot_2 {B_2} \big(\varphi(g)\big) \cdot_2 \varphi(h) \cdot_2 {B_2} \big(\varphi(g)\big)^{-1}\\
&=& \varphi (g) \circ_{B_2} \varphi (h),
\end{eqnarray*}
which is desired. The second assertion is immediate.
$\blacksquare$ 
\end{proof}


\begin{remark}
{\rm 
Mapping a Rota--Baxter group to its induced skew left brace gives a functor from the category $\mathcal{RBG}$ of Rota--Baxter groups to the category $\mathcal{SLB}$ of skew left braces.}
\end{remark}

We now examine the solution to the Yang--Baxter equation derived from a Rota--Baxter group \cite[Theorem 6.1]{MR4370524}.

\begin{theorem} 
Let $(G, B)$ be a Rota--Baxter group and $\lambda_a(b) = B(a) b B(a)^{-1}$ for $a, b \in G$. Then $r : G \times G \to G\times G$ given by
\begin{equation} \label{RBE}
r(a, b) = \big(\lambda_a(b), ~a^{\lambda_a(b)B(\lambda_a(b))}\big),
\end{equation}
gives a~non-degenerate bijective solution $(G, r)$ to the Yang--Baxter equation. Moreover, $S$ is involutive if and only if $G$ is abelian.
\end{theorem}

\begin{proof}
By Proposition \ref{RBToSLB}, taking $a \circ_B b = a B(a) b B(a)^{-1}$, we obtain the skew left brace $(G, \cdot, \circ_B)$, where $\cdot$ is the group operation in $G$. In this case, the map $\lambda: (G, \circ_B) \to \Aut(G, \cdot)$ is given by $\lambda_a(b) = B(a) b B(a)^{-1}$ for $a, b \in G$. We see that
$$
(a \circ_B b)^{-1} a (a \circ_B b)
 = B(a) b^{-1} B(a)^{-1} a B(a) b B(a)^{-1}
 = a^{B(a) b B(a)^{-1}}
$$
and
$$ \lambda^{-1}_{\lambda_a(b)} \big((a \circ_B b)^{-1} a (a \circ_B b) \big) = B \big(\lambda_a(b)\big)^{-1}a^{B(a) b B(a)^{-1}} B \big(\lambda_a(b)\big)= a^{B(a) b B(a)^{-1} B(\lambda_a(b))}= a^{\lambda_a(b) B(\lambda_a(b))}.$$
By Theorem \ref{solution from a skew brace}, for a skew left brace $(G,\cdot, \circ_B)$, the map
\begin{equation}
r(a, b) = \big(\lambda_a(b), ~\lambda^{-1}_{\lambda_a(b)}((a \circ_B b)^{-1}  a  (a \circ_B b))\big)
\end{equation}
gives a~non-degenerate bijective solution $(G, r)$ to the Yang--Baxter equation. Moreover, $r$~is involutory if and only if $a b = b  a$ for all $a, b \in G$. This completes the proof. $\blacksquare$   
\end{proof}

We conclude with the following examples.

\begin{example}
{\rm 
If a group $G$ has an exact factorization $G = HL$, then the binary operation
$$(a_1 b_1) \circ (a_2 b_2) = a_1 a_2 b_2 b_1 $$
for $a_i \in H$ and $b_i \in L$, gives a skew left brace $(G, \cdot, \circ)$. Further, the map 
$B : G \to G$ given by $B(ab)= b^{-1}$ is a Rota--Baxter operator on $G$. Hence, we have a non-degenerate bijective solution to the Yang--Baxter equation with braiding
$$
r(a_1b_1,~a_2b_2)=
\big(b_1^{-1}a_2b_2b_1,~ b_2(a_2b_2b_1)^{-1}(b_1a_1)(a_2b_2b_1)b_2^{-1}\big) = \big( (a_2 b_2)^{b_1},~ (b_1 a_1)^{a_2 b_2 b_1 b_2^{-1}} \big).
$$}
\end{example}


\begin{example}
{\rm 
Recall from Proposition \ref{exact factorisation of free group} that the free group $F_n = \langle x_1, \ldots, x_n \rangle$ of rank $n \ge 2$ has an exact factorization $F_n = AB$, where
$$
A =  \big\langle x_1, x_2, \ldots, x_{n-1}, [x_n, F_n] \rangle \quad \textrm{and}\quad B =  \langle x_n \big\rangle.
$$
For a reduced word $w$ representing an element of $F_n$ and $1 \le i \le n$, let $\mathfrak{L}_i(w)$ be the sum of the powers  of $x_i$ in $w$. Each element $u \in F_n$ can be written in the form $u=(u x_n^{-\mathfrak{L}_n(u)}) x_n^{\mathfrak{L}_n(u)}$, where $u x_n^{-\mathfrak{L}_n(u)} \in A$ and $x_n^{\mathfrak{L}_n(u)} \in B$. Let $r: F_n \times F_n \to F_n \times F_n$ be the map given by
$$
r(u, v) = \big(v^{\pi(u)}, ~u^{\pi(u)^{-1} v \pi(u) \pi(v)^{-1}} \big),
$$
for $u, v \in F_n$, where $\pi(u) = x_n^{\mathfrak{L}_n(u)}$ and $\pi(v) = x_n^{\mathfrak{L}_n(v)}$. Then $(F_n, r)$ is a non-degenerate bijective solution to the Yang--Baxter equation.}
\end{example}
