\section{Structure of skew braces  arising from Rota--Baxter groups}\label{TermsViaRB}

Recall from Proposition \ref{bijective 1-cocycle and skew brace} that, there is a one-to-one correspondence between  skew  left braces and bijective  1-cocycles.
\para

 If $(G, \cdot)$ is a~group and $\pi : \Gamma \to G$ is a bijective group 1-cocycle, then the binary operation given by
\begin{equation} \label{1-cocycle}
a \circ b = \pi \big(\pi^{-1}(a) \,\pi^{-1}(b) \big)
\end{equation}
for $a,b \in G$, gives a skew left brace $(G, \cdot, \circ)$. Conversely, suppose that $(G, \cdot, \circ)$ is a~skew left brace. Taking $\Gamma = G$ with group operation $(a,b)\mapsto a\circ b$ and the action $a \mapsto \lambda_a$ of $\Gamma$ on $G$,  we see that the identity map $\id:\Gamma \to G$ is a bijective 1-cocycle. In particular, when $G$ acts on itself by conjugation, the inverse of a bijective 1-cocycle given by \eqref{1-cocycle} is simply a Rota--Baxter operator on~$G$~\cite{MR4271483}.

\begin{proposition} \cite[Proposition 5.1]{MR4370524}
Let $B$ be a Rota--Baxter operator on a group $(G,\cdot)$ and  $(G,\cdot, \circ_B)$ the induced skew left brace. Then $(G,\cdot,\circ_B)$ is a two-sided skew  left brace
if and only if the map $\psi_g: G^{\rm op} \to G^{\rm op}$
given by $\psi_g(x)= [B(x)^{-1},g]$ is a~1-cocycle for each $g\in G$.
\end{proposition}

\begin{proof}
By~Proposition~\ref{RBToSLB}, $G$ is a skew left brace. Rewriting the axiom 
$$
(b \cdot c) \circ a  =  (b \circ a) \cdot a^{-1} \cdot (c\circ a)
$$
of a  skew  right  brace in terms of $B$, we get
$$
abB(ab)cB(ab)^{-1}
 = aB(a)cB(a)^{-1}c^{-1}bB(b)cB(b)^{-1},
$$
which is further equivalent to
$$
b[B(ab)^{-1},c^{-1}]
 = [B(a)^{-1},c^{-1}]b[B(b)^{-1},c^{-1}].
$$
Thus, $\psi_{c^{-1}}(ab) = \psi_{c^{-1}}(a)^b \psi_{c^{-1}}(b)$, and hence $\psi_g(b*a) = \psi_g(b)* \big(b\cdot \psi_g(a)\big)$ for all $a,b,g\in G^{\rm op}$.
Here, $b*a = ab$ is the opposite group operation in~$G$. $\blacksquare$ 
\end{proof}

The following result gives a criteria for a Rota--Baxter group induced skew left brace to be $\lambda$-homomorphic \cite[Proposition 5.14]{MR4370524}.

\begin{proposition}
Let $B$ be a Rota--Baxter operator on a group $(G,\cdot)$ and  $(G,\cdot, \circ_B)$ the induced skew left brace. Then $(G,\cdot,\circ_B)$ is a $\lambda$-homomorphic skew left brace if and only if $B(a \cdot b)^{-1} \cdot B(a) \cdot B(b)\in \Z(G,\cdot)$ for all $a,b\in G$.
\end{proposition}

\begin{proof}
Note that $\lambda_{a \cdot c}(b) = B(a \cdot c) \cdot b \cdot B(a \cdot c)^{-1}$ for all $a, b, c \in G$. On the other hand, we have
$$
\lambda_{a} \lambda_{c}(b) = \lambda_{a} \big( B(c) \cdot b \cdot B(c)^{-1} \big) = B(a) \cdot B(c) \cdot b \cdot B(c)^{-1} \cdot B(a)^{-1}
$$
for all $a, b, c \in G$. Hence, $\lambda: (G, \cdot) \to \Aut (G, \cdot)$ is a  homomorphism if and only if $b\cdot B(a\cdot c)^{-1}\cdot B(a)\cdot B(c) = B(a \cdot c)^{-1}\cdot B(a)\cdot B(c) \cdot b$ for all $a,b,c \in G$. $\blacksquare$ 
\end{proof}


Recall that, an ideal of a skew left brace $(G, \cdot, \circ)$ is a subset $I$ of $G$ such that $(I, \cdot)$ is a normal subgroup of $(G,\cdot)$, $(I, \circ)$ is a normal subgroup of $(G, \circ)$ and $\lambda_a(I) \subseteq I$ for any $a \in G$.  The condition $\lambda_a(I) \subseteq I$ is equivalent to the equality $a\circ I = a \cdot I$ of cosets for all $a\in G$. Thus, the notion of an ideal allows us to consider the quotient skew left brace $G/I$. 

\begin{definition}
A \index{left ideal}{\it left ideal} of a skew left brace $(G, \cdot, \circ)$  is a subgroup $(L, \cdot)$ of $(G, \cdot)$ such that $\lambda_a(L) \subseteq L$ for each $a \in G$.   A \index{strong left ideal}{\it strong left ideal} of $(G, \cdot, \circ)$ is a normal subgroup  $(L, \cdot)$ of $(G, \cdot)$ such that $\lambda_a(L) \subseteq L$ for each $a \in G$. 
\end{definition}

Clearly, every ideal of a skew left brace is a left as well as a strong left ideal. If $L$ is a left ideal of a skew left brace $(G, \cdot, \circ)$, then we have
$$
a \circ b = a \cdot \lambda_a(b) \in L \quad \textrm{and} \quad \bar{a} = \big(\lambda_{\bar{a}}(a) \big)^{-1} \in L
$$
for all $a, b \in L$. It follows that a left ideal of a skew left brace is always a subbrace. Strong left ideals provide decompositions of the corresponding solutions to the Yang--Baxter equation~\cite{MR4023387}, and are also connected with intermediate fields of Galois extensions~\cite{MR4033084}.
\para 

Inspired by Theorem~\ref{Embedding}, Remark~\ref{tilde{G}Nilpotent}, and the analogy with post-algebras, we apply the map $\psi:G \to \widetilde{G}= G \ltimes G$, given by  $\psi(g) = (1, g)$, to define some classes of skew left braces \cite{MR3957824}.

\begin{definition}\label{DefViaDelta}
Let~$(G, \cdot, \circ)$ be a~skew left brace and $\mathcal{X}$ a class of groups.
\begin{enumerate}
\item  A~non-empty subset $I$ of $G$ is said to be of type~$\mathcal{X}$
if $I$ is of type $\mathcal{X}$ in the group~$(G,\cdot)$.
\item  A~non-empty subset $I$ of $G$ is said to be of strong type $\mathcal{X}$
if $\psi(I)$ is of type $\mathcal{X}$ in the group~$\widetilde{G}$.
\end{enumerate}
\end{definition}

In \cite{MR4427114}, many notions of skew left braces $(G, \cdot, \circ)$ have been interpreted in terms of the group~$\widetilde{G}$. 

\begin{proposition} \label{IdealCriterion}
Let $(G, \cdot, \circ)$ be a skew left brace. A~non-empty subset~$I$ is a~strong left ideal of~ $(G, \cdot, \circ)$ if and only if
$\psi(I)$ is a normal subgroup of~$\widetilde{G}$.
\end{proposition}

\begin{proof}
Recall that $\psi:G \to \widetilde{G}$ is given by $\psi(g)=(1, g)$. Let $a\in G$ and $i\in I$. The condition that $\psi(I)$ is a normal subgroup of~$\widetilde{G}$ is equivalent to the inclusions
$$
(1,a)^{*(-1)}*(1,i)*(1,a)\in \{1\} \times I\quad \textrm{and}\quad (a,1)^{*(-1)}*(1,i)*(a,1)\in \{1\} \times I.
$$
By~\eqref{CircProduct}, we obtain  $a^{-1}ia\in I$ and $\lambda_{a^{\circ(-1)}}(i)\in I$. Since $a$ and $i$ are arbitrary, this implies that $\psi(I)$ is a normal subgroup of~$\widetilde{G}$
if and only if~$I$ is a~normal subgroup of $(G,\cdot)$ and $\lambda_x(I)\subseteq I$ for all $x\in G$. $\blacksquare$ 
\end{proof}

\begin{proposition}
Let $B$ be a Rota--Baxter operator on a group $(G,\cdot)$ and $I\subseteq G$. Then the following  assertions hold:
\begin{enumerate}
\item $I$~is an ideal of~$(G, \cdot, \circ_B)$ if and only if $I$~is a~normal subgroup of both
$(G, \circ_B)$ and $(G, \cdot)$.
\item $I$~is a left ideal of $(G, \cdot, \circ_B)$ if and only if $I$ is a subgroup of $(G, \cdot)$ normalized by $\im(B)$.
\end{enumerate}
\end{proposition}

\begin{proof}
If $I$ is an ideal of~$(G, \cdot, \circ_B)$, then $I$~is a~normal subgroup of both $(G, \cdot)$ and $(G, \circ_B)$ and $\lambda_a(I) \subseteq I$ for all $a \in G$. The last condition means that $B(a)iB(a)^{-1}\in I$ for all $a\in G$ and $i \in I$, which follows from the normality of~$I$ in $(G, \cdot)$, thereby establishing assertion (1). The proof of  assertion (2) is similar. $\blacksquare$ 
\end{proof}

Next, we introduce the notion of the left center of a~skew left brace.

\begin{definition}
Let $(G, \cdot, \circ)$ be a~skew left brace. The \index{left center of skew brace}{\it left center} of~$G$ is defined as 
$$
 \Z_l(G)
 = \{c\in G \, \mid \, c\in \Z(G,\cdot) ~\textrm{and}~
 g \cdot c = g\circ c\mbox{ for all }g\in G\}.
$$
\end{definition}


\begin{proposition}\label{strong let center prop}
The following assertions hold:
\begin{enumerate}
\item  If $(G, \cdot, \circ)$ is a skew left brace, then $\psi \big( \Z_l(G)\big) = \Z(\widetilde{G})\cap \psi(G)$.
\item If $G(B) = (G,\cdot,\circ)$ is a~skew left brace induced by a Rota--Baxter operator~$B$ on $(G, \cdot)$, then
$ \Z_l \big(G(B)\big) = \Z(G,\cdot)$.
\end{enumerate}
\end{proposition}

\begin{proof}
An element~$(1,s)$ lies in $\Z(\widetilde{G})$ if and only if $(a,b)*(1,s) = (1,s)*(a,b)$ for all $a,b\in G$. This means that $b \cdot \lambda_a(s) = s\cdot \lambda_1(b) = s\cdot b$ or equivalently $\lambda_a(s) = b^{-1}\cdot s\cdot b$. Taking~$a = 1$, we get $s\in \Z(G,\cdot)$. Thus, $s = \lambda_a(s) = a^{-1}\cdot (a\circ s)$ for all $a\in G$. This gives $a\cdot s = a\circ s$, which proves assertion (1).
\para 
If $c\in \Z_l \big(G(B)\big)$, then $c\in \Z(G, \cdot)$. Conversely, if $c\in \Z(G, \cdot)$, then $g\circ c = g \cdot B(g)\cdot c \cdot B(g)^{-1} = g \cdot c$ for all $g\in G$, which proves assertion (2). $\blacksquare$ 
\end{proof}

It follows from  Proposition~\ref{IdealCriterion} and Proposition \ref{strong let center prop} that $ \Z_l(G)$ is a strong left ideal of $(G, \cdot, \circ)$. In general, the left center is not an ideal of a skew left brace.

\begin{example}{\rm 
Let $A = \mathbb{Z}_3 = \langle a\rangle$ and 
$B = \mathbb{Z}_2 = \langle b\rangle$ be trivial braces.  Consider the homomorphism $\beta : B \to \Aut(A)$ defined such that $\beta(b):A \to A$ acts as $x\to x^2$. Then we have the semi-direct product $G = A\rtimes B$ with $(G,\cdot)\cong \mathbb{Z}_3\times\mathbb{Z}_2$ and $(G,\circ)\cong \Sigma_3$.  It is not difficult to see that $ \Z_l(G) = \{1\}\rtimes B$, which is not a normal subgroup of $(G,\circ)$.}
\end{example}

Recall that the socle of a skew left brace $(G, \cdot, \circ)$ is defined as
$$
\Soc(G)
 = \big\{a\in G \, \mid \, a\in \Z(G,\cdot)~\textrm{and}~ a\circ b = a \cdot b ~\mbox{ for all }b\in G\big\}.
$$

In analogy with the concept of the left center, we refer to $\Soc(G)$ as the right center of $(G, \cdot, \circ)$. The following result provides a description of the socles of skew left braces induced by Rota--Baxter operators.

\begin{proposition}
Let $B$ be a Rota--Baxter operator on a group $(G,\cdot)$ and $G(B)$ its induced skew left brace. Then
$$
\Soc(G(B)) = \big\{ a \in G \, \mid \, a,B(a) \in \Z(G, \cdot)\big\}
 = \Z(G, \cdot)\cap B^{-1}\big(\Z(G, \cdot)\big).
$$
\end{proposition}

\begin{proof}
The equality $a\circ b = a \cdot b$ is equivalent to $B(a)\cdot b\cdot B(a)^{-1} = b$, that is, $B(a)\in \Z(G, \cdot)$. $\blacksquare$ 
\end{proof}

In~\cite{MR3917122}, the \index{annihilator}{\it annihilator} of a~skew left brace~$(G, \cdot, \circ)$ is defined as $$\Ann(G) = \Z(G,\circ)\cap\Soc(G).$$ 
Thus, we can redefine the annihilator as $\Ann(G) = \Z_l(G)\cap\Soc(G)$. In~\cite{Bonatto}, $\Ann(G)$ is referred to as the {\it center} and has been applied to develop central nilpotency of skew left braces.
\para 

We define the \index{upper central series}{\it upper central series} of a skew left brace $(G, \cdot, \circ)$ by setting $\zeta_1(G) = \Z_l(G)$ and $\zeta_{n+1}(G)$ to be the strong left ideal of~$G$ such that
$$
\zeta_{n+1}(G)/\zeta_n(G) = \psi(G)/\zeta_n(G)\cap \Z \big(\widetilde{G}/\zeta_n(G)\big).
$$
Here, we identify $\zeta_i(G)$ with its image in $\widetilde{G}$ under the  map $\psi:G \to \widetilde{G}$.

\begin{definition}
A~skew left brace  $(G, \cdot, \circ)$ is called {\it strong left-nilpotent} if there exists an integer $m \ge 1$ such that $\zeta_m(G) = G$.
\end{definition}

Extending the idea of nilpotency of left braces by Rump \cite{MR2278047},  left- and right-nilpotency of skew left braces was defined in \cite{MR3957824}. The left series of a skew left brace $(G, \cdot, \circ)$ is the sequence of subsets $$G^1 \supseteq G^2 \supseteq G^3 \supseteq  \cdots \supseteq G^n \supseteq \cdots,$$ 
where  $G^1=G$, $G^{n+1} = G * G^n$ for each $n \ge 1$ and $$g* h = g^{-1} \cdot (g\circ h) \cdot h^{-1}.$$
A skew left brace $(G, \cdot, \circ)$ is said to be {\it left-nilpotent} if there exists $n \ge 1$ such that $G^n$ is trivial. 

\begin{proposition}
Let $(G, \cdot, \circ)$ be a strong left-nilpotent skew left brace. Then $(G, \cdot, \circ)$ is left-nilpotent and $(G,\cdot)$ is nilpotent.
\end{proposition}

\begin{proof}
Since $ \Z_l \big(\widetilde{G}/\zeta_n(G) \big) \subseteq \Z \big(\psi(G)/\zeta_n(G) \big)$,  we see that $\zeta_1(G),\zeta_2(G),\ldots$ is a central series of the group~$(G,\cdot)$, and hence  $(G,\cdot)$ is nilpotent. Suppose that $\zeta_m(G) = G$ for some $m \ge 1$. Then by definition of $\zeta_i(G)$, we have $G* \zeta_i(G)\subseteq \zeta_{i+1}(G)$. Hence, $G^{m+1}$ is trivial and $(G, \cdot, \circ)$ is left-nilpotent. $\blacksquare$ 
\end{proof}

We conclude the section with the following result \cite[Theorem 5.11]{MR4370524}.

\begin{theorem}
Let $(G, \cdot, \circ)$ be a strong left-nilpotent skew left brace and $I$ a non-trivial strong left ideal of $(G, \cdot, \circ)$. Then $ \Z_l(G)\cap I$ is non-trivial.
\end{theorem}

\begin{proof}
Suppose that $ \Z_l(G)\cap I$ is trivial. Let  $k\geq1$ be such that $\zeta_k(G)\cap I$ is trivial, but $\zeta_{k+1}(G)\cap I$ is non-trivial. Consider a non-trivial element $ i\in \zeta_{k+1}(G)\cap I$. By  definition of $\zeta_{k+1}(G)$, we have $i\in \Z \big(\widetilde{G}/\zeta_k(G)\big)$. Thus, $[i,g]\in \zeta_k(G)$ for all $g\in \widetilde{G}$. Since $I$ is a normal subgroup of~$\widetilde{G}$, we also have $[i,g]\in I$. By our assumption,  $\zeta_k(G)\cap I$ is trivial, and hence $[i,g] = 1$ for all $g\in\widetilde{G}$. Finally, we conclude that $i\in \Z(\widetilde{G})$, and hence $i\in \zeta_1(G)\cap I$, which is a~contradiction. $\blacksquare$ 
\end{proof}
