\section{Symmetric skew braces} \label{sym}

In this section, we discuss symmetric skew left braces.

\begin{definition}
A skew  left brace $(G, \cdot, \circ)$ is said to be \index{symmetric skew  left brace}{symmetric} if  $(G, \circ, \cdot)$ is also a skew  left brace.
\end{definition}

These braces were introduced by Childs \cite{MR3982254} under the name bi-skew braces and studied subsequently by Caranti \cite{MR4130907}. The next result gives a characterisation of a symmetric skew  left brace \cite[Proposition 5.2]{MR4346001}.

\begin{proposition}  \label{symprop1}
A skew  left brace  $(G, \cdot, \circ)$ is symmetric if and only if
\begin{eqnarray} \label{inc1}
\overline{b}\circ (a\cdot b)\circ \overline{a} \in \ker(\lambda)
\end{eqnarray}
for all $a,b \in G$, where $\bar a$ denotes the inverse of $a$ in $(G,\circ)$.
\end{proposition}

\begin{proof}
Let $(G, \cdot, \circ)$ be a skew  left brace. Recall that $\lambda : (G, \circ) \to \Aut (G, \cdot)$ is a group homomorphism, where
\begin{equation}\label{eqn1sec5}
\lambda_a(b)=a^{-1} \cdot (a\circ b)
\end{equation}
 for all $a, b \in G$. Now, $( G, \circ, \cdot)$ is a symmetric skew  left brace if and only if
\begin{equation}\label{eqn2sec5}
a\cdot(b\circ c)=(a\cdot b)\circ \overline{a}\circ (a\cdot c)
\end{equation}
for all $a, b, c \in G$. Using \eqref{eqn1sec5}, we see that \eqref{eqn2sec5} is equivalent to
$$  
a \cdot b \cdot \lambda_b(c)=a \cdot b \cdot  \lambda_{a \cdot b} \big(\overline{a} \cdot \lambda_{\overline{a}} (a \cdot c) \big),$$
which is further equivalent to
$$
\lambda_b(c)=\lambda_{a \cdot b} \big(\overline{a} \cdot \lambda_{\overline{a}} (a) \cdot \lambda_{\overline{a}} (c)\big).
$$
Since $\lambda_{\overline{a}} (a)={\overline{a}}^{-1}\cdot (\overline{a}  \circ a)={\overline{a}}^{-1}$, we obtain
$$
\lambda_b(c)=\lambda_{a \cdot b} \big(\lambda_{\overline{a}} (c) \big) \Longleftrightarrow
\lambda_b(c)=\lambda_{(a \cdot b)\circ \overline{a}} (c) \Longleftrightarrow
\lambda_{\overline{b} \circ (a \cdot b)\circ \overline{a}} (c)=1.
$$
Since $a, b, c \in G$ are arbitrary elements, the assertion follows.
$\blacksquare$ 
\end{proof}
\para

\begin{remark}\label{symcor1}
{\rm 
The expression \eqref{inc1} is equivalent to $\lambda_{\overline{b} \circ (a \cdot b)\circ \overline{a}} =\id$, which can also be rewritten in the forms
$$
\lambda_{\overline{a}\circ\overline{b} \circ (a \cdot b) }=\id,\quad
\lambda_{b\circ a  }=\lambda_{a \cdot b } \quad \textrm{or} \quad
\lambda_{ (\overline{a \cdot b}) \circ (b \circ a)}=\id.
$$}
\end{remark}
\para

Let us consider some examples.

\begin{example}{\rm 
Consider the  left  brace $( \mathbb{Z}, +, \circ)$, where  $+$  is the usual addition and
$$
m \circ n=m+(-1)^{m}n
$$
for $m,n \in \mathbb{Z}$. In this case, $\lambda: (\mathbb{Z}, \circ) \to \Aut(\mathbb{Z}, +)$ is the homomorphism such that $\lambda(1) = -\id$ and
$\ker(\lambda)=2\mathbb{Z}$. Further, for $m,n \in \mathbb{Z}$, we have
$$
m\circ n\equiv m + n \mod\, 2 \quad \textrm{and}\quad  \overline{m}= (-1)^{m+1}m \equiv m \mod\, 2.
$$
Thus, we have
$$
\overline{m} \circ (m+n)\circ \overline{n} \equiv 2m+2n \equiv 0\mod\, 2.
$$
Hence, by Proposition \ref{symprop1}, $(\mathbb{Z}, \circ, + )$ is a  symmetric left  brace.}
\end{example}
\para

\begin{example}{\rm 
Let $\mathbb{Z}^n=\left\langle x_1,\ldots,x_n\right\rangle$ be the  free abelian group  of rank $n$  and 
$$
\mathbb{Z}^n_0=
\left\{\, \sum\limits_{i=1}^{n} a_ix_i \in  \mathbb{Z}^n \,  \mid \,  \sum a_i=0 \,\right\}.
$$
Let $\varphi\in \Aut (\mathbb{Z}^n, +)$ be an automorphism such that $\varphi(x_i) \equiv x_i\mod \mathbb{Z}^n_0$ for each $1 \le i  \le n$. Consider the left brace $(\mathbb{Z}^n, +, \circ)$, where $a \circ b=a+\varphi^{\sum a_i}(b)$. Note that 
$\mathbb{Z}^n_0=\ker(\lambda)$. Since
$$
a \circ b \equiv a+b \mod \mathbb{Z}^n_0 \quad \textrm{and} \quad \overline{a}=-\varphi^{-\sum a_i}(a)\equiv -a \mod \mathbb{Z}^n_0,
$$
we obtain
$$
\overline{b} \circ (a+b)\circ \overline{a} \equiv -b+a+b-a \equiv 0 \mod \mathbb{Z}^n_0.
$$
Hence, by Proposition \ref{symprop1}, $(\mathbb{Z}^n, \circ, +)$ is a symmetric skew  left brace.}
\end{example}

The next result gives more examples of symmetric skew left braces \cite[Theorem 5.8]{MR4346001}.

\begin{theorem} \label{t6.6}
Every $\lambda$-cyclic skew  left brace is symmetric.
\end{theorem}

\begin{proof}
Let   $(G, \cdot, \circ)$ be a $\lambda$-cyclic skew  left brace. Then  $\lambda : (G, \cdot) \to \Aut (G, \cdot)$ is a group homomorphism and $H_\lambda$ is a regular subgroup of $\Hol (G, \cdot)$. Thus, by Theorem \ref{t1},  we have
$$
\lambda \big(b^{-1} \cdot \lambda_a(b) \big)=\id,
$$
which is equivalent to
\begin{equation}\label{cyclic skew is symmetric}
\lambda \big((a \cdot b)^{-1} \cdot (a\circ b) \big)=\id.
\end{equation}
Since the image of $\lambda$ is a cyclic subgroup of  $\Aut (G, \cdot)$, it follows that  $\ker(\lambda)$ contains the commutator subgroup  of $(G, \cdot)$. Thus, \eqref{cyclic skew is symmetric} gives
$$
 \lambda \big((b \cdot a)^{-1} \cdot (a\circ b) \big)=\id,$$
 which further yields $\lambda(b \cdot a) = \lambda(a\circ b)$. Thus, by Proposition \ref{symprop1} and Remark \ref{symcor1}, it follows that  $(G, \cdot, \circ)$ is a symmetric skew  left brace. This completes the proof.
$\blacksquare$ 
\end{proof}


The next result shows that skew  left braces constructed from some exact factorizations are symmetric  \cite[Theorem 5.14]{MR4346001}.

\begin{theorem}
Let $G = A B$ be an exact factorization of a group $G$ such that $A$ is a normal subgroup of $G$. Then the skew  left brace obtained from this exact factorization is symmetric.
\end{theorem}

\begin{proof}
In view of Theorem \ref{skew left brace exact factor}, given the exact factorisation $G = AB$, we have the skew left brace $(G, \cdot, \circ)$, where
\begin{equation} \label{efeqn1}
x \circ y= a  y  b 
\end{equation}
for $x, y\in G$, where $x = a  b$. Further, for $x=ab \in G$, we have $\bar x = a^{-1}b^{-1}$. Hence, for $x_1=a_1b_1$ and $x_2=a_2b_2 \in G$, we have
$$
\bar x_1 \circ \bar x_2 \circ (x_1x_2)=a_1^{-1}a_2^{-1}a_1b_1a_2b_1^{-1}.
$$
Note that  $\lambda_x$ is the inner automorphism of $G$ induced by  $b$, that is,
$$
\lambda_x (y)=b^{-1}yb
$$
for all $y \in G$. Thus, if $x \in A$, then $\lambda_x = \id$.
Since  $A$ is a normal subgroup of  $G$, we get
$$
a_1^{-1}a_2^{-1}a_1b_1a_2b_1^{-1} \in A
$$
for all $a_1, a_2 \in A$ and $ b_1 \in B $. Hence, we have $\bar x_1 \circ \bar x_2 \circ (x_1x_2) \in \ker(\lambda)$. Thus, by  Proposition \ref{symprop1} and Remark \ref{symcor1},   $(G, \cdot, \circ)$ is a symmetric skew left brace, which completes the proof.
$\blacksquare$ 
\end{proof}

We conclude this section by introducing a generalization of a skew left brace, which might be of independent interest.

\begin{definition}
Let $k$ be a positive integer. A $(k+1)$-groupoid $(G, \circ_0, \circ_1, \circ_2, \ldots,\circ_k)$ is called a \index{skew left $k$-brace}{skew left $k$-brace} if the following conditions hold:
\begin{enumerate}
\item $(G, \circ_i)$ is a~group for each $0 \le i \le k$.
\item  For each $0 < i < k$ and $a, b, c \in G$, we have
$$
a \circ_{i} (b \circ_{i-1} c)
 = (a \circ_{i} b) \circ_{i-1} a^{\circ_{i-1}(-1)} \circ_{i-1} (a \circ_{i} c),
$$
where $a^{\circ_{i-1}(-1)}$ is the inverse to $a$ in the group $(G, \circ_{i-1})$. Note that a skew left 1-brace is simply a skew left brace.
\end{enumerate}
\end{definition}


\begin{proposition}
Let $B$ be a  Rota--Baxter operator on a group $(G, \cdot)$ and $k$ a positive integer. Define binary operations $\circ_0, \circ_1,\circ_2,\ldots,\circ_k$ on $G$ by
$$
x \circ_{i+1} y = x \circ_i B(x) \circ_i y \circ_i \big(B(x)\big)^{\circ_i(-1)}
$$
where $\circ_0 = \cdot$. Then
$(G,\circ_0, \circ_1, \circ_2,\ldots,\circ_k)$ is a~skew left $k$-brace.
\end{proposition}

\begin{proof}
The assertion follows directly from Proposition~\ref{prop:Derived}. $\blacksquare$ 
\end{proof}
\bigskip
\bigskip


