\section{Obstruction to induction of skew braces from Rota--Baxter groups} \label{obstruction to SLB arising from RBG}
In view of Remark \ref{remark lambda RBO}, if $B$ is a Rota--Baxter operator on a group $(G,\cdot)$ and $(G, \cdot, \circ_B)$ is the induced skew left brace, then $$\lambda_g(h) = B(g)hB(g)^{-1}$$ for all $g, h \in G$. Thus, for a skew left brace induced by a Rota--Baxter group, the map $\lambda$ takes values in the inner automorphism group of $(G, \cdot)$.
\para

Let $(G, \cdot, \circ)$ be a skew left brace such that  $\lambda$ takes values in the inner automorphism group of $(G, \cdot)$.  It is natural to ask whether the skew left brace $(G, \cdot, \circ)$ (equivalently, the map $\lambda$)  is induced by a Rota--Baxter operator on $(G, \cdot)$. In view of Proposition \ref{complete SLB is RBO}, the answer is affirmative when the group $(G, \cdot)$ is complete. 
In general, it was shown in \cite{MR4531710} that the obstruction to the existence of a Rota--Baxter operator is captured by a certain second group cohomology. In this section, we explore this idea in detail.
\para


We begin by recalling the connection  between group extensions and the second group cohomology \cite{MR0672956}.  Let $G$ be a group and $A$ an abelian group admitting a right action of $G$ by automorphisms. In this case, we say that $A$ is a right $G$-module. The \index{group cohomology}{group cohomology} $\Ho^\ast_{\rm Grp}(G;A)$ of  $G$ with coefficients in $A$ is the cohomology of the cochain complex $C^*(G;A)=\{C^n(G;A),\partial^n\}$ with cochain groups $C^n(G;A) = \Map(G^n,A)$ and coboundary maps $\partial^n: C^n(G;A) \to C^{n+1}(G;A)$ given by
\begin{eqnarray}\label{group coboundary 1}
\partial^n f (g_1,\ldots,g_{n+1}) &=& f(g_2,\ldots,g_{n+1}) + (-1)^{n+1} f(g_1,\ldots,g_{n}) \cdot g_{n+1}\\
\nonumber  &&+ \sum_{i=1}^n (-1)^{i} f(g_1,\ldots, g_{i-1}, g_i g_{i+1}, g_{i+2}, \ldots,  g_{n+1})
\end{eqnarray}
for all $f \in C^n(G;A)$ and $(g_1,\ldots,g_{n+1}) \in G^{n+1}$. If the coefficients are in a left $G$-module~$A$, then the coboundary maps $\partial^n: C^n(G;A) \to C^{n+1}(G;A)$ are given by
\begin{eqnarray}\label{group coboundary 2}
\partial^n f (g_1,\ldots,g_{n+1}) &=& g_1 \cdot f(g_2,\ldots,g_{n+1}) + (-1)^{n+1} f(g_1,\ldots,g_{n})\\
 \nonumber &&+ \sum_{i=1}^n (-1)^{i} f(g_1,\ldots, g_{i-1}, g_i g_{i+1}, g_{i+2}, \ldots,  g_{n+1}). 
\end{eqnarray}
\para

For each $n \ge 0$, we write $\Ho^n_{\rm Grp}(G;A)= Z^n(G;A)/ B^n(G;A)$, where $Z^n(G;A)=\ker(\partial^n)$ is the group of $n$-cocycles and  $B^n(G;A)=\im(\partial^{n-1})$ is the group of $n$-coboundaries. In particular, for $n=2$ we have $\Ho^2_{\rm Grp}(G; A)=Z^2(G; A)/B^2(G; A)$, where
$$Z^2(G; A) =\big\{\theta:G \times G \to A  \, \mid \,   \big(x \cdot \theta(y,z) \big)\theta(x, yz)= \theta(xy, z)\theta(x, y)~ \textrm{for all}\ x, y, z\in G\big\}$$
and
$$B^2(G;A) = \big\{\theta:G \times G \to A  \, \mid \,  \textrm{there exists}~\lambda:G \to A~\textrm{with}~ \theta(x, y)=~ \big(x \cdot \lambda(y) \big)\lambda(xy)^{-1} \lambda(x)~\textrm{for all}~x, y\in G \big\}.$$
\para


Let  $G$ be  a group and $A$ a (left) $G$-module. We denote the action of $G$ on $A$ by $(g, a) \mapsto g \cdot a$ for $g \in G$ and $a \in A$. Let $E$ be an extension  of $G$  by $A$,  that is,  there is a short exact sequence of groups
$$ 1 \to A \to E \xrightarrow{\pi} G\to 1$$
such that the conjugation action of $G$  on $A$ coincides with the given action, where we identify $A$ with  its image in $E$. Let  $s : G  \to  E$  be  a normalised  \index{set-theoretic section}{set-theoretic section},  that  is,  $s(1)=1$ and $\pi \big(s(x)\big) = x$ for all $x  \in G$.  Then  there exists  a  map $\theta : G \times  G \to  A$ such  that 
\begin{equation}
  \label{equation theta}
  s(x) s(y)  s(x y)^{-1}= \theta(x, y)
\end{equation}
for  all $x,  y \in G$. Associativity in $E$ implies that $\theta$ satisfy
\begin{equation*}
\big( x \cdot {\theta(y,z)} \big) \, \theta(x,yz)=\theta(xy,z) \, \theta(x,y)
\end{equation*}
for all $x,y,z\in G$,  and hence $\theta$ is  a group $2$-cocycle. Conversely, if $\theta: G \times
G \to A$ is a group $2$-cocycle, then the set $E = A \times G$ can be endowed with the group operation
\begin{equation}
  \label{equation E operation}
  (a_1, x_1) (a_2, x_2)  =  \big(a_1(x_1 \cdot a_2) \theta(x_1, x_2), \, x_1 x_2 \big)
\end{equation}
for all $a_1, a_2 \in A$ and $x_1, x_2 \in G$. The preceding observations lead to the following well-known result \cite[Chapter IV,  Section  3]{MR0672956}. 

\begin{proposition} \label{prop:rob}
Let $G$ be a group and $A$  a $G$-module. Then the following assertions hold:
  \begin{enumerate}
  \item  Given an extension $E$ of $G$  by $A$ and a set-theoretic section $s$, the map $\theta$ as defined in \eqref{equation theta}  is a  group $2$-cocycle whose cohomology class  in $\Ho^2_{\rm Grp}(G; A)$ does not  depend on the choice of the set-theoretic section.
  \item   If  $\theta: G \times  G \to  A$ is  a group $2$-cocycle, then there  exists an extension $E$ of $G$  by $A$ and a set-theoretic section $s$ such
    that \eqref{equation theta} holds. 
  \item    The extension $E$ of $G$ by $A$ splits if and only if the cohomology class of $\theta$ in  $\Ho^2_{\rm Grp}(G; A)$ is trivial.
  \end{enumerate}
\end{proposition}

\begin{remark}
{\rm  If $A$ is  a trivial $G$-module, then the corresponding  group extension is central, that is, $A \le \Z(E)$. Note that, if the central extension $E$ of $G$ by $A$ splits,  then $E\cong G\times A$.}
\end{remark}


 Let $U$ and $V$  be groups. Let $A$ be an  abelian normal subgroup of $V$ and $\psi: U \to V/A$  a group homomorphism. Note that $A$ is a $V/A$-module  under  conjugation, and  hence  a  $U$-module via the homomorphism $\psi$. Let $C: U \to V$ be a lifting of $\psi$, that is, $C$ is a set-theoretic map such that $\psi(u) = C(u) A$ for all $u \in
U$. Since $\psi$ is a group homomorphism, there exists a map  $\kappa : U \times U \to A$ such that
\begin{equation}
  \label{eq:enter-coc}
  C(u_{1}) C(u_{2}) = \kappa(u_{1}, u_{2}) C(u_{1} u_{2})
\end{equation}
for all $u_{1}, u_{2} \in U$. Expanding the expression $C((u_{1} u_{2}) u_{3})  = C(u_{1} (u_{2} u_{3}))$ for $u_1, u_2, u_3 \in U$,  it follows  that   $\kappa$    is   a group $2$-cocycle. If $\sigma: U \to A$ is a map and $C'(u) = \sigma(u) C(u)$, then the group 2-cocycle $\kappa'$ associated to $C'$ is given by
\begin{equation*}
  \kappa'(u_{1}, u_{2})
  =
  \kappa(u_{1}, u_{2}) \sigma(u_{1})
  \big(u_1 \cdot \sigma(u_{2})  \big) \sigma(u_{1} u_{2})^{-1}
\end{equation*}
for all $u_{1}, u_{2} \in U$. Thus,  $\kappa$ and $\kappa'$ differ by a group $2$-coboundary.  Proposition~\ref{prop:rob} together with \cite[Chapter  IV, Section   3,  Exercise 1(a)]{MR0672956} yield the following result.

\begin{proposition}  \label{prop:MOF}
  Let $U$  and $V$ be groups, $A$ an abelian normal subgroup  of $V$ and   $\psi : U \to V/A$  a group homomorphism. Let $C: U \to V$ be a
  lifting of $\psi$   and $\kappa:U \times U \to A$ the map defined  by~\eqref{eq:enter-coc}. Then the following assertions hold:
  \begin{enumerate}
  \item    $\kappa$ is a group $2$-cocycle whose cohomology class in $\Ho^2_{\rm Grp}(U; A)$ does not depend on the choice of the lifting.
  \item     There exists a group homomorphism $\phi : U \to V$ which is a lifting of $\psi$ if and only if the cohomology class of $\kappa$ in $\Ho^2_{\rm Grp}(U; A)$ is trivial.
  \item    Two group homomorphisms $\phi_{1}, \phi_{2}$ are liftings of $\psi$ if  and only if there exists a group $1$-cocycle $\zeta : U \to A$ such that
$ \phi_{2}(u) =  \zeta(u) \phi_{1}(u)$  for all $u \in U$.
  \end{enumerate}
\end{proposition}

Specialising to the set-up of a skew left brace, Proposition \ref{prop:MOF} leads to the following result \cite[Theorem 3.2]{MR4531710}.

\begin{theorem}  \label{thm:thm}
Let $(G, \cdot, \circ)$ be a skew left brace such that the homomorphism $\lambda: (G, \circ) \to \Aut(G, \cdot)$ takes values in $\Inn(G, \cdot)$.  Let $C  :  G \to  G$  be a  map such  that  $\lambda(g) = \iota_{C(g)}$, the inner automorphism induced by $C(g)$, for all $g  \in G$. Let $\kappa :  (G, \circ)  \times (G, \circ)  \to \Z(G, \cdot)$  be  the map defined by
  \begin{equation}
    \label{equation coc}
    C(g)\cdot C(h)
    =
    \kappa(g, h) \cdot  C(g \circ h)
  \end{equation}
  for all $g, h \in G$.
Then the  following assertions hold:
  \begin{enumerate}
  \item    $\kappa$ is a group $2$-cocycle whose cohomology class in $\Ho^2_{\rm Grp} \big((G, \circ); \Z(G, \cdot) \big)$   does not  depend on the choice  of $C$.
  \item      The map $\lambda$ is induced by a Rota--Baxter operator on $(G, \cdot)$ if and only if  the cohomology class of $\kappa$ in $\Ho^2_{\rm Grp} \big((G, \circ); \Z(G, \cdot) \big)$ is trivial. 
  \item    Two Rota--Baxter operators $B_1, B_2$ on $(G, \cdot)$ induce the same map $\lambda$  if and only if there exists a group homomorphism $\zeta : (G, \circ)
    \to \Z(G, \cdot)$ such that $  B_{2}(g) = \zeta(g) \cdot B_{1}(g) $
    for all $g \in G$.
  \end{enumerate}
\end{theorem}

\begin{proof}
Let $(G, \cdot, \circ)$ be a skew left brace such that the homomorphism $\lambda: (G, \circ) \to \Aut(G, \cdot)$ takes values in $\Inn(G, \cdot)$. Then there exists a map $C  :  G \to  G$  such  that  $\lambda(g) = \iota_{C(g)}$ for all $g  \in G$. Composing  $\lambda$  with   the  natural
isomorphism  $\Inn(G, \cdot)  \to  (G,  \cdot)/\Z(G, \cdot)$, we  obtain a group homomorphism $\psi\colon (G, \circ) \to (G, \cdot)/\Z(G, \cdot)$. Note that a group homomorphism $B : (G, \circ) \to (G, \cdot)$ is a lifting  of $\psi$ if and only if $B$ is a Rota--Baxter operator on $(G, \cdot)$ which induces $\lambda$.  Note that $\Z(G, \cdot)$ is  a trivial $(G,\circ)$-module via $\psi$. Thus, a group 1-cocycle $(G, \circ)    \to \Z(G, \cdot)$  is precisely a group homomorphism. The theorem now follows directly from Proposition~\ref{prop:MOF}.  $\blacksquare$ 
\end{proof}

\begin{remark}
{\rm 
We now see how we can explicitly determine the Rota--Baxter operator associated with the given skew left brace $(G, \cdot, \circ)$. Let $C  :  G \to  G$  be a  map such  that $\lambda(g)=\iota_{C(g)}$ for each $g \in G$. Let $\kappa$ be the group 2-cocycle defined as in~\eqref{equation coc} and suppose that the cohomology class of $\kappa$ in $\Ho^2_{\rm Grp} \big((G, \circ); \Z(G, \cdot) \big)$ is trivial. Thus, there exists a map $\sigma:  (G, \circ) \to   \Z(G, \cdot)$  such  that  
$$  \kappa(g,h)=\sigma(g)^{-1}\cdot \sigma(h)^{-1}\cdot\sigma(g\circ h)$$
for all $g, h \in G$. If  we  define $B(g)= \sigma(g) \cdot C(g)  $  for   all   $g\in  G$,   then a direct check shows that $B$ is  the  Rota--Baxter operator on $(G, \cdot)$ which induces the map $\lambda$.}
\end{remark}

\begin{example}
{\rm 
We give an example of  a skew left  brace $(G,  \cdot, \circ)$ for which the map $\lambda$ takes values in the inner automorphism group of $(G, \cdot)$, but it is not induced by a Rota--Baxter operator. In fact, the example is a simplified version  of~\cite[Example 5.4]{MR4473766}. Let $p$ be an odd prime and $H$ the Heisenberg group of order
$p^{3}$ given by the presentation
$$
  H  = \big\langle u, v, k \mid u^{p}, v^{p}, k^{p},    [u, v] = k, [u, k], [v, k] \big\rangle.
$$
Note that every element of $H$ can be written uniquely as $u^i v^j k^{q}$ for some $0\le i,j,q<p$. Let $S = \langle x,  y \rangle$ be the elementary  abelian $p$-group  of  order  $p^2$ and take  $$(G,\cdot)  = S \times  H.$$  We write $\Z(G)=\Z(G,\cdot)$ and   $K =  \langle k \rangle=\Z(H) \le
\Z(G)$. Since $H/K = \langle u K,  v K \rangle$ is the elementary abelian $p$-group of order
$p^{2}$, the assignment
$$
 \psi (x K) = u K,  \quad   \psi(y K) = v K  \quad \textrm{and} \quad  \psi(h K) = K
$$
for all $h\in H$, uniquely defines an  endomorphism $\psi:G/K \to G/K$,
whose kernel and  image are $H/K$.
\para

Let $C : G \to G$ be a map such that 
\begin{equation}
  \label{equation of lift}
  C(g) K = \psi(g K)
\end{equation}
for all $g  \in  G$. Note that $C(G) \subseteq H$ and $C(H)\subseteq K$. It is not difficult to see that  the map $\lambda : G \to \Inn(G)$  defined by $\lambda_g = \iota_{C(g)}$ depends only on $\psi$ and is independent of the choice of $C$. Further, $\lambda$  satisfies 
$$\lambda \big(g\cdot \lambda_g( h) \big) = \lambda (g) \lambda (h)$$
for all $g, h \in G$. This defines a  skew left brace  $(G, \cdot, \circ)$,  where the group operation $\circ$ is given by
$$
  g \circ h  =  g\cdot C(g)\cdot h\cdot C(g)^{-1}
$$
for all $g,h\in G$. Note that $[a, b] = 1$  for all $a \in S$  and $b \in  C(G) \subseteq H$. Thus,  the group operations $\cdot$  and $\circ$ coincide on $S$, and hence $S$ is a subgroup  of $(G, \circ)$.
\para

We now compute the associated group $2$-cocycle $\kappa$. We can  choose any map $C$ satisfying~\eqref{equation of lift}. In particular, we take the map $C : G \to G$ defined by
\begin{equation*}
  C(x^{i} y^{j} c)
  =
  u^{i} v^{j}
  \in H
\end{equation*}
for all $0 \le i, j < p$ and $c \in H$. For all  $0 \le i, j, m, n < p$ and $c, d \in H$, we have
$$ C \big((x^{i} y^{j} c) \cdot  C(x^{i} y^{j} c) \cdot (x^{m} y^{n} d)  \cdot C(x^{i} y^{j} c)^{-1} \big)=	 C(x^{i+m} y^{j+n} e)= u^{i+m} v^{j+n},$$
for some $e \in H$.
We also have
$$  C(x^{i} y^{j} c) \cdot C(x^{m} y^{n} d)=  u^{i} v^{j} u^{m} v^{n}=  u^{i+m} v^{j+n} [v^{-j}, u^{-m}]= u^{i+m} v^{j+n} k^{-j m}.$$
Thus, the group $2$-cocycle $\kappa$ is given by
\begin{equation}
  \label{equation of kappa}
  \kappa( x^{i} y^{j} c, x^{m} y^{n} d)  =  k^{-j m}
\end{equation}
and has its image in $K = \Z(H) \le \Z(G) = S \times K$.
\para

We claim that the cohomology class of $\kappa$ in $\Ho^2_{\rm Grp} \big( (G, \circ); \Z(G, \cdot) \big)$ is non-trivial.   Let $E = (S \times K) \times (G, \circ)$. Consider the central
  extension  
  \begin{equation}
    \label{eq:alt}
    1 \to S \times K \to E \to (G, \circ) \to 1
  \end{equation}
  defined by $\kappa$  and the set-theoretic section given by $s(g) =  (1, g)$. The group operation in $E$  is given as in ~\eqref{equation E operation}. It  follows from the expression \eqref{equation of kappa} for   $\kappa$ that
  \begin{eqnarray*}
    \big[(1, x), (1, y)     \big]    &= &    (1, x) (1, y) \big((1, y) (1, x) \big)^{-1}\\
&=&    (1, x y) \big(\kappa(x, y), 1\big) \big( (\kappa(y, x), 1) (1, y x) \big)^{-1}\\
&=&     (1, x y) (1, y x)^{-1} \big(\kappa(y, x), 1\big)^{-1}\\
&=&    \big(\kappa(y, x)^{-1}, 1\big)\\
&=&     (k, 1),
  \end{eqnarray*}
  so that $(1 \times K, 1)$ is contained in the  commutator subgroup    $[E, E]$ of $E$.  Suppose  that the exact sequence~\eqref{eq:alt}
  splits, and let $T$ be a complement  to $S \times K$ in $E$. Then $M  = (S  \times 1, 1)  T$ is a maximal  subgroup of
  the  finite  $p$-group $E$,  which  does  not contain  $(1  \times K, 1)$, a non-trivial subgroup of $[E, E]$.  This contradiction shows that the sequence \eqref{eq:alt} does
  not split. Hence, by Proposition~\ref{prop:rob}, the cohomology class of $\kappa$ in $\Ho^2_{\rm Grp} \big((G, \circ); \Z(G) \big)$ is  non-trivial. }
\end{example}

