\chapter*{Part II}
\begin{center}
{\huge{Racks and quandles}}
\end{center}


\chapter{Racks and quandles}\label{chapter preliminaries on racks and quandles}

\begin{quote}
Racks and quandles offer non-degenerate bijective solutions to the Yang--Baxter equation, and share a close connection with low-dimensional topology. This chapter develops the fundamental algebraic theory of racks and quandles, building upon the pioneering works of Joyce and Matveev. We showcase a range of examples of quandles, which extend across multiple mathematical disciplines, and investigate key constructions and properties that are intrinsic to racks and quandles.
\end{quote}
\bigskip

\section{Properties and examples}
A quandle is a non-empty set with a binary operation that satisfies three axioms which are algebraic formulations of the three Reidemeister moves of planar diagrams of knots in the 3-space. Ignoring the first Reidemeister move gives rise to a weaker structure called a rack. While racks and quandles are abundant in the vast realm of mathematics, their study gained momentum only after fundamental works of Joyce \cite{MR2628474, MR0638121} and Matveev \cite{MR0672410}, who independently associated a quandle to each link in the 3-space and proved it to be an almost complete invariant of knots. Although knot quandles are strong invariants of knots, it is usually difficult to distinguish two quandles from their presentations. The algebraic theory of racks and quandles has seen numerous captivating developments as a result of this.

\para

We begin with the definition of a quandle.

\begin{definition}
A \index{quandle}{\it quandle} is a non-empty set $X$ with a binary operation $(x,y) \mapsto x *y$ satisfying the following axioms:
\begin{enumerate}
\item[(Q1)] $x*x=x$ for all $x \in X$.
\item[(Q2)] For each $x, y \in X$, there is a unique $z \in X$ such that $x=z*y$.
\item[(Q3)] $(x*y)*z=(x*z) * (y*z)$ for all $x, y, z \in X$.
\end{enumerate}
An algebraic structure satisfying (Q2) and (Q3) is called a \index{rack}{\it rack}, whereas the one satisfying (Q3) is called a \index{shelf} {\it shelf} or a \index{distributive groupoid}{\it distributive groupoid}.
\end{definition}

\begin{remark}{\rm 
It is worth noting that Burstin and Mayer \cite{MR1581179} initially investigated distinct classes of finite distributive groupoids. Further, given a shelf $(X, *)$, the map $r: X \times X \to X\times X$ given by $r(x, y)=(y, x*y)$ gives a solution to the Yang--Baxter equation. Additionally, if $(X, *)$ is a rack, then the solution $(X, r)$ is bijective and non-degenerate. It was already observed by Brieskorn \cite{MR0975077} that racks provide solutions to the Yang--Baxter equation.}
\end{remark}

If $(X, *)$ is a rack, then it follows from the second quandle axiom that there exists another binary operation $*^{-1} : X \times X \to X$ such that
$$
z = x *^{-1} y  \quad \textrm{if and only if} \quad x = z * y  
$$
for all $x, y, z \in X$. This equivalent to
$$
(x * y) *^{-1} y = x = (x *^{-1} y) * y
$$
for all $x, y \in X$. The preceding identity together with the third quandle axiom implies that
\begin{eqnarray*}
(x * y) *^{-1} z &=&  (x *^{-1} z) * (y *^{-1} z),\\
(x *^{-1} y) * z &=& (x * z) *^{-1} (y * z) \quad \textrm{and}\\
(x *^{-1} y) *^{-1} z &=& (x *^{-1} z) *^{-1} (y *^{-1} z)
\end{eqnarray*}
for all $x, y, z \in X$.
\para 

If $(X,*)$ and $(Y, \circ)$ are two quandles, then a map $f:X \to Y$ is called a \index{quandle homomorphism}{\it quandle homomorphism} if
$$f(x*y)=f(x) \circ f(y)$$
for all $x, y \in X$. The set of all quandles forms a category $\mathcal{Q}$ with objects as quandles and quandle homomorphisms as morphisms in this category. We write $\Hom_{\mathcal{Q}} (X, Y)$ to denote the set of all quandle homomorphisms from $X$ to $Y$. As usual, a quandle isomorphism is a simply a bijective homomorphism of quandles. A non-empty subset $Y$ of a quandle $(X, *)$ is called a \index{subquandle}{\it subquandle} of $X$ if $Y$ forms a quandle under the operation $*$. The essential axiom to be checked in $Y$ is the second quandle axiom. Morphisms and \index{subrack} subracks of racks are defined analogously. Throughout the text, by \index{order}{\it order} of a rack or a quandle $X$, we mean the cardinality of the set $X$.
\para

If $X$ is a rack, then for each $x \in X$, we can define a map $S_x : X \longrightarrow X$ by $$S_x(y)= y*x$$ for each $y \in X$.
\para

\begin{proposition}
If $X$ is a rack, then $S_x$ is an automorphism of $X$ for each $x \in X$.
\end{proposition}

\begin{proof}
Note that the third quandle axiom can be rewritten as $S_z(x*y)=S_z(x)*S_z(y)$ for all $x, y, z \in X$. hence, each $S_x$ is a homomorphism of $X$. Further, the second quandle axiom is equivalent to each $S_x$ being a bijection. $\blacksquare$
\end{proof}

The map $S_x$ is referred to as the \index{inner automorphism}{\it inner automorphism} of $X$ induced by $x$, or  the {\it symmetry} at $x$. Let $\Aut(X)$ denote the group of all automorphisms of $X$. Then the subgroup $\Inn(X)$ of $\Aut(X)$ generated by the set $\{S_x \mid x \in X \}$ is called the group of \index{inner automorphism group}{inner automorphisms} of $X$. It is evident that $\Inn(X)$ is a normal subgroup of $\Aut(X)$.
\para 

\begin{proposition}\label{S quandle homomorphism}
If $X$ is a quandle, then the map $S: X \to \Conj(\Inn(X))$ given by $S(x)=S_x$ is a quandle homomorphism.
\end{proposition}

\begin{proof}
For $x, y, z \in X$, we have
\begin{eqnarray*}
S_{x*y}(z) &=& z * (x*y)\\
&=& \big((z*^{-1} y)*y \big)* (x*y)\\
&=& \big(((z*^{-1} y)*x)* y \big)\\
&=&  S_yS_x S_y^{-1} (z)\\
&=&  (S_x *S_y) (z),
\end{eqnarray*}
and hence $S$ is a quandle homomorphism. $\blacksquare$
\end{proof}
\para

A quandle $X$ is called \index{trivial quandle}{\it trivial} if $x*y=x$ for all $x,y \in X$. Trivial quandles are the simplest example of quandles. Note that a trivial quandle can contain arbitrary number of elements, and that any quandle on at most two elements is trivial. We denote the trivial quandle with $n$ elements by $\T_n$ and the trivial quandle with countably infinite number of elements by $\T_{\infty}$.
\medskip

It is interesting to understand similarities between quandles and groups.


\begin{proposition}
The following statements hold:
\begin{enumerate}
\item A quandle is associative if and only if it is trivial.
\item A quandle contains an identity element if and only if it is the trivial quandle with one element.
\end{enumerate}
\end{proposition}

\begin{proof}
Suppose that
$$
(x * y)  * z = x * (y * z).
$$
for all $x, y, z \in X$. Taking $z = y$, we get $(x * y) * y = x * y$. It follows from the second quandle axiom that $x*y=x$, and hence $X$ is a trivial quandle. The converse is obvious, and hence assertion (1) holds.
\para
If $X$ contains an identity element, say $e$, then $e * x = x=x*x$ for all $x \in X$. It now follows from the second quandle axiom that $x = e$. The converse is obvious, and hence we have assertion (2). $\blacksquare$
\end{proof}


Let us now see some non-trivial examples of quandles arising in different contexts. Groups turn out to be a large source of quandles. We shall often denote a finite quandle simply by its multiplication table. For this, we first order the elements of $X$ as $\{x_1, \ldots, x_n \}$. Then the $(i,j)$-th entry in the table represents the element $x_i * x_j$ of the quandle.

\begin{example}{\rm 
If $G$ is a group and $n$ an integer, then the set $G$ equipped with the binary operation
$$
a*b= b^{n} a b^{-n}
$$ for $a, b \in G$, becomes a quandle called the {\it $n$-conjugation quandle} of $G$ and is denoted by $\Conj_n(G)$. If $n=1$, then we  refer this quandle simply as the \index{conjugation quandle}{\it conjugation quandle} and denote it by $\Conj(G)$. Obviously, if $G$ is an abelian group, then $\Conj(G)$ is a trivial quandle.
\para
 For instance, if
$$
\Sigma_3 = \big\{ e, (12), (23), (13), (123), (132) \big\}
$$
is the symmetric group on three symbols, then the  conjugation quandle $\Conj(\Sigma_3)$ has the following multiplication table.
$$
\begin{tabular}{|c||c|c|c|c|c|c|}
    \hline
$*$ & $e$ & (12) & (23) & (13) & (123) & (132) \\
  \hline \hline
$e$ & $e$ & $e$ & $e$ & $e$ & $e$ & $e$ \\
\hline
(12) & (12) & (12) & (13) & (23) & (23) & (13) \\
\hline
(23) & (23) & (13) & (23) & (12) & (13) & (12) \\
\hline
(13) & (13) & (23) & (12) & (13) & (12) & (23) \\
\hline
(123) & (123) & (132) & (132) & (132) & (123) & (123) \\
\hline
(132) & (132) & (123) & (123) & (123) & (132) & (132) \\
  \hline
\end{tabular}
$$

The table shows that $\Conj(\Sigma_3)$ contains the subquandle  $\{ e, (12), (23), (13) \}$
with 4 elements. Hence, we do not have an analog of the Lagrange's theorem for finite quandles.}
\end{example}

\begin{example}{\rm 
If $G$ is a group, then the set $G$ equipped with the binary operation
$$
a*b= b a^{-1} b
$$ forms a quandle called the \index{core quandle}{\it core quandle} of $G$, which we denote by $\Core(G)$. For example, $\Core(\Sigma_3)$ has the following multiplication table.
$$
\begin{tabular}{|c||c|c|c|c|c|c|}
    \hline
$*$ & $e$ & (12) & (23) & (13) & (123) & (132) \\
  \hline \hline
$e$ & $e$ & $e$ & $e$ & $e$ & (132) & (123) \\
\hline
(12) & (12) & (12) & (13) & (23) & (12) & (12) \\
\hline
(23) & (23) & (13) & (23) & (12) & (23) & (23) \\
\hline
(13) & (13) & (23) & (12) & (13) & (13) & (13) \\
\hline
(123) & (132) & (123) & (123) & (123) & (123) & e \\
\hline
(132) & (123) & (132) & (132) & (132) & e & (132) \\
  \hline
\end{tabular}
$$}
\end{example}

\begin{example}{\rm 
If $G$ is an  abelian group, then the core quandle of $G$ is referred in the literature as the \index{Takasaki quandle}{\it Takasaki quandle} of $G$, and is denoted by $\T(G)$. Note that, for an additively written abelian group, the binary operation in $\T(G)$ is given as $$a*b= 2b-a.$$ Such quandles (earlier called \index{Kei}{\it Kei}) appeared first in the work of Takasaki \cite{MR0021002} in the context of finite geometry. 
\para

The Takasaki quandle of the cyclic group $\mathbb{Z}_n$ of integers modulo $n$ is usually referred to as the \index{dihedral quandle}{\it dihedral quandle} and is denoted by $\R_n$. We shall write $\R_n= \{0, 1, 2, \ldots, n-1 \}$, where $$i*j= 2j-i \mod n.$$ Interestingly, the dihedral quandle $\R_n$ has a nice geometrical interpretation (see Figure \ref{regular pentagon dihedral} for $\R_5$ and $\R_6$). Consider a regular $n$-gon and  denote its vertices as $a_0, a_1, \ldots, a_{n-1}$, along the counterclockwise direction.  The binary operation in $\R_n$ can be viewed as the reflection of this  $n$-gon. More precisely, $a_{i * j}$ is the vertex of the $n$-gon which one gets after reflecting $a_i$ across the line which goes through $a_j$ and is an axis of symmetry of the $n$-gon.

\begin{figure}[hbtp]
\centering
\includegraphics[height=6cm]{regular-pentagon-dihedral.pdf}
\caption{Geometric interpretation of binary operation in dihedral quandles.}
\label{regular pentagon dihedral}
\end{figure}}
\end{example}

\begin{example}\label{example generalised Alexander quandle}
{\rm 
If $G$ is a group and $\varphi \in \Aut(G)$ an automorphism of $G$, then the binary operation $$a*b=\varphi(ab^{-1})b$$ gives a quandle structure on $G$, which we denote by $\Alex(G, \varphi)$. This quandle is referred to as the \index{generalised Alexander quandle}{\it generalised Alexander quandle}.
\para
If $G$ is an additive abelian group and  $\varphi=-\id$, the inversion in $G$, then $a*b=2b-a$. Thus,  $\Alex(G, \varphi)=\T(G)$, the Takasaki quandle of $G$. On the other hand, for arbitrary $\varphi \in \Aut(G)$, we have $$a*b=\varphi(a) + (\id-\varphi)(b),$$ and  $\Alex(G, \varphi)$ is the \index{Alexander quandle}{\it Alexander quandle} of $G$.
\para

If $M$ is a module over the ring $\mathbb {Z} \left[t,\,t^{-1}\right]$ of Laurent polynomials over integers, then the right multiplication by $t$ is an automorphism of the additive abelian group of $M$. This gives the Alexander quandle structure on $M$ with
    $$
    a* b=ta+(1-t)b.
    $$}
\end{example}

\begin{example}\label{example spherical quandle}
{\rm 
Let $\mathbb{k}$ be a  field of characteristic other than 2 and $\langle ~,~ \rangle : \mathbb{k}^{n+1} \times \mathbb{k}^{n+1} \to \mathbb{k}$ the standard symmetric bilinear form. Let
$$
S(\mathbb{k}^{n+1}) = \big\{ x \in \mathbb{k}^{n+1} \, \mid \,  \langle x, x \rangle = 1 \big\}
$$
be the unit sphere in $\mathbb{k}^{n+1}$ with respect to the form $\langle ~,~ \rangle$. Then the binary operation 
$$x * y = 2 \langle x, y \rangle y -x$$
gives a quandle structure on $S(\mathbb{k}^{n+1})$, and is referred to as the \index{spherical quandle}{\it spherical quandle}.}
\end{example}


\begin{example}\label{coset quandle with auto}
{\rm 
Let $G$ be a group and $\phi$ an automorphism of $G$. Let $H$ be a subgroup of $G$ such that $H \le \Fix(\phi)= \{x \in G \mid \phi(x)=x \}$. Then the set $G/H$ of right cosets of $H$ in $G$ has a quandle structure given by 
$$Hx*Hy= H\phi(xy^{-1})y$$
for $x, y \in G$. We denote this quandle by $\Alex(G, H, \varphi)$. Taking $H$ to be the trivial subgroup recovers Example \ref{example generalised Alexander quandle}. Further, by taking $G=\Oo(n + 1, \mathbb{F})$, $H = \Oo(n,\mathbb{F})$ viewed as a subgroup of $G$ and $\phi$ to be the inner automorphism induced by the diagonal matrix $\diag(1, \ldots, 1, -1)$, we recover Example \ref{example spherical quandle}.}
\end{example} 

\begin{example}{\rm 
Let $\mathbb{k}$ be any commutative ring and $X$ a free $\mathbb{k}$-module equipped with an antisymmetric bilinear form $\langle-, - \rangle : X \times X \to \mathbb{k}$. If the additive group of the ring $\mathbb{k}$ has any two-torsion, then we require alternating rather than just antisymmetric. Then $X$ can be turned into a quandle when equipped with the binary operation
$$x * y = x + \langle x, y \rangle y
$$
for all $x, y \in X$. This quandle first appeared in \cite[Example 4]{MR1985908} where it is referred to as an \index{alternating quandle}{\it alternating quandle}. Later, from the work \cite{MR2493966} onwards, such quandles are referred to as \index{symplectic quandle}{\it symplectic quandles}.
\para

Let us consider special symplectic quandles arising from orientable surfaces. Let $\mathcal{S}_g$ be a closed orientable surface of genus $g \ge 1$. For isotopy classes $a$ and $b$ of transverse, oriented, simple closed curves in $\mathcal{S}_g$, the {\it algebraic intersection number} $\hat{i}(a,b)$ is defined as the sum of the indices of the intersection points of $a$ and $b$, where an intersection point is of index +1 when the orientation of the intersection agrees with the orientation of the surface, and is -1 otherwise. It turns out that $\hat{i}(a,b)$ depends only on the homology classes (and hence isotopy classes) of $a$ and $b$. Further, it is known \cite[Section 6.1.2]{MR2850125} that $\hat{i}(-, -)$ gives a skew-symmetric (in fact, symplectic) bilinear form on the $\mathbb{Z}$-module $\mathrm{H}_1^{\rm Cell}(\mathcal{S}_g; \mathbb{Z}) \cong \mathbb{Z}^{2g}$, where $\mathrm{H}_1^{\rm Cell}(\mathcal{S}_g; \mathbb{Z})$ is the cellular homology of $\mathcal{S}_g$. Then the binary operation given by
\begin{equation}
x*y=x + \hat{i}(x,y) y
\end{equation}
for $x, y \in \mathrm{H}_1^{\rm Cell}(\mathcal{S}_g; \mathbb{Z})$, gives a symplectic quandle structure on $\mathrm{H}_1^{\rm Cell}(\mathcal{S}_g; \mathbb{Z})$.}
\end{example}

The next example shows that quandles appear naturally in algebraic geometry as well. We refer the reader to \cite{MR0463157} for the necessary background on algebraic geometry.

\begin{example}{\rm 
Let $\Bbbk$ be an algebraically closed field of an arbitrary characteristic. A \index{quandle variety}{\it quandle variety} over $\Bbbk$ is a reduced and irreducible algebraic variety $X$ over $\Bbbk$ equipped with a quandle operation $*$ such that the map $X \times X \to X \times X$ given by 
$$(x, y) \mapsto (x, x *y)$$ is an automorphism of varieties. 
\para
Let $X$ be an algebraic variety, $A$ a connected commutative \index{algebraic group}{\it algebraic group} and $f: X \times X \to A$ a regular map with  $f(x, x) = 0$ for all $x$.  Then the set $X\times A$ has a quandle variety structure with quandle operation given by
$$(x, a) * (y, b) = \big(x, \, a + f(x, y)\big).$$ 
\para

If $G$ is a connected algebraic group, then $\Conj(G)$ is a quandle variety. Similarly, if $G$ is a connected algebraic group and $\varphi$ is an algebraic automorphism, then $\Alex(G, \varphi)$  is a quandle variety. Quandle varieties were introduced and investigated by Takahashi in \cite{MR3492048}.}
\end{example}



\begin{example}{\rm 
Example \ref{coset quandle with auto} arise naturally in the setting of Lie groups. A \index{differentiable reflection space}{\it differentiable reflection space} is a differentiable manifold with a differentiable binary operation satisfying the quandle axioms \cite{MR0239005}. For example, if $G$ is a connected Lie group with an involutive automorphism $\varphi$ and $H$ a subgroup of the fixed-point subgroup containing the identity component, then the homogeneous space $G/H$ acquires the structure of differentiable reflection space with the binary operation $$Hx *Hy=H\varphi(x y^{-1})x$$ for all $x, y \in G$. Conversely, any differentiable reflexion space can be obtained from a symmetric space \cite{MR0239005}. }
\end{example}

Examples of the preceding kind have led to transfer of ideas (for example, flatness) from the theory of Riemannian symmetric spaces to the theory of quandles \cite{MR3544543, MR3576755}. Next, we consider some quandles arising from surfaces.

\begin{example}{\rm 
Let $\mathcal{S}_g$ be a closed orientable surface of genus $g \ge 1$, $\mathcal{M}_g$ the mapping class group of $\mathcal{S}_g$ and $\mathcal{D}_g$ the set of isotopy classes of simple closed curves in $\mathcal{S}_g$. It is well-known that $\mathcal{M}_g$ is generated by Dehn twists along finitely many simple closed curves from $\mathcal{D}_g$ \cite[Theorem 4.1]{MR2850125}. The binary operation
$$\alpha * \beta= T_\beta(\alpha)$$ for $\alpha, \beta \in \mathcal{D}_g$, where $T_\beta$ is the Dehn twist along $\beta$ (See Figure \ref{dehn quandle operation}), turns $\mathcal{D}_g$ into a quandle called the \index{Dehn quandle of surface}{\it Dehn quandle} of the surface $\mathcal{S}_g$.

\begin{figure}[hbtp]
\centering
\includegraphics[height=3.8cm]{dehn-quandle.pdf}
\caption{Dehn twist.}
\label{dehn quandle operation}
\end{figure}

By identifying the isotopy class of a simple closed curve with the corresponding Dehn twist, it turns out that the quandle $\mathcal{D}_g$ is a subquandle of the conjugation quandle $\Conj(\mathcal{M}_g)$ of the mapping class group. These quandles originally appeared in the work of Zablow \cite{MR2699808, MR1967241}. Further, \cite{MR1865704,Yetter2002, MR1985908} considered a quandle structure on the set of isotopy classes of simple closed arcs in orientable surfaces with at least two punctures, and called it quandle of cords. A presentation for the quandle of cords of the disk and the 2-sphere has been given in \cite{MR1865704}.}
\end{example}

More generally, we have the following example.

\begin{example}\label{example Dehn quandle}
{\rm 
Let $G$ be a group, $A$ a non-empty subset of $G$ and $A^G$ the set of all conjugates of elements of $A$ in $G$. The \index{Dehn quandle}{\it Dehn quandle} $\mathcal{D}(A^G)$ of $G$ with respect to $A$ is defined as the set $A^G$ equipped with the binary operation of conjugation, that is, $$x*y=yxy^{-1}$$ for all $x, y \in A^G$.
\para

Clearly, $\mathcal{D}(A^G)$ is a subquandle of $\Conj(G)$ for each subset $A$ of $G$. We shall prove later in Theorem \ref{injectivity-dehn-eta} that every subquandle of $\Conj(G)$ is a Dehn quandle. Dehn quandles of groups generalise many well-known constructions of quandles from groups. 
\begin{enumerate}
\item If $A=G$, then $\mathcal{D}(G^G)$ is the conjugation quandle $\Conj(G)$. 
\item If $F(S)$ is the free group on the set $S$, then $\mathcal{D}(S^{F(S)})$ is the \index{free quandle}free quandle on $S$ \cite{Kamada2012, MR3588325, MR3729413}. 
\item If $\mathcal{W}$ is a \index{Coxeter group}Coxeter group with Coxeter generating set $S$, then $\mathcal{D}(S^{\mathcal{W}})$ is the so called \index{Coxeter quandle}Coxeter quandle \cite{MR4175808, MR3821082}. Similarly, if $\mathcal{A}$ is an \index{Artin group}Artin group with Artin generating set $S$, then $\mathcal{D}(S^{\mathcal{A}})$ is the \index{Artin quandle}Artin quandle.  
\item Let $S_{g}$ be a closed orientable surface of genus $g$ and $\mathcal{M}_{g}$ its mapping class group. If $S$ is the set of Dehn twists about essential simple closed curves, then $\mathcal{D}(S^{\mathcal{M}_{g}})$ is the Dehn quandle of the surface $\mathcal{S}_g$. 
\end{enumerate}}
\end{example}


Dehn quandles have been investigated in detail in \cite{MR4669143}. Further, in \cite{MR4642200}, two approaches to write efficient presentations for such quandles have been given. Next, we give examples of quandles arising from knots and links in the 3-sphere.  Numerous captivating texts on knot theory are readily accessible, such as \cite{MR0808776, MR0146828, MR0907872, MR1417494, MR1472978, MR1253070, MR1391727, MR0515288}.


\begin{example}\label{construction link quandle}
{\rm 
