Though we do not have associativity in (non-trivial) quandles, we can use the defining axioms to write a typical element in a standard form.

\begin{proposition}\label{left associated form in quandles}
Any element in a quandle $X$ can be written in the form
\begin{equation*}
\big(\left(\cdots\left(\left(x_0*^{\epsilon_1} x_1\right)*^{\epsilon_2} x_2\right)*^{\epsilon_3}\cdots\right)*^{\epsilon_{n-1}} x_{n-1}\big)*^{\epsilon_n} x_n,
\end{equation*}
where $x_i \in X$ and $\epsilon_i \in \{ 1, -1 \}$ are such that $x_0\neq x_1$, and if $x_i=x_{i+1}$ for any $1 \le i \le n-1$, then $\epsilon_i= \epsilon_{i+1}$.
\end{proposition}

\begin{proof}
Using the third quandle axiom in $X$, we see that
\begin{equation}\label{left association identity}
x*^\epsilon\left(y*^\delta z\right)=\big((x*^{-\delta} z)*^\epsilon y\big)*^\delta z
\end{equation}
for all $x,y,z\in X$ and $\epsilon,\delta\in\{1,-1\}$.  By a repeated use of \eqref{left association identity}, any element of $X$ can be written in the form
\begin{equation}\label{left association identity 2}
\big(\left(\cdots\left(\left(x_0*^{\epsilon_1} x_1\right)*^{\epsilon_2} x_2\right)*^{\epsilon_3}\cdots\right)*^{\epsilon_{n-1}} x_{n-1}\big)*^{\epsilon_n} x_n,
\end{equation}
where $x_i \in X$ and $\epsilon_i \in \{ 1, -1 \}$. If $x_0= x_1$, then the expression \eqref{left association identity 2} reduces to
$$ \big(\cdots((x_0 *^{\epsilon_2} x_2 )*^{\epsilon_3}\cdots )*^{\epsilon_{n-1}} x_{n-1} \big)*^{\epsilon_n} x_n.$$
And, if $x_i=x_{i+1}$ for any $1 \le i \le n-1$ and $\epsilon_i= -\epsilon_{i+1}$, then the expression reduces to
$$
\big((\cdots (( x_0*^{\epsilon_1} x_1 ) *^{\epsilon_2}\cdots *^{\epsilon_{i-1}} x_{i-1})*^{\epsilon_{i+2}} x_{i+2}  \cdots )*^{\epsilon_{n-1}} x_{n-1} \big)*^{\epsilon_n} x_n.
$$

After all the cancellations have been incorporated in \eqref{left association identity 2}, we can write each element of $X$ in the desired form. $\blacksquare$
\end{proof}

For simplicity, we write the expression \eqref{left association identity 2} as
\begin{equation*}
x_0*^{\epsilon_1} x_1*^{\epsilon_2}\cdots*^{\epsilon_n} x_n.
\end{equation*}
and refer it as the \index{left-associated product}{\it left-associated product}. We will use this convention throughout the monograph.
\para

Proposition \ref{left associated form in quandles} yields the following result \cite[Lemma 4.4.8]{MR2634013}.

\begin{proposition}\label{Lem:the canonical left associated form}
Let $X$ be a quandle. Then the product 
\begin{equation*}
(x_0*^{\epsilon_1}x_1*^{\epsilon_2}\cdots*^{\epsilon_m}x_m)*^{\mu_0}\left(y_0*^{\mu_1}y_1*^{\mu_2}\cdots*^{\mu_n}y_n\right)
\end{equation*}
of two left-associated expressions in $X$ is the left-associated expression
\begin{equation*}
x_0*^{\epsilon_1}x_1*^{\epsilon_2}\cdots*^{\epsilon_m}x_m*^{-\mu_n}y_n*^{-\mu_{n-1}}y_{n-1}*^{-\mu_{n-2}}\cdots*^{-\mu_1}y_1*^{\mu_0}y_0*^{\mu_1}y_1*^{\mu_2}\cdots*^{\mu_n}y_n.
\end{equation*}
\end{proposition}
