\chapter{Adjoint groups of quandles}\label{chapter-adjoint-groups-quandles}

\begin{quote}
The adjoint group of a rack or a quandle is simply the structure group of the solution to the Yang--Baxter equation associated to it. In this chapter, we discuss characteristics of adjoint groups within these frameworks. We explore augmented quandles and those that embed into their adjoint groups, thereby becoming unions of conjugacy classes. Additionally, we provide a classification of finite quandles whose adjoint groups are abelian.
\end{quote}
\bigskip


\section{Properties of adjoint groups}
In this section, we associate a group to a quandle that satisfies some universal property, and plays a crucial role in the structure theory of quandles.
\para

\begin{definition}
The  \index{adjoint group} {\it adjoint group} of a quandle $X$ is the group with the following presentation
$$\Adj(X)=\big\langle \textswab{a}_x, ~x \in X  \, \mid \,  \textswab{a}_{x*y}=\textswab{a}_y \textswab{a}_x \textswab{a}_y^{-1} ~ \textrm{for all} ~ x, y \in X \big\rangle.$$     
\end{definition}

\begin{remark}
{\rm 
Recall that a quandle $(X, *)$ gives rise to a solution $(X, r)$ to the Yang--Baxter equation via the braiding $r(x, y)=(y, x*y)$. It follows from the definitions that both the structure group and the derived structure group of the solution $(X, r)$ are simply the group $\Adj(X)$.  Following \cite[Section 6]{MR0638121},  we refer the  group as the adjoint group, but it is also known in the literature as  the {\it associated group} \cite[Section 2]{MR1194995}, the {\it enveloping group} \cite[Definition 1.5]{MR1994219} and the {\it structure group} \cite[Section 2]{MR1722951}.
}    
\end{remark}

\begin{example}
{\rm 
If $\T_n$ is the trivial quandle on $n$ elements, then $$\Adj(\T_n)=  \big\langle \textswab{a}_x, ~x \in \T_n  \, \mid \,  \textswab{a}_y \textswab{a}_x= \textswab{a}_x \textswab{a}_y ~ \textrm{for all} ~ x, y \in \T_n \big\rangle,$$ and hence $\Adj(\T_n)$ is the free abelian group of rank $n$.
}    
\end{example}

Let $\mathcal{Q}$ and $\mathcal{G}$ denote the categories of quandles and groups, respectively.  Taking the adjoint group of a quandle is a functor $$\Adj: \mathcal{Q} \to \mathcal{G}.$$ Further, $\Adj$ is left adjoint of the functor $$\Conj: \mathcal{G} \to \mathcal{Q}.$$ More precisely, there is a bijection
$$\Hom_{\mathcal{Q}} \big(X, \Conj(G) \big) \longleftrightarrow \Hom_{\mathcal{G}} \big(\Adj(X), G \big)$$
for each $X \in \mathcal{Q}$ and $G \in \mathcal{G}$. By functoriality, any quandle homomorphism $f: X \rightarrow Y$ induces a group homomorphism $f_\#: \Adj(X) \rightarrow \Adj(Y)$ defined as $$f_\#(\textswab{a}_x)=\textswab{a}_{f(x)}$$ for any $x \in X$. 
\para

There is a natural map $i_X: X \rightarrow \Adj(X)$ defined as $$i_X(x)=\textswab{a}_x$$ for all $x \in X$. The following result of Winker \cite[Theorem 5.1.7]{MR2634013} gives a smaller presentation of the adjoint group $\Adj(X)$ using a given presentation of the quandle $X$.

\begin{theorem}\label{presentation-of-adjoint-group}
Let $X$ be a quandle with a presentation $\langle S \mid R \rangle$. Then the adjoint group $\Adj(X)$ has a presentation $\langle \overline{S} \mid \overline{R} \rangle$, where 
$ \overline{S} = \{\textswab{a}_x  \, \mid \,  x \in S \}$ and $\overline{R}$ consists of relations in $R$ with each expression $x*y$ replaced by $\textswab{a}_y \textswab{a}_x \textswab{a}_y^{-1}$ and the expression $x *^{-1} y$ replaced by $\textswab{a}_y^{-1} \textswab{a}_x \textswab{a}_y$.
\end{theorem}

\begin{proof}
It follows from Proposition \ref{left associated form in quandles} that any relation in $R$ is of the form 
$$x_0 *^{\epsilon_1} x_1  *^{\epsilon_2} \cdots  *^{\epsilon_n} x_n=  y_0 *^{\varepsilon_1} y_1  *^{\varepsilon_2} \cdots  *^{\varepsilon_m} y_m$$
for some $x_i, y_j \in X$ and $\epsilon_i, \varepsilon_j \in \{1, -1\}$. Setting $G=\langle \overline{S}  \, \mid \,  \overline{R} \rangle$, it suffices to show that $G \cong \Adj(X)$. The map $\phi: \overline{S} \to \Adj(X)$ given  by $\phi(\textswab{a}_x)=\textswab{a}_x$ for $x \in S$ defines a group homomorphism from the free group $F(\overline{S})$ to $\Adj(X)$, which we denote by $\phi$ itself. If $x \in X$, then by Proposition \ref{left associated form in quandles}, we can write
$x=x_0 *^{\epsilon_1} x_1  *^{\epsilon_2} \cdots  *^{\epsilon_n} x_n$ for some $x_i\in S$ and $\epsilon_i \in \{1, -1\}$. Thus,
\begin{eqnarray*}
    \textswab{a}_x &=& \textswab{a}_{x_0 *^{\epsilon_1} x_1  *^{\epsilon_2} \cdots  *^{\epsilon_n} x_n}\\
    &=& \textswab{a}_{x_n}^{\epsilon_n} \textswab{a}_{x_{n-1}}^{\epsilon_{n-1}} \cdots \textswab{a}_{x_1}^{\epsilon_1} \textswab{a}_{x_0}\textswab{a}_{x_1}^{-\epsilon_1} \cdots  \textswab{a}_{x_{n-1}}^{-\epsilon_{n-1}} \textswab{a}_{x_n}^{-\epsilon_n}\\
    &=& \phi\big( \textswab{a}_{x_n}^{\epsilon_n} \textswab{a}_{x_{n-1}}^{\epsilon_{n-1}} \cdots \textswab{a}_{x_1}^{\epsilon_1} \textswab{a}_{x_0}\textswab{a}_{x_1}^{-\epsilon_1} \cdots  \textswab{a}_{x_{n-1}}^{-\epsilon_{n-1}} \textswab{a}_{x_n}^{-\epsilon_n}\big),
\end{eqnarray*}
and hence $\phi$ is surjective. By definition of $\Adj(X)$, if $\overline{r}=\overline{s}$ is any relation in $\overline{R}$, then $\phi(\overline{r})=\overline{r}=\overline{s}=\phi(\overline{s})$ in $\Adj(X)$ as well, and hence $\phi$ induces a surjective group homomorphism $\overline{\phi}: G \to \Adj   (X)$. Finally, injectivity of $\overline{\phi}$ follows from the fact that relations in the definition of $\Adj(X)$ can be derived from relations in $\overline{R}$. $\blacksquare$
\end{proof}
\para

Let  $X \star Y$ denote the free product of quandles $X$ and $Y$. For the sake of clarity, we denote by $G \hexstar H$ the free product of groups $G$ and $H$.

\begin{proposition}\label{presentation-of-adjoint-group-of-free-product-of-quandles}
If $X$ and $Y$ are quandles, then $\Adj(X \star Y) \cong  \Adj(X) \hexstar \Adj(Y).$
\end{proposition}

\begin{proof}
If $X$ and $Y$ have presentations $X = \langle S_1 \,\mid \, R_1 \rangle$ and $Y = \langle S_2  \, \mid \, R_2 \rangle$, then $X \star Y = \langle S_1 \sqcup S_2 \, \mid \, R_1 \sqcup R_2 \rangle$. Now, by Theorem \ref{presentation-of-adjoint-group}, we have
\begin{eqnarray*}
\Adj(X \star Y) & \cong & \langle \textswab{a}_x, ~x \in  S_1 \sqcup S_2 \, \mid \, \overline{R}_1 \sqcup \overline{R}_2 \rangle \\
& \cong &  \langle \textswab{a}_x, ~x \in S_1  \, \mid \, \overline{R}_1 \rangle \ast  \langle \textswab{a}_x,~x \in S_2  \, \mid \, \overline{R}_2 \rangle\\
& \cong &  \Adj(X) \hexstar \Adj(Y),
\end{eqnarray*}
which completes the proof. $\blacksquare$   
 \end{proof}      



\begin{proposition}\label{rank-of-free-quandle}
Let $FQ(S)$ and $ FQ(T)$ be free quandles on sets $S$ and $T$, respectively. If $FQ(S)\cong FQ(T)$, then $|S|=|T|$.
\end{proposition}

\begin{proof}
It follows from Theorem \ref{presentation-of-adjoint-group} that for free quandles $FQ(S)$ and $FQ(T)$, we have $\Adj \big(FQ(S) \big)\cong F(S)$ and $\Adj\big(FQ(T) \big) \cong F(T)$, the free groups on the sets $S$ and $T$, respectively. Since $FQ(S)\cong FQ(T)$, we must have $\Adj \big(FQ(S) \big) \cong \Adj \big(FQ(T)\big)$, and hence $|S|=|T|$.
$\blacksquare$    \end{proof}          


In view of Proposition \ref{rank-of-free-quandle}, we can define the \index{rank of free quandle}{\it rank of a free quandle} as the cardinality of its any free generating set.
\para


The adjoint group of a quandle satisfies the following properties \cite[Section 6]{MR0638121}.

\begin{proposition}\label{Prop: natural map from quandle to its adjoint group}
The following statements hold for any quandle $X$.
\begin{enumerate}
\item The natural map $i_X: X \rightarrow \Conj \big(\Adj(X) \big)$ is a quandle homomorphism.
\item For any group $G$ and a quandle homomorphism $f: X \rightarrow \Conj(G)$, there exists a unique group homomorphism $\bar{f}: \Adj(X) \rightarrow G$ such that the diagram 

		$$\begin{tikzcd}
		X \arrow[d, "f"'] \arrow[r, "i_X"] & \Conj \big(\Adj(X) \big) \arrow[d, "\bar{f}"] \\
		\Conj(G) \arrow[r, "\id_G"']           & G                          
		\end{tikzcd}$$
	\end{enumerate}
	commutes. Here, $\bar{f}$ is also viewed as a map $\Conj \big(\Adj(X) \big) \rightarrow G$.
\end{proposition}

\begin{proof}
If $x, y \in X$, then $i_X(x*y)=\textswab{a}_{x*y}= \textswab{a}_y \textswab{a}_x \textswab{a}_y^{-1}= \textswab{a}_x*\textswab{a}_y= i_X(x)* i_X(y)$. Thus, $i_X$ is a quandle homomorphism, which is assertion (1).
\para

Given a quandle homomorphism $f: X \to \Conj(G)$, we define $\bar{f}: \Adj(X) \rightarrow G$ by $\bar{f}(\textswab{a}_x)= f(x)$ for all $x \in X$. Then, for $x, y \in X$, we have
$$\bar{f} (\textswab{a}_{x*y})= f(x*y)=f(x)*f(y)=f(y) f(x) f(y)^{-1}= \bar{f}(\textswab{a}_y) \bar{f}(\textswab{a}_x) \bar{f}(\textswab{a}_y)^{-1}= \bar{f}(\textswab{a}_y \textswab{a}_x \textswab{a}_y^{-1}),$$
and hence $\bar{f}$ is a group homomorphism. Further, $\bar{f} i_X (x)= \bar{f}(\textswab{a}_x)= f(x)$ for all $x \in X$, which proves assertion (2). $\blacksquare$
\end{proof}


\begin{remark} \label{image-under-eta}
{\rm
If $X$ is a quandle and $f : X \rightarrow \{a\}$ the trivial quandle homomorphism, then the  induced group homomorphism $f_{\#}: \Adj(X) \rightarrow \Adj(\{a\}) \cong \mathbb{Z}$ is given by $f_{\#}(\textswab{a}_x) = 1$ for all $x \in X$. Thus, $i_X: X \rightarrow \Adj(X)$ does not map any element of $X$ onto the identity element of $\Adj(X)$.}
\end{remark}


\begin{remark} \label{eta not injective}
{\rm
The natural map $i_X: X \rightarrow \Adj(X)$ is not injective in general. For example, consider the quandle
$$
\J_3=\begin{tabular}{|c||c|c|c|}
    \hline
$*$ & 1 & 2 & 3  \\
  \hline \hline
1 & 1 & 1 & 1  \\
\hline
2 & 3 & 2 & 2  \\
\hline
3 & 2 & 3 & 3  \\
  \hline
\end{tabular}
$$
of Example \ref{all three element quandles}. Since $1=1*2$, we have $\textswab{a}_{1}=\textswab{a}_{1*2}=\textswab{a}_2 \textswab{a}_1 \textswab{a}_2^{-1}$, and hence $\textswab{a}_2\textswab{a}_1=\textswab{a}_1 \textswab{a}_2$. Now, $3=2*1$ implies that $$i_X(3)=\textswab{a}_3=\textswab{a}_{2*1}= \textswab{a}_1 \textswab{a}_2 \textswab{a}_1^{-1}=\textswab{a}_2=i_X(2),$$ and hence $i_X$ is not injective.}
\end{remark}


Given a quandle $X$, there is a group homomorphism $$\zeta: \Adj(X) \rightarrow \Inn(X)$$ defined on generators by $\zeta(\textswab{a}_x)=S_x$ for each $x \in X$. 

\begin{proposition}\label{adj inn central extension}
If $X$ is a quandle, then
$$
1 \to \ker(\zeta) \to \Adj(X) \to \Inn(X) \to 1
$$
is a central extension of groups.
\end{proposition}

\begin{proof}
The map $\zeta$ is clearly a surjective group homomorphism.  Further, the homomorphism $\zeta$ induces a left-action of $\Adj(X)$ on $X$ by $\textswab{a}_y \cdot x=S_y(x)=x*y$ for $x, y \in X$. If $x \in X$ and $g=\textswab{a}_{x_1}^{\epsilon_1}\textswab{a}_{x_2}^{\epsilon_2} \cdots \textswab{a}_{x_k}^{\epsilon_k} \in \Adj(X)$ for some $x_i \in X$ and $\epsilon_i \in \{1, -1\}$, then the definition of left group action implies that
\begin{eqnarray*}
\textswab{a}_{g \cdot x} &=& \textswab{a}_{(\textswab{a}_{x_1}^{\epsilon_1}\textswab{a}_{x_2}^{\epsilon_2} \cdots \textswab{a}_{x_k}^{\epsilon_k}) \cdot x}\\
&=& \textswab{a}_{\textswab{a}_{x_1}^{\epsilon_1} \cdot ( \cdots (\textswab{a}_{x_{k-1}}^{\epsilon_{k-1}} \cdot (\textswab{a}_{x_k}^{\epsilon_k} \cdot x)))}\\
&=& \textswab{a}_{(((x *^{\epsilon_k} x_k) *^{\epsilon_{k-1}} x_{k-1}) \cdots ) *^{\epsilon_1} x_1}\\
&=& \textswab{a}_{x_1}^{\epsilon_1} \textswab{a}_{x_2}^{\epsilon_2}  \cdots \textswab{a}_{x_k}^{\epsilon_k} \textswab{a}_x  \textswab{a}_{x_k}^{-\epsilon_k} \cdots \textswab{a}_{x_2}^{-\epsilon_2} \textswab{a}_{x_1}^{-\epsilon_1}\\
&=& g \textswab{a}_x g^{-1}.
\end{eqnarray*} 
Now, if  $g \in \ker (\zeta)$, then $g \cdot x=x$ for all $x \in X$. Thus, the preceding identity gives $\textswab{a}_x= g \textswab{a}_x g^{-1}$ for all $x \in X$, and hence $\ker(\zeta)$ lies in the center of $\Adj(X)$. $\blacksquare$
\end{proof}

One of the most important results concerning link quandles was independently established by Joyce \cite{MR0638121} and Matveev \cite{MR0672410}.

\begin{theorem}\label{Thm:MJ-2}
If $L$ is a link in $\mathbb{S}^3$, then $\Adj \big(Q(L) \big)\cong G(L)=\pi_1(\mathbb{S}^3 \setminus L)$.
\end{theorem}

\begin{example}\label{trefoil adjoint group b3}
{\rm 
Let $K$ be the trefoil knot. As in Example \ref{trefoil-coloring-r3}, the knot quandle of $K$ has a presentation
$$
Q(K) = \langle x, y, z   \, \mid \,  x * y = z,~ y * z = x,~ z * x = y \rangle.
$$
By Theorem \ref{presentation-of-adjoint-group}, a presentation of the adjoint group is 
$$\Adj \big(Q(K)\big)= \big\langle \textswab{a}_x, \textswab{a}_y, \textswab{a}_z  \, \mid \,  \textswab{a}_y \textswab{a}_x \textswab{a}_y^{-1} = \textswab{a}_z,~ \textswab{a}_z \textswab{a}_y \textswab{a}_z^{-1} = \textswab{a}_x, ~  \textswab{a}_x \textswab{a}_z \textswab{a}_x^{-1} = \textswab{a}_y \big\rangle.$$
We can remove the generator $\textswab{a}_z$ and the presentation takes the form
$$\Adj \big(Q(K)\big)= \big\langle \textswab{a}_x, \textswab{a}_y \, \mid \, \textswab{a}_y \textswab{a}_x \textswab{a}_y = \textswab{a}_x \textswab{a}_y \textswab{a}_x \big\rangle,$$ 
which is isomorphic to the braid group $\B_3$ on three strands.}
\end{example}


\begin{example}\label{dihh}
{\rm 
The multiplication table for the dihedral quandle $\R_3$ is as follows.
\begin{center}
\begin{tabular}{|c||c|c|c|}
    \hline
  % after \\: \hline or \cline{col1-col2} \cline{col3-col4} ...
$*$ & 0 & 1 & 2  \\
  \hline \hline
0 & 0 & 2 & 1  \\
\hline
1 & 2 & 1 & 0  \\
\hline
2 & 1 & 0 & 2  \\
  \hline
\end{tabular}
\end{center}
The adjoint group $\Adj(\R_3)$ has three generators $\textswab{a}_0, \textswab{a}_1, \textswab{a}_2$ and following defining relations
$$\textswab{a}_0 \textswab{a}_1 \textswab{a}_0^{-1}=\textswab{a}_2=\textswab{a}_1 \textswab{a}_0 \textswab{a}_1^{-1},$$
$$\textswab{a}_1 \textswab{a}_2 \textswab{a}_1^{-1} =\textswab{a}_0=\textswab{a}_2 \textswab{a}_1 \textswab{a}_2^{-1},$$
$$\textswab{a}_0 \textswab{a}_2 \textswab{a}_0^{-1} =\textswab{a}_1=\textswab{a}_2 \textswab{a}_0 \textswab{a}_2^{-1}.$$
We remove the generator $\textswab{a}_2$ using the first relation and obtain the following relations
$$\textswab{a}_0 \textswab{a}_1 \textswab{a}_0^{-1}= \textswab{a}_1 \textswab{a}_0 \textswab{a}_1^{-1}, \quad \textswab{a}_0 \textswab{a}_1 \textswab{a}_0^{-1}= \textswab{a}_1^{-1} \textswab{a}_0 \textswab{a}_1, \quad \textswab{a}_1 \textswab{a}_0 \textswab{a}_1^{-1} = \textswab{a}_0^{-1} \textswab{a}_1 \textswab{a}_0.$$
The first and the second relation  imply that $\textswab{a}_1^2 \textswab{a}_0 \textswab{a}_1^{-2}= \textswab{a}_0$, that is, $\textswab{a}_1^2$ belongs to the center of $\Adj(\R_3)$. Similarly, the first and the third relation imply that $\textswab{a}_0^2$ belongs to the center of $\Adj(\R_3)$. The square of the first relation gives $\textswab{a}_0^2=\textswab{a}_1^2$, and we obtain $\textswab{a}_0 \textswab{a}_1\textswab{a}_0=\textswab{a}_1\textswab{a}_0\textswab{a}_1$. Hence, we have 
$$\Adj(\R_3)=\big\langle \textswab{a}_0,\, \textswab{a}_1  \, \mid \,  \textswab{a}_1 \textswab{a}_0 \textswab{a}_1 = \textswab{a}_0 \textswab{a}_1 \textswab{a}_0 ~\textrm{and}~ \textswab{a}_0^2 = \textswab{a}_1^2 \big\rangle.$$ In particular, $\Adj(\R_3)$ is a homomorphic image of the braid group $\B_3$  on three strands.
}
\end{example}
\para

For a quandle $X$, let $$\delta:\Adj(X) \to \mathbb{Z}$$ be the unique surjective homomorphism of groups given by $\delta(\textswab{a}_x)=1$ for all $x\in X$.  The following result gives a decomposition of adjoint groups of quandles \cite[Lemma 2.3]{MR3671570}.

\begin{proposition}\label{adjoint group as kernel}
The following statements hold for any quandle $X$.
\begin{enumerate}
\item $\Adj(X) \cong \ker (\delta) \rtimes \mathbb{Z}$.
\item If $X$ is connected, then $\ker (\delta) = [\Adj(X), \Adj(X)]$.
\end{enumerate}
\end{proposition}

\begin{proof}
One could think of $\delta$ as the group homomorphism of adjoint groups induced by the quandle homomorphism of $X$ onto the trivial one element quandle. Let $x \in X$ an element. Since $\ker (\delta)$ is a normal subgroup of $\Adj(X)$, it follows that the product $ \ker (\delta) \langle \textswab{a}_x\rangle$ is a subgroup of $\Adj(X)$. If $y \in X$, then $\textswab{a}_y= (\textswab{a}_y\textswab{a}_x^{-1}) \textswab{a}_x \in  \ker (\delta) \langle \textswab{a}_x\rangle$, and hence  $\Adj(X)=\ker (\delta) \langle \textswab{a}_x\rangle$. Since $\ker (\delta) \cap \langle \textswab{a}_x\rangle=1$ by definition of $\delta$, it follows that
 $\Adj(X)=\ker (\delta) \rtimes \langle \textswab{a}_x  \rangle \cong \ker (\delta) \rtimes \mathbb{Z}$. This proves assertion (1).
\para
It is clear that $[\Adj(X), \Adj(X)] \subseteq\ker (\delta)$.  Consider the length function $\ell:\Adj(X)\to \mathbb{Z}$ defined as $\ell(g)=n$ if $g=\textswab{a}_{x_1}^{\epsilon_1}\dots \textswab{a}_{x_n}^{\epsilon_n}$ is a  reduced expression of $g$ in terms of generators of $\Adj(X)$, where $x_i \in X$ and $\epsilon_i\in\{\pm1\}$. We show that $\ker (\delta) \subseteq [\Adj(X), \Adj(X)]$ by induction on $\ell(g)$ for $g\in\ker (\delta)$.  If $\ell(g)=2$, then $g=\textswab{a}_{x_1}^{\pm1} \textswab{a}_{x_2}^{\mp1}$ for some $x_1, x_2 \in X$. We can assume that $g=\textswab{a}_{x_1} \textswab{a}_{x_2}^{-1}$.  Since $X$ is connected, there exists $h \in \Adj(X)$ such
that $h\cdot \textswab{a}_{x_2}=\textswab{a}_{x_1}$. Hence, $g=h \textswab{a}_{x_2} h^{-1} \textswab{a}_{x_2}^{-1} = [h, \textswab{a}_{x_2}] \in [\Adj(X), \Adj(X)]$, and we are done. Now, suppose that $\ell(g)>2$. Then there is a reduced expression of $g$ (or $g^{-1}$) such that $g=g_1 \textswab{a}_{x_1} \textswab{a}_{x_2}^{-1}g_2$ for some $x_1, x_2 \in X$ and $g_1,g_2\in \Adj(X)$.  Since $g \in \ker(\delta)$, we have 
$$0=\delta (g)=\delta(g_1)+1-1+\delta(g_2)=\delta(g_1g_2),$$
and hence $g_1g_2 \in \ker (\delta)$. As $\ell(g_1g_2)<\ell(g)$, by induction hypothesis we have $g_1g_2\in [\Adj(X), \Adj(X)]$. Writing $g=(g_1  \textswab{a}_{x_1} \textswab{a}_{x_2}^{-1}g_1^{-1})(g_1g_2)$, we see that $g\in [\Adj(X), \Adj(X)]$, which proves assertion (2).  $\blacksquare$
\end{proof}


\begin{proposition}\label{fingen} 
Let $X$ be a quandle. Then the following assertions hold:
\begin{enumerate}
\item If $X$ has finitely many orbits, then the abelianization of the adjoint group $\Adj(X)$ is isomorphic to the free abelian group $\mathbb{Z}^{\left| \mathcal{O}(X)\right|}$, where $\mathcal{O}(X)$ is the set of all orbits of $X$.
\item If $X$ is finite, then the commutator subgroup of the adjoint group $\Adj(X)$  is finitely generated.
\end{enumerate}
\end{proposition}
\begin{proof}
Recall that $\Adj(X)$ is generated by elements $\{ \textswab{a}_x \, \mid \, x \in X \}$ subject to the defining relations $\textswab{a}_{x*y}= \textswab{a}_y \textswab{a}_x \textswab{a}_y^{-1}$. Thus, modulo the commutator subgroup $[\Adj(X), \Adj(X)]$ of $\Adj(X)$, the relation $\textswab{a}_{x*y}= \textswab{a}_y \textswab{a}_x \textswab{a}_y^{-1}$ has the form $\textswab{a}_{x*y}=\textswab{a}_x$ for all $x, y \in X$. Hence, if $X$ is finite, then we have an isomorphism between the abelianization of $\Adj(X)$ and $\mathbb{Z}^{|\mathcal{O}(X)|}$, which is assertion (1).
\para

It follows from the defining relations of $\Adj(X)$ that $\textswab{a}_{x *^{-1} y}= \textswab{a}_y^{-1} \textswab{a}_x \textswab{a}_y$. Further, we have
$$
\textswab{a}_{z} (\textswab{a}_x \textswab{a}_y \textswab{a}_x^{-1} \textswab{a}_y^{-1} ) \textswab{a}_z^{-1} = \textswab{a}_{z} [\textswab{a}_x,  \textswab{a}_y]
 \textswab{a}_z^{-1} = [\textswab{a}_{x*z},  \textswab{a}_{y*z}] \quad \textrm{and} \quad 
 \textswab{a}_{z}^{-1}  [\textswab{a}_x,  \textswab{a}_y]  \textswab{a}_z = [\textswab{a}_{x *^{-1} z},  \textswab{a}_{y *^{-1}  z}].
$$
Using these identities and the  commutator identities
$$
[a b, c] = a [b, c] a^{-1} [a, c] \quad \textrm{and} \quad [c, a b] = [c, a] a [c, b] a^{-1},
$$
we can write any commutator from  $[\Adj(X), \Adj(X)]$ as a product of commutators $ [\textswab{a}_x,  \textswab{a}_y]$ for $x, y \in X$. Since the number of such commutators is finite, assertion (2) follows. $\blacksquare$
\end{proof}

Observe that the dihedral quandle $\R_3$ is connected. Thus, by Proposition~\ref{fingen}(1), the abelianization of the adjoint group $\Adj(\R_3)$ is isomorphic to $\mathbb{Z}$. The same conclusion also follows from Example \ref{dihh}, where we proved that $\Adj(\R_3)=\langle \textswab{a}_0, \textswab{a}_1  \, \mid \, \textswab{a}_1 \textswab{a}_0 \textswab{a}_1 = \textswab{a}_0 \textswab{a}_1 \textswab{a}_0~\textrm{and}~\textswab{a}_0^2 = \textswab{a}_1^2\rangle.$
\para

Recall from Remark \ref{eta not injective} that the natural map  $i_X: X\to \Adj(X)$ is not injective in general. The following result shows a relation between the automorphism group of $X$ and the automorphism group of $\Adj(X)$ when $i_X$ is injective \cite[Proposition 4]{MR3948284}.

\begin{proposition}\label{inclus} 
Let $X$ be a quandle such that the natural map $i_X: X\to \Adj(X)$ is injective. If $\Aut_X \big(\Adj(X)\big)$ denotes the subgroup of $\Aut \big(\Adj(X) \big)$ consisting of automorphisms which keep $i_X(X)$ invariant, then $\Aut_X \big(\Adj(X) \big)\cong  \Aut(X)$.
\end{proposition}

\begin{proof}
Since $i_X$ is injective, for each $f\in \Aut_X \big(\Adj(X) \big)$, the map $f': X \to X$ given by $f'(x)= i_X^{-1}(f(\textswab{a}_x))$ is a well-defined bijective map. Moreover, if $x, y \in X$, then 
\begin{eqnarray*}
f'(x*y) &=& i_X^{-1} \big(f(\textswab{a}_{x*y})\big)\\
&=& i_X^{-1} \big(f(\textswab{a}_y) f(\textswab{a}_x) f(\textswab{a}_y)^{-1} \big)\\
&=& i_X^{-1} \big(f(\textswab{a}_x) * f(\textswab{a}_y) \big)\\
&=& i_X^{-1} \big(f(\textswab{a}_x) \big) * i_X^{-1} \big(f(\textswab{a}_y) \big)\\
&=& f'(x)*f'(y),
\end{eqnarray*}
 and hence $f' \in \Aut(X)$.  This defines a map $\phi:\Aut_X \big(\Adj(X\big)) \to \Aut(X)$ given by $\phi(f)=f'$, which is clearly a group homomorphism. We claim that $\phi$ is a bijection.
\para
If $\phi(f)=\phi(g)$ for $f,g\in \Aut \big(\Adj(X) \big)$, then $f'(x)=g'(x)$ for all $x\in X$. This implies that $f=g$ since $\Adj(X)$ is generated by $i_X(X)=\{\textswab{a}_x \,\mid \, x \in X \}$. For surjectivity of $\phi$, let $\alpha \in \Aut(X)$. Then the injective composition $i_X \alpha \, i_X^{-1}:i_X(X) \to \Adj(X)$ can be extended to a group homomorphism $f:F(X) \to \Adj(X)$, where $F(X)$ is the free group on $i_X(X)$. Further, for elements $x, y \in X$, we have
\begin{eqnarray*}
f(\textswab{a}_{x*y}) &=& i_X \alpha \, i_X^{-1}(\textswab{a}_{x*y})\\
&=& i_X \alpha(x*y)\\
&=& i_X \alpha(x)*i_X\alpha(y)\\
&=& i_X\alpha(y) ~i_X \alpha(x) ~i_X\alpha(y)^{-1}\\
&=& f(\textswab{a}_y) ~ f(\textswab{a}_x) ~f(\textswab{a}_y)^{-1}\\
&=& f(\textswab{a}_y \textswab{a}_x \textswab{a}_y^{-1}),
\end{eqnarray*}
and hence $f$ can be viewed as a group homomorphism $f: \Adj(X) \to \Adj(X)$. It is easy to see that $f$ is an automorphism of $\Adj(X)$ which keeps $X$ invariant such that $\phi(f)= \alpha$.  This completes the proof of the proposition. $\blacksquare$
\end{proof}

\begin{remark}{\rm 
If $i_X:X \to \Adj(X)$ is injective,  then by Proposition \ref{inclus}, the group $\Aut(X)$ is a subgroup of $\Aut \big(\Adj(X) \big)$, which is not necessarily normal. Indeed, if $\T_n=\{x_1,\dots,x_n\}$ is the trivial quandle, then the natural map $i_X$ is injective and $\Adj(\T_n)$ is the free abelian group of rank $n$. We have $\Aut(\T_n) \cong \Sigma_{n}$, which consists of all permutations of elements of $\T_n$. On the other hand, $\Aut \big(\Adj(\T_n) \big) \cong \GL(n, \mathbb{Z})$, which acts naturally on $\Adj(\T_n)\cong \mathbb{Z}^{n}$.  If $n>1$, then consider the automorphisms
$$
\varphi :\begin{cases}x_1\mapsto x_2,&\\
x_2\mapsto x_1,&\\
x_i\mapsto x_i& ~\textrm{for}~~i>2,
\end{cases}
\quad \textrm{and } \quad 
\psi: \begin{cases}
\textswab{a}_{x_1}\mapsto \textswab{a}_{x_1}+ \textswab{a}_{x_2},&\\
\textswab{a}_{x_i}\mapsto \textswab{a}_{x_i}&~\textrm{for}~~ i>1,
\end{cases}
$$
in the groups $\Aut(\T_n)$ and $\Aut \big(\Adj(\T_n) \big)$, respectively. Viewing $\Aut(\T_n)$ as a subgroup of $\Aut \big(\Adj(\T_n)\big)$, we see that the automorphism $\psi^{-1}\varphi\psi$ of $\Adj(\T_n)$ has the form
$$
\psi^{-1}\varphi\psi : \begin{cases}
\textswab{a}_{x_1} \mapsto \textswab{a}_{x_1},& \\
\textswab{a}_{x_2} \mapsto \textswab{a}_{x_1} - \textswab{a}_{x_2},& \\
\textswab{a}_{x_i} \mapsto \textswab{a}_{x_i}& ~\textrm{for}~~i > 2,
\end{cases}
$$
and hence does not lie in $\Aut(\T_n)$. Thus, $\Aut(\T_n)$ is not a normal subgroup of $\Aut \big(\Adj(\T_n) \big)$.}
\end{remark}


Next, we show that every quandle admits a homogeneous representation in terms of its adjoint group. For this, we first recall the quandle of Example \ref{coset quandle with auto}. The construction presented below generalizes this example.


\begin{proposition}
Let $G$ be a group, $\{z_i \mid i \in I\}$ a set of elements of $G$ and $H_i \le \C_G(z_i)$ a family of subgroups of $G$. Then the disjoint union $\bigsqcup_{i \in I} G/H_i$ of right cosets forms a quandle with respect to the binary operation
$$
H_i x * H_j y = H_i z_i^{-1} x y^{-1} z_j y
$$
for $x, y \in G$. We denote this quandle by $\bigsqcup_{i \in I}(G, H_i, z_i)$.
\end{proposition}

\begin{proof}
The proof is a direct check, and hence omitted. $\blacksquare$
\end{proof}

Observe that a quandle $X$ is connected if and only if $\Adj(X)$ acts transitively on $X$. The next result shows that every quandle admits a homogeneous representation \cite{MR0638121, MR0672410}.


\begin{theorem}\label{thm connected quandle is coset quandle}
The following statements hold:
\begin{enumerate}
\item  Let $X$ be a connected quandle,  $x_0 \in X$ a fixed element and $z = \textswab{a}_{x_0} \in\Adj(X)$. Let $H$ be the stabilizer of $x_0$ under the action of $\Adj(X)$.
Then the orbit map $\xi : \Adj(X) \to X$ given by $\xi(w)= x_0 \cdot w$ induces a quandle isomorphism $$ \big(\Adj(X), H,  z \big) \cong X.$$
\item Every quandle $X$ is representable as $\bigsqcup_{i \in I}(G, H_i, z_i)$ for some group $G$, a set $\{z_i \mid i \in I\}$ of elements of $G$ and a family of subgroups $H_i \le \C_G(z_i)$ of $G$.
\end{enumerate}
\end{theorem}

\begin{proof} For assertion (1), since $X$ is connected, the map $\xi$ descends to a bijection $\overline{\xi}: \Adj(X)/H\to X$. Hence, it is enough to show that $\xi$ is a quandle homomorphism. Indeed, we see that
\begin{eqnarray*}
\overline{\xi}(Hw_1 * Hw_2) &=& \overline{\xi} (H z^{-1} w_1 w_2^{-1} z w_2)\\
&=& x_0 \cdot (z^{-1} w_1 w_2^{-1} z w_2)\\
&=& \big(((x_0 \cdot z^{-1}) \cdot w_1w_2^{-1}) \cdot z \big) \cdot w_2\\
&=& \big((x_0 \cdot w_1w_2^{-1})* x_0 \big) \cdot w_2\\
&=& \big((x_0 \cdot w_1w_2^{-1})\cdot w_2 \big) * (x_0 \cdot w_2)\\
&=& (x_0 \cdot w_1) * (x_0 \cdot w_2)\\
&=& \overline{\xi}(Hw_1) * \overline{\xi}(Hw_2)
\end{eqnarray*}
for any $w_1, w_2 \in  \Adj(X)$.
\para

Take $G = \Adj(X)$ and write $X = \bigsqcup_{i \in I} X_i$ as a disjoint union of orbits, where $X_i$ is the orbit of the element $x_i \in X$. For each $i$, let  $z_i=\textswab{a}_{x_i} \in G$ and $H_i$ the stabilizer of $x_i$, giving rise to the quandle $(G, H_i, z_i)$. For each $i$, define a map $\xi_i : G \to X_i$ by $\xi(w) = x_i \cdot w$, which induce a bijection $\overline{\xi}_i:G/H_i \to X_i$. As in  assertion (1), the map $\bigsqcup_{i \in I} \overline{\xi}_i: \bigsqcup_{i \in I}(G, H_i, z_i) \to X$ is a quandle isomorphism, which proves assertion (2). $\blacksquare$
\end{proof}

\begin{remark}{\rm  
The homogeneous representation of a connected quandle $X$ as in Theorem \ref{thm connected quandle is coset quandle} is not unique. For example, we can replace $\Adj(X)$ by groups $\Inn(X)$ or $\Aut(X)$.}
\end{remark}

