\section{Adjoint functors between categories of quandles and groups}\label{adjoint-functor-section}
Let $\mathcal{Q}$ and $\mathcal{G}$ denote the categories of quandles and groups, respectively.  Let $w = w(x,y)$ be a word in the free group $F(x,y)$ on generators $x$ and $y$. For any group $G$, the word $w$ defines a map $G\times G\to G$ given by $(g, h) \mapsto w(g, h)$  for $g, h \in G$. Setting $$g * h = w(g, h)$$ gives an algebraic structure $(Q_w(G), *)$. If $w(x,y) = y^{n} x y^{-n}$ for some integer $n$, then $Q_w(G)$ is the $n$-th conjugation quandle $\Conj_n(G)$, and if $w(x,y) = y x^{-1} y$, then $Q_w(G)$ is the core quandle $\Core(G)$. In fact, Proposition \ref{verbal rack quandle prop} shows that these are all the possibilities for $(Q_w(G), *)$ to be a quandle.
\para
For a word $w = w(x,y)\in F(x,y)$ and a quandle $X \in \mathcal{Q}$, we define the group
$$\Adj_w(X)= \big\langle \textswab{a}_x, ~x \in X \, \mid \, \textswab{a}_{x*y}=w(\textswab{a}_x, \textswab{a}_y),~~x, y \in X \big\rangle.$$
We note that if $w(x,y)=yxy^{-1}$, then $\Adj_w(X)$ is simply the adjoint group $\Adj(X)$ of $X$.


\begin{proposition}\label{verbal-adjoint}
Let $w(x,y) = y x^{-1} y$ or $y^{n} x y^{-n}$ for some $n \in \mathbb{Z}$. Then $\Adj_w: \mathcal{Q} \to \mathcal{G}$ is a functor that is left adjoint to the functor $Q_w:\mathcal{G} \to \mathcal{Q}$.
\end{proposition}

\begin{proof}
Let $X, Y \in \mathcal{Q}$ and $\phi \in \Hom_{\mathcal{Q}}(X, Y)$ a quandle homomorphism. Then we obtain a group homomorphism
$\Adj_w(\phi): F(X) \to \Adj_w(Y)$ given by $\Adj_w(\phi)(\textswab{a}_x)= \textswab{a}_{\phi(x)}$, where $F(X)$ is the free group on the set $\{\textswab{a}_x \, \mid \, x \in X\}$. Further, for $x, y \in X$, we have
\begin{eqnarray*}
\Adj_w(\phi)(\textswab{a}_{x*y})& =& \textswab{a}_{\phi(x)*\phi(y)}\\
& =& w(\textswab{a}_{\phi(x)}, \textswab{a}_{\phi(y)})\\
& =& \Adj_w(\phi) \big(w(\textswab{a}_x, \textswab{a}_y)\big),
\end{eqnarray*}
and hence we obtain a group homomorphism $\Adj_w(\phi): \Adj_w(X) \to \Adj_w(Y).$
\para

Conversely, let $G, H \in \mathcal{G}$ and $f \in \Hom_{\mathcal{G}} (G, H)$. Defining $Q_w(f): Q_w(G) \to Q_w(H)$ by $Q_w(f)(a)=f(a)$, we see that
\begin{eqnarray*}
Q_w(f)(a*b)& =& f(a*b)\\
& =& f\big(w(a, b)\big)\\
& =& w\big(f(a), f(b)\big)\\
& =& f(a)*f(b)\\
& =& Q_w(f)(a)*Q_w(f)(b)
\end{eqnarray*}
for all $a, b \in G$. Thus, $Q_w(f) \in \Hom_{\mathcal{Q}} \big(Q_w(G), Q_w(H)\big)$. A direct check shows that both $\Adj_w$ and $Q_w$ are functors.
\para

Let $X \in \mathcal{Q}$, $G \in \mathcal{G}$ and $\phi \in \Hom_{\mathcal{Q}} \big(X, Q_w(G)\big)$ a quandle homomorphism. Define $\widetilde{\phi}: F(X) \to G$ by setting $\widetilde{\phi}(\textswab{a}_x)= \phi(x)$. Then, for $x, y \in X$, we have
\begin{eqnarray*}
\widetilde{\phi}(\textswab{a}_{x*y})& =& \phi(x*y)\\
& =& \phi(x)*\phi(y)\\
& =& w\big(\phi(x), \phi(y)\big)\\
& =& \widetilde{\phi}\big(w(\textswab{a}_{x}, \textswab{a}_{y})\big),
\end{eqnarray*}
and hence $\widetilde{\phi} \in \Hom_{\mathcal{G}} \big(\Adj_w(X), G\big)$. Similarly, let $f \in \Hom_{\mathcal{G}} \big(\Adj_w(X), G\big)$ be a group homomorphism. Define $\widehat{f}: X \to Q_w(G)$ by setting $\widehat{f}(x)= f(\textswab{a}_x)$. Then, for $x, y \in X$, we have
\begin{eqnarray*}
\widehat{f}(x*y)& =& f(\textswab{a}_{x*y})\\
& =& f\big(w(\textswab{a}_x, \textswab{a}_y)\big)\\
& =& w\big(f(\textswab{a}_x), f(\textswab{a}_y)\big)\\
& =& w\big(\widehat{f}(x), \widehat{f}(y)\big)\\
& =& \widehat{f}(x) * \widehat{f}(y)
\end{eqnarray*}
and hence $\widehat{f} \in \Hom_{\mathcal{Q}} \big(X, Q_w(G)\big)$. It follows easily that $\widehat{\widetilde{\phi}}=\phi$ and $\widetilde{\widehat{f}}=f$, which estabishes that $\Adj_w$ is left adjoint to $Q_w$.  $\blacksquare$
\end{proof}

\begin{corollary}
For any quandle $X$ and any group $G$, there is a natural bijection
$$
\Hom_{\mathcal{Q}} \big(X, \Conj(G) \big) \cong \Hom_{\mathcal{G}} \big(\Adj(X), G \big).  
$$
\end{corollary}
\para

Let $\mathcal{Q}'$ denote the category of pairs $(X, \phi)$, where $X \in \mathcal{Q}$ and $\phi \in \Aut(X)$. If $(X_1, \phi_1), (X_2, \phi_2) \in \mathcal{Q}'$, then a morphism from $(X_1, \phi_1)$ to $(X_2, \phi_2)$ is a quandle homomorphism $\psi:X_1 \to X_2$ such that $$\phi_2 \, \psi= \psi \, \phi_1.$$ In case of groups, the category $\mathcal{G}'$ is defined analogously. Each object $(G, f) \in \mathcal{G}'$ gives an object $\big(\Alex_f(G),  \Alex(f) \big)$, where $\Alex(f)$ acts as $f$. On the other hand, for each $(X, \phi) \in \mathcal{Q}'$, we define the group
$$\Adj_\phi(X)= \big\langle \textswab{a}_x, ~x \in X \, \mid \, \textswab{a}_{x*y}=\textswab{a}_{\phi(x)}\textswab{a}_{\phi(y)}^{-1}\textswab{a}_{y}\quad \textrm{for all} \quad x, y \in X \big\rangle.$$
Further, the map $\phi$ extends to an automorphism $\Adj(\phi)$ of the free group $F(X)$. Moreover, for $x, y \in X$, we have 
$$ \Adj(\phi)(\textswab{a}_{x*y}) = \textswab{a}_{\phi(x)*\phi(y)}= \textswab{a}_{\phi^2(x)}\textswab{a}_{\phi^2(y)}^{-1}\textswab{a}_{\phi(y)}=
 \Adj(\phi) \big(\textswab{a}_{\phi(x)}\textswab{a}_{\phi(y)}^{-1}\textswab{a}_{y} \big),
$$
and hence $\big(\Adj_\phi(X), \Adj(\phi)\big) \in \mathcal{G}'$. It follows easily that both $\Alex$ and $\Adj$ are functors. Imitating the proof of Proposition \ref{verbal-adjoint}, we obtain the following result.

\begin{proposition}\label{alexander-adjoint}
The functor $\Adj: \mathcal{Q}' \to \mathcal{G}'$ is left adjoint to the functor $\Alex:\mathcal{G}' \to \mathcal{Q}'$.
\end{proposition}
\bigskip
\bigskip

