\section{Quandles that embed into their adjoint groups}
This section is motivated by the question of which quandles can be embedded into the conjugation quandles of groups. We begin with a generalisation of the construction of free quandles and free racks. 
\para

Let $G$ be a group and $A$ a subset of $G$. On the set $A\times G$, we define the binary operation
$$
(a, u) * (b, v) = (a, v b v^{-1} u)
$$
for $a, b \in A$ and $u, v \in G$. It is not difficult to check that the algebraic structure $(A\times G, *) $ forms a rack, which we denote by $R(G,A)$ and refer as a {\it $(G,A)$-rack}. Let $Q(G,A)$ be the quotient of $R(G,A)$ by the equivalence relation generated by $(a,uw)\sim(a,u)$ for all $a \in A$, $u \in G$ and $w\in \C_G(a)=\{x\in G \, \mid \, xa=ax\}$. Then the binary operation
$$
[(a, u)] * [(b, v)] = [(a, v b v^{-1} u)],
$$
where $[(a,u)]$ denotes the equivalence class of $(a,u)$, turns $Q(G,A)$ into a quandle referred to as a {\it $(G,A)$-quandle}. For the sake of simplicity, we write $(a,u)$ instead of $[(a,u)]$ to denote an element of  $Q(G,A)$. Note that, if $F(X)$ is the free group with free basis $X$, then $Q \big(F(X),X  \big)=FQ(X)$, the free quandle on $X$. The following observation follows from the definition.
\para

A direct computation yields the following result.

\begin{lemma}\label{simple2} 
If $x,y\in Q(G,A)$ are such that $x*y=x$, then $y*x=y$.
\end{lemma}

It seems that, similar to free quandles, the quandle $Q(G,A)$ is isomorphic to the subquandle of $\Conj(G)$ consisting of union of conjugacy classes of elements from $A$. However, it is not true, in general. For example, if $G=F_2=\langle x,y\rangle$ is a free group and $A=\{x,y,y^{-1}xy\}$, then the quandle $Q(G,A)$ has three orbits under the action of $\Inn  \big(Q(G,A) \big)$, but the subquandle of $\Conj(G)$ consisting of union of conjugacy classes of $x$ and $y$ has only two orbits under the action of its group of inner automorphisms. However, if the elements of $A$ are pairwise non-conjugate, then we have the following result \cite[Proposition 4.3]{MR4129183}.

\begin{proposition} \label{ga subquandle of conj}
Let $G$ be a group and $A$ a subset of $G$ such that the elements of $A$ are pairwise non-conjugate in $G$. Then $Q(G,A)$ is isomorphic to the subquandle of $\Conj(G)$ consisting of complete conjugacy classes of elements from $A$.
\end{proposition}

\begin{proof} 
Let $X$ denote the subquandle of $\Conj(G)$ consisting of union of conjugacy classes of elements from $A$ and consider the map $\varphi:Q(G,A)\to X$ given by $\varphi\big((a,u)\big)=u au^{-1}$. If $w\in X$, then there exist elements $b\in A$ and $x\in G$ such that $w=x bx^{-1}$. Thus, $\varphi\big((b,x)\big)=w$, and $\varphi$ is surjective. Suppose that $u au^{-1}=\varphi \big((a,u)\big)=\varphi\big((b,v)\big)=v bv^{-1}$ for $a,b\in A$ and $u,v\in G$. Since elements from $A$ are pairwise non-conjugate, it follows that $a=b$ and $vu^{-1}\in \C_G(a)$. Thus, $(a,u)=(b,v)$ in $Q(G,A)$ and $\varphi$ is injective. Further, direct computations give
\begin{eqnarray*}
\varphi \big((a,u)*(b,v)\big)&=& \varphi(a,v b v^{-1}u)\\
&=&(v b v^{-1}u) a (v b v^{-1}u)^{-1}\\
&=& (v b v^{-1}) (u a u^{-1}) (v b v^{-1})^{-1}\\
&=& \big(\varphi(b,v)\big) \big(\varphi(a,u)\big) \big(\varphi(b,v)\big)^{-1}\\
&=& \varphi \big((a,u)\big)* \varphi\big((b,v)\big),
\end{eqnarray*}
and hence $\varphi$ is an isomorphism. $\blacksquare$
\end{proof}

\begin{corollary} 
Let $G$ be a group and $A$ a set of representatives of conjugacy classes of $G$. Then $Q(G,A) \cong \Conj(G)$.
\end{corollary}

The following result demonstrates that a wide variety of quandles can be realized as $(G,A)$-quandles \cite[Theorem 4.5]{MR4129183}.


\begin{theorem}\label{theorem quandle is ga quandle}
Let $X$ be a quandle such that the natural map $i_X:X\to \Adj(X)$ is injective, and $A$ be a complete set of representatives of orbits of $X$. Then $X \cong Q  \big(\Adj(X),i_X(A)  \big)$.
\end{theorem}

\begin{proof} 
If $a\in X$, then there exist an element $x\in A$ and an inner automorphism $\varphi \in \Inn(X)$ such that $a=\varphi(x)$. Note that $\varphi$ can be written in the form $\varphi=S_{x_n}^{\varepsilon_n}S_{x_{n-1}}^{\varepsilon_{n-1}}\cdots S_{x_1}^{\varepsilon_1}$ for some $x_i\in X$ and $\varepsilon_i \in\{\pm1\}$. Thus, we can write
\begin{align}\label{canon}
a=x*^{\varepsilon_1}x_1*^{\varepsilon_2}\dots *^{\varepsilon_n}x_n.
\end{align}
Define $\psi:X\to Q  \big(\Adj(X),i_X(A) \big)$ by
$$\psi(a)= (\textswab{a}_x, \,\textswab{a}_{x_n}^{\varepsilon_n} \cdots \textswab{a}_{x_1}^{\varepsilon_1}).$$
We claim that $\psi$ is an isomorphism of quandles. First, we prove that $\psi$ is well-defined. Let $a \in X$ be such that
\begin{equation}\label{korre} 
x*^{\varepsilon_1}x_1*^{\varepsilon_2}\dots *^{\varepsilon_n}x_n=a=y*^{\epsilon_1}y_1*^{\epsilon_2}\dots *^{\epsilon_k}y_k
\end{equation}
for some $x,y\in A$, $x_i,y_j\in X$ and $\varepsilon_i,\epsilon_j \in\{\pm 1\}$. Since all the elements from $A$ belong to different orbits, we must have $x=y$. The equality \eqref{korre} implies that
$$
x*^{\varepsilon_1}x_1*^{\varepsilon_2}\dots *^{\varepsilon_n}x_n*^{-\epsilon_k}y_k*^{-\epsilon_{k-1}}\dots*^{-\epsilon_1}y_1=x.
$$
Applying the map $i_X$, we see that the element $w=\textswab{a}_{y_1}^{-\epsilon_1}\textswab{a}_{y_2}^{-\epsilon_2} \cdots \textswab{a}_{y_{k-1}}^{-\epsilon_{k-1}}\textswab{a}_{y_k}^{\epsilon_k}\textswab{a}_{x_n}^{\varepsilon_n}\textswab{a}_{x_{n-1}}^{\varepsilon_{n-1}} \cdots \textswab{a}_{x_2}^{\varepsilon_2}\textswab{a}_{x_1}^{\varepsilon_1}$ belongs to the centraliser $\C_{\Adj(X)}(\textswab{a}_x)$. Thus, we have
$$\psi(a)=(\textswab{a}_y,\textswab{a}_{y_k}^{\epsilon_k}\cdots \textswab{a}_{y_1}^{\epsilon_1})=(\textswab{a}_x,\textswab{a}_{y_k}^{\epsilon_k}\cdots \textswab{a}_{y_1}^{\epsilon_1})=(\textswab{a}_x, \textswab{a}_{y_k}^{\epsilon_k}\cdots \textswab{a}_{y_1}^{\epsilon_1}w)=(\textswab{a}_x, \textswab{a}_{x_n}^{\varepsilon_n} \cdots \textswab{a}_{x_1}^{\varepsilon_1})=\psi(a),$$
and the map $\psi$ is well-defined.
\para
Next, we prove that $\psi$ is bijective. Let $(\textswab{a}_x,w) \in Q  \big(\Adj(X),i_X(A) \big)$, where $\textswab{a}_x\in i_X(A)$ and $w\in \Adj(X)$. Since $i_X(X)=\{ \textswab{a}_x \, \mid \, x \in X\}$ generates $\Adj(X)$, we have $w=\textswab{a}_{x_n}^{\varepsilon_n}\cdots \textswab{a}_{x_1}^{\varepsilon_1}$ for some $x_i\in X$ and $\varepsilon_i \in\{\pm1\}$. Setting $a=x*^{\varepsilon_1}x_1*^{\varepsilon_2}\dots *^{\varepsilon_n}x_n$, we see that $\psi(a)=(\textswab{a}_x, \textswab{a}_{x_n}^{\varepsilon_n} \cdots \textswab{a}_{x_1}^{\varepsilon_1})$, and $\psi$ is surjective. For injectivity, consider two elements
$$ a=x*^{\varepsilon_1}x_1*^{\varepsilon_2}\dots *^{\varepsilon_n}x_n \quad \textrm{and} \quad  b=y*^{\epsilon_1}y_1*^{\epsilon_2}\dots *^{\epsilon_k}y_k,$$
where $x,y\in A$, $x_i, y_j\in X$ and $\varepsilon_i,\epsilon_i\in\{\pm 1\}$, such that
\begin{equation}\label{1inject}
(\textswab{a}_x, \textswab{a}_{x_n}^{\varepsilon_n} \cdots \textswab{a}_{x_1}^{\varepsilon_1})=\psi(a)=\psi(b)=(\textswab{a}_y, \textswab{a}_{y_k}^{\epsilon_k} \cdots \textswab{a}_{y_1}^{\epsilon_1}).
\end{equation}
It follows from the construction of $Q(G,A)$ that $\textswab{a}_x=\textswab{a}_y$. Since $i_X$ is injective, we get $x=y$. Equation \eqref{1inject} implies that the element $w=\textswab{a}_{y_1}^{-\epsilon_1} \textswab{a}_{y_2}^{-\epsilon_2} \cdots \textswab{a}_{y_{k-1}}^{-\epsilon_{k-1}} \textswab{a}_{y_k}^{\epsilon_k} \textswab{a}_{x_n}^{\varepsilon_n} \textswab{a}_{x_{n-1}}^{\varepsilon_{n-1}} \cdots \textswab{a}_{x_2}^{\varepsilon_2} \textswab{a}_{x_1}^{\varepsilon_1}$ belongs to $\C_{\Adj(X)}(\textswab{a}_x)$. Consider the element
$$c=x*^{\varepsilon_1}x_1*^{\varepsilon_2}\dots *^{\varepsilon_n}x_n*^{-\epsilon_k}y_k*^{-\epsilon_{k-1}}\dots *^{-\epsilon_1}y_1.$$
Applying $i_X$ on both the sides give $i_X(c)=w i_X(x) w^{-1}=i_X(x)$. Since $i_X$ is injective, we get $c=x=y$. This gives
$$b=y*^{\epsilon_1}y_1*^{\epsilon_2}\dots *^{\epsilon_k}y_k=c*^{\epsilon_1}y_1*^{\epsilon_2}\dots *^{\epsilon_k}y_k=x*^{\varepsilon_1}x_1*^{\varepsilon_2}\dots *^{\varepsilon_n}x_n=a$$
and $\psi$ is injective.
\para
Finally, we prove that $\psi$ is a homomorphism. Let $a=x*^{\varepsilon_1}x_1*^{\varepsilon_2}\dots *^{\varepsilon_n}x_n$ and $b=y*^{\epsilon_1}y_1*^{\epsilon_2}\dots *^{\epsilon_k}y_k$ be elements of $X$. Then $\psi(a)=(\textswab{a}_x, \textswab{a}_{x_n}^{\varepsilon_n} \cdots \textswab{a}_{x_1}^{\varepsilon_1})$, $\psi(b)=(\textswab{a}_y, \textswab{a}_{y_k}^{\epsilon_k} \cdots \textswab{a}_{y_1}^{\epsilon_1})$ and 
\begin{equation}\label{oneside}
\psi(a)*\psi(b)=(\textswab{a}_x, \textswab{a}_{y_k}^{\epsilon_k} \cdots \textswab{a}_{y_1}^{\epsilon_1} \textswab{a}_y \textswab{a}_{y_1}^{-\epsilon_1} \cdots \textswab{a}_{y_k}^{-\epsilon_k} \textswab{a}_{x_n}^{\varepsilon_n} \cdots \textswab{a}_{x_1}^{\varepsilon_1}).
\end{equation}

Note that the right-distributivity axiom can be rewritten as
\begin{equation}\label{hope}
x*^{-1}z*z*y*z=(x*z)*(y*z)
\end{equation}
for all $x, y, z \in X$. Applying \eqref{hope} repeatedly, we obtain
\begin{eqnarray*}
a*b&= & a*(y*^{\epsilon_1}y_1*^{\epsilon_2}\dots *^{\epsilon_k}y_k)\\
 &= & \big((a*^{-\epsilon_k}y_k)*(y*^{\epsilon_1}y_1*^{\epsilon_2}\dots *^{\epsilon_{k-1}}y_{k-1})\big)*^{\epsilon_k} y_k\\
 &\vdots &\\
&=&a*^{-\epsilon_k}y_k*^{-\epsilon_{k-1}}\dots *^{-\epsilon_1}y_1*y*^{\epsilon_1}y_1*^{\epsilon_2}\dots*^{\epsilon_k}y_k.
\end{eqnarray*}
Applying $i_X$ to the preceding equality and comparing with \eqref{oneside} proves that $\psi$ is a homomorphism.  $\blacksquare$
\end{proof}


\begin{remark}{\rm 
Note that Example \ref{example Dehn quandle} gives the following similar but different construction of quandles from groups. Let $G$ be a group and $A$ a non-empty subset of $G$. Let $A^G$ be the set of all conjugates of elements of $A$ in $G$. Then the {\it Dehn quandle} $\mathcal{D}(A^G)$ of $G$ with respect to $A$ is defined as the set $A^G$ equipped with the binary operation  $x*y=yxy^{-1}$ of conjugation.
\para
By Proposition \ref{ga subquandle of conj}, the quandles $Q(G, A)$ and $\mathcal{D}(A^G)$ are the same if and only if elements of $A$ are pairwise non-conjugate in $G$. Thus, for a fairly large class of groups including knot groups, mapping class groups, Artin groups and Coxeter groups, the construction in Example \ref{example Dehn quandle} differs from the one presented in this section.}
\end{remark}
\para

The next result gives a complete answer to the question posed in the beginning of this section \cite[Proposition 3.9]{MR4669143}.

\begin{theorem}\label{injectivity-dehn-eta}
The following statements are equivalent for any quandle $X$:
\begin{enumerate}
\item $X$ embeds in $\Conj(H)$ for some group $H$.
\item The natural map $i_X: X \to \Adj(X)$ is injective.
\item $X \cong \mathcal{D}(S^G)$ for some group $G$ and a generating set $S$ of $G$.
\end{enumerate}
\end{theorem}

\begin{proof}
For (1) $\Rightarrow$ (2), suppose that $f: X \hookrightarrow \Conj(H)$ is an embedding for some group $H$. Then, by Proposition \ref{Prop: natural map from quandle to its adjoint group}(2), there is a unique group homomorphism $\bar{f}: \Adj(X) \to H$ such that $f=\bar{f} ~i_X$. Thus, $i_X$ is injective. The implication (2) $\Rightarrow$ (1) is obvious.
\para
For (2) $\Rightarrow$ (3), suppose that $X$ is a quandle for which the map $i_X$ is injective. Let $A$ be the set of representatives of orbits (connected components) of $X$. We claim that elements of $i_X(A)$ are pairwise non-conjugate in $\Adj(X)$. Let $x$ and $y$ be distinct elements of  $A$ such that $\textswab{a}_x=g \textswab{a}_y g^{-1}$, where $g= \textswab{a}_{x_1}^{\epsilon_1} \textswab{a}_{x_2}^{\epsilon_2} \cdots \textswab{a}_{x_k}^{\epsilon_k}$ for $x_i \in X$ and $\epsilon_i \in \{ 1, -1\}$. Then we have
$$\textswab{a}_x=\textswab{a}_{x_1}^{\epsilon_1} \textswab{a}_{x_2}^{\epsilon_2} \cdots \textswab{a}_{x_k}^{\epsilon_k} \textswab{a}_y \textswab{a}_{x_k}^{-\epsilon_k} \cdots \textswab{a}_{x_2}^{-\epsilon_2} \textswab{a}_{x_1}^{-\epsilon_1} = \textswab{a}_{y *^{\epsilon_k} x_k *^{\epsilon_{k-1}} x_{k-1} *^{\epsilon_{k-2}} \cdots *^{\epsilon_1} x_1}.$$
Since $i_X$ is injective, it follows that $x=y *^{\epsilon_k} x_k *^{\epsilon_{k-1}} x_{k-1}*^{\epsilon_{k-2}} \cdots *^{\epsilon_1} x_1$, that is, $x$ and $y$ are in the same orbit, a contradiction. It now follows from Proposition \ref{ga subquandle of conj} and Theorem \ref{theorem quandle is ga quandle} that $X\cong \mathcal{D} \big(i_X(A)^{\Adj(X)}\big)$. If $S$ is a generating set for $X$, then $i_X(S)$ is a generating set for $\Adj(X)$. Further, $S$ intersects every orbit of $X$, and therefore we can choose a representative of an orbit from $S$. In other words, the set $A$ can be chosen to be a subset of $S$. For this choice of $A$, elements of $i_X(S)$ are conjugates of elements of $i_X(A)$ in $\Adj(X)$. Thus, $i_X(S)^{\Adj(X)}=i_X(A)^{\Adj(X)}$ as sets, and hence $X\cong \mathcal{D}\big(i_X(S)^{\Adj(X)}\big)$.
\para
For (3) $\Rightarrow$ (2), suppose that $X \cong \mathcal{D}(S^G)$ for some group $G$ and a generating set $S$ of $G$. Let $\tau: \mathcal{D}(S^G) \to \Conj(G)$ be the natural embedding and  $i_X: \mathcal{D}(S^G) \to \Conj \big(\Adj(\mathcal{D}(S^G))\big)$ the natural quandle homomorphism. Define $\phi: \Adj \big(\mathcal{D}(S^G)\big) \to G$ by $\phi(\textswab{a}_x)= x$ for $x \in \mathcal{D}(S^G)$. Since $$\phi(\textswab{a}_{x*y})=\phi(\textswab{a}_{yxy^{-1}})=yxy^{-1}=\phi(\textswab{a}_y\textswab{a}_x\textswab{a}_y^{-1})$$ for all $x, y \in \mathcal{D}(S^G)$, it follows that $\phi$ is a group homomorphism, and hence induces homomorphism of conjugation quandles. Since $\phi ~i_X=\tau$, it follows that $i_X$ is injective.  $\blacksquare$
\end{proof}

\begin{remark}{\rm 
Given a quandle $X$, there are two natural maps $i_X: X \to \Adj(X)$ and $S: X \to \Inn(X)$. The universal property of $\Adj(X)$ implies that if $S$ is injective, then $i_X$ is also injective. However, the converse is not true. For instance, if $X$ is a trivial quandle with more than one element, then $i_X$ is injective, but $S$ is not.}
\end{remark}

A knot is said to be \index{prime knot}{\it prime} if it cannot be written as a connected sum of two non-trivial knots. The following result of Ryder provides an elegant characterisation of prime knots \cite[Corollary 3.6]{MR1388194}.

\begin{theorem}\label{prime-quandles-injective-in-adjoint-group}
A knot $K$ in $\mathbb{S}^3$ is prime if and only if its knot quandle $Q(K)$ embeds into its adjoint group $\Adj \big(Q(K)\big)=G(K)$.
\end{theorem}
\para

Constructing families of quandles that embed into their adjoint groups is of particular interest. In this context,  Bardakov and Nasybullov proved the following result \cite[Lemma 7.1]{MR4129183}.

\begin{proposition}\label{embedding-of-quandles-into-adjoint-group}
Let $X$ and  $Y$  be quandles. If the natural maps $X \rightarrow \Adj(X)$ and $Y \rightarrow \Adj(Y)$ are injective, then the natural map $X \star Y \rightarrow \Adj(X) \star \Adj(Y)$ is injective.
\end{proposition}

\begin{proof}
By Proposition \ref{presentation-of-adjoint-group-of-free-product-of-quandles}, we have $\Adj(X \star Y) \cong  \Adj(X) \hexstar \Adj(Y)$. Let $i_X: X \to \Adj(X)$, $i_Y: Y \to \Adj(Y)$ and $i_{X\star Y}: X \star Y \to \Adj(X) \hexstar \Adj(Y)$  be natural maps.  Let $a, b\in X\star Y$ be such that $i_{X\star Y}(a)=i_{X\star Y}(b)$. The elements $a,b$ can be written in the forms $a=a_1*^{\varepsilon_2}\dots *^{\varepsilon_n} a_n$ and $b=b_1*^{\mu_2}\dots *^{\mu_k} b_k$, where each $a_i,b_j$ belongs to either $X$ or $Y$ and $\varepsilon_2,\dots,\varepsilon_n,\mu_2,\dots,\mu_k\in \{1, -1\}$. Since there is no non-trivial element in $\Adj(X)$ that is conjugate to an element in $\Adj(Y)$, it follows that $a_1,b_1$ both belong to either $X$ or $Y$. Without loss of generality, we can assume that $a_1,b_1\in X$. Setting
$$c:=a_1*^{\varepsilon_2}\dots *^{\varepsilon_n} a_n*^{-\mu_k}b_k*^{-\mu_{k-1}}\dots *^{-\mu_2} b_2,$$
we see that $i_{X\star Y}(c)=i_{X\star Y}(b_1)$.  By definition of $i_{X\star Y}$, we have
$$(\textswab{a}_{b_2}^{-\mu_2} \cdots \textswab{a}_{b_k}^{-\mu_k} \textswab{a}_{a_n}^{\varepsilon_n}\cdots \textswab{a}_{a_3}^{\varepsilon_3} \textswab{a}_{a_2}^{\varepsilon_2}) \textswab{a}_{a_1} (\textswab{a}_{b_2}^{-\mu_2} \cdots \textswab{a}_{b_k}^{-\mu_k} \textswab{a}_{a_n}^{\varepsilon_n}\cdots \textswab{a}_{a_3}^{\varepsilon_3} \textswab{a}_{a_2}^{\varepsilon_2})^{-1}=i_{X\star Y}(c)=i_{X\star Y}(b_1)=\textswab{a}_{b_1}.$$
It follows that the element $\textswab{a}_{b_2}^{-\mu_2} \cdots \textswab{a}_{b_k}^{-\mu_k} \textswab{a}_{a_n}^{\varepsilon_n}\cdots \textswab{a}_{a_3}^{\varepsilon_3} \textswab{a}_{a_2}^{\varepsilon_2}$ belongs to $\Adj(X)$, since two elements from $\Adj(X)$ are conjugated in $\Adj(X)\ast \Adj(Y)$ if and only if they are conjugated in $\Adj(X)$. Thus, the element can be written as
$$\textswab{a}_{b_2}^{-\mu_2} \cdots \textswab{a}_{b_k}^{-\mu_k} \textswab{a}_{a_n}^{\varepsilon_n}\cdots \textswab{a}_{a_3}^{\varepsilon_3} \textswab{a}_{a_2}^{\varepsilon_2}=\textswab{a}_{x_1}^{\xi_1}\dots \textswab{a}_{x_t}^{\xi_t}$$
for some $x_1,\dots, x_t\in X$ and $\xi_1,\dots,\xi_t\in\{1, -1\}$. Hence, we have the equality
$$c=a_1*^{\varepsilon_2}\dots *^{\varepsilon_n} a_n*^{-\mu_k}b_k*^{-\mu_{k-1}}\dots *^{-\mu_2} b_2=a_1*^{\xi_t}x_t*^{\xi_{t-1}}\dots*^{\xi_1}x_1,$$
which implies that $c\in X$. Since $i_X(c)=i_X(b_1)$ and $i_X$ is injective, we conclude that $c=b_1$, and hence $a=b$. $\blacksquare$
\end{proof}
