\section{Quandles with abelian adjoint groups}

The purpose of this section is to classify finite quandles with abelian adjoint groups. We begin with the following result of Lebed and Vendramin \cite[Theorem 7.15]{MR3974961}. 

\begin{theorem}\label{thm Lebed Vendramin}
The following statements are equivalent for a finite quandle $X$:
\begin{enumerate}
\item $\Adj(X)$ has no torsion.
\item $\Adj(X)$ is free abelian.
\item $\Adj(X)$ is abelian.
\end{enumerate}

\end{theorem}
\begin{proof}
Let $(X, *)$ be the given quandle. The implications $(2) \Rightarrow (1)$  and $(2) \Rightarrow (3)$ are immediate. Assume that $\Adj(X)$ has no torsion. By Proposition \ref{adj inn central extension}, we have the central extension of groups
$$
1 \to \ker(\zeta) \to \Adj(X) \to \Inn(X) \to 1.
$$
Since $X$ is finite, it follows that the center of $\Adj(X)$ is of finite index. Then, by Schur's theorem \cite[Theorem 5.32]{MR1307623}, the commutator subgroup of $\Adj(X)$ is finite. Since $\Adj(X)$ has no torsion, this subgroup is trivial, and hence $\Adj(X)$ is free abelian. This proves  $(1) \Rightarrow (2)$.
\para
Now, assume that $\Adj(X)$ is abelian. Define an equivalence relation $\sim$ on $X$ by setting $x \sim y$ if and only if $\textswab{a}_x=\textswab{a}_y$ in $\Adj(X)$. If $X/\!\sim$ is the set of equivalence classes, then the binary operation $[x]*' [y]:=[x*y]$ turns $X/\!\sim$ into a quandle. Further, by the construction of  $X/\!\sim$, it follows that $\Adj(X/\!\sim) \cong \Adj(X)$. For any $x,y\in X$, we have $\textswab{a}_x \textswab{a}_y=\textswab{a}_y \textswab{a}_x=\textswab{a}_{x * y} \textswab{a}_y$ in $\Adj(X)$, and hence $x \sim x * y$. Thus, the induced  quandle $(X/\!\sim,*')$ is trivial. Since  $\Adj(X/\!\sim) \cong \Adj(X)$, the triviality of $X/\!\sim$ implies that $\Adj(X/\!\sim)$, and hence $\Adj(X)$ is free abelian. This proves $(3) \Rightarrow (2)$. $\blacksquare$
\end{proof}


Theorem \ref{thm Lebed Vendramin} shows that adjoint groups of finite quandles exhibit the following dichotomy:
\begin{enumerate}
\item either they are free abelian of rank $r = |\mathcal{O}(X)|$, where $\mathcal{O}(X)$ is the set of orbits of $X$,
\item or they are non-abelian and have torsion.
\end{enumerate}

It is natural to ask which quandles lie in the first class. The condition $\Adj(X)\cong \mathbb{Z}$ is easily seen to be equivalent to $X$ being a one element quandle. Quandles with $\Adj(X) \cong \mathbb{Z}^2$ were first characterised in \cite{MR4129183}. This work was extended in \cite{MR4116819} to characterise all finite quandles $X$ with $\Adj(X) \cong \mathbb{Z}^r$ for arbitrary $r$, which we present in this section. We first show that quandles with abelian adjoint groups are necessarily abelian, that is, they satisfy the condition
\begin{equation}\label{equation abelian quandle}
(a * b) * c = (a * c) * b.
\end{equation}
\para

We fix a positive integer $r \geq 2$, and consider a collection 
\begin{equation}\label{parameter matrix}
M=(m_{i,j})_{1 \leq j \leq i <r}
\end{equation}
of $\frac{r(r-1)}{2}$ integers, where $1 \leq m_{i,i}$ and  $0 \leq m_{j,i} < m_{i,i}$ for $i < j$. We think of $M$ as a lower triangular matrix of size $r-1$, and associate an abelian group $G(M)$ by defining
$$G(M) = \big\langle x_1, \ldots, x_{r-1} ~|~ x_ix_j=x_jx_i, \quad x_1^{m_{i,1}}x_2^{m_{i,2}}\cdots x_i^{m_{i,i}} =1 \quad \textrm{for} \quad 1 \le i, j \le r-1 \big\rangle.$$
Using the notations $x_0:=1$ and $m_i:=m_{i,i}$, we see that the group $G(M)$ is finite abelian of order $m_{1}m_{2}\cdots m_{r-1}$.
\para

For instance, $r=2$ gives the cyclic group of order $m_{1}$. For $r=4$ and 
$M=\begin{psmallmatrix}
m_1& 0& 0\\ 
m_{2,1}&m_{2}&0&\\
m_{3,1}&m_{3,2}&m_{3}
\end{psmallmatrix}$, 
we get commuting generators $x_1, x_2, x_3$ subject to relations
$$ x_1^{m_{1}}=1, \quad x_1^{m_{2,1}}x_2^{m_{2}}=1, \quad x_1^{m_{3,1}}x_2^{m_{3,2}}x_3^{m_{3}}=1.
$$

We take $r$ collections $M^{(1)}$, \ldots, $M^{(r)}$ as above, and consider the disjoint union
$$Q(M^{(1)}, \ldots, M^{(r)}):=G(M^{(1)})\sqcup \cdots \sqcup G(M^{(r)}).$$
We denote the generator $x_i$ of $G(M^{(j)})$ by $x_i^{(j)}$, and equip $Q(M^{(1)}, \ldots, M^{(r)})$ with a binary operation $*$ as follows. For any $a^{(i)} \in G(M^{(i)})$ and $b^{(i+k)}\in G(M^{(i+k)})$, where $0 \leq k < r$ and the sum $i+k$ is considered modulo $r$, we put
$$a^{(i)} * b^{(i+k)} = a^{(i)}x_k^{(i)} \in G(M^{(i)}).$$
Since $x_0^{(i)}=1$, we have $a^{(i)} * b^{(i)} = a^{(i)}$ for each $i$. It is not difficult to prove the following result  \cite[Proposition 2.1]{MR4116819}.

\begin{proposition} \label{abelian quandle from parameters}
The quandle $\big(Q(M^{(1)}, \ldots, M^{(r)}), * \big)$ is abelian with $r$ components $G(M^{(1)}), \ldots, G(M^{(r)})$ as its orbits. 
\end{proposition}

\begin{proof}
The first two quandle axioms, and the assertion about the orbits, are clear from the construction. Moreover, the groups  $G(M^{(i)})$ are abelian, and hence all right $*$-actions commute. Consequently, we obtain the condition  \eqref{equation abelian quandle}. By construction, all elements from the same orbit $G(M^{(i)})$ of $Q(M^{(1)}, \ldots, M^{(r)})$ have the same right $*$-actions. Hence, we obtain
$$(a * b) * c = (a * c) * b = (a * c) * (b * c)$$
 for all $a,b,c \in Q(M^{(1)}, \ldots, M^{(r)})$, which is the third quandle axiom.
  $\blacksquare$
\end{proof}

\begin{definition}
A quandle $X$ such that $X \cong Q(M^{(1)}, \ldots, M^{(r)})$ is called a \index{filtered-permutation quandle} {\it filtered-permutation quandle}, and $M^{(1)}, \ldots, M^{(r)}$ are called the {\it parameters} of $X$.
\end{definition}


\begin{remark}
{\rm For $r=2$,  by assuming $m^{(1)}_1\leq m^{(2)}_1$, we recover the quandle $U_{m_1^{(1)},m_1^{(2)}}$ considered in \cite{MR4129183}. These quandles are parametrised by coprime tuples $(m,n)$ with $m\leq n$, and are presented as 
\begin{equation}
U_{m,n} = \big\{x_0,x_1, \ldots, x_{m-1}, y_0,y_1,\ldots, y_{n-1} \big\}
\end{equation}
with
$$x_i * x_j = x_i, \quad y_k * y_l = y_k,\quad  x_i * y_k = x_{i+1}, \quad  y_k * x_i = y_{k+1},$$
where $x_{m}=x_0$, $y_{n}=y_0$, $0 \leq i,j \leq m-1$ and $0 \leq k,l \leq n-1$.}
\end{remark}
\medskip

Using structural results on medial quandles, that is, quandles satisfying the condition $$(a * b) * (c * d)=(a * c) * (b * d),$$
the following result is derived in \cite{MR3400403}. The proof presented below is from \cite[Theorem 2.3]{MR4116819}.

\begin{theorem}\label{abelian filtered per module}
The following statements are equivalent for a finite quandle $X$.
\begin{enumerate}
\item $X$ is abelian.
\item $X$ is isomorphic to a filtered-permutation quandle.
\end{enumerate}
Moreover, two filtered-permutation quandles with $r$ ordered orbits are isomorphic if and only if they have the same parameters $M^{(1)}, \ldots, M^{(r)}$.
\end{theorem}

\begin{proof} 
The implication (2) $\Rightarrow$ (1) follows from Proposition~\ref{abelian quandle from parameters}. For (1) $\Rightarrow$ (2), first note that if $X$ is an abelian quandle, then
$$(a * b) * c = (a * c) * b = (a * b) * (c * b)$$
for all $a,b,c \in X.$ Since the right translation $- * b$ is bijective, we have
$$a * c = a * (c * b)$$
for all $a,b,c \in X.$ Further, since $X$ is finite abelian, we have $a * a' = a * a = a$ for $a$ and $a'$ from the same orbit. Let $O_1,\ldots,O_r$ be the orbits of $X$ under the action of $\Inn(X)$. Further, we have permutations $f_{i,j} \in \Sigma_{O_i}$, $1 \leq i, j \leq r$ such that
\begin{equation}
a * b =f_{i,j}(a)
\end{equation}
for all $a \in O_i, b \in O_j$. These permutations satisfy the following conditions:
\begin{enumerate}[(i)]
\item Commutativity: $f_{i,j}f_{i,k}=f_{i,k}f_{i,j}$.
\item Transitivity: the $f_{i,j}$, $1 \leq j \leq r$, generate a transitive subgroup $G_i$ of $\Sigma_{O_i}$.
\item Freeness: $a \cdot g = a$ for some $a \in O_i$ and $g \in G_i$ implies $a' \cdot g = a'$ for all $a' \in O_i$.
\end{enumerate}
Indeed, (i) follows from abelianity condition, and (ii) from the definition of orbits and the finiteness of~$X$. For (iii), using transitivity, write $a'=a\cdot h$ for some $h \in G_i$ to get
$$a' \cdot g = (a\cdot h) \cdot g = a\cdot (hg)= a\cdot (gh) = (a\cdot g) \cdot h = a\cdot h = a'.$$

Now, fix an index $i$. All the indices below are considered modulo~$r$. By the freeness, the permutation $f_{i,i+1}$ consists of cycles of the same length; denote this length by $m^{(i)}_1$. Further, take an $a \in O_i$; the permutation $f_{i,i+2}$ will send $a$ to a possibly different $f_{i,i+1}$-cycle, but after $m^{(i)}_2$ iterations will bring it back to the original $f_{i,i+1}$-cycle for the first time. This yields a condition $f_{i,i+2}^{m^{(i)}_2}(a)=f_{i,i+1}^{-m^{(i)}_{2,1}}(a)$ for some $0 \leq m^{(i)}_{2,1} < m^{(i)}_1$. Once again, the freeness yields the relation $f_{i,i+1}^{m^{(i)}_{2,1}} f_{i,i+2}^{m^{(i)}_2}=1$ in $\Sigma_{O_i}$. Similarly, by looking when  $f_{i,i+3}$ brings $a$ back to its original $\left\langle f_{i,i+1},f_{i,i+2}\right\rangle$-orbit (where we are considering the subgroup of $\Sigma_{O_i}$ generated by $f_{i,i+1}$ and $f_{i,i+2}$), one finds a relation $f_{i,i+1}^{m^{(i)}_{3,1}} f_{i,i+2}^{m^{(i)}_{3,2}} f_{i,i+3}^{m^{(i)}_3}=1$ in $\Sigma_{O_i}$, with $0 \leq m^{(i)}_{3,1} < m^{(i)}_1$ and $0 \leq m^{(i)}_{3,2} < m^{(i)}_2$.
\para 
Iterating this argument, we obtain a parameter collection $M^{(i)}$ of the form~\eqref{parameter matrix}, and a transitive action of the group $G(M^{(i)})$ on $O_i$.	To be precise, the generator $x^{(i)}_k$ of $G(M^{(i)})$ act by $f_{i,i+k}$. If the action is not free, then we have a relation $f_{i,i+1}^{m'_{k,1}}f_{i,i+2}^{m'_{k,2}}\cdots  f_{i,i+k-1}^{m'_{k,k-1}}f_{i,i+k}^{m'_k}=1$ in $\Sigma_{O_i}$, with $1 \leq k \leq r-1$, and $0<m'_k<m^{(i)}_k$. But this contradicts the minimality in the choice of $m^{(i)}_k$. Hence, the action must be free. 
\para
Now, choosing an $a_i \in \Sigma_{O_i}$ for each $i$, we get the bijections
$$ G(M^{(i)}) \longleftrightarrow O_i$$
given by
$$(x_1^{(i)})^{n_1}(x_2^{(i)})^{n_2}\ldots (x^{(i)}_{r-1})^{n_{r-1}} \longleftrightarrow f_{i,i+1}^{n_1}f_{i,i+2}^{n_2}\ldots f_{i,i+r-1}^{n_{r-1}}(a_i).$$
Since the action of~$f_{i,i+k}$ on~$O_i$ corresponds to multiplying by $x^{(i)}_k$ in $G(M^{(i)})$, we obtain a quandle isomorphism $Q(M^{(1)}, \ldots, M^{(r)}) \cong X$.

Finally, by the freeness of the $G_i$-action on~$O_i$, the parameter collection $M^{(i)}$ is independent of the choice of the orbit representative~$a_i$, and hence is uniquely determined by the isomorphism class of $X$, where we require isomorphisms to preserve a chosen order of orbits. $\blacksquare$
\end{proof}

\begin{remark}
{\rm To avoid ambiguity, we consider finite quandles with ordered orbits. The parameters $M^{(1)}, \ldots, M^{(r)}$  uniquely determine finite abelian quandles up to a reordering of orbits, that is, up to the natural action of the symmetric group $\Sigma_r$. }
\end{remark}
\para


\begin{definition}
Let $X \cong Q(M^{(1)}, \ldots, M^{(r)})$ be a finite abelian quandle with parameters $M^{(1)}, \ldots, M^{(r)}$. Then the group
\begin{equation}
G'(X)= {\prod_{i=1}^r G(M^{(i)})}/ {\left\langle x^{(i)}_{j-i}x^{(j)}_{i-j} \,,\, 1\leq i < j \leq r \right\rangle}
\end{equation}
is called the parameter group of $X$.
\end{definition}

For example, for $r=2$, we have
\begin{eqnarray*}
G' (X) &=& {G(M^{(1)})\times G(M^{(2)})}/{\left\langle x^{(1)}_{1}x^{(2)}_{1} \right\rangle} \\
&\cong&  \left\langle x^{(1)}_{1},x^{(2)}_{1} \,\mid\, (x^{(1)}_{1})^{m^{(1)}_1}, \, (x^{(2)}_{1})^{m^{(2)}_1}, \, x^{(1)}_{1}x^{(2)}_{1} \right\rangle\\
&\cong&  \mathbb{Z}_{\gcd(m^{(1)}_1,m^{(2)}_1)}.
\end{eqnarray*}

Next, we have the following result \cite[Theorem 3.2]{MR4116819}.

\begin{theorem}  \label{ajoint central parameter}
Let $X$ be a finite abelian quandle with $r$ orbits. Then the following assertions hold:
\begin{enumerate}
\item $\Adj(X)$ is a central extension of $\mathbb{Z}^r$ by its parameter group $G'(X)$.
\item $G'(X)$ is a finite abelian group, and is isomorphic to the commutator subgroup of $\Adj(X)$.
\end{enumerate}
\end{theorem}

\begin{proof}
Recall that
$$\Adj(X) = \big\langle \textswab{a}_a, \, a \in X \,\mid\, \textswab{a}_b \textswab{a}_a \textswab{a}_b^{-1} =  \textswab{a}_{a* b} ~~ \textrm{for all}~~  a,b \in X \big\rangle.$$
By Theorem~\ref{abelian filtered per module}, we can assume that $X \cong Q(M^{(1)}, \ldots, M^{(r)})$. The defining relations of $\Adj(X)$ are
\begin{equation}\label{adjoint defining parameter}
\textswab{a}_b \textswab{a}_a = \textswab{a}_{ax_{j-i}} \textswab{a}_b 
\end{equation} 
for $a \in G(M^{(i)})$ and $b \in G(M^{(j)})$. As usual, the index $(j-i)$ is taken modulo $r$. We omit the indexing ${}^{(i)}$ when the context is clear.
\para

Let $G_i$ denote the subgroup of $\Adj(X)$ generated by $\{\textswab{a}_a \, \mid \,a \in G(M^{(i)}) \}$. Since $x^{(i)}_0=1$, it is abelian. Further, we can rewrite \eqref{adjoint defining parameter} as
\begin{equation}\label{adjoint defining parameter3}
\textswab{a}_b \textswab{a}_a \textswab{a}_b^{-1} \textswab{a}_a^{-1} = \textswab{a}_{ax_{j-i}} \textswab{a}_a^{-1} \in G_i.
\end{equation}
In particular, this expression is independent of~$b$. Interchanging the roles of $a$ and $b$ gives
$$\textswab{a}_a \textswab{a}_b \textswab{a}_a^{-1} \textswab{a}_b^{-1}= \textswab{a}_{bx_{i-j}} \textswab{a}_b^{-1}  \in G_j,$$
which is independent of~$a$, and is the inverse of the preceding expression. Denoting both sides of~\eqref{adjoint defining parameter3} by $g_{i,j}$, we  obtain elements $g_{i,j} \in G_i \cap G_j$, which allow us to break the relations \eqref{adjoint defining parameter3} into two parts, namely,
\begin{eqnarray}
\textswab{a}_b \textswab{a}_a  &=& g_{i,j} \textswab{a}_a \textswab{a}_b  \; \text{ for } a \in G(M^{(i)}) \text{ and } b\in G(M^{(j)}),\label{adjoint defining parameter2}\\
\textswab{a}_{ax_{j-i}} &=& g_{i,j} \textswab{a}_a \; \text{ for } a \in G(M^{(i)}).\label{adjoint defining parameter4}
\end{eqnarray} 
Moreover, $g_{i,j}$ satisfy the conditions
\begin{eqnarray}
g_{i,j}g_{j,i} &=& 1 \; \text{ for } 1 \leq i < j \leq r,\label{equation of gij}\\
g_{i,i}&=& 1 \; \text{ for } 1 \leq i \leq r.\label{equation of gij2}
\end{eqnarray}

We claim that
\begin{equation}\label{equation of gij3}
g_{i,j} \text{ lies in the center of } \Adj(X) ~\text{for all}~1 \leq i, j \leq r.
\end{equation}
Indeed, $g_{i,j} $ can be written as $\textswab{a}_{a'} \textswab{a}_a^{-1}$, with $a$ and $a'$ from the same orbit $G(M^{(i)})$. Taking $b \in G(M^{(j)})$, we see that 

\begin{equation}\label{E:Compute}
\textswab{a}_b \textswab{a}_{a'} {\textswab{a}_a}^{-1}=\textswab{a}_{a'} \textswab{a}_b g_{i,j} {\textswab{a}_a}^{-1}= \textswab{a}_{a'} \textswab{a}_b {\textswab{a}_a}^{-1}g_{i,j}  =\textswab{a}_{a'} {\textswab{a}_a}^{-1} \textswab{a}_b g_{j,i} g_{i,j}=\textswab{a}_{a'} {\textswab{a}_a}^{-1} \textswab{a}_b,
\end{equation}
since $g_{i,j}$ commutes with $G_i$. For each $1 \le i \le r$, set $h_i:=\textswab{a}_{1^{(i)}} \in G_i$. It follows from \eqref{adjoint defining parameter4} that the set 
$$ \big\{g_{i,j} \, \mid \,  1 \le i,j \le r \big\} \cup \big\{h_i \,  \mid  \,  1 \le i \le r \big\}$$
generates $\Adj(X)$. Indeed, we can put
$$g_{(x_1^{(i)})^{n_1}(x_2^{(i)})^{n_2}\ldots (x^{(i)}_{r-1})^{n_{r-1}}} = g_{i,i+1}^{n_1}g_{i,i+2}^{n_2}\ldots g_{i,i+r-1}^{n_{r-1}}h_i.$$
This is well-defined if and only if
\begin{equation} \label{equation of gij4}
 g_{i,i+1}^{m^{(i)}_{j,1}}g_{i,i+2}^{m^{(i)}_{j,2}}\ldots g_{i,i+j}^{m^{(i)}_{j,j}}=1
\end{equation}
for $1 \leq i \leq r$ and  $1 \leq  j < r$.  If we assume these conditions, then the relations~\eqref{adjoint defining parameter4} become redundant. Finally, since each $g_{i,j}$ is central, it is  sufficient to check relations~\eqref{adjoint defining parameter2} for the generators $h_i$ only, that is,
\begin{equation} \label{equation of gij5}
h_j h_i  = g_{i,j}  h_i h_j.  
\end{equation}
This gives a new presentation of the adjoint group as
\begin{equation}\label{new adjoint grp present}
\Adj(X) \cong \Big\langle g_{i,j}, \, 1 \leq i,j \leq r \, ; \, h_i, \, 1 \leq i \leq r \;\mid\; \eqref{equation of gij}, \eqref{equation of gij2}, \eqref{equation of gij3}, \eqref{equation of gij4}, \eqref{equation of gij5} \Big\rangle.
\end{equation}

It follows from the presentation~\eqref{new adjoint grp present} that the commutator subgroup $[\Adj(X), \Adj(X)]$ of ~$\Adj(X)$ is generated by $\{ g_{i,j} \mid 1 \le i, j \le r \}$. It is well-known that the abelianisation of~$\Adj(X)$ is $\mathbb{Z}^r$, and hence we obtain the short exact sequence
$$0 \to [\Adj(X), \Adj(X)] \to \Adj(X) \to \mathbb{Z}^r \to 0$$
of groups. Since each $g_{i,j}$ is central in~$\Adj(X)$, it follows that $\Adj(X)$ is a central extension of $\mathbb{Z}^r$ by $[\Adj(X), \Adj(X)]$. 
\para 
It remains to prove that $G'(X) \cong [\Adj(X), \Adj(X)]$. Relations \eqref{equation of gij}, \eqref{equation of gij2} and \eqref{equation of gij4} give a surjective  homomorphism  $$\psi : G'(X)\to [\Adj(X), \Adj(X)]$$ defined by $\psi(x^{(i)}_j) =  g_{i,i+j}$. For injectivity, we construct a set-theoretic map $\pi : \Adj(X) \to G'(X)$ whose restriction to $[\Adj(X), \Adj(X)]$ is the inverse of $\psi$. Take an element $g \in \Adj(X)$ written in terms of the generators $g_{i,j}$ and $h_i$. Move all the occurrences of $h_1^{\pm 1}$ to the left using the centrality of the $g_{i,j}$ and the twisted commutativity~\eqref{equation of gij5} of the $h_i$. Similarly, move all the occurrences of $h_2^{\pm 1}$ right after the $h_1^{\pm 1}$, and so on. Using the trivial relations $h_i h_i^{-1}= h_i^{-1} h_i = 1$, we obtain a word of the form $h_1^{k_1}\ldots h_r^{k_r}g''$, where $k_1,\ldots,k_r \in \mathbb{Z}$ and $g''$ is a product of the $g_{i,j}^{\pm 1}$. Next, in $g''$ replace each generator $g_{i,j}$ by $x^{(i)}_{j-i}$ and denote by $g'$ the word obtained. Considering it as an element of~$G'(X)$, we set $\pi(g)=g'$. The map is well-defined, since relations \eqref{equation of gij}, \eqref{equation of gij2}, \eqref{equation of gij4} and $g_{i,j}^{\pm 1}g_{i,j}^{\mp 1}=1$ have counterparts in~$G'(X)$. Further, the relation~\eqref{equation of gij3} does not change the result by construction. Similarly, the relations \eqref{equation of gij5} and $h_i^{\pm 1}h_i^{\mp 1}=1$ do not change the result as shown by a computation similar to~\eqref{E:Compute} together with~\eqref{equation of gij}. Consider the restriction $$\varphi: [\Adj(X), \Adj(X)] \to G'(X)$$
of $\pi$ to $[\Adj(X), \Adj(X)]$. It simply replaces each $g_{i,j}$ by $x^{(i)}_{j-i}$ in any representative of an element of~$[\Adj(X), \Adj(X)]$, and hence is the desired inverse of~$\psi$. Finally, since the groups $G(M^{(i)})$ are finite abelian groups, it follows that $G'(X)$ is a finite abelian group.  $\blacksquare$
\end{proof}

\begin{definition}
Let $X$ be a finite abelian quandle with parameters $M^{(1)}, \ldots, M^{(r)}$. The parameter matrix $\mathcal{M}(X)$ of $X$ is defined as follows: Its columns are indexed by tuples $(i,j)$ with $1 \leq i < j \leq r$. Its rows are indexed by tuples $(i,j)$ with $1 \leq i \leq r$ and $1 \leq j < r$. All tuples are ordered lexicographically here. The row $(i,j)$ corresponds to the $j$-th row of $M^{(i)}$; for all $1 \le k \le \min \{j, r-i\}$, it contains $m^{(i)}_{j,k}$ in the column $(i,i+k)$, and for all $r-i < k \leq j$, it contains $-m^{(i)}_{j,k}$ in the column $(i+k-r,i)$. 
\end{definition}

Let us see two special cases. For $r=2$, $M^{(1)} = \begin{psmallmatrix} m^{(1)}_1 \end{psmallmatrix}$ and $M^{(2)} = \begin{psmallmatrix} m^{(2)}_1 \end{psmallmatrix}$, we have
$$\mathcal{M}(X)=\begin{psmallmatrix}
m^{(1)}_1 \\ -m^{(2)}_1
\end{psmallmatrix}.$$

For $r=3$, there are three columns $(1,2)$, $(1,3)$, $(2,3)$, and 
$$\mathcal{M}(X)=\begin{psmallmatrix}
m^{(1)}_1 & 0 & 0\\
m^{(1)}_{2,1} & m^{(1)}_{2} & 0\\ 
0 & 0 & m^{(2)}_1\\
-m^{(2)}_{2} & 0 & m^{(2)}_{2,1}\\
0 & -m^{(3)}_1 & 0\\
0 & -m^{(3)}_{2,1} & -m^{(3)}_{2}\\
\end{psmallmatrix}.$$

The following result classifies finite quandles with abelian adjoint groups \cite[Theorem 4.2]{MR4116819}.

\begin{theorem}\label{classify quandle abelian adjoint}  
Let $X$ be a finite quandle. Then the following statements are equivalent:
\begin{enumerate}
\item $\Adj(X)$ is abelian.
\item $X$ is abelian and its parameter group $G'(X)$ is trivial.
\item $X$ is abelian and the maximal minors of its parameter matrix $\mathcal{M}(X)$ are globally coprime.
\end{enumerate}
\end{theorem}

\begin{proof}
There is a natural  left-action of $\Adj(X)$ on~$X$ given by $\textswab{a}_b \cdot a =a * b$ for $a, b \in X$. If $\Adj(X)$ is abelian, then
$$(a * b) * c = \textswab{a}_c \cdot (\textswab{a}_b \cdot a) = (\textswab{a}_c \textswab{a}_b) \cdot a = (\textswab{a}_b \textswab{a}_c) \cdot a=\textswab{a}_b \cdot  (\textswab{a}_c  \cdot a)= (a * c) * b.$$
Hence, if $\Adj(X)$ is abelian, then $X$ is abelian. Thus, we only need to understand which finite abelian quandles have abelian adjoint groups. By Theorem~\ref{ajoint central parameter}, this happens if and only the parameter group $G'(X)$ is trivial. Furthermore, if $G'(X)$ is trivial, then $\Adj(X) \cong \mathbb{Z}^r$. And, if $\Adj(X)$ is abelian, then by Theorem \ref{thm Lebed Vendramin}, it is free abelian. Hence, the only possibility for its finite subgroup~$G'(X)$ is that it must be trivial. Thus, we have proved the equivalence of (1) and (2).
\para
Assume that $X$ is abelian and has parameters $M^{(1)}, \ldots, M^{(r)}$. The group~$G'(X)$ admits as generators the elements $x^{(i)}_{j}$ for $i+j \leq r$, since for $i+j > r$ one has $x^{(i)}_{j}=(x^{(j+i-r)}_{r-j})^{-1}$. With these $n:=\frac{r(r-1)}{2}$ generators, $G'(X)$ is isomorphic to the quotient of $\mathbb{Z}^n$ by the row space of the matrix $\mathcal{M}(X)$. Indeed, the rows of~$\mathcal{M}$ encode the defining relations of the components $G(M^{(i)})$ of~$\Adj(X)$, taking into account the identification $x^{(i)}_{j}=(x^{(j+i-r)}_{r-j})^{-1}$. We claim that triviality of $G'(X)$ is equivalent to the maximal minors of $\mathcal{M}(X)$ being globally coprime. To see this, note that for a given finitely generated abelian group, both its isomorphism class and the greatest common divisor of the maximal minors of its presentation matrix as above are invariant under elementary row and column operations. Further, for a matrix in Smith normal form, the triviality of the group and the minors condition are both equivalent to the matrix being of maximal rank with all diagonal entries equal to $1$. This establishes the equivalence of (2) and (3). 
$\blacksquare$
\end{proof}

For $r=2$, the coprimality condition in Theorem \ref{classify quandle abelian adjoint} becomes $\gcd \big(m^{(1)}_1,~m^{(2)}_1 \big)=1$, and recovers the main result of Bardakov and Nasybullov \cite{MR4129183}. The next result provides a large supply of quandles satisfying the conditions of the preceding theorem  \cite[Proposition 4.3]{MR4116819}.

\begin{proposition} 
Let $X$ be a finite abelian quandle with parameters $M^{(1)}, \ldots, M^{(r)}$ such that $m^{(i)}_{j,k}$ vanish whenever $k<j$. Then the following conditions are equivalent:
\begin{enumerate}
\item  $\Adj(X) \cong \mathbb{Z}^r$.
\item $\gcd \big(m^{(i)}_{j},~m^{(j+i-r)}_{r-j} \big)=1$ whenever $i+j>r$.
\end{enumerate}
\end{proposition}

\begin{proof}
We check the triviality of the abelian group $G'(X)$ and use the equivalence (1) $\Longleftrightarrow$ (2) of Theorem~\ref{classify quandle abelian adjoint}. In our situation, $G'(X)$ has the presentation
$$G'(X) \cong \Big\langle \, x^{(i)}_j \,\mid\, \left( x^{(i)}_j\right)^{m^{(i)}_{j}} =1,\, \, x^{(l)}_{k-l}x^{(k)}_{l-k} =1 \, \Big\rangle,$$
where $1\leq i \leq r$, $1\leq j < r$ and $1\leq l < k \leq r$. The last condition means that the generators $x^{(l)}_{k-l}$ and $x^{(k)}_{l-k}$ are mutually inverses. The above presentation can be rewritten as
$$G'(X) \cong \Big\langle \, x^{(i)}_j, \, i+j>r \,\mid \, \left( x^{(i)}_j\right)^{\gcd (m^{(i)}_{j},m^{(j+i-r)}_{r-j})} =1~~\textrm{for}~ i+j>r \, \Big\rangle,$$
where $1\leq i \leq r$ and $1\leq j < r$. But this is the direct product of cyclic groups of orders $\gcd \big(m^{(i)}_{j},~m^{(j+i-r)}_{r-j} \big)$, where $1\leq i \leq r$, $1\leq j < r$ and $ i+j>r$, and the proof is complete. $\blacksquare$
\end{proof}

\begin{remark}
{\rm
The quandles from the preceding proposition have $r(r-1)$ non-zero parameters $m^{(i)}_{j}$, and condition (2) divides them into $\frac{r(r-1)}{2}$ coprime pairs. Thus, one obtains, for each~$r,$ an infinite family of quandles with adjoint group $\mathbb{Z}^r$.
}
\end{remark}
\bigskip
