\chapter{Automorphisms of quandles}\label{chapter-auto-quandles}

\begin{quote}
A comprehensive understanding of automorphisms of algebraic structures is crucial for their systematic classification. In this chapter, we explore automorphisms of Takasaki quandles and conjugation quandles of groups. Additionally, we study automorphisms of quandle extensions, as well as the subgroup of quasi-inner automorphisms of these structures. As we progress, we will also touch upon topics such as connectivity and commutativity in Alexander quandles, and the multi-transitive actions of these automorphisms groups.
\end{quote}
\bigskip



\section{Automorphisms of Takasaki quandles}\label{section4}

Automorphisms play a crucial role in the structure theory of quandles. We begin by making some basic observations about automorphisms of quandles. 
\para
It is readily apparent that the set of all inner automorphisms of a group is a group. But, this is not the case for quandles. The following example shows, in general, that the group $\Inn(X)$ is bigger than the set $\{ S_x \, \mid \, x \in X \}$ of all symmetries.

\begin{example}{\rm 
Consider the dihedral quandle $\R_3 = \{ 0, 1, 2 \}$, where $i * j = 2j-i \mod 3$. Then the set of symmetries  contains only three elements, but $\Inn(\R_3)=\Aut(\R_3) \cong \Sigma_3$, the permutation group on three symbols.}
\end{example}

The following example shows that, in general, $\Aut(X) \neq \Inn(X)$.

\begin{example}{\rm 
Let $G = \{ \pm 1, \pm i, \pm j, \pm k \}$ be the quaternion group of order 8 and $\Conj(G)$ its conjugation quandle.
Let $X$ be the subquandle of $\Conj(G)$ consisting of conjugacy classes of elements from the set $\{\pm i, \pm j \}$. Then we see that $\Inn(X) = \langle S_i, S_j \rangle \cong \mathbb{Z}_2 \times  \mathbb{Z}_2$ and $\Aut(X) = \langle S_i, S_j, \varphi \rangle$ has order 8, where $\varphi(\pm i) = \pm j$ and $\varphi(\pm j) = \pm i$.}
\end{example}

First, we present the following slightly more general result \cite[Proposition 4.1]{MR3718201}.

\begin{proposition}\label{joyce-embedding}
Let $G$ be a group and $\varphi \in \Aut(G)$. Then there is an embedding $\Z(G) \rtimes \C_{\Aut(G)}(\varphi)  \hookrightarrow \Aut\big(\Alex(G, \varphi)\big)$, where $\C_{\Aut(G)}(\varphi)$ is the centraliser of $\varphi$ in $\Aut(G)$ and $\Z(G)$ is the center of $G$.
\end{proposition}

\begin{proof}
Let $f \in \C_{\Aut(G)}(\varphi)$. Then for $a, b \in G$, we see that
\begin{eqnarray*}
f(a*b) &=& f\big( \varphi(a)\varphi(b)^{-1}b\big)\\
& = & f\big(\varphi(a)\big) f\big(\varphi(b)\big)^{-1}f(b)\\
& = & \varphi\big(f(a)\big) \varphi\big(f(b)\big)^{-1}f(b)\\
& = & f(a)*f(b).
\end{eqnarray*}
 Hence, we have $\C_{\Aut(G)}(\varphi) \leq  \Aut\big(\Alex(G, \varphi)\big)$.
\para 
Now, for $a \in \Z(G)$, let $t_a: G \to G$ be given by $t_a(b)=ba$ for all $b \in G$. Then $t_a \in \Aut\big(\Alex(G, \varphi)\big)$ and the map $a \mapsto t_a$ gives an embedding $\Z(G) \hookrightarrow \Aut\big(\Alex(G, \varphi)\big)$.

Finally, we show that the map $\Phi:\Z(G) \rtimes \C_{\Aut(G)}(\varphi) \to \Aut\big(\Alex(G, \varphi)\big)$ given by $\Phi(a,f) = t_a  f$ is an embedding. The map is clearly injective. Further, for $(a_1,f_1), (a_2, f_2) \in  \Z(G) \rtimes \C_{\Aut(G)}(\varphi)$, we have
\begin{eqnarray*}
\Phi\big((a_1,f_1)(a_2, f_2) \big) & = & \Phi\big((a_1 f_1(a_2), f_1  f_2) \big)\\
& = & t_{a_1 f_1(a_2)}  (f_1  f_2)\\
& = & (t_{a_1}  f_1)  (t_{a_2}  f_2)\\
& = & \Phi\big((a_1,f_1)\big)  \Phi\big((a_2, f_2) \big).
\end{eqnarray*}
This completes the proof of the proposition. $\blacksquare$
\end{proof}

We now take $G$ to be an additive abelian group and $\varphi=-\id_G$. In this case $\Alex(G, \varphi)=\T(G)$ and  $\C_{\Aut(G)}(\varphi)= \Aut(G)$. The following result gives a complete description of the  automorphism and the inner automorphism groups of some Takasaki quandles \cite[Theorem 4.2]{MR3718201}. 

\begin{theorem}\label{main-theorem}
Let $G$ be an additive abelian group without 2-torsion. Then the following  assertions hold:
\begin{enumerate}
\item $\Aut\big(\T(G)\big) \cong G \rtimes \Aut(G)$.
\item $\Inn\big(\T(G)\big) \cong 2G \rtimes \mathbb{Z}_2$.
\end{enumerate}
\end{theorem}

\begin{proof}
We already proved in Proposition \ref{joyce-embedding} that there is an embedding $\Phi:G \rtimes \Aut(G)  \hookrightarrow \Aut\big(\T(G)\big)$.  Let $f \in \Aut\big(\T(G)\big)$. Then $f(a*b)=f(a)* f(b)$ implies that $f(2b-a)=2f(b)-f(a)$ for all $a, b \in \T(G)$. Taking $a=2b$, we have  $$f(2b)=2f(b)-f(0)$$ for all $b \in G$, where $0$ is the identity element  of the group $G$.
\para
Define $h: G \to G$ by $h(a)=f(a)-f(0)$ for $a \in G$. We claim that $h \in \Aut(G)$. Since $f$ is a bijection, it follows that $h$ is also a bijection.  To show that $h$ is a group homomorphism, it suffices to show that $f(a+b)=f(a)+f(b)-f(0)$ for all $a, b \in G$. We can write
$$f(a+b)=f\big(2a-(a-b)\big)=2f(a)-f(a-b)$$
and
$$f(a+b)=f\big(2b-(b-a)\big)=2f(b)-f(b-a).$$
 Adding the two identities yields $2 f(a+b)= 2f(a)+ 2f(b)-f(a-b)-f(b-a)$. But, $f(a-b)=f\big(0-(b-a)\big)= 2f(0)-f(b-a)$. This gives $2 f(a+b)= 2f(a)+ 2f(b)- 2 f(0)$. Since $G$ has no 2-torsion, our claim follows. By definition of $h$, we can write $f=t_{f(0)}  h \in \Phi \big(G \rtimes \Aut(G) \big)$, and the proof of assertion (1) is complete.
\para
Let $r \in \Aut(G)$ be the automorphism given by $r(a) = -a$ for all $a \in G$. Then $\langle r \rangle \cong \mathbb{Z}_2$. Note that $\Phi(2a, r) = t_{2a}  r=S_a$, and hence $\Phi$ embeds $2G \rtimes \mathbb{Z}_2$ into $\Inn\big(\T(G)\big)$. Conversely, any $S_a \in \Inn\big(\T(G)\big)$ can be written as $S_a= t_{2a}  r$, and the proof of assertion (2) is complete.  $\blacksquare$
\end{proof}


As an immediate consequence, we obtain the following result.

\begin{corollary}
$\Aut\big( \T(\mathbb{Z}^n)\big) \cong \mathbb{Z}^n \rtimes \GL(n, \mathbb{Z})$ and  $\Inn\big( \T(\mathbb{Z}^n)\big) \cong (2\mathbb{Z})^n \rtimes \mathbb{Z}_2$ for all $n \geq 1$.
\end{corollary}


\begin{remark}{\rm 
In \cite[Proposition 2.1]{MR2831947}, Hou proved a general result  analogous to Theorem \ref{main-theorem} for Alexander quandle of a group $G$ under the condition that $G= \{\varphi(a)^{-1}a \, \mid \, a \in G \}$. Note that this set is precisely the \index{twisted conjugacy class} {\it $\varphi$-twisted conjugacy class} of the identity element of $G$ and is of independent interest. For instance, see \cite{MR3089322} for some related results. When $G$ is a finite group, this condition is equivalent to the automorphism $\varphi$ being fixed-point free. In particular, when $G$ is a  finite additive abelian group and $\varphi = -\id_G$, then this condition is equivalent to $G$ being without 2-torsion. However, when $G$ is infinite, then the two conditions are different. For example, $G=\mathbb{Q}/\mathbb{Z}$ satisfy $G=2G$, but has 2-torsion. On the other hand, $G=\mathbb{Z}$ is without 2-torsion, but $G \neq 2G$. Thus, Theorem \ref{main-theorem}, though restricted to Takasaki quandles of abelian groups, can be considered as complementary to that of Hou's result. Later, in Theorem \ref{fixed-point-free-theorem}, we prove a stronger version of Theorem \ref{main-theorem} for finite abelian groups.}
\end{remark}


The following result provides a complete characterization of the automorphism and the inner automorphism groups of dihedral quandles \cite[Theorems 2.1 and 2.2]{MR2900878}. Observe that when $n$ is odd, the result also follows from Theorem \ref{main-theorem}.

\begin{theorem}\label{Aut}
Let $\R_n$ be the dihedral quandle of order $n$. Then the following assertions hold:
\begin{enumerate}
\item $\Aut(\R_n) \cong \mathbb{Z}_n \rtimes \mathbb{Z}_n^\times$, where $\mathbb{Z}_n^\times$ is the group of units of $\mathbb{Z}_n$ when viewed as a ring.
\item   $\Inn(\R_n) \cong D_m$, the dihedral group of order $m$, where $m$ is the least common multiple of $n$ and $2$.
\end{enumerate}
\end{theorem}

\begin{proof}
Note that $\R_n= \T(\mathbb{Z}_n)$, where $\mathbb{Z}_n$ is the cyclic group of order $n$. By Proposition \ref{joyce-embedding}, there is an embedding $\mathbb{Z}_n \rtimes \Aut(\mathbb{Z}_n)\hookrightarrow \Aut(\R_n)$. Conversely, suppose that  $f \in \Aut(\R_n)$. Define $g:\R_n \rightarrow \R_n$ by $g(i)=f(i)-f(0)$. Since $f$ is a bijection, it follows that $g$ is also a bijection. Since $f(2j-i)=2f(j)-f(i)$ for all $i, j \in \R_n$, 
it follows that 
\begin{equation}\label{formula for g}
g(2j-i)= f(2j-i)-f(0)= 2f(j)-f(i)-f(0)=2g(j)-g(i).  
\end{equation}
Note that $g(0)=0$. Taking $j=0$ in \eqref{formula for g} gives $g(-i)=-g(i)$ for all $i$. Similarly, taking $i=0$ in \eqref{formula for g} gives $g(2j)=2g(j)$ for all $j$. Iterating the procedure gives $g(kj)= k g(j)$ for all even $k$. For odd multiples, we have  $g \big((2k+1)j \big)=g \big(2kj -(-j) \big)=2g(kj)-g(-j)=2kg(j)+g(j)=(2k+1)g(j)$. Hence, $g \in \Aut(\mathbb{Z}_n)$, and therefore $f=t_{f(0)}\, g$. Since $\Aut(\mathbb{Z}_n)\cong \mathbb{Z}_n^\times$, the proof of assertion (1) is complete.
\para

For $i \in \R_n$,  we have $S_i(j)= 2i-j \mod n$. Further, $S_i$ can be thought of as a reflection of a regular $n$-gon.  If $n$ is odd, the axis of symmetry of $S_i$ connects the vertex $i$ to the mid-point of the side opposite to $i$. If $n=2m$ is even, the axis of symmetry of $S_i$ passes through the opposite vertices $i$ and $(i+m) \mod 2m$. The result now follows from these observations. Observe that, if $n$ is odd, then Theorem \ref{main-theorem}(2) also shows that
$\Inn( \R_n) \cong \mathbb{Z}_n \rtimes \mathbb{Z}_2$, which establishes assertion (2).
$\blacksquare$
\end{proof}

We conclude the section with an embedding result for automorphism groups of core quandles.

\begin{proposition}\label{coreaut}
Let $G$ be a group with center $\Z(G)$. Then there is an embedding $\Z(G)\rtimes\Aut(G) \hookrightarrow \Aut(\Core(G))$.
\end{proposition}

\begin{proof} 
Recall that, in $\Core(G)$, we have $x*y=yx^{-1}y$ for all $x,y\in G$. If $\varphi \in \Aut(G)$, then by functoriality, $\varphi$ can be viewed as an automorphism of $\Core(G)$. Let $H_1=\Aut(G)$ viewed as automorphisms of $\Core(G)$. For an element $a\in \Z(G)$, let $t_a$ denote the bijection of $\Core(G)$ of the form $t_a(x)= ax$, which is clearly an automorphism of $\Core(G)$.  Let $H_2$ denote the subgroup of $\Aut(\Core(G))$ generated by $t_a$ for all $a\in \Z(G)$. Since  $\varphi(1)=1$ for each automorphism $\varphi\in H_1$, it follows that $H_1 \cap H_2= 1$. For $\varphi\in H_1$ and $t_a\in H_2$, we have $\varphi t_a\varphi^{-1}=t_{\varphi(a)}$, and hence $H_2$ is the normal subgroup of the group $H$ generated by $\{H_1, H_2\}$. Thus, $H$ is the semi-direct product $H_2\rtimes H_1$ of $H_2 \cong \Z(G)$ and $H_1 \cong \Aut(G)$.
$\blacksquare$    \end{proof}          
\para


Recall that an automorphism $\varphi$ of a group $G$ is called \index{quasi-inner automorphism} {\it quasi-inner} if for every $g \in G$, there exists $h \in G$ such that $\varphi(g) = h g h^{-1}$. In other words, $\varphi$ is  quasi-inner if for every $g \in G$, there exists an inner automorphism $\iota_h$ of $G$ such that $\varphi(g) = \iota_h(g)$. Every inner automorphism of $G$ is obviously quasi-inner.
\para


In 1913, Burnside posed the question of whether every quasi-inner automorphism of a group must necessarily be inner. He later provided a negative answer in \cite{MR1577234}, presenting an example of a finite group that admits a quasi-inner automorphism which is not inner. In the setting of quandles, this concept leads to two distinct definitions.


\begin{definition}
An automorphism $\varphi$ of a quandle $X$ is called a {\it quasi-inner automorphism in strong sense} if for every $x \in X$ there exists $y\in X$ such that $\varphi(x)=x*y$. Similarly, an automorphism $\varphi$ of a quandle $X$ is called a {\it quasi-inner automorphism in weak sense} if for every $x \in X$ there exists an inner automorphism $S \in \Inn(X)$ such that $\varphi(x)=S(x)$.
\end{definition}

Every quasi-inner automorphism in strong sense is obviously quasi-inner in weak sense. However, in general, the converse is not true since  the group of inner automorphisms $\Inn(X)=\langle S_x \,\mid \, x\in X \rangle$ does not have to coincide with the set $\{ S_x \,\mid \, x \in X \}$. If $X=\Conj(G)$ for some group $G$, then the two definitions of a quasi-inner automorphism are the same. Further, if $G$ is a $2$-step nilpotent group, then the two definitions of a quasi-inner automorphism are the same for the quandles $X=\Conj_n(G)$ for any $n$.
\para

We denote by $\QInn(X)$ the set of all automorphisms of the quandle $X$ that are quasi-inner in the weak sense. It is clear that $\QInn(X)$ forms a subgroup of $\Aut(X)$ and contains $\Inn(X)$ as a subgroup. 

\begin{lemma}\label{qaut}
If $X$ is a connected quandle, then $\Aut(X)=\QInn(X)$.
\end{lemma} 

\begin{proof}
Let $\phi$ be an automorphism of $X$. Since $X$ is connected, for each element $\phi(x) \in X$, there exists an inner automorphism $S$ such that $\phi(x)=S(x)$. Thus, we have $\Aut(X)=\QInn(X)$.
$\blacksquare$    \end{proof}          


If $X$ is a trivial quandle, then  both $\Inn(X)$ and $\QInn(X)$ are trivial. An analogue of \index{Burnside's problem}{Burnside's problem} for quandles is the question of whether there exists a quandle $X$ such that $\Inn(X) \neq \QInn(X)$. Let $G$ be the group constructed by Burnside in \cite{Burnside1913} that admits a non-inner quasi-inner automorphism $\varphi$. Then the automorphism of $\Conj(G)$ induced by $\varphi$ is non-inner quasi-inner in a strong sense. This gives a negative answer to the preceding question. The following result provides an example of a quandle that is not a conjugation quandle and admits a non-inner quasi-inner automorphism.

\begin{proposition}\label{dihburn}
If $n\geq5$ is odd, then $\Inn(\R_n) \neq \QInn(\R_n)$.
\end{proposition}

\begin{proof}
By Theorem \ref{main-theorem}, if $n$ is  odd, then $\Aut( \R_n) \cong \mathbb{Z}_n\rtimes \mathbb{Z}_n^\times$, where $\mathbb{Z}_n^\times$ is the multiplicative group of the ring $\mathbb{Z}_n$. Again, by Theorem~\ref{main-theorem}, if $n$ is odd, then  $\Inn(\R_n) \cong  \mathbb{Z}_n \rtimes \mathbb{Z}_2$. Thus, if $n\ge 5$ is odd, then the groups $\Inn(\R_n)$ and $\Aut( \R_n)$ do not coincide. Since for odd $n$, the quandle $\R_n$ is connected, by Lemma \ref{qaut}, we have $\QInn(\R_n)=\Aut(\R_n)\neq \Inn(Q)$.
$\blacksquare$    \end{proof} 
\bigskip
\bigskip


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%End of section
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%


\section{Automorphisms of conjugation quandles}\label{sec4}
Let $G$ be a group and $\varphi$ an automorphism of $G$. By functoriality, an automorphism of $G$ induces an automorphism of $\Conj_n(G)$ for each $n$, and hence $\Aut(G) \leq \Aut\big(\Conj_n (G)\big)$ for each $n$. The group $\Aut(G)$ is not necessarily normal in  $\Aut\left(\Conj_n (G)\right)$. For example, if $G$ is a cyclic group of prime order $p\geq5$, then the order of $\Aut(G)$ is equal to $(p-1)$. The quandle $\Conj(G)$ is trivial and $\Aut\big(\Conj(G)\big)=\Sigma_p$. The only proper normal subgroup of $\Sigma_p$ for $p\geq5$ is the alternating group $A_p$, which has order $\frac{p!}{2}>p-1$. Thus, $\Aut(G)$ cannot be normal in $\Aut \big(\Conj(G)\big)$.
\para

We shall show that $\Aut(G)=\Aut\big(\Conj(G) \big)$ if and only if $\Z(G)=1$. Throughout the section, $x^y$ means $yxy^{-1}$. First, note that 
$$\Inn \big(\Conj(G)\big) \cong \Inn(G) \cong G/\Z(G)$$ for any group $G$. Our first result is the following \cite[Proposition 4.7]{MR3718201}.

\begin{proposition}\label{aut-conj}
Let $G$ be a group with center $\Z(G)$. Then there is an embedding of groups $\Z(G) \rtimes \Aut(G) \hookrightarrow \Aut\big(\Conj(G)\big)$.
\end{proposition}

\begin{proof}
For each $a \in \Z(G)$, let $t_a: G \to G$ be given by $t_a(b)=ba$ for all $b \in G$. Then $t_a \in \Aut\big(\Conj(G))$ and the map $a \mapsto t_a$ gives an embedding $G \hookrightarrow \Aut\big(\Conj(G)\big)$.  Obviously, $\Aut(G)\subseteq  \Aut\big(\Conj(G)\big)$.
\para
It remains to show that the map $\Phi: \Z(G) \rtimes \Aut(G) \to \Aut\big(\Conj(G)\big)$ given by $\Phi(a,f) = t_a  f$ is an embedding. The map is clearly injective. Further, for $(a_1,f_1), (a_2, f_2) \in  \Z(G) \rtimes \Aut(A)$, we have
\begin{eqnarray*}
\Phi\big((a_1,f_1)(a_2, f_2) \big) & = & \Phi\big((a_1f_1(a_2), f_1  f_2) \big)\\
& = & t_{a_1f_1(a_2)}  (f_1  f_2)\\
& = & (t_{a_1}  f_1)  (t_{a_2}  f_2)\\
& = & \Phi\big((a_1,f_1)\big)  \Phi\big((a_2, f_2) \big).
\end{eqnarray*}
This completes the proof of the proposition.  $\blacksquare$
\end{proof}

It is known that $\Aut\big(\Conj(\Sigma_3)\big) \cong \Inn\big(\Conj(\Sigma_3)\big) \cong \Sigma_3$ \cite{MR2900878}. Also, it is well-known that if $n \ge 3$ and $n \neq 6$, then $\Aut\big(\Sigma_n \big) \cong \Inn\big(\Sigma_n  \big) \cong \Sigma_n$. In view of Proposition \ref{aut-conj} and the preceding discussion, it is a natural problem to classify groups $G$ for which $\Aut\big(\Conj(G)\big) \cong \Z(G) \rtimes \Aut(G)$. 
The main result of this section gives such a classification. First, we present the following result.

\begin{lemma}
Let $G$ be a group, $X=\Conj(G)$ and $\varphi \in \Aut(X)$. Then for $x,y\in X$, there exists an element $z\in \Z(G)$ such that $\varphi(xy)=\varphi(x)\varphi(y)z$.
\end{lemma}

\begin{proof} For $x,y,z\in X$, we have $$\varphi(x^{yz})=\varphi(x*{yz})=\varphi(x)*{\varphi(yz)}=\varphi(x)^{\varphi(yz)}.$$
On the other hand, we have 
\begin{multline*}\varphi(x^{yz})=\varphi \big((x^y)^z \big)=\varphi(x^y*z)=\varphi(x*y)*{\varphi(z)}=\big(\varphi(x)*\varphi(y) \big)*{\varphi(z)}=\varphi(x)^{\varphi(y)\varphi(z)}
\end{multline*}
and $\varphi(x)^{\varphi(yz)}=\varphi(x)^{\varphi(y)\varphi(z)}$. Since $x \in G$ is arbitrary, the element $\varphi(yz) \big(\varphi(y)\varphi(z)\big)^{-1}$ lie in $\Z(G)$.
$\blacksquare$    \end{proof}          

As an immediate consequence, we have the following result.

\begin{corollary}\label{aut conj trivial center}
If $G$ is a group with trivial center, then $\Aut(G)=\Aut \big(\Conj(G)\big)$.
\end{corollary}

Next, we prove the following \cite[Proposition 5]{MR3948284}.

\begin{proposition}\label{left}
If $G$ is a group with non-trivial center, then $\Aut(G)\neq \Aut \big(\Conj (G)\big)$.
\end{proposition}

\begin{proof}
Let $x\in \Z(G)$ be a non-trivial element. Let $\varphi$ denote the bijection of $X=\Conj(G)$ such that  $\varphi(1)=x$, $\varphi(x)=1$ and it 
fixes all other elements of $X$. We claim that $\varphi\in \Aut(X)$. Let $y,z \in X$. If $y\in\{1,x\}$, then $\varphi(y)\in\Z(G)$, and hence
$\varphi(y*z)=\varphi(y^z)=\varphi(y)=\varphi(y)*{\varphi(z)}$. If $y\notin\{1,x\}$, then $y^z\notin\{1,x\}$, and hence  $\varphi(y*z)=\varphi(y^z)=y^z=\varphi(y)^{\varphi(z)}=\varphi(y)*\varphi(z)$. This shows that $\varphi$ is an automorphism of $X$. Since $\varphi(1)\neq1$, the map $\varphi$ does not belong to $\Aut (G)$, and hence $\Aut(G)\neq \Aut \big(\Conj (G)\big)$.
$\blacksquare$    \end{proof}          

\begin{corollary}\label{equal}
Let $G$ be a group. Then $\Aut(G)=\Aut \big(\Conj (G)\big)$ if and only if $\Z(G)=1$.
\end{corollary}

By Proposition \ref{aut-conj},  for each group $G$, there is an embedding $\Z(G)\rtimes \Aut(G)\hookrightarrow \Aut\big(\Conj (G)\big)$. The following result shows that if $G$ is a non-abelian group, then $\Aut (G) \times  \Sigma_{\Z(G)}$ also embeds in $\Aut\big(\Conj (G)\big)$ \cite[Proposition 6]{MR3948284}.

\begin{proposition}\label{direct aut conj}
Let $G$ be a non-abelian group. Then the direct product $\Aut (G) \times  \Sigma_{\Z(G)}$ embeds in $\Aut \big(\Conj(G) \big)$.
\end{proposition}

\begin{proof} 
Consider the map $f:\Aut(G)\to\Aut \big(\Conj(G) \big)$ which sends an automorphism $\varphi \in \Aut(G)$ to the map $f(\varphi):\Conj (G) \to  \Conj(G)$, defined as
$$f(\varphi)(x)=\begin{cases}
\varphi(x)&~\textrm{if}~ x\notin \Z(G),\\
x& ~\textrm{if}~x\in \Z(G).
\end{cases}$$
Since $\varphi\in \Aut (G)$, it maps $\Z(G)$ to $\Z(G)$ and maps $G\setminus \Z(G)$ to $G\setminus \Z(G)$. Hence, $f(\varphi)$ is a bijection on $\Conj (G)$. A direct check shows that $f(\varphi)$ preserves the quandle operation in $\Conj (G)$, and hence  $f(\varphi) \in \Aut \big(\Conj (G)\big)$.
\para 
For automorphisms $\varphi,\psi\in \Aut(G)$ and an element $x\in \Z(G)$, we have $f(\varphi\psi)(x)=x=f(\varphi)f(\psi)(x)$. If $x\notin \Z(G)$, then $\psi(x)\notin \Z(G)$, and hence $f(\varphi\psi)(x)=\varphi \big(\psi(x)\big)=f (\varphi) \big(f(\psi)(x)\big)=f(\varphi)f(\psi)(x)$. Thus, $f$ is a group homomorphism. If $f(\varphi)=f(\psi)$, then for all $x\notin \Z(G)$, we have $\varphi(x)=f(\varphi)(x)=f(\psi)(x)=\psi(x)$. In particular, if $x \in G\setminus \Z(G)$ and $y\in \Z(G)$, then $\varphi(x)=\psi(x)$ and $\varphi(xy)=\psi(xy)$. This gives $\varphi(y)=\psi(y)$, and hence $\varphi=\psi$. Hence, $f: \Aut(G) \to \Aut \big(\Conj(G)\big)$ is injective.
\para
Consider the map $g:\Sigma_{\Z(G)}\to \Aut \big(\Conj(G) \big)$ which sends a permutation $\sigma$ of $\Z(G)$ to the map $g(\sigma): \Conj (G) \to  \Conj(G)$, defined as
$$g(\sigma)(x)=\begin{cases}
x&~\textrm{if}~   x\notin \Z(G),\\
\sigma(x)&~\textrm{if}~ x\in \Z(G).
\end{cases}$$
As in the case of $f$, it is straightforward to verify that $g:\Sigma_{\Z(G)} \to \Aut \big(\Conj (G) \big)$ is an injective group homomorphism. Let $H$ be a subgroup of $\Aut \big(\Conj(G)\big)$ generated by $H_1=f \big(\Aut(G) \big)$ and $H_2=g( \Sigma_{\Z(G)})$. Both $H_1,H_2$ are normal subgroups of $H$ (moreover, $H_2$ is normal in $\Aut \big(\Conj(G)\big)$) and $H_1\cap H_2= 1$. Hence, we have $H=H_1\times H_2 \cong \Aut(G)\times \Sigma_{\Z(G)}$.
$\blacksquare$    \end{proof}          

\begin{corollary} 
Let $G$ be a group. Then $\Z(G)$ embeds in $\Aut \big(\Conj (G)\big)$.
\end{corollary}

\begin{proof} 
Since $\Z(G)$ acts faithfully on itself by right multiplications, it follows that $\Z(G)$ is a subgroup of $\Sigma_{\Z(G)}$. If $G$ is abelian, then $\Conj(G)$ is  the trivial quandle and  $\Aut \big(\Conj(G)\big) \cong \Sigma_{G}$. If $G$ is not abelian, then by Proposition \ref{direct aut conj}, the group $\Sigma_{\Z(G)}$ is a subgroup of $\Aut \big(\Conj (G)\big)$.
$\blacksquare$    \end{proof}          

The next result proves an analogue of Proposition \ref{direct aut conj} for finite abelian groups.

\begin{proposition}\label{abbb} 
Let $G$ be a non-trivial finite abelian group. Then $\Aut(G)\times\Sigma_{G}$ embeds in $\Aut \big(\Conj(G)\big)$ if and only if $G \cong \mathbb{Z}_2$.
\end{proposition}

\begin{proof} 
Note that conjugation quandles of abelian groups are trivial quandles. Clearly, if $G\cong \mathbb{Z}_2$, then $\Aut \big(\Conj(G)\big) \cong  \Aut(G)\times\Sigma_{G}$. Conversely, suppose that $\Aut(G)\times\Sigma_{G}$ embeds in $\Aut \big(\Conj(G)\big)$. Since $G$ is an abelian group, we have $\Aut \big(\Conj(G)\big) =\Sigma_{G}$, which has order $|G|!$. But, ${\Aut(G)}\times\Sigma_{G}$ has order $|\Aut(G)| (|G|!)$. This implies that $|\Aut(G)|=1$, and hence $G \cong \mathbb{Z}_2$. 
$\blacksquare$    \end{proof}           

 The following result gives a description of all finite groups $G$ for which $\Aut \big(\Conj(G) \big) \cong \Aut(G)\times \Sigma_{\Z(G)}$ \cite[Theorem 1]{MR3948284}.

\begin{theorem} Let $G$ be a finite group. Then $\Aut\big(\Conj(G)\big) \cong \Aut(G)\times \Sigma_{\Z(G)}$ if and only if $\Z(G)$ is trivial or $G \cong \mathbb{Z}_2$.
\end{theorem}

\begin{proof}
Corollary \ref{equal} and Proposition \ref{abbb} imply that if $\Z(G)$ is trivial or $G \cong \mathbb{Z}_2$, then $\Aut \big(\Conj(G)\big) \cong \Aut(G)\times \Sigma_{\Z(G)}$.
\para

For the converse, suppose that $\Aut \big(\Conj(G)\big) \cong \Aut(G)\times \Sigma_{\Z(G)}$. If $\Z(G)$ is trivial, then the assertion follows from Corollary \ref{equal}. Suppose that $\Z(G)$ is non-trivial. Then, according to the proof of Proposition \ref{direct aut conj}, the group $\Aut(G)\times \Sigma_{\Z(G)}$ consists of automorphisms of the form
\begin{equation}\label{gfo}
x\mapsto\begin{cases}
\varphi(x)& ~\textrm{if}~x\notin \Z(G),\\
\sigma(x)&~\textrm{if}~ x\in \Z(G),
\end{cases}
\end{equation}
where $\varphi$ is an automorphism of $G$ and $\sigma$ is a permutation of $\Z(G)$. For an element $1 \neq a\in \Z(G)$, denote by $t_a$ the automorphism of $\Conj(G)$ of the form $t_a(x)= xa$. Then the map $t_a$ must have the form \eqref{gfo}. If there exist  elements $x,y \in G \setminus \Z(G)$ such that $xy \in G \setminus \Z(G)$, then \eqref{gfo} gives $$\varphi(x)\varphi(y)=\varphi(xy)=t_a(xy)=axy.$$ On the other hand,  from \eqref{gfo}, we have $\varphi(x)=ax$ and $\varphi(y)=ay$. This implies that $a=1$, which is a contradiction. Thus, we have proved that for all $x,y \in G \setminus \Z(G)$, the product $xy$ lie in $\Z(G)$. This means that $|G/\Z(G)|\leq 2$, and $G$ is abelian. Hence, by Proposition \ref{abbb}, we have $G \cong \mathbb{Z}_2$.
$\blacksquare$   
\end{proof}          


By Proposition \ref{aut-conj}, the semi-direct product $\Z(G)\rtimes \Aut(G)$ embeds in $\Aut\big(\Conj (G)\big)$. The following result describes all finite groups $G$ satisfying $\Aut\big(\Conj (G)\big) \cong \Z(G)\rtimes \Aut(G)$ \cite[Theorem 2]{MR3948284}.

\begin{theorem}\label{solution}
Let $G$ be a finite group. Then $\Aut \big(\Conj (G)\big) \cong \Z(G)\rtimes \Aut(G)$ if and only if either $\Z(G)$ is trivial or $G \cong \mathbb{Z}_2$, $\mathbb{Z}_2^2$ or $\mathbb{Z}_3$.
\end{theorem}

\begin{proof} By Corollary \ref{equal}, if $\Z(G)$ is trivial, then $\Aut \big(\Conj (G)\big)=\Aut (G) \cong \Z(G)\rtimes \Aut (G)$. For the groups $\mathbb{Z}_2$, $\mathbb{Z}_2^2$ and $\mathbb{Z}_3$, we see that 
\begin{align}
\notag \Aut \big(\Conj(\mathbb{Z}_2)\big)&\cong \Sigma_2\cong\mathbb{Z}_2\cong\mathbb{Z}_2\rtimes \Aut(\mathbb{Z}_2),\\
\notag \Aut \big(\Conj(\mathbb{Z}_2^2)\big)&\cong \Sigma_4\cong\mathbb{Z}_2^2\rtimes\Sigma_3\cong\mathbb{Z}_2^2\rtimes\Aut(\mathbb{Z}_2^2),\\
\notag \Aut \big(\Conj(\mathbb{Z}_3)\big)&\cong \Sigma_3\cong\mathbb{Z}_3\rtimes\Sigma_2\cong\mathbb{Z}_3\rtimes\Aut(\mathbb{Z}_3).
\end{align}

Conversely, suppose that $G$ is finite and $\Aut \big(\Conj (G)\big) \cong \Z(G)\rtimes \Aut(G)$. For an element $a\in \Z(G)$, denote by $t_a$ the automorphism of the quandle $\Conj(G)$ of the form $t_a(x)=xa$. The group generated by the set $\{t_a \, \mid \, a\in \Z(G) \}$ is isomorphic to $\Z(G)$. In view of Proposition \ref{aut-conj}, the subgroup of $\Aut \big(\Conj(G)\big)$ which is isomorphic to $\Z(G)\rtimes  \Aut(G)$ consists of the automorphisms of the form $t_a\varphi$ for some $a\in \Z(G)$ and $\varphi\in\Aut(G)$. Thus, we need to prove that if every automorphism of $\Conj(G)$ has the form $t_a\varphi$ for some $a\in \Z(G)$ and $\varphi\in\Aut(G)$, then either  $\Z(G)$ is trivial or $G \cong \mathbb{Z}_2$, $\mathbb{Z}_2^2$ or $\mathbb{Z}_3$. 
\para

Suppose that $\Z(G)$ is non-trivial. For a permutation $\sigma$ of  $\Z(G)$, denote by $f$ the automorphism of $\Conj(G)$ of the form
$$f(x)=\begin{cases}
x& ~\textrm{if}~x\notin \Z(G),\\
\sigma(x)&~\textrm{if}~ x\in \Z(G).
\end{cases}$$
Suppose that $f=t_a\varphi$ for some $a\in \Z(G)$ and $\varphi\in \Aut(G)$. If there exist two elements $x,y\in G \setminus \Z(G)$ such that $xy \in G \setminus \Z(G)$, then we see that
\begin{eqnarray}
\notag x&=&f(x)=t_a\varphi(x)=a\varphi(x),\\
\notag y&=&f(y)=t_a\varphi(y)=a\varphi(y),\\
\notag xy&=&f(xy)=t_a\varphi(xy)=a\varphi(x)\varphi(y).
\end{eqnarray}
These equalities imply that $a=1$, and hence $f=\varphi$. Since $\Z(G)\neq 1$, we choose $\sigma$ such that $\sigma(1)\neq1$. In this case, $f$ cannot belong to $\Aut(G)$. Thus, for any two elements $x,y \in G \setminus \Z(G)$, their product $xy$ must lie in $\Z(G)$. This implies that $|G/\Z(G)|\leq 2$, and hence $G$ is abelian. Consequently, we have $|\Aut \big(\Conj(G)\big)|=|\Sigma_{G}|=|G|!$. Since every group automorphism of $G$ fixes the identity element, it follows that  $|\Aut(G)|\leq \big(|G|-1 \big)!$. Further, since $\Aut \big(\Conj (G)\big) \cong \Z(G)\rtimes \Aut(G)=G\rtimes \Aut(G)$, we get $|\Aut(G)|=\big(|G|-1 \big)!$. This means that every permutation of non-trivial elements of $G$ is a group automorphism of $G$. In particular, all non-trivial elements of $G$ have the same order. Suppose that $G$ has at least five distinct elements $\{1,x,y,xy,t\}$. The map $\varphi$ with $\varphi(1)=1$, $\varphi(x)=x$, $\varphi(y)=y$ and $\varphi(xy)=t$ can be extended to a group automorphism of $G$. This gives  $t=\varphi(xy)=\varphi(x)\varphi(y)=xy$, which is a contradiction. Hence,  $G$ has at most $4$ elements. Since all non-trivial elements of $G$ have the same order, it follows that $G \cong \mathbb{Z}_2$, $\mathbb{Z}_2^2$ or $\mathbb{Z}_3$.
$\blacksquare$   
\end{proof}          
