\section{Multi-transitive action of automorphism groups}\label{section6 doubly transitive}
Let $G$ be a group acting on a set $X$ from the left. For each $x \in X$, the subgroup $G_x= \{g \in G \, \mid \, g \cdot x=x \}$ is called the \index{stabilizer subgroup} {\it stabilizer subgroup} at $x$. For each $1 \leq k \leq |X|$, we say that $G$ acts \index{$k$-transitive group}{\it $k$-transitively} on $X$ if for each pair of $k$-tuples $(x_1,\dots,x_k)$ and $(y_1,\dots,y_k)$ of distinct elements of $X$, there exists $g \in G$ such that $g \cdot x_i = y_i$ for each $1 \leq i \leq k$. A 1-transitive action is simply called {\it transitive} and a 2-transitive action is also called {\it doubly transitive}.
\para

Let $X$ be a quandle and $\Inn(X)$ its inner automorphism group. For an integer $k\geq 1$, the quandle $X$ is called \index{$k$-transitive quandle} {\it $k$-transitive} if the group $\Inn(X)$ acts $k$-transitively on $X$. A 1-transitive quandle is simply  a connected quandle. A 2-transitive quandle is also called a \index{two-point homogeneous quandle} {\it two-point homogeneous quandle} in \cite{MR3127819}, where a classification of all two-point homogeneous quandles of prime order was given. A complete classification of finite two-point homogeneous quandles was later completed by Vendramin \cite[Theorem 3]{MR3685034} and Wada \cite{MR3379001}.
\para

McCarron  proved that if $X$ is a finite $k$-transitive quandle with $k\geq 2$ and with at least four elements, then $k = 2$ \cite[Proposition~5]{MR3206312}. Moreover, the dihedral quandle $\R_3$ of order three is the only $3$-transitive quandle. Thus, higher order transitivity does not exist in quandles with at least four elements. In view of the preceding remark, the following problem seems natural.

\begin{problem}
For an integer $k \geq 2$, classify all finite quandles $X$ for which $\Aut(X)$ acts $k$-transitively on $X$.
\end{problem}

We generalise a result of Ferman, Nowik, and Teicher \cite{MR2795262} about doubly transitive action of the automorphism group of a finite Alexander quandle of prime order on the underlying quandle. An alternate proof of the same result was given by Watanabe \cite{MR3319676}. Our approach is more general than \cite{MR2795262} and \cite{MR3319676}. 
\para 

Let $G$ be a finite abelian group, $\varphi \in \Aut(G)$ and 
$$\Aut\big(\Alex(G, \varphi)\big)_1=\big\{f \in  \Aut\big(\Alex(G, \varphi)\big) \, \mid \,  f(1)=1 \big\}$$
 the stabilizer subgroup of $\Aut\big(\Alex(G, \varphi)\big)$ at the identity element $1 \in G$. We first prove a stronger version of Theorem \ref{main-theorem} for finite abelian groups with fixed-point free automorphisms.

\begin{theorem}\label{fixed-point-free-theorem}
Let $G$ be a finite abelian group and $\varphi \in \Aut(G)$ a fixed-point free automorphism. Then the following  assertions hold:
\begin{enumerate}
\item $\C_{\Aut(G)}(\varphi)= \Aut\big(\Alex(G, \varphi)\big)_1$.
\item $ \Aut\big(\Alex(G, \varphi)\big) \cong G \rtimes \C_{\Aut(G)}(\varphi)$.
\item $ \Inn\big(\Alex(G, \varphi)\big) \cong G \rtimes \langle \varphi \rangle$.
\end{enumerate}
\end{theorem}

\begin{proof}
Let $f \in \Aut\big(\Alex(G, \varphi)\big)_1$. Then, for $a, b \in G$, we have
\begin{equation}\label{alex aut fix point free}
f\big(\varphi(a)\varphi(b)^{-1} b \big)=\varphi\big(f(a)\big)\varphi\big(f(b)\big)^{-1}f(b).
\end{equation}
Taking $a=1$ gives $f\big(\varphi(b)^{-1}b \big)=\varphi\big(f(b)\big)^{-1}f(b)$ and taking $b=1$ gives $f\big(\varphi(a)\big)=\varphi\big(f(a)\big)$. Using these identities in \eqref{alex aut fix point free}, we obtain
\begin{equation}\label{alex aut fix point free 2}
f\big(\varphi(a)\tilde{\varphi}(b)^{-1} \big)=f\big(\varphi(a)\varphi(b)^{-1}b \big)=f\big(\varphi(a)\big) f\big(\varphi(b)^{-1}b \big)= f\big(\varphi(a)\big) f\big(\tilde{\varphi}(b)^{-1} \big).
\end{equation}
Since $\varphi$ is fixed-point free, it follows from Theorem \ref{Bae-Choe-theorem} that $\tilde{\varphi} \in \Aut(G)$. Thus, \eqref{alex aut fix point free 2} gives $f(xy)=f(x)f(y)$ for all $x, y \in G$, and hence $f \in \C_{\Aut(G)}(\varphi)$. Conversely, if $f \in \C_{\Aut(G)}(\varphi)$, then $f(1)=1$ and $f(a*b)=f(a)*f(b)$. This proves assertion (1).
\para 
By Proposition \ref{joyce-embedding}, there is an embedding $\Phi:G \rtimes \C_{\Aut(G)}(\varphi)  \hookrightarrow \Aut\big(\Alex(G, \varphi)\big)$ given by $\Phi(a,f) = t_a  f$, where $t_a(x)=xa$. Let $f \in \Aut\big(\Alex(G, \varphi)\big)$. Define $h: G \to G$ by $h(a)=f(a)f(1)^{-1}$ for all $a \in G$. Then $h \in \Aut\big(\Alex(G, \varphi)\big)$ and $h(1)=1$. Hence, $h \in \C_{\Aut(G)}(\varphi)$ and $f= t_{f(1)} h \in \Phi\big(G \rtimes \C_{\Aut(G)}(\varphi) \big)$, which proves assertion (2).

Since $\varphi$ is fixed-point free, by Theorem \ref{Bae-Choe-theorem}, we have $G= \im(\tilde{\varphi})= \{ a^{-1}\varphi(a) \, \mid \, a \in G \}$. Thus, for each $a \in G$, $S_a=t_{\varphi(a)^{-1}a} \varphi \in \Phi(G \rtimes \langle \varphi \rangle)$. Conversely, since each $a \in G$ can be written as $a=\varphi(b)^{-1}b$ for some $b \in G$, we have $t_a \varphi=S_{b}$. This proves assertion (3).
$\blacksquare$    
\end{proof}          

The result below is well-known and follows easily.

\begin{lemma}\label{doubly-transitive-criteria}
Let $G$ be a group acting on a set $X$ and $x \in X$. Then the action is doubly transitive if and only if it is transitive and the stabilizer subgroup $G_x$ acts transitively on $X\setminus \{x\}$.
\end{lemma}

The following result is presumably well-known; however, we include a proof for the sake of completeness.

\begin{lemma}\label{transitive-criteria}
Let $G$ be a non-trivial finite $p$-group, where $p$ is a prime. Then $\Aut(G)$ acts transitively on $G \setminus \{1\}$ if and only if $G \cong (\mathbb{Z}_p)^n$ for some integer $n \geq 1$.
\end{lemma}


\begin{proof}
Suppose that $\Aut(G)$ acts transitively on $G \setminus \{1\}$. By Cauchy's Theorem for finite groups, there exists an element $a \in G$ of order $p$.  Given any $1 \ne b \in G$, there exists $\varphi \in \Aut(G)$ such that $\varphi(a)=b$. This implies that all non-trivial elements of $G$ have order $p$. Since $G$ is a non-trivial $p$-group, its center $\Z(G)$ is non-trivial. For each $1 \ne a \in G$ and $1 \ne b \in \Z(G)$, there exists $\varphi \in \Aut(G)$ such that $\varphi(b)=a$. Since  $\Z(G)$ is characteristic, it follows that  $a\in \Z(G)$. Hence, $G\cong  (\mathbb{Z}_p)^n$ for some integer $n \geq 1$. The converse is obvious, and hence omitted.
$\blacksquare$  
  \end{proof}          

The next result generalises \cite[Theorem 3.9]{MR2795262} to elementary abelian $p$-groups.

\begin{theorem}\label{FNT-generalisation}
Let $G=  (\mathbb{Z}_p)^n$ for some prime $p$ and integer $n \geq 1$. If $\varphi$ is multiplication by a non-trivial unit of $\mathbb{Z}_p$, then $\Aut\big(\Alex(G, \varphi)\big)$ acts doubly transitively on $\Alex(G, \varphi)$.
\end{theorem}

\begin{proof}
Since $\varphi$ is fixed-point free, by Theorem \ref{Bae-Choe-theorem}, the quandle $\Alex(G, \varphi)$ is connected. This implies that $\Inn\big(\Alex(G, \varphi)\big)$, and hence $\Aut\big(\Alex(G, \varphi)\big)$ acts transitively on $\Alex(G, \varphi)$. In view of Lemma \ref{doubly-transitive-criteria}, it suffices to prove that $\Aut\big(\Alex(G, \varphi)\big)_0$ acts transitively on $\Alex(G, \varphi) \setminus \{0\}$. By Theorem \ref{fixed-point-free-theorem},  $\Aut\big(\Alex(G, \varphi)\big)_0=\C_{\Aut(G)}(\varphi)$. But, $\C_{\Aut(G)}(\varphi)= \Aut(G)$, which by Lemma \ref{transitive-criteria} acts transitively on $\Alex(G, \varphi) \setminus \{0\}$.
$\blacksquare$    
\end{proof}          

\begin{remark}{\rm 
It is worth pointing out that $\Alex(G, \varphi)$ is not two-point homogeneous for $G =  (\mathbb{Z}_p)^n$ with $n \geq 2$. This follows from results of Vendramin \cite[Theorem 3]{MR3685034}  and Wada \cite[Corollary 4.5]{MR3379001}, where they classify all finite two-point homogeneous quandles. In fact, they proved that any such quandle is isomorphic to an Alexander quandle defined by primitive roots over a finite field.}
\end{remark}


Next, we define the center of a quandle. 

\begin{definition}
Let $X$ be a quandle. The subset $\Z(X)= \big\{x\in X \, \mid \, x*y=x~\text{for all}~y\in X \big\}$ is called the \index{center of a quandle} {\it center} of the quandle $X$.
\end{definition}

 If $X=\Conj(G)$, then the center $\Z(X)$ of the quandle $X$ coincides with the center $\Z(G)$ of the group $G$.

\begin{lemma}\label{center}
Let $X$ be a quandle with center $\Z(X)$ and $\varphi$ an automorphism of  $X$. Then $\varphi\big(\Z(X)\big)=\Z(X)$.
\end{lemma}
\begin{proof}
If $x\in \Z(X)$, then for all $y\in X$, we have $\varphi(x)*\varphi(y)=\varphi(x*y)=\varphi(x)$. Thus, we have $\varphi(x)\in \Z(X)$. Conversely, if $\varphi(x)\in \Z(X)$, then for all $y\in X$, we have $\varphi(x*y)=\varphi(x)*{\varphi(y)}=\varphi(x)$. Hence, $x*y=x$ for all $y\in X$, and therefore $x\in \Z(X)$.
$\blacksquare$    \end{proof}          


\begin{theorem}\cite[Theorem 5]{MR3948284}\label{tran}
Let $X$ be a finite quandle. Then the following statements are equivalent:
\begin{enumerate}
\item $X$ is either the trivial quandle or $X \cong \R_3$.
\item $\Aut(X)=\Sigma_{X}$. 
\item $\Aut(X)$ acts $3$-transitively on $X$.
\end{enumerate}
\end{theorem}
\begin{proof}
The implications $(1)\Leftrightarrow(2)$ and $(2)\Rightarrow(3)$ are obvious. It remains to prove the implication $(3)\Rightarrow(1)$. 
\para 
Suppose that $\Z(X)\neq\varnothing$. Since $\Aut(X)$ acts $3$-transitively (and therefore $1$-transitively) on $X$, by Lemma \ref{center}, the quandle $X$ is trivial.
\para 
Suppose that $\Z(X)=\varnothing$. Then $|X|\geq3$ and for an element $x\in X$, there exists an element $y\in X$ such that $z:=x*y\neq x$. Since $x\neq y$, we have $z=x*y\neq y*y=y$, and hence $x,y,z$ are distinct elements. Let $t$ be an arbitrary element of $X$. Since $\Aut(X)$ acts $3$-transitively on $X$, if $t\notin\{x,y\}$, then there exists an automorphism $\varphi$ of $X$ such that $\varphi(x)=x$, $\varphi(y)=y$ and $\varphi(z)=t$. This gives $\varphi(z)=\varphi(x*y)=\varphi(x)*\varphi(y)=x*y=z$, and hence  $X=\{x,y,z\}$.
\para
Next, we identify the quandle structure on $X$. Since $\Aut(X)$ acts $3$-transitively on $X$, there exists an automorphism $\varphi$ such that $\varphi(x)=y$, $\varphi(y)=x$ and $\varphi(z)=z$. Thus, $y*x=\varphi(x)*{\varphi(y)}=\varphi(x*y)=\varphi(z)=z=x*y$.
Again, since $\Aut(X)$ acts $3$-transitively on $X$, there exists an automorphism $\psi$ such that $\psi(x)=z$, $\psi(y)=x$ and $\psi(z)=y$, and hence $y=\psi(z)=\psi(x*y)=\psi(x)*{\psi(y)}=z*x$. Repeating this argument for all possible triples constructed from the set $X=\{x,y,z\}$, we obtain the  relations
$$x*y=y*x=z,~x*z=z*x=y~\textrm{and}~y*z=z*y=x.$$
Hence, $X=\{x,y,z\}$ is isomorphic to the dihedral quandle $\R_3$.
$\blacksquare$    
\end{proof}          

\begin{corollary}
If $X$ is a finite quandle such that $\Aut(X)$ acts $3$-transitively on $X$, then it acts $k$-transitively on $X$ for each $k\geq3$.
\end{corollary}
