\chapter{Residual finiteness of quandles}\label{chap residual finiteness}

\begin{quote}
This chapter investigates the property of residual finiteness within the framework of quandles. We begin by establishing foundational results concerning residually finite quandles and then focus on specific classes, including core, conjugation, and Alexander quandles, arising from residually finite groups. We further demonstrate that both free quandles and free products of residually finite quandles, under suitable conditions, preserve residual finiteness.  In the context of knot theory, we leverage these findings to establish that all link quandles exhibit residual finiteness. This conclusion, in turn, implies the solvability of the word problem for link quandles.
\end{quote}
\bigskip

\section{Properties of residually finite quandles}\label{basic properties of residually finite quandles}

Recall that, a group $G$ is said to be \index{residually finite quandle}{\it residually finite} if for each $g, h \in G$ with $g \neq h$, there exists a finite group $F$ and a homomorphism $\phi: G \to F$ such that $\phi(g) \neq \phi(h)$. 
\para
For example, finite groups, free groups and link groups \cite{MR0648524} are known to be residually finite. Residual finiteness of groups play a crucial role in combinatorial group theory. This notion can be analogously defined for quandles.

\begin{definition}
	A quandle $X$ is said to be {\it residually finite} if for all $x,y \in X$ with $x \neq y$, there exists a finite quandle $F$ and quandle homomorphism $\phi:X \rightarrow F$ such that $\phi(x) \neq \phi(y)$.
\end{definition}


In \cite{Malcev-1}, Mal$'$cev gave the definition of a residually finite algebra, and proved that for some algebras, residual finiteness implies that the word problem is solvable. The preceding definition is a particular case of Mal$'$cev's idea.
\para

Clearly, every finite quandle is residually finite, and every subquandle of a residually finite quandle is residually finite. We begin with some elementary observations.


\begin{proposition}\label{trivial-res-finite}
	Every trivial quandle is residually finite.
\end{proposition}

\begin{proof}
	Let $X$ be a trivial quandle. If $X$ is finite, then there is nothing to prove. Suppose that $X$ is infinite. Let $x, y \in X$ with $x \neq y$. Consider the trivial subquandle $\{x, y \}$ of $X$ and define $\phi: X \to \{x, y \}$ by $\phi(x)=x$ and $\phi(z)=y$ for all $z \neq x$. It is easy to see that $\phi$ is a quandle homomorphism with $\phi(x) \neq \phi(y)$, and hence $X$ is residually finite.
$\blacksquare$    \end{proof}          

Next, we investigate some closure properties of residually finite quandles. Let $\lbrace X_i\rbrace_{i \in I}$ be a family of quandles and $X= \prod_{i \in I}X_i$. Then $X$ is itself a quandle, called the {\it product quandle},  with binary operation given by  $$(x_i) \ast (y_i)= (x_i \ast y_i)$$ for $(x_i), (y_i) \in X$.  Further, for each $j \in I$, the projection map $$\pi_j: X \rightarrow X_j$$ given by $\pi_j \big((x_i)\big)=x_j$ is a quandle homomorphism.


\begin{proposition}\label{direct-prod-rf}
	Let $\{X_i\}_{i \in I}$ be a family of residually finite quandles. Then the product quandle $X = \prod_{i \in I}X_i$ is residually finite.
\end{proposition}

\begin{proof}
	Let $x=(x_i),  y=(y_i) \in X$ such that $x \neq y$. Then there exists an $i_0 \in I$ such that $x_{i_0} \neq y_{i_0} $. Since $X_{i_0}$ is residually finite, there exists a finite quandle $F$ and a homomorphism $ \phi: X_{i_0} \rightarrow F$ such that $ \phi(x_{i_0}) \neq \phi(y_{i_0})$. The homomorphism $ \phi ' := \phi ~ \pi_{i_0}$ satisfy $ \phi '(x) \neq \phi ' (y)$, and hence $X$ is a residually finite quandle.
$\blacksquare$    \end{proof}          



\begin{proposition}
	The following statements are equivalent for a quandle $X$:
	\begin{enumerate}
		\item $X$ is residually finite.
		\item There exists a family $\{W_i\}_{i \in I}$ of finite quandles such that the quandle $X$ is isomorphic to a subquandle of the product quandle $\prod _{i \in I} W_i $.
	\end{enumerate}
\end{proposition}

\begin{proof}
	The implication $(2) \Rightarrow (1)$ follows from Proposition  \ref{direct-prod-rf} and the fact that a  subquandle of a residually finite quandle is residually finite. Conversely, suppose that $X$ is residually finite. For each pair $(x,y) \in X \times X$ such that $x \neq y$, there exists a finite quandle $W_{(x,y)}$ and a homomorphism $ \phi_{(x,y)} : X \rightarrow W_{(x,y)}$ such that $ \phi_{(x,y)}(x) \neq \phi_{(x,y)}(y)$. Consider the product quandle $$ W= \displaystyle\prod_{(x,y)\in X \times X,~ x \neq y} W_{(x,y)}.$$ Then the homomorphism $\psi : X \rightarrow W $ defined by $$ \psi= \displaystyle\prod_{(x,y)\in X \times X,~ x \neq y} \phi_{(x,y)}$$ is clearly injective, which proves the implication  $(1) \Rightarrow (2)$.
$\blacksquare$    \end{proof}          

\begin{definition}
A quandle $X$ is called \index{Hopfian quandle}{\it Hopfian} if every surjective quandle endomorphism of $X$ is injective.
\end{definition}

It is well-known that finitely generated residually finite groups are Hopfian  \cite{MR0003420}. We prove a similar result for quandles.
\begin{theorem}\label{hopfian-thm}
Every finitely generated residually finite quandle is Hopfian.
\end{theorem}

\begin{proof}
Let $X$ be a finitely generated residually finite quandle and $\phi:X \rightarrow X$ a surjective quandle homomorphism. Suppose that $\phi$ is not injective. Let $x_1, x_2 \in X$ such that $ x_1 \neq x_2$ and $\phi(x_1) = \phi(x_2)$. Since $X$ is residually finite, there exist a finite quandle $F$ and a quandle homomorphism $\tau:X \rightarrow F$ such that $\tau(x_1) \neq \tau(x_2)$.
\para

We claim that the maps $\tau \, \phi ^{n}:X \rightarrow F$ are distinct quandle homomorphisms for all $n \geq 0$. Let $0 \leq m <n$ be fixed integers. Since $$ \phi ^{m}:X \rightarrow X$$ is surjective, there exist $y_1, y_2 \in X$ such that $\phi ^{m}(y_1)=x_1$ and $\phi ^{m}(y_2)=x_2$. Thus, we have $$\tau \, \phi ^{m}(y_1) \neq \tau \, \phi ^{m}(y_2),$$ whereas $$\tau \, \phi ^{n}(y_1) = \tau \, \phi ^{n}(y_2),$$ which proves our claim. Thus, there are infinitely many quandle homomorphisms from $X$ to $F$. But, this is a contradiction, since $X$ is finitely generated and $F$ is finite. Hence, $\phi$ is an automorphism, and  $X$ is Hopfian.
$\blacksquare$    \end{proof}          

Analogous to groups, we define the \index{word problem} {\it word problem} for quandles as the problem of determining whether two given elements of a quandle are the same. The word problem is solvable for finitely presented residually finite groups  \cite[p. 55]{MR1357169}. Below is an analogous result for quandles.


\begin{theorem}\label{word-problem}
Every finitely presented residually finite quandle has a solvable word problem.
\end{theorem}

\begin{proof}
Let $X=\langle  S \, \mid \, R \rangle $ be a  finitely presented residually finite quandle, and  $w_1,w_2$ two words in the generators $S$. We describe two procedures which tell us whether or not $w_1 =w_2$ in $X$. The first procedure lists all the words  that we obtain by using  the relations of $X$ on the word $w_1$. If the word $w_2$ turns up at some stage, then $w_1=w_2$, and we are done.
\para
The second procedure lists all the finite quandles. Since $X$ is finitely generated, for each finite quandle $F$, the set $\Hom_{\mathcal{Q}}(X,F)$ of all quandle homomorphisms is finite. Now, for each homomorphism $\phi \in \Hom_{\mathcal{Q}}(X,F)$, we check whether or not $\phi(w_1)=\phi(w_2)$. Since $X$ is  residually finite, the above procedure must stop at some point. That is, there exists a finite quandle $F$ and  $\phi \in \Hom_{\mathcal{Q}}(X,F)$  such that  $\phi(w_1) \neq \phi(w_2)$ in $F$, and hence $w_1 \neq w_2$ in $X$.
$\blacksquare$    \end{proof}          


\begin{remark}{\rm 
In \cite{MR3440592}, Belk and McGrail showed that the word problem for quandles is unsolvable in general by giving an example of a finitely presented quandle with unsolvable word problem. In view of Theorem \ref{word-problem}, such a quandle cannot be residually finite. Clearly, if a group $G$ has unsolvable word problem, then $\Conj(G)$ also has unsolvable word problem. But, if a group $G$ is finitely presented, then it is not clear whether $\Conj(G)$ is finitely presented.}
\end{remark}

