\section{Residual finiteness of quandles arising from groups}\label{sec-rf-other-quandles}

In this section, we examine the residual finiteness of conjugation, core, and Alexander quandles associated with residually finite groups. Additionally, we explore the residual finiteness of certain automorphism groups of residually finite quandles.

\begin{proposition}\label{conj-g-res-finite}
Let $G$ be a residually finite group. Then the following assertions hold:
\begin{enumerate}	
\item If $\alpha :G \rightarrow G$ is an inner automorphism, then $\Alex(G, \alpha)$ is a  residually finite quandle.
\item	$\Conj_n(G)$ and $\Core(G)$ are residually finite quandles for each $n$.
\end{enumerate}
\end{proposition}

\begin{proof}
For assertion (1), let $\alpha$ be the inner automorphism induced by $x \in G$. If $g_1, g_2 \in G$ such that $g_1 \neq g_2$, then there exists a finite group $F$ and a group homomorphism $\psi:G \rightarrow F$ such that $\psi(g_1) \neq \psi(g_2)$. Let  $\beta$ be the inner automorphism of $F$ induced by $\psi(x)$. It follows that $\psi$ viewed as a map $ \Alex(G, \alpha) \rightarrow \Alex(F, \beta)$  is a quandle homomorphism with $\psi(g_1) \neq \psi(g_2)$, and hence $\Alex(G, \alpha)$ is residually finite.
\para
Similarly, assertion (2) follows  from the fact that $\Conj_n$ and $\Core$ are functors from the category of groups to that of quandles.
$\blacksquare$    
\end{proof}          

It is well-known that the automorphism group of a finitely generated residually finite group is residually finite \cite[p. 414]{MR0207802}. An analogous result holds for inner automorphism groups of residually finite quandles \cite[Theorem 4.3]{MR3981139}.


\begin{theorem} If $X$ is a residually finite quandle, then $\Inn(X)$ is a residually finite group.
\end{theorem}

\begin{proof}
Let $S_{a_1}^{\epsilon_1} \cdots S_{a_m}^{\epsilon_m}\neq \id_X$ be an element of $\Inn(X)$, where $a_j \in X$ and $\epsilon_j \in \{1, -1\}$ for each $j$. Then there exists an element $x \in X$ such that $$S_{a_1}^{\epsilon_1}  \cdots S_{a_m}^{\epsilon_m}(x) \neq x$$ or equivalently
$$\big(\big((x \ast^{\epsilon_m} a_m) \ast^{\epsilon_{m-1}} a_{m-1} \big) \cdots \big) \ast ^{\epsilon_1} a_1 \neq x.$$ Since $X$ is residually finite, there exists a finite quandle $F$ and a surjective quandle homomorphism $\phi: X \rightarrow F$ such that
\begin{equation}\label{phi-big}
\phi\big(\big(\big((x \ast^{\epsilon_m} a_m) \ast^{\epsilon_{m-1}} a_{m-1} \big) \cdots \big) \ast ^{\epsilon_1} a_1\big) \neq \phi(x).
\end{equation}
Define a map $$\widetilde \phi: \big\{ S_{y}^{\pm 1} \,\mid\,y \in X \big\} \rightarrow \Inn(F)$$ by setting $$\widetilde \phi\big(S_{y}^{\pm 1}\big)=S_{\phi(y)}^{\pm 1}$$ 
for each $y \in X$. It is easy to see that if $S_{x_1}^{\mu_1}  \cdots S_{x_n}^{\mu_n}=\id_X$ is a relation in $\Inn(X)$, then $S_{\phi(x_1)}^{\mu_1}  \cdots S_{\phi(x_n)}^{\mu_n}=\id_F$, and hence $\widetilde \phi$ extends to a group homomorphism $\widetilde \phi: \Inn(X) \to \Inn(F)$. If $\widetilde \phi \big(S_{a_1}^{\epsilon_1} \cdots S_{a_m}^{\epsilon_m} \big) = 1$, then evaluating both the sides at $\phi(x)$ contradicts \eqref{phi-big}. Hence, $\Inn(X)$ is a residually finite group.
$\blacksquare$    \end{proof}          


Next, we consider residual finiteness of automorphism groups of core and conjugation quandles.


\begin{proposition}
If $G$ is a finitely generated abelian group without $2$-torsion, then $\Aut\big(\Core(G)\big)$ is a residually finite group.
\end{proposition}

\begin{proof}
Since $G$ is a finitely generated abelian group, it is residually finite, and hence $\Aut(G)$ is also residually finite. Moreover, a semi-direct product of a finitely generated residually finite group by a residually finite group is residually finite. By Theorem \ref{main-theorem}, we have $\Aut\big(\Core(G)\big) \cong G \rtimes \Aut(G)$, and hence it is residually finite.
$\blacksquare$    \end{proof}          


\begin{proposition}
If $G$ is a finitely generated residually finite group with trivial center, then $\Aut \big(\Conj(G)\big)$ is a residually finite group.
\end{proposition}

\begin{proof}
Since $G$ has trivial center, by Corollary \ref{aut conj trivial center},  we have $\Aut \big(\Conj(G)\big)=\Aut(G)$. Since $G$ is  residually finite, so it  $\Aut(G)$. $\blacksquare$    \end{proof}          
