\section{Residual finiteness of free products of quandles}\label{residual finiteness of free quandles and free product}

Recall the construction of free quandles described in Section \ref{section free quandles} of Chapter \ref{chapter preliminaries on racks and quandles}.

\begin{theorem}\label{free-quandle-rf}
Every free quandle is residually finite.
\end{theorem}

\begin{proof}
	Let $FQ(S)$ be the free quandle on the set $S$. It is well-known that the free group $F(S)$ is residually finite \cite[Theorem 2.3.1]{MR2683112}. By Proposition \ref{conj-g-res-finite}, the quandle $\Conj\big(F(S)\big)$ is residually finite. Since $FQ(S)$ is a subquandle of $\Conj \big(F(S)\big)$, it follows that $FQ(S)$ is residually finite.
$\blacksquare$    \end{proof}          


Theorems \ref{free-quandle-rf} and \ref{hopfian-thm} lead to the following result.

\begin{corollary}\label{fg-free-quandle-hopf}
Every finitely generated free quandle is Hopfian.
\end{corollary}


\begin{remark}{\rm 
Corollary \ref{fg-free-quandle-hopf} is not true for infinitely generated free quandles. Indeed, if $FQ_{\infty}$ is the free quandle freely generated by a countably infinite set $\{x_1, x_2, \ldots \}$, then we can define a homomorphism $\varphi : FQ_{\infty} \to FQ_{\infty}$ by setting
$$
\varphi(x_1) = x_1~\textrm{and}~\varphi(x_i) = x_{i-1}
$$
for $i\ge 2$. It is easy to see that $\varphi$ is an epimorphism which is not an automorphism since $\varphi(x_1) = \varphi(x_2)$.}
\end{remark}


The following is a well-known result for free groups \cite[p. 42]{MR0080089}.


\begin{theorem}\label{free-group-symm}
Let $F(S)$ be a free group on a set $S$ and $g\in F(S)$ a non-trivial element. Then there is a homomorphism $\rho: F(S) \to \Sigma_n$ for some $n$ such that $\rho(g) \neq 1$, where $\Sigma_n$ is the symmetric group on $n$ elements.
\end{theorem}

We apply the preceding theorem to establish an analogous result for free quandles. 

\begin{theorem}
Let $FQ(S)$ be the free quandle on a set $S$ and let $x,y \in FQ(S)$ be two distinct elements. Then there is a quandle homomorphism $\phi:FQ(S) \rightarrow \Conj(\Sigma_n)$ for some $n$ such that $\phi(x) \neq \phi(y)$.
\end{theorem}

\begin{proof}
Recall that the map $\Phi: FQ(S) \rightarrow \Conj \big(F(S)\big) $ in Theorem \ref{equivalence-two-models} is an injective quandle homomorphism. Let $(a_{1},{w_{1}}) \neq (a_{2},{w_{2}}) \in FQ(S)$. Then $g_{1} \neq g_{2} \in F(S)$, where $g_{1}=\Phi \big((a_{1},{w_{1}}) \big)$ and $g_{2}=\Phi \big((a_{2},{w_{2}})\big)$. Consequently, $g_{2}^{-1}g_{1}$ is a non-trivial element of $F(S)$. By Theorem \ref{free-group-symm}, there exists a group homomorphism $\rho:F(S) \rightarrow \Sigma_n$ for some $n$ such that $\rho(g_{1})\neq\rho(g_{2})$. We can view $\rho$ as a quandle homomorphism
$\Conj \big(F(S)\big) \rightarrow \Conj(\Sigma_n)$. Taking  $\phi := \rho\, \Phi : FQ(S) \rightarrow \Conj(\Sigma_n)$, we see that $\phi \big((a_{1},{w_{1}})\big) \neq \phi \big((a_{2},{w_{2}}) \big)$, and the proof is complete.
$\blacksquare$    \end{proof}          


The following result is well-known in combinatorial group theory, first proved by Gruenberg \cite[Theorem 4.1]{MR0087652}. See also \cite{MR0484178, MR0463296}.


\begin{theorem}\label{free-product-of-residually-finite-groups}
A free product of residually finite groups is residually finite.
\end{theorem}


We prove an analogue of the preceding theorem for quandles provided their adjoint groups are residually finite. Recall that, every element of a quandle $X$ can be written in a left associated form $x_0 \ast^{\epsilon_1} x_1 \ast^{\epsilon_2} x_2 \ast ^{\epsilon_3} \cdots \ast ^{\epsilon_n} x_n$. Moreover, the expression $x_0 \ast^{\epsilon_1} x_1 \ast^{\epsilon_2} x_2 \ast ^{\epsilon_3} \cdots \ast ^{\epsilon_n} x_n$ is called a \index{reduced form}{\it reduced form} when $x_0 \neq x_1$ and if $x_i = x_{i+1}$, then $\epsilon_i = \epsilon_{i+1}.$ Note that the reduced form is not unique. For example, if $X = \{ t \} \star \R_3$ is the free product of the one element trivial quandle and the dihedral quandle $\R_3 = \{ 0, 1, 2 \}$, then
$$
(t * 1) * 2 = (t * 2) * (1 * 2) =  (t * 2) * 0.
$$

\begin{theorem} \cite[Theorem 4.3]{MR4075375}\label{finite-free-product-of-residually-finite-quandles}
	Let $X_1, \ldots,X_n$ be residually finite quandles. If each adjoint group $\Adj(X_i)$ is residually finite, then $X_1 \star \cdots \star X_n$ is a residually finite quandle.
\end{theorem}
\begin{proof}
It is enough to consider the case $n=2$. Set $X= X_1 \star X_2$. Let $x$ and $x'$ be two distinct elements of $X$, where
$$ x =a_0 \ast ^{\epsilon_1}a_1  \ast ^{\epsilon_2} a_2 \ast ^{\epsilon_3}\cdots \ast ^{\epsilon_n} a_n \quad \textrm{and} \quad 
x'=b_0 \ast ^{\epsilon_1'}b_1 \ast ^{\epsilon_2'} b_2  \ast ^{\epsilon_3'}\cdots \ast ^{\epsilon_m'} b_m $$
are their reduced expressions with $a_i, b_j  \in X_1 \sqcup X_2$. 
\begin{enumerate}
\item[Case 1:] $x, x' \in X_1$ or  $x, x' \in X_2$. Suppose that  $x, x' \in X_1$. Since $X_1$ is a residually finite quandle, there exist a finite quandle $F$ and a quandle homomorphism $\phi: X_1 \rightarrow F$ such that $\phi(x)\neq \phi(x')$. Let $a \in F$ be  some fixed element. Define a map $\tilde{\phi}: X \rightarrow {F}$ by setting
	$$
	\tilde{\phi}(q)= \left\{
	\begin{array}{ll}
	\phi(q) &  \textrm{if}~q  \in X_1,\\
	a~& \textrm{if}~ q \in X_2.
	\end{array} \right.
	$$
	Since $\tilde{\phi}$ preserve all the relations in $X$, it extends to a quandle homomorphism with $\tilde{\phi}(x) \neq \tilde{\phi}(x')$ in $F$.
\para
\item[Case 2:] $ x \in X_1$ and $x' \in X_2$. Let $Y= \{ a, b \}$ and $FQ(Y)$ the free quandle on $Y$. Define a map $\phi : X \rightarrow FQ(Y)$ by setting
	$$
	\phi(q)= \left\{
	\begin{array}{ll}
	a~&  \textrm{if}~q  \in X_1,\\
	b~& \textrm{if}~ q \in X_2.
	\end{array} \right.
	$$
	Since $\phi$ preserve all the relations in $X$, it extends to a quandle homomorphism with $\phi(x) \neq \phi(x')$ in $FQ(Y)$.
\para
\item[Case 3:] $ x \in X \setminus (X_1 \sqcup X_2)$ and $x ' \in X_1$. We can assume that either $a_0 \in X_1$, $a_1 \in X_2$ and $a_2, \ldots , a_n \in X_1 \sqcup X_2$ or $a_0 \in X_2$, $a_1 \in X_1$ and $a_2,\ldots , a_n \in X_1 \sqcup X_2$, that is,


	$$
	x= \left\{
	\begin{array}{ll}
	q_1 \ast^{\epsilon_1} q_2  \ast^{\epsilon_2} a_2 \ast ^{\epsilon_3} \cdots \ast^{\epsilon_n} a_n & ~~\textrm{where}~~q_1 \in X_1,~~q_2 \in X_2,\\
	\textrm{or} &\\
	q_2 \ast ^{\epsilon_1} q_1 \ast ^{\epsilon_2} a_2 \ast ^{\epsilon_3} \cdots \ast^{\epsilon_n} a_n & ~~\textrm{where}~~q_1 \in X_1,~~q_2 \in X_2.
	\end{array} \right.
	$$
	It follows from Proposition \ref{presentation-of-adjoint-group-of-free-product-of-quandles}, Theorem \ref{free-product-of-residually-finite-groups} and Proposition \ref{conj-g-res-finite} that $\Conj\big(\Adj(X)\big)$ is a residually finite quandle. Let	$i_X:X  \rightarrow \Conj\big(\Adj(X)\big)$	be the natural quandle homomorphism. Then, we have
	$$
	i_X(x_0 \ast ^{\epsilon_1}x_1  \ast ^{\epsilon_2} x_2 \ast ^{\epsilon_3}\cdots \ast ^{\epsilon_n} x_n )= (\textswab{a}_{x_1} ^{\epsilon_1}  \textswab{a}_{x_2} ^{\epsilon_2} \cdots  \textswab{a}_{x_n} ^{\epsilon_n})^{-1} \textswab{a}_{x_0} (\textswab{a}_{x_1} ^{\epsilon_1}  \textswab{a}_{x_2} ^{\epsilon_2} \cdots  \textswab{a}_{x_n} ^{\epsilon_n}).
	$$
	We claim that $i_X(x) \neq i_X(x')$. 
\para
\item[Case 3.1:] If $x =  q_1 \ast^{\epsilon_1} q_2  \ast^{\epsilon_2} a_2 \ast ^{\epsilon_3} \cdots \ast^{\epsilon_n} a_n, ~~\textrm{where}~~q_1 \in X_1,~~q_2\in X_2,~~ \textrm{and}~~a_2, \ldots, a_{n}   \in X_1 \sqcup X_2$, then
	\begin{align*}
	i_X(x) &= (\textswab{a}_{q_2} ^{\epsilon_1}  \textswab{a}_{a_2} ^{\epsilon_2} \cdots  \textswab{a}_{a_n} ^{\epsilon_n})^{-1} \textswab{a}_{q_1} (\textswab{a}_{q_2} ^{\epsilon_1}  \textswab{a}_{a_2} ^{\epsilon_2} \cdots  \textswab{a}_{a_n} ^{\epsilon_n})\\
	&= \textswab{a}_{a_n} ^{-\epsilon_n} \ldots \textswab{a}_{a_2} ^{-\epsilon_2} \textswab{a}_{q_2} ^{-\epsilon_1} \textswab{a}_{q_1} \textswab{a}_{q_2} ^{\epsilon_1}  \textswab{a}_{a_2} ^{\epsilon_2} \cdots  \textswab{a}_{a_n} ^{\epsilon_n}.
	\end{align*}
	Suppose that $i_X(x)=i_X(x')$. Then by the Remark \ref{image-under-eta} and the fact that elements of $\Adj(X_1)$ have no relations with elements of $\Adj(X_2)$ in the group $\Adj(X)$, it follows that either $\textswab{a}_{q_2} ^{\epsilon_1}  \textswab{a}_{a_2}^{\epsilon_2} \cdots  \textswab{a}_{a_n} ^{\epsilon_n}= 1$ in $\Adj(X)$ or $\textswab{a}_{q_2} ^{\epsilon_1}  \textswab{a}_{a_2} ^{\epsilon_2} \cdots  \textswab{a}_{a_n} ^{\epsilon_n}= \textswab{a}_{q_{i_1}}^{\epsilon _1} \textswab{a}_{q_{i_2}}^{\epsilon _2} \cdots \textswab{a}_{q_{i_k}}^{\epsilon _k} $, where $q_{i_1}, q_{i_2} , \ldots, q_{i_k}  \in X_1$ and $\epsilon_j = \pm 1$ for $1 \leq j \leq k$. Since $\Adj(X)$ has a left-action on the quandle $X$, this implies that in either situation $q_1 \cdot (\textswab{a}_{q_2} ^{\epsilon_1}  \textswab{a}_{a_2} ^{\epsilon_2} \ldots  \textswab{a}_{a_n} ^{\epsilon_n})$ belongs to $X_1$. Thus, $x=q_1 \ast ^{\epsilon_1} q_2 \ast ^{\epsilon_2} a_2 \ast ^{\epsilon_3}\cdots \ast ^{\epsilon_n} a_n  \in X_1$, which is a contradiction. Hence, we must have $i_X(x) \neq i_X(x')$.
\para
\item[Case 3.2:] If $x = q_2 \ast ^{\epsilon_1} q_1 \ast ^{\epsilon_2} a_2 \ast ^{\epsilon_3} \cdots \ast^{\epsilon_n} a_n,  ~~\textrm{where}~~q_1 \in X_1,~~q_2 \in X_2~~ \textrm{and}~~a_2, \ldots , a_{n} \in X_1 \sqcup X_2,$ then
	\begin{align*}
	i_X(x) &= (\textswab{a}_{q_1} ^{\epsilon_1}  \textswab{a}_{a_2} ^{\epsilon_2} \cdots  \textswab{a}_{a_n} ^{\epsilon_n})^{-1} \textswab{a}_{q_2} (\textswab{a}_{q_1} ^{\epsilon_1}  \textswab{a}_{a_2} ^{\epsilon_2} \cdots  \textswab{a}_{a_n} ^{\epsilon_n})\\
	&= \textswab{a}_{a_n} ^{-\epsilon_n} \ldots \textswab{a}_{a_2} ^{-\epsilon_2} \textswab{a}_{q_1} ^{-\epsilon_1} \textswab{a}_{q_2} \textswab{a}_{q_1} ^{\epsilon_1}  \textswab{a}_{a_2} ^{\epsilon_2} \cdots  \textswab{a}_{a_n} ^{\epsilon_n}.
	\end{align*}
	Clearly $i_X(x) \neq i_X(x')$, since they belong to different conjugacy classes in $\Adj(X)$.
\para
\item[Case 4:] $ x \in X \setminus (X_1 \sqcup X_2)$ and $x ' \in X_2$. This is similar to Case 3.
\para
\item[Case 5:] $ x, x' \in X \setminus (X_1 \sqcup X_2).$ This case can be reduced to one of the Cases (1--4) by repeated use of the second quandle axiom. More precisely, we can replace the element $x$ by $y$ and $x'$ by $y'$, where
	\begin{align*}
	y&= a_0 \ast ^{\epsilon_1} a_1 \ast ^{\epsilon_2} \cdots \ast^{\epsilon_n} a_n \ast^{-\epsilon_m'} b_m \ast^{-\epsilon' _{m-1}} b_{m-1} \ast^{-\epsilon' _{m-2}} \cdots \ast^{-\epsilon' _{1}} b_1,\\
	y'&= b_0.
	\end{align*}
\end{enumerate}
Hence, we conclude that $X= X_1 \star X_2$ is a residually finite quandle.
$\blacksquare$    \end{proof}          

We now extend  the preceding result to arbitrary family of quandles \cite[Theorem 4.4]{MR4075375}.

\begin{theorem}\label{arbitrary-free-product-of-residually-finite-quandles}
Let $\{X_i\}_{i \in I}$ be a family of residually finite quandles. If each $\Adj(X_i)$ is a residually finite group, then the free product $\star_{i \in I} X_i$ is a residually finite quandle.
\end{theorem}
\begin{proof}
Let $X= \star_{i \in I} X_i$ be the free product of residually finite quandles $X_i$. Let $x, x' \in X$ be two distinct elements such that
$$ x =a_0 \ast ^{\epsilon_1}a_1  \ast ^{\epsilon_2} a_2 \ast ^{\epsilon_3}\cdots \ast ^{\epsilon_n} a_n \quad \textrm{and} \quad 
x'=b_0 \ast ^{\varepsilon_1}b_1 \ast ^{\varepsilon_2} b_2  \ast ^{\varepsilon_3}\cdots \ast ^{\varepsilon_m} b_m.
$$
Consider the set $S = \{ a_i, b_j  \, \mid \,  1 \leq i \leq n~~\textrm{and}~~1 \leq j \leq m \}$. Then $S$ is a finite set contained in $ X_{i_1} \sqcup \cdots \sqcup X_{i_k}$ for some $i_1, \ldots, i_k \in I$. Let $a$ be a fixed element in $\sqcup_{i \in I} X_i \setminus ( X_{i_1} \sqcup \cdots \sqcup X_{i_k})$.
Define a map $$\phi: X \rightarrow X_{i_1} \star \cdots \star X_{i_k}$$ by setting

$$
\phi(q)= \left\{
\begin{array}{ll}
q &  \textrm{if}~~q  \in  X_{i_1} \sqcup \cdots \sqcup X_{i_k},\\
a~& \textrm{if}~ q \in \sqcup_{i \in I} X_i \setminus (X_{i_1} \sqcup \cdots \sqcup X_{i_k}).
\end{array} \right.
$$
Since $\phi$ preserves all the relations in $X$, it extends to a quandle homomorphism with $\phi(x) \neq \phi(x')$. Hence, it follows from Theorem \ref{finite-free-product-of-residually-finite-quandles} that $X$ is a residually finite quandle.
$\blacksquare$    \end{proof}          

We note that Theorem \ref{arbitrary-free-product-of-residually-finite-quandles} gives an alternate proof of Theorem \ref{free-quandle-rf}. Finally we discuss residual finiteness of adjoint groups of quandles. 

\begin{proposition}\label{ass-group-finite}
If $X$ is a finite quandle, then its adjoint group $\Adj(X)$ is a residually finite group.
\end{proposition}

\begin{proof}
Consider the natural group homomorphism  $\psi_{X}: \Adj(X) \rightarrow \Inn(X)$. Since $X$ is a finite quandle, the inner automorphism group $\Inn(X)$ is finite, and hence  $\Adj(X)/ \ker(\psi_{X})$ is finite. Moreover, $\ker(\psi_{X})$ is contained in the center $\Z \big(\Adj(X) \big)$ of $\Adj(X)$, and hence $\Adj(X)/ \Z \big(\Adj(X)\big)$ is finite. It is well-known that
if $G$ is a finitely generated group with infinitely generated center $\Z(G)$, then the quotient $G/\Z(G)$ is not finitely presented. Hence, $\Z \big(\Adj(X)\big)$ is a finitely generated abelian group, and therefore it is residually finite. It is known that if $N$ is a normal subgroup of finite index in a group $G$ and $N$ is residually finite, then $G$ is also residually finite \cite[Proposition 2.2.12]{MR2683112}. Hence,  $\Adj(X)$ is a residually finite group.
$\blacksquare$    \end{proof}          
\para

As a consequence of Proposition \ref{ass-group-finite} and Theorem \ref{arbitrary-free-product-of-residually-finite-quandles}, we obtain the following result.

\begin{corollary}
A free product of finite quandles is residually finite.
\end{corollary}
