\section{Residual finiteness of link quandles}\label{sec-non-split}
In this section, we prove that the link quandle of any oriented link in $\mathbb{S}^3$ is residually finite. We recall the following definition from \cite{Malcev-1}.

\begin{definition}
A subgroup $H$ of a group $G$ is said to be \index{finitely separable subgroup}{\it finitely separable} if for any $g \in G \setminus H$, there exists a finite group $F$ and a group homomorphism $\phi: G \rightarrow F$ such that $\phi(g) \not\in \phi(H)$.
\end{definition}
\para

For example, if $G$ is a residually finite group and $H$ a finite subgroup of $G$, then $H$ is finitely separable in $G$. In analogy with groups, we introduce the following definition.

\begin{definition}
	A subquandle $Y$ of a quandle $X$ is said to be \index{finitely separable subquandle}{\it finitely separable} in $X$ if for each $x \in X\setminus Y$, there exists a finite quandle $F$ and a quandle homomorphism $\phi: X \to F$ such that $\phi(x) \not\in \phi(Y)$.
\end{definition}

The following result is of independent interest.

\begin{proposition}
Let $X$ be a residually finite quandle and $\alpha \in \Aut(X)$. If the fixed-point set $\Fix(\alpha)= \{x \in X \, \mid \,  \alpha(x)=x\}$ is non-empty, then it is a finitely separable subquandle of $X$.
\end{proposition}

\begin{proof}
Clearly $\Fix(\alpha)$ is a subquandle of $X$. Let $x_0 \in X \setminus \Fix(\alpha)$, that is, $\alpha(x_0) \neq x_0$. Since $X$ is residually finite, there exists a finite quandle $F$ and a quandle homomorphism $\phi: X \rightarrow F$ such that $\phi \big(\alpha(x_0) \big) \neq \phi(x_0)$. Define a map $\psi: X \rightarrow F\times F $ by $\psi(x)=\big(\phi(x), \, \phi\, \alpha(x)\big)$. Clearly $\psi$ is a quandle homomorphism with $\psi(x_0) \not\in \psi \big(\Fix(\alpha) \big)$, and hence $\Fix(\alpha)$ is finitely separable in $X$.
$\blacksquare$    \end{proof}          

The following result will be used to prove residual finiteness of link quandles \cite[Proposition 3.4]{MR4075375}.

\begin{proposition} \label{res-finite-quandle}
	Let $G$ be a group, $\{z_i \, \mid \, i \in I \}$ be a finite set of elements of $G$, and $\{H_i \, \mid \, i \in I \}$ subgroups of $G$ such that $H_i \le \C_G(z_i)$. If each $H_i$ is finitely separable in $G$, then the quandle $\bigsqcup_{i \in I}(G,H_i,z_i)$ is residually finite.
\end{proposition}

\begin{proof}
	Let $H_k a \neq	 H_j b$ be two elements of $\bigsqcup_{i \in I}(G,H_i,z_i)$.
\begin{enumerate}
\item[Case 1:] $k \neq j$. Let $F=\{a',b' \}$ be a two element trivial quandle. Define $$\phi: \bigsqcup_{i \in I}(G,H_i,z_i) \rightarrow F$$ by setting
	$$
	\phi(H_i x)= \left\{
	\begin{array}{ll}
	a' &  \textrm{if}~ i=k,\\
	b'~& \textrm{if}~ i\neq k.
	\end{array} \right.
	$$
	Then $\phi$ is a quandle homomorphism with $\phi(H_k a)\neq \phi(H_j b)$.
\para
\item[Case 2:] $k=j$. Since $H_k a \neq H_k b$, we have $a \neq hb$ for any $h \in H_k$. Further, since $H_k$ is finitely separable in $G$, there exist a finite group $F$ and a group homomorphism $\phi:G \rightarrow F$ such that $\phi(a) \neq \phi(h b)$ for each $h \in H_k$. For each $i \in I$, set $\overline{H}_i= \phi(H_i)$  and $\bar{z}_i=\phi(z_i)$. Then  $\overline{H}_i \le  \C_F( \bar{z}_i)$ and $\bigsqcup_{i \in I}(F, \overline{H}_i,\bar{z}_i)$ is a finite quandle. Further, the group homomorphism $\phi:G \rightarrow F$ induces a map

	 $$\bar{\phi}:\bigsqcup_{i \in I}(G,H_i,z_i) \rightarrow \bigsqcup_{i \in I}(F,\overline{H}_i,\bar{z}_i)$$ 	 
	 given by $$\bar{\phi}(H_i x)=\overline{H_i} \phi(x),$$ which is a quandle homomorphism. Also, $\bar{\phi}(H_k a) \neq \bar{\phi}(H_k b)$, otherwise $\phi(a)=\phi(hb)$ for some $h\in H_k$, which is a contradiction.  
\end{enumerate}	 
Hence, the quandle $\bigsqcup_{i \in I}(G,H_i,z_i)$ is residually finite.
$\blacksquare$    \end{proof}          

Let $M$ be a 3-manifold. A surface $F$ in $M$, which is not a 2-sphere, is said to be \index{incompressible subsurface}{\it incompressible} if the homomorphism $\pi_1(F, x) \to \pi_1(M, x)$ is injective for $x \in F$. The following result concerning  finitely separable subgroups of fundamental groups of irreducible 3-manifolds is due to Long and Niblo \cite[Theorem 1]{MR1109662}.

\begin{theorem}\label{Long-Niblo-thm}
	Suppose that $M$ is an orientable, irreducible compact 3-manifold and $X$ an incompressible connected subsurface of a component of $\partial(M)$. If $x\in X$ is a base point, then $\pi_1(X,x)$ is a finitely separable subgroup of $\pi_1(M,x)$.
\end{theorem}
\para

Joyce \cite{MR2628474, MR0638121} and Matveev \cite{MR0672410} independently introduced the link quandle $Q(L)$ of an oriented link $L$ in $\mathbb{S}^3$ (see Example \ref{construction link quandle}). We recall their topological construction here.
 \para

Let $L$ be an oriented link in $\mathbb{S}^3$ with component knots $K_1, \ldots, K_m$ and $V(L)=\bigsqcup_{i=1}^m V(K_i)$ be its tubular neighbourhood. Let $X(L)$ be the closure of $\mathbb{S}^3 \setminus V(L)$ in $\mathbb{S}^3$.  For each $i$, consider the inclusion maps $\kappa_i : \partial V(K_i) \rightarrow X(L)$ and induced group homomorphisms $$\kappa^*_i : \pi_1 \big(\partial V(K_i) \big) \rightarrow \pi_1\big(X(L)\big).$$ Since $\pi_1\big(\partial V(K_i)\big) \cong \mathbb{Z} \oplus \mathbb{Z}$, we may choose generators of this group corresponding to the \textit{meridian} $m_i$ and the \textit{longitude}  $\ell_i$ of the knot  $K_i$, which are well-defined up to homotopy in $\partial V(K_i)$.  The group $P_i=\kappa^*_i \big(\pi_1(\partial V(K_i)) \big)$ is called the $i$-th \textit{peripheral subgroup} of $\pi_1\big(X(L)\big)$. 
\para


Let $Q(L)$ be the set of homotopy classes of paths in the space $X(L)$, with initial point on $ \partial V(L)$ and a fixed endpoint $ x_0 \in X(L)$. We require that these conditions on the initial and the final points are preserved during the homotopy.  Define a binary operation on $ Q(L)$ by
\begin{eqnarray*}
	[a] * [b] = [ab^{-1}m_j b],
\end{eqnarray*}
where $a$ and $b$ are paths in $X(L)$ representing $[a]$ and $[b]$, respectively. It can be checked that the binary operation turns $Q(L)$ into a quandle, called the {\it link quandle} of the link $L$. The natural action of $\pi_1\big(X(L)\big)$ on $Q(L)$ given by $$[a] \cdot [g]=[a g]$$ yields the following homogeneous representation of $Q(L)$ in terms of $\pi_1 \big(X(L)\big)$ (see \cite[Section 4.9, Corollary 1]{MR2628474} or \cite[Theorem 3.6]{MR4075375}).

\begin{theorem}\label{coset representation of knot quandle}
Let $L$ be an oriented link in $\mathbb{S}^3$ with component knots $K_1, \ldots, K_m$. For each $i$, let $m_i$ and $\ell_i$ be the fixed meridian and the longitude of the component $K_i$, respectively. Then $Q(L) \cong \bigsqcup_{i=1}^m \big(\pi_1(X(L)),P_i,m_i \big)$, where $P_i=\langle m_i,\ell_i \rangle.$ 
\end{theorem}

Following is the main result of this section  \cite[Theorem 4.5]{MR4075375}.

\begin{theorem}\label{non-split-link-quandle-is-residually-finite}
The link quandle of any oriented link in $\mathbb{S}^3$ is residually finite.
\end{theorem}

\begin{proof} 
If $L$ is a trivial link, then its link quandle is a free quandle. By Theorem \ref{free-quandle-rf}, such a quandle is residually finite. Suppose that $L$ is a non-trivial and non-split link. By Theorem \ref{coset representation of knot quandle}, we have 
$$Q(L) \cong \bigsqcup_{i=1}^m \big(\pi_1(X(L)),P_i,m_i \big),$$
where $P_i=\langle m_i,\ell_i \rangle.$   Since $L$ is non-split, it follows from Theorem \ref{Long-Niblo-thm} that each $P_i$ is finitely separable in $\pi_1 \big(X(L)\big)$. Hence, by Proposition \ref{res-finite-quandle}, the link quandle $Q(L)$ is residually finite.
\para
Now, suppose that $L$ is a non-trivial and split link. Then the link quandle $Q(L)$ is a free product of link quandles of its non-split components. Using the fact that all link groups are residually finite \cite{MR0895623}, the result now follows from the preceding case and Theorem \ref{finite-free-product-of-residually-finite-quandles}.
$\blacksquare$    \end{proof}          

\begin{corollary}
The link quandle of any oriented link in $\mathbb{S}^3$ is Hopfian, has solvable word problem, and has residually finite inner automorphism group.
\end{corollary}

Since adjoint groups of finite quandles, free quandles and link quandles are residually finite, the following seems to be the case in general.

\begin{conjecture}\label{residually-finite-adjoint-group}
The adjoint group of a finitely presented residually finite quandle is a residually finite group.
\end{conjecture}

\begin{remark}
{\rm 
If Conjecture \ref{residually-finite-adjoint-group} is true, then by Theorem \ref{arbitrary-free-product-of-residually-finite-quandles}, a free product of finitely presented residually finite quandles would be residually finite, which would be an analogue of Theorem \ref{free-product-of-residually-finite-groups} for quandles.
}
\end{remark}

\begin{remark}
{\rm 
In \cite{DhanwaniSarafSingh}, building on results from Thurston's geometrisation program, Theorem \ref{non-split-link-quandle-is-residually-finite} was extended to all $n$-quandles of link quandles.}
\end{remark}


