\chapter{Orderability of quandles}\label{chap orderability of quandles}

\begin{quote}
Orderability of an algebraic structure is expected to have profound implications on its inherent structure. In this chapter, we introduce the idea of orderability of quandles. We begin by exploring properties of linear orderings on quandles and provide many examples of orderable quandles. We also give some general constructions of orderable quandles, and observe that  free quandles  are orderable. As application to knot theory, we also delve into the examination of the orderability of link quandles.
\end{quote}
\bigskip

\section{Properties and examples of orderable quandles}
Existence of a linear order on a group is known to have profound implications on its structure. For instance, a left-orderable group cannot have torsion and a bi-orderable group cannot have even generalized torsion (product of conjugates of a non-trivial element being trivial). In this chapter, we investigate orderability of quandles with applications to link quandles.
\para

\begin{definition} 
A quandle $X$ is said to be \index{left-orderable quandle}{\it left-orderable} if there is a (strict) \index{linear order}linear order $<$ on $X$ such that $x<y$ implies $z*x<z*y$ for all $x,y,z\in X$. Similarly, a quandle $X$ is \index{right-orderable quandle}{\it right-orderable} if there is a linear order $<$ on $X$ such that $x< y$ implies $x*z< y*z$ for all $x,y,z\in X$.  Further, a quandle is \index{bi-orderable quandle}{\it bi-orderable} if it has a linear order with respect to which it is both left and right ordered.
\end{definition}

If $\T=\left\{x_1,x_2,\ldots\right\}$ is a trivial quandle, then it is clear that the linear order $x_1<x_2<\cdots$ is preserved under multiplication on the right, but is not preserved under multiplication on the left. Thus, a trivial quandle with more than one element is right-orderable but not left-orderable. 
This stands in contrast to the case of groups, where left-orderability and right-orderability are equivalent.
\para

The following result demonstrates that a wide variety of left- or right-orderable quandles can be constructed from bi-orderable groups (\cite[Proposition 7]{MR2320157} and (\cite[Proposition 2.6]{MR4330281}).


\begin{proposition}\label{conj right orderable}
The following  assertions hold for a bi-orderable group $G$:
\begin{enumerate}
\item  $\Conj_n(G)$ is a right-orderable quandle for each $n$.
\item $\Core(G)$ is a left-orderable quandle. 
\item If $\phi \in \Aut(G)$ is an order reversing automorphism, then $\Alex(G, \phi)$ is a left-orderable quandle.
\end{enumerate}
\end{proposition}

\begin{proof}
Let $G$ be bi-ordered with respect to the  linear order $<$ and $x, y, z \in G$ such that $x < y$. Then $$x*z=z^nxz^{-n} < z^nyz^{-n}=y*z$$ implies that $\Conj_n(G)$ is a right-orderable quandle. Similarly, 
$$z*x= xz^{-1}x <  yz^{-1}x <  yz^{-1}y= z*y$$ implies that $\Core(G)$ is a left-orderable quandle. This establishes (1) and (2).
\para
For assertion (3), bi-ordering of $G$ and $\phi$ being order reversing implies that $\phi(x)^{-1} < \phi(y)^{-1}$. This gives
$$z*x= \phi(zx^{-1})x=  \phi(z)\phi(x^{-1})x < \phi(z)\phi(x^{-1})y < \phi(z)\phi(y^{-1})y=z*y,$$
which proves that $\Alex(G, \phi)$ is left-orderable.
$\blacksquare$    \end{proof}          


For example, free groups \cite{MR0031482},  fundamental group of any connected surface other than the projective plane or the Klein bottle \cite{MR2141698} and  pure braid groups  \cite{MR0975081} are bi-orderable.
\para

An immediate consequence of the preceding proposition is the following result.

\begin{corollary}
The following  assertions hold for any quandle $X$:
\begin{enumerate}
\item If $X$ is a subquandle of $\Conj_n(G)$ for some bi-orderable group $G$, then $X$ is right-orderable. 
\item If $X$ is a subquandle of $\Core(G)$ for some bi-orderable group $G$, then $X$ is left-orderable. 
\end{enumerate}
\end{corollary}


It is easy to see that a right- or left-orderable group must be infinite. But, this is not true for quandles since any finite trivial quandle is right-orderable. A quandle is said to be \index{semi-latin}{\it semi-latin} if left multiplication by each element is injective. Clearly, a latin quandle is semi-latin, but the converse does not hold in general. The following properties hold for quandles \cite[Proposition 3.7]{MR4450681}.

\begin{proposition}\label{orderable-implies-latin}
The following  assertions hold for any quandle $X$:
\begin{enumerate}
\item If $X$ is  right-orderable, then the $\langle S_y \rangle $-orbit of  $x$ is infinite for all $x, y \in X$ with $S_y(x) \ne x$.
\item If $X$ is  left-orderable, then it is semi-latin and the set $\{L_y^n(x)\}_{n \ge 0}$ is infinite for $x \ne y \in X$, where
$$
L_y^0(x) = x~\textrm{and}~L_y^{i}(x) =L_y \big(L_y^{i-1}(x) \big) ~\textrm{for}~i \ge 1.
$$
\end{enumerate}
\end{proposition}

\begin{proof}
If $x<S_y(x)$ and the $\langle S_y \rangle$-orbit of $x$ is finite, then right-orderability of $X$ implies that  $$x <  S_y(x) <  S_y^2(x) <  \cdots <  S_y^n(x)=x$$ for some integer $n$, which is a contradiction. Similarly, the assertion follows if $S_y(x) < x$.
\para

Suppose that there are elements $x, y, z \in X$ with $y\neq z$, say $y < z$, such that $x * y = x * z$. This is a contradiction to left-orderability of $X$, and hence $X$ must be semi-latin. Further, if $x \ne y$ are two elements of $X$ such that $x = L_y(x)$, then $x * x = y * x$, which contradicts the second quandle axiom. Hence, $x<L_y(x)$ or $L_y(x) < x$. Suppose that $x<L_y(x)$. Since $X$ is left-orderable, we have 
$$
x < L_y(x) < L_y^2(x) < \cdots < L_y^n(x)< \cdots,
$$
and hence $\{L_y^n(x)\}_{n \ge 0}$ is infinite. The case $L_y(x) < x$ is similar.
$\blacksquare$    \end{proof}          

The other sided orderability of quandles in Proposition \ref{conj right orderable} does not hold in general, as shown in \cite[Corollaries 3.8 and 3.9]{MR4450681}.

\begin{proposition}
The following  assertions hold for any non-trivial group $G$:
\begin{enumerate}
\item The quandle $\Conj_n(G)$ is not left-orderable for each $n$.
\item The quandle $\Core(G)$ is not right-orderable.
\item If $\phi\in \Aut(G)$ an involution, then the quandle $\Alex(G,\phi)$ is not right-orderable.
\end{enumerate}
\end{proposition}

\begin{proof}
Since $\Conj_n(G)$ is not semi-latin and $\Core(G)$ is involutory, the assertions follow from Proposition \ref{orderable-implies-latin}. If $\phi \in \Aut(G)$ is an involution, then $\Alex(G, \phi)$ is involutory and we obtain the third assertion.
$\blacksquare$    \end{proof}          


\begin{proposition}\label{orderable quandle infinite}
Any non-trivial left or right-orderable quandle is infinite.
\end{proposition}

\begin{proof}
Let $X$ be a non-trivial quandle that is right-orderable. Then there exist elements $x \neq y$ in $X$ such that $S_y(x)\neq x$. It follows from Proposition \ref{orderable-implies-latin}(1) that the $\left\langle S_y\right\rangle$-orbit of $x$ is infinite, and hence $X$ must be infinite. On the other hand, if $X$ is left-orderable, then by Proposition \ref{orderable-implies-latin}(2), the set $\{L_y^n(x)\}_{n \ge 1}$ is infinite for any $x\neq y$ in $X$, and hence $X$ must be infinite.
$\blacksquare$    \end{proof}          

For free quandles, we have the following result \cite[Theorem 3.5]{MR4450681}.

\begin{theorem}\label{orderability-free-quandle}
Free quandles are right-orderable and semi-latin. In particular, link quandles of trivial links are right orderable.
\end{theorem}

\begin{proof}
Let $S$ be a non-empty set. It is well-known that the free group $F(X)$ on the set $S$ is bi-orderable  (see \cite[Theorem 2.1.9]{Deroin2014} and \cite{MR0031482}). It follows from  Proposition \ref{conj right orderable}(1) that $\Conj \big(F(S)\big)$ is right-orderable. By Proposition \ref{equivalence-two-models}, the free quandle $FQ(S)$ is a subquandle of $\Conj \big(F(S)\big)$, and hence  is right-orderable.
\para

Next, we prove that $FQ(S)$ is semi-latin. If $S$ is a singleton set, then $FQ(S)$ is the one-element trivial quandle and the assertion is evident. Suppose that $|S| > 1$ and there are elements $x, y, z \in FQ(S)$ such that $x \not= y$ and $z * x = z * y$. Since the free quandle $FQ(S)$ is a subquandle of $\Conj \big(F(S)\big)$ consisting of all conjugates of elements of $S$, we can write
$$
z = s_i^{z_0},~~x = s_j^{x_0}~\textrm{and}~y = s_k^{y_0}
$$
for some $s_i, s_j, s_k \in S$ and $z_0, x_0, y_0 \in F(S)$. Here, $a^b$ denotes the element $b^{-1} a b$. The identity $z * x = z * y$ gives
$$
s_i^{z_0 x_0^{-1} s_j x_0} = s_i^{z_0 y_0^{-1} s_k y_0}
$$
in $F(S)$, which is further equivalent to
$$
s_i^{z_0 x_0^{-1} s_j x_0 y_0^{-1} s_k^{-1}  y_0 z_0^{-1}} = s_i.
$$
Such an equality is possible in $F(S)$ if and only if 
\begin{equation} \label{e1}
z_0 x_0^{-1} s_j x_0 y_0^{-1} s_k^{-1}  y_0 z_0^{-1} = s_i^{\alpha}
\end{equation}
for some integer $\alpha$. Taking the quotient of $F(S)$ by its commutator subgroup $[F(S), F(S)]$, equation \ref{e1} gives
$$
\overline{s}_j \, \overline{s}_k^{-1} = \overline{s}_i^{\alpha},
$$
where $\overline{s}_j,  \overline{s}_k,  \overline{s}_i$ are the generators of the free abelian group $F(S)/[F(S), F(S)]$. This implies that $j = k$ and $\alpha = 0$. Thus, \eqref{e1} takes the form
$$
z_0 x_0^{-1} s_j x_0 y_0^{-1} s_j^{-1}  y_0 z_0^{-1} = 1,
$$
which further gives
$$
 s_j x_0 y_0^{-1} s_j^{-1}  y_0 x_0^{-1}= 1.
$$
This equality holds in $F(S)$ if and only if $y_0 x_0^{-1} = s_j^{\beta}$ for some integer $\beta$, that is, $y_0 = s_j^{\beta} x_0$.
Hence, $z, x, y$ have the form
$$
z = s_i^{z_0},~~ x = s_j^{x_0},~~ y= s_j^{x_0},
$$
which contradicts our assumption that $x \ne y$. Hence, $FQ(S)$ is a semi-latin quandle.
$\blacksquare$    \end{proof}          

For free involutory quandles, Propositions \ref{left associated form in quandles} and \ref{Lem:the canonical left associated form} take the following simpler form \cite[Lemma 4.4.2 and Theorem 4.4.4 ]{MR2634013}.

\begin{proposition}\label{free invol quandle element}
Any element in a free involutory quandle can be written in a left-associated product of the form
\begin{equation*}
x_n *x_{n-1}*\cdots *x_1\,,
\end{equation*}
where $x_1,x_2,\ldots,x_n\in S$ with $x_i\neq x_{i+1}$ for each $i$. Further, the multiplication of such products is given by 
\begin{equation*}
(x_n*x_{n-1}*\cdots*x_1)*(y_m*y_{m-1}*\cdots*y_1) = x_n*x_{n-1}*\cdots*x_1*y_1*\cdots*y_{m-1}*y_m*y_{m-1}*\cdots* y_1.
\end{equation*}
\end{proposition}


It also follows from Proposition \ref{orderable-implies-latin}(1) that a non-trivial involutory quandle is not right-orderable. We present the following result regarding the left-orderability of free involutory quandles \cite[Proposition 4.4]{MR4669143}.

\begin{theorem}\label{free invol left orderable} 
Free involutory quandles are left-orderable.
\end{theorem}

\begin{proof}
Let $F(S)$ be the free group on a non-empty set $S$. Recall that, $F(S)$ is the set of all conjugates of elements of $S$ in $F(S)$, equipped with the binary operation of conjugation. Given any involutory quandle $X$ and a set-theoretic map $\varphi: S \to X$, by the universal property of free quandles, $\varphi$ extends to a unique surjective quandle homomorphism $\tilde{\varphi}: FQ(S) \to X$. Since $X$ is involutory, $\tilde{\varphi}$  descends to a quandle homomorphism $\tilde{\varphi}: \big(FQ(S)\big)_2 \to X$, where $\big(FQ(S)\big)_2$ is the involutory quotient of $FQ(S)$. Hence, $\big(FQ(S)\big)_2$ is a model for the free involutory quandle on $S$. In fact, it follows that $\big(FQ(S)\big)_2$ is isomorphic to the subquandle of $\Conj(\hexstar_S \mathbb{Z}_2)$ consisting of all conjugates of generators in the free product $\hexstar_S \mathbb{Z}_2$.
\para

Let $\phi:\big(FQ(S)\big)_2 \to\Core \big(F(S)\big)$ be the map defined by 
\begin{equation*}
\phi(x_n*x_{n-1}*\cdots*x_1) = x_1^{d_1}x_2^{d_2}\cdots x_{n-1}^{d_{n-1}}x_n^{d_n}x_{n-1}^{d_{n-1}}\cdots x_2^{d_2}x_1^{d_1}\,,
\end{equation*} 
where $x_1,x_2,\ldots,x_n\in S$ with $x_i\neq x_{i+1}$ and $d_i=(-1)^{i+1}$ for $1\leq i\leq n$. By Proposition \eqref{free invol quandle element}, it can be checked that $\phi$ is a quandle homomorphism. Further, it turns out that $\phi$ is injective, and hence we have an embedding of $\big(FQ(S)\big)_2$ into $\Core \big(F(S)\big)$. Since free groups are well-known to be bi-orderable (see \cite[Theorem 2.1.9]{Deroin2014} and \cite{MR0031482}), it follows from Proposition \ref{conj right orderable}(2) that $\Core \big(F(S)\big)$ is a left-orderable quandle. Hence, the free involutory quandle $\big(FQ(S)\big)_2$ is left-orderable.
$\blacksquare$    
\end{proof}          

Theorems \ref{orderability-free-quandle} and \ref{free invol left orderable} suggest the following problem.

\begin{problem}
Determine whether free $k$-quandles are left-, right- or bi-orderable for $k \ge 3$.
\end{problem}


\begin{remark}{\rm 
In \cite{MR2069015}, Sikora introduced a natural topology on the set of left-orderings of a group and proved that for a countable group this space is compact, metrisable and totally disconnected. An analogous study was carried out in \cite{MR2320157} for the space of left-orderings on a groupoid. It was proved that such a space is compact and metrisable whenever the groupoid is countable.}
\end{remark}

The preceding remark together with Theorems \ref{orderability-free-quandle} and \ref{free invol left orderable} suggest the following problem.

\begin{problem}
Identify the space of right-orderings on free quandles and the space of left-orderings on free involutory quandles.
\end{problem}

Next, we present the following result for generalised Alexander quandles \cite[Proposition 4.5]{MR4669143}.

\begin{proposition}\label{biordered_alexander_quandle}
Let $<$ be a bi-ordering on a group $G$ and $\phi\in\Aut(G)$. Then the following statements are equivalent:
\begin{enumerate}
\item The linear order $<$ is a bi-ordering on $\Alex(G,\phi)$.
\item If $1$ is the identity element of $G$ and $1 <g$, then $1<\phi(g)<g$.
\end{enumerate}
\end{proposition}

\begin{proof}
For $(1) \Rightarrow (2)$, let $g\in G$ be such that $1<g$. Since $<$ is a bi-ordering on $\Alex(G,\phi)$, we have $1< g*1$ and $1<1*g$. This gives $1<\phi(g)$ and $1<\phi(g)^{-1}g$, and hence
$1<\phi(g)<g$.
\para
For $(2) \Rightarrow (1)$, let $x, y, z \in G$ be such that $x<y$. This gives $1<yx^{-1}$, and hence $1<\phi(y)\phi(x)^{-1}<yx^{-1}$. Since $<$ is a bi-ordering on $G$, it follows that $\phi(x) < \phi(y)$ and  $\phi(x)^{-1}x < \phi(y)^{-1} y$. Again using bi-ordering on $G$, we get  $\phi(x)\phi(z)^{-1}z<\phi(y)\phi(z)^{-1}z$ and $\phi(z)\phi(x)^{-1}x < \phi(z)\phi(y)^{-1}y$. By definition, this gives
$x*z<y*z$ and $z*x<z*y$, which is desired.
$\blacksquare$    \end{proof}          

We conclude by presenting a sufficient condition under which left-orderability fails in quandles.

\begin{proposition}\label{prop11}
Let $X$ be a quandle generated by a set $S$ such that the map $i_X: X \to \Conj \big(\Adj(X)\big)$ is injective. If there exist two distinct commuting elements in $\Adj(X)$ that are not inverses of each other and that are conjugates of elements from $i_X(S)^{\pm 1}$, then the quandle $X$ is not left-orderable.
\end{proposition}

\begin{proof}
Recall from Theorem \ref{presentation-of-adjoint-group} that the set $i_X(S)= \{ \textswab{a}_x \,\mid \,x \in S\}$ is a generating set for the adjoint group $\Adj(X)$. Let $i_X(S)^{-1}$ denote the set of inverses of elements in $i_X(S)$. Let $\textswab{a}_{a},\textswab{a}_{b}\in\Adj(X)$ with ${\textswab{a}_{a}}^{\,\pm1}\neq\textswab{a}_{b}$ be two commuting elements that are conjugates of elements from $i_X(S)^{\pm1}$. Then we can write
\begin{align*}
\textswab{a}_{a}&=\textswab{a}_{x_1}^{-d_1} \textswab{a}_{x_2}^{-d_2}\cdots \textswab{a}_{x_{m-1}}^{-d_{m-1}}\textswab{a}_{x_m}^{d_m}\:\!\textswab{a}_{x_{m-1}}^{d_{m-1}}\cdots \textswab{a}_{x_2}^{d_2}\textswab{a}_{x_1}^{d_1},\\
\textswab{a}_{b}&=\textswab{a}_{y_1}^{-\epsilon_1} \textswab{a}_{y_2}^{-\epsilon_2}\cdots \textswab{a}_{y_{n-1}}^{-\epsilon_{n-1}}\textswab{a}_{y_n}^{\epsilon_n}\:\! \textswab{a}_{y_{n-1}}^{\epsilon_{n-1}}\cdots \textswab{a}_{y_2}^{\epsilon_2} \textswab{a}_{y_1}^{\epsilon_1}\,,
\end{align*}
where $\textswab{a}_{x_i},\textswab{a}_{y_i}\in i_X(X)$ and $d_i,\epsilon_i\in\{-1,1\}$ for all $i$. For each $i$, there exist $x_i,y_i\in X$ such that $\textswab{a}_{x_i}=i_X(x_i)$ and $\textswab{a}_{y_i}=i_X(y_i)$. We see that
\begin{align*}
\textswab{a}_{a}^{d_m}&=i_X(x_1)^{-d_1} i_X(x_2)^{-d_2} \cdots i_X(x_{m-1})^{-d_{m-1}}i_X(x_m)\:\!i_X(x_{m-1})^{d_{m-1}}\cdots i_X(x_2)^{d_2}i_X(x_1)^{d_1}\\
&=i_X(x_m)*^{d_{m-1}}i_X(x_{m-1})*^{d_{m-2}}\cdots*^{d_1}i_X(x_1),~\textrm{by quandle operation in}~ \Conj \big(\Adj(X)\big)\\
&=i_X\!\left(x_m*^{d_{m-1}}x_{m-1}*^{d_{m-2}}\cdots*^{d_1}x_1\right),~\textrm{since $i_X$ is a quandle homomorphism}\\
&=i_X(a),
\end{align*}
and similarly
\begin{equation*}
\textswab{a}_{b}^{\epsilon_n}=i_X(b),
\end{equation*}
where $a=x_m*^{d_{m-1}}x_{m-1}*^{d_{m-2}}\cdots*^{d_1}x_1$ and $b=y_n*^{\epsilon_{n-1}}y_{n-1}*^{\epsilon_{n-2}}\cdots*^{\epsilon_1}y_1$. 
\para

Suppose on the contrary that the quandle $X$ is left-ordered with respect to a linear order $<$. Since $\textswab{a}_{a}^{\pm1}\neq\textswab{a}_{b}$, we get $\textswab{a}_{a}^{d_m}\neq \textswab{a}_{b}^{\epsilon_n}$, and hence $i_X(a)\neq i_X(b)$. This implies that $a\neq b$. Suppose that $a\, <\, b$. Then, we have $a=a*a\, <\, a*b$. Since $\textswab{a}_{b}^{-1}\textswab{a}_{a} \textswab{a}_{b}=\textswab{a}_{a}$, we have $\textswab{a}_{b}^{-1} \textswab{a}_{a}^{d_m}\textswab{a}_{b}=\textswab{a}_{a}^{d_m}$, and hence
\begin{equation*}
i_X(a*^{\epsilon_n}b)=i_X(a)*^{\epsilon_n}i_X(b)=i_X(b)^{-\epsilon_n}i_X(a)i_X(b)^{\epsilon_n}=\textswab{a}_{b}^{-1} \textswab{a}_{a}^{d_m}\textswab{a}_{b}=\textswab{a}_{a}^{d_m}=i_X(a).
\end{equation*}
The map $i_X$ being a monomorphism gives $a*^{\epsilon_n}b=a$, and hence $a*b=a$. Since $a\, <\, a*b$, we get a contradiction.
$\blacksquare$    \end{proof}          


\begin{corollary}
Let $K$ be a prime knot such that its knot quandle $Q(K)$ is generated by a set $X$. If there exist two distinct commuting elements in the knot group $G(K)$ that are not inverses of each other and that are conjugates of elements from $i_{Q(K)}(X)^{\pm1}$, then $Q(K)$ is not left-orderable.
\end{corollary}

\begin{proof}
If $K$ is a prime knot, then by Theorem \ref{prime-quandles-injective-in-adjoint-group}, the map $i_{Q(K)}: Q\left(K\right)\to\Conj \big(G(K)\big)$ is a monomorphism of quandles. The result now follows from Proposition \ref{prop11}.
$\blacksquare$    
\end{proof} 
