\section{Properties of linear orderings on quandles}\label{properties-orderable-quandle}

In this section, we examine basic properties of linear orderings on quandles. Recall that a quandle essentially has two binary operations $*$ and $*^{-1}$. Thus, comprehending the behaviour of a linear order concerning both of these binary operations becomes imperative.
\para

Let $<$ be a linear order on a quandle $X$. We introduce an additional symbol $>$ by writing $y>x$ if and only if $x<y$.  


\begin{definition}
Let $<$ be a linear order on a quandle $X$ and $\mathcal{O}$ be the set $\left\{=,<,>\right\}$. For a quadruple $( \diamond_1, \diamond_2, \diamond_3, \diamond_4)\in\mathcal{O}^4$, the order $<$ is said to be of {\it type} $( \diamond_1, \diamond_2, \diamond_3, \diamond_4)$ if the following  assertions hold for all $x,y,z\in X$ with $x<y$:
\begin{enumerate}[(1)]
\item $x*z\, \diamond_1\, y*z$.
\item $x*^{-1}z\, \diamond_2\, y*^{-1}z$.
\item $z*x\, \diamond_3\, z*y$.
\item $z*^{-1}x\, \diamond_4\, z*^{-1}y$.
\end{enumerate}
We say the order $<$ is of type $(\underline{\;\;}, \diamond_2,\underline{\;\;},\underline{\;\;})$ if the second condition is true, it is of the type $( \diamond_1,\underline{\;\;}, \diamond_3,\underline{\;\;})$ if the first and third conditions are true, it is of the type $( \diamond_1, \diamond_2,\underline{\;\;}, \diamond_4)$ if the first, second and fourth conditions are true, etc.
\end{definition}

The second quandle axiom implies that if $x< y$, then 
\begin{equation}\label{eq17}
x*z\neq y*z\qquad\textrm{and}\qquad x*^{-1}z\neq y*^{-1}z.
\end{equation}
\para

\begin{lemma} \cite[Lemma 3.2]{MR4330281} \label{lem2}
Let $<$ be a linear order on a quandle $X$ and $ \diamond\in\{<,>\}$. Then the order $<$ is of the type $( \diamond,\underline{\;\;},\underline{\;\;},\underline{\;\;})$ if and only if it is of the type $(\underline{\;\;}, \diamond,\underline{\;\;},\underline{\;\;})$.
\end{lemma}

\begin{proof}
Let $ \diamond\in\{<,>\}$. Define $ \diamond^{-1}$ to be $>$ if $ \diamond$ is $<$ and define it as $<$ if $ \diamond$ is $>$. Furthermore, we write $ \diamond^1$ as $ \diamond$. By \eqref{eq17}, we note that $x*z\, \diamond^d\,y*z$ and $x*^{-1}z\, \diamond^e\,y*^{-1}z$ for some $d,e\in\{-1,1\}$ whenever $x,y,z\in X$ and $x<y$.
\para
For the forward implication, suppose on the contrary that $x*^{-1}z\, \diamond^{-1}\,y*^{-1}z$ for some $x,y,z\in X$ with $x<y$. Since the order $<$ is of the type $( \diamond,\underline{\;\;},\underline{\;\;},\underline{\;\;})$, this implies that $\left(x*^{-1}z\right)*z\, \diamond^{-1}\,\left(y*^{-1}z\right)*z$ if $ \diamond$ is $<$ and $\left(x*^{-1}z\right)*z\, \diamond\,\left(y*^{-1}z\right)*z$ if $ \diamond$ is $>$. In other words, $\left(x*^{-1}z\right)*z>\left(y*^{-1}z\right)*z$, that is, $x>y$, which is a contradiction.
\para
For the backward implication, suppose on the contrary that $x*z\, \diamond^{-1}\,y*z$ for some $x,y,z\in X$ with $x<y$. This implies that $\left(x*z\right)*^{-1}z\, \diamond^{-1}\,\left(y*z\right)*^{-1}z$ if $ \diamond$ is $<$ and $\left(x*z\right)*^{-1}z\, \diamond\,\left(y*z\right)*^{-1}z$ if $ \diamond$ is $>$, since the order $<$ is of the type $(\underline{\;\;}, \diamond,\underline{\;\;},\underline{\;\;})$. This gives $\left(x*z\right)*^{-1}z>\left(y*z\right)*^{-1}z$, that is, $x>y$, which is a contradiction.
$\blacksquare$    \end{proof}          

\begin{lemma}\cite[Lemma 3.3]{MR4330281}\label{lem3}
Let $<$ be a linear order on a quandle $X$. Then the following statements are equivalent:
\begin{enumerate}[(1)]
\item The quandle $X$ is trivial.
\item The order $<$ is of the type $(\underline{\;\;},\underline{\;\;},=,\underline{\;\;})$.
\item The order $<$ is of the type $(\underline{\;\;},\underline{\;\;},\underline{\;\;},=)$.
\end{enumerate}
\end{lemma}

\begin{proof}
It is clear that (1) $\Rightarrow$ (2) and (1) $\Rightarrow$ (3).
\para
For (2) $\Rightarrow$ (1), let $x, y \in X$. If $x=y$, then by the idempotency axiom, $x*y=x$. If $x<y$ or $y<x$, then by (2), $x*y=x*x=x$. This proves that $x*y=x$ for all $x,y\in X$.
\para
For (3) $\Rightarrow$ (1), let  $x, y \in X$. If $x=y$, then by the idempotency axiom, $x*y=x$. If $x<y$ or $y<x$, then by (3), $x*^{-1}y=x*^{-1}x=x$. This implies that $(x*^{-1}y)*y=x*y$. Hence, by cancellation, we get $x*y=x$. This proves that $x*y=x$ for all $x,y\in X$.
$\blacksquare$    \end{proof}          

\begin{theorem}\cite[Theorem 3.4]{MR4330281}\label{th2}
Let $<$ be a linear order on a quandle $X$ of type $( \diamond_1, \diamond_2, \diamond_3, \diamond_4)$ for some $( \diamond_1, \diamond_2, \diamond_3, \diamond_4)\in \mathcal{O}^4$. Then the following assertions hold:
\begin{enumerate}[(1)]
\item $ \diamond_1, \diamond_2\in\left\{<,>\right\}$.
\item $ \diamond_1$ and $ \diamond_2$ are the same.
\item The quandle $X$ is trivial $\Leftrightarrow$ $ \diamond_3$ is the equality \textquoteleft\,$=$\textquoteright\, $\Leftrightarrow$ $ \diamond_4$ is the equality \textquoteleft\,$=$\textquoteright\,.
\item The quadruple $( \diamond_1, \diamond_2, \diamond_3, \diamond_4)$ is one of the following:\\
$(<,<,=,=)$,\quad $(<,<,<,>)$,\quad $(<,<,>,<)$\quad{or}\quad $(>,>,<,<)$.
\end{enumerate}
\end{theorem}

\begin{proof}
Assertion (1) follows from \eqref{eq17}, assertion (2) follows from Lemma \ref{lem2}, and assertion (3) follows from Lemma \ref{lem3}. 
\para

If $ \diamond_3$ or $ \diamond_4$ is the equality \textquoteleft\,$=$\textquoteright, then by (3), the quandle $X$ is trivial. In this case, $( \diamond_1, \diamond_2, \diamond_3, \diamond_4)$ must be $(<,<,=,=)$. If $ \diamond_3, \diamond_4\in\left\{<,>\right\}$, then by (1) and (2), $( \diamond_1, \diamond_2, \diamond_3, \diamond_4)$ must be one of the following quadruples:
\begin{align*}
\textrm{(a)}\;\,&(<,<,<,<),&\textrm{(b)}\;\,&(<,<,<,>),&\textrm{(c)}\;\,&(<,<,>,<),&\textrm{(d)}\;\,&(<,<,>,>),\\
\textrm{(e)}\;\,&(>,>,<,<),&\textrm{(f)}\;\,&(>,>,<,>),&\textrm{(g)}\;\,&(>,>,>,<),&\textrm{(h)}\;\,&(>,>,>,>).
\end{align*}
To prove assertion (4), we have to rule out the cases (a), (d), (f), (g) and (h). Let us consider the case (g) first. Suppose that $( \diamond_1, \diamond_2, \diamond_3, \diamond_4)=(>,>,>,<)$. Let $x,y,z\in X$ and $x<y$. Then we have
\begin{align}
\nonumber &z*x>z*y&&(\textrm{since}\, \diamond_3\,\textrm{is}\,>),\\
\nonumber  \Rightarrow\quad&(z*x)*^{-1}x<(z*y)*^{-1}x&&(\textrm{since}\, \diamond_2\,\textrm{is}\,>),\\
\Rightarrow\quad&z<z*y*^{-1}x&&(\textrm{by right cancellation}).\label{eq1 right cancel}
\end{align}
Furthermore, we have
\begin{align*}
\nonumber  &(z*y)*^{-1}x<(z*y)*^{-1}y&&(\textrm{since}\, \diamond_4\,\textrm{is}\,<),\\
\Rightarrow\quad&z*y*^{-1}x<z&&(\textrm{by right cancellation}).
\end{align*}
This is a contradiction to \eqref{eq1 right cancel}, and hence the case (g) does not arise. 
\para

Next, we consider the case (h). Suppose that $( \diamond_1, \diamond_2, \diamond_3, \diamond_4)=(>,>,>,>)$. Let $x,y,z\in X$ and $x<y$. Then we have 
\begin{align}
\nonumber&z*x>z*y&&(\textrm{since}\, \diamond_3\,\textrm{is}\,>),\\
\nonumber \Rightarrow\quad&x*^{-1}(z*x)<x*^{-1}(z*y)&&(\textrm{since}\, \diamond_4\,\textrm{is}\,>),\\
\Rightarrow\quad&x*^{-1}z*x<x*^{-1}y*^{-1}z*y.&& \label{eq2 order}
\end{align}
Furthermore, we have
\begin{align}
\nonumber &\left(x*^{-1}z\right)*x>\left(x*^{-1}z\right)*y&&(\textrm{since}\, \diamond_3\,\textrm{is}\,>),\\
\Rightarrow\quad&x*^{-1}z*x>x*^{-1}z*y. &&\label{eq3}
\end{align}
Combining \eqref{eq2 order} with \eqref{eq3}, we get
\begin{align}
\nonumber &x*^{-1}z*y<x*^{-1}y*^{-1}z*y,&&\\
\nonumber\Rightarrow\quad&\left(x*^{-1}z*y\right)*^{-1}y>\left(x*^{-1}y*^{-1}z*y\right)*^{-1}y&&(\textrm{since}\, \diamond_2\,\textrm{is}\,>),\\
\nonumber\Rightarrow\quad&x*^{-1}z>x*^{-1}y*^{-1}z&&(\textrm{by right cancellation}),\\
\nonumber\Rightarrow \quad&\left(x*^{-1}z\right)*z<\left(x*^{-1}y*^{-1}z\right)*z&&(\textrm{since}\, \diamond_1\,\textrm{is}\,>),\\
\Rightarrow\quad&x<x*^{-1}y&&(\textrm{by right cancellation}).\label{eq4}
\end{align}
We also have
\begin{align*}
&x*^{-1}x>x*^{-1}y&&(\textrm{since}\, \diamond_4\,\textrm{is}\,>),\\
\Rightarrow\quad&x>x*^{-1}y. &&
\end{align*}
This is a contradiction to \eqref{eq4}, and hence the case (h) does not arise. The cases (a), (d) and (f) can be ruled out similarly.
$\blacksquare$    \end{proof}          

\begin{corollary}
Let $<$ be a linear order on a quandle $X$. Then $X$ is trivial if and only if the linear order $<$ is of the type $(<,<,=,=)$.
\end{corollary}

We note that all the four possibilities for the quadruple $( \diamond_1, \diamond_2, \diamond_3, \diamond_4)$ in Theorem \ref{th2}(4) can be realized, as shown by the following example.

\begin{example}\label{ex1}
{\rm
Consider the group $(\mathbb{R},+)$. For a non-zero $u\in\mathbb{R}$, let $\phi_u$ be the automorphism of $\mathbb{R}$ given by $\phi_u(x)=ux$. Then for the Alexander quandle $\Alex(\mathbb{R},\phi_u)$, the quandle operation $*$ and its inverse operation $*^{-1}$ are given by $x*y=ux+(1-u)y$ and $x*^{-1} y=u^{-1}x+\left(1-u^{-1}\right)y$, respectively. With the usual linear order $<$ on $\mathbb{R}$, it is easy to check the following assertions:
\begin{enumerate}[(i)]
\item If $0<u<1$, then $<$ is a bi-ordering on $\Alex(\mathbb{R},\phi_u)$.
\item If $u<1$, then $<$ is a left-ordering on $\Alex(\mathbb{R},\phi_u)$.
\item If $0<u$, then $<$ is a right-ordering on $\Alex(\mathbb{R},\phi_u)$.
\end{enumerate}
Further, the following properties of the ordering $<$ on $\Alex(\mathbb{R},\phi_u)$ can be checked easily.
\begin{enumerate}[(i)]
\item If $u=1$, then the order $<$ is of the type $(<,<,=,=)$.
\item If $0<u<1$, then the order $<$ is of the type $(<,<,<,>)$.
\item If $1<u$, then the order $<$ is of the type $(<,<,>,<)$.
\item If $u<0$, then the order $<$ is of the type $(>,>,<,<)$.
\end{enumerate}}
\end{example}

\begin{remark}{\rm 
For $0<u<1$, the automorphism $\phi_u$ satisfy statement (2) of Proposition \ref{biordered_alexander_quandle}.}
\end{remark}

\begin{remark}{\rm 
It was asked in  \cite[Question 3.6]{MR4450681} whether there exists an infinite non-commutative bi-orderable quandle. We see that for $u\in(0,1)\setminus\left\{\frac{1}{2}\right\}$, the quandle $\Alex(\mathbb{R},\phi_u)$ with the usual order $<$ on $\mathbb{R}$ is an infinite non-commutative bi-orderable quandle, thereby answering the question in an affirmative.}
\end{remark}

Example \ref{ex1} confirms the general result below \cite[Proposition 3.8]{MR4330281}.

\begin{proposition}\label{prop3}
Let $<$ be a linear order on a quandle $X$. Then the order $<$ is a bi-ordering on $X$ if and only if it is of the type $(<,<,<,>)$.
\end{proposition}

\begin{proof}
It is trivial that if the ordering $<$ is of the type $(<,<,<,>)$, then it is a bi-ordering on $X$. Conversely, suppose that $<$ is a bi-ordering on $X$. Then we know that the ordering $<$ is of the type $(<,\underline{\;\;},<,\underline{\;\;})$. Hence, by Lemma \ref{lem2}, the ordering $<$ is of the type $(<,<,<,\underline{\;\;})$. Suppose on the contrary that $<$ is not of the type $(<,<,<,>)$. Then $z*^{-1}x<z*^{-1}y$\, for some $x,y,z\in X$ with $x<y$. This gives
\begin{align}
\nonumber &\left(z*^{-1}y\right)*x<\left(z*^{-1}y\right)*y&&(\textrm{since}\,<\,\textrm{is a left ordering on}\;X),\\
\Rightarrow\quad&z*^{-1}y*x<z&&(\text{by right cancellation})\label{eq16}.
\end{align}
Also, we have
\begin{align*}
&\left(z*^{-1}x\right)*x<\left(z*^{-1}y\right)*x&&(\textrm{since}\,<\,\textrm{is a right ordering on}\;X),\\
\Rightarrow\quad&z<z*^{-1}y*x&&(\text{by right cancellation}).
\end{align*}
But, this contradicts \eqref{eq16}, and hence  $<$ is not of the type $(<,<,<,>)$.
$\blacksquare$   
 \end{proof}          
