\section{Constructions of orderable quandles}\label{construction-order-quandles-automorphisms}

An \textit{action} of a quandle $X$ on a quandle $Y$ is a quandle homomorphism $$\phi : X \to \Conj\big(\Aut(Y)\big),$$ where $\Aut(Y)$ is the group of quandle automorphisms of $Y$. In other words, if $\phi_{x}$ denotes the image of $x$ under $\phi$, then $\phi_{x*y}=\phi_{y}\phi_{x}\phi_{y}^{-1}$. Viewing any set $Y$ as a trivial quandle and noting that $\Aut(Y)=\Sigma_Y$, the symmetric group on $Y$,  we obtain the definition of an action of a quandle $X$ on a set $Y$.

\begin{example}{\rm 
Some basic examples of quandle actions are:
\begin{enumerate}
\item If $X$ is a quandle, then the map $\phi: X \to \Conj \big(\Aut(X)\big)$ given by $q \mapsto S_q$ is a quandle homomorphism. Thus, every quandle acts on itself by inner automorphisms.
\item Let $G$ be a group acting on a set $X$. That is, there is a group homomorphism $\phi: G \to \Sigma_X$. Viewing both $G$ and $\Sigma_X$ as conjugation quandles and observing that a group homomorphism is also a quandle homomorphism between corresponding conjugation quandles, it follows that the quandle $\Conj(G)$ acts on the set $X$.
\end{enumerate}}
\end{example}

We begin with the following result \cite[Theorem 4.2]{MR4330281}.

\begin{theorem}\label{th5}
If a semi-latin quandle is right-orderable, then it acts faithfully on a linearly ordered set by order-preserving bijections. Conversely, if a quandle acts faithfully on a well-ordered set by order-preserving bijections, then it is right-orderable.
\end{theorem}

\begin{proof}
Let $X$ be a semi-latin quandle that is right-ordered with respect to a linear order $<$. Then $\phi: X \to \Conj(\Sigma_X)$ given by $\phi(q)=S_q$ gives an action of $X$ on the ordered set $X$. Further, if $q, x, y \in X$ such that $x<y$, then right-orderability of $X$ implies that
$$\phi(q)(x)=S_q(x)=x*q < y*q=S_q(y)=\phi(q)(y).$$
Further, if $p, q \in X$ such that $\phi(p)=\phi(q)$, then $X$ being semi-latin implies that $p=q$. Hence, $X$ acts faithfully on itself by order-preserving bijections.
\para

Conversely, suppose that $\phi: X \to \Conj(\Sigma_S)$ is a faithful action of a quandle $X$ on a well-ordered set $S$ by order-preserving bijections. Let $<$ be the well-order on $S$. We use the order $<$ to define an order on the quandle $X$ as follows. For $p, q \in X$ with $p \neq q$, consider the set $A_{p, q}=\{x \in S \, \mid \,\phi(p)(x) \neq \phi(q)(x) \}$. Faithfulness of the action implies that $\phi(p) \neq \phi(q)$, and hence $A_{p, q}$ is a non-empty subset of $S$. Since $<$ is a well-ordering on $S$, the set $A_{p, q}$ must admit the smallest element, say $x_0$, with respect to $<$. We define $p\prec q$ if $\phi(p)(x_0) < \phi(q)(x_0)$ and $q\prec p$ if $\phi(q)(x_0) < \phi(p)(x_0)$. 
\para

It is enough to check transitivity of $\prec$ on $X$. Let $p \prec q$ and $ q \prec r$. Let $A_{p, q} = \{ x \in S  \,\mid\, \phi(p)(x) \neq \phi(q)(x) \}$, $A_{q, r} = \{ x \in S  \, \mid \, \phi(q)(x) \neq \phi(r)(x) \}$ and $A_{p, r} = \{ x \in S \, \mid \, \phi(p)(x) \neq \phi(r)(x) \}$. Since $p \prec q$ and $ q \prec r$, it follows that $A_{p, r}$ is non-empty. Let $x_0$, $y_0$ and $z_0$ be the smallest elements of the sets $A_{p, q}$, $A_{q, r}$ and $A_{p, r}$, respectively. Then we have the following cases:
\begin{enumerate}[(i)]
\item If $x _0 < y_0$, then $\phi(p)(x_0) < \phi(q)(x_0)=\phi(r)(x_0)$, which implies that $z_0 \leq x_0$. If $z_0 < x_0$, then $\phi(p)(z_0)=\phi(q)(z_0) \neq \phi(r)(z_0)$, which contradicts the fact that $y_0$ is the smallest element of $A_{q, r} $. Hence, $x_0=z_0$ and $ p \prec r$.
\item If $x_0 = y_0$, then $\phi(p)(x_0) < \phi(q)(x_0)< \phi(r) (x_0)$, which gives $z_0 \leq x_0$. If $z_0 < x_0$, then $\phi(p)(z_0)=\phi(q)(z_0) \neq \phi(r)(z_0)$, which is a contradiction to the fact that $y_0$ is the smallest element of $A_{q, r}$. Hence, $z_0=x_0$ and $p \prec r$.
\item If $x_0 > y_0$, then $\phi(p)(y_0)=\phi(q)(y_0) < \phi(r)(y_0)$, which further gives $z_0 \leq y_0$. If $z_0 < y_0$, then $\phi(p)(z_0)=\phi(q)(z_0) \neq \phi(r)(z_0)$, which is again a contradiction to the fact that $y_0$ is the smallest element of $A_{q, r}$. Hence, $z_0=y_0$ and $ p \prec r$.
\end{enumerate}
Now, suppose that $p, q, r \in X$ such that $p \prec q$. Let $A_{p, q}=\{x \in S \, \mid \,\phi(p)(x) \neq \phi(q)(x) \}$ and $A_{p*r, q*r}=\{x \in S \, \mid \,\phi(p*r)(x) \neq \phi(q*r)(x) \}$. Since both $A_{p, q}$ and $A_{p*r, q*r}$ are non-empty, they admit smallest elements, say $x_0$ and $y_0$, respectively. Note that the bijection $\phi(r)$ maps $A_{p, q}$ onto $A_{p*r, q*r}$. Since $\phi(r)$ is order-preserving with respect to $<$, we have $\phi(r)(x_0)=y_0$. Since $p \prec q$, we have $\phi(p)(x_0) < \phi(q)(x_0)$, which implies that $\phi(p)\phi(r)^{-1}(y_0) < \phi(q)\phi(r)^{-1}(y_0)$. Since $\phi$ is a quandle homomorphism and $\phi(r)$ is order-preserving, this gives 
\begin{eqnarray*}
\phi(p*r)(y_0)&=& \phi(p)*\phi(r)(y_0)\\
&=& \phi(r)\phi(p)\phi(r)^{-1}(y_0) \\
&<& \phi(r)\phi(q)\phi(r)^{-1}(y_0)\\
&=& \phi(q)*\phi(r)(y_0)\\
&=& \phi(q*r)(y_0),
\end{eqnarray*}
and hence $p*r \prec q*r$. Thus, $X$ is a right orderable quandle, and the proof is complete.
$\blacksquare$    \end{proof}          

Next, we give three constructions of orderable quandles. 

\begin{proposition}\label{prop6}
Let $(X_1,*)$ and $(X_2,\circ)$ be right-orderable quandles and $\sigma: X_1 \to \Conj\big(\Aut(X_2) \big)$ and $\tau: X_2 \to \Conj\big(\Aut(X_1) \big)$ be order-preserving quandle actions. Suppose that
\begin{enumerate}
\item $\tau(z)(x)* y=\tau\big(\sigma(y)(z)\big)(x* y)$ for $x, y \in X_1$ and $z \in X_2$,
\item $\sigma(z)(x)\circ y=\sigma\big(\tau(y)(z)\big)(x\circ y)$ for $x, y \in X_2$ and $z \in X_1$.
\end{enumerate}
Then $X=X_1 \sqcup X_2$ with the binary operation
$$
x\star y=\begin{cases}
x*y& \textrm{if}~~~x, y \in X_1, \\
x\circ y &\textrm{if}~~~ x, y \in X_2, \\
{\tau(y)}(x) &\textrm{if}~~~x \in X_1, y \in X_2, \\
{\sigma(y)}(x) &\textrm{if}~~~x \in X_2, y \in X_1,
\end{cases} 
$$
is a right-orderable quandle.
\end{proposition}

\begin{proof}
It follows from Proposition \ref{new2} that $X$ is a quandle. Let $<_1$ and $<_2$ be the right-orders on $X_1$ and $X_2$, respectively. Define an order $<$ on $X$ by setting $x< y$ if $x, y \in X_1$ and $x<_1 y$ or $x, y \in X_2$ and $x<_2 y$ or $x\in X_1$ and $y \in X_2$. A direct check shows that $<$ is indeed a linear order on $X$. We claim that $<$ turns $X$ into a right orderable quandle. Let $x, y, z \in X$ such that $x<y$. We have the following cases:
\begin{enumerate}[(i)]
\item $x, y, z \in X_1$ or $x, y,z \in X_2$: In this case, since $X_1$ and $X_2$ are right-orderable, we get $x\star z < y\star z$.
\item $x, y \in X_1$ and $z \in X_2$: In this case, since $\tau(z)$ is order preserving, we have $x \star z=\tau(z)(x) <_1 \tau(z)(y)=y \star z$, and hence $x \star z < y \star z$.
\item $x, y \in X_2$ and $z \in X_1$: In this case, $\sigma(z)$ being order preserving implies that $x \star z=\sigma(z)(x) <_2 \sigma(z)(y)=y \star z$, and hence $x \star z < y \star z$.
\item $x, z \in X_1$ and $y \in X_2$: In this case, $x \star z= x*z \in X_1$ and $y \star z= \sigma(z)(y) \in X_2$, and hence $x \star z < y \star z$.
\item $x \in X_1$ and $y, z \in X_2$: In this case, $x \star z= \tau(z)(x) \in X_1$ and $y \star z= y \circ z \in X_2$, and hence $x \star z < y \star z$.
\end{enumerate}
Thus, $X$ is a right-orderable quandle.
$\blacksquare$    \end{proof}          

If $\sigma: X_1 \to \id_{X_2}$ and $\tau: X_2 \to \id_{X_1}$ are the trivial actions, then conditions (1) and (2) of Proposition \ref{prop6} always hold. Thus, the disjoint union of two right-orderable quandles is right-orderable. It is clear that the disjoint union of two left-orderable quandles is not left-orderable. For example, any trivial quandle with more than one element is not left-orderable.
\para

Let $\{X_i, *_i\}_{i \in \Lambda}$ be a family of quandles and $X= \prod_{i \in \Lambda} X_i$ their cartesian product. Then $X$ is a quandle with $(x_i)\star (y_i)= (x*_i y_i)$ and called the {\it product quandle}. The following observation is rather immediate.

\begin{proposition}\label{prop1}
The product of right-orderable quandles is a right-orderable quandle. Similarly, the product of left-orderable (bi-orderable) quandles is a left-orderable (bi-orderable) quandle.
\end{proposition}

\begin{proof}
Let $\{X_i, *_i\}_{i \in \Lambda}$ be a family of right-orderable quandles. Let $<_i$ be the right-order on $X_i$ for $i \in \Lambda$ and $X$ their product quandle. By axiom of choice, we can take a well-ordering $<$ on the indexing set $\Lambda$. Let $(x_i), (y_i) \in X$ such that $(x_i) \neq (y_i)$. Then there exists the least index $\ell \in \Lambda$ such that $x_\ell \neq y_\ell$. We define $(x_i) \prec (y_i)$ if $x_\ell <_\ell y_\ell$ and $(y_i) \prec (x_i)$ if $y_\ell <_\ell x_\ell$. It is easy to check that $\prec$ is a linear order on $X$.
\para

Let $(x_i), (y_i), (z_i) \in X$ such that $(x_i) \prec (y_i)$. Then $x_\ell <_\ell y_\ell$, where $\ell$ is the least index such that $x_\ell \neq y_\ell$. The second quandle axiom in $X$ implies that $(x_i *_i z_i)= (x_i)\star(z_i) \neq (y_i) \star (z_i)=(y_i *_i z_i)$. It turns out that $\ell$ is also the least index for which $x_\ell *_\ell z_\ell \neq y_\ell *_\ell z_\ell$. Since $x_\ell <_\ell y_\ell$ and $X_\ell$ is right orderable, it follows that $x_\ell *_\ell z_\ell <_\ell y_\ell *_\ell z_\ell$. By definition of $\prec$, we have $ (x_i)\star(z_i) \prec (y_i) \star (z_i)$. Thus, $X$ is a right-orderable quandle. The second assertion follows analogously.
$\blacksquare$    \end{proof}          
\medskip

The construction of free racks and free quandles was generalised in  \cite{MR4129183}, which we discuss next. Let $G$ be a group and $A$ a subset of $G$. Then the set $A \times G$ becomes rack under the following binary operation
\begin{equation*}
(a,u)*(b,v)= (a, vbv^{-1} u)
\end{equation*}
for $a,b\in A$ and $u,v\in G$. The rack defined as above is known as a $(G,A)$-rack and is denoted by $R(G,A)$. 
\para

Let $Q(G,A)$ be the quotient of the set $A \times G$ by the equivalence relation $(a, vu) \sim (a,u)$ if and only if $v \in \C_G(a)=\{x \in G \,\mid \, xa=ax\}$. Let $[(a,u)] \in Q(G,A)$ denote the equivalence class of $(a,u) \in A \times G$. The set $Q(G,A)$ becomes quandle under the binary operation
\begin{equation*}
[(a,u)]*[(b,v)]= [(a,vbv^{-1}u)]
\end{equation*}
for $a,b\in A$ and $u,v\in G$, and this quandle is known as a $(G,A)$-quandle. For simplicity of notation, we write $(a,u)$ instead of $[(a,u)]$ throughout this section. There is a natural rack homomorphism $\epsilon: R(G,A) \to \Conj(G)$ defined as $\epsilon(a,u)=u^{-1}a u$. Moreover, this map induces a quandle homomorphism $\overline{\epsilon}: Q(G, A) \to \Conj(G)$ defined as $\overline{\epsilon}(a,u)=u^{-1} a u$.
\para

We prove the following result \cite[Theorem 5.1]{MR4330281}.

\begin{theorem}\label{th3}
Let $G$ be a group and $A$ a subset of $G$. Then the following assertions hold:
\begin{enumerate}
\item If $G$ is right-orderable, then the rack $R(G,A)$ is right-orderable.
\item If $G$ is bi-orderable, then the quandle $Q(G,A)$ is right-orderable.
\end{enumerate}
\end{theorem}

\begin{proof}
Let $<$ be a right ordering on $G$. We define a linear order $<'$ on $R(G,A)$ as follows. Let $(a,u)$ and $(b,v)$ be two distinct elements of $R(G,A)$.
\begin{enumerate}[(i)]
\item If $a \neq b$, define $(a,u)<'(b,v)$ if $a<b$ and $(b,v)<'(a,u)$ if $b<a$.
\item If $a=b$, define $(a,u)<'(a,v)$ if $u<v$ and $(a,v)<'(a,u)$ if $v<u$.
\end{enumerate}
Let $(a,u), (b,v), (c,w) \in R(G,A)$ such that $(a,u)<'(b,v)$. If $a \neq b$, then $a<b$, and hence $(a,u)*(c,w)<'(b,v)*(c,w)$. If $a=b$, then $u<v$. Since $G$ is right-ordered with respect to $<$, it follows that $uw^{-1}cw<vw^{-1}cw$, and hence $(a,u)*(c,w)<'(a,v)*(c,w)$. This shows that $R(G,A)$ is a right-orderable rack, which is assertion (1).
\medskip

Let $<$ be a bi-ordering on $G$. Define a linear order $<'$ on $Q(G,A)$ as follows. Let $(a,u)$ and $(b,v)$ be two distinct elements of $Q(G,A)$. 
\begin{enumerate}[(i)]
\item If $a \neq b$, then define $(a,u)<'(b,v)$ if $a<b$ and $(b,v)<'(a,u)$ if $b<a$.
\item If $a=b$, then we define the order using the image of $(a,u)$ and $(a,v)$ under the map $\overline{\epsilon}: Q(G,A) \to G$. Note that, if $(a,u) \neq (a,v)$ in $Q(G,A)$, then $\overline{\epsilon}(a,u)\neq \overline{\epsilon}(a,v)$. For, if $u^{-1}au=v^{-1}av$, then $vu^{-1}a=a vu^{-1}$; this implies that $vu^{-1} \in C_G(a)$ and hence $(a,u) =(a,v)$. Now, define $(a,u)<'(a,v)$ if $u^{-1} a u<v^{-1} a v$ and $(a,v)<'(a,u)$ if $v^{-1}av<u^{-1}au$.
\end{enumerate}
We claim that $Q(G,A)$ is right-ordered with respect to $<'$. Let $(a,u), (b,v), (c,w) \in R(G,A)$ such that $(a,u)<'(b,v)$. If $a \neq b$, then $a<b$, and hence $(a,u)*(c,w)<'(b,v)*(c,w)$. If $a=b$, then $u^{-1}au<v^{-1} a v$. Since $G$ is bi-ordered with respect to $<$, we have $w^{-1}c^{-1}wu^{-1}auw^{-1}cw<w^{-1}c^{-1}wv^{-1}avw^{-1}cw$, and hence $(a,u)*(c,w)<'(a,v)*(c,w)$. This shows that $Q(G,A)$ is right-orderable, which is assertion (2).
$\blacksquare$    
\end{proof}          

\begin{corollary}
Free racks are right-orderable.
\end{corollary}

\begin{proof}
Recall from Section \ref{section free quandles} of Chapter \ref{chapter preliminaries on racks and quandles} that the free rack $FR(A)$ on a set $A$ is the rack $R \big(F(A),A \big)$, where $F(A)$ is the free group on $A$. Since $F(A)$ is right-orderable, the result follows from Theorem \ref{th3}(1). $\blacksquare$    
\end{proof}

\begin{remark}
{\rm If $A$ is a set of representatives of conjugacy classes of a group $G$, then $Q(G, A)\cong \Conj(G)$, and we recover Proposition \ref{conj right orderable}(1). Similarly, if $G$ is the free group on a set $A$, then  $Q(G, A)$ is the free quandle on $A$, and we retrieve Theorem \ref{orderability-free-quandle}.}
\end{remark}
\bigskip
\bigskip

