\section{Orderability of link quandles}\label{orderability-knot-quandle}
Problem 3.16 in \cite{MR4450681} asked whether link quandles are orderable. In this section, we investigate orderability of link quandles and provide solution to this problem in some cases. We begin with the following result.

\begin{proposition}\label{prop4}
Let $X$ be a quandle such that the natural map $i_X:X\to \Conj \big(\Adj(X) \big)$ is injective. If $\Adj(X)$ is a bi-orderable group, then $X$ is a right-orderable quandle.
\end{proposition} 

\begin{proof}
Since $\Adj(X)$ is a bi-orderable group, by Proposition \ref{conj right orderable}(1), $\Conj \big(\Adj(X) \big)$ is a right-orderable quandle. Since $i_X$ is injective, it follows that $X$ is right-orderable.
$\blacksquare$    \end{proof}           

\begin{corollary}
If $X$ is a commutative, latin or simple quandle such that $\Adj(X)$ is a bi-orderable group, then $X$ is right-orderable.
\end{corollary}

\begin{proof}
It is not difficult to see that the map $i_X$ is injective for a commutative, latin or simple quandle.
$\blacksquare$    \end{proof}          

\begin{corollary}\label{cor1}
If the knot group of a prime knot is bi-orderable, then its knot quandle is right-orderable.
\end{corollary}

\begin{proof}
Let $K$ be a prime knot such that its knot group $G(K)$ is bi-orderable. Since $K$ is prime, by Theorem \ref{prime-quandles-injective-in-adjoint-group}, the map $i_X: Q\left(K\right)\to \Conj \big(G(K)\big)$ is injective. Hence, by Proposition \ref{prop4}, the knot quandle $Q\left(K\right)$ is right-orderable.
$\blacksquare$    \end{proof}          

\begin{corollary}\label{cor4}
If all the roots of the Alexander polynomial of a fibered prime knot are real and positive, then its knot quandle is right-orderable.
\end{corollary}

\begin{proof}
Let $K$ be a fibered prime knot all the roots of whose Alexander polynomial are real and positive. Then, by \cite[Theorem 1.1]{MR1990838}, the knot group $G(K)$ is bi-orderable. The result now follows from Corollary \ref{cor1}.
$\blacksquare$    \end{proof}          

As a special case, it follows that the knot quandle of the figure eight knot is right-orderable.
\medskip

Next, we focus on orderability of link quandles of torus links. Recall that, two links $L_1$ and $L_2$ are called {\it weakly equivalent} if $L_1$ is ambient isotopic to either $L_2$ or the reverse of the mirror image of $L_2$. It is known that link quandles of weakly equivalent links are isomorphic \cite[Theorem 5.2 and Corollary 5.3]{MR1194995}. For any $m,n\geq1$, since the torus link $T(m,n)$ is invertible, it is weakly equivalent to its reverse, mirror image and the reverse of its mirror image, and hence their link quandles are isomorphic to that of $T(m,n)$. Recall that a torus link $T(m,n)$ is a knot (a one component link) if and only if $\gcd(m,n)=1$.
\para

We begin with the following result \cite[Proposition 7.1]{MR4330281}.

\begin{proposition}\label{prop5}
The link quandle of the torus link $T(m,n)$ is generated by $a_1,\ldots,a_m$ and has the following defining relations
\begin{equation*}
a_i=a_{n+i}*a_n*a_{n-1}*\cdots*a_1\quad\textrm{for}\;\;1 \le i \le m,
\end{equation*}
where $a_{mj+k}=a_k$ for $j\in\mathbb{Z}$ and $1 \le k \le m$.
\end{proposition}

\begin{proof}
Since a torus link $T(m,n)$ is the closure of the braid $\tau(m,n)=\left(\sigma_1\sigma_2\cdots\sigma_{m-1}\right)^n$, with reference to Figure \ref{toricbraid2}, it is enough to prove that
\begin{equation}\label{eq5}
c_i=a_{n+i}*a_n*a_{n-1}*\cdots*a_1\quad\textrm{for}\;\;1 \le i \le m.
\end{equation}

\begin{figure}[hbtp]
\centering
\includegraphics[height=2.8cm]{toric-braid2.pdf}
\caption{Toric braid $\tau(m, n)$.}
\label{toricbraid2}
\end{figure}

We prove \eqref{eq5} by induction on $n$. Observing Figure \ref{toricbraid3}, we see that $c_i=a_{i+1}*a_1$ for $1 \le i \le m$.
\begin{figure}[hbtp]
\centering
\includegraphics[height=3.6cm]{toric-braid3.pdf}
\caption{Toric braid $\tau(m, 1)$.}
\label{toricbraid3}
\end{figure}
 Thus,  \eqref{eq5} hold for $n=1$. Suppose that \eqref{eq5} hold for a positive integer $n-1$. Since $\tau(m,n)=\tau(m,n-1)\tau(m,1)$ (see Figure \ref{toricbraid}), we have 
\begin{equation}\label{eq6}
c_i=b_{i+1}*b_1 \quad\textrm{for}\;\;1 \le i \le m
\end{equation}
where $b_{m+1}=b_1$. By induction hypothesis, we have
\begin{equation}\label{eq7}
b_{i+1}=a_{n+i}*a_{n-1}*a_{n-2}*\cdots*a_1\quad\textrm{for}\;\;1 \le i \le m.
\end{equation}


\begin{figure}[hbtp]
\centering
\includegraphics[height=5.6cm]{toric-braid.pdf}
\caption{Toric braid $\tau(m, n)$ seen as  $\tau(m, n-1)$ $\tau(m, 1)$.}
\label{toricbraid}
\end{figure}

\noindent Using \eqref{eq7} in \eqref{eq6}, we get
\begin{align*}
c_i&=\left(a_{n+i}*a_{n-1}*a_{n-2}*\cdots*a_1\right)*\left(a_n*a_{n-1}*a_{n-2}*\cdots*a_1\right)\\
&=a_{n+i}*a_{n-1}*a_{n-2}*\cdots*a_1*^{-1}a_1*^{-1}a_2*^{-1}\cdots*^{-1}a_{n-1}*a_n*a_{n-1}*\cdots*a_1\\
&=a_{n+i}*a_n*a_{n-1}*\cdots*a_1\quad\;\textrm{for}\;\;1 \le i \le m.
\end{align*}
This proves that \eqref{eq5} hold for all $n$. $\blacksquare$    
\end{proof}          

If $<$ is a right-ordering on a quandle $X$ and $x,y,z_1,z_2,\ldots,z_n\in X$ with $x\, \diamond\, y$ for $ \diamond\in\{<,>\}$, then we have
\begin{equation}\label{eq14}
x*z_1*z_2*\cdots*z_n\, \diamond\, y*z_1*z_2*\cdots*z_n~\textrm{and}~
x*^{-1}z_1*^{-1}z_2*^{-1}\cdots*^{-1}z_n\, \diamond\, y*^{-1}z_1*^{-1}z_2*^{-1}\cdots*^{-1}z_n.
\end{equation}

We now present the main result of this section \cite[Theorem 7.2]{MR4330281}.

\begin{theorem}\label{th4}
Let $m,n\geq2$ be integers such that one is not a multiple of the other. Then the link quandle of the torus link $T(m,n)$ is not right-orderable.
\end{theorem}

\begin{proof}
Note that the torus links $T(m,n)$ and $T(n,m)$ are ambient isotopic. Thus, we can assume that $m<n$ by switching $m$ and $n$, if required. If $d=\gcd(m,n)$, then $d<m$. By Proposition \ref{prop5}, the link quandle $Q \big(T(m,n) \big)$ is generated by $a_1,\ldots,a_m$ and has relations
\begin{equation}\label{eq10}
a_i=a_{n+i}*a_n*a_{n-1}*\cdots*a_1\quad\textrm{for}\;\;1 \le i \le m,
\end{equation}
where $a_{mj+k}=a_k$ for $j\in\mathbb{Z}$ and $1 \le k \le m$. Using \eqref{eq10}, we obtain
\begin{equation}\label{eq11}
a_i=a_{n+i}*a_n*a_{n-1}*\cdots*a_1\quad\textrm{for all}\;\;i\in\mathbb{Z},
\end{equation}
where $a_{mj+k}=a_k$ for $j\in\mathbb{Z}$ and $1 \le k \le m$. We can rewrite \eqref{eq11} as
\begin{equation}\label{eq12}
a_{i-n}=a_i*a_n*a_{n-1}*\cdots*a_1\quad\textrm{for all}\;\;i\in\mathbb{Z}.
\end{equation}
\noindent Also, \eqref{eq11} can be written as 
\begin{equation}\label{eq13}
a_{n+i}=a_i*^{-1}a_1*^{-1}a_2*^{-1}\cdots*^{-1}a_n\quad\textrm{for all}\;\;i\in\mathbb{Z}.
\end{equation}

Suppose on the contrary that the quandle $Q \big(T(m,n)\big)$ is right-ordered with respect to a linear order $<$. By the proof of Proposition \ref{prop5} (see Figures \ref{toricbraid2}, \ref{toricbraid3} and \ref{toricbraid}), the generators $a_1,\ldots,a_m$ of $Q \big(T(m,n)\big)$ correspond to some of the arcs in the standard diagram of the closed toric braid representing $T(m,n)$.  Note that $i_X(a_1),\ldots,i_X(a_m)$ are the meridional elements that generate the link group $G\big(T(m,n)\big)$, where $i_X:Q\big(T(m,n)\big)\to G\big(T(m,n)\big)$ is the natural map. According to \cite[Corollary 1.5]{MR0889376}, the elements $i_X(a_1),\ldots,i_X(a_m)$ must be pairwise distinct in $G \big(T(m,n)\big)$, and hence so are the elements $a_1,\ldots,a_m$ in $Q\big(T(m,n)\big)$. In particular, we have $a_1\neq a_{d+1}$, and hence $a_1\, \diamond\, a_{d+1}$ for some $ \diamond\in\{<,>\}$. A repeated application of \eqref{eq14} together with \eqref{eq12} and \eqref{eq13} yields
\begin{equation}\label{eq15}
a_{nk+1}\, \diamond\, a_{nk+d+1}\quad\textrm{for all}\;\;k\in\mathbb{Z}.
\end{equation}
Let $l$ be an integer. Since $\gcd(m,n)=d$, we have $dl=mj+nk$ for some integers $j$ and $k$. This implies that $nk+1\equiv dl+1\;(\!\!\!\!\mod m)$ and $nk+d+1\equiv dl+d+1\;(\!\!\!\!\mod m)$. By \eqref{eq15}, we have $a_{dl+1}\, \diamond\, a_{dl+d+1}$. Thus, $a_{dl+1}\, \diamond\, a_{dl+d+1}$ for any integer $l$. Using this repeatedly, we get $a_1\, \diamond\, a_{d+1}\, \diamond\, a_{2d+1}\, \diamond\,\cdots\, \diamond\, a_{cd+1}\, \diamond\, a_1$, where $c=\frac{m}{d}-1$. This implies that $a_1<a_1$ or $a_1>a_1$, a contradiction.
$\blacksquare$    \end{proof}          

As a consequence of Theorem \ref{th4}, we retrieve the following result of Perron and Rolfsen \cite[Proposition 3.2]{MR1990838}.

\begin{corollary}\label{cor3}
The knot group of a non-trivial torus knot is not bi-orderable.
\end{corollary}

\begin{proof}
Let $K$ be a non-trivial torus knot. By Theorem \ref{th4}, the knot quandle of $K$ is not right-orderable. Hence, by Corollary \ref{cor1}, the knot group of $K$ is not bi-orderable.
$\blacksquare$    \end{proof}          

We conclude with the following result.

\begin{corollary}
The knot quandle of the trefoil knot is neither left nor right orderable.
\end{corollary}

\begin{proof}
Note that the trefoil knot is the torus knot $T(2,3)$. By Theorem \ref{th4}, the knot quandle $Q\big(T(2,3)\big)$ is not right-orderable. We claim that it is not left-orderable as well. The quandle $Q\big(T(2,3)\big)$ is generated by $a_1, a_2$ and has  relations 
\begin{align}
a_1&=a_2*a_1*a_2,\label{eq8}\\
a_2&=a_1*a_2*a_1.\label{eq9}
\end{align}
Assume contrary that $Q\big(T(2,3)\big)$ is left-ordered with respect to a linear order $<$. Since $Q\big(T(2,3)\big)$ is non-trivial, we must have $a_1\neq a_2$. Hence, $a_1\, \diamond\, a_2$ for some $ \diamond\in\{<,>\}$. We see that
\begin{align*}
&\quad a_1\, \diamond\, a_2&&\\
\Rightarrow&\quad a_1*a_1\, \diamond\, a_1*a_2&&\textrm{(since $<$ is left-ordering)},\\
\Rightarrow&\quad a_1\, \diamond\, a_1*a_2&&\textrm{(by idempotency)},\\
\Rightarrow&\quad a_2*a_1\, \diamond\, a_2*(a_1*a_2)&&\textrm{(since $<$ is left-ordering)},\\
\Rightarrow&\quad a_2*a_1\, \diamond\, a_2*a_1*a_2,&&\\
\Rightarrow&\quad a_2*a_1\, \diamond\, a_1&&\textrm{(by \eqref{eq8})},\\
\Rightarrow&\quad a_1*(a_2*a_1)\, \diamond\, a_1*a_1&&\textrm{(since $<$ is left-ordering)},\\
\Rightarrow&\quad a_1*a_2*a_1\, \diamond\, a_1,&&\\
\Rightarrow&\quad a_2\, \diamond\, a_1&&\textrm{(by \eqref{eq9})}.
\end{align*}
This gives a contradiction, since we cannot have $a_1\, \diamond\, a_2$ and $a_2\, \diamond\, a_1$ together.
$\blacksquare$   
 \end{proof} 

\begin{remark}
{\rm 
Further work on the orderability of knot quandles includes a non-left-orderability criterion for involutory quandles of non-split links \cite{arXiv.2310.05735}, used to show that those of non-trivial alternating links are not left-orderable. Biorderability of knot quandles for prime knots up to eight crossings has also been studied \cite{arXiv:2505.19573}.
}
\end{remark}

