\chapter{Quandle rings and algebras}\label{chaper quandle rings}

\begin{quote}
This chapter explores the construction and properties of quandle rings and algebras, drawing analogies with the classical theory of group rings and algebras. We examine fundamental aspects of quandle rings and how their algebraic structure reflects the properties of the underlying quandles. Key topics include power-associativity, commutator width, and the behavior of associated graded rings. The chapter also includes a discussion of the isomorphism problem for quandle rings, highlighting structural challenges and open questions in the field.
\end{quote}
\bigskip


\section{Properties of quandle rings and algebras}\label{section1 of chap quandle rings}
Let $(X, *)$ be a quandle and $\mathbb{k}$ an associative ring with unity {\bf 1}.  Let $e_x$ be a unique symbol corresponding to each $x \in X$. Let $\mathbb{k}[X]$ be the set of all formal expressions of the form $\sum_{x \in X }  \alpha_x e_x$, where $\alpha_x \in \mathbb{k}$ such that all but finitely many $\alpha_x=0$.  The set $\mathbb{k}[X]$ has a free $\mathbb{k}$-module structure with basis $\{e_x \, \mid \, x \in X \}$ and admits a product given by 
 $$ \Big( \sum_{x \in X }  \alpha_x e_x \Big) \Big( \sum_{ y \in X }  \beta_y e_y \Big)
 =   \sum_{x, y \in X } \alpha_x \beta_y e_{x * y},$$
where $x, y \in X$ and $\alpha_x, \beta_y \in \mathbb{k}$. This turns $\mathbb{k}[X]$ into a ring (rather a $\mathbb{k}$-algebra) called the \index{quandle ring} {\it quandle ring} or the \index{quandle algebra} {\it quandle algebra} of $X$ with coefficients in $\mathbb{k}$. Even though the coefficient ring $\mathbb{k}$ is associative, the quandle ring $\mathbb{k}[X]$ is non-associative when $X$ is a non-trivial quandle. The quandle $X$ can be identified as a subset of $\mathbb{k}[X]$ via the natural map $x \mapsto {\bf 1}e_x=e_x$.  We will see that, unlike groups, the quandle ring structure of a trivial quandle is interesting in its own.

\begin{remark}{\rm 
 If $X$ is a rack, then $\mathbb{k}[X]$ is referred to as the \index{rack ring}{\it rack ring} or the \index{rack algebra} {\it rack algebra} of $X$ with coefficients in $\mathbb{k}$. Most of the concepts introduced in this chapter also apply to racks.}
\end{remark}

\begin{remark}{\rm 
Note that a quandle with a (left) identity element has only one element. Thus, $\mathbb{k}[X]$ is a non-associative ring without unity, unless $X$ has only one element.}
\end{remark}


Analogous to group rings, we define the \index{augmentation map} {\it augmentation map}
$$\varepsilon: \mathbb{k}[X] \to \mathbb{k}$$
 by setting $$\varepsilon \Big(\sum_{x \in X} \alpha_x e_x \Big)= \sum_{x \in X} \alpha_x.$$
Clearly, $\varepsilon$ is a surjective ring homomorphism. Let $\Delta_{\mathbb{k}}(X)$ be the kernel of the homomorphism $\varepsilon$. Then $\Delta_{\mathbb{k}}(X)$ is a two-sided ideal of $\mathbb{k}[X]$ and referred to as the {\it augmentation ideal} of $\mathbb{k}[X]$. Further, we have
$$\mathbb{k}[X]/\Delta_{\mathbb{k}}(X) \cong \mathbb{k}$$ as rings. In the case $\mathbb{k} = \mathbb{Z}$, we denote the augmentation ideal simply by $\Delta(X)$. The following result is straightforward.


\begin{proposition}
Let $X$ be a rack and $\mathbb{k}$ an associative ring with unity. Then $\{e_x- e_y\,\mid\,x, y \in X \}$ is  a generating set for $\Delta_{\mathbb{k}}(X)$ as a $\mathbb{k}$-module. Further, if $x_0 \in X$ is a fixed element, then the set $\big\{e_x-e_{x_0} \,\mid\, x \in X \setminus \{ x_0\} \big\}$ is a basis for $\Delta_{\mathbb{k}}(X)$ as an $\mathbb{k}$-module.
\end{proposition}

The following is a noteworthy observation.

\begin{proposition}
Let $X$ be a quandle and $\mathbb{k}$ an associative ring with unity. Then $e_x e_y+ e_y e_x \equiv e_x+e_y~ \mod \Delta_{\mathbb{k}}^2(X)$ for all $x, y \in X$.
\end{proposition}

\begin{proof}
It follows from the first quandle axiom that $e_x^2=e_x$ in $\mathbb{k}[X]$ for all $x \in X$. We see that
\begin{eqnarray*}
e_x & = & (e_x-e_y+e_y)^2\\
& = & (e_x-e_y)^2+e_y^2+(e_x-e_y) e_y+e_y(e_x-e_y)\\
& \equiv & e_x e_y+e_y e_x-e_y \mod  \Delta_{\mathbb{k}}^2(X),
\end{eqnarray*}
and hence $e_x e_y+e_y e_x \equiv e_x+e_y \mod \Delta_{\mathbb{k}}^2(X)$ for all $x, y \in X$. $\blacksquare$
\end{proof}

Clearly, if $Y$ is a subrack of a rack $X$, then $\Delta_{\mathbb{k}}(Y) \subseteq \Delta_{\mathbb{k}}(X)$. It is natural to look for conditions under which $\Delta_{\mathbb{k}}(Y)$ is a two-sided ideal of $\mathbb{k}[X]$. For trivial racks, we have the following result.

\begin{proposition}
Let $X$ be a trivial rack, $Y$ a subrack of $X$ and $\mathbb{k}$ an associative ring with unity. Then $\Delta_{\mathbb{k}}(Y)$ is a two-sided  ideal of $\mathbb{k}[X]$.
\end{proposition}

\begin{proof}
Note that $\Delta_{\mathbb{k}}(Y)$ is generated as an $\mathbb{k}$-module by the set $\{e_y-e_z \,\mid \,y,z \in Y \}$. Then, for any $\sum_{x \in X}\alpha_x e_x \in \mathbb{k}[X]$, we have
$$\big(\sum_{x \in X} \alpha_x e_x\big)(e_y -e_z)=\sum_{x \in X} \alpha_x (e_x e_y - e_x  e_z)=\sum_{x \in X}\alpha_x (e_x - e_x)= 0 \in \Delta_{\mathbb{k}}(Y),$$
and
$$(e_y -e_z) \big(\sum_{x \in X}\alpha_x e_x\big)=\sum_{x \in X}\alpha_x (e_y  e_x -e_z  e_x)=\sum_{x \in X}\alpha_x (e_y -e_z) \in \Delta_{\mathbb{k}}(Y).$$
Hence, $\Delta_{\mathbb{k}}(Y)$ is a two-sided ideal of $\mathbb{k}[X]$. $\blacksquare$
\end{proof}


The next result characterises trivial quandles in terms of their augmentation ideals \cite[Theorem 3.5]{MR3977818}.

\begin{theorem}\label{deltasqzero}
Let $X$ be a quandle and $\mathbb{k}$ an associative ring with unity. Then $X$ is trivial if and only if $\Delta_{\mathbb{k}}^2(X)=\{0\}$.
\end{theorem}

\begin{proof}
Suppose that $\Delta_{\mathbb{k}}^2(X)=\{0\}$. Let $x_0 \in X$ be a fixed element. Observe that $\Delta_{\mathbb{k}}^2(X)$ is generated as an $\mathbb{k}$-module by the set $\big\{(e_x-e_{x_0})(e_y-e_{x_0}) \, \mid \, x, y \in X\setminus \{x_0 \} \big\}$. It follows that $(e_x-e_{x_0})(e_y-e_{x_0})=0$ for all $x, y \in X\setminus \{x_0 \}$. In particular, $(e_x-e_{x_0})(e_x-e_{x_0})=0$ for all $x \in X\setminus \{x_0 \}$, which yields
$$e_x-e_{x_0} e_x - e_x  e_{x_0}+e_{x_0}=0$$
for all $x \in X\setminus \{x_0 \}$. Since it is an expression in $\mathbb{k}[X]$, the terms must cancel off with each other. Suppose that $e_{x_0} e_x=e_x$ and $e_x e_{x_0}=e_{x_0}$ for some $x \in X\setminus \{x_0 \}$. Also, we have $e_x  e_x=e_x$ by the first quandle axiom. Thus, by second quandle axiom, we have $e_x=e_{x_0}$, which is a contradiction. Hence, we must have $e_x  e_{x_0}=e_x$ and $e_{x_0} e_x=e_{x_0}$ for all $x \in X\setminus \{x_0 \}$. This means $x_0$ acts trivially on all elements of $X$. Since $x_0$ was arbitrary, it follows that $X$ is trivial.
\para

Conversely, suppose that $X$ is a trivial quandle. Let $y, z, y', z' \in X$. Then
$$(e_y-e_z)(e_{y'}-e_{z'})=e_y  e_{y'}-e_{z}  e_{y'}-e_y  e_{z'}+e_{z} e_{z'}=e_y-e_z-e_y+e_z=0,$$
and hence $\Delta_{\mathbb{k}}^2(X)=\{0\}$. $\blacksquare$
\end{proof}

\begin{corollary}
A group $G$ is abelian if and only if $\Delta_{\mathbb{k}}^2\big(\Conj(G)\big)=\{0\}$.
\end{corollary}

\begin{remark}{\rm 
Clearly, if $X$ is a trivial rack, then $\Delta_{\mathbb{k}}^2(X)=\{0\}$. However, the converse is not true for racks that are not quandles. For example, take $X= \{0, 1, \dots, n-1\}$ with the rack structure given by $$i*j=i+1 \mod n.$$ Then $X$ is not a trivial rack. On the other hand, for $0 \le i, j \le n-1$, we have
$$(e_{i}-e_{1})(e_{j}-e_{1})=e_{i}e_{j} - e_{i}e_{1} - e_{1}e_{j} + e_{1}e_{1}=e_{i+1}-e_{i+1}-e_{2}+e_{2}=0,$$ and hence  $\Delta_{\mathbb{k}}^2(X)=\{0\}$.}
\end{remark}

 \begin{remark}{\rm 
 If $\phi:X \to Y$ is a homomorphism of quandles, then it extends linearly to a homomorphism of corresponding quandle rings $\mathbb{k}[X]\to \mathbb{k}[Y]$. Throughout the text, we denote this induced homomorphism by $\hat{\phi}: \mathbb{k}[X]\to \mathbb{k}[Y]$.}
 \end{remark}
