\section{Associated graded rings of quandle rings}\label{section6}
Let $X$ be a quandle (respectively, rack) and $\mathbb{k}$ an associative ring with unity. Consider the direct sum
$$
\mathcal{X}_{\mathbb{k}}(X) = \bigoplus_{i\geq 0} \Delta^i_{\mathbb{k}}(X) / \Delta^{i+1}_{\mathbb{k}}(X)
$$
of $\mathbb{k}$-modules $\Delta^i_{\mathbb{k}}(X) / \Delta^{i+1}_{\mathbb{k}}(X)$. We regard $\mathcal{X}_{\mathbb{k}}(X)$ as a graded $\mathbb{k}$-module with the convention that the elements of $\Delta^i_{\mathbb{k}}(X) / \Delta^{i+1}_{\mathbb{k}}(X)$ are homogeneous of degree $i$. Define multiplication in $\mathcal{X}_{\mathbb{k}}(X)$ as follows. For $u_i \in \Delta^i_{\mathbb{k}}(X)$, let $\underline{u}_i = u_i + \Delta^{i+1}_{\mathbb{k}}(X)$. Then, for $\underline{u}_i \in \Delta^i_{\mathbb{k}}(X) / \Delta^{i+1}_{\mathbb{k}}(X)$, $\underline{u}_j \in \Delta^j_{\mathbb{k}}(X) / \Delta^{j+1}_{\mathbb{k}}(X)$, we define 
$$\underline{u}_i ~ \underline{u}_j = \underline{u_i u_j}.$$ The product of two arbitrary elements of $\mathcal{X}_{\mathbb{k}}(X)$ is defined by extending the above product linearly. In other words, if $\underline{u} = \sum_i \underline{u}_i$ and $\underline{v} = \sum_j \underline{v}_j$ are decompositions of $\underline{u}, \underline{v} \in \mathcal{X}_{\mathbb{k}}(X)$ into homogeneous components, then
$$
\underline{u}~ \underline{v} = \sum_{i,j} \underline{u}_i ~ \underline{v}_j.
$$
With this multiplication, $\mathcal{X}_{\mathbb{k}}(X)$ becomes a graded ring, called the \index{associated graded ring}{\it associated graded ring} of $\mathbb{k}[X]$. We have a complete description of associated graded rings of trivial quandles.

\begin{proposition}
If $\T$ is a trivial quandle and $x_0 \in \T$, then $\mathcal{X}_{\mathbb{k}}(\T) = \mathbb{k} x_0\oplus \Delta_{\mathbb{k}}(\T)$.
\end{proposition}

\begin{proof}
It follows from the definition of $\mathcal{X}_{\mathbb{k}}(\T)$ and Theorem \ref{deltasqzero}. $\blacksquare$
\end{proof}

In order to understand $\mathcal{X}_{\mathbb{k}}(X)$,  it is essential to examine the quotients $\Delta^i_{\mathbb{k}}(X) / \Delta^{i+1}_{\mathbb{k}}(X)$. In what follows,  we compute  powers of the integral augmentation ideals of dihedral quandles. Note that $\R_1$ and $\R_2$ are trivial quandles. We first consider dihedral quandles of odd orders \cite[Theorem 6.2]{MR3915329}. 

\begin{theorem} 
Let $n>1$ be an odd integer. Then $\Delta^k(\R_n) / \Delta^{k+1}(\R_n) \cong \mathbb{Z}_n$ for all $k \geq 1$. 
\end{theorem}

\begin{proof} 
We write $\R_n= \{0, 1, 2, \ldots, n-1\}$ and prove the result by induction on $k$. Throughout the proof, all the computations are modulo $\Delta^{2}(\R_n)$. Set $f_i:= e_{i}-e_{0}$ for $1 \le i \le n-1 $. First, we claim that $\Delta(\R_n)/\Delta^2(\R_n)$ is generated as an abelian group by the coset of $f_1$ and that $\Delta(\R_n) / \Delta^2(\R_n) \cong \mathbb{Z}_n$. Recall that $\Delta(\R_n)$ is generated by $\{ f_1, f_2, \ldots, f_{n-1} \}$ and $\Delta^2(\R_n)$ is generated by  $\{f_i  f_j \, \mid \, 1 \le i, j \le n-1\}$ as abelian groups. We see that
$$f_{2i}+f_{n-2i}= e_{2i}- e_0 +e_{n-2i}- e_0= -(e_{2i}-e_0)(e_{i}-e_0)=-f_{2i}f_{i},$$
for each $1\leq i\leq \frac{n-1}{2}$. This implies that $f_{2i}=-f_{n-2i}$ for each $1\leq i\leq \frac{n-1}{2}$. In particular, for  $i=\frac{n-1}{2}$, we have $f_1=-f_{n-1}$. Note that, $f_1 f_1=0$ implies $f_2=2f_1$, whereas $f_{n-1} f_1=0$ implies $f_3=3f_1$.  Continuing in this manner, we get $f_{n-1}=(n-1)f_1$. Since $f_1=-f_{n-1}$, we obtain $n f_1=0$. Hence, $\Delta(\R_n)/\Delta^2(\R_n)$ is generated as an abelian group by the coset of $f_1$, and $\Delta(\R_n) / \Delta^2(\R_n) \cong \mathbb{Z}_n$. 
\para
Now, assume that $\Delta^k(\R_n) / \Delta^{k+1}(\R_n) \cong \mathbb{Z}_n$ for some $k \ge 1$.  Let the coset of $\alpha \in  \Delta^k(\R_n)$ generate $\Delta^k(\R_n) / \Delta^{k+1}(\R_n)$. Obrserve that the cosets of the elements $f_1\alpha, \ldots, f_{n-1}\alpha$~ generate $\Delta^{k+1}(\R_n) / \Delta^{k+2}(\R_n)$. Since $f_k=k f_1 \mod \Delta^2(\R_n)$ for each $1\leq k\leq n-1$, it follows that $f_k \alpha=k f_1 \alpha \mod \Delta^{k+2}(\R_n)$ for each $1\leq k\leq n-1$. Thus, the coset of $f_1\alpha$ generates $\Delta^{k+1}(\R_n) / \Delta^{k+2}(\R_n)$. Since $n f_1=0 \mod \Delta^2(\R_n)$, it follows that $n f_1 \alpha =0 \mod \Delta^{k+2}(\R_n)$, and hence
$$\Delta^{k+1}(\R_n) / \Delta^{k+2}(\R_n) \cong \mathbb{Z}_n,$$ 
which is desired. $\blacksquare$
\end{proof}


Next, we calculate powers of the augmentation ideal for $\R_4$. Setting $f_i: = e_i - e_0$ for $1 \le i \le 3$, we see that $\Delta(\R_4)$ is generated as an abelian groups by $\{f_1, f_2, f_3 \}$.


\begin{proposition}\label{ass-graded-2}
The following statements hold for $\R_4$:
\begin{enumerate}
\item $\Delta^2(\R_4)$ is generated as an abelian group by $\{f_1 - f_2 - f_3,~ 2 f_2\}$
and $\Delta(\R_4) / \Delta^2(\R_4) \cong \mathbb{Z} \oplus \mathbb{Z}_2$.
\item If $k > 2$, then $\Delta^k(\R_4)$ is generated as an abelian group by $\{2^{k-2}(f_1 - f_2 - f_3), ~2^{k-1} f_2\}$
and $\Delta^{k-1}(\R_4) / \Delta^k(\R_4) \cong \mathbb{Z}_2 \oplus \mathbb{Z}_2$.
\end{enumerate}
\end{proposition}

\begin{proof}
The abelian group $\Delta^2(\R_4)$ is generated by the products $f_i f_j$. The following table shows these products $f_i f_j$, where $f_i$ is taken from the leftmost column and $f_j$ is taken from the topmost row.
\begin{center}
\begin{tabular}{|c||c|c|c|}
  \hline
 $\cdot$ & $f_1$ & $f_2$ & $f_3$ \\
   \hline
     \hline
$f_1$ & $f_1 - f_2 -f_3$ & $0$ & $f_1 - f_2 -f_3$ \\
  \hline
$f_2$  & $-2 f_2$ & $0$ & $-2 f_2$ \\
  \hline
$f_3$ & $-f_1 - f_2+f_3$ & $0$ & $-f_1 - f_2+f_3$ \\
  \hline
\end{tabular}\\
\end{center}
It follows that $\Delta^2(\R_4)$ is generated by the set
$$
\big\{f_1 - f_2 -f_3,~~ -2 f_2,~~ -f_1 - f_2+f_3 \big\}
$$
and $\{f_1 - f_2 - f_3, 2 f_2\}$ forms a basis of $\Delta^2(\R_4)$. The isomorphism $\Delta(\R_4) / \Delta^2(\R_4)\cong \mathbb{Z} \oplus \mathbb{Z}_2$ follows from properties of abelian groups, which proves assertion (1).
\para
Next, we consider assertion (2). In order to find a basis of $\Delta^3(\R_4)$, we multiply the basis of $\Delta^2(\R_4)$ by the elements $f_1, f_2, f_3$. Using the preceding multiplication table, we get
\begin{align*}
&(f_1 - f_2 - f_3) f_1 = 2 (f_1 + f_2 - f_3), & & f_1 (f_1 - f_2 - f_3) = 0, & &(f_1 - f_2 - f_3) f_2 = f_2 (f_1 - f_2 - f_3) = 0,\\
&(f_1 - f_2 - f_3) f_3 = 2 (f_1 + f_2 - f_3), & &f_3 (f_1 - f_2 - f_3) = 0,& & 2 f_1  f_2 = 0, \\
&2 f_2 f_1 = - 4 f_2, & &  2 f_2 f_2 = 0, & & 2 f_2 f_3 = - 4 f_2,\\
& 2 f_3 f_2 = 0. & & &
\end{align*}
Hence, the set $\{2 (f_1 - f_2 - f_3), 4 f_2\}$ forms a basis of $\Delta^3(\R_4)$. We obtain the general formulas using induction on $k$. Finally, the  assertion $\Delta^{k-1}(\R_4) / \Delta^k(\R_4) \cong \mathbb{Z}_2 \oplus \mathbb{Z}_2$ follows from properties of abelian groups. $\blacksquare$
\end{proof}

Let $\R_n$ be the dihedral quandle of order $n$ and $f_i: = e_i - e_0$ for $1 \le i \le n-1$. A direct check gives
\begin{equation}\label{neranga2}
f_i  f_j= f_{2j-i}-f_{n-i}-f_{2j}
\end{equation}
for all $1 \le i, j \le n-1$. Next, we have the following result \cite[Theorem 6.3]{MR3915329}.

\begin{theorem}\label{neranga3}
If $n=2k$ for some integer $k \ge 2$, then $\Delta(\R_n) / \Delta^2(\R_n)\cong \mathbb{Z}\oplus \mathbb{Z}_{k}$. 
\end{theorem}

\begin{proof}
Throughout the proof, all the computations are modulo $\Delta^{2}(\R_n)$.  We claim that the following assertions hold: 
\begin{enumerate}
\item  $\Delta(\R_n) / \Delta^{2}(\R_n)$ is generated as an abelian group by the cosets of $f_1$ and $f_2$.
\item   The abelian subgroup generated by the coset of $f_2$ is isomorphic to $\mathbb{Z}_k$. 
 \item  The abelian subgroup generated by the coset of $f_1$ is isomorphic to $\mathbb{Z}$. 
 \end{enumerate}

Using \eqref{neranga2}, we  have
$f_{n-l} f_{1}=-f_{2}-f_{l}+f_{l+2}$. Since $f_{n-l} f_{1}=0$, this gives 
\begin{equation}\label{relation among fis}
f_{l+2}=f_l+f_2.
\end{equation}
We  claim that
\begin{equation}\label{Star relations}
f_l = \left\{
\begin{array}{ll}
\frac{l}{2}\,f_2 &  \textnormal{if}\,\,l\,\,\textnormal{is even},\\[0.3cm]
\lfloor \frac{l}{2} \rfloor\,f_2+f_1 &  \textnormal{if}\,\,l\,\,\textnormal{is odd}.
\end{array}
\right.
\end{equation}
 for each $1 \le l \le  n-1$, where $\lfloor - \rfloor$ is the floor function. The relations are obvious for $l=1, 2$.  We proceed by induction on $l$. First, assume that $l \ge 4$ is even. Since $0=f_{n-2}  f_1=-2f_2+f_4$, we obtain $f_4=2f_2$, which is the case $l=4$. Suppose that \eqref{Star relations} holds for $l \ge 4$ even. Using the induction hypothesis and \eqref{relation among fis}, we get
$$f_{l+2}=f_l+f_2=\frac{l}{2}\,f_2+f_2=\Big(\frac{l+2}{2}\Big)\,f_2,$$
which is desired. Next, we assume that $l \ge 3$ is odd. The division algorithm gives $l=\lfloor \frac{l}{2} \rfloor\,2+1$, and hence
we can write $f_{l-1}=\frac{(l-1)}{2} f_2=\lfloor \frac{l}{2} \rfloor\,f_2$.  It follows from \eqref{neranga2} that 
\begin{equation}\label{second relations amongs fis}
f_l=f_{l-1}+f_1.
\end{equation}
Since $0=f_{n-1}  f_1=-f_1-f_2+f_3$, we obtain $f_3=f_2+f_1$, which is the case $l=3$. Suppose that \eqref{Star relations} holds for $l \ge 3$ odd. Using induction hypothesis, \eqref{relation among fis} and \eqref{second relations amongs fis}, we get
$$f_{l+2}=f_{l-1}+f_1+f_2=\Big(\frac{l-1}{2}\Big)\,f_2+f_1+f_2=\Big(\frac{l+1}{2}\Big)\,f_2+f_1=\lfloor \frac{l+2}{2} \rfloor\,f_2+f_1.$$
This proves \eqref{Star relations}, from which assertion (1) follows immediately.
\para

Next, if $i$ is even, then \eqref{neranga2} and \eqref{Star relations} give
$$
-f_i  f_j=-f_{2j-i}+f_{n-i}+f_{2j}=-\Big(\frac{2j-i}{2}\Big)\,f_2+\Big(\frac{n-i}{2}\Big)\,f_2+\Big(\frac{2j}{2}\Big)\,f_2 =\frac{n}{2}\,f_2 =kf_2.
$$
Similarly, if $i$ is odd, then $-f_i f_j=kf_2$. Since $f_i f_j=0$, it follows that $kf_2=0$. Further, we  have $0 \ne f_4 = 2f_2, \ldots, 0 \neq f_{2k-2} =(k-1)f_2$,
it follows that the abelian subgroup generated by the coset of $f_2$ is isomorphic to $\mathbb{Z}_k$, which is assertion (2).
\para

The relation \eqref{Star relations} implies that $f_1 =f_3-f_2$. Thus, if $mf_1 =0$, then $mf_2 =mf_3$, which implies that $m=0$. Hence, the abelian group generated by the coset of $f_1$ is torsion-free, which is assertion (3). Thus, $\Delta(\R_n) / \Delta^2(\R_n)\cong \mathbb{Z}\oplus \mathbb{Z}_{k},$  which is desired. $\blacksquare$
\end{proof}
\bigskip
\bigskip

