\section{Commutator width of quandle algebras}\label{commutator-width}
Let $X$ be a quandle and $\mathbb{k}$ an associative ring with unity. Define the \textit{commutator} of elements $u, v \in \mathbb{k}[X]$ as the element $$[u, v]=uv-vu.$$ Then the \index{commutator subalgebra}\textit{commutator subalgebra} $\mathbb{k}[X]'$ of $\mathbb{k}[X]$ is the $\mathbb{k}$-algebra generated by the set of all commutators in $\mathbb{k}[X]$. 

\begin{lemma}\label{commutator-augmentation}
Let $X$ be a quandle and $\mathbb{k}$ an associative ring with unity. Then the following assertions hold:
\begin{enumerate}
\item  If $X$ is a commutative quandle, then $\mathbb{k}[X]' =\{0\}$. 
\item If $\mathbb{k}$ is commutative, the $\mathbb{k}[X]' \le \Delta_{\mathbb{k}}(X)$.
\end{enumerate}
\end{lemma}

\begin{proof}
Assertion (1) is obvious. Since $\mathbb{k}$ is commutative and $\varepsilon \big([u, v] \big)=0$ for each $[u, v] \in \mathbb{k}[X]'$, assertion (2) follows.
\end{proof}

The equality in Lemma \ref{commutator-augmentation}(2) does not hold in general. For example, the dihedral quandle $\R_3$ is commutative, and hence $\mathbb{Z}[\R_3]'=\{0\}$. On the other hand, we have $\Delta(\R_3) =\langle e_1-e_0,  e_2-e_0 \rangle \neq \{0\}$. 
\para

We define the \index{commutator length} \textit{commutator length} $\cl(u)$ of an element $u \in \mathbb{k}[X]'$ as 
$$\cl(u)=\min \big\{n \,\mid\, u= \sum_{i=1}^n \alpha_i [u_i,v_i],~\textrm{where}~\alpha_i \in R ~\textrm{and}~u_i, v_i \in \mathbb{k}[X]\big\}.$$
The \textit{commutator width} $\cw \big(\mathbb{k}[X] \big)$ of $\mathbb{k}[X]$ is defined as 
$$\cw \big(\mathbb{k}[X] \big)=\sup \big\{\cl(u) \, \mid \, u \in \mathbb{k}[X]'\big\}.$$

It follows from the definition of commutator width that a quandle $X$ is commutative if and only if  $\cw \big(\mathbb{k}[X] \big)=0$. Consequently, we have $\cw \big(\mathbb{k}[\R_3] \big)=0$.
\para

The computation of commutator width has been studied in the context of free Lie rings \cite{MR1803583}, free metabelian Lie algebras \cite{MR3328893}, and absolutely free as well as free solvable Lie rings of finite rank \cite{MR3601334}. In the remainder of this section, we compute the commutator width for several quandle rings.
\para

We say that a quandle $X$ is {\it strongly non-commutative} if for every pair of distinct elements $x, y \in X$ there exist elements $a, b \in X$ such that $a*b = x$ and $b*a = y$. Obviously, every strongly non-commutative quandle is non-commutative.

\begin{theorem}\cite[Theorem 7.2]{MR4450681} \label{commutator-width-general}
Let $X$ be a strongly non-commutative quandle or a non-commutative quandle admitting a 2-transitive action by $\Aut(X)$. Let $\mathbb{k}$ be a commutative and associative ring with unity. Then the following  assertions hold:
\begin{enumerate}
\item $\mathbb{k}[X]'=\Delta_{\mathbb{k}}(X)$.
\item If $X$ has order $n$, then $1 \le \cw \big(\mathbb{k}[X] \big) \le n-1$.
\end{enumerate}
\end{theorem}

\begin{proof}
In view of Lemma \ref{commutator-augmentation}(2), we only need to show that $\Delta_{\mathbb{k}}(X) \le \mathbb{k}[X]'$. Since $\Delta_{\mathbb{k}}(X)$ is generated as an $\mathbb{k}$-module by elements of the form $e_x-e_y$, where $x, y \in X$ are distinct elements, it suffices to show that each such element is a commutator. Suppose first that $X$ is strongly non-commutative. Let $x, y \in X$ be two distinct elements. Then, there exist $a, b \in X$ such that $e_x-e_y = e_ae_b - e_be_a  = [e_a, e_b] \in \mathbb{k}[X]'$. Now, suppose that $X$ is non-commutative. Then, there exist elements $c, d \in X$ such that $c*d \neq d*c$. By 2-transitivity of $\Aut(X)$ action on $X$, there exists $\phi \in \Aut(X)$ such that $\phi(c*d)=x$ and  $\phi(d*c)=y$. Thus, we have $e_x-e_y=\hat{\phi}(e_c e_d)-\hat{\phi}(e_d e_c)=[\hat{\phi}(e_c), \hat{\phi}(e_d)] \in  \mathbb{k}[X]'$, where $\hat{\phi}$ is the induced automorphism of $\mathbb{k}[X]$. This proves assertion (1).
\para
Let $X=\{x_0, x_1, \ldots, x_{n-1} \}$. By assertion (1), we have $\mathbb{k}[X]'=\Delta_{\mathbb{k}}(X)$. Hence, any $u \in \mathbb{k}[X]'$ has the form $u= \sum_{i=1}^{n-1} (e_{x_i}-e_{x_0})$, where each $(e_{x_i}-e_{x_0})$ is a commutator as shown in the proof of (1). Since $X$ is non-commutative, we obtain $1 \le \cw \big(\mathbb{k}[X] \big) \le n-1$. $\blacksquare$
\end{proof}

\begin{corollary}
Let $G$ be an elementary abelian $p$-group with $p>3$ and $\phi \in \Aut(G)$ act as multiplication by a non-trivial unit of $\mathbb{Z}_p$. Then $1 \le \cw\big(\mathbb{k}[\Alex(G,\phi)]\big) \le |G|-1$.
\end{corollary}

\begin{proof}
The quandle $\Alex(G,\phi)$ is non-commutative for $p>3$. Further, by Theorem \ref{FNT-generalisation}, it admits a 2-transitive action by $\Aut \big(\Alex(G,\phi) \big)$.   $\blacksquare$
\end{proof}

We remark that a complete description of finite 2-transitive quandles has been given by Bonatto \cite{MR4075376} by extending results of Vendramin \cite{MR3685034}. The following result computes commutator width of some finite quandles \cite[Theorem 7.4]{MR4450681}.

\begin{theorem} 
Let $\mathbb{k}$ be a commutative and associative ring with unity. Then the following assertions hold:
\begin{enumerate}
\item If $\T$ is a trivial quandle, then $\cw \big(\mathbb{k}[\T] \big)=1$.
\item $\cw \big(\mathbb{k}[\R_4] \big) =1$.
\item $\cw \big(\mathbb{k}[\J_3] \big)=1$.
\end{enumerate}
\end{theorem}

\begin{proof}
By Theorem \ref{commutator-width-general}, we have $\mathbb{k}[\T]'=\Delta_{\mathbb{k}}(\T)$, and hence any element of $\mathbb{k}[\T]'$ has the form $u= \sum_{i=1}^n \alpha_i (e_{x_i}-e_{x_0})$. Taking $v= (1- \sum_{i=1}^n \alpha_i)e_{x_0} +  \sum_{i=1}^n \alpha_i e_{x_i}$ and $w=e_{x_0}$, we see that
\begin{eqnarray*}
[v, w] &=& vw-wv\\
&=& \varepsilon(w) v -\varepsilon(v) w\\
&=& (1- \sum_{i=1}^n \alpha_i)e_{x_0} +  \sum_{i=1}^n \alpha_i e_{x_i} -e_{x_0}\\
&=&  \sum_{i=1}^n \alpha_i (e_{x_i}-e_{x_0})=u,
\end{eqnarray*}
and hence $\cw \big(\mathbb{k}[\T] \big)=1$, which proves (1).
\para

By Lemma \ref{commutator-augmentation}(2), we have $\mathbb{k}[\R_4]' \le \Delta_{\mathbb{k}}(\R_4)$. Note that $\Delta_{\mathbb{k}}(\R_4)$ is generated by $\{f_1, f_2, f_3\}$, where $f_i=e_i-e_0$ for $i=1,2,3$. A direct check shows that
$$
f_1 = [e_3, e_2],~~f_2=[e_2, e_0], ~~f_3 = -[e_2, e_1],
$$ 
and hence $\mathbb{k}[\R_4]' = \Delta_{\mathbb{k}}(\R_4)$. 
If $w=\gamma_1 f_1+ \gamma_2 f_2 + \gamma_3 f_3 \in \Delta_{\mathbb{k}}(\R_4)$ for some $\gamma_i \in \mathbb{k}$, then we can write it as
$$
w=[e_2, \gamma_2 e_0 - \gamma_3 e_1 - \gamma_1 e_3].
$$ 
Thus, every element of $\mathbb{k}[\R_4]'$ is a commutator, and hence $\cw \big(\mathbb{k}[\R_4] \big) = 1$, which proves (2).
\para

Let $\J_3=\{1,2,3\}$ be the quandle with multiplication table given by
$$
\J_3=\begin{tabular}{|c||c|c|c|}
    \hline
  % after \\: \hline or \cline{col1-col2} \cline{col3-col4} ...
$*$ & 1 & 2 & 3  \\
  \hline \hline
1 & 1 & 1 & 1  \\
\hline
2 & 3 & 2 & 2  \\
\hline
3 & 2 & 3 & 3  \\
  \hline
\end{tabular}.
$$
The augmentation ideal $\Delta_{\mathbb{k}}(\J_3)$ is generated by $f_1=e_3-e_2$ and $f_2=e_1-e_2$. Further, multiplication rules in $\J_3$ show that $f_1=e_3 e_2-e_2 e_3=[e_3, e_2]$ and $f_2=e_1 e_3-e_3 e_1= [e_1, e_3]$, and hence $\mathbb{k}[\J_3]'=\Delta_{\mathbb{k}}(\J_3)$.  Let $w=\gamma_1f_1+ \gamma_2f_2 \in \Delta_{\mathbb{k}}(\J_3)$, where $\gamma_i \in \mathbb{k}$. A direct check gives
$$f_1 e_2=f_1,~~f_2 e_2=f_2,~~e_2 f_1=0,~~e_2 f_2=f_1.$$
Now, taking $u=e_2+ (\gamma_1+\gamma_2)f_1 + \gamma_2 f_2$ and $v=e_2$, we see that
$$w=uv-vu=[u, v].$$
Hence, $\cw \big(\mathbb{k}[\J_3] \big)=1$, which establishes assertion (3). $\blacksquare$
\end{proof}

