\section{Quandle algebras as representation spaces}
Let $X=X_1 \sqcup\cdots\sqcup X_k$ be the decomposition of a finite quandle $X$ by its connected components. Each $x \in X$ gives rise to  maps $L_x: X\rightarrow X$ and $S_x: X\rightarrow X$ given by $L_x(y)=x*y$ and $S_x(y)=y*x$, respectively. Thus, we have a map  $$\psi: X\rightarrow\mathcal{M}(X)$$
given by $x \mapsto L_x$. Similarly, we have a map
$$\varphi: X\rightarrow \Sigma_{n}$$
given by $x \mapsto S_x$. Note that this map further restricts to  maps $\varphi_i: X\rightarrow \Sigma_{n_i}$, where $n_i=|X_i|$ and $n=\sum\limits_{i=1}^{k} n_i$. Let $H(X)$ denote the semigroup generated by $\psi(X)$. Note that $H(X)$ is not necessarily a group. On the other hand, we know that the semigroup generated by  $\varphi(X)$ is the group $\Inn(X)$ of inner automorphisms of $X$. For each $i$, let $G(X_i)$ denote the group generated by $\varphi_i (X)$, which is a subgroup of $\Sigma_{n_i}$.
\para

Let $X$ be a quandle and $\mathbb{k}$ a field. Let $V$ denote the underlying $\mathbb{k}$-vector space of the quandle algebra $\mathbb{k}[X]$. To study right ideals of the algebra $\mathbb{k}[X]$, we view $V$ as a representation space of $\Inn(X)$. Clearly, we have 
$$V=\underset{i=1}{\overset{k}{\oplus}}V^i,$$
 where $V^i= \mathbb{k}[X_i]$. Thus, it is enough to  understand  decomposition of  $V^i$ into irreducible representations of $G(X_i)$. Since $X_i$ is finite, $V^i$ contains a one-dimensional subspace $V_{\textrm{triv}}^i:=\mathbb{k}v_{\textrm{triv}}$ which is invariant under the action of $G(X_i)$, where $v_{\textrm{triv}}=\sum\limits_{x\in X_i} e_x$.


\begin{definition}
Let $X=X_1 \sqcup\cdots\sqcup X_k$ be a finite quandle. Then $X$ is said to be:
\begin{enumerate}
\item  \textit{left $2$-transitive} if the semigroup  $H(X)$ acts $2$-transitively on $X$.
\item  \textit{right $2$-transitive} if the group $\Inn(X)$ acts $2$-transitively on $X$. 
\item  \textit{right orbit $2$-transitive} if  the group $G(X_i)$ acts $2$-transitively on $X_i$ for each $i$.
\end{enumerate}
\end{definition}


\para
Let $X$ be a finite quandle of order $n$ and  $V_{\textrm{st}}$ the subspace of $V$ orthogonal to $V_{\textrm{triv}}$.  The following result gives the list of subgroups $G\leqslant  S_n$ for which the representation $V_{\textrm{st}}$ is irreducible. 
\para

\begin{theorem} \label{TransClassif}
Let $X$ be a finite quandle of order $n$ and $\mathbb{k}$ a field. Then the following statements hold:
\begin{enumerate}
\item If $\charac(\mathbb{k})=0$,  then $V_{\textrm{st}}$ is an irreducible representation of the subgroup $G < S_n$ if and only if  $G$ is $2$-transitive and $A_n\not\leq G$. 
 \item If $\charac(\mathbb{k})=p>3$,  then $V_{\textrm{st}}$ is an irreducible representation of the subgroup $G < S_n$ if and only if  $G$ is $2$-transitive and $A_n\not\leq G$ except when:
 \begin{enumerate}
 \item[(i)] $G \leqslant  A\Gamma L(m, q)$ and $p$ divides $q$;
 \item[(ii)] $G \leqslant  P\Gamma L(m, q)$, $m\geq 3$ and $p$ divides $q$;
 \item[(iii)] $G \leqslant  P\Gamma U(3, q)$ and $p$ divides $q+1$;
 \item[(iv)] $G \leqslant  Sz(q)$ and $p$ divides $q+1+m$, where $m^2=2q$;
 \item[(v)] $G \leqslant  Re(q)$ and $p$ divides $(q+1)(q+1+m)$, where $m^2=3q$.
\end{enumerate} 
\end{enumerate}
\end{theorem}

\begin{proof}
Assertion (1) is stated in \cite[Theorem 1(b)] {MR0913206}, while assertion (2) is established in \cite[Main Theorem (ii)]{MR1807270}. The description of groups $(i)-(v)$ can be found in \cite[Chapter 7]{MR1409812}. In short, the groups $(i)-(v)$ are the affine general semilinear groups, projective general semilinear groups, projective semilinear unitary groups, Suzuki groups and Ree groups, respectively. $\blacksquare$
\end{proof}

If $A$ is a finite semigroup and $e \in A$ is an idempotent, then $eAe$ is a monoid with identity $e$. The group of units of $eAe$ is called the \textit{maximal subgroup} of $A$ at $e$.

\begin{corollary}\label{RightModDecomp}
Let $X$ be a finite quandle of order $n$ such that $A_n \not\le \Inn(X)$ and $\mathbb{k}$ a field. Then the following statements hold:
\begin{enumerate}
\item  If $X=X_1 \sqcup \cdots \sqcup X_k$ is a right orbit 2-transitive quandle and $\charac(\mathbb{k})=0$, then  $\mathbb{k}[X]\cong \underset{i=1}{\overset{k}{\bigoplus}}(V^i_{\textrm{st}}\oplus V^i_{\textrm{triv}})$, where the summands on the right hand side are simple right ideals.

\item  If $X=X_1 \sqcup \cdots \sqcup X_k$ is a right orbit 2-transitive quandle such that none of the groups $G(X_i)$ is in the list of groups in Theorem~\ref{TransClassif}(2) and  $\charac(\mathbb{k})=p>3$, then $\mathbb{k}[X]\cong \underset{i=1}{\overset{k}{\bigoplus}}(V^i_{\textrm{st}}\oplus V^i_{\textrm{triv}})$, where the summands on the right hand side are simple right ideals.

\item If $X$ is such that  $H(X)$ contains a maximal subgroup with a $2$-transitive action on $X$ and $\charac(\mathbb{k})=0$, then $\mathbb{k}[X]\cong V_{\textrm{st}}\oplus V_{\textrm{triv}}$, where the summands on the right hand side are simple left ideals.

\item If $X$ is such that  $H(X)$ contains a maximal subgroup with a $2$-transitive action on $X$, which is not in the list of groups in  Theorem~\ref{TransClassif}(2) and $\charac(\mathbb{k})=p>3$, then $\mathbb{k}[X]\cong V_{\textrm{st}}\oplus V_{\textrm{trivial}}$, where the summands on the right hand side are simple left ideals.
\end{enumerate}
\end{corollary}

\begin{definition}
A finite quandle $X$ is of \index{cyclic type quandle} \textit{right cyclic type} if for each $x \in X$, the inner automorphism $S_x$ acts on $X \setminus \{x\}$ as a cycle of length $|X|-1$.
\para
 Similarly, $X$ is said to be of \textit{left cyclic type} if for each $x \in X$, the semigroup element $L_x$ acts on $X \setminus \{x\}$ as a cycle of length $|X| - 1$.
\end{definition}
\para

The following result relates  2-transitivity of finite quandles to cyclicity \cite[Corollary 4]{MR3685034}.

\begin{theorem}
Every finite right  $2$-transitive quandle is of right cyclic type.
\end{theorem}

\begin{remark}
{\rm 
If $X$ is a quandle of left cyclic type, then it is left $2$-transitive.  
For, let $(a, b),(c, d) \in X \times X$. Since $X$ is of left cyclic type, there exist $i, j$ such that $L_b^i(a)= c$ and   $L_c^j(b) = d$. Consequently, $L_c^j \,L_b^i$ maps the pair $(a, b)$ to the pair $(c, d)$.
}
\end{remark}

The preceding observations allow to strengthen Corollary~\ref{RightModDecomp}.

\begin{corollary}
Let $X$ be a finite quandle of order $n$ such that $A_n \not\le \Inn(X)$ and $\mathbb{k}$ a field. Then the following statements hold:
\begin{enumerate}
\item  If $X=X_1 \sqcup\cdots\sqcup X_k$ is such that each subquandle $X_i$ is of right cyclic type, then $\mathbb{k}[X]\cong \underset{i=1}{\overset{k}{\bigoplus}}(V^i_{st}\oplus V^i_{triv})$, where the summands on the right hand side are simple right ideals.
\item If $X$ is of left cyclic type, then $\mathbb{k}[X]\cong V_{st}\oplus V_{triv}$, where the summands on the right hand side are simple left ideals.
\end{enumerate}
\end{corollary}
