A computer assisted check for quandles of order less than seven suggests the following conjecture \cite[Conjecture 3.1]{MR4565221}.

\begin{conjecture}\label{Main conjecture}
The integral quandle ring of a semi-latin quandle has only trivial idempotents. In particular, the integral quandle ring of a finite latin quandle has only trivial idempotents.
\end{conjecture}

It follows from Theorem \ref{orderability-free-quandle} that free quandles are semi-latin. We shall prove in Theorem \ref{idempotents in free products} that free quandles satisfy Conjecture \ref{Main conjecture}. 
\para

For a quandle $X$, we denote by $\Aut_{\textrm{algebra}} \big(\mathbb{k}[X] \big)$ the group of $\mathbb{k}$-algebra automorphisms of $\mathbb{k}[X]$, that is, ring automorphisms of $\mathbb{k}[X]$ that are $\mathbb{k}$-linear. 

\begin{proposition}\label{auto quandle ring free products}
Let $X$ be a quandle and $\mathbb{k}$ an integral domain with unity. If $\mathbb{k}[X]$ admits only trivial idempotents, then 
$\Aut_{\textrm{algebra}}\big(\mathbb{k}[X]\big) \cong \Aut_{\textrm{quandle}}(X).$
\end{proposition}

\begin{proof}
Clearly, each automorphism of $X$ induces an automorphism of $\mathbb{k}[X]$. Conversely, if $\phi \in \Aut_{\textrm{algebra}}\big(\mathbb{k}[X]\big)$, then $\phi$ is a bijection of the set $\mathcal{I}\big(\mathbb{k}[X]\big)$ of all idempotents. Since $\mathbb{k}[X]$ has only trivial idempotents, we have $X \cong \mathcal{I}\big(\mathbb{k}[X]\big)$ via the map $x \mapsto e_x$, and hence $\phi$ can be viewed as an automorphism of $X$, proving the assertion. $\blacksquare$
\end{proof}


\para
In what follows, we give a complete description of idempotents for some elementary quandles.

\begin{proposition} \label{trivial-quandle-idempotents}
If $\T$ is a trivial quandle and $\mathbb{k}$ an integral domain with unity, then $\mathcal{I}(\mathbb{k}[\T]) =  e_{x_0} + \Delta_{\mathbb{k}} (\T)$, where  $x_0 \in \T$ is a fixed element.
\end{proposition}

\begin{proof}
Since $\T$ is trivial, by Theorem \ref{deltasqzero}, $\Delta_{\mathbb{k}}^2 (\T) = 0$. It follows that non-zero idempotents do not lie in $\Delta_{\mathbb{k}} (\T)$. Hence, a non-zero idempotent has the form
 $u = e_{x_0} + \delta$, where $\delta \in \Delta_{\mathbb{k}} (\T)$ and $x_0 \in \T$ some fixed element. Indeed, 
$$
u^2 = e_{x_0}^2 + e_{x_0} \delta + \delta e_{x_0} + \delta^2= e_{x_0}+ \delta=u
$$
since $e_{x_0}^2 = e_{x_0}$, $e_{x_0} \delta = \delta^2 = 0$ and $\delta e_{x_0} = \delta$. $\blacksquare$
\end{proof}


\begin{proposition}\cite[Proposition 4.2]{MR4450681} \label{joyce-quandle}
Let $\J_3$ be the 3-element quandle given by
$$
\J_3=\begin{tabular}{|c||c|c|c|}
    \hline
$*$ & 1 & 2 & 3  \\
  \hline \hline
1 & 1 & 1 & 1  \\
\hline
2 & 3 & 2 & 2  \\
\hline
3 & 2 & 3 & 3  \\
  \hline
\end{tabular}.
$$
Then $\mathcal{I} \big(\mathbb{Z}[\J_3] \big) = \big\{ (1 - \beta) e_2 +  \beta e_3,~ \alpha e_2 + \alpha e_3 +  (1 - 2 \alpha) e_1~ \mid~ \beta, \alpha \in \mathbb{Z} \big\}$.
\end{proposition}

\begin{proof}
The quandle $\J_3$ is a disjoint union of two trivial subquandles $\{1\}$ and $\{ 2, 3 \} $. If $w = \alpha e_2 + \beta  e_3 + \gamma e_1 \in \mathbb{Z}[\J_3]$, then
$$
w^2 = (\alpha^2 + \alpha \beta + \beta \gamma) e_2 + (\alpha \beta + \beta^2 + \alpha \gamma) e_3 + (\alpha \gamma + \beta \gamma + \gamma^2 )e_1.
$$
Thus, $w$ is an idempotent if and only if the system of equations
\begin{eqnarray*}
\alpha &=& \alpha^2 + \alpha \beta + \beta \gamma,\\
\beta &=& \beta^2 + \alpha \beta +  \alpha \gamma,\\
\gamma &=& \gamma^2 + \alpha \gamma + \beta \gamma,
\end{eqnarray*}
is simultaneously  solvable over integers. Suppose that $\gamma = 0$. Then we obtain the equations
$$\alpha = \alpha^2 + \alpha \beta \quad \textrm{and} \quad \beta = \beta^2 + \alpha \beta.$$
If $\alpha = 0$, then $\beta = 0, 1$. The first case gives $w=0$, while the second case gives $w = e_3$. If $\alpha \not= 0$, then $\alpha = 1 - \beta$ and we have idempotents
$$
w = (1 - \beta) e_2 +  \beta e_3,~~\beta \in \mathbb{Z}.
$$
These are idempotents of the quandle ring $\mathbb{Z}[\{ 2, 3 \}]$.
\para

Now, suppose that $\gamma \not= 0$. Then the third equation of the system gives $\gamma = 1 - \alpha - \beta$. Substituting this expression in the first and the second equations gives
$$
(\alpha - \beta) (\alpha + \beta) = (\alpha - \beta).
$$
If $\alpha - \beta \not= 0$, then we obtain the same idempotent as in the previous case. If $\alpha - \beta = 0$, then we have idempotents
$$
w = \alpha e_2 + \alpha e_3 +  (1 - 2 \alpha) e_1,~~\alpha \in \mathbb{Z}.
$$
Hence, we have proved that $\mathcal{I} \big(\mathbb{Z}[\J_3] \big) = \big\{ (1 - \beta) e_2 +  \beta e_3, \alpha e_2 + \alpha e_3 +  (1 - 2 \alpha) e_1 \, \mid \, \beta, \alpha \in \mathbb{Z} \big\}.
$ $\blacksquare$
\end{proof}

\begin{remark}{\rm 
 If a quandle $X = X_1 \cup \cdots \cup X_n$ is a union of subquandles and $\mathbb{k}$ an integral domain with unity, then
\begin{equation}\label{idempotents-union}
  \mathcal{I} \big(\mathbb{k}[X_1] \big) \cup \cdots \cup \mathcal{I} \big(\mathbb{k}[X_n] \big) \subseteq \mathcal{I} \big(\mathbb{k}[X] \big).
\end{equation}
The inclusion is, in general, not an equality. In fact, the preceding example shows that
$$
 \mathcal{I} \big(\mathbb{Z}[\{ 2, 3 \}] \big) \cup \mathcal{I} \big(\mathbb{Z}[\{1\}] \big) \neq \mathcal{I} \big(\mathbb{Z}[\J_3] \big).
$$}
\end{remark}
 \medskip

Let  $\R_n = \{0, 1, \ldots, n-1 \}$ be the dihedral quandle of order $n$, where $i*j=2j-i \mod  n$. We examine idempotents in $\mathbb{Z}[\R_n]$ for $1 \le n\le 4$. Note that $\R_1$ and $\R_2$ are trivial quandles.

\begin{proposition}\cite[Proposition 4.3]{MR4450681} \label{idempotents-r3}
$ \mathcal{I} \big(\mathbb{Z}[\R_3] \big) = \{ e_0, e_1, e_2 \}. $
\end{proposition}

\begin{proof}
Let $z = \alpha_0 e_0 + \alpha_1 e_1 + \alpha_2 e_2 \in \mathbb{Z}[\R_3]$ be an idempotent. Then we have $\varepsilon(z) = 0, 1$.
\medskip

 Case 1: $\varepsilon(z) = 0$, that is, $\alpha_0 = - \alpha_1 - \alpha_2$. Then $z = \alpha_1 f_1 + \alpha_2 f_2$, where $f_i = e_i - e_0$. The elements $f_1$ and $f_2$ generate $\Delta (\R_3)$ and have the following multiplication table.
\begin{center}
\begin{tabular}{|c||c|c|}
  \hline
 $\cdot$ & $f_1$ & $f_2$  \\
   \hline
     \hline
$f_1$ & $f_1 - 2 f_2$ & $-f_1 - f_2$  \\
  \hline
$f_2$  & $-f_1 - f_2$ & $-2 f_1 + f_2$ \\
  \hline
\end{tabular}\\
\end{center}
Thus, we have
$$
z^2 = (\alpha_1^2 - 2 \alpha_1 \alpha_2 - 2 \alpha_2^2) f_1 + (\alpha_2^2 - 2 \alpha_1 \alpha_2 - 2 \alpha_1^2) f_2.
$$
The equality $z^2 = z$ leads to the equations
$$\alpha_1 = \alpha_1^2 - 2 \alpha_1 \alpha_2 - 2 \alpha_2^2 \quad \textrm{and} \quad \alpha_2 = \alpha_2^2 - 2 \alpha_1 \alpha_2 - 2 \alpha_1^2.$$
Subtracting the second equation from the first yields
$$
\alpha_1 - \alpha_2 = 3 (\alpha_1 - \alpha_2) (\alpha_1 + \alpha_2).
$$
It is not difficult to see that in this case the only solution is $\alpha_1=\alpha_2=\alpha_3=0$.
\para 

Case 2: $\varepsilon(z) = 1$. In this case
 $\alpha_0 = 1 - \alpha_1 - \alpha_2$. Then $z = e_0 + \alpha_1 f_1 + \alpha_2 f_2$ and we get
$$
z^2 = e_0^2+ (2 \alpha_2 + \alpha_1^2 - 2 \alpha_1 \alpha_2 - 2 \alpha_2^2) f_1 + (2 \alpha_1 + \alpha_2^2 - 2 \alpha_1 \alpha_2 - 2 \alpha_1^2) f_2.
$$
 From $z^2 = z$, we obtain the equations
$$\alpha_1 - 2 \alpha_2 = \alpha_1^2 - 2 \alpha_1 \alpha_2 - 2 \alpha_2^2 \quad \textrm{and} \quad \alpha_2 - 2 \alpha_1 = \alpha_2^2 - 2 \alpha_1 \alpha_2 - 2 \alpha_1^2.$$
Subtracting the second from the first gives
$$
\alpha_1 - \alpha_2 =  (\alpha_1 - \alpha_2) (\alpha_1 + \alpha_2).
$$
If $\alpha_1 = \alpha_2$, then the system is equivalent to the equation $\alpha_1 = 3 \alpha_1^2$, whose only solution is $\alpha_1=\alpha_2=0$. Thus, $\alpha_0=1$, and hence $z=e_0$ in this case. If $\alpha_1 \not = \alpha_2$, then the system has solutions $(\alpha_1, \alpha_2) = (1,0)$ or $(0,1)$. In this case $\alpha_0 = 0$, and hence $z=e_1$ or $e_2$. $\blacksquare$
\end{proof}
\para


Note that $\R_4$ is disconnected and is a disjoint union of trivial subquandles $\{0, 2 \} $ and $\{1, 3 \}$. Thus, we have
$$
  \mathcal{I} \big(\mathbb{Z}[\{e_0, e_2 \}] \big) \cup \mathcal{I} \big(\mathbb{Z}[\{e_1, e_3 \}] \big) \subseteq \mathcal{I} \big(\mathbb{Z}[\R_4] \big).
$$
In fact, we have an equality in this case \cite[Proposition 4.4]{MR4450681}.

\begin{proposition}\label{R4-idempotents}
$
\mathcal{I} \big(\mathbb{Z}[\R_4] \big) = \Big\{ \alpha e_0 +  (1 - \alpha) e_2, ~\beta e_1 + (1-\beta) e_3  \, \mid \,  \alpha, \beta \in \mathbb{Z} \Big\}.
$
\end{proposition}

\begin{proof}
If $z \in \mathbb{Z}[\R_4]$ is an idempotent, then $\varepsilon (z) = 0, 1$. We consider the following two cases:
\para 

Case 1: $\varepsilon (z) = 0$, that is, $z \in \Delta (\R_4)$. In this case, we can write
$$
z = \alpha f_1 + \beta f_2 + \gamma f_3 ~\mbox{for some}~ \alpha, \beta, \gamma \in \mathbb{Z},
$$
where $f_i = e_i - e_0$ for $i = 1, 2, 3$. Using the multiplication table

\begin{center}
\begin{tabular}{|c||c|c|c|}
  \hline
 $\cdot$ & $f_1$ & $f_2$ & $f_3$ \\
   \hline
     \hline
$f_1$ & $f_1 - f_2 -f_3$ & $0$ & $f_1 - f_2 -f_3$ \\
  \hline
$f_2$  & $-2 f_2$ & $0$ & $-2 f_2$ \\
  \hline
$f_3$ & $-f_1 - f_2+f_3$ & $0$ & $-f_1 - f_2+f_3$ \\
  \hline
\end{tabular}\\
\end{center}
we obtain
$$
z^2 = (\alpha^2 - \gamma^2) f_1 - (\alpha^2 + 2 \alpha \beta + 2 \alpha \gamma + 2 \beta \gamma + \gamma^2)  f_2 + (-\alpha^2  + \gamma^2) f_3.
$$
Thus, $z^2=z$ if and only if
\begin{eqnarray*}
 \alpha &=& \alpha^2 - \gamma^2,\\
\beta &=& - (\alpha^2 + 2 \alpha \beta + 2 \alpha \gamma + 2 \beta \gamma + \gamma^2),\\
\gamma &=& -\alpha^2  + \gamma^2.
\end{eqnarray*}
Adding the first and the third equations gives $\alpha + \gamma = 0$. Then it follows from the system of equations that $\alpha = \beta = \gamma = 0$. Thus, $\mathbb{Z} [\R_4]$ does not have non-trivial idempotents with augmentation value 0.
\para

Case 2: $\varepsilon (z) = 1$, that is, $z = e_0 + \delta$, where $\delta \in \Delta (\R_4)$ and
$$
\delta = \alpha f_1 + \beta f_2 + \gamma f_3 ~\mbox{for some}~ \alpha, \beta, \gamma \in \mathbb{Z}.
$$
We have $z^2 = e_0 + \delta e_0 + e_0 \delta + \delta^2$. Since $\Delta (\R_4)$ is a two-sided ideal, we have $\delta e_0, e_0 \delta \in \Delta (\R_4)$. Using the formulas
$$
f_1 e_0 = f_3,~~f_2 e_0 = f_2,~~f_3 e_0 = f_1,~~e_0 f_1 = f_2,~~ e_0 f_2 = 0,~~ e_0 f_3 = f_2,
$$
we obtain
$$
\delta e_0 = \alpha f_3 + \beta f_2 + \gamma f_1 \quad \textrm{and} \quad e_0 \delta  = \alpha f_2 +  \gamma f_2.
$$
Using the expression for $\delta^2$ from Case 1 gives
$$
z^2 = e_0 + (\gamma + \alpha^2 - \gamma^2) f_1 + (\beta + \alpha + \gamma - \alpha^2 - \gamma^2 - 2 \alpha \gamma - 2 \alpha \beta - 2 \beta \gamma) f_2 + (\alpha - \alpha^2 + \gamma^2) f_3.
$$
Now, $z^2=z$ if and only if the system of equations
\begin{eqnarray*}
\alpha &=& \gamma + \alpha^2 - \gamma^2,\\
0 &=&  \alpha + \gamma - \alpha^2 - \gamma^2 - 2 \alpha \beta - 2 \alpha \gamma - 2 \beta \gamma,\\
\gamma &=& \alpha - \alpha^2  + \gamma^2,
\end{eqnarray*}
has integral solutions. The first equation has the form
$$
(\alpha - \gamma) = (\alpha - \gamma) (\alpha + \gamma).
$$
Suppose that $\alpha = \gamma$, then the second equation has the form $0 = \alpha (1 - 2 \alpha - 2 \beta)$. If $\alpha = 0$, then for arbitrary $\beta$, we have the idempotent $z = e_0 + \beta (e_2 - e_0)$. If $\alpha \not= 0$, then the second equation does not have solutions. Now, suppose that $\alpha \neq \gamma$, then $\gamma = 1 - \alpha$ and the second equation gives $\beta = 0$. Hence, for arbitrary $\alpha$, we have the idempotent $z = e_3 + \alpha(e_1 - e_3).$ $\blacksquare$
\end{proof}

The union construction for two quandles has a twisted version when the quandles act on each other by automorphisms (see Proposition \ref{new2}). We consider a simple case of this construction when both the quandles are trivial. Note that the automorphism group of a trivial quandle is the symmetric group on the underlying set. Let $X, Y$ be trivial quandles, $f \in \Aut(X)$ and $g \in \Aut(Y)$. For $x \in X$ and $y \in Y$,  setting 
$$x*y = f(x) \quad  \textrm{and} \quad y*x = g(y)$$
defines a quandle structure on the disjoint union $X \sqcup Y$, and we denote this quandle by $X \sqcup_{f, g}Y$. The following result gives the precise description of idempotents for $X \sqcup_{f, g}Y$ \cite[Proposition 6.3]{MR4565221}.

\begin{proposition}\label{idempotens in trivial unions}
Let $X$ and $Y$ be trivial quandles of orders $n$ and $m$, respectively. Let $\mathbb{k}$ be an integral domain such that characteristic of $\mathbb{k}$ is coprime to both $n$ and $m$. Let $f \in Aut(X)$ and $g \in Aut(Y)$ be automorphisms acting transitively on $X$ and $Y$, respectively. Then 
\begin{small}
$$\mathcal{I}\big(\mathbb{k}[X \sqcup_{f, g} Y]\big)= \mathcal{I}\big(\mathbb{k}[X]\big) \sqcup~ \mathcal{I}\big(\mathbb{k}[Y]\big) \sqcup \Big\{\alpha \big(\sum_{x \in X} e_x \big) + \beta \big(\sum_{y \in Y} e_y \big) ~\bigl\vert~ \alpha, \beta \in \mathbb{k}~~\textrm{~such that~}~~\alpha n+ \beta m=1 \Big\}.$$
\end{small}
\end{proposition}

\begin{proof}
Note that any $u \in \mathbb{k}[X \sqcup_{f, g} Y]$ can be written uniquely as $u=v+w$, where $v= \sum_{x \in X} \alpha_x e_x \in \mathbb{k}[X]$, $w= \sum_{y \in Y} \beta_y e_y \in \mathbb{k}[Y]$ and $\alpha_x, \beta_y \in \mathbb{k}$. If $u=u^2$, then
$$v+w=v^2+w^2+vw+wv= \varepsilon(v)v + \varepsilon(w)w + \varepsilon(w) \sum_{x \in X} \alpha_x e_{f(x)}+ \varepsilon(v)\sum_{y \in Y} \beta_y e_{g(y)},$$
and consequently
$$v= \varepsilon(v)v + \varepsilon(w) \sum_{x \in X} \alpha_x e_{f(x)} \quad \textrm{and} \quad w= \varepsilon(w)w+ \varepsilon(v)\sum_{y \in Y} \beta_y e_{g(y)}.$$
Comparing coefficients give
\begin{equation}\label{eq union 1}
\alpha_x= \varepsilon(v) \alpha_x+ \varepsilon(w) \alpha_{f^{-1}(x)}
\end{equation}
and
\begin{equation}\label{eq union 2}
\beta_y = \varepsilon(w) \beta_y + \varepsilon(v) \beta_{g^{-1}(y)}
\end{equation}
for all $x\in X$ and $y \in Y$. Adding \eqref{eq union 1} for all $x \in X$ gives $\varepsilon(v)= \varepsilon(v) \varepsilon(u)$. Similarly, adding 
\eqref{eq union 2} for all $y \in Y$ gives $\varepsilon(w)= \varepsilon(w) \varepsilon(u)$. If $\varepsilon(u)=0$, then $\varepsilon(v)=\varepsilon(w)=0$, and hence $u=0$, a contradiction. So, we can assume that $\varepsilon(u)=1$, and hence at least one of $\varepsilon(v)$ or $\varepsilon(w)$ is non-zero. If $\varepsilon(v) \neq 0$, then \eqref{eq union 2} gives $\beta_y = \beta_{g^{-1}(y)}$ for all $y \in Y$. Since $g$ acts transitively on $Y$, it follows that $\beta_y= \beta$ (say) for all $y \in Y$. If $\beta=0$, then $w=0$. In this case, $u=\sum_{x \in X} \alpha_x e_x$, where $\sum_{x \in X} \alpha_x =1$, and hence $u \in  \mathcal{I}\big(\mathbb{k}[X]\big)$. If $\beta \neq 0$, then $\varepsilon(w) = m\beta \neq 0$, and \eqref{eq union 1} gives $\alpha_x= \alpha_{f^{-1}(x)}$ for all $x \in X$. Since $f$ also acts transitively on $X$, it follows that $\alpha_x= \alpha$ (say) for all $x \in X$. Thus, we have $$u= \alpha \big(\sum_{x \in X} e_x \big) + \beta \big(\sum_{y \in Y} e_y \big),$$ where $n \alpha +m \beta=1$. Similarly, if $\varepsilon(w) \neq 0$ and $\alpha = 0$, then we get $v=0$. In this case, $u=\sum_{y \in Y} \beta_y e_y$, where $\sum_{y \in Y} \beta_y =1$, and hence $u \in \mathcal{I}\big(\mathbb{k}[Y]\big)$. This completes the proof.  $\blacksquare$
\end{proof}
\bigskip
\bigskip
