\section{Quandle coverings and idempotents}\label{coverings and idempotents}
In this section, we use the idea of a quandle covering for giving a precise description of idempotents in quandle rings of quandles of finite type. The notion of a quandle covering is attributed to the work of Eisermann \cite{MR1954330, MR3205568}. 

\begin{definition}
    A quandle homomorphism $p: X  \to Y$ is called a \index{quandle covering}{\it quandle covering} if it is surjective and $S_x=S_{x'}$ whenever $p(x) = p(x')$ for any $x, x' \in X$. Clearly, an isomorphism of quandles is a quandle covering, called a \index{trivial covering}{\it trivial covering}. 

\end{definition}

\begin{example}{\rm 
Some basic examples of quandle coverings are as follows:
\begin{enumerate}
\item A surjective group homomorphism $p: G \to H$ yields a quandle covering $\Conj(G) \to \Conj(H)$ if and only if $\ker(p)$ is a central subgroup of $G$.
\item A surjective group homomorphism $p: G\to H$ yields a quandle covering $\Core(G) \to \Core(H)$ if and only if $\ker(p)$ is a central subgroup of  $G$ of exponent two.
\item Let $X$ be a quandle and  $F$ a non-empty set viewed as a trivial quandle. Consider $X \times F$ with the product quandle structure $(x,s) * (y,t) = (x *y,s)$. Then the projection $p: X \times F \to X$ given by $(x,s) \to x$ is a quandle covering.
\item Let $X$ be a quandle and $A$ an abelian group. Recall that, a quandle 2-cocycle is a map $\alpha: X \times X \to A$ satisfying
\begin{equation*} \label{group-coefficient-cocycle-condition}
\alpha_{x, y}~\alpha_{x*y, z}= \alpha_{x, z}~\alpha_{x* z, y*z}
\end{equation*}
and 
\begin{equation*}\label{normalised-cocycle-condition1}
\alpha_{x, x}=1
\end{equation*}
for $x, y, z \in X$. Given a 2-cocyle  $\alpha$, the set $X \times A$ turns into a quandle with the binary operation
\begin{equation*}\label{dynamical-quandle-operation}
(x, s)* (y,t)= \big( x* y, ~s~\alpha(x, y) \big),
\end{equation*} 
for $x, y \in X$ and $s, t \in A$. The quandle so obtained is called an  {\it extension} of $X$ by $A$ through $\alpha$, and is denoted by $X \times_{\alpha} A$. A direct check shows that the projection $p:X \times_{\alpha} A \to X$ given by $p(x, s)=x$ is a quandle covering.
\end{enumerate}}
\end{example}

The following lemma summarises some basic properties of quandle coverings, which we shall use without stating explicitly.

\begin{lemma}\label{quandle covering properties}
Let $p: X  \to Y$ be a quandle covering. Then the following  assertions hold:
\begin{enumerate}
\item Each fibre $p^{-1}(y)$ is a trivial subquandle of $X$. 
\item Each inner automorphism of $X$ permutes the fibres.
\item The fibres over any two elements of the same connected component of $Y$ are isomorphic.
\end{enumerate}
\end{lemma}

\begin{proof}
If $p: X  \to Y$ is a quandle homomorphism, then each fibre $p^{-1}(y)$ is a subquandle of $X$. Since $p$ is a covering, $S_x=S_{x'}$ whenever $x, x' \in p^{-1}(y)$. This gives $x*x'=S_{x'}(x)=S_x(x)=x$ and $x'*x=S_{x}(x')=S_{x'}(x')=x'$, which proves assertion (1).
\para
For assertion (2), it is enough to check that if $x_1, x_2 \in p^{-1}(y)$, then $S_x(x_1)$ and $S_x(x_2)$ are in the same fibre. Indeed, $p(S_x(x_1))=p(x_1*x)=
y*p(x)=p(x_2*x)=p(S_x(x_2))$, and we are done.
\para
Let $y, y'$ be elements of the same connected  component of $Y$. Then there exists elements $y_1, y_2, \ldots, y_n \in Y$ and $\mu_1, \mu_2, \ldots, \mu_n \in \{1, -1 \}$ such that $y'=y *^{\mu_1}y_1*^{\mu_2}y_2 \cdots *^{\mu_n}y_n$. Here the parentheses are left normalised. For each $i$,  choose one element $x_i \in p^{-1}(y_i)$. If $x \in p^{-1}(y)$, then we see that 
$$p(x*^{\mu_1} x_1*^{\mu_2} x_2 \cdots *^{\mu_n} x_n)= y*^{\mu_1}y_1*^{\mu_2}y_2 \cdots *^{\mu_n}y_n= y'.$$
Thus, the inner automorphism $S_{x_n}^{\mu_n}S_{x_{n-1}}^{\mu_{n-1}} \cdots S_{x_1}^{\mu_1}$ maps the fibre $p^{-1}(y)$ bijectively onto  $p^{-1}(y')$, which proves assertion (3). $\blacksquare$
\end{proof}

\begin{proposition}\label{covering with non-trivial idempotents}
Let $p:X \to Y$ be a non-trivial quandle covering and $\mathbb{k}$ an integral domain with unity. Then $\mathbb{k}[X]$ has non-trivial idempotents.
\end{proposition}

\begin{proof}
Since $p$ is a non-trivial covering, there is at least one connected component of $Y$ such that $|p^{-1}(y)| \ge 2$ for all elements $y$ of that connected component. By assertion (1) of Lemma \ref{quandle covering properties}, $p^{-1}(y)$ is a trivial subquandle of $X$. The result now follows from Proposition \ref{trivial subquandle idempotent}. $\blacksquare$
\end{proof}

A \index{long knot}{\it long knot} $L$ is the image of a smooth embedding $\ell: \mathbb{R} \hookrightarrow \mathbb{R}^3$ such that $\ell(t) = (t, 0, 0)$ for all $t$ outside some compact interval. We consider long knots only up to isotopy with compact support. The closure of a long knot is a usual knot defined in the obvious way.

\begin{proposition}\label{idempotents long knots}
Let $L$ be a non-trivial long knot in $\mathbb{R}^3$ and $\mathbb{k}$ an integral domain with unity. Then $\mathbb{k}[Q(L)]$ has non-trivial idempotents.
 \end{proposition}

\begin{proof}
Let $L$ be a long knot and $K$  its corresponding closed knot defined in the obvious way. Let $Q(L)$ and $Q(K)$ be knot quandles of $L$ and $K$, respectively. Note that $Q(K)$ is obtained from $Q(L)$ by adjoining one extra relation corresponding to the first and the last arc of $L$. By \cite[Theorem 35]{MR1954330}, the natural projection $p: Q(L) \to Q(K)$ is a non-trivial quandle covering, and the result follows from Proposition \ref{covering with non-trivial idempotents}. $\blacksquare$
 \end{proof}

Let $p:X \to Y$ be a quandle covering, and $\mathcal{F}(Y)$ the set of all finite subsets of $Y$. For each $y \in Y$, let $\mathcal{F}(p^{-1}(y))$ be the set of all finite subsets of $p^{-1}(y)$, and denote a typical element of this set by $I_y$. Given elements $x,y$ in a quandle $X$ of finite type, we set
$$[e_x]_y:= e_x+ e_{x*y}+ e_{x*y*y}+ \cdots +e_{x\underbrace{*y*y*\cdots *y}_{(n_y-1)-\textrm{times}}}=e_x+ e_{S_y(x)}+ e_{S_y^2(x)}+ \cdots +e_{S_y^{n_y-1}(x)},$$
the sum of the basis elements in the $S_y$-orbit of $e_x$. We have the following result \cite[Theorem 4.5]{MR4565221}.

\begin{theorem}\label{quandle covering theorem}
Let $X$ be a quandle of finite type, $p:X \to Y$ a non-trivial quandle covering and $\mathbb{k}$ an integral domain with unity. If $\mathbb{k}[Y]$ has only trivial idempotents, then the set of idempotents of $\mathbb{k}[X]$ is
\begin{small}
\begin{eqnarray}\label{quandle covering theorem idempotents}
\nonumber \mathcal{I} \big(\mathbb{k}[X]\big) &=& \Big\{ \sum_{y \in J} \Big( \sum_{x \in I_y,~~\sum \alpha_x =0}  \alpha_x~ [e_x]_{x_0} \Big) + \Big(\sum_{x' \in I_{y_0},~~\sum \alpha_{x'} =1} \alpha_{x'} ~e_{x'}\Big) ~\bigl\vert \\
 && J \in \mathcal{F}(Y),~~I_y \in \mathcal{F}(p^{-1}(y)),~~I_{y_0} \in \mathcal{F}(p^{-1}(y_0)),~~ x_0 \in  I_{y_0}, ~~y_0 \in Y, ~~\alpha_x, \alpha_{x'}  \in \mathbb{k} \Big\}.
\end{eqnarray}
\end{small}
\end{theorem}

\begin{proof}
Since $p$ is a quandle covering, we have $S_x=S_{x'}$ for any $x, x ' \in p^{-1}(y)$. Hence, the automorphisms of the quandle ring $\mathbb{k}[X]$ induced by $S_x$ and $S_{x'}$ are identical for any $x, x ' \in p^{-1}(y)$. This together with direct computations give
\begin{eqnarray}\label{even dihedral eq1}
&&\Big(\sum_{x \in J} \beta_{x}~ e_{x}\Big)\Big(\sum_{x' \in I_y,~~\sum \alpha_{x'} =1} \alpha_{x'} ~e_{x'}\Big)\\
\nonumber &=& \sum_{x' \in I_y,~~\sum \alpha_{x'} =1}\alpha_{x'} \Big( \sum_{x \in J} \beta_{x}~ e_{x} \Big) e_{x'}\\
\nonumber &=&\sum_{x' \in I_y,~~\sum \alpha_{x'} =1} \alpha_{x'} \Big( \sum_{x \in J} \beta_{x}~ e_{x} \Big)e_{x_0},\quad \textrm{for any fixed}~x_0\in I_y\\
\nonumber &=&\sum_{x' \in I_y,~~\sum \alpha_{x'} =1} \alpha_{x'} \Big( \sum_{x \in J} \beta_{x} ~e_{x*x_0} \Big)\\
\nonumber  &=&   \sum_{x \in J} \beta_{x}~ e_{x*x_0},\quad \textrm{since}~\sum_{x' \in I_y,~~\sum \alpha_{x'} =1} \alpha_{x'} =1,
\end{eqnarray}
and
\begin{eqnarray}\label{even dihedral eq2}
&&  \Big(\sum_{x \in J} \beta_{x} ~e_{x}\Big) \Big( \sum_{x' \in I_y,~~\sum \alpha_{x'} =0}  \alpha_{x'} ~e_{x'} \Big)\\
\nonumber &=&  \sum_{x' \in I_y,~~\sum \alpha_{x'} =0}  \alpha_{x'} \Big(\sum_{x \in J} \beta_{x} ~e_{x}\Big) e_{x'}\\
\nonumber &=&  \sum_{x' \in I_y,~~\sum \alpha_{x'} =0}  \alpha_{x'}\Big(\sum_{x \in J} \beta_{x}~ e_{x*x_0}\Big), \quad \textrm{for any fixed}~x_0 \in I_y\\
\nonumber &=& \Big(\sum_{x' \in I_y,~~\sum \alpha_{x'} =0}  \alpha_{x'} \Big) \Big(\sum_{x \in K} \beta_{x} ~e_{x*x_0}\Big)\\
\nonumber &=& 0,\quad \textrm{since}~ \sum_{x' \in I_y,~~\sum \alpha_{x'} =0}  \alpha_{x'}=0,
\end{eqnarray}
where $J \in \mathcal{F}(X)$, $I_y \in \mathcal{F}(p^{-1}(y))$,  $y \in Y$ and $\beta_x, \alpha_{x'}  \in \mathbb{k}$. Let $u=v+w$, where 
\begin{eqnarray*}
v &=&\sum_{y \in J} \Big( \sum_{x \in I_y,~~\sum \alpha_x =0}  \alpha_x ~[e_x]_{x_0}\Big),\\
w &=& \sum_{x' \in I_{y_0},~~\sum \alpha_{x'} =1} \alpha_{x'} ~e_{x'},\\
\end{eqnarray*}
$J \in \mathcal{F}(Y)$  and $x_0 \in  I_{y_0}$ a fixed element. Equations \eqref{even dihedral eq1} and \eqref{even dihedral eq2} imply that $w^2=w$, $wv=0$ and  $v^2=0$. By definition of the element $[e_x]_{x_0}$, it follows that $\big([e_x]_{x_0}\big)e_{x_0}=[e_x]_{x_0}$. Consequently, $vw=v$, and hence $u^2=u$. 
\para
For the converse, let $u$ be a non-zero idempotent of $\mathbb{k}[X]$. Since $X$ is the disjoint union of fibres of $p$, we can write $u$ uniquely in the form
$$u=\sum_{y \in J} \Big( \sum_{x \in I_y}  \alpha_x ~e_x \Big)$$
for some $J \in \mathcal{F}(Y)$ and $I_y \in \mathcal{F}(p^{-1}(y))$ for each $y \in J$. If $\hat{p}: \mathbb{k}[X] \to \mathbb{k}[Y]$ is the induced homomorphism of rings, then $\hat{p}(u)$ is an idempotent of $\mathbb{k}[Y]$. It follows from the decomposition of $u$ that
$$\hat{p}(u)=  \sum_{y \in J} \Big( \sum_{x \in I_y}  \alpha_x \Big) e_y.$$
Since $\mathbb{k}[Y]$ has only trivial idempotents, it follows that either $\hat{p}(u)=0$ or precisely one of the coefficients of $\hat{p}(u)$ is 1 and all other coefficients are 0. If $\hat{p}(u)=0$, then $\sum_{x \in I_y}  \alpha_x =0$ for each $y \in J$. Writing 
$$u=\sum_{y \in J} \Big( \sum_{x \in I_y, ~~\sum \alpha_{x} =0}  \alpha_x ~e_x \Big),$$
 it follows from \eqref{even dihedral eq2} that $u=u^2=0$, which is a contradiction as $u \ne 0$. Hence, there exists $y_0 \in J$ such that $\sum_{x' \in I_{y_0}}  \alpha_{x'}=1$ and $\sum_{x \in I_y}  \alpha_x=0$ for all $y \neq y_0$. We can write $u= v+w$, where 
$$v= \sum_{y \in J, ~y \neq y_0} \Big( \sum_{x \in I_y,~~\sum \alpha_x =0}  \alpha_x~ e_x \Big)$$ and $$w= \sum_{x' \in I_{y_0},~~\sum \alpha_{x'} =1} \alpha_{x'}~ e_{x'}.$$ Again, equations \eqref{even dihedral eq1} and \eqref{even dihedral eq2} imply that $w^2=w$, $wv=0$ and  $v^2=0$. Thus, we have
$$u=u^2=v^2+w^2+vw+wv= w+vw,$$
and consequently $v=vw$. This implies that 
$$\sum_{y \in J, ~y \neq y_0} \Big( \sum_{x \in I_y,~~\sum \alpha_x =0}  \alpha_x~ e_x \Big)= \sum_{y \in J, ~y \neq y_0} \Big( \sum_{x \in I_y,~~\sum \alpha_{x} =0}  \alpha_{x}~ e_{x} \Big) e_{x_0}$$
for some fixed $x_0 \in I_{y_0}$. Hence, it follows that $v$ has the form
$$v=\sum_{y \in J', ~y \neq y_0} \Big( \sum_{x \in I_y,~~\sum \alpha_x =0}  \alpha_x ~[e_x]_{x_0} \Big),$$
where $J' \subseteq J$ is a set of representatives of orbits of the action of $S_y$ on $J$. This completes the proof of the theorem. $\blacksquare$
 \end{proof}

 \begin{corollary}
If $X$ is a trivial quandle and $\mathbb{k}$ an integral domain with unity, then 
$$\mathcal{I}\big(\mathbb{k}[X]\big) =\Big\{ \sum_{x \in J} \alpha_x ~e_x  \, \mid \,    J \in \mathcal{F}(X)~\textrm{such that}~ \sum_{x \in J} \alpha_x=1 \Big\}.$$
 \end{corollary}
 \begin{proof}
If $\{z \}$ is a one element quandle, then the constant map $c: X \to \{z \}$ is a quandle covering. The proof now follows from Theorem \ref{quandle covering theorem}. $\blacksquare$
 \end{proof}

\begin{corollary}
Let $p:X \to Y$ be a non-trivial quandle covering and $\mathbb{k}$ an integral domain with unity. If $\mathbb{k}[Y]$ has only trivial idempotents, then every idempotent of $\mathbb{k}[X]$ has augmentation value 1.
\end{corollary}

\begin{proof}
The assertion follows from the proof of the converse part of Theorem \ref{quandle covering theorem}. Note that we do not need our quandles to be of finite type. $\blacksquare$
\end{proof}

The preceding result together with computer-assisted computations for quandles of order less than six suggests the following conjecture \cite[Conjecture 6.2]{MR4579329}.

\begin{conjecture}
Any non-zero idempotent of the integral quandle ring of a quandle has augmentation value 1.
\end{conjecture}

By Proposition \ref{idempotents-r3},  the integral quandle ring of $\R_3$ has only trivial idempotents. A computer assisted check shows that the same assertion holds for the integral quandle ring of $\R_5$ as well \cite[Section 6]{MR4579329}. As an application of the preceding theorem, we characterise idempotents in quandle rings of certain dihedral quandles of even order under the assumption of Conjecture \ref{Main conjecture}.

\begin{corollary}\label{even dihedral corollary}
Let $n=2m+1$ be an odd integer with $m \ge 1$ and $\mathbb{k}$ an integral domain with unity. Assume that $\mathbb{k}[\R_{n}]$ has only trivial idempotents. Then the set of idempotents of $\mathbb{k}[\R_{2n}]$ is given by
\begin{small}
$$\mathcal{I}\big(\mathbb{k}[\R_{2n}]\big) =\Big\{ \big(\beta e_j + (1-\beta)e_{n+j}\big)+ \sum_{i=0}^{m} \alpha_i \big(e_i-e_{n+i} + e_{2j-i}- e_{n+2j-i}\big) ~\bigl\vert ~ 0 \le j \le n-1 ~\textrm{and~} ~~ \alpha_i, \beta \in \mathbb{k} \Big\}.$$
\end{small}
 \end{corollary}

 \begin{proof}
Note that the natural map $p:\R_{2n} \to \R_{n}$ given by the reduction modulo $n$ is a two-fold non-trivial quandle covering. Further, for each $i \in \R_n$,  we have $p^{-1}(i)=\{i, n+i\}$. The result now follows from Theorem \ref{quandle covering theorem}. $\blacksquare$
 \end{proof}

\begin{proposition}\label{zero-divisors for coverings}
Let $p:X \to Y$ be a non-trivial quandle covering and $\mathbb{k}$ an integral domain with unity. Then $\mathbb{k}[X]$ has right zero-divisors.
 \end{proposition}

\begin{proof}
Let $J \in \mathcal{F}(X)$, $y \in Y$ and $I_y \in \mathcal{F}(p^{-1}(y))$ such that $|I_y| \ge 2$. Then for any $\sum_{x \in I_y,~~\sum \alpha_x =0}  \alpha_x e_x$ and $\sum_{x' \in J} \beta_{x'} e_{x'}$, it follows from \eqref{even dihedral eq2} that
$$\Big(\sum_{x' \in J} \beta_{x'} ~e_{x'}\Big) \Big( \sum_{x \in I_y,~~\sum \alpha_x =0}  \alpha_x ~e_x \Big)=0$$
and hence  $\sum_{x \in I_y,~~\sum \alpha_x =0}  \alpha_x e_x$ is a right zero-divisor of $k[X]$. $\blacksquare$
 \end{proof}

\begin{proposition}
Let $X$ be an involutory quandle and $\mathbb{k}$ an integral domain with unity. Let $A$ be a non-trivial abelian group and  $\alpha: X \times X \to A$ a quandle 2-cocycle.
\begin{enumerate}
\item  If $\alpha$ satisfy $\alpha_{x*y, y}=\alpha_{x, y}^{-1}$ for all $x, y \in X$, then the extension $X \times_{\alpha} A$ is involutory. 
\item If $\mathbb{k}[X]$ has only trivial idempotents, then $\mathbb{k}[X \times_{\alpha} A]$ has non-trivial idempotents.
\end{enumerate}
\end{proposition}

\begin{proof}
A direct check shows that the condition $\alpha_{x*y, y}=\alpha_{x, y}^{-1}$ is equivalent to the extension $X \times_{\alpha} A $ being involutory. Since the map $p:X \times_{\alpha} A \to X$ is a non-trivial quandle covering, the result follows from Theorem \ref{quandle covering theorem}. In fact, Theorem \ref{quandle covering theorem} gives the precise set of idempotents.  $\blacksquare$
\end{proof}

It turns out that the set of all idempotents of a quandle ring has the structure of a quandle in some cases \cite[Proposition 4.11]{MR4565221}.

\begin{proposition}\label{idempotents forming quandle covering}
Let $X$ be a quandle of finite type, $p : X \to Y$ a quandle covering and  $\mathbb{k}$ an integral domain with unity. Then the set 
\begin{eqnarray}
\nonumber  \mathcal{I} \big(\mathbb{k}[X]\big)  &=& \Big\{ \sum_{y \in J} \Big( \sum_{x \in I_y,~~\sum \alpha_x =0}  \alpha_x ~[e_x]_{x_0} \Big) + \Big(\sum_{x' \in I_{y_0},~~\sum \alpha_{x'} =1} \alpha_{x'}~ e_{x'}\Big) ~\bigl\vert \\
\nonumber && J \in \mathcal{F}(Y),~~I_y \in \mathcal{F}(p^{-1}(y)),~~I_{y_0} \in \mathcal{F}(p^{-1}(y_0)),~~ x_0 \in  I_{y_0}, ~~y_0 \in Y,~~\alpha_x, \alpha_{x'}  \in \mathbb{k}\Big\}
\end{eqnarray}
of idempotents of $\mathbb{k}[X]$ is a quandle with respect to the ring multiplication.
\end{proposition}

\begin{proof}
Consider the elements 
\begin{eqnarray*}
u &=& \sum_{y \in J_1} \Big( \sum_{x \in I_y,~~\sum \alpha_x =0}  \alpha_x ~ [e_x]_{x_1}  \Big) + \Big(\sum_{x' \in I_{y_1},~~\sum \alpha_{x'} =1} \alpha_{x'}~ e_{x'}\Big),\\
v &=&\sum_{y \in J_2} \Big( \sum_{x \in I_y,~~\sum \beta_x =0}  \beta_x ~[e_x]_{x_2}  \Big) + \Big(\sum_{x' \in I_{y_2},~~\sum \beta_{x'} =1} \beta_{x'}~ e_{x'}\Big)
\end{eqnarray*}
in $ \mathcal{I} \big(\mathbb{k}[X]\big) $, where $J_i \in \mathcal{F}(Y)$ and $I_{y} \in \mathcal{F}(p^{-1}(y))$, $y_i \in Y$ and $x_i \in I_{y_i}$. Then we have
\begin{eqnarray*}
& uv&\\
 &=& \Big(\sum_{y \in J_1} \Big( \sum_{x \in I_y,~~\sum \alpha_x =0}  \alpha_x ~ [e_x]_{x_1} \Big) + \Big(\sum_{x' \in I_{y_1},~~\sum \alpha_{x'} =1} \alpha_{x'}~ e_{x'}\Big) \Big) \\
&& \Big( \sum_{y \in J_2} \Big( \sum_{x \in I_y,~~\sum \beta_x =0}  \beta_x ~[e_x]_{x_2}  \Big) + \Big(\sum_{x' \in I_{y_2},~~\sum \beta_{x'} =1} \beta_{x'}~ e_{x'}\Big)\Big) \\
&=& \Big(\sum_{y \in J_1} \Big( \sum_{x \in I_y,~~\sum \alpha_x =0}  \alpha_x ~[e_x]_{x_1} \Big) + \Big(\sum_{x' \in I_{y_1},~~\sum \alpha_{x'} =1} \alpha_{x'} ~e_{x'}\Big) \Big) \Big(\sum_{x' \in I_{y_2},~~\sum \beta_{x'} =1} \beta_{x'}~ e_{x'}\Big),\\
&& \quad \textrm{by}~ \eqref{even dihedral eq2} \\
&=& \Big(\sum_{y \in J_1} \Big( \sum_{x \in I_y,~~\sum \alpha_x =0}  \alpha_x ~[e_x]_{x_1} \Big) + \Big(\sum_{x' \in I_{y_1},~~\sum \alpha_{x'} =1} \alpha_{x'} ~e_{x'}\Big) \Big) e_{x_2}, \quad \textrm{by} ~\eqref{even dihedral eq1}\\
&=& \sum_{y \in J_1} \Big( \sum_{x \in I_y,~~\sum \alpha_x =0}  \alpha_x ~\big([e_x]_{x_1}\big)e_{x_2} \Big) + \Big(\sum_{x' \in I_{y_1},~~\sum \alpha_{x'} =1} \alpha_{x'} ~ e_{x'*x_2}\Big),\\
&=& \sum_{y \in J_1} \Big( \sum_{x*x_2 \in I_{y*y_2},~~\sum \alpha_x =0}  \alpha_x~[e_{x*x_2}]_{x_1*x_2} \Big) + \Big(\sum_{x'*x_2 \in I_{y_1*y_2},~~\sum \alpha_{x'} =1} \alpha_{x'} ~e_{x'*x_2}\Big),
\end{eqnarray*}
since $\big([e_x]_{x_1}\big)e_{x_2}=[e_{x*x_2}]_{x_1*x_2}$ due to right-distributivity. Note here that $x_1*x_2 \in I_{y_1*y_2}$. Thus, we have proved that $uv \in  \mathcal{I} \big(\mathbb{k}[X]\big) $. The preceding computation also shows that the right multiplication by $v$ is precisely the right multiplication by 
$e_{x_2}$ for any fixed $x_2 \in I_{y_2}$. In other words, the right multiplication by $v$ is the ring automorphism $\hat{S}_{x_2}$ of $\mathbb{k}[X]$. This proves that the set $ \mathcal{I} \big(\mathbb{k}[X]\big) $ is a quandle. $\blacksquare$
\end{proof}

An immediate consequence of Proposition \ref{idempotents forming quandle covering} is the following result.

 \begin{corollary}\label{idempotens form quandle}
 Let $X$ be a quandle of finite type, $p : X \to Y$ a quandle covering and  $\mathbb{k}$ an integral domain with unity. Suppose that $\mathbb{k}[Y]$ has only trivial idempotents. Then the following  assertions hold:
\begin{enumerate}
\item The set of all idempotents of $\mathbb{k}[X]$ is  a quandle with respect to the ring multiplication.
\item The right multiplication by each idempotent of $\mathbb{k}[X]$ is a ring automorphism induced by some trivial idempotent of $\mathbb{k}[X]$.
\end{enumerate}
 \end{corollary}
