\chapter{Trunks and rack spaces}\label{chapter trunks and rack space}

\begin{quote}
This chapter builds on Fenn, Rourke, and Sanderson's concept of the rack space, a topological analogue of a group's classifying space. It introduces key concepts such as trunks, cubical sets, and square sets.  The construction of the rack space of a rack is then presented, from which the quandle space of a quandle is derived. The chapter also explores homotopy types of selected rack spaces and their second homotopy groups, offering insights into the topological aspects of racks and quandles.
\end{quote}
\bigskip

\section{Trunks}\label{trun}

Through an exploration of racks, particularly the rack space, Fenn, Rourke, and Sanderson \cite{MR1364012} were prompted to explore the notion of a trunk. In broad terms, a trunk can be considered as an entity akin to a category. We begin the section by presenting the subsequent definition.

\begin{definition}
A \index{trunk}{trunk} $T$ consists of a class of objects such that there is a set $\Hom_T(A,B)$ of morphisms for each ordered pair $(A,B)$ of
objects, and $T$ admits certain preferred squares
	\begin{equation}\label{preferred}
		\begin{tikzcd}[row sep=huge]
			A \arrow[r, "f"] \arrow[d, "k"]  & B  \arrow[d, "g"]  \\
			C \arrow[r, "h"]   & D 
		\end{tikzcd}
	\end{equation}	
of morphisms (a notion analogous to that of composition in a category). 	
\end{definition}

Note that, a trunk can be thought of as a directed graph, together with a collection of oriented squares called preferred squares.  There is a natural notion of a \index{trunk map}{trunk map} (or a functor). 

\begin{definition}
 Given trunks $T_1$ and $T_2$, a \index{trunk map}{trunk map} $F: T_1 \rightarrow T_2$ is a map that assigns to each  object $S$ of $T_1$ an object $F(S)$ of $T_2$, and to each morphism $f:A \rightarrow B$ of $T_1$ a morphism $F(f): F(A) \rightarrow F(B)$ of $T_2$  such that $F$ preserves preferred squares. 
 \end{definition}

 In other words, when the functor $F$ is covariant, the preferred square~(\ref{preferred}) gives the preferred square
\begin{equation*}
	\begin{tikzcd}[row sep=huge]
		F(A) \arrow[r, "F(f)"] \arrow[d, "F(k)"]  & F(B)  \arrow[d, "F(g)"]  \\
		F(C) \arrow[r, "F(h)"]   & F(D), 
	\end{tikzcd}
\end{equation*}	
and when the functor $F$ is contravariant, the preferred square~(\ref{preferred}) yields the preferred square

\begin{equation*}
	\begin{tikzcd}[row sep=huge]
		F(A)   & F(B)  \arrow[l, "F(f)"]  \\
		F(C) \arrow[u, "F(k)"]   & F(D).   \arrow[l, "F(h)"]   \arrow[u, "F(g)"] 
	\end{tikzcd}
\end{equation*}	


\begin{example}\label{trunk examples}
Let us consider some examples of trunks.
\begin{enumerate}
\item For each category $\mathcal{C}$,  there is a trunk $\mathcal{T}(\mathcal{C})$ which has the same objects and morphisms as $\mathcal{C}$, and whose preferred squares are the commutative diagrams in $\mathcal{C}$. 	
\item  Each rack $X$ defines a trunk $\mathcal{T}(X)$, called the \index{rack trunk}{rack trunk}, which has a single vertex $\bullet$ and has $X$ as its set of edges.  The preferred squares are of the  form	
\begin{equation*}
			\begin{tikzcd}[row sep=huge]
				\bullet \arrow[r, "x"] \arrow[d, "y"]  & 	\bullet \arrow[d, "y"]  \\
\bullet \arrow[r, "x*y"]   & 	\bullet,
\end{tikzcd}
\end{equation*}	
one for each ordered pair $(x,y)$ of elements of $X$. 
\item For each rack $X$, we define another trunk $\mathcal{T}'(X)$ as follows. For each element $x \in X$,  there is an object of $\mathcal{T}'(X)$ (also denoted by $x$); and for each ordered pair $(x,y)$ of elements of $X$, there is a morphism $\textbf{a}_{x,y}: x \rightarrow x*y$ and a morphism $\textbf{b}_{x,y}: y \rightarrow x*y$ such that the squares
		\begin{equation*}
			\begin{tikzcd}[row sep=huge]
				x \arrow[r, "\textbf{a}_{x,y}"] \arrow[d, "\textbf{a}_{x,z}"]  & 	x*y \arrow[d, "\textbf{a}_{x*y,z}"]  \\
				x*z \arrow[r, "\textbf{a}_{x*z,y*z}"]   & 	(x*y)*z=(x*z)*(y*z)
			\end{tikzcd}
		\end{equation*}	
		and 
		\begin{equation*}
			\begin{tikzcd}[row sep=huge]
				y \arrow[r, "\textbf{b}_{x,y}"] \arrow[d, "\textbf{a}_{x,z}"]  & 	x*y \arrow[d, "\textbf{a}_{x*y,z}"]  \\
				y*z \arrow[r, "\textbf{b}_{x*z,y*z}"]   & 	(x*y)*z=(x*z)*(y*z)
			\end{tikzcd}
		\end{equation*}	
are preferred squares for all $x,y,z \in X$.
\item The naturally oriented one-dimensional skeleton of the $n$-cube $I^n=[0,1]^n$ in $\mathbb{R}^n$ forms a trunk, where the preferred squares are the two-dimensional faces of $I^n$.
\end{enumerate}	
\end{example}

\begin{remark}\label{remark on trunk map}
{\rm 
Let $\mathcal{A}$ be the category of abelian groups. For each rack $X$, we define a trunk map $A: \mathcal{T}'(X) \to \mathcal{A}$ that assigns an abelian group $A_x$ to each $x \in X$ and assign  group homomorphisms $\eta_{x,y} \colon A_x \rightarrow A_{x*y}$ and $\xi_{x,y} \colon A_y \rightarrow A_{x*y}$ for each ordered pair $(x, y)$ of elements of $X$ such that 
$$	\eta_{x*y,z}\eta_{x,y}=\eta_{x*z,y*z} \eta_{x,z} \quad \textrm{and} \quad 
\eta_{x*y,z}\xi_{x,y} = \xi_{x*z,y*z} \eta_{x,z}
$$
for all $x,y,z \in X$.  Later, this trunk map will be used to define the notion of a quandle module in Chapter \ref{chapter homology YBE}.
}		
\end{remark}

\begin{definition}\label{corner}
A \index{corner trunk}{corner trunk} is a trunk that satisfies the following two corner axioms.
\begin{enumerate}
\item Given morphisms $f:A \rightarrow B$ and $k:A \rightarrow C$, there exist unique morphisms $g:B \rightarrow D$ and $h:C \rightarrow D$ such that the square 
		\begin{equation*}
			\begin{tikzcd}[row sep=huge]
				A \arrow[r, "f"] \arrow[d, "k"]  & B  \arrow[d, "g"]  \\
				C \arrow[r, "h"]   & D 
			\end{tikzcd}
		\end{equation*}	
is preferred.  
\item In the following diagram, if the center, south, and west squares are preferred, then it is possible to complete the diagram so that the east and north squares are also preferred.
		\begin{equation*}
			\begin{tikzcd}[row sep=huge]
				E \arrow{rrr} &&& F\\
				&A \arrow{r} \arrow{ul}& B \arrow{ur} &\\    
				&C  \arrow[r, "f"] \arrow[dl, "g"]  \arrow[u, "h"] &  D \arrow{dr}  \arrow{u}  & \\
				H   \arrow{rrr} \arrow{uuu}&&&G \arrow{uuu}
			\end{tikzcd}
		\end{equation*}	
In other words, assuming condition (1),  the morphisms $f$, $g$ and $h$ determine the entire diagram of preferred squares. 
\end{enumerate}
\end{definition}
\medskip


Next, we consider cubes and square sets. Let $I=[0,1]$ and $I^n=[0,1]^n$ be the $n$-cube in $\mathbb{R}^n$. A vertex of $I^n$ is a point of the form $(\epsilon_1, \ldots, \epsilon_n)$, where each $\epsilon_i=0$ or $1$.  A $p$-face of $I^n$ is a subset given by setting $(n-p)$ coordinates equal to either $0$ or $1$. For example, a $1$-face (also called an edge) is of the form 
$$\{ \epsilon_1 \} \times \cdots \times  \{ \epsilon_{j-1} \} 
\times I_j  \times \{ \epsilon_{j+1} \}  \times \cdots \times   \{ \epsilon_{n}\}$$
for some $j$ with $1 \leq j \leq n$,
where each $\epsilon_k = 0$ or $1$ and $I_j=I$. Similarly, a $2$-face has the form 
$$  \{ \epsilon_1 \} \times \cdots \times  \{ \epsilon_{i-1} \} 
\times I_i  \times \{ \epsilon_{i+1} \}  \times \cdots \times
\{ \epsilon_{j-1} \}  \times I_j  \times \{ \epsilon_{j+1} \}
\times \cdots \times  \{ \epsilon_{n}\}  $$
for some $i$ and $j$ with $1 \leq i<  j \leq n$, where each $\epsilon_k = 0$ or $1$ and $I_i=I_j=I$.  Faces can be given canonical orientations.  For simplicity of notation, we will think of a vertex of $I^n$ as a subset of $\{1, \ldots, n\}$ as follows: A subset $A \subseteq \{1, \ldots, n\}$ corresponds to a vertex with $\epsilon _i=1$ if and only if $i \in A$.  Then an edge has the form $A \rightarrow A\cup \{i\}$ with $i \notin A$.  
\para 

The $n$-cube $I^n$ can be regarded as a trunk (called the $n$-cube trunk) with the 2-faces
\begin{equation*}
	\begin{tikzcd}[row sep=huge]
		A \arrow[r] \arrow[d]  & 	A \cup \{i\} \arrow[d]  \\
		A \cup \{j\} \arrow[r]   & 	A \cup \{i\} \cup \{j\}
	\end{tikzcd}
\end{equation*}	
as preferred squares, where $1 \le i<j \le n$. In the following diagram, we see that if the center, south and west squares are preferred, then the diagram can be completed such that the east and north squares are also preferred.
\begin{equation*}
	\begin{tikzcd}[row sep=huge]
		B \cup \{i,k \}\arrow{rrr} &&&  B \cup \{i,j,k\}\\
		&B \cup \{k\} \arrow{r} \arrow{ul}& B  \cup \{j,k\} \arrow{ur} &\\    
		&B  \arrow[r, "f"] \arrow[dl, "g"]  \arrow[u, "h"] &  B \cup \{j\} \arrow{dr}  \arrow{u}  & \\
		B \cup \{i\}   \arrow{rrr} \arrow{uuu}&&&  B \cup \{i,j\} \arrow{uuu}.
	\end{tikzcd}
\end{equation*}	

Next, we provide the definition of the square category, which will be utilized subsequently in conjunction with trunks.

\begin{definition}
	The \index{square category}{square category} (~$\square$-category) is the category whose objects are the $n$-cubes $I^n$ for $n\ge 0$ and whose morphisms are the face maps.
\end{definition}

The face maps $\delta_i^\epsilon: I^{n-1} \rightarrow I^n$ corresponding to the $(n-1)$-faces of $I^n$ are given by $$ \delta_i^\epsilon(x_1, \ldots, x_{n-1})= (x_1, \ldots, x_{i-1},\epsilon, x_i, \ldots x_{n-1}),$$ where $\epsilon \in \{0,1\}$. It is not difficult to see that 

\begin{eqnarray}
	\delta_i^\epsilon \delta_{j-1}^\omega = \delta_{j}^\omega \delta_i^\epsilon
\end{eqnarray}
 for $1 \leq i<j\leq n$ and $\epsilon, \omega \in \{0,1\}$. Any face map $\lambda$ can be uniquely written as a composition $\delta_{i_k}^{\epsilon_k} \ldots \delta_{i_1}^{\epsilon_1}$, where each $\epsilon_j \in \{0,1\}$ and we assume that either $i_1<\cdots <i_k$ or $i_k \leq \cdots \leq i_1$.

\begin{definition}
A $\square$-set is a functor $C: \square^{\textrm{op}} \rightarrow \mathcal{S}$, where  $\square^{\textrm{op}}$ is the opposite category of the $\square$-category and $\mathcal{S}$ is the category of sets.  A $\square$-map between two $\square$-sets is a natural transformation of functors.  
\end{definition}

\begin{definition}
The \index{nerve}{nerve} of a trunk $T$ is the $\square$-set $NT$ satisfying the following conditions:
\begin{enumerate}
\item The set $NT_n$ is defined to be the set $\Hom(I^n,T)$ of trunk-maps from the cube trunk $I^n$ to the trunk $T$.  
\item The  map $\lambda^*$ is given by $\lambda^*(f)= f \circ \lambda$, where $\lambda \colon I^p \rightarrow I^n$ is a face map and $f \colon I^n \rightarrow T$ is a trunk map.
\end{enumerate}
\end{definition}

For an $n$-cube $I^n$ and a face map $\lambda$, we denote $C(I^n)$ by $C_n$ and  $C(\lambda)$ by $\lambda^*$.  We also denote $C(\delta_i^\epsilon)$ by  $\partial_i^\epsilon$. The geometric realization $|C|$ of a $\square$-set $C$ is defined to be the quotient space of the disjoint union $\bigsqcup_{n \geq 0} \; \big(C_n \times I^n \big)$ by the equivalence relation generated by
$$\big(\lambda^*(x),t \big) \sim \big(x, \lambda(t) \big),$$ 
where $x \in C_n$ and $t \in I^n$.  Note that $|C|$ is a CW-complex with one $n$-cell for each element of $C_n$ and  each $n$-cell has a canonical characteristic map from the $n$-cube.


\begin{remark}
{\rm A trunk has a natural cubical nerve, analogous to the simplicial nerve of a category. The classifying space of the trunk is the geometric realization of this nerve.   The rack space is the realization of a semi-cubical complex, and the natural structure is cubical, rather than simplicial as in the case of a classifying space. 
}    
\end{remark}
\bigskip

