\chapter{Homology and cohomology of solutions to the Yang--Baxter equation}\label{chapter homology YBE}

\begin{quote}
Fenn, Rourke, and Sanderson introduced a homology theory for racks as the homology of the rack space, as outlined in Chapter \ref{chapter trunks and rack space}. This initial development inspired the formulation of a (co)homology theory for racks and quandles by Carter, Jelsovsky, Kamada, Langford, and Saito. Later, a module theoretic approach to quandle cohomology was developed by Andruskiewitsch and Gra\~{n}a.  Subsequently,  Carter, Elhamdadi, and Saito extended the homology theory to encompass general solutions to the Yang--Baxter equation. These (co)homology theories have since undergone further expansion by Lebed and Vendramin, which encompasses and unifies all previously known theories in this domain. This chapter summarizes these advancements, includes selected computations, and explores their applications in knot theory.
\end{quote}
\bigskip


\section{Homology and cohomology of racks and quandles}\label{Homology} 
The subsequent construction of the chain complex leads to a homology theory for racks and quandles. This construction was introduced in \cite{MR1990571} as a variant of the homology of the rack space for a rack.
\para 
Let $(X,*)$ be a quandle. For each $n \ge 0$, let  $C_n^{\rm R}(X)$ be the free  abelian group generated by $n$-tuples $(x_1, \ldots, x_n)$ of elements of $X$. For each $n \geq 2$, define  $\partial_{n}: C_{n}^{\rm R}(X) \to C_{n-1}^{\rm R}(X)$ by 
\begin{eqnarray}
\partial_{n}(x_1, x_2, \dots, x_n) &=& \sum_{i=2}^{n} (-1)^{i} \big( (x_1, x_2, \dots, x_{i-1}, x_{i+1},\dots, x_n) \\
\nonumber && - (x_1 \ast x_i, x_2 \ast x_i, \dots, x_{i-1}\ast x_i, x_{i+1}, \dots, x_n) \big)
\end{eqnarray}
and set $\partial_n=0$ for $n \leq 1$. A simple verification demonstrates that $\partial_{n} ~ \partial_{n+1}=0$, and hence  
$C_\ast^{\rm R}(X)= \{C_n^{\rm R}(X), \partial_n \}$ is a chain complex.
\para 

For $n \geq 2$, let $C_n^{\rm D}(X)$ be the subgroup of $C_n^{\rm R}(X)$ generated
by $n$-tuples $(x_1, \dots, x_n)$ with $x_{i}=x_{i+1}$ for some $i \in \{1, \dots,n-1\}$, and otherwise set $C_n^{\rm D}(X)=0$. If $X$ is a quandle, then it follows that $\partial_n(C_n^{\rm D}(X)) \subseteq C_{n-1}^{\rm D}(X)$. Hence,
$C_\ast^{\rm D}(X) = \{ C_n^{\rm D}(X), \partial_n \}$ becomes a sub-complex of
$C_\ast^{\rm	R}(X)$.  Let $$C_n^{\rm Q}(X) := C_n^{\rm R}(X)/ C_n^{\rm D}(X)$$ and  $C_\ast^{\rm Q}(X) = \{ C_n^{\rm Q}(X), \overline{\partial}_n \}$ be the quotient complex, where $\overline{\partial}_n$ is the induced homomorphism, which we shall denote by $\partial_n$ again.
\para 

Let ${\rm W}={\rm D}$, ${\rm R}$, ${\rm Q}$. For each $n \ge 0$ and an abelian group $A$, define
$$ C_n^{\rm W}(X;A) = C_n^{\rm W}(X) \otimes_{\mathbb{Z}} A \quad \textrm{and} \quad \partial'_n :=\partial_n \otimes {\rm id}: C_n^{\rm W}(X;A) \to C_{n-1}^{\rm W}(X;A).$$
Similarly, we define
$$C^n_{\rm W}(X;A) = \Hom_{\mathcal{G}} \big(C_n^{\rm	W}(X), A \big) \quad \textrm{and} \quad \partial^n := \Hom(\partial_{n+1}, G): C^n_{\rm W}(X;A) \to C^{n+1}_{\rm W}(X;A).
$$
For convenience, we shall denote $\partial'_n$ by $\partial_n$.
\para 

Once we have the chain and the cochain complexes, we can define homology groups
$$\Ho_n^{\rm W}(X; A) = \Ho_{n} \big(C_\ast^{\rm W}(X;A) \big)$$
and cohomology groups
$$\Ho^n_{\rm W}(X; A)  = \Ho^{n}\big(C^\ast_{\rm W}(X;A)\big).$$
For ${\rm W}={\rm D}$, ${\rm R}$, ${\rm Q}$ and $n \ge 0$, the group $\Ho_n^{\rm W}(X; A)$ is called the $n$-th \index{degenerate homology}{degenerate}, \index{rack homology}{rack} and \index{quandle homology}{quandle homology} group of $X$ with coefficients in the abelian group $A$, respectively. Similarly, the group $\Ho^n_{\rm W}(X; A)$ is called the $n$-th \index{degenerate cohomology}{degenerate}, \index{rack cohomology}{rack} and \index{quandle cohomology}{quandle cohomology} group of $X$ with coefficients in the abelian group $A$, respectively.   We make use of the convention that whenever the coefficients of the (co)homology groups are not specified, we will mean $\mathbb{Z}$ coefficients. We denote by $\beta_n^{\rm W}(X)$ the $n$-th \index{Betti number}{Betti number} of $X$ determined by the homology group $\Ho_n^{W}(X)$.
\para 

It is natural to expect that the homology of racks and that of rack spaces are related. It follows from the construction of the rack space, the definition of cellular homology of a CW-complex and the definition of the rack homology of a rack,  that the cellular homology of the rack space is the same as the rack homology of the rack  \cite[Proposition 5.11]{MR3729413}.

\begin{proposition}\label{cellular and rack same}
Let $X$ be a rack.  Then the cellular chain complex of the rack space $BX$ and the rack chain complex of $X$ are isomorphic as chain complexes. As a consequence, 
$$\Ho_n^{\rm R}(X; A) \cong \Ho_n^{\rm Cell}(BX; A)\quad \textrm{and} \quad \Ho^n_{\rm R}(X; A) \cong \Ho^n_{\rm Cell}(BX; A)$$ for each $n \ge 0$ and for each abelian group $A$.
\end{proposition}

The simillar result holds for quandles and quandle spaces \cite[Proposition 5.11]{MR3729413}.

\begin{proposition}\label{cellular and quandle same}  
Let $X$ be a quandle.  Then the cellular chain complex of the quandle space $\widehat{BX}$  and the quandle chain complex of $X$ are isomorphic as chain complexes. As a consequence, 
		$$\Ho_n^{\rm Q}(X; A) \cong \Ho_n^{\rm Cell} \big(\widehat{BX}; A \big)\quad \textrm{and} \quad \Ho^n_{\rm Q}(X; A) \cong \Ho^n_{\rm Cell}\big(\widehat{BX}; A\big)$$ for each $n \ge 0$ and for each abelian group $A$.
	\end{proposition}

In view of Proposition \ref{cellular and rack same} and Proposition \ref{homology free rack space}, we have the following result for free racks.

\begin{proposition}
Let $FR_n$ be the free rack of rank $n$ and $A$ an abelian group.  Then
$$
\Ho_m^{\rm R}(FR_n; A) \cong
\left\{
\begin{array}{ll}
A  &    \textrm{if}~~ m=0,\\
A^n   &    \textrm{if}~~ m=1,\\
1  & \textrm{otherwise.}
\end{array}
\right.
$$
\end{proposition}

See \cite[Theorem 3.1]{MR3196064} and \cite[Remark 2.6]{arXiv:2011.04524} for independent proofs of the preceding proposition. Further, a similar result holds for free quandles \cite[Theorem 4.1]{MR3196064}.

\begin{proposition}
Let $FQ_n$ be the free quandle of rank $n$ and $A$ an abelian group.  Then
$$
\Ho_m^{\rm Q}(FQ_n; A) \cong
\left\{
\begin{array}{ll}
A  &    \textrm{if}~~ m=0,\\
A^n   &    \textrm{if}~ ~m=1,\\
1  & \textrm{otherwise.}
\end{array}
\right.
$$
\end{proposition}

\begin{proposition}\cite[Proposition 3.3]{MR1812049}
If $X$ is a quandle, then there is a long exact sequence 
 \begin{eqnarray}\label{Basic Homology Long Exact Sequence}
		\cdots \stackrel{\updelta_n}{\longrightarrow} \Ho_n^{\rm D}(X;A) \stackrel{i_n}{\longrightarrow} \Ho_n^{\rm R}(X;A)
		\stackrel{j_n}{\longrightarrow} \Ho_n^{\rm Q}(X;A)
		\stackrel{\updelta_{n-1}}{\longrightarrow} \Ho_{n-1}^{\rm D}(X;A) \longrightarrow \cdots
	\end{eqnarray}
of quandle homology groups which is natural with respect to homomorphisms induced by quandle homomorphisms. Here, each $\updelta_n$ is a connecting homomorphism.
\end{proposition}

\begin{proof}
By standard homological algebra, the short exact sequence of chain complexes    
$$1 \longrightarrow C_*^{\rm D}(X)\otimes_{\mathbb{Z}} A \stackrel{i\otimes \id}{\longrightarrow} C_n^{\rm R}(X)\otimes_{\mathbb{Z}}  A \stackrel{j\otimes \id}{\longrightarrow} C_n^{\rm Q}(X) \otimes_{\mathbb{Z}}  A \longrightarrow 1$$ 
induces the desired long exact sequence of homology groups. $\blacksquare$
\end{proof}


We have the following split exact sequences \cite[Proposition 3.4]{MR1812049}.  

\begin{proposition}\label{Universal Coefficient Theorem}
	There exist split exact sequences
	\begin{eqnarray*}
		1 \longrightarrow \Ho_n^{\rm W}(X) \otimes A \longrightarrow \Ho_n^{\rm W}(X; A) \longrightarrow
		{\rm Tor} \big(\Ho_{n-1}^{\rm W}(X), A \big) \longrightarrow 1 \\
		1 \longrightarrow {\rm Ext} \big(\Ho_{n-1}^{\rm W}(X), A \big) \longrightarrow \Ho^n_{\rm W}(X; A) \longrightarrow
		{\rm Hom} \big(\Ho_n^{\rm W}(X), A \big) \longrightarrow 1,
	\end{eqnarray*}
	where ${\rm W} = {\rm R}$ if $X$ is
	a rack, or one of ${\rm D}$, ${\rm R}$, ${\rm Q}$ if $X$ is a quandle.
\end{proposition}

\begin{proof}
Since $C_*^W(X)$ is a chain complex of free abelian groups, the result follows from the \index{Universal Coefficient Theorem}Universal Coefficient Theorems \cite[Theorems 53.1 and 55.1]{MR0755006}.  $\blacksquare$
\end{proof}

Let us consider some elementary examples of computations \cite[Examples 3.5 and 3.6]{MR1812049}.

\begin{example}\label{dihedral quandle of order three homology}
{\rm 
Let $\R_3$ be the dihedral quandle of three elements. Direct calculations using the definition gives
\begin{eqnarray*}
\Ho_1^{\rm Q}(\R_3) = \mathbb{Z} \quad \textrm{and} \quad  \quad \Ho_2^{\rm Q}(\R_3) = 1. 
\end{eqnarray*}
Thus, we have
\begin{eqnarray*}
\Ho_2^{\rm Q}(\R_3;A) = 1 \quad \textrm{and} \quad  \quad \Ho^2_{\rm Q}(\R_3;A) = 1 
\end{eqnarray*}
for any coefficient group $A$.
\para

Let $\R_4$ be the dihedral quandle of four elements. Direct calculations give
\begin{eqnarray*}
\Ho_1^{\rm Q}(\R_4) = \mathbb{Z}^2 \quad \textrm{and} \quad  \Ho_2^{\rm Q}(\R_4) = \mathbb{Z}^2 \oplus (\mathbb{Z}_2)^2. 
\end{eqnarray*}
Hence, we obtain
\begin{eqnarray*}
\Ho_2^{\rm Q}(\R_4;\mathbb{Z}_2) = (\mathbb{Z}_2)^4 \quad \textrm{and} \quad  \quad \Ho^2_{\rm Q}(\R_4;\mathbb{Z}_2) = (\mathbb{Z}_2)^4
\end{eqnarray*}
and
\begin{eqnarray*}
\Ho_2^{\rm Q}(\R_4;\mathbb{Z}_m) = (\mathbb{Z}_m)^2 \quad \textrm{and} \quad  \quad \Ho^2_{\rm Q}(\R_4;\mathbb{Z}_m) = (\mathbb{Z}_m)^2
\end{eqnarray*}
for any odd positive integer $m$.
}
\end{example}

\begin{example}\label{homology of trivial quandle}
{\rm 
Let $\T_m$ be the trivial quandle with $m < \infty$ elements. Since each $\partial_n :C_n^{\rm R}(\T_m) \to C_{n-1}^{\rm R}(\T_m)$ is the zero map, the connecting homomorphisms $\updelta_\ast$ in the long exact homology sequence with $A=\mathbb{Z}$ are
zero maps. Hence, the long exact sequence is decomposed into the short exact sequences
\begin{eqnarray*}
1 \to \Ho_n^{\rm D}(\T_m) \to \Ho_n^{\rm R}(\T_m) \to \Ho_n^{\rm Q}(\T_m) \to 1,
\end{eqnarray*}
which are further identified with the short exact sequences 
\begin{eqnarray*}
1 \to C_n^{\rm D}(\T_m) \to C_n^{\rm R}(\T_m) \to C_n^{\rm Q}(\T_m) \to 1.
\end{eqnarray*}
In particular, we have
\begin{eqnarray*}
\beta_n^{\rm D}(\T_m) &=& {\rm rank} \big(C_n^{\rm D}(\T_m) \big),\\
\beta_n^{\rm R}(\T_m) &=& m^n,\\ 
\beta_n^{\rm Q}(\T_m) &=& {\rm rank} \big(C_n^{\rm Q}(\T_m) \big).
\label{eqn:BettiTrivial}
\end{eqnarray*}
}
\end{example}
\para 

Let $X$ be a quandle and $\mathcal{O}(X)$ the set of orbits of $X$. For simplicity, we assume that $|\mathcal{O}(X)| = m < \infty$. Let $\pi: X \to \mathcal{O}(X) \cong \T_m$ be the natural projection from $X$ onto its set of orbits, which is identified with the trivial quandle $\T_m$. The naturality of the
 long exact homology  sequence gives the following  commutative diagram
\begin{eqnarray} \label{eqn:BasicTrivializingDiagram}
\begin{array}{ccccccccc}
\cdots & \stackrel{\updelta_n}{\longrightarrow}
& \Ho_n^{\rm D}(X) & \stackrel{i_n}{\longrightarrow}
& \Ho_n^{\rm R}(X) & \stackrel{j_n}{\longrightarrow}
& \Ho_n^{\rm Q}(X) & \stackrel{\updelta_{n-1}}{\longrightarrow} & \cdots
\\ {} & {} & \downarrow {\pi_\ast} & {} & \downarrow {\pi_\ast} & {} & \downarrow {\pi_\ast} & {} & {} \\
1 & \longrightarrow
& \Ho_n^{\rm D}(\T_m) & \stackrel{i_n}{\longrightarrow}
& \Ho_n^{\rm R}(\T_m) & \stackrel{j_n}{\longrightarrow}
& \Ho_n^{\rm Q}(\T_m) & \longrightarrow 1. & 
\end{array}
\end{eqnarray}

\begin{proposition}\cite[Proposition 3.8]{MR1812049}.
Let $X$ be a quandle. Then the following  assertions hold:
\begin{enumerate}
\item $\Ho_1^{\rm D}(X)= 1$.
\item $\Ho_1^{\rm R}(X)\cong \Ho_1^{\rm Q}(X) \cong \mathbb{Z}^{|\mathcal{O}(X)|}$.
\end{enumerate}
\end{proposition}

\begin{proof}
By definition, $\Ho_1^{\rm D}(X)= \Ho_0^{\rm D}(X)=1$ for any quandle $X$. Thus, it follows from the long exact homology sequence that $\Ho_1^{\rm R}(X) \cong \Ho_1^{\rm Q}(X)$ for any quandle $X$.  The group $Z_1^{\rm R}(X)$ of 1-cycles is freely generated by elements of $X$ and the  group $B_1^{\rm R}(X)$ of 1-boundaries is generated by the images $\partial_2((x,y))= x - x \ast y$ for all $x,y \in X$. Hence, $\Ho_1^{\rm R}(X)$ is generated by $\{ [x_\omega] \, \mid \, \omega \in \mathcal{O}(X) \}$, where $[x_\omega]$ is the homology class of $x_\omega$, which is a representative of the orbit $\omega$ of $X$. Let $m =|\mathcal{O}(X)|$ and $\T_m$ the trivial quandle with $m$ elements. By Example \ref{homology of trivial quandle}, $\beta_1^{\rm R}(\T_m) = m$, and hence $\Ho_1^{\rm R}(\T_m)\cong \mathbb{Z}^m$ is the free abelian group generated by $\T_m \cong \mathcal{O}(X)$. Considering the commutative diagram \eqref{eqn:BasicTrivializingDiagram} for $n=1$ and noting that $\pi_\ast: \Ho_1^{\rm R}(X) \to \Ho_1^{\rm R}(\T_m)$ maps $[x_\omega]$ to $[\omega]$,  we see that $\pi_\ast$ an isomorphism.
$\blacksquare$
\end{proof}

A result of Litherland and Nelson \cite{MR1952425} shows that the long exact sequence \eqref{Basic Homology Long Exact Sequence} decomposes into short exact sequences of quandle homology groups. We need the following set-up to prove this result. 
\para 
For $x = (x_1, \ldots, x_n)\in X^n$ and $y \in X$, we set
$x \diamond y := (x_1, \ldots, x_n, y)\in X^{n+1}$ and $ x*y: =
(x_1*y, \ldots, x_n*y) \in X^n$. Then, for $c \in C^{\rm R}_n(X)$, we define
$c \diamond y \in C^{\rm R}_{n+1}(X)$ and $c*y\in C^{\rm R}_n(X)$ by linearity. More precisely, if $c= \sum_{i=1}^k \alpha_i (x_{i_1}, x_{i_2}, \ldots,  x_{i_n})$, then 
$$c \diamond y= \sum_{i=1}^k \alpha_i (x_{i_1}, x_{i_2}, \ldots,  x_{i_n}, y) \quad \textrm{and} \quad c * y= \sum_{i=1}^k \alpha_i (x_{i_1}*y, x_{i_2}*y, \ldots,  x_{i_n}*y).$$ 
Also, note that $$\partial_{n+1}(c \diamond y) = \partial_n(c) \diamond y +(-1)^{n+1}(c - c*y).$$ Next we define homomorphisms ${\alpha_n}:{C^{\rm R}_n(X)} \rightarrow {C^{\rm R}_n(X)}$ by induction on $n$. We take $\alpha_1$ to be the identity map. For $n \geq 1$, $x = (x_1, \ldots, x_n)\in X^n$ and $y\in X$, we define $\alpha_{n+1}$ by the recursive formula
$$
 \alpha_{n+1}( x \diamond y) = \alpha_n( x)\diamond y -\alpha_n( x)\diamond x_n.
$$
We also define homomorphisms ${\beta_n}:{C^{\rm R}_n(X)} \rightarrow {C^{\rm R}_{n+1}(X)}$
by $\beta_n( x) = \alpha_n( x)\diamond x_n$.  Then, for any $c \in
C^{\rm R}_n(X)$ and $y\in X$, we have the relation
\begin{equation}\label{equation in litherland2}
 \alpha_{n+1}(c \diamond y) = \alpha_n(c)\diamond y - \beta_n(c).
\end{equation}

\begin{lemma}\label{litherland nelson lemma} 
The homomorphisms ${\alpha_n}:{C^{\rm R}_n(X)} \rightarrow {C^{\rm R}_n(X)}$
form a chain map ${\alpha}:{C^{\rm R}_*(X)} \rightarrow {C^{\rm R}_*(X)}$.
\end{lemma}

\begin{proof} 
Induction on $n$ shows that $\alpha_n( x*y) = \alpha_n(x)*y$ for $ x \in X^n$ and $y\in X$. We prove by induction on $n$ that $\partial_n \alpha_n = \alpha_{n-1}\partial_n$ for $n \geq 2$. For $n = 2$, we have $\alpha_2(x,y) = (x,y)-(x,x)$ and hence $\partial_2 \alpha_2(x,y) = \partial_2(x,y) =
\alpha_1\partial_2(x,y)$.  Suppose that the result is true for some
$n \geq 2$, and let $ x= (x_1, \ldots, x_n) \in X^n$ and $y\in X$. We compute
\begin{eqnarray*}
\partial_{n+1} \alpha_{n+1}( x \diamond y)
&=&\partial_{n+1} \bigl(\alpha_n( x) \diamond y\bigr) -
\partial_{n+1} \bigl(\alpha_n( x) \diamond  x_n\bigr)\\
&=&\partial_n \alpha_n( x) \diamond y + (-1)^{n+1}\bigl(\alpha_n( x) -
\alpha_n( x)*y\bigr) \\
&&- \partial_n  \alpha_n( x) \diamond  x_n
- (-1)^{n+1}\bigl(\alpha_n( x)
- \alpha_n( x)*{x_n}\bigr) \\
&=&\alpha_{n-1} \partial_n( x) \diamond y -
\alpha_{n-1}\partial_n ( x) \diamond x_n
+ (-1)^n\alpha_n( x*y) -
(-1)^n\alpha_n( x*{x_n})
\end{eqnarray*}
and
\begin{eqnarray*}
\alpha_n\partial_{n+1} ( x \diamond y) &=& \alpha_n\bigl(\partial_n ( x) \diamond y
+ (-1)^{n+1}( x -  x * y)\bigr)\\
&=& \alpha_{n-1}\partial_n ( x)\diamond y - \beta_{n-1}\partial_n ( x)
- (-1)^n\alpha_n( x) + (-1)^n\alpha_n( x*y).
\end{eqnarray*}
Hence, $\partial_{n+1} \alpha_{n+1}( x \diamond y) = \alpha_n\partial_{n+1} ( x \diamond y)$ if and only if
\begin{equation}\label{equation in litherland}
\alpha_{n-1} \partial_n(x) \diamond x_n + (-1)^n\alpha_n( x*{x_n})
= \beta_{n-1}\partial_n ( x) + (-1)^n\alpha_n( x).    
\end{equation}

We shall need the components of the boundary maps $\partial_n$ of the chain complex. For $1 \leq i \leq n$, $\epsilon = 0$ or 1, let $ {\partial ^\epsilon_i}: {X^n} \rightarrow {X^{n-1}}$ be the maps given by
\begin{eqnarray*}
 \partial^0_i(x_1,\ldots,x_n) & = & (x_1,\ldots,x_{i-1},x_{i+1},\ldots,x_n)\\
 \hbox{and}\qquad
 \partial^1_i(x_1,\ldots,x_n) & = & (x_1*{x_i},\ldots,x_{i-1}*{x_i},x_{i+1},\ldots,x_n).
\end{eqnarray*}
Now, for $1 \leq i < n$ and $\epsilon = 0$ or 1, the element  $\partial_i^\epsilon( x)$ of $X^{n-1}$ has last entry $x_n$. Thus, $\alpha_{n-1}\partial_i^\epsilon( x)\diamond x_n
=\beta_{n-1}\partial_i^\epsilon( x)$. Further, using \eqref{equation in litherland2}, we obtain
\begin{eqnarray*}
\alpha_{n-1}\partial_n^0( x)\diamond x_n-\beta_{n-1}\partial_n^0( x)
&=& \alpha_n\bigl(\partial_n^0( x)\diamond x_n\bigr) =\alpha_n( x)\\
\hbox{and}\qquad
\alpha_{n-1}\partial_n^1( x)\diamond x_n -\beta_{n-1}\partial_n^1( x)
&=&\alpha_n\bigl(\partial_n^1( x)\diamond x_n\bigr)
=\alpha_n( x*{x_n}).
\end{eqnarray*}
%(The last step here uses the quandle condition.)  
It follows that
$$\alpha_{n-1}\partial_n( x)\diamond x_n -\beta_{n-1}\partial_n( x)
 =(-1)^n\bigl(\alpha_n( x)-\alpha_n( x*{x_n})\bigr),
$$
which establishes \eqref{equation in litherland}, and hence we obtain the lemma.
$\blacksquare$
\end{proof}


\begin{theorem}\cite[Theorem 4]{MR1952425}
If $X$ is a quandle, then each connecting homomorphism $\updelta_\ast: \Ho_n^{\rm Q}(X) \to \Ho_{n-1}^{\rm D}(X)$ is zero. Consequently, the long exact sequence \eqref{Basic Homology Long Exact Sequence} decomposes into short exact sequences
	\begin{eqnarray}
		1 \longrightarrow \Ho_n^{\rm D}(X)  \stackrel{i_n}{\longrightarrow} \Ho_n^{\rm R}(X)
		\stackrel{j_n}{\longrightarrow}
		\Ho_n^{\rm Q}(X) \longrightarrow 1
  \end{eqnarray}
  of homology groups for each $n$.
\end{theorem}

\begin{proof} 
By Lemma \ref{litherland nelson lemma}, the maps $\gamma_n: C^{\rm R}_n(X) \to C^{\rm R}_n(X)$ given by $\gamma_n(c)= c - \alpha_n(c)$ gives a chain map $\gamma_*: C^{\rm R}_*(X) \to C^{\rm R}_*(X)$. We show that each $\gamma_n$ is a projection onto the subcomplex $C^{\rm D}_n(X)$. Thus, we need to prove the following assertions:
\begin{enumerate}
\item If $c \in C^{\rm D}_n(X)$, then $\alpha_n(c) = 0$.
\item If $c \in C^{\rm R}_n(X)$, then $c-\alpha_n(c) \in C^{\rm D}_n(X)$.
\end{enumerate}
For $n=1$, $C^{\rm D}_n(X)=0$, and hence assertion (1) is true in this case. Let $n \geq 1$, $x = (x_1, \ldots, x_n)\in X^n$ and $y\in X$. Suppose that $ x \diamond y \in C^{\rm D}_{n+1}(X)$.  Then either $ x \in C^{\rm D}_n(X)$ or $x_n = y$. If $ x \in C^{\rm D}_n(X)$, then  using the formula $ \alpha_{n+1}( x \diamond y) = \alpha_n( x)\diamond y -\alpha_n( x)\diamond x_n$ and the induction hypothesis, we obtain $\alpha_{n+1}( x \diamond y) = 0$. And, if $x_n = y$, then $\alpha_{n+1}( x \diamond y)=\alpha_{n+1}( x \diamond x_n) =\alpha_n(x) \diamond x_n-\alpha_n(x) \diamond x_n =0$.  Since $\alpha_n$ is linear, if $c \in C^{\rm D}_n(X)$ is a general element, then $\alpha_n(c) = 0$.  This proves assertion (1).  
\par

Assertion (2) is clear for $n=1$. Let  $n \geq 1$, $ x \in X^n$ and $y\in X$. Then we have
$$ x \diamond y - \alpha_{n+1}( x \diamond y) = \bigl(x -\alpha_n( x)\bigr)\diamond y -\bigl( x -\alpha_n( x)\bigr)\diamond x_n + x \diamond x_n.$$
Since $ x \diamond x_n \in C^{\rm D}_{n+1}(X)$ and $x -\alpha_n( x) \in C^{\rm D}_{n}(X)$ by induction hypothesis, it follows that  $ x \diamond y -\alpha_{n+1}( x \diamond y)$, and assertion (2) follows. It follows that $\gamma_* \,i_*: C^{\rm D}_*(X) \to C^{\rm D}_*(X)$ is the identity chain map, and hence the induced maps $i_n: \Ho_n^{\rm D}(X) \rightarrow \Ho_n^{\rm R}(X)$ of homology groups are injective. Exactness of the long exact homology sequence implies that the connecting homomorphisms $\updelta_n:\Ho_n^{\rm Q}(X) \rightarrow \Ho^{\rm D}_{n-1}(X)$ are zero, which proves the theorem. $\blacksquare$
\end{proof}


\begin{remark}
The preceding theorem was conjectured in \cite[p. 142]{MR1812049} and verified therein for $n=3$ \cite[Proposition 3.9]{MR1812049}. Further, the theorem was proved for $n=4$ in \cite{MR1825963}.
\end{remark}

In \cite[Section 4]{MR1948837}, Etingof and Gra\~na extended and sharpened results of \cite{MR1812049, MR1952425, MR1960136} on Betti numbers of finite quandles.  More precisely, they proved that if $X$ is a finite quandle, then the lower bounds for the Betti numbers of rack, quandle and degenerate cohomologies of $X$ given in \cite{MR1812049} are in fact equalities. 

\begin{theorem}
Let $X$ be a finite quandle with $m$ orbits under the action of $\Adj(X)$ on $X$. Then the Betti numbers of the rack, quandle and degenerate cohomologies of $X$ are given by
$$\beta_n^{\rm D}(X) = a_n, \quad  \beta_n^{\rm R}(X) = m^n \quad \textrm{and} \quad  \beta_n^{\rm Q}(X) = b_n,$$
where $a_n+b_n=|X|^n$ and $b_n= |X| \big(|X|-1 \big)^{n-1}$ for $n \ge 1$.
\end{theorem}

\begin{remark}
{\rm
It is well-known that the bounded cohomology of groups is intimately related to word metrics on groups, and is a key tool in the geometry of manifolds and rigidity theory. Building on this insight, Kedra \cite{MR4779104} introduced the concept of bounded cohomology for racks and quandles, linking it to a natural metric derived from their internal symmetries. This work appears to have initiated the incorporation of geometric perspectives into the study of racks and quandles.}
\end{remark}
