\section{Module theoretic approach to quandle cohomology}
In this section, we consider a general cohomology theory for racks and quandles developed by Andruskiewitsch and Gra\~{n}a \cite{MR1994219}.  Braided vector spaces arising from groups play a fundamental role in the classification of finite-dimensional complex pointed Hopf algebras. The most important class of braided vector spaces arising from groups is the class of braided vector spaces $(\mathbb{C}X, r_\phi )$, where $X$ is a rack and $\phi$ is a 2-cocycle on
$X$ with coefficients in $\mathbb{C}$. This lead Andruskiewitsch and Gra\~{n}a to study cohomology of racks and quandles, thereby developing a general cohomology theory that encompasses the previously defined cohomology theories.  
\para 

\subsection{Cohomology with coefficients in a quandle module}
Let $X$ be a rack or a quandle and $\Omega (X)$ the free ${\mathbb{Z}}$-algebra  generated by the symbols $\eta_{x,y},$ $\xi_{x,y}$   for $x,y \in X$ with the condition that $\eta_{x,y}$ is invertible for every $x,y \in X$.  Then we have the following definition \cite[Definition 2.22]{MR1994219}. 

\begin{definition}\label{QuandAlg}
The  \index{rack algebra}{\it rack algebra} $\mathbb{Z}\{X\}$ of a rack $X$ is defined to be the  quotient  of $\Omega(X)$ by the relations
\begin{eqnarray}
  \label{rack alg rel 1}\eta_{x*y,z}\eta_{x,y} & =&  \eta_{x*z,y*z}\eta_{x,z},\\
 \label{rack alg rel 2}\eta_{x*y,z}\xi_{x,y} & =&  \xi_{x*z,y*z}\eta_{y,z},\\
 \label{rack alg rel 3}\xi_{x*y,z}& =& \eta_{x*z,y*z} \xi_{x,z} + \xi_{x*z,y*z}\xi_{y,z}.
\end{eqnarray}
The  \index{quandle algebra}{\it quandle algebra} $\mathbb{Z}(X)$ of a quandle $X$ is defined to be the  quotient  of $\Omega(X)$ by the relations \eqref{rack alg rel 1}--\eqref{rack alg rel 3} together with the relation
\begin{eqnarray}
\label{quandle alg rel 1} \xi_{x,x} + \eta_{x,x} &=& 1.
\end{eqnarray}
\end{definition}

\begin{remark}{\rm 
Notice the abuse of terminology. The quandle algebra defined above is not the same as the quandle algebra defined in Chapter \ref{chaper quandle rings}.}
\end{remark}


\begin{definition}
Let $X$ be a rack. A  representation of the rack algebra $\mathbb{Z}\{X\}$ is an abelian group $A$ together a family $\{\eta_{x,y} \in \Aut(A) \mid x, y \in X \}$ of automorphisms  and a family $\{ \xi_{x,y}\in \End(A) \mid x, y \in X$ of endomorphisms  such that relations \eqref{rack alg rel 1}--\eqref{rack alg rel 3} hold. 
\para
If $X$ is a quandle, then a representation of the quandle algebra $\mathbb{Z}(X)$ is an abelian group $A$ together a collection of automorphisms $\{\eta_{x,y} \in \Aut(A) \mid x, y \in X \}$ and a collection of endomorphisms  $\{ \xi_{x,y}\in \End(A) \mid x, y \in X$ such that relations \eqref{rack alg rel 1}--\eqref{quandle alg rel 1} hold. 
\end{definition}

In other words, a representation of the quandle algebra $\mathbb{Z}(X)$ means that there is a $\mathbb{Z}$-algebra homomorphism  $$\mathbb{Z}(X) \rightarrow \End(A).$$ We denote the  image of a generator by the same symbol. Given a representation $A$ of  $\mathbb{Z}(X)$, we say that $A$ is a $\mathbb{Z}(X)$-module or \index{quandle module}{\it a quandle module}.  The action of $\mathbb{Z}(X)$ on $A$ is written as a left-action  and denoted by $$(\rho, g) \mapsto \rho g  =  \rho (g)$$ for  $g\in A$ and  $\rho \in \End(A)$, where $\rho$ is the image of the element  $\rho \in \mathbb{Z}(X)$ under the homomorphism $\mathbb{Z}(X) \rightarrow \End(A)$

\begin{example}
{\rm Let $X$ be a quandle.  Let $\Lambda = \mathbb{Z}[T,T^{-1}]$ denote the ring of Laurent polynomials over the ring of integers and $A$ a $\Lambda$-module. Then $A$ is a left $\mathbb{Z}(X)$-module by setting 
$$\eta_{x,y} (a)=Ta \quad \textrm{and}\quad \xi_{x,y} (b) = (1-T) (b)$$
for $x,y \in X$ and $a, b \in A$. Similarly, any left $\Adj(X)$-module $A$ can be viewed as a left $\mathbb{Z}(X)$-module by setting 
\begin{equation}\label{module over rack algebra via Adj}
\eta_{x,y} (a)=\textswab{a}_y a \quad \textrm{and}\quad \xi_{x,y} (b) = b- \textswab{a}_{x*y}b
\end{equation}
for $x, y \in X$ and $a, b \in A$.}
\end{example}

We now present the construction of the generalized quandle homology theory due to Andruskiewitsch and Gra\~{n}a \cite{MR1994219}. Let $(X,*)$ be a quandle and $C_n(X)$  the free  right  $\mathbb{Z}(X)$-module  with basis $X^n$, where $X^0=\{ x_0 \}$ for some fixed element $x_0 \in X$.  Let $\partial_n: C_{n+1}(X) \rightarrow C_n(X)$ be the $\mathbb{Z} ( X )$-linear map defined on the basis elements by 
\begin{eqnarray} \label{Andruskiewitsch grana cohomology}
&& \partial_n (x_1, \ldots, x_{n+1} )\\
\nonumber  &=& {\displaystyle  \sum_{i=2}^{n+1} (-1)^i \eta_{ [x_1, \ldots, x_{i-1}, x_{i+1}, \ldots, x_{n+1} ], [x_i, \ldots, x_{n+1}] }
		(x_1, \ldots, x_{i-1}, x_{i+1}, \ldots, x_{n+1} ) } \\
 \nonumber & & \\
\nonumber & & - {\displaystyle  \sum_{i=2}^{n+1} (-1)^i 
		(x_1*x_i, \ldots, x_{i-1}*x_i, x_{i+1},  \ldots, x_{n+1} ) }  \\
\nonumber 	& & \\
\nonumber & & +~	\xi_{[x_1, x_3, \ldots, x_{n+1}], [x_2, x_3, \ldots, x_{n+1}]} (x_2, \ldots, x_{n+1} ),
\end{eqnarray}
for $n \ge 1$ and
\begin{equation}\label{Andruskiewitsch grana cohomology at 0}
 \partial_0(x) = - \xi_{x *^{-1} x_0, x_0}(x_0),
\end{equation}
where
$$	[x_1, x_2, \ldots, x_n] = ( ( \cdots ( x_1 * x_2 ) * 	x_3  ) * \cdots ) * x_n$$
is the left-normalised product. We then have the following result.

\begin{lemma}
$\{C_n(X), \partial_n\}$ is a chain complex.
\end{lemma}

\begin{proof}
We write $\partial_n=  \sum_{i=1}^{n+1} (-1)^i  \partial_n^i$, where
	\begin{eqnarray*} 
		\partial_n^i (x_1, \ldots, x_{n+1} ) &=&
			\eta_{ [x_1, \ldots, x_{i-1}, x_{i+1}, \ldots, x_{n+1} ], [x_i, \ldots, x_{n+1}] }
			(x_1, \ldots, x_{i-1}, x_{i+1}, \ldots, x_{n+1} )  \\
		& & - (x_1*x_i, \ldots, x_{i-1}*x_i, x_{i+1},  \ldots, x_{n+1} ) 
	\end{eqnarray*}
for $2 \le i \leq n+1$ and
	\begin{eqnarray*} 
	\partial_n^{1} (x_1, \ldots, x_{n+1} ) &=& 	\xi_{[x_1, x_3, \ldots, x_{n+1}], [x_2, x_3, \ldots, x_{n+1}]}
	(x_2, \ldots, x_{n+1} ).
\end{eqnarray*}
A direct calculation verifies that
\begin{equation}\label{module theoretic boundary}
\partial_{n-1}^i \partial_n^j= \partial_{n-1}^{j-1} \partial_n^i
\end{equation}
for $1 \le i < j \le n+1$. We write 
\begin{equation}\label{module theoretic boundary2}
\partial_{n-1}\partial_n= \sum_{i=1}^n\sum_{j=1}^{n+1} (-1)^{i+j}\partial^i_{n-1} \partial^j_n= \sum_{1 \le i < j \le n+1}(-1)^{i+j}\partial^i_{n-1} \partial^j_n + \sum_{1 \le j \le i \le n} (-1)^{i+j}\partial^i_{n-1} \partial^j_n.
\end{equation}
Then, using \eqref{module theoretic boundary} in \eqref{module theoretic boundary2}, we obtain
$$\partial_{n-1}\partial_n=  \sum_{1 \le i < j \le n+1}(-1)^{i+j} \partial_{n-1}^{j-1} \partial_n^i + \sum_{1 \le j \le i \le n} (-1)^{i+j}\partial^i_{n-1} \partial^j_n=0,$$
which completes the proof. $\blacksquare$ 
\end{proof}


Let $X$ be a quandle and  $A$ a right $\mathbb{Z}(X)$-module. Take $C^n(X; A)= \Hom_{\mathbb{Z}(X)} \big(C_n(X), A \big)$ and let $\partial^n$ be the coboundary map induced from $\partial_n$. This gives a cochain complex $\{C^n(X; A), \partial^n \}$ leading to cohomology groups with coefficients in $A$, which we denote by $\Ho^n_{\rm Q}(X; A)$. If $A$ is a left $\mathbb{Z}(X)$-module, then we define $C_n(X; A)= C_n(X) \otimes_{ \mathbb{Z}(X)} A$, which leads to homology groups $\Ho_n^{\rm Q}(X; A)$ with coefficients in $A$.
\para

\begin{remark}
{\rm  When $X$ is a rack, then replacing the quandle algebra by the rack algebra $\mathbb{Z}\{X\}$ in the preceding construction, we obtain the generalized rack homology  $\Ho_n^{\rm R}(X; A)$  and  the generalized rack cohomology $\Ho^n_{\rm R}(X; A)$ of $X$ with coefficients in $A$.}
\end{remark}

\begin{remark}
{\rm If $X$ is a rack, then the  $2$-cocycle  condition for a $2$-cochain $\kappa$  in this cohomology theory 
is written as 
\begin{equation}\label{2-cocycle condition for gen cohomo}
\eta_{x*y, z} (\kappa_{x,y}) + \kappa_{x*y, z} = \eta_{x*z, y*z} (\kappa_{x,z})  +  \xi_{x*z, y*z} (\kappa_{y,z})
+ \kappa_{x*z,y*z}
\end{equation}
for any $x,y,z \in X$. Here, $\eta_{x, y}$ and $\xi_{x, y}$ corresponds to the right $\mathbb{Z}(X)$-module $A$. Further, 2-cocycles $\kappa$ and $\kappa'$ are cohomologous if there exists a map $f : X \to A$ such that 
\begin{equation}\label{2-coboundary condition for gen cohomo}
\kappa'_{x,y}- \kappa_{x,y}= \eta_{x,y} \big(f(x) \big)-f(x*y) +\xi_{x, y} \big(f(y) \big)
\end{equation}
for any $x,y,z \in X$. We refer to equation \eqref{2-cocycle condition for gen cohomo} as the {\it generalized $2$-cocycle condition}. If $X$ is a quandle, then $\kappa $ further satisfies the condition $\kappa_{x,x}=0$ for all $x \in X$.} 
\end{remark}

\begin{remark}
{\rm The (co)homology theory defined in this section recovers the  twisted quandle (co)homology theory introduced in \cite{MR1885217} by taking $\Lambda=\mathbb Z [T, T^{-1}]$ as coefficients, where $$\eta_{x,y} (a)=Ta \quad \textrm{and} \quad \xi_{x,y} (b) = (1-T) (b)$$ for all $x,y \in X$. In this case, the boundary map is explicitly given by 
\begin{eqnarray*}
	\partial^T_{n}(x_1, x_2, \dots, x_n)  \nonumber & = &
	\sum_{i=1}^{n} (-1)^{i} \Big( T (x_1, x_2, \dots, x_{i-1}, x_{i+1},\dots, x_n) \\
	& &
	- (x_1 \ast x_i, x_2 \ast x_i, \dots, x_{i-1}\ast x_i, x_{i+1}, \dots, x_n) \Big)
\end{eqnarray*}
for $n \geq 2$ and $\partial^T_n=0$ for $n \leq 1$.}
\end{remark}
