\subsection{Relation between quandle cohomology and group cohomology}

In \cite{MR1948837}, a group-theoretical interpretation of the second cohomology of racks is given, which we discuss next.  Let $X$ be a connected quandle and  $x_0\in X$ a fixed element. Consider the unique surjective group homomorphism  $$\delta: \Adj(X) \to \mathbb{Z}$$ given by $\delta(\textswab{a}_{x})=1$ for each $x \in X$. By Proposition \ref{adjoint group as kernel}, we have
$$\Adj(X) \cong \ker (\delta) \rtimes \langle \textswab{a}_{x_0}\rangle \cong [\Adj(X),\Adj(X)] \rtimes \mathbb{Z}.$$ 
Since $X$ is connected, for $x, y \in X$, there exists $g \in \Adj(X)$ such that $g \cdot x=y$. Let $h=\textswab{a}_y^{-\delta(g)}g$. Then we see that $\delta(h)= \delta(\textswab{a}_y^{-\delta(g)})=0$, and hence $h \in \ker (\delta)=[\Adj(X),\Adj(X)]$. Also, we have $$h \cdot x= (\textswab{a}_y^{-\delta(g)}g) \cdot x= \textswab{a}_y^{-\delta(g)}\cdot y=y.$$ Thus, the action of $\Adj(X)$ on $X$ restricts to a transitive action of $[\Adj(X),\Adj(X)]$ on $X$. 
\para 
Let $N_0$ denote the stabilizer of $x_0$ under the action of $[\Adj(X),\Adj(X)]$ on $X$. Let $A$ be an abelian group and $\Map(X,A)$ the left $\Adj(X)$-module of maps $X \rightarrow A$, where 
\begin{equation}\label{adj action on set of maps}
(\textswab{a}_x \cdot f)(y)=f(y*^{-1} x)
\end{equation}
for $x,y\in X$ and $f\in  \Map(X,A)$.  The proof of the following result is a direct check \cite[Proposition 5.1]{MR1948837}.


\begin{proposition}\label{shift} 
Let $X$ be a rack and $A$ a trivial $\Adj(X)$-module. Then there is a natural isomorphism of cochain complexes
 $J: C^*(X;A)\to C^*\big(X; \Map(X,A)\big)$, where for each $n \ge 1$, $J_n: C^n(X;A)\to C^{n-1} \big(X; \Map(X,A)\big)$ is given by
$$(J_n\phi)(x_1,\ldots,x_{n-1})(x)=\phi(x_1,\ldots,x_{n-1}, x).$$ In particular, $J$ induces an isomorphism $\Ho^n_{\rm R}(X;A)\cong \Ho^{n-1}_{\rm R} \big(X; \Map(X,A)\big)$ of cohomology groups. 
\end{proposition}

Note that Proposition \ref{shift} fails when the action of $\Adj(X)$ on $A$ is non-trivial.  Using the preceding result, Etingof and Gra\~na proved the following result \cite[Proposition 5.3 and Corollary 5.4]{MR1948837}. 

\begin{theorem}\label{relation rack cohomo and group cohomo}
Let $X$ be a rack and $A$ an abelian group. Then the following  assertions hold:
\begin{enumerate}
\item $\Ho^1_{\rm Grp}\big(\Adj(X); A\big) \cong \Ho^1_{\rm R}(X; A)$.
\item If $A$ is a trivial $\Adj(X)$-module, then 
$$\Ho^1_{\rm Grp} \big(\Adj(X); \Map(X,A) \big)\cong \Ho^2_{\rm R}(X;A)$$
where $\Map(X,A)$ is the left $\Adj(X)$-module of maps from $X$ to $A$.
\end{enumerate}
Here, $\Ho^*_{\rm Grp}$ is the group cohomology of $\Adj(X)$ with coefficients in the left $\Adj(X)$-module $A$ for (1) and with coefficients in the left $\Adj(X)$-module $\Map(X,A)$ for (2). And, $\Ho^*_{\rm R}$ is the rack cohomology of $X$ (in the sense of \eqref{Andruskiewitsch grana cohomology}) with coefficients in a left $\mathbb{Z}(X)$-module $A$ (in the sense of  \eqref{module over rack algebra via Adj}) with respect to the given $\Adj(X)$-module structure on $A$.
\end{theorem}

\begin{proof}
We first prove assertion (1). Let $C^* \big(\Adj(X);A \big)$ be the standard cochain complex that gives the group cohomology of the group $\Adj(X)$ with coefficient in a left $\Adj(X)$-module $A$. Let  $i_X: X\rightarrow \Adj(X)$, given by $i_X(x)= \textswab{a}_x$, be the natural map. Let $i_X^*: C^1 \big(\Adj(X);A \big)\rightarrow  C^1(X;A)$ be the homomorphism induced by $i_X$, that is, $i_X^*(f)= f\,i_X$ for $f \in C^1 \big(\Adj(X);A \big)$.
\para 
We claim that $i_X^*$ restricts to a bijection from $Z^1 \big(\Adj(X);A \big)$ onto $Z^1(X;A)$. For $ g \in \Adj(X)$ and $a \in A$, let $g \cdot a$ denote the given left  group action of  $\Adj(X)$ on $A$.  Let $f \in Z^1 \big(\Adj(X);A \big)$ be a group $1$-cocycle. Then, by \eqref{group coboundary 2}, we have $f(gh)=f(g)+g \cdot f(h)$ for all $g,h \in \Adj(X)$. For $x,y \in X$, we see that
\begin{eqnarray*}
i_X^*(f) (x*y) + \textswab{a}_{x*y} \cdot i_X^*(f) (y)&=& f(\textswab{a}_{x*y}) + \textswab{a}_{x*y} \cdot f(\textswab{a}_y)\\
&=& f(\textswab{a}_{x*y} \textswab{a}_{y}), \quad \textrm{since $f$ is a group 1-cocycle}\\
&=& f(\textswab{a}_{y} \textswab{a}_{x}), \quad \textrm{since $\textswab{a}_{x*y} \textswab{a}_{y}=\textswab{a}_{y} \textswab{a}_{x}$ in $\Adj(X)$}\\
&=& f(\textswab{a}_{y})+  \textswab{a}_{y} \cdot f(\textswab{a}_{x}), \quad \textrm{since $f$ is a group 1-cocycle}\\
&=& i_X^*(f)(y)+  \textswab{a}_{y} \cdot i_X^*(f)(x),
\end{eqnarray*}
and hence $i_X^*(f)$ is a rack 1-cocycle. 
\para 
Next, suppose that $i_X^*(f)=i_X^*(h)$ for $f, h \in Z^1 \big(\Adj(X);A \big)$. By definition, we have $f(\textswab{a}_x)=h(\textswab{a}_x)$ for all $x \in X$. Recall that, a map $\gamma: \Adj(X) \rightarrow  A$ is a group $1$-cocycle if and only if the map $\hat{\gamma}:\Adj(X) \rightarrow \Adj(X) \ltimes A$ given by $\hat{\gamma}(g)=  (g,\gamma(g))$ is a group homomorphism. This gives $\hat{f}(\textswab{a}_x)= \big(\textswab{a}_x, f(\textswab{a}_x) \big)= \big(\textswab{a}_x, h(\textswab{a}_x)\big)=\hat{h}(\textswab{a}_x)$. Since $\hat{f}$ and $\hat{h}$ are group homomorphisms, it follows that $\hat{f}=\hat{h}$, and hence $f=g$, which shows that $i_X^*:Z^1 \big(\Adj(X);A \big) \to Z^1(X;A)$ is injective.
\para 

Let $f\in Z^1(X;A)$ be a rack $1$-cocycle, that is,
\begin{equation}\label{rack cocycle with andruskiewich action}
f(x*y)= \textswab{a}_{y} \cdot f(x) + f(y)-\textswab{a}_{x*y} \cdot f(y),
\end{equation}
for $x, y \in X$. The map $f$ induces a map $\tilde{f}: X\rightarrow  \Adj(X) \ltimes A$ given by $\tilde{f}(x)=\big(\textswab{a}_x,\, f(x) \big)$. We show that $\tilde{f}$ further extends to a group homomorphism $\tilde{f}:\Adj(X) \rightarrow \Adj(X) \ltimes A$. Recall that, $\Adj(X)$ has a presentation
$$\Adj(X)= \big\langle \textswab{a}_{x},~ x\in X \mid \textswab{a}_{x*y} \textswab{a}_y=\textswab{a}_y \textswab{a}_x ~\textrm{for all}~x, y \in X \big\rangle.$$ For $x, y \in X$, we compute
\begin{eqnarray*}
\tilde{f}(\textswab{a}_{x*y}) \tilde{f}(\textswab{a}_{y}) &=& \big(\textswab{a}_{x*y},~f(x*y) \big) \big(\textswab{a}_{y},~f(y) \big)\\
&=& \big(\textswab{a}_{x*y}\textswab{a}_{y},~f(x*y) + \textswab{a}_{x*y} \cdot f(y)\big)\\
&=&  \big(\textswab{a}_{y}\textswab{a}_{x},~f(y) + \textswab{a}_{y} \cdot f(x)\big)
\quad \textrm{by}\quad \eqref{rack cocycle with andruskiewich action}\\
&=& (\textswab{a}_{y}, ~f(y)) (\textswab{a}_{x}, ~f(x))\\
&=& \tilde{f}(\textswab{a}_{y}) \tilde{f}(\textswab{a}_{x}),
\end{eqnarray*}
and hence $\tilde{f}$ is a group homomorphism. Thus, it follows that the map $\pi \tilde{f}:\Adj(X) \rightarrow  A$ is a group 1-cocycle, where $\pi: \Adj(X) \ltimes A \to A$ is the projection onto the second factor. Observing that 
$$i_X^*(\pi \tilde{f})(x)= \pi \tilde{f} i_X(x)= \pi \tilde{f} (\textswab{a}_x)= \pi \big(\textswab{a}_x, f(x) \big)= f(x)$$ for all $x \in X$, it follows that $i_X^*:Z^1 \big(\Adj(X);A \big) \to Z^1(X;A)$  is surjective, and hence bijective.
\para 

Let $\lambda \in B^1 \big(\Adj(X);A \big)$ be a group 1-coboundary. We claim that $i_X^*(\lambda)$ is a rack 1-coboundary.  By definition, there exist $a \in A$ such that $\lambda(g)=g \cdot a -a$ for all $g \in \Adj(X)$. Recall from the construction of rack homology \eqref{Andruskiewitsch grana cohomology at 0} that, $\partial_0:C_1(X) \to C_0(X)$ is given by $$\partial_0(x)=-\xi_{x*^{-1}x_0 ,x_0}(x_0)= \textswab{a}_x \cdot x_0- x_0$$ for all $x \in X$, where $C_0(X)$ is the free $\mathbb{Z}(X)$-module over $\{x_0\}$ for some fixed $x_0 \in X$. Define $\alpha \in C^0(X; A)=\Hom_{\mathcal{G}} \big(C_0(X), A \big)$ by $\alpha(x_0)=a$. Then we see that
$$\partial^0(\alpha)(x)=\alpha(\partial_0(x))=\alpha(\textswab{a}_x \cdot x_0- x_0)=  \textswab{a}_x \cdot \alpha(x_0)- \alpha(x_0)=\textswab{a}_x \cdot a-a= \lambda i_X(x)= i_X^*(\lambda)(x)$$
for all $x \in X$. Hence, $i_X^*(\lambda)$ is a rack  1-coboundary, and we conclude that the map $i_X^*: C^1 \big(\Adj(X);A \big)\rightarrow  C^1(X;A)$ induces a group homomorphism $ \Ho^1_{\rm Grp}\big(\Adj(X);A \big) \rightarrow  \Ho^1_{\rm R}(X;A)$. Since $i_X^*:Z^1 \big(\Adj(X);A \big) \to Z^1(X;A)$ is already shown to be bijective, the proof of assertion (1) is complete. Finally, Propositions \ref{shift} and assertion (1) imply assertion (2).  $\blacksquare$
\end{proof}

In \cite{MR3671570}, Garc\'{i}a Iglesias and Vendramin established that, for a finite quandle $X$, the depicted diagram commutes, and its columns are exact.
\begin{tiny}
$$
\xymatrix{
	& 1\ar[d] & 1\ar[d]\\
	& \Ho^1_{\rm Grp} \big(\langle \textswab{a}_{x_0} \rangle ; \Map(X,A)^{[\Adj(X), \Adj(X)]} \big)\ar[r]^{\cong}\ar[d]_{\inf} & A\ar[d]^{\iota}\\
	\Ho^2_{\rm Q}(X;A)\ar[r]^{\cong\hspace*{1cm}} & \Ho^1_{\rm Grp} \big( \Adj(X);\Map(X,A)\big)
	\ar[d]_{\mbox{res}} & A\times \Ho^1_{\rm Grp}\big([\Adj(X), \Adj(X)];\Map(X,A)\big)\ar[d]^{\pi}\\
	& \Ho^1_{\rm Grp}\big([\Adj(X), \Adj(X)];\Map(X,A)\big)^{\langle \textswab{a}_{x_0} \rangle}\ar@{=}[r]\ar[d] & \Ho^1_{\rm Grp}\big([\Adj(X), \Adj(X)];\Map(X,A)\big)\ar[r]^{\hspace*{1cm}\cong}\ar[d] & \Hom_{\mathcal{G}} (N_0,A)\\
	& 1 & 1
}
$$
\end{tiny}
Here, $\mbox{inf}$ and $\mbox{res}$ denote the inflation and restriction maps in group cohomology, respectively; and $\iota$ and $\pi$ denote the canonical inclusion and projection maps, respectively. Recall that, $N_0$ is the stabilizer of $x_0$ under the action of $[\Adj(X), \Adj(X]$ on $X$.  Let the map $$\Ho^1_{\rm Grp}\big( \Adj(X); \Map(X,A)\big)\to \Hom_{\mathcal{G}} (N_0,A)$$ deduced from the preceding diagram be denoted by $f\mapsto f_0$. Using Proposition~\ref{shift} and the preceding diagram, Garc\'{i}a Iglesias and Vendramin gave an explicit description of $2$-cocycles of finite connected quandles with coefficients in an abelian group \cite[Theorem 1.1]{MR3671570}.

\begin{theorem}
Let $X$ be a finite connected quandle, $x_0 \in X$ a fixed element and $A$ an abelian group with trivial $\Adj(X)$-action. Then the map $\phi \mapsto \big(\phi(x_0,x_0),(J\phi)_0 \big)$ induces an isomorphism
\begin{equation}
	\label{eqn:map}
	\Ho^2_{\rm Q}(X;A)\cong  A\times\Hom_{\mathcal{G}}  (N_0,A).
\end{equation}
\end{theorem}

In particular, the preceding result shows that non-constant 2-cocycles on $X$ are controlled by a finite group. A new proof of the following result of Eisermann \cite[Theorem 1.12]{MR3205568} is also deduced in \cite{MR3671570}.

\begin{theorem}
Let $X$ be a finite connected quandle and $x_0 \in X$ a fixed element. Then
$$\Ho_2^{\rm Q}(X; \mathbb{Z})\cong \big([\Adj(X), \Adj(X] \cap \C_{\Adj(X)}(\textswab{a}_{x_0}) \big)_{\rm ab} \cong (N_0)_{\rm ab}$$
where $N_0$ is the stabilizer of  $x_0$ under the action of $[\Adj(X), \Adj(X]$ on $X$.
\end{theorem}

We conclude this subsection with a beautiful homological characterisation of the unknot due to Eisermann\cite[Theorem 1]{MR1954330}.

\begin{theorem}
Let $Q(K)$ be the knot quandle of a knot $K$. Then $\Ho_2^{\rm Q} \big(Q(K); \mathbb{Z} \big)=1$ if and only if $K$ is trivial.
\end{theorem}
