\subsection{Extension theory of quandles}\label{sec extension theory of quandles} 
An extension theory of quandles using quandle cocycles was initially introduced in \cite{MR1885217, MR1973510}. A far reaching generalization of quandle extensions using dynamical 2-cocycles, which encompassed the previous constructions, was given in \cite{MR1994219}. The following result presents a further extension of this framework, as proved in \cite[Proposition 3.1]{MR4282648}.

\begin{proposition}\label{set-cocycle}
Let $X$ and $S$ be two sets, $\alpha: X \times X \to \Map(S \times S, S)$ and $\beta: S \times S \to \Map(X \times X, X)$ two maps. Then the set $X \times S$ with the binary operation 
\begin{equation}\label{genralised-quandle-operation}
(x, s)* (y,t)= \big( \beta_{s, t}(x, y), ~\alpha_{x, y}(s, t) \big)
\end{equation}
forms a quandle if and only if the following conditions hold:
\begin{enumerate}
\item $\beta_{s, s}(x, x)=x$ and $\alpha_{x, x}(s, s)=s$ for all $x \in X$, $s \in S$;
\item  for each $(y, t) \in X \times S$, the map $(x, s) \mapsto  \big( \beta_{s, t}(x, y),~ \alpha_{x, y}(s, t) \big)$ is a bijection;
\item $\beta_{\alpha_{x, y}(s, t), u}\Big(\beta_{s, t}(x, y),~ z \Big)= \beta_{\alpha_{x, z}(s, u), \alpha_{y, z}(t, u)}\Big(\beta_{s, u}(x, z), ~\beta_{t, u}(y, z) \Big)$ 
\item[] and
\item[] $\alpha_{\beta_{s, t}(x, y), z}\Big(\alpha_{x, y}(s, t), ~u \Big)= \alpha_{\beta_{s, u}(x, z), \beta_{t, u}(y, z)}\Big(\alpha_{x, z}(s, u), ~\alpha_{y, z}(t, u) \Big)$.
\end{enumerate}
\end{proposition}

\begin{proof}
The idempotency axiom holds if and only if $\beta_{s, s}(x, x)=x$ and $\alpha_{x, x}(s, s)=s$ for all $x \in X$, $s \in S$. The invertibility of the right multiplication axiom is equivalent to condition (2). Finally, if $(x, s), (y, t), (z, u) \in X \times S$, then 
\begin{eqnarray*}
&& \big((x, s)*(y, t) \big)* (z, u) \\
&=& \big( \beta_{s, t}(x, y), ~\alpha_{x, y}(s, t) \big) *(z, u)\\
&=& \Big(\beta_{\alpha_{x, y}(s, t), u}\big(\beta_{s, t}(x, y), z \big),~ \alpha_{\beta_{s, t}(x, y), z}\big(\alpha_{x, y}(s, t), u \big) \Big)
\end{eqnarray*}
and
\begin{eqnarray*}
&& \big((x, s)*(z, u) \big)* \big((y, t)*(z, u) \big)\\
&=& \big( \beta_{s, u}(x, z), ~\alpha_{x, z}(s, u) \big) *\big( \beta_{t, u}(y, z), ~\alpha_{y, z}(t, u) \big)\\
&=& \Big(\beta_{\alpha_{x, z}(s, u), ~\alpha_{y, z}(t, u)}\big(\beta_{s, u}(x, z), ~\beta_{t, u}(y, z) \big), ~\alpha_{\beta_{s, u}(x, z), ~\beta_{t, u}(y, z)}\big(\alpha_{x, z}(s, u), ~\alpha_{y, z}(t, u) \big)\Big).
\end{eqnarray*}
Thus, the right distributivity axiom of the quandle is equivalent to condition (3).
$\blacksquare$    \end{proof}          

We denote the quandle obtained in Proposition \ref{set-cocycle} by $X~ _{\alpha}\times_{\beta} S$. 

\begin{corollary}
Let $X$ and $S$ be two sets, $\alpha: X \times X \to \Map(S \times S, S)$ and $\beta: S \to \Map(X \times X, X)$ two maps. Then the set $X \times S$ with the binary operation 
$$(x, s)* (y,t)= \big( \beta_{t}(x, y), \alpha_{x, y}(s, t) \big)$$ forms a quandle if and only if the following conditions hold:
\begin{enumerate}
\item $\beta_{s}(x, x)=x$ and $\alpha_{x, x}(s, s)=s$ for all $x \in X$, $s \in S$;
\item $\beta_{s}(-, y): X \to X$ and  $\alpha_{x, y}(-, t): S \to S$ are bijections for all $x, y \in X$, $s \in S$;
\item $\beta_{u}\big(\beta_{t}(x, y), ~z \big)= \beta_{\alpha_{y, z}(t, u)}\big(\beta_{u}(x, z), ~\beta_{u}(y, z) \big)$ 
\item[] and
\item[] $\alpha_{\beta_{t}(x, y), z}\big(\alpha_{x, y}(s, t), ~u \big)= \alpha_{\beta_{u}(x, z), ~\beta_{u}(y, z)}\big(\alpha_{x, z}(s, u), ~\alpha_{y, z}(t, u) \big)$.
\end{enumerate}
\end{corollary}
\medskip

A special case of Proposition \ref{set-cocycle} was considered by Andruskiewitsch and Gra\~{n}a \cite[Section 2.1]{MR1994219} when $X$ is a quandle and $\beta_{s, t}(x, y)=x*y$ for all $x, y \in X$ and $s, t \in S$. In this case, the map $\alpha: X \times X \to \Map(S \times S, S)$ satisfy
\begin{equation}\label{dynamical-cocycle-condition1a}
\alpha_{x, x}(s, s)=s,
\end{equation}
\begin{equation}\label{dynamical-cocycle-condition2a}
\alpha_{x, y}(-, t): S \to S~\textrm{is a bijection}
\end{equation}
and the  {\it cocycle condition}
\begin{equation}\label{dynamical-cocycle-condition3a}
\alpha_{x*y, z}\big(\alpha_{x, y}(s, t), ~u \big)= \alpha_{x* z, y*z}\big(\alpha_{x, z}(s, u),~ \alpha_{y, z}(t, u) \big)
\end{equation}
for all $x, y \in X$ and $s, t \in S$. Such an $\alpha$ is called a {\it dynamical 2-cocycle}. Further, in this case, the quandle operation \eqref{genralised-quandle-operation}  on $X \times S$ becomes 
\begin{equation}\label{dynamical-quandle-operation1a}
(x, s)* (y,t)= \big( x* y, ~\alpha_{x, y}(s, t) \big).
\end{equation} 
The quandle so obtained is called a  \index{dynamical extension}{\it dynamical extension} of $X$ by $S$ through $\alpha$, and is denoted by $X \times_{\alpha} S$.

\begin{corollary}\label{isomorphic-s-quandles}
Let $X$ be a connected quandle. Then the following  assertions hold:

\begin{enumerate}
\item For each $x \in X$, the set $S$ forms a quandle be defining
$$s *_x t :=\alpha_{x,x}(s,t)$$ for all $s, t \in S$.
\item $(S, *_x) \cong (S, *_y)$ for all $x, y \in X$.
\end{enumerate}
\end{corollary}

\begin{proof}
A direct verification shows that $(S, *_x)$ is a quandle for each $x \in X$. Let $x, z \in X$ and $u \in S$. Define a map $\phi: (S, *_x) \to (S, *_{x*z})$ by 
$$\phi(s)= \alpha_{x, z}(s, u)$$ for all $s \in S$.
Then, for $s, t \in S$, we have
\begin{eqnarray*}
\phi(s *_x t) &=& \alpha_{x, z}(s *_x t, u)\\
&=& \alpha_{x, z}\big( \alpha_{x, x}(s, t), u\big)\\
&=&\alpha_{x* z, x*z}\big(\alpha_{x, z}(s, u),~ \alpha_{x, z}(t, u) \big),~\textrm{by \eqref{dynamical-cocycle-condition3}}\\
&=&\phi(s) *_{x*z} \phi(t),
\end{eqnarray*}
and $\phi$ is an isomorphism of quandles. Since $X$ is connected, it follows that $(S, *_x) \cong (S, *_y)$ for all $x, y \in X$.
$\blacksquare$    
\end{proof}          


\begin{example} \label{example of dynamical cocycle eta xi kappa}
	{\rm
		Let $A$ be  a $\mathbb{Z}(X)$-module for the quandle $X$,
		and $\kappa$ a generalized $2$-cocycle. 
		For $a,b \in A$, let 
		$$\alpha_{x,y}(a,b) =  \eta_{x,y}(a)  +  \xi_{x,y}(b)
		+ \kappa_{x,y} .$$ 
		Then it can be verified directly that $\alpha$ is a dynamical cocycle. 
		In particular, even with $\kappa=0$, 
		a $\mathbb{Z}(X)$-module structure on the abelian 
		group $A$ defines a quandle structure
		$A\times_\alpha X$. }
\end{example}


If $A$ is an abelian group, then a normalized quandle 2-cocycle is a map $\alpha: X \times X \to A$ satisfying
$$
\alpha_{x, y}~\alpha_{x*y, z}= \alpha_{x, z}~\alpha_{x* z, y*z} \quad \textrm{and} \quad \alpha_{x, x}=1
$$
for all $x, y, z \in X$. A normalized quandle 2-cocycle $\alpha: X \times X \to A$ gives rise to a dynamical 2-cocycle $\alpha': X \times X \to \Map(A \times A, A)$ given as $$\alpha'_{x, y}(s, t)=s \,\alpha_{x, y}.$$ In this case, the quandle $X \times_\alpha A$ is called the {\it abelian extension} of $X$ by $A$ through $\alpha$. Such extensions appeared first in \cite{MR1973510}.


\begin{proposition}\cite[Corollary 2.5]{MR1994219}\label{AGlemma}   
Let $p: Y \rightarrow X$ be a surjective quandle homomorphism  such that the cardinality of $p^{-1}(x)$ is constant for all $x \in X$. Then $Y$ is isomorphic to a dynamical  extension  $X \times_{\alpha} S$ of $X$ by $S$ through some dynamical 2-cocycle $\alpha$, where $S$ is a set with $|S|=|p^{-1}(x)|$.
\end{proposition}

\begin{proof}
Since the cardinality of $p^{-1}(x)$ is constant for each $x \in X$, we can choose a set $S$ and bijections $g_x: p^{-1}(x) \to S$ for each $x \in X$. Define $\alpha: X \times X \to \Map(S \times S, S)$ by 
$$\alpha_{x_1, x_2}(s_1,s_2)=g_{x_1*x_2} \big(g_{x_1}^{-1}(s_1) * g_{x_2}^{-1}(s_2)\big)$$ for $x_1, x_2 \in X$ and $s_1, s_2 \in S$. Clearly, $\alpha$ satisfy \eqref{dynamical-cocycle-condition1a} and \eqref{dynamical-cocycle-condition2a}. Further, for  $x_1, x_2, x_3 \in X$ and $s_1, s_2, s_3 \in S$, we have
\begin{eqnarray*}
\alpha_{x_1*x_2, x_3} \big(\alpha_{x_1,x_2}(s_1, s_2), s_3 \big)&=& \alpha_{x_1*x_2, x_3} \big(g_{x_1*x_2}(g_{x_1}^{-1}(s_1) * g_{x_2}^{-1}(s_2)), s_3 \big)\\
&=& g_{(x_1*x_2)*x_3}\big(g_{x_1*x_2}^{-1} (g_{x_1*x_2}(g_{x_1}^{-1}(s_1) * g_{x_2}^{-1}(s_2)))* g_{x_3}^{-1}(s_3) \big)\\
&=& g_{(x_1*x_3)*(x_2*x_3)}\big((g_{x_1}^{-1}(s_1) * g_{x_2}^{-1}(s_2))* g_{x_3}^{-1}(s_3) \big)\\
&=&g_{(x_1*x_3)(x_2*x_3)} \big((g_{x_1}^{-1}(s_1) * g_{x_3}^{-1}(s_3))* (g_{x_2}^{-1}(s_2)*g_{x_3}^{-1}(s_3))\big)\\
&=&\alpha_{x_1*x_3, x_2*x_3} \big(\alpha_{x_1,x_3}(s_1, s_3), \alpha_{x_2,x_3}(s_2, s_3) \big).
\end{eqnarray*}
Hence, $\alpha$ satisfies \eqref{dynamical-cocycle-condition3a}, and therefore it is a dynamical 2-cocycle.
\para
We can write $Y= \sqcup_{x \in X}~ p^{-1}(x)$. Define $\varphi: Y \to X \times_\alpha S$ by 
$$\varphi(y)=\big(p(y), ~g_{p(y)}(y)\big)$$
for $y \in Y$. For $y_1, y_2\in Y$, we see that 
\begin{eqnarray*}
\varphi(y_1*y_2) &=& \big( p(y_1*y_2), ~g_{p(y_1*y_2)}(y_1*y_2)\big)\\
&=& \big( p(y_1)*p(y_2), ~g_{p(y_1)*p(y_2)}(g_{p(y_1)}^{-1}(g_{p(y_1)}(y_1))*g_{p(y_2)}^{-1}(g_{p(y_2)}(y_2)))\big)\\
&=& \big( p(y_1)*p(y_2), ~\alpha_{p(y_1), p(y_2)}(g_{p(y_1)}(y_1), g_{p(y_2)}(y_2))\big)\\
&=& \big( p(y_1), g_{p(y_1)}(y_1) \big) * \big( p(y_2), g_{p(y_2)}(y_2) \big)\\
&=& \varphi(y_1)*\varphi(y_2),
\end{eqnarray*}
and $\varphi$ is a quandle homomorphism. A direct check shows that the map $\psi: X \times_\alpha S \to Y$ given by $\psi(x, s)= g_x^{-1}(s)$ is the inverse to $\varphi$, and hence it is an isomorphism of quandles.
$\blacksquare$
\end{proof}

