\subsection{From group extensions to dynamical extensions of quandles} \label{extsec}  
In this subsection, we derive dynamical extensions of quandles from extensions of groups \cite{MR2166720}. We shall utilise basic extension theory of groups, which is summarised in Section \ref{obstruction to SLB arising from RBG} of Chapter \ref{chap RBG and YBE}. 
\para

Let $1 \rightarrow N \stackrel{i}{\rightarrow} E  \stackrel{\pi}{\rightarrow} H \rightarrow 1$ be a short exact sequence of groups, where $N$ is abelian. Let $s:H \to E$ be a normalised set-theoretic section. Then there is a group 2-cocycle $\theta: H \times H \to N$ given by
$$  s(x) s(y)  s(x y)^{-1}= i \big(\theta(x, y)\big)
$$
for  all $x,  y \in H$. We denote the conjugation action of $H$ on $N$ by $(x, a) \mapsto x \cdot a$ for all $x \in H$ and $a \in A$. Recall that the set $N \times H$  is a group with the binary operation $$(a, x)(b, y)=\big(a + x \cdot b+ \theta(x, y), xy\big)$$
for all $x, y \in H$ and $a, b \in N$, and we denote this group by $N \times_\theta H$. A direct check shows that the map $\psi: E \to N \times_\theta H$ given by $\psi \big(i(a)s(x)\big)=(a, x)$ is an isomorphism of groups. With the preceding set-up, we have the following result.

\begin{proposition}   \label{qmoduleprop}
Let $1 \rightarrow N \stackrel{i}{\rightarrow} E  \stackrel{\pi}{\rightarrow} H \rightarrow 1$ be a short exact sequence of groups, where $N$ is abelian. Then the following  assertions hold:
\begin{enumerate}
\item $\Conj(E)$ is a dynamical extension of $\Conj(H)$  through a dynamical 2-cocycle $\alpha: H \times H \rightarrow \Map(N \times N, N)$.
\item The dynamical 2-cocycle $\alpha$ is given by 
$$\alpha_{x,y} (a,b ) =\eta_{x,y} (a) + \xi_{x,y}(b) + \kappa_{x,y}$$ 
for all $x, y \in H$ and $a, b \in N$, where 
$$\eta_{x,y} (a)=y  \cdot a, \quad \xi_{x,y}(b)= b-(x*y) \cdot b, \quad \kappa_{x,y}=\theta(y,x) - (yx) \cdot \theta (y^{-1}, y) + \theta(yx, y^{-1})$$
and $\theta: H \times H \to N$ is a group 2-cocycle associated with a set-theoretic section $s:H \to E$.
\end{enumerate}
\end{proposition}

\begin{proof} 
The surjective group homomorphism $\pi: E \to H$ gives a surjective quandle homomorphism $\pi: \Conj(E) \to \Conj(H)$ such that $|\pi^{-1}(x)|=|\ker(\pi)|=|N|$ for all $x \in H$. Hence, by Lemma~\ref{AGlemma}, $\Conj(E)$ is  a dynamical extension of $\Conj(H)$ by $N$ through a dynamical 2-cocycle $\alpha: H \times H \rightarrow \Map(N \times N, N)$. We use the isomorphism $E \cong N \times_\theta H$ to derive the expression of $\alpha$.  Clearly, $(0,1)$ is the identity element in $N \times_\theta H$ and 
	$$ (b, y)^{-1} = \big(-y^{-1} \cdot b - \theta(y^{-1}, y), \,y^{-1} \big) =  \big(-y^{-1} \cdot b - y^{-1} \cdot \theta (y, y^{-1}),\, y^{-1} \big)$$ 
 for any $(b,y)\in N \times_\theta H$. Expanding the quandle operation in $\Conj (N \times_\theta H)$ gives
\begin{eqnarray*} 
(a, x)* (b, y) &=& (b, y) (a, x) (b, y)^{-1} \\
&= & \big( b + y \cdot a - (yxy^{-1})\cdot b + \theta(y,x)- (yx) \cdot \theta (y^{-1}, y) + \theta(yx, y^{-1}),~ y x y^{-1} \big)\\
&= & \big( y \cdot a +b - (x*y) \cdot b + \theta(y,x)- (yx) \cdot \theta (y^{-1}, y) + \theta(yx, y^{-1}),~ x * y \big).
\end{eqnarray*}
Taking
$$\eta_{x,y} (a)=y \cdot a,  \quad \xi_{x,y}(b)= b-(x*y) \cdot b,\quad 
\kappa_{x,y}=\theta(y,x) - (yx) \cdot \theta (y^{-1}, y) + \theta(yx, y^{-1})$$
and
$$ \alpha_{x,y}(a,b)=\eta_{x,y}(a) + \xi_{x,y}(b) + \kappa_{x,y},$$
we can write 
$$(a, x)* (b, y)= \big(\alpha_{x,y}(a,b), \, x * y \big).$$
By Example \ref{example of dynamical cocycle eta xi kappa}, $\alpha$ is a dynamical 2-cocycle, which proves the proposition. $\blacksquare$
\end{proof}


\begin{example} \label{wreathex} {\rm 
The wreath product of groups gives  specific examples. Let $G$ be any abelian group and $N=G^n$ for some integer $n \ge 2$. Then the  symmetric group  $H=\Sigma_n$ acts on $N$  by  permutation of factors, that is,
$$\sigma(x_1,\ldots, x_n)= \big(x_{\sigma^{-1} (1)}, \ldots, x_{\sigma^{-1} (n)} \big)$$  for $\sigma \in \Sigma_n$ and $(x_1,\ldots, x_n) \in N$. In this case, the semi-direct product $E=N \rtimes H= G \wr \Sigma_n$ is  called
a wreath product. Since the extension $1 \to N \to E \to H \to 1$ splits, we can choose a set-theoretic section for which $\theta=0$, and hence $\kappa=0$.
} 
\end{example} 

Recall that, in case of groups, the group $2$-cocycle $\theta$ is an obstruction to the section $s:H \to E$ being  a group homomorphism. There is a similar  interpretation for quandle $2$-cocycles. 

\begin{proposition}\label{sectlemma}
Let $1\rightarrow N \stackrel{i}{\rightarrow} E  \stackrel{\pi}{\rightarrow} H \rightarrow 1$ be a short exact sequence of groups, where $N$ is abelian. Then the following  assertions hold:
\begin{enumerate}
\item The map $\kappa$ in Proposition~\ref{qmoduleprop} is a quandle $2$-cocycle.
\item The map $\kappa$ satisfy $s(x)*s(y)=i(\kappa_{x,y}) s(x*y)$. 
\item The map $\kappa$ satisfy  $\kappa_{x,y} = \theta(y, x) - \theta(yxy^{-1}, y )$.
\item If $\theta$ is a group 2-coboundary, then $\kappa$ is a quandle 2-coboundary.
\end{enumerate}
\end{proposition} 

\begin{proof} 
Since $\alpha$ is a dynamical 2-cocycle, it satisfies 
$$\alpha_{x*y, z}\big(\alpha_{x, y}(a, b), ~c \big)= \alpha_{x* z, y*z}\big(\alpha_{x, z}(a, c),~ \alpha_{y, z}(b, c) \big)$$
for $x, y, z \in H$ and $a, b,c \in N$. Substituting $\alpha_{x,y} (a,b ) =\eta_{x,y} (a) + \xi_{x,y}(b) + \kappa_{x,y}$ and using the relations \eqref{rack alg rel 1}-\eqref{rack alg rel 3}, we obtain
$$ \eta_{x*y,z}(\kappa_{x,y}) + \kappa_{x*y,z} = \eta_{x*y,y*z}(\kappa_{x,z}) + \xi_{x*z,y*z}(\kappa_{y,z}) + \kappa_{x*z,y*z}$$
for all $x, y, z \in H$. This shows that $\kappa$ is a quandle $2$-cocycle (see \eqref{2-cocycle condition for gen cohomo}), which is assertion (1). 
\para

Using the isomorphism $E \cong N \times_\theta H$, we can write $s(x)=(0, x)$ and $i(a)=(a, 1)$. Then we have
$$s(x)*s(y)=(0,x)*(0,y)= \big(\alpha_{x,y}(0,0), x*y \big)=(\kappa_{x,y}, x*y)= i(\kappa_{x,y}) s(x*y),$$
which is assertion (2).
\para 
By assertion (2), we have $s(y) s(x) s(y)^{-1} = i(\kappa_{x,y}) s(yxy^{-1} )$. This gives
$$ i \big(\theta(y,x)\big) s(yx) =i (\kappa_{x,y}) s(yxy^{-1} ) s(y) =i(\kappa_{x,y})  i \big(\theta(yxy^{-1}, y )\big) s(yx)= i \big(\kappa_{x,y} +\theta(yxy^{-1}, y )\big)s(yx).
$$
Since $i$ is injective, we obtain the formula in assertion (3).
\para 

Suppose that $\theta$ is a group 2-coboundary. That is, there is a $1$-cochain $\gamma:H \to N$ such that 
$$ \theta(x,y) =(\partial^1_{\rm Group} \gamma) (x, y) =\gamma(xy)-\gamma(x)-x \cdot \gamma(y),$$
	where $\partial^1_{\rm group}$ denotes the group 1-coboundary operator. By assertion (3), we have
	$$\kappa_{x,y} = \gamma(x*y) -y \cdot \gamma(x) - \gamma(y) + (x*y) \cdot \gamma(y)=\gamma(x*y) -\eta_{x, y} \big(\gamma(x)\big) - \xi_{x, y} \big(\gamma(y)\big) = \big(\partial^1_{\rm Quandle} (-\gamma)\big)(x,y),$$
where  $\partial^1_{\rm quandle}$ denotes the quandle 1-coboundary operator. Hence, $\kappa$ is a quandle 2-coboundary, which is assertion (4). $\blacksquare$
\end{proof}

\begin{remark}
{\rm 
Let   $E \cong N \times_{\theta} H $ be as in the preceding result. Let $X$ be a subquandle of $\Conj(H)$
and $\tilde{X}=\pi^{-1}(X)$. Then $\tilde{X}$ is a subquandle of $\Conj(E)$  and $\pi$ induces the quandle homomorphism $\pi:\tilde{X} \rightarrow X$, which is a dynamical extension.}
\end{remark}

Let $X$ be a quandle and $A$ a right $\mathbb Z(X)$-module.  Consider the dynamical extension $A \times_{\alpha} X$ of $X$ by $A$ through the dynamical 2-cocycle  $\alpha_{x,y}=\eta_{x,y}+\xi_{x,y}$. Let  $f \in C^1(X;A)=\Hom_{\mathbb Z(X)} \big(C_1(X),A \big)$ be a quandle $1$-cochain. Define $\hat{f}: X \rightarrow A \times_{\alpha} X$ by 
$\hat{f}(x)=\big(f(x), x \big)$. Since $\pi \, \hat{f}={\rm id}_X$, the map $\hat{f}$ is a set-theoretic section to the projection  $\pi: A \times_{\alpha} X \rightarrow X$.

\begin{proposition}\label{onecocylemma}
The quandle 1-cochain $f$ is a 1-cocycle if and only if the section $\hat{f}$ is a quandle homomorphism.
\end{proposition} 

\begin{proof}
It follows from the definition that $f:X \to A$ is a quandle $1$-cocycle if $$f(x*y)=\eta_{x,y} \big(f(x)\big)+\xi_{x,y} \big(f(y)\big)$$
for all $x, y \in X$. On the other hand, we see that
$$ \hat{f} (x*y) = \big(f(x*y), ~x*y \big)$$
and
$$\hat{f}(x) * \hat{f}(y) = \big(f(x), ~x \big) *\big(f(y), ~y \big) =\big(\alpha_{x,y}(f(x),f(y)), ~x*y \big) = \big(\eta_{x,y}f(x)+\xi_{x,y}f(y), ~x*y \big)$$
for all $x, y \in X$. Thus, $f$ is a quandle 1-cocycle if and only if $\hat{f}$ is a quandle homomorphism.
	$\blacksquare$
\end{proof}
