\subsection{Extensions of solutions and obstruction cocycles}
Low dimensional Yang--Baxter cocycles have interpretations as obstruction cocycles in extensions of solutions to the Yang--Baxter equation. This is similar to cohomology theories for groups and other algebraic structures, and also generalizes the quandle cohomology case as well.
\para 

Let $1 \rightarrow N \stackrel{i}{\rightarrow}  G \stackrel{p}{\rightarrow}  A \rightarrow 1$  be an exact sequence of abelian groups  with a normalised set-theoretic section $s: A \rightarrow G$. Let $n$ be a positive integer and  $f \in C^n_{\rm YB}(X;A)= \Hom_{\mathcal{G}} \big(C_{n-1}^{\rm YB}(X), A\big)$ an $n$-cocycle. Then $\partial^n f (x_1, \ldots, x_n)$ has $2n$ terms, each of which  has $(n-1)$ arguments. Let us write  $$\partial^n f (x_1, \ldots, x_n)=T_1 + \cdots + T_{2n}.$$ Consider the expression $h=s(T_1) + \cdots + s(T_{2n})$. Then $p(h)=0 \in A$, since $p \, s = \id_A$, $p$ is a homomorphism and $f$ is a cocycle. Thus, there is a unique  element, say $\psi(x_1, \ldots, x_n) \in N$,  such that  $i \, \psi(x_1, \ldots, x_n) = h$.  For example, for $n=2$, by \eqref{dim two boundary homo}, we obtain 
\begin{equation}\label{defining2} 
	sf(x) + sf(y)= i \psi (x, y) +  sf \big(\sigma_x(y)\big) + sf \big( \tau_y(x)\big).
\end{equation}



\begin{proposition} 
The map $\psi$ is an $(n+1)$-cocycle of $X$ with coefficients in $N$.
\end{proposition}
\begin{proof}
The $2n$ terms $T_1, \ldots, T_{2n}$ are in one-to-one correspondence with $(n-1)$-faces of ${\mathcal I}_n$, whose initial path is labeled by $x_1, \ldots, x_n$ via $L$ (by Lemma \ref{yblemma}). We assign $i \psi(x_1, \ldots, x_n)$ to this cube ${\mathcal I}_n$. In ${\mathcal I}_{n+1}$, whose initial path  is labeled by $(x_1, \ldots, x_{n+1})$, the $n$-faces ${\mathcal I}_n$ are in one-to-one correspondence with the assigned $i\psi$. Then $\partial^{n+1} (\psi) =\partial^{n+1} \partial^n(f)=0$ since $\partial^{n+1} \partial^n=0$.
$\blacksquare$
\end{proof}


We call such a cocycle $\psi$ an \index{obstruction cocycle}{\it obstruction $(n+1)$-cocycle}. Explicit computations can be carried out using this correspondence. For example, when $n=2$, we have
\begin{eqnarray*}
 &&  \underline{sf(x) + sf(y)} + sf(z) \\
&=&  i \psi (x, y) +  sf \big(\sigma_x(y)\big) + \underline{sf \big(\tau_y(x) \big) + sf(z)} \\
	&=&  i \psi (x, y) +  i \psi \big(\tau_y(x), z \big)  + \underline{ sf \big(\sigma_x(y) \big) + sf \big( \sigma_{\tau_y(x)}(z) \big)}  + sf \big( \tau_z(\tau_y(x)) \big) \\
	&=&  i \psi (x, y) +  i \psi \big(\tau_y(x), z \big) 	+  i \psi \big(\sigma_x(y), \sigma_{\tau_y(x)}(z) \big) \\ 
	& & 	+  sf \big(\sigma_{\sigma_x(y)}(\sigma_{\tau_y(x)}(z)) \big)	+ sf \big( \tau_{ \sigma_{\tau_y(x)}(z)}(\sigma_x(y)) \big)  +  sf \big( \tau_z( \tau_y(x)) \big)
\end{eqnarray*} 
and
\begin{eqnarray*} 
 && sf(x) +  \underline{sf(y)+ sf(z)} \\
  &=& i \psi (y,z) + \underline{sf(x) + sf \big(\sigma_y(z) \big)} + sf \big(\tau_z(y)\big) \\
	&=&  i \psi (y,z) +  i \psi \big(x, \sigma_y(z) \big) + sf \big( \sigma_x(\sigma_y(z)) \big) +  \underline{sf \big( \tau_{\sigma_y(z)}(x) \big)+sf \big( \tau_z(y)\big) } \\
	&=&  i \psi (y,z) +  i \psi \big(x, \sigma_y(z) \big) + i \psi \big( \tau_{ \sigma_y(z)}(x),  \tau_z(y)\big) \\
 & & + sf \big( \sigma_x(\sigma_y(z))\big) + sf \big( \sigma_{\tau_{ \sigma_y(z)}(x)}(\tau_z(y))\big) + sf \big( \tau_{\tau_z(y)}(\tau_{\sigma_y(z)}(x))\big),
\end{eqnarray*} 
where the defining relation \eqref{defining2} of $\psi$ is applied to the underlined terms. We recover the formula for the second coboundary homomorphism this way.  This computation  is  directly visualized from Figure \ref{3dboundary}.
\para 

\begin{proposition} \label{extprop}
Let $A$ be a ring, $(X,r)$ a solution to the Yang--Baxter equation with $r(x, y)= \big(\sigma_x(y), \tau_y(x)\big)$, and $\psi_1, \psi_2 \in  C^2_{\rm YB}(X;A)$.
Let $V=A \times X$ and $s: V \times V \rightarrow  V \times V$ be defined by 
	$$s \big( (a_1, x_1), (a_2, x_2) \big) = \big( (a_2 + \psi_1(x_1, x_2) , \sigma_{x_1}(x_2)),
	(a_1 + \psi_2(x_1, x_2),  \tau_{x_2}(x_1) ) \big)$$
	for  $(a_i, x_i) \in V$. If  $(V, s)$ is a solution to the Yang--Baxter equation, then 
	$\psi_1 + \psi_2 \in  Z^2_{\rm YB}(X;A)$.
\end{proposition}
\begin{proof} 
We compute
\begin{eqnarray}\label{sum of cochains solution 1}
&& (s \times \id )( \id \times s)(s \times \id) \big(( a_1, x_1), (a_2, x_2), (a_3, x_3) \big) \\
\nonumber &=& \Big(\Big(a_3 + \psi_1( \tau_{x_3}(x_1), x_3) + \psi_1(\sigma_{x_1}(x_2), ~\sigma_{\tau_{x_2}(x_1)}(x_3)), ~\sigma_{\sigma_{x_1}(x_2)}(\sigma_{\tau_{x_2}(x_1)}(x_3) ) \Big),~\\
\nonumber 	& & \Big( a_2 + \psi_1(x_1, x_2) + \psi_2( \sigma_{x_1}(x_2), ~\sigma_{\tau_{x_2}(x_1)}(x_3)), ~ 
 \tau_{\sigma_{\tau_{x_2}(x_1)}(x_3)}(\sigma_{x_1}(x_2)) \Big), ~\\
	\nonumber & & \Big( a_1 +  \psi_2(x_1, x_2) + \psi_2( \tau_{x_2}( x_1) , x_3), ~\tau_{x_3}(\tau_{x_2}(x_1))  \Big)  \Big)
\end{eqnarray} 
and 
\begin{eqnarray}\label{sum of cochains solution 2}
&& (\id \times s)(s \times \id)( \id \times s)\big(( a_1, x_1), (a_2, x_2), (a_3, x_3) \big) \\
\nonumber &=& \Big(  \Big(a_3 + \psi_1( x_2, x_3) + \psi_1( x_1, \sigma_{x_2}(x_3) ),~  \sigma_{x_1}(\sigma_{x_2}(x_3))\Big), \\
\nonumber & & \Big( a_2 +  \psi_2( x_2, x_3) + \psi_1(\tau_{\sigma_{x_2}(x_3)}(x_1),   \tau_{x_3}(x_2) ), ~\sigma_{\tau_{\sigma_{x_2}(x_3)}(x_1)}(\tau_{x_3}(x_2)) \Big), \\
\nonumber  & &  \Big( a_1 + \psi_2(x_1, \sigma_{x_2}(x_3) ) +   \psi_2(\tau_{ \sigma_{x_2}(x_3)}(x_1), \tau_{x_3}(x_2)), ~ \tau_{ \tau_{x_3}(x_2)}(\tau_{\sigma_{x_2}(x_3)}(x_1)) \Big) \Big).
\end{eqnarray} 
Since $(V, s)$ is a solution to the Yang--Baxter equation, equating \eqref{sum of cochains solution 1} and \eqref{sum of cochains solution 1} gives
\begin{eqnarray*}
& & \Big( \psi_1( \tau_{x_3}(x_1), x_3) + \psi_1(\sigma_{x_1}(x_2),~\sigma_{\tau_{x_2}(x_1)}(x_3)), ~\sigma_{\sigma_{x_1}(x_2)}(\sigma_{\tau_{x_2}(x_1)}(x_3) ) \Big)\\
&=&  \Big( \psi_1( x_2, x_3) + \psi_1( x_1, \sigma_{x_2}(x_3) ),~  \sigma_{x_1}(\sigma_{x_2}(x_3))\Big),\\
& &\\
 & & \Big( \psi_1(x_1, x_2) + \psi_2( \sigma_{x_1}(x_2), ~\sigma_{\tau_{x_2}(x_1)}(x_3)), ~  \tau_{\sigma_{\tau_{x_2}(x_1)}(x_3)}(\sigma_{x_1}(x_2)) \Big) \\
 &=& \Big(  \psi_2( x_2, x_3) + \psi_1(\tau_{\sigma_{x_2}(x_3)}(x_1),   \tau_{x_3}(x_2) ), ~\sigma_{\tau_{\sigma_{x_2}(x_3)}(x_1)}(\tau_{x_3}(x_2)) \Big),\\
 & &\\
& & \Big( \psi_2(x_1, x_2) + \psi_2( \tau_{x_2}( x_1) , x_3), ~\tau_{x_3}(\tau_{x_2}(x_1))  \Big) \\
 &=& \Big( \psi_2(x_1, \sigma_{x_2}(x_3) ) +   \psi_2(\tau_{ \sigma_{x_2}(x_3)}(x_1), \tau_{x_3}(x_2)), ~ \tau_{ \tau_{x_3}(x_2)}(\tau_{\sigma_{x_2}(x_3)}(x_1)) \Big).
\end{eqnarray*} 
Adding these equalities give  the $2$-cocycle  condition for $\psi_1+ \psi_2$, and the proof is complete. $\blacksquare$
\end{proof}

Note that, although $\psi_1 + \psi_2$ is a cocycle, each of $\psi_1$ and $\psi_2$ can not be a cocycle. Taking $\psi_1=\psi_2$ in Proposition~\ref{extprop}, we obtain the following corollary.

\begin{corollary} \label{extcor}
Let $A$ be a ring in which $2$ is invertible and $V=A \times X$. Let $s: V \times V \rightarrow  V \times V $ be defined by 
	$$s\big( (a_1, x_1), (a_2, x_2) \big) = \big( (a_2 + \psi(x_1, x_2) , \sigma_{x_1}(x_2)),
	(a_1 + \psi(x_1, x_2),  \tau_{x_2}(x_1) ) \big)$$
	for  $(a_i, x_i) \in V$. 	If  $(V, s)$ is a solution to the Yang--Baxter equation, then 
	$\psi \in  Z^2_{\rm YB}(X;A)$.
\end{corollary}

\begin{proof}
In Proposition~\ref{extprop}, setting $\psi_1=\psi_2$ gives twice the cocycle condition at the end. The result follows since  $2$ is invertible in $A$.
$\blacksquare$
\end{proof}


\begin{example} \label{omegaextex} {\rm 
Let $X=\mathbb Z_q [s^{\pm 1}, t^{\pm 1} ] / (1-s)(1-t)$. Then, by Example~\ref{YBEexamples}, the matrix  $\displaystyle r= \left[ \begin{array}{cc} 1-s & s \\ t & 1-t \end{array} \right]$  gives a solution $(X, r)$ to the Yang--Baxter equation. Let $A=X$ and define $\psi_i: X \times X \rightarrow A$ by  $\psi_i(x, y)=u_i(y-x)$ for some $u_i \in X$, where $i=1,2$. Let $V=A \times X$ and $s: V \times V \rightarrow V \times V$ be as defined in Proposition~\ref{extprop}. That is, 
$$s\big( (a_1, x_1), (a_2, x_2) \big) = \big( (a_2 + \psi_1(x_1, x_2) , \sigma_{x_1}(x_2) ), ~(a_1 + \psi_2(x_1, x_2),  \tau_{x_2}(x_1) )\big)
$$
for any $(a_i, x_i) \in V$. Then $s$ is represented by the matrix  
$$\displaystyle  s= \left[ \begin{array}{cccc}
0 & -u_1 & 1 & u_1 \\
0 & 1-s & 0 & s \\
1 & -u_2 & 0 & u_2 \\
0 & t & 0 & 1-t 
\end{array} \right]. $$ 
Taking $\displaystyle Y= \left[ \begin{array}{cc} 1 & u_1 \\ 0 & s \end{array} \right]$
and $\displaystyle Z= \left[ \begin{array}{cc} 1 & -u_2 \\ 0 & t \end{array} \right]$, we see that  
$s$ can be written  as $\displaystyle s= \left[ \begin{array}{cc} I-Y & Y \\ Z & I-Z \end{array} \right]$, where $Y,Z$ invertible and $I$ is the identity matrix. If $u_2(1-s)+u_1(1-t)=0$, then $YZ=ZY$ and $(I-Y)(I-Z)=0$. Thus, by Example~\ref{YBEexamples}, $(V,s)$ is a solution to the Yang--Baxter equation and is an extension of $(X,r)$ by $(\psi_1, \psi_2)$.
