\left[ \begin{array}{cc} y_1 \\ y_2 \end{array} \right] \right)
=  \left[ \begin{array}{cc} w (y_2 - x_2)  \\ 0 \end{array} \right] , $$
where $w \in \mathbb{k}$. Take $s : V \times V \rightarrow  V \times V$ as in Proposition~\ref{extprop}, that is, 
$$s\big( (\vec{a}, \vec{x}), (\vec{b}, \vec{y}) \big) = \big( (\vec{b} + \psi(\vec{x}, \vec{y}) , \sigma_{\vec{x}}( \vec{y}) ), ~(\vec{a }+ \psi(\vec{x}, \vec{y}),  \tau_{\vec{y}}(\vec{x}) ) \big)$$ 
