\section{Homology of non-degenerate  solutions}
We present a (co)homology theory for left non-degenerate solutions to the Yang--Baxter equation based on the work \cite{MR3558231} of Lebed and Vendramin, which is a generalization of the (co)homology theory given in \cite{MR2128041}.  The (co)homology theory introduced in \cite{MR2128041} is a generalization of the quandle (co)homology theory defined in \cite{MR1990571}, which itself is a generalization of the (co)homology theory of Fenn, Rourke, and Sanderson \cite{MR1257904, MR2063665,MR2255194, MR1364012}.
\bigskip



\subsection{Pre-cubical structure}

Lebed and Vendramin \cite{MR3558231} studied left non-degenerate solutions to the Yang Baxter equation with the focus on two classes of algebraic structures, namely, racks and cycle sets.  They consider two cohomology theories of such solutions which extend previous works and place existing (co)homology theories into a broader perspective.  They showed that for a certain type of left non-degenerate  solutions, including quandles and non-degenerate cycle sets, the (co)homologies split into the degenerate and the normalized parts. Furthermore, they gave an interpretation of the second cohomology group of left non-degenerate solutions in terms of group cohomology generalizing a similar result for racks established by Etingof and Gra\~na \cite{MR1948837}. We now review the constructions from \cite{MR3558231}.

\begin{definition}
Let $\mathcal{C}$ be a category. A \index{pre-cubical structure}{pre-cubical structure} in $\mathcal{C}$ is a sequence of objects $\{C_k\}_{k \geqslant 0}$, together with two sequences of morphisms $d^+_i, d^-_i : C_k \to C_{k-1}$ (called boundaries) for each $k \ge 1$ and $1 \le i \le k$, such that the following  conditions hold:
\begin{eqnarray}\label{Equation pre Cubical}
d^\varepsilon_i d^\zeta_j = d^\zeta_{j-1}d^\varepsilon_i && ~\text{if}~ i < j \:\text{and } \varepsilon,\zeta \in \{+,-\}.
\end{eqnarray} 
A pre-cubical structure is called a \index{weak skew cubical structure}{weak skew cubical structure} if it also includes morphisms $s_i : C_k \to C_{k+1}$ (called degeneracies) for each $k \ge 1$ and $1 \le i \le k$, such that the following conditions hold:
\begin{eqnarray}
\nonumber d^\varepsilon_i s_j = s_{j-1}d^\varepsilon_i & & ~\text{if}~ i < j \:\text{and } \varepsilon \in \{+,-\},\\
\nonumber  d^\varepsilon_i s_j = s_{j}d^\varepsilon_{i-1} & & ~\text{if}~i > j+1 \:\text{and } \varepsilon \in \{+,-\},\\
d^\varepsilon_i s_i = d^\varepsilon_{i+1}s_{i} && ~\text{if}~ i \:\text{and } \varepsilon \in \{+,-\}.\label{Equation Weak Cubical 3}
\end{eqnarray}
A \index{skew cubical structure}{skew cubical structure} (respectively, \index{semi-strong skew cubical structure}{semi-strong skew cubical structure}) additionally satisfies  the conditions
	\begin{eqnarray*}
		s_i s_j = s_{j+1}s_i & &~\text{if}~ i \le j
	\end{eqnarray*}
	and the enhanced version
	\begin{eqnarray}
		d^\varepsilon_i s_i = d^\varepsilon_{i+1}s_{i} = \id \label{Equation Weak Cubical 3'}
		\end{eqnarray}
	of condition~\eqref{Equation Weak Cubical 3} for all $\varepsilon \in \{+,-\}$ (respectively, for $\varepsilon = +$ only).
\end{definition}

With the preceding definition,  we have the following result \cite[Theorem 2.2]{MR3558231}.

\begin{theorem}
Let $\{C_k,\,d^+_i,\, d^-_i \}$ be a pre-cubical structure in the category of modules over a commutative ring $\mathbb{k}$ with unity.
\begin{enumerate}
\item The $\mathbb{k}$-modules $C_k$ endowed with the alternating sum maps 
$$
\partial^{(\alpha, \beta)}_k = \alpha\sum\nolimits_{i=1}^k (-1)^{i-1}d^+_i + \beta \sum\nolimits_{i=1}^k (-1)^{i-1} d^-_i
$$
form a chain complex $\{C_k,\partial^{(\alpha, \beta)}_k \}$ for each $\alpha, \beta \in \mathbb{k}$. 
\item If the boundaries $(d^+_i,\, d^-_i)$ can be completed with degeneracies~$s_i$, then the modules $C^{D}_k= \sum_{i=1}^{k-1} \im (s_i)$ form a sub-complex of $\{C_k,\partial^{(\alpha, \beta)}_k \}$ for each $\alpha, \beta \in \mathbb{k}$.
\item If $\{C_k,\, d^+_i,\, d^-_i,\, s_i \}$ is moreover semi-strong skew cubical, then there are $\mathbb{k}$-module decompositions
\begin{equation} \label{Equation splitting general formula}
C_k = C^{D}_k\oplus C^{N}_k,
\end{equation}
where $C^{N}_k = \im (\eta_k)$ and  $\eta_k = ( \id- s_1d^+_2)( \id- s_2d^+_3)\cdots( \id- s_{k-1}d^+_k).$ It yields a chain complex splitting for $\{C_k,\partial^{(\alpha, \beta)}_k \}$ for each $\alpha, \beta \in \mathbb{k}$.
	\end{enumerate}
\end{theorem}

\begin{proof}
Assertions (1) and (2) can be verified by a direct computation. We give a complete proof of assertion (3). We fix $\alpha, \beta \in \mathbb{k}$ and put $\partial_k = \partial^{(\alpha, \beta)}_k$. We first show that $\eta_k$ form an endomorphism of the chain complex $\{C_k,\partial_k\}$. It suffices to verify the relations 
	\begin{align}\label{Equation eta complex map}
		&\sum\nolimits_{i=1}^k (-1)^{i-1}d^\varepsilon_i \eta_k = \eta_{k-1}\sum\nolimits_{i=1}^k (-1)^{i-1}d^\varepsilon_i \quad \textrm{for} \quad \varepsilon \in \{+,-\}.
	\end{align}
We put $p_i = \id - s_{i}d^+_{i+1}$ and rewrite $\eta_k$ as $p_1 \cdots p_{k-1}$. The weak skew cubical conditions imply that
\begin{eqnarray}
\nonumber d^\varepsilon_i p_j &=& p_{j-1}d^\varepsilon_i \quad \textrm{if} \quad i < j,\\
\label{Equation weak cubical p} d^\varepsilon_i p_j &=& p_{j}d^\varepsilon_{i} \quad \textrm{if} \quad i>j + 1,\\
\label{Equation weak cubical 3p} (d^\varepsilon_i-d^\varepsilon_{i+1})p_{i} &= & d^\varepsilon_i-d^\varepsilon_{i+1}.
\end{eqnarray}
Further, semi-strong skew cubical conditions yield
	\begin{align}
		p_id^\varepsilon_{i+1}p_{i+1} &= d^\varepsilon_{i+1}p_{i+1}.\label{Equation weak cubical 4p}
	\end{align}
Since
	\begin{align*}
		s_{i}d^+_{i+1}d^\varepsilon_{i+1}s_{i+1}d^+_{i+2} &\overset{\eqref{Equation pre Cubical}}{=}s_{i}d^\varepsilon_{i+1}d^+_{i+2}s_{i+1}d^+_{i+2} \overset{\eqref{Equation Weak Cubical 3'}}{=} s_{i}d^\varepsilon_{i+1}d^+_{i+2} \overset{\eqref{Equation pre Cubical}}{=} s_{i}d^+_{i+1}d^\varepsilon_{i+1},
	\end{align*}
we have 
$$
s_{i}d^+_{i+1}d^\varepsilon_{i+1}( \id-s_{i+1}d^+_{i+2}) = 0.
$$
Using \eqref{Equation weak cubical p}, we rewrite the right-hand side of~\eqref{Equation eta complex map} as
$$ p_1 \cdots p_{k-2}\sum\nolimits_{i=1}^k (-1)^{i-1}d^\varepsilon_i = \sum\nolimits_{i=1}^{k-1} (-1)^{i-1} p_1 \cdots p_{i-1} d^\varepsilon_i p_{i+1} \cdots p_{k-1} + (-1)^{k-1}p_1 \cdots p_{k-2} d^\varepsilon_k.
$$
In order to conclude, we obtain the identical expression for the left-hand side of~\eqref{Equation eta complex map} by repeatedly using the following for $s < k-1$:
\begin{eqnarray*}
&& \sum\nolimits_{i=s}^k  (-1)^{i-1} d^\varepsilon_i p_s \cdots p_{k-1} \\
&\overset{\eqref{Equation weak cubical p},\eqref{Equation weak cubical 3p}}{=}&\sum\nolimits_{i=s+2}^k (-1)^{i-1} p_s d^\varepsilon_i p_{s+1} \cdots p_{k-1}  + \big((-1)^{s-1} d^\varepsilon_s + (-1)^{s} d^\varepsilon_{s+1}\big) p_{s+1} \cdots p_{k-1}\\ 
&\overset{\eqref{Equation weak cubical 4p}}{=} & (-1)^{s-1} d^\varepsilon_s p_{s+1} \cdots p_{k-1} + p_s \big(\sum\nolimits_{i=s+1}^k (-1)^{i-1} d^\varepsilon_i \big) p_{s+1} \cdots p_{k-1}.
\end{eqnarray*}

Thus, both $C^{D}_k = \sum_{i=1}^{k-1} \im(s_i)$ and $C^{N}_k = \im(\eta_k)$ give sub-complexes of $\{C_k,\partial^{(\alpha, \beta)}_k\}$. It remains to establish the $\mathbb{k}$-module decomposition $C_k= C^{D}_k\oplus C^{N}_k$. The definition of $\eta_k$ directly imply that $\im ( \id- \eta_k) \subseteq \sum_{i=1}^{k-1} \im(s_i)$. 
Further, the semi-strong skew cubical conditions imply that
\begin{eqnarray*}
s_i p_j &=& p_{j+1}s_i \quad \textrm{if} \quad i \le j,\\
s_i p_j &=& p_{j}s_{i} \quad \textrm{if} \quad i > j+1,\\
p_is_i &=& 0,\\
p_is_{i+1} &=& s_{i+1} - s_i,\\
(s_i-s_{i+1})p_{i} &=& s_i-s_{i+1}.
\end{eqnarray*}
These relations further imply that the map~$\eta_k$ vanishes on $\im(s_i)$ for all $1 \le i \le k-1$. Consider the sequence $$C^{D}_k \overset{\iota_k}{\hookrightarrow} C_k \overset{\eta_k}{\to} C_k$$ of $\mathbb{k}$-modules and homomorphisms, where~$\iota_k$ is the inclusion map. Note that $\eta_k \iota_k = 0$ and $\im ( \id- \eta_k) \subseteq \im(\iota_k)$. The condition $\im ( \id- \eta_k) \subseteq \im(\iota_k)$ implies that $C_k=\im(\iota_k) + \im (\eta_k)$. The relation $\eta_k \iota_k = 0$  means that $\im (\iota_k) \subseteq \ker(\eta_k)$. Thus, we have $\im(\id -\eta_k) \subseteq  \ker(\eta_k)$, which translates to $\eta_k^2 = \eta_k$. But this yields $\ker (\eta_k) \cap \im (\eta_k)=0$, and hence $\im (\iota_k) \cap \im (\eta_k)=0$. Thus, we obtain the direct sum decomposition $C_k=\im (\iota_k) \oplus \im(\eta_k)$. $\blacksquare$
\end{proof}

The decomposition~\eqref{Equation splitting general formula} induces a decomposition at the level of homology groups.  The ${D}$- and ${N}$- parts of the complexes and homology groups above are called \emph{degenerate} and \emph{normalized}, respectively.
