\includegraphics[height=3.3cm]{graphic-calculus-rule.pdf}
\caption{Labelling by a solution at a crossing and its opposite.}
\label{graphic calculus rule} 
\end{center}
\end{figure}


\begin{figure}[!ht]
 \begin{center}
\includegraphics[height=6cm]{graphical-YBE.pdf}
\caption{Reidemeister move $R3$ representing the Yang--Baxter equation.}
\label{graphical YBE} 
\end{center}
\end{figure}

\begin{definition}\label{braided module over a solution}
Let $(X, r)$ be a solution to the Yang--Baxter equation. A right (braided) module over $(X,r)$ is a pair $(M, \rho)$, where $M$ is a set and $\rho : M \times X \to M$ is a map  written as $\rho(m,x) = m \cdot x$ such that the following  condition
$$(m \cdot x) \cdot y = \big(m \cdot  \sigma_x(y) \big) \cdot \tau_y(x)$$ 
 hold for all $m \in M$ and $x,y \in X$. \\
 Similarly, a left (braided) module over $(X,r)$ is a pair $(N, \lambda)$, where  $\lambda : X \times N \to N$ is a map  written as $\lambda(x, n) = x \cdot n$ such that 
$$ x \cdot (y \cdot n)  = \sigma_x(y) \cdot \big(\tau_y(x) \cdot n \big)$$ 
 hold for all $n \in N$ and $x,y \in X$. See Figure \ref{left right modules YBE} for a graphical interpretation of braided modules.
\end{definition}

\begin{figure}[!ht]
 \begin{center}
\includegraphics[height=3cm]{left-right-modules-YBE.pdf}
\caption{Right and left braided modules.}
\label{left right modules YBE} 
\end{center}
\end{figure}

\begin{example} \label{Example Trivial}
{\rm Let us consider some examples.
\begin{enumerate}
\item  The singleton set $I = \{\ast\}$ with the unique map $X \to I$ yields an example of a right (as well as left) $(X,r)$-module for any solution $(X,r)$. It is referred to as the \textit{trivial} right (left) $(X,r)$-module.
\item If $(X,r)$ is a solution, then $X$ is a right module over itself with the action $\rho(x, y) =\tau_y(x)$  (see \eqref{condition for solution 3}). Similarly, $X$ it is a left module over itself with the action $\lambda(x, y) = \sigma_x(y)$ (see \eqref{condition for solution 1}). These modules are called \index{adjoint module} adjoint modules. More generally, any power $X^n$ is a right and a left module over $T(X) = \sqcup_{i \ge 0} X^i$ with the module structure adjoint to the extension of the braiding $(X,r)$ to $T(X)$.
\end{enumerate}}
\end{example}

Let $(M,\rho)$ be a right module  and $(N,\lambda)$ a left module  over a solution $(X,r)$ to the Yang--Baxter equation. Let  $r_i, \rho_0, \lambda_n: M \times X^n \times N \to M \times X^{(n-1)}\times N$ be maps given by
\begin{eqnarray*}
r_i &=& \id_{M} \times \id_{X}^{(i-1)} \times r \times \id_{X}^{ (n-i-1)} \times \id_N,\\
\rho_0 &=& \rho \times \id_{X}^{(n-1)} \times \id_N,\\
\qquad \lambda_n &=& \id_{M} \times \id_{X}^{ (n-1)} \times \lambda.
\end{eqnarray*}

The  proof of the following result is a computational check and left as an exercise \cite[Theorem 3.5]{MR3558231}.

\begin{theorem}\label{Theorem module sol pre cubical}
Let $(M,\rho)$ be a right module  and $(N,\lambda)$ a left module  over a solution $(X,r)$ to the Yang--Baxter equation. Define $C_n = M \times X^n \times N$. Then the following assertions hold:
\begin{enumerate} 
\item  The  maps $d_i^{l,+}, d_i^{r,-}: C_n \to C_{n-1}$ given by 
$$
d_i^{l,+} = \rho_0 \circ r_1 \circ \cdots \circ r_{i-1}
\quad \textrm{and} \quad 
 d_i^{r,-} = \lambda_n \circ r_{n-1} \circ \cdots \circ r_{i}
$$
give a pre-cubical structure $\{C_n, d_i^{l,+}, d_i^{r,-} \}$.
\item Suppose that the braiding $r$ is invertible and define
$$ d_i^{l,-} = \rho_0 \circ r^{-1}_1 \circ \cdots \circ r^{-1}_{i-1}
\quad \textrm{and} \quad 
d_i^{r,+} = \lambda_n \circ r^{-1}_{n-1} \circ \cdots \circ r^{-1}_{i}.
$$
Then for any choice of $\varepsilon,\zeta \in \{l,r\}$, the triplet $\{C_n, d_i^{\varepsilon,+},\, d_i^{\zeta,-} \}$ with $n \ge 1$ and $1 \le i \le n$, forms a pre-cubical structure. See Figure \ref{differentials of Theorem BrHom} for a graphical interpretation of the differentials.
\end{enumerate}
\end{theorem}

