\includegraphics[height=10cm]{differentials-Theorem-BrHom.pdf}
\caption{Differentials in braided homology.}
\label{differentials of Theorem BrHom} 
\end{center}
\end{figure}

\begin{remark}
{\rm 
The homology theory arising from Theorem \ref{Theorem module sol pre cubical} is called the \index{braided homology}{braided homology}. By choosing trivial modules (see Example \ref{Example Trivial}) as coefficients with  $\alpha = 1$ and $\beta = -1$, one gets the chain complex and hence homology of \cite{MR2128041} described in Section \ref{homsec colorings} of this chapter. See also \cite[Theorem 3.1]{MR3835755} for a direct chain  homotopy equivalence between the two complexes. We recommend the reader to see \cite{MR3558231} for elegant graphical and intuitive interpretations of the differentials defined in this section.}
\end{remark}
