\subsection{Birack homology}\label{S:BirackHom} 
The origins of a homology theory for biracks lie in the work \cite{MR1257904} of Fenn, Rourke and Sanderson, and was developed in the language of augmented biracks in \cite{MR3266530}. It is worth noting that, in \cite{MR2906433, MR3381331}, Przytycki studied homology theory of distributive magmas which specialises to homology of racks and quandles. 


\begin{definition}
 A solution to the Yang--Baxter equation is called a \index{birack}{birack} if it is bijective and non-degenerate.
\end{definition}

In other words, a solution $(X, r)$ with $r(x, y)= \big(\sigma_x(y), \tau_y(x)\big)$ is a birack if the braiding $r:X \times X \to X \times X$ and the maps $\sigma_x, \tau_x:X \to X$ are bijective  for all $x \in X$.


\begin{remark}
{\rm It is worth noting that in several other works, for instance \cite{MR4406425, MR2100870, MR4125863}, the term birack is used for an algebraic structure with two binary operations satisfying certain mixing axioms. It turns out that the birack defined above gives rise to such an algebraic structure and the converse also holds. Special types of biracks gives rise to what are called biquandles, which have been used extensively for constructing invariants of virtual knots and links \cite{MR3055555, MR3666513, MR2100870, MR2994593, MR3868206}.
}
\end{remark}

We have the following result \cite[Theorem 4.2]{MR3558231}.

\begin{theorem}\label{Theorem birack pre cubical}
Let $(X,r)$ be a birack and $C_n=X^n$. Then the following assertions hold:
\begin{enumerate}
\item The maps $d_i, d_i':C_n\to C_{n-1}$ given by
\begin{eqnarray*}
&& d_i : (x_1, \ldots, x_n) \mapsto \big(\tau_{x_i}^{-1}(x_1), \ldots, \tau_{x_i}^{-1}(x_{i-1}), \sigma_{\tau_{x_{i+1}}^{-1}(x_i)}(x_{i+1}), \ldots, \sigma_{\tau_{x_n}^{-1}(x_i)}(x_n)\big),\\
&& d_i'  : (x_1, \ldots, x_n) \mapsto (x_1, \ldots, x_{i-1}, x_{i+1}, \ldots, x_n), 
\end{eqnarray*}
form a pre-cubical structure $\{C_n, d_i, d_i' \}$.
\item The assertion remains true when the maps $d_i$ are replaced with
\begin{eqnarray*}
&& d^\star_i : (x_1, \ldots, x_n) \mapsto \big( \sigma_{\tau_{x_1}^{-1}(x_i)}(x_1),\ldots, \sigma_{\tau_{x_{i-1}}^{-1}(x_i)}(x_{i-1}), \tau_{x_i}^{-1}(x_{i+1}), \ldots, \tau_{x_i}^{-1}(x_n)\big).
\end{eqnarray*}
\end{enumerate}
\end{theorem}

\begin{proof}
The proof of assertion (1) follows from the fact that $d_i\; d'_j=d'_{j-1} \; d_i$, which is straightforward from the definitions of $d_i$ and $d'_i$. Similarly, definitions of $d_i^\star$ and $d'_i$ yield assertion (2). $\blacksquare$
\end{proof}

The homology theory arising from Theorem \ref{Theorem birack pre cubical} is called the \index{birack homology}{birack homology}. It turns out that the braided homology and the birack homology are intimately related. Let us set some terminology to state the precise result. 

\begin{definition}
Let  $(X, r)$ be a solution to the Yang--Baxter equation and $n \ge 1$. The $n$-guitar map for $(X, r)$ is the map $J: X^n\to  X^n$ defined by $$J(\bar{x})= \big(J_1(\bar{x}), \ldots, J_n(\bar{x}) \big),$$ where $J_i(\bar{x})=\tau_{x_n} \tau_{x_{n-1}}\cdots \tau_{x_{i+1}}(x_i)$ and $\bar{x}=(x_1, \ldots, x_n)\in X^n$.  See Figure \ref{guitar map} for a graphical interpretation of the $n$-guitar map.
\end{definition}


\begin{figure}[!ht]
 \begin{center}
\includegraphics[height=5.6cm]{guitar-map.pdf}
\caption{The $n$-guitar map.}
\label{guitar map} 
\end{center}
\end{figure}

Recall that, a shelf is a non-empty set with a right-distributive binary operation.

\begin{lemma}\label{LNDS guita map lemma}
Let $(X, r)$ be a left non-degenerate solution to the Yang--Baxter equation. Then the following assertions  hold:
\begin{enumerate}
\item The binary operation $x*_r y= \tau_y \big(\sigma_{\tau_x^{-1}(y)}(x)\big)$ defines a shelf structure on $X$.
\item The shelf $(X, *_r)$ is a rack if and only if $r$ is bijective.
\item The $n$-guitar map $J$ for $(X, r)$ is bijective for all $n \ge 1$.
\end{enumerate}
\end{lemma}

\begin{proof}
Assertion (1) is immediate from the left non-degeneracy of the solution $(X, r)$. Similarly, the bijectivity of $J$ is equivalent to the left non-degeneracy of $r$, which gives assertion (3). For assertion (2), suppose that $r$ is bijective. This implies that, for a given $y \in X$, the map $x \mapsto \sigma_{\tau_x^{-1}(y)}(x)$ is bijective. Since the map $x \mapsto \tau_y(x)$ is bijective by left non-degeneracy, it follows that the map $x \mapsto x *_r y$ is bijective, and hence $(X, *_r)$ is a rack. Conversely, the bijectivity of $x \mapsto x *_r y$ and of $x \mapsto \tau_y(x)$ yields the bijectivity of $x \mapsto \sigma_{\tau_x^{-1}(y)}(x)$. Then $r^{-1}$ is defined by $r^{-1}(z, y) = \big(\tau_x^{-1}(y), x \big)$, where $x$ is the unique element of $X$ satisfying  $\sigma_{\tau_x^{-1}(y)}(x)=z$. $\blacksquare$
\end{proof}

Let $(X, r)$ be a left non-degenerate solution. In view of Lemma \ref{LNDS guita map lemma}(3), let $J^{-1}= (J_1^{-1}, \ldots, J_n^{-1})$ denote  the inverse of the $n$-guitar map $J$. Define maps $\chi_i: X^n \to X$ by
$$\chi_i(x_1, \ldots, x_n)=J_1^{-1}\big((x_i *_r x_{i-1})*_r \cdots *_r x_1, x_1, x_2, \ldots, x_{i-1}, x_{i+1}, \ldots, x_n \big),$$

The next result extends the birack homology to the more general left non-degenerate solutions and also add coefficients to the involved chain complexes. Further, it establishes an equivalence between this extended birack homology and the braided homology using the guitar map \cite[Theorem 7.1]{MR3558231}. 

\begin{theorem}\label{equality of braided and birack homology}
Let $(X, r)$ be a left non-degenerate solution to the Yang--Baxter equation. Let $(M,\rho)$ be a right module  and $(N,\lambda)$ a left module  over $(X,r)$. Consider the sets $C_n = M \times X^n \times N$. Then the following assertions hold:
\begin{enumerate} 
\item  The  maps $d_i, d_i': C_n \to C_{n-1}$ defined by 
\begin{eqnarray*}
&& d_i: (a, x_1, \ldots, x_n, b) \mapsto  \big(a, \tau_{x_i}^{-1}(x_1), \ldots, \tau_{x_i}^{-1}(x_{i-1}), \sigma_{\tau_{x_{i+1}}^{-1}(x_i)}(x_{i+1}), \ldots, \sigma_{\tau_{x_n}^{-1}(x_i)}(x_n),  \lambda(x_i, b) \big),\\
&& d_i'  : (x_1, \ldots, x_n) \mapsto \big(\rho(a, \chi_i(\bar{x})),  x_1, \ldots, x_{i-1}, x_{i+1}, \ldots, x_n, b \big) 
\end{eqnarray*}
for $\bar{x}=(x_1, \ldots, x_n) \in X^n$, $a \in M$ and $b \in N$, give a pre-cubical structure $\{C_n, d_i, d_i' \}$.
\item The extended guitar map $J := \id_M \times J \times  \id_N$ yields an isomorphism between the pre-cubical structure $\{C_n, d_i^{r,-}, d_i^{l,+}\}$ of Theorem  \ref{Theorem module sol pre cubical} and the structure $\{C_n, d_i, d_i' \}$ of assertion (1) above.
\end{enumerate}
\end{theorem}

\begin{remark}
{\rm Note that when the solution is a birack and the coefficients $M$ an $N$ are trivial (see Example \ref{Example Trivial}), the pre-cubical structure from Theorem \ref{equality of braided and birack homology} specializes to that from Theorem \ref{Theorem birack pre cubical}. Thus, the braided homology and the birack homology are identical for biracks.
}
\end{remark}

\begin{remark}\label{star 2-cocycle}
{\rm
Let $(X, r)$ be a  left non-degenerate solution to the Yang--Baxter equation. Changing the pre-cubical structure $(d_i, d'_i)$ to $(d^{\star}_i, d'_i)$ in Theorem~\ref{Theorem birack pre cubical}, one obtains  a (co)homology theory for which a map $f: X \times X \to A$ is a $2$-cocycle if 
\begin{eqnarray}\label{left non-dgen cocycle condition}
  f(x,z)+f \big(\tau_x^{-1}(y),\tau_x^{-1}(z) \big)=f(y,z)+f \big(\sigma_{\tau_x^{-1}(y) } (x),\tau_y^{-1}(z) \big)
\end{eqnarray}
for all $x, y, z \in X$.}
\end{remark}
\medskip


\begin{lemma}	\label{L:FunAsMod}
Let $(X,r)$ be a left non-degenerate solution to the Yang--Baxter equation and~$A$ an abelian group. Then the map
	$$\Map(X,A) \times X \to \Map(X,A)$$
given by $(\gamma, x) \mapsto \gamma \cdot x$, where  $(\gamma \cdot x)(y)= \gamma \big(\tau_x^{-1} (y)\big)$ for all $x, y \in X$,
extends to a right $G(X,r)$-module structure on the abelian group $\Map(X,A)$ of maps from $X$ to $A$.
\end{lemma}

\begin{proof}
Since $(X, r)$ is left non-degenerate, each $\tau_x$ is a bijection. Hence, by Proposition \ref{p122}, there is a left-action of the group $G(X,r)$ on the set $X$ obtained by 
extending the map $X \to \Sigma_X$, given by $x \mapsto  \tau_x^{-1}$, to a group homomorphism $G(X,r) \to \Sigma_X$. This left-action induces a right $G(X, r)$-module structure on the abelian group $\Map(X,A)$ by setting $(\gamma, u) \mapsto \gamma \cdot u$, where  
$$(\gamma \cdot u)(x)= \gamma(u \cdot x)=\gamma \big(\tau_u^{-1} (x) \big) \quad \textrm{and} \quad \tau_u^{-1}= \tau_{x_k}^{-\epsilon_k} \cdots \tau_{x_1}^{-\epsilon_1}
$$ for $x \in X$, $\gamma \in \Map (X, A)$ and $u= x_1^{\epsilon_1}\cdots x_k^{\epsilon_k} \in G(X, r)$. $\blacksquare$
\end{proof}

Compare the action of Lemma \ref{L:FunAsMod} with the one given by \eqref{adj action on set of maps} for racks. The group cohomology with these choices turns out to be useful in studying the cohomology of our left non-degenerate solution. We now present the following result \cite[Theorem 11.2]{MR3558231}, which generalizes Theorem \ref{relation rack cohomo and group cohomo}(2). 

\begin{theorem}\label{T:GroupCohom}
Let $(X,\, r)$ be a left non-degenerate solution to the Yang--Baxter equation and~$A$ an abelian group. Then there is an isomorphism
$$\Ho^2_{\rm LND}(X;A)\cong \Ho^1_{\rm Grp} \big(G(X, r);\Map(X,A) \big)$$
of groups, where on the left hand side $\Ho^2_{\rm LND}$ stands for the cohomology of $(X,\, r)$ with coefficients in $A$ (as in Remark \ref{star 2-cocycle}), and on the right hand side $\Ho^1_{\rm Grp}$ stands for the group cohomology of $G(X, r)$ with coefficients in the right module $\Map(X,A)$ (as in Lemma \ref{L:FunAsMod}).
\end{theorem}

\begin{proof}
Consider the map 
$$ \Phi: Z^1\big(G(X, r);\Map(X,A) \big) \longrightarrow Z^2(X;A)$$
given by
$$\Phi(\theta)(x,y)=\theta(x)(y)$$
for $\theta \in Z^1\big(G(X, r);\Map(X,A) \big)$ and $x, y \in X$.
Consider another map
$$\Psi: Z^2(X;A) \to  Z^1\big(G(X, r); \Map(X,A) \big)$$
given by
$$f \mapsto \Psi(f),$$
where $\Psi(f):G(X, r) \to \Map(X,A)$ has the form
$$\Psi(f)(u)(x)= f(u,x)$$
for $f \in Z^2(X;A)$, $u \in G(X, r)$ and $x \in X$.  We claim that the following assertions hold:
\begin{enumerate}
\item $\Phi $ is well-defined.
\item $\Psi$ is well-defined.
\item $\Phi$ maps $1$-coboundaries to $2$-coboundaries.
\item $\Psi$ maps $2$-coboundaries to $1$-coboundaries.
\end{enumerate}

In view of the preceding claims, we see that $\Phi$ and~$\Psi$ are inverses of each other.  Let us prove the claims one-by-one.
\begin{enumerate}
\item Let $\theta \in Z^1\big(G(X, r); \Map(X,A) \big)$ be a group 1-cocycle. Then, by \eqref{group coboundary 1}, $\theta$ satisfies the relation 
			$$\theta(g_1g_2) =  \theta(g_2) + \theta(g_1)\cdot g_2 = \theta(g_2) + \theta(g_1)\tau_{g_2}^{-1}$$
			for $g_1,g_2 \in G(X, r)$.	For $f := \Phi(\theta)$, we need to check the 2-cocycle condition \eqref{left non-dgen cocycle condition} given by
			$$f(x,z)+ f \big(\tau_x^{-1}(y),\tau_x^{-1}(z) \big)=f(y,z)+f \big(\sigma_{\tau_x^{-1}(y) } (x),\tau_y^{-1}(z) \big)$$
			for all $x,y,z \in X$, which can be rewritten as
			$$\theta(x)(z)+\theta \big(\tau_x^{-1}(y) \big) \big(\tau_x^{-1}(z) \big)=\theta(y)(z)+ \theta \big(\sigma_{\tau_x^{-1}(y)}(x) \big) \big(\tau_y^{-1}(z) \big).$$
			Recalling the definition of the $G(X, r)$-action on $\Map(X,A)$, the preceding equation transforms into
			$$\theta(x)(z)+\big(\theta(\tau_x^{-1}(y)) \cdot x \big)(z)=\theta(y)(z)+ \big(\theta(\sigma_{\tau_x^{-1}(y)}(x)) \cdot y \big)(z).$$
   This gives
   $$\theta(x)+\theta \big(\tau_x^{-1}(y) \big) \cdot x=\theta(y)+\theta \big(\sigma_{\tau_x^{-1}(y)}(x) \big) \cdot y$$
   for all $x, y \in X$. By the $1$-cocycle condition for~$\theta$, the preceding equation is the same as
$$\theta \big((\tau_x^{-1}(y)) x \big)= \theta \big(( \sigma_{\tau_x^{-1}(y) } (x)) y \big).$$
But this relation follows from the relation $\big(\tau_x^{-1}(y) \big) x = \big( \sigma_{\tau_x^{-1}(y) } (x)\big) y$, which always hold in the structure group $G(X, r)$.
			\item Recall that, a map $\theta: G(X, r)\rightarrow  \Map(X,A)$ is a group $1$-cocycle if and only if the map
			$G(X, r)\to G(X, r)\ltimes \Map(X,A)$ given by $g\mapsto (g,\theta(g))$ is a group homomorphism. Here, $G(X, r)\ltimes \Map(X,A)$ is the set  $G(X, r)\times \Map(X,A)$ endowed with the group operation 
   $$(g,\gamma)(g',\gamma')=(gg',~\gamma \cdot g' +\gamma')=(gg',~\gamma \tau^{-1}_{g'} +\gamma')$$ 
in the semi-direct product.   We will now show that, for each $f \in Z^2(X;A)$, the map $\hat{f} : X \to G(X, r)\ltimes  \Map(X,A)$, given by $\hat{f}(x)=\big(x,f(x,-)\big)$, extends to a unique group homomorphism $G(X, r) \to G(X, r)\ltimes \Map(X,A)$. For this, it suffices to check that
$$\hat{f} \big(\tau_x^{-1}(y)\big) \hat{f}(x) = \hat{f} \big( \sigma_{\tau_x^{-1}(y) } (x) \big) \hat{f}(y)$$
for all $x,y \in X$. The preceding equation reads as
			$$\big(\tau_x^{-1}(y),~ f(\tau_x^{-1}(y) ,-)\big)\big(x,f(x,-)\big)=\big( \sigma_{\tau_x^{-1}(y) } (x), ~f( \sigma_{\tau_x^{-1}(y) } (x) ,-)\big)\big(y,f(y,-)\big),$$
			which further simplifies to	
$$ \big((\tau_x^{-1}(y))x, ~f(\tau_x^{-1}(y), 	\tau_x^{-1}(-)) + f(x,-)\big)= \big(( \sigma_{\tau_x^{-1}(y) } (x))y,  ~f(\sigma_{\tau_x^{-1}(y) } (x) , 	\tau_{y}^{-1}(-) )+f(y,-)\big).$$
Since the relation $ \big(\tau_x^{-1}(y) \big) x = \big(\sigma_{\tau_x^{-1}(y)}(x) \big) y$ always holds in $G(X, r)$, it remains to show that
			$$ f \big(\tau_x^{-1}(y), 	\tau_x^{-1}(-) \big) + f(x,-)= f \big(\sigma_{\tau_x^{-1}(y) } (x) , 	\tau_{y}^{-1}(-) \big)+f(y,-),$$
			but this is precisely the definition of a quandle $2$-cocycle.
\item A group $1$-coboundary in $C^1\big(G(X, r); \Map(X,A) \big)$ is a map $\lambda: G(X, r) \to \Map(X,A)$ of the form 			
   $$\lambda(g)= \gamma - \gamma \cdot g= \gamma - \sigma_{\tau_{g}^{-1}(\gamma) } (g)$$
    for some $\gamma \in \Map(X,A).$  Its image $\Phi(\lambda)$ is the map given by
			$$\Phi(\lambda)(x, y)= \lambda(x)(y)= (\gamma - \gamma \cdot x)(y)= \gamma(y) - \gamma \big( \tau_{x}^{-1}(y)\big) = - \partial^1 \gamma(x,y),$$
			yielding $\Phi(\lambda) = \partial^1 (-\gamma)$.
\item A $2$-coboundary in $C^2(X;A)$ is a map of the form $\partial^1(\gamma)$ for some $\gamma \in \Map(X,A)$. Since~$\Phi$ and~$\Psi$ are  inverses of each other, the computation above implies the relation $\Psi \big(\partial^1 (\gamma)\big) = \partial_{{\rm group}}^0 (-\gamma)$.
		\end{enumerate}
  This completes the proof of the theorem. $\blacksquare$
\end{proof}
\bigskip
\bigskip

