\chapter{Computations of homology and cohomology of solutions}\label{chapter homology computations}

\begin{quote}
The computation of the homology and cohomology of racks, quandles, and other solutions to the Yang--Baxter equation is typically challenging. Although  the number of computational techniques for these structures is relatively limited compared to homology theories for other algebraic structures, there is a significant body of computational results available in the literature. This chapter surveys key findings related to the computational aspects of homology and cohomology for solutions to the Yang--Baxter equation.
\end{quote}
\bigskip

\section{Low dimensional homology of racks and quandles}
A thorough examination of the existing literature on homology and cohomology computations would necessitate a dedicated text focused exclusively on the subject. For a more in-depth exploration of the topic, we recommend referring to the following references: \cite{MR4038329, MR4065999, MR3613433, MR3342681, MR2854230, MR4602407, MR4310563, MR3196064, MR4491426, MR3226796, MR2988494, MR2657689, MR3898509, MR2521709, MR2494367, MR2673749, MR2777023, MR3042590, MR4400200, MR3571388, MR3937311}. We use the convention that, whenever the coefficients of (co)homology groups are not specified, they are assumed to be $\mathbb{Z}$ coefficients. 
\para 

The free parts of the rack, degenerate, and quandle homology groups of finite racks and quandles are well understood (\cite[Corollary 4.3]{MR1948837} and \cite[Theorem 2]{MR1952425}).

\begin{theorem}  \label{Theorem 1.4}
Let $\mathcal{O}$ be the set of orbits of a finite rack or a quandle $X$. Then the following assertions hold:
	\begin{enumerate}
		\item $\rank \big( \Ho_n^{\rm R}(X) \big)=|\mathcal{O}|^{n}$.
		\item $\rank \big(\Ho_n^{\rm Q}(X) \big)=|\mathcal{O}| \big(|\mathcal{O}|-1 \big)^{n-1}$.
		\item $\rank \big( \Ho_n^{\rm D}(X) \big)=|\mathcal{O}|^{n}-|\mathcal{O}| \big(|\mathcal{O}|-1 \big)^{n-1}$.
	\end{enumerate}
\end{theorem}

If $|\mathcal{O}|=1$, that is, $X$ is a connected rack, then $\rank \big(\Ho_n^{\rm R}(X) \big)=1$. For latin quandles, Niebrzydowski and Przytycki provided a natural description of the kernel of the second boundary map  \cite[Lemma 2.1]{MR2777023}.

\begin{lemma}
Let $X$ be a latin quandle and $a_0 \in X$ a fixed element. Let $\langle(a_0,a) \rangle$ be the subgroup of $C^{\rm Q}_2(X)$ generated by elements of the form $(a_0,a)$ for any $a\in X$.  Then the quotient map $C^{\rm Q}_2(X) \rightarrow	C^{\rm Q}_2(X)/ \langle (a_0,a)\rangle$ is an isomorphism when restricted to $\ker( \partial_2)$.
\end{lemma}

As a consequence, the following result is obtained \cite[Corollary 2.2]{MR2777023}.

\begin{corollary} 
If $X$ is a latin quandle and $a_0 \in X$ a fixed element, then $$\Ho^{\rm Q}_2(X) \cong \mathbb{Z}^{X\times X} / \big\langle (a,a),(a_0,b), \im(\partial_3) \big\rangle.$$
\end{corollary}

Recall that, if $G$ is a group, then $\Core(G)$ is an involutory quandle with the binary operation $g*h=hg^{-1}h$. If $G$ is abelian, then $\Core(G)=\T(G)$, the Takasaki quandle of $G$. Note that the Takasaki quandle of a group of odd order is latin. In order to state the next result, we recall the definition of the exterior square of a module.

\begin{definition}
	Let $\mathbb{k}$ be a commutative ring and let $A$ be a $\mathbb{k}$-module.  Then the exterior square $\wedge^2 A$ is defined as the quotient of $A \otimes_{\mathbb{k}} A$ by the submodule generated by the set $\{ x \otimes x \; \mid \; x \in A \}$.
\end{definition}

The following result holds \cite[Theorem 1.1]{MR2777023}. 

\begin{theorem}\label{exterior}
If $G$ is an abelian group of odd order, then
	$$\Ho_2^{\rm Q} \big(T(G) \big) \cong  \wedge^2 G.$$ 
In particular, if	$G=\mathbb{Z}_k  ^n$, where $k$ is odd, then
	$$\Ho_2^{\rm Q} \big(T(\mathbb{Z}_k^n) \big) \cong \mathbb{Z}_k^{\frac{n(n-1)}{2}}.$$
\end{theorem}

Next, we consider computations of second quandle homology of Core quandles of some groups \cite[Example 4.2]{MR2777023}.

\begin{example}
There are five non-isomorphic groups of order $27$. The second quandle homology of their core quandles are as follows:
\begin{enumerate}
\item If $G=\mathbb{Z}_{27}$, then  $\Ho^{\rm Q}_2 \big(T(G) \big) \cong 1$.
\item If $G=\mathbb{Z}_{3}\oplus \mathbb{Z}_9$, then  $\Ho^{\rm Q} _2 \big(T(G) \big) \cong \mathbb{Z}_3$.
\item If  $G=\mathbb{Z}_{3}^3$, then $\Ho^{\rm Q} _2 \big(T(G)\big) \cong \mathbb{Z}_3^3$.
\item If $G=\langle s,t\ \mid \  s^9=t^3=1,~st=ts^4 \rangle $, then $\Ho^{\rm Q} _2 \big(\Core(G) \big) \cong\mathbb{Z}_3$.
\item If $G=\langle x,y,z\ \mid \  x^3 = y^3 = z^3 = 1, ~yz = zyx,~ xy = yx, ~xz = zx \rangle $, then $\Ho^{\rm Q}_2 \big(\Core(G) \big) \cong \mathbb{Z}_3^3$.	
\end{enumerate}
\end{example}

Mochizuki proved the following result \cite[Theorem 3.1(ii)]{MR1960136}.

\begin{theorem}\label{Mochizuki theorem on third homology}
If $p$ is an odd prime and $\R_p$ is the dihedral quandle of order $p$, then $\Ho_3^{\rm Q}(\R_p;\mathbb{ Z}_p ) \cong \mathbb{ Z}_p$.
\end{theorem}

Note that the preceding result is equivalent to $ \Ho^{\rm R}_3(\R_p) \cong\mathbb{ Z} \oplus \mathbb{ Z}_p$, which was originally conjectured by Fenn, Rourke, and Sanderson  \cite[Conjecture 5.12 ]{MR2065029}.  Furthermore, they proposed  the following general conjecture  \cite[Conjecture 16]{MR2494367}.

\begin{conjecture}
If $p$ is an odd prime and  $\R_p$ is the dihedral quandle of order $p$, then the torsion subgroup of $\Ho^{\rm R}_n(\R_p)$ is annihilated by $p$ for each $n>1$.
\end{conjecture}

The following results are proved using some homology operations on homology of quandles \cite[p. 1537]{MR2673749}.

\begin{proposition}
Let $\R_n$ be the dihedral quandle of order $n$. Then the following assertions hold:
\begin{enumerate}
\item $\Ho_3^{\rm Q}(\R_8) \cong \mathbb{Z}^2 \oplus \mathbb{Z}_8^2$.
\item $\Ho_4^{\rm Q}(\R_8) \cong \mathbb{Z}^2 \oplus \mathbb{Z}_2^4 \oplus \mathbb{Z}_4^4 \oplus \mathbb{Z}_8^2$.
\item $\Ho^{\rm Q}_3(\R_{16}) \cong \mathbb{Z}^2 \oplus \mathbb{Z}_{16}^2$.
\end{enumerate}
\end{proposition}

In general, the following statement was conjectured \cite[Conjecture 14]{MR2673749}.

\begin{conjecture}\label{Conjecture 3.1}
If $k \neq 2^t$ for any $t>1$, then $k$ annihilates the torsion in $\Ho_n^{\rm R}(\R_{2k})$. If $k=2^t$ for some $t>1$, then $2k$ is the smallest integer annihilating torsion in $ \Ho_n^{\rm R}(\R_{2k})$. 
\end{conjecture}

It is a classical result that the reduced homology of a finite group $G$ is annihilated by its order \cite[Corollary 10.2]{MR0672956}. Przytycki and Yang
proved the following analogous result for latin quandles \cite[Theorem 2.1]{MR3346517}, which was conjectured by Niebrzydowski and Przytycki  \cite[Conjecture 42]{MR2673749}.

\begin{theorem} \label{1}
Let $X$ be a finite latin quandle. Then the torsion subgroup of $\Ho_n^{\rm R}(X)$ is annihilated by $|X|$.
\end{theorem}

Note that every Latin quandle is connected; however, a connected quandle need not be Latin. It is observed in \cite{MR3346517} that the previous result does not hold for connected quandles that are not Latin.

\begin{example}\label{connected but not latin homology}
	Let $X=\{1,2,3,4,5,6\}$ be the quandle given by the following multiplication table. 
$$
\begin{tabular}{|c||c|c|c|c|c|c|}
\hline
$\ast$ & 1 & 2 & 3 & 4 & 5 & 6 \\
\hline \hline
1 & 1 & 1 & 6 & 5 & 3 & 4 \\ \hline
2 & 2 & 2 & 5 & 6 & 4 & 3 \\ \hline
3 & 5 & 6 & 3 & 3 & 2 & 1 \\ \hline
4 & 6 & 5 & 4 & 4 & 1 & 2 \\ \hline
5 & 4 & 3 & 1 & 2 & 5 & 5 \\ \hline
6 & 3 & 4 & 2 & 1 & 6 & 6	\\ \hline
\end{tabular}
$$	
Then $X$ is isomorphic to the subquandle of $\Conj(\Sigma_4)$ consisting of all 4-cycles. It has been proved in \cite[Example 7.5]{MR1825963} that $\Ho^{\rm Q}_3(X; \mathbb{Z}) \cong \mathbb{ Z}_{24}$.
\end{example}
