\section{Homology of Alexander quandles}

Recall that, an Alexander quandle is a $\mathbb{Z}[t, t^{-1}]$-module $X$ with the quandle operation $x* y = tx + (1- t)y$ for all $x, y \in X$.  Since $X$ is a $\mathbb{Z}[t, t^{-1}]$-module, it is a $\mathbb{Z}$-module, and hence we can consider its tensor product $X \otimes_{\mathbb{Z}} X$ and the exterior product $X\wedge_{\mathbb{Z}} X$. In \cite{MR4065999}, a connection was established between the second quandle homology of quandles and the Schur multipliers of suitable associated groups. Further, a description of the second quandle homology of some Alexander quandles was also given \cite[Theorem 4.1]{MR4065999}\label{prob1}. 

\begin{theorem} 
Let $X$ be an Alexander quandle such that $1-t$ invertible. Then the map $\mathbb{Z} ^{ X \times X}  \to X \otimes_{\mathbb{Z}} X$, given by $(x,y) \mapsto x \otimes (1-t)y$, gives an isomorphism 
\begin{equation*}\label{abc2} \Ho_2^{\rm Q}(X;\mathbb{Z}) \cong
X\otimes_{\mathbb{Z}} X / \langle x \otimes y - y \otimes t x \mid x,y \in X \rangle.
\end{equation*}	
\end{theorem}

Note that, the map $ X \otimes_{\mathbb{Z}} X \rightarrow X \otimes_{\mathbb{Z}} X$ given by  $x \otimes y \mapsto x \otimes (1-t)y$ induces an isomorphism
$$
X\otimes_{\mathbb{Z}} X / \langle x \otimes y - y \otimes t x \mid x,y \in X \rangle \longrightarrow X\wedge_{\mathbb{Z}} X /
  \langle x \wedge y - tx \wedge ty \mid x,y \in X \rangle.
$$
In fact, its inverse is induced by the map $ X \otimes_{\mathbb{Z}} X \rightarrow X \otimes_{\mathbb{Z}} X$ given by $x \otimes y \mapsto x \otimes (1-t)^{-1}y$.  This leads to the following result \cite[Corollary 4.3] {MR4065999}.

\begin{corollary} \label{prob7}
Let $X$ be an Alexander quandle such that $1-t$ invertible. Then there is an isomorphism
	\begin{equation*}\label{abc} \Ho_2^{\rm Q}(X;\mathbb{Z}) \cong X\wedge_{\mathbb{Z}} X / \langle x \wedge y - tx \wedge ty  \mid x,y \in X \rangle. 
	\end{equation*}
\end{corollary}

The preceding result is used to compute the second homology of the Alexander quandle $\mathbb{F}_p [t]/(1+t+ \dots +t^{n-1})$, where $p$ is a prime  \cite[Proposition 4.6] {MR4065999}.


\begin{proposition}\label{prob5} 
Let $p$ be a prime and $n > 2$ an integer such that $\gcd(n, p)=1$.	Let $X$ be the Alexander quandle $\mathbb{F}_p [t]/(1+t+ \dots +t^{n-1})$. Then there is an isomorphism
	\begin{equation*}\label{abc34} \Ho_2^{\rm Q}(X;\mathbb{Z}) \cong (\mathbb{Z}_p)^{ \lfloor \frac{n-1}{2}\rfloor } .
	\end{equation*}
\end{proposition}

The next result gives computations of some higher homology groups \cite[Example 13(ii)]{MR2673749}.

\begin{proposition}
Let $X = \mathbb{Z}_2[t]/(1+t+t^2)$ be the four element Alexander quandle. Then the following assertions hold:
$$ \Ho^{\rm Q}_2(X) \cong \mathbb{Z}_2, \;\; \quad \quad \quad 	\Ho^{\rm Q}_3(X) \cong \mathbb{Z}_2\oplus \mathbb{Z}_4, \quad \Ho^{\rm Q}_4(X) \cong \mathbb{Z}_2^{2}\oplus \mathbb{Z}_4,$$
$$\Ho^{\rm Q}_5(X) \cong \mathbb{Z}_2^{5}\oplus \mathbb{Z}_4, \quad \Ho^{\rm Q}_6(X) \cong \mathbb{Z}_2^{9}\oplus \mathbb{Z}_4^{2}, \quad 	\Ho^{\rm Q}_7(X) \cong \mathbb{Z}_2^{17}\oplus \mathbb{Z}_4^{3}.
$$
\end{proposition}

The preceding computations lead to the following conjecture \cite[Example 13(ii)]{MR2673749}.

\begin{conjecture}
The torsion subgroup of $\Ho^{\rm Q}_n \big(\mathbb{Z}_2[t]/(1+t+t^2) \big)$ is isomorphic  to $\mathbb{Z}_4^{f_n} \oplus \mathbb{Z}_2^{f'_n}$, where 
$\{f_n\}_{n \ge 1}$  is the sequence of delayed Fibonacci numbers and 
$$f'_n = \log_2 \big(| \Tor \Ho_n^{\rm Q}(\mathbb{Z}_2[t]/(1+t+t^2))| \big) -2f_n.$$ 
\end{conjecture}


It is well-known \cite{MR1848966} that any  connected quandle of order a prime $p$ is isomorphic to one of the Alexander quandles defined on $X=\mathbb{Z}_p$ with the quandle operation given by $$x*y=\omega x+(1-\omega)y,$$ where $\omega \neq 0,1$.  Nosaka computed the integral quandle homology of Alexander quandles of prime orders \cite[Theorem 2.1]{MR3042590}.

\begin{theorem}\label{Nosaka result on alexander quandles} 
Let $X=\mathbb{ Z}_p$ be the Alexander quandle of order $p$ with quandle operation $x*y=\omega x+(1-\omega)y,$ where $\omega \neq 0,1$.  Then
	$$\Ho^{\rm Q}_1(X) \cong \mathbb{ Z} \oplus \mathbb{ Z}_p^{b_1} \quad  \textrm{and} \quad \Ho^{\rm Q}_n(X) \cong  \mathbb{ Z}_p^{b_n}\quad  \textrm{for each} \quad n \geq 2,$$  where $b_{n+2e}=b_n+b_{n+1} + b_{n+2}$,  $b_1=b_2=\cdots =b_{2e-2}=0$,  $b_{2e-1}=b_{2e}=1$ and $e>0$ is the minimal integer satisfying $\omega^e=1$.  
\end{theorem} 

As an interesting consequence of Theorem \ref{Nosaka result on alexander quandles}, we have the following result, which was originally conjectured by Niebrzydowski and Przytycki  \cite[Conjecture 5]{MR2494367}.

\begin{corollary}
If $p$ is an odd prime and $\R_p$ is the dihedral quandle of order $p$. Then the torsion subgroup of $\Ho^{\rm Q}_n(\R_p)$ is isomorphic to $ \mathbb{Z}_p^{f_n}$, where $\{f_n\}_{n \ge 1}$ is the sequence of delayed Fibonacci numbers given by $$f_1=f_2=0, ~f_3=1 \quad \textrm{and} \quad f_n = f_{n-1} + f_{n-3}~\textrm{for}~ n \ge 4.$$
\end{corollary}

As another consequence of Theorem \ref{Nosaka result on alexander quandles}, we have  the following result \cite[Corollary 2.3]{MR3042590}.

\begin{corollary} 
Let $X=\mathbb{ Z}_p$ be the Alexander quandle of order $p$ with quandle operation $x*y=\omega x+(1-\omega)y,$ where $\omega \neq -1,0,1$. Then $\Ho^{\rm Q}_n(X)$ is trivial for $n=2,3,4$.
\end{corollary}
\para


In \cite{MR2988494},  Kabaya presented a construction of quandle cocycles derived from group cocycles. For an integer $p \geq 3$, he obtained quandle cocycles of the dihedral quandle $\R_p$ from group cocycles of the cyclic group $\mathbb{Z}_p$. In particular, it was shown  that a group 3-cocycle of $\mathbb{Z}_p$ gives rise to a non-trivial quandle 3-cocycle of $\R_p$.  By Theorem \ref{Mochizuki theorem on third homology}, for an odd prime $p$, the cohomology group $\Ho_{\rm Q}^3(\R_p; \mathbb{ Z}_p)$ is one-dimensional. Hence, this quandle $3$-cocycle is a constant multiple of the Mochizuki 3-cocycle up to a coboundary. Below we review Kabaya's construction.
\para

 For a group $G$ and a $G$-module $A$, we denote the homology and cohomology of $G$ with coefficients in $A$ by $\Ho_n^{\rm{Grp}} (G;A)$ and $\Ho^n_{\rm{Grp}}(G;A)$, respectively. Let $G$ be the cyclic group $\mathbb{Z}_p$, where $p >2$ is an integer not necessarily a prime. The first cohomology group $\Ho^1_{\rm{Grp}}(G; \mathbb{Z}_p) = \Hom_{\mathcal{G}} (\mathbb{Z}_p, \mathbb{Z}_p)$ is generated by the group 1-cocycle $b_1$ given by
$$
b_1(x) = x.
$$
The connecting homomorphism $\delta \colon \Ho^1_{\rm{Grp}}(G; \mathbb{Z}_p) \to \Ho^2_{\rm{Grp}}(G; \mathbb{Z})$ of the long exact sequence of cohomology groups corresponding to the short exact sequence $$1 \to \mathbb{Z} \to \mathbb{Z} \to \mathbb{Z}_p \to 1$$ maps $b_1$ to a generator of $\Ho^2_{\rm{Grp}}(G; \mathbb{Z})$. Further,  the homomorphism $\Ho^2_{\rm{Grp}}(G; \mathbb{Z}) \to  \Ho^2_{\rm{Grp}}(G; \mathbb{Z}_p)$ induced by the natural projection $\mathbb{Z} \to \mathbb{Z}_p $,  maps it to a generator $b_2$ of $\Ho^2_{\rm{Grp}}(G; \mathbb{Z}_p)$. More explicitly, we have
\begin{equation*}
	\label{eq:2_cocycle_of_cyclic_group}
	b_2(x,y) = \frac{1}{p} \big(\overline{x}+\overline{y} - \overline{x+y} \big)
	=
	\left\{ 
	\begin{array}{ll}
		1 & \textrm{if $\overline{x}+\overline{y} \geq p$,} \\  
		0 & \textrm{otherwise,}
	\end{array} \right. 
\end{equation*}
where $\overline{x}$ is an integer $0 \leq \overline{x} < p$ such that $\overline{x} \equiv x \mod p$. When $p$ is an odd prime, it is known that  any element of $\Ho^m_{\rm{Grp}}(G; \mathbb{Z}_p)$ can be presented by a cup product of $b_1$'s and $b_2$'s \cite[Proposition 3.5.5]{MR1110581}. 
\para


For an integer $p > 2$, let $f$ be a normalized group $k$-cocycle representing an element of $\Ho^k_{\rm{Grp}}(G; \mathbb{Z}_p)$. Viewing $\R_p$ as $\mathbb{Z}_p$, 
we obtain a map $f \colon (\R_p)^{k+1} \to \mathbb{Z}_p$ satisfying the following conditions:
\begin{enumerate}
	\item[(1)] $\displaystyle\sum_{i=0}^{k+1} (-1)^i f(x_0, \dots, \widehat{x_i}, \dots ,x_{k+1}) = 0$.
	\item[(2)] $f(x_0, \dots , x_{k} ) = 0$ if $x_i=x_{i+1}$ for some $i$.
\end{enumerate}
If $f$ also satisfies the condition 
\begin{enumerate}
	\item[(3)] $f(x_0 * y, \dots, x_k * y) =  f(x_0, \dots, x_k)$ for any $y \in \R_p$,
\end{enumerate}
then $f$ gives rise to a quandle cohomology class in $\Ho_{\rm Q}^k(\R_p; \mathbb{Z}_p)$.  Define $\tilde{f}: (\R_p)^{k+1} \to \mathbb{Z}_p$ by
$$	\tilde{f}(x_0, \dots, x_k) = f(x_0, \dots, x_k) + f(-x_0,\dots ,-x_k).
$$
Then the map $\tilde{f}$ satisfies conditions (1), (2) and (3), and hence is a quandle $k$-cocycle. We use this construction to give an explicit presentation of the quandle $3$-cocycle arising from $b_1 b_2 \in \Ho^3_{\rm{Grp}}(G; \mathbb{Z}_p)$. We define
$$d(x,y)= b_2(x,y) - b_2(-x,-y).  $$
By the preceding construction, $d$ is a quandle 2-cocycle. By definition, we have
$$	d(-x,-y) = -d(x,y)$$
and 
$$
	d(x,y) =  \left\{ 
	\begin{array}{ll}
		1  & ~\textrm{if}~~ \overline{x} + \overline{y} > p, \\  
		-1 & ~\textrm{if}~~ \overline{x} + \overline{y} < p,~x \neq 0~ \textrm{and}~y \neq 0, \\
		0  & ~\textrm{otherwise}. \\
	\end{array} \right. 
$$

The preceding discussion leads to the following result \cite[Proposition 7.1]{MR2988494}.

\begin{proposition}
The quandle $3$-cocycle arising from $b_1 b_2 \in \Ho_{\rm{Grp}}^3(G; \mathbb{Z}_p)$ has the form
	\begin{equation}
		\label{eq:the_cocycle}
		(x,y,z) \mapsto 2z \big(d(y-x,z-y) + d(y-x,y-z) \big)
	\end{equation}
for all $x,y,z \in \R_p$. Further, it gives a non-trivial cohomology class in  $\Ho^3_{\rm Q}(\R_p; \mathbb{Z}_p)$.

\end{proposition}

Since 2 is divisible in $\mathbb{Z}_p$ when $p$ is odd, we have the following result \cite[Corollary 7.3]{MR2988494}.

\begin{corollary}
If $p > 2$ is an odd integer, then the map $\R_p \times \R_p \times \R_p \to \mathbb{Z}_p$, defined by
	\begin{equation*}
		(x,y,z) \mapsto z \big(d(y-x,z-y) + d(y-x,y-z) \big),
	\end{equation*}
gives a non-trivial cohomology class in  $\Ho^3_{\rm Q}(\R_p; \mathbb{Z}_p)$.
\end{corollary}

