\chapter{Automorphism groups, second cohomology and extensions of quandles}\label{chap cohomology of quandles}

\begin{quote}
This chapter introduces a precise four-term exact sequence that links quandle 1-cocycles, second quandle cohomology, and a particular group of automorphisms arising from an abelian extension of quandles. We examine quandle extensions that originate from group extensions. Additionally, we develop natural group homomorphisms connecting the second cohomology of a group to that of its associated core and conjugation quandles, revealing deeper structural relationships among these objects.
\end{quote}
\bigskip

\section{Action of automorphism groups on dynamical 2-cocycles}\label{Action of automorphisms on dynamical 2-cocycles}

In \cite{MR1994219}, Andruskiewitsch and Gra\~{n}a considered a special case of Proposition \ref{set-cocycle} when $X$ is a quandle and $\beta_{s, t}(x, y)=x*y$ for all $x, y \in X$ and $s, t \in S$. In this case, the map $\alpha$ satisfies the
conditions
\begin{equation}\label{dynamical-cocycle-condition1}
\alpha_{x, x}(s, s)=s,
\end{equation}
\begin{equation}\label{dynamical-cocycle-condition2}
\alpha_{x, y}(-, t): S \to S~\textrm{is a bijection}
\end{equation}
and the  {\it cocycle condition}
\begin{equation}\label{dynamical-cocycle-condition3}
\alpha_{x*y, z}\big(\alpha_{x, y}(s, t), ~u \big)= \alpha_{x* z, y*z}\big(\alpha_{x, z}(s, u),\, \alpha_{y, z}(t, u) \big)
\end{equation}
for all $x, y \in X$ and $s, t \in S$. Such an $\alpha$ is referred to as a {\it dynamical 2-cocycle}. Further, in this case, the quandle operation \eqref{genralised-quandle-operation}  on $X \times S$ becomes 
\begin{equation}\label{dynamical-quandle-operation1}
(x, s)* (y,t)= \big( x* y, \,\alpha_{x, y}(s, t) \big).
\end{equation} 
The quandle so obtained is called an  {\it extension} of $X$ by $S$ through $\alpha$, and is denoted by $X \times_{\alpha} S$. It is easy to see that, for each $x \in X$, the set $S$ forms a quandle with the binary operation $$s *_x t :=\alpha_{x,x}(s,t)$$ for all $s, t \in S$.
\para 


Let $X$ be a quandle, $\Sigma_S$ the symmetric group on a set $S$ and $\mathcal{Z}^2_{\rm Q}(X; S)$ the set of all dynamical 2-cocycles. For $(\phi, \theta) \in \Aut(X) \times \Sigma_S$ and a dynamical 2-cocycle $\alpha \in \mathcal{Z}^2_{\rm Q}(X; S)$, define $$^{(\phi, \theta)}\alpha:X \times X \to \Map(S \times S, S)$$ by setting
\begin{equation}\label{auto-action}
^{(\phi, \theta)}\alpha_{x, y}(s, t):= \theta \Big(\alpha_{\phi^{-1}(x), \phi^{-1}(y)}\big(\theta^{-1}(s), ~\theta^{-1}(t)\big)  \Big)
\end{equation}
for $x, y \in X$ and $s, t \in S$.

\begin{lemma}\label{aut action on cocycles}
The map $\big(\Aut(X) \times \Sigma_S\big) \times \mathcal{Z}^2_{\rm Q}(X; S) \to \mathcal{Z}^2_{\rm Q}(X; S)$ given by
$$\big(( \phi, \theta), \alpha\big) \mapsto~ ^{(\phi, \theta)}\alpha$$ defines a left-action of the group $\Aut(X) \times \Sigma_S$ on the set $\mathcal{Z}^2_{\rm Q}(X; S)$.
\end{lemma}
\begin{proof} 
Let $(\phi, \theta) \in \Aut(X) \times \Sigma_S$ and $\alpha \in \mathcal{Z}^2_{\rm Q}(X; S)$ a dynamical 2-cocycle. We first prove that $^{(\phi, \theta)}\alpha$ is a dynamical 2-cocycle. For $x, y \in X$ and $s, t \in S$, we see that
\begin{eqnarray*}
&  & ^{(\phi, \theta)}\alpha_{x*y, z}\Big(^{(\phi, \theta)}\alpha_{x, y}(s, t), u \Big) \\
& = & \theta \Big(\alpha_{\phi^{-1}(x)*\phi^{-1}(y), ~\phi^{-1}(z)}\Big(\theta^{-1}\big(^{(\phi, \theta)}\alpha_{x, y}(s, t)\big),~ \theta^{-1}(u)\Big)  \Big)\\
& = & \theta \Big(\alpha_{\phi^{-1}(x)*\phi^{-1}(y), ~\phi^{-1}(z)}\Big(\alpha_{\phi^{-1}(x), ~\phi^{-1}(y)}\big(\theta^{-1}(s),~ \theta^{-1}(t)\big),~ \theta^{-1}(u)\Big)  \Big)\\
& = & \theta \Big( \alpha_{\phi^{-1}(x)* \phi^{-1}(z),~ \phi^{-1}(y)*\phi^{-1}(z)}\Big(\alpha_{\phi^{-1}(x),~ \phi^{-1}(z)} \big(\theta^{-1}(s), ~\theta^{-1}(u)\big), ~\alpha_{\phi^{-1}(y), ~\phi^{-1}(z)}\big(\theta^{-1}(t), ~\theta^{-1}(u)\big) \Big) \Big)\\
& & \textrm{by the cocycle condition \eqref{dynamical-cocycle-condition3} for}~\alpha \\
& = & \theta \Big( \alpha_{\phi^{-1}(x*z), \phi^{-1}(y*z)}\Big(\alpha_{\phi^{-1}(x), ~\phi^{-1}(z)}\big(\theta^{-1}(s),~ \theta^{-1}(u)\big),~ \alpha_{\phi^{-1}(y), ~\phi^{-1}(z)}\big(\theta^{-1}(t),~ \theta^{-1}(u)\big) \Big) \Big)\\
& = & ^{(\phi, \theta)}\alpha_{x* z, y*z}\Big(^{(\phi, \theta)}\alpha_{x, z}(s, u),~~ ^{(\phi, \theta)}\alpha_{y, z}(t, u) \Big),
\end{eqnarray*}
and hence $^{(\phi, \theta)}\alpha$ satisfies \eqref{dynamical-cocycle-condition3}. A direct check shows that $ ^{(\phi, \theta)}\alpha$ satisfy \eqref{dynamical-cocycle-condition1} and \eqref{dynamical-cocycle-condition2}, which shows that $ ^{(\phi, \theta)}\alpha \in \mathcal{Z}^2_{\rm Q}(X; S)$.
\para

Given $(\phi_1, \theta_1), (\phi_2, \theta_2) \in \Aut(X) \times \Sigma_S$, we see that
\begin{eqnarray*}
^{(\phi_1, \theta_1)(\phi_2, \theta_2)}\alpha_{x, y}(s, t) & = & ^{(\phi_1\phi_2, ~\theta_1\theta_2)}\alpha_{x, y}(s, t) \\
& = & \theta_1\theta_2 \Big(\alpha_{\phi_2^{-1}\phi_1^{-1}(x), ~\phi_2^{-1}\phi_1^{-1}(y)}\big(\theta_2^{-1}\theta_1^{-1}(s), ~\theta_2^{-1}\theta_1^{-1}(t)\big)  \Big)\\
& = & \theta_1 \Big( ^{(\phi_2, \theta_2)}\alpha_{\phi_1^{-1}(x), ~\phi_1^{-1}(y)}\big(\theta_1^{-1}(s),~ \theta_1^{-1}(t)\big) \Big)\\
& = & ^{(\phi_1, \theta_1)}\big(^{(\phi_2, \theta_2)}\alpha\big)_{x, y}(s, t),
\end{eqnarray*}
and hence the group $\Aut(X) \times \Sigma_S$ acts on $\mathcal{Z}^2_{\rm Q}(X; S)$ from the left. 
$\blacksquare$    \end{proof}          

Two dynamical 2-cocycles $\alpha, \beta \in \mathcal{Z}^2_{\rm Q}(X; S)$ are said to be {\it cohomologous } if there exists a map $\lambda:X \to \Sigma_S$ such that
\begin{equation}\label{cohomologous}
\beta_{x, y}(s, t)=\lambda_{x*y} \Big(\alpha_{x, y}\big(\lambda_x^{-1}(s),~ \lambda_y^{-1}(t) \big)\Big)
\end{equation}
for all $x, y \in X$ and $s, t \in S$. Clearly, being cohomologous is an equivalence relation on $\mathcal{Z}^2_{\rm Q}(X; S)$, and let $\mathcal{H}^2_{\rm Q}(X; S)$ denote the set of cohomology classes of dynamical 2-cocycles. For $\alpha \in \mathcal{Z}^2_{\rm Q}(X; S)$, we denote its equivalence class  by $[\alpha]  \in \mathcal{H}^2_{\rm Q}(X; S)$.

\begin{proposition} \cite[Proposition 4.2]{MR4282648}
The map $\big(\Aut(X) \times \Sigma_S\big) \times \mathcal{H}^2_{\rm Q}(X; S) \to \mathcal{H}^2_{\rm Q}(X; S)$ given by
$$\big(( \phi, \theta), [\alpha] \big) \mapsto~ [^{(\phi, \theta)}\alpha]$$ defines a left-action of the group $\Aut(X) \times \Sigma_S$ on the set $\mathcal{H}^2_{\rm Q}(X; S)$.
\end{proposition}

\begin{proof}
It suffices to prove that cohomologous cocycles are mapped onto cohomologous cocycles under the action in Lemma \ref{aut action on cocycles}. Let $(\phi, \theta) \in \Aut(X) \times \Sigma_S$,  $\alpha, \beta \in \mathcal{Z}^2_{\rm Q}(X; S)$ and $\lambda:X \to \Sigma_S$ such that equation \eqref{cohomologous} is satisfied. Define a map $\lambda':X \to \Sigma_S$ by setting $\lambda'_x= \theta \lambda_{\phi^{-1}(x)} \theta^{-1}$ for $x \in X$. Then, for $x, y \in X$ and $s, t \in S$, we see that
\begin{eqnarray*}
&  & ^{(\phi, \theta)}\beta_{x, y}(s, t) \\
& = & \theta \Big(\beta_{\phi^{-1}(x),~ \phi^{-1}(y)}\big(\theta^{-1}(s), ~~\theta^{-1}(t)\big)  \Big)\\ 
& = & \theta \Big(\lambda_{\phi^{-1}(x)* \phi^{-1}(y)} \Big(\alpha_{\phi^{-1}(x), ~\phi^{-1}(y)} \Big( \lambda_{\phi^{-1}(x)}^{-1}\big(\theta^{-1}(s) \big), ~~\lambda_{\phi^{-1}(y)}^{-1}\big(\theta^{-1}(t) \big) \Big) \Big) \Big),~ \textrm{by using}~ \eqref{cohomologous}\\
& = & \theta \Big(\lambda_{\phi^{-1}(x*y)} \Big(\alpha_{\phi^{-1}(x),~ \phi^{-1}(y)} \Big( \lambda_{\phi^{-1}(x)}^{-1}\theta^{-1}(s), ~~\lambda_{\phi^{-1}(y)}^{-1}\theta^{-1}(t) \Big) \Big) \Big)\\
& = & \Big( \theta \lambda_{\phi^{-1}(x*y)} \theta^{-1} \Big) \theta \Big(\alpha_{\phi^{-1}(x),~ \phi^{-1}(y)} \Big( \theta^{-1} (\theta \lambda_{\phi^{-1}(x)}\theta^{-1})^{-1}(s), ~~\theta^{-1}(\theta \lambda_{\phi^{-1}(y)}\theta^{-1})^{-1}(t)  \Big) \Big)\\  
& = & \lambda'_{x*y} ~ \theta \Big(\alpha_{\phi^{-1}(x), ~\phi^{-1}(y)} \Big( \theta^{-1} {\lambda'_x}^{-1}(s), ~~\theta^{-1}{\lambda'}_y^{-1}(t)  \Big) \Big)\\  
& = & \lambda'_{x*y}  ~ \Big(^{(\phi, \theta)}\alpha_{x, y} \Big({\lambda'_x}^{-1}(s), ~~{\lambda'_y}^{-1}(t)  \Big) \Big),  
\end{eqnarray*}
and hence $[^{(\phi, \theta)}\alpha]=[^{(\phi, \theta)}\beta]$.
$\blacksquare$    \end{proof}          

\begin{remark}\label{dynamical to ordinary cocycle}
{\rm 
Let $X$ be a quandle, $S=A$ a group (not necessarily abelian), and $\alpha: X \times X \to A$ a map. Then the map $\alpha': X \times X \to \Map(A \times A, A)$ given by $$\alpha'_{x, y}(s, t)= s ~\alpha_{x, y},$$ where $x, y \in X$ and $s, t \in A$, satisfy \eqref{dynamical-cocycle-condition1} and \eqref{dynamical-cocycle-condition3} if and only if $\alpha$ satisfy
\begin{equation}\label{group-coefficient-cocycle-condition1}
\alpha_{x, y}~\alpha_{x*y, z}= \alpha_{x, z}~\alpha_{x* z, y*z}
\end{equation}
and 
\begin{equation}\label{normalised-cocycle-condition}
\alpha_{x, x}=1
\end{equation}
for $x, y, z \in X$. If $A$ is abelian, then \eqref{group-coefficient-cocycle-condition1} is the cocycle condition defining the usual second quandle cohomology $\Ho^2_{\rm Q}(X; A)$ (see Section \ref{Homology} of Chapter  \ref{chapter homology YBE}).}
\end{remark}
\bigskip
\bigskip

