\section{Wells-type exact sequence for dynamical extensions of quandles}\label{Wells-type exact sequence via dynamical cohomology}
Let $X$ be a quandle, $S$ a set, $\alpha\in \mathcal{Z}^2_{\rm Q}(X; S)$ a dynamical 2-cocycle and $E=X \times_\alpha S$ the extension of $X$ by $S$  through $\alpha$.  Fixing a base point $x_0 \in X$, we define
$$\Aut^{x_0}(X)= \big\{\phi \in \Aut(X) \, \mid \,  \phi(x_0)=x_0 \big\},$$ 
and 
\begin{small}
$$\Aut^{x_0}_S(E)=\Big\{ \psi \in \Aut(E) \, \mid \, \psi(x, s)=\big(\phi(x),~ \tau(x, s)\big)~\textrm{for some}~\phi \in \Aut^{x_0}(X)~\textrm{and}~\tau \in \Map(X \times S, S) \Big\}.$$
\end{small}

For $x \in X$ and $s \in S$, we denote $\tau(x, s)$ by $\tau_x(s)$.

\begin{lemma}
The following  assertions hold:
\begin{enumerate}
\item If $\psi \in \Aut(E)$ such that $\psi(x, s)=\big(\phi(x), \tau_x(s)\big)$, then $\tau_x \in \Sigma_S$.
\item $\Aut^{x_0}_S(E)$ is a subgroup of $\Aut(E)$.
\end{enumerate}
\end{lemma}

\begin{proof}
Assertion (1) follows from the bijectivity of $\psi$. For assertion (2), let $\psi \in \Aut^{x_0}_S(E)$ such that $\psi(x, s)=\big(\phi(x), \tau_x(s)\big)$ for all $x \in X$ and $s \in S$. Define $\varphi(x,s) = \big(\phi^{-1}(x), ~\tau_{\phi^{-1}(x)}^{-1}(s)\big)$. Since $\phi$ and $\tau_x$ are bijections for all $x \in X$, it follows that $\varphi$ is also a bijection. Further, since $\psi$ is a quandle homomorphism, for $x, y \in X$ and $s, t \in S$, we have
\begin{equation*}
\tau_{x*y}\big(\alpha_{x, y}(s, t)\big)=\alpha_{\phi(x), \phi(y)}\big(\tau_x(s),~ \tau_y(t)\big),
\end{equation*}
which is equivalent to
\begin{equation}\label{useful-in-subgroup}
\alpha_{\phi^{-1}(x), \phi^{-1}(y)} \big(\tau_{\phi^{-1}(x)}^{-1}(s),~ \tau_{\phi^{-1}(y)}^{-1}(t) \big)=\tau_{\phi^{-1}(x*y)}^{-1} \big(\alpha_{x, y}(s,t) \big).
\end{equation}

Now, we compute
\begin{eqnarray*}
\varphi \big( (x, s)*(y, t) \big) &=& \varphi \big(x*y,~ \alpha_{x, y}(s, t) \big)\\
 &=&  \big(\phi^{-1}(x*y), ~\tau_{\phi^{-1}(x*y)}^{-1}\big(\alpha_{x, y}(s, t) \big)\big)\\
  &=&  \big(\phi^{-1}(x)*\phi^{-1}(y), ~\alpha_{\phi^{-1}(x), \phi^{-1}(y)} \big(\tau_{\phi^{-1}(x)}^{-1}(s),~ \tau_{\phi^{-1}(y)}^{-1}(t)\big)\big),~\textrm{by}~\eqref{useful-in-subgroup}\\
  &=&    \big(\phi^{-1}(x), ~\tau_{\phi^{-1}(x)}^{-1}(s)\big)* \big(\phi^{-1}(y), ~\tau_{\phi^{-1}(y)}^{-1}(t)\big)\\
  &=&  \varphi(x,s) * \varphi(y,t).
\end{eqnarray*}
Thus, $\varphi \in \Aut^{x_0}_S(E)$ and a direct check shows that it is the inverse of $\psi$. Further, given $\psi(x, s)=\big(\phi(x), ~\tau_x(s)\big)$ and $\psi'(x, s)=\big(\phi'(x),~ \tau'_x(s)\big)$, we see that
\begin{equation}\label{product-psi}
\psi \psi'(x, s)=\psi \big( \phi'(x), ~\tau'_x(s)\big)=\big(\phi\big( \phi'(x)\big), ~\tau_{\phi'(x)}\big(\tau'_x(s)\big) \big)=\big(\phi \phi'(x), ~\tau_{\phi'(x)}\tau'_x(s) \big),
\end{equation}
and hence $\Aut^{x_0}_S(E)$ is a subgroup of $\Aut(E)$.
$\blacksquare$    \end{proof}          
\medskip

Restricting the action of $\Aut(X) \times \Sigma_S$ to that of its subgroup $\Aut^{x_0}(X) \times \Sigma_S$, let $$\Omega_{[\alpha]}: \Aut^{x_0}(X) \times \Sigma_S \to \mathcal{H}^2_{\rm Q}(X; S)$$ be the orbit map given by 
\begin{equation}\label{wells-map}
\Omega_{[\alpha]}(\phi, \theta)= ~^{(\phi, \theta)}[\alpha].
\end{equation}
For ease of notation, we denote  $\Omega_{[\alpha]}$ by $\Omega$. Further, let $$\Phi: \Aut^{x_0}_S(E) \to \Aut^{x_0}(X) \times \Sigma_S$$ be the restriction map given by 
\begin{equation}\label{restriction-map}
\Phi(\psi)= ~(\phi, \theta),
\end{equation} 
where $\psi(x, s)=\big(\phi(x),~ \tau_x(s)\big)$ and $\theta(s):=\tau_{x_0}(s)$ for all $x \in X$ and $s \in S$.  Define a map $\lambda:X \to \Sigma_S$ by setting $$\lambda_x:= \theta\tau_{\phi^{-1}(x)}^{-1}.$$ 
Note that $\lambda_{x_0}=\id_S$ and $\tau_x$ can be uniquely written as 
 \begin{equation}\label{expression-tau}
 \tau_x=(\tau_x \theta^{-1}) \theta=\lambda_{\phi(x)}^{-1}\theta
\end{equation}
for all $x \in X$. With this set-up, we prove the following result.

\begin{proposition}\label{image of phi equals kernel of Omega}
The map $\Phi$ is a group homomorphism and $\im(\Phi)=\Omega^{-1}\big([\alpha]\big)$.
\end{proposition}

\begin{proof}
If $\psi, \psi' \in \Aut^{x_0}_S(E)$, then by \eqref{product-psi}, we obtain 
$$\psi \psi'(x, s)=\big(\phi \phi'(x), ~\tau_{\phi'(x)}\tau'_x(s) \big),$$
where $\tau_{\phi'(x_0)}\tau'_{x_0}(s)=\tau_{x_0}\tau'_{x_0}(s)=\theta \theta'(s)$. This shows that $\Phi(\psi \psi' )=\Phi(\psi)\Phi(\psi' )$, that is, $\Phi$ is a homomorphism. Note that $$\Omega^{-1}\big([\alpha]\big)= \big( \Aut^{x_0}(X) \times \Sigma_S \big)_{[\alpha]},$$ the stabilizer of the action of $\Aut^{x_0}(X) \times \Sigma_S$ at $[\alpha]$. Let $\psi \in \Aut^{x_0}_S(E)$ such that $\Phi (\psi)= (\phi, \theta)$. Since $\psi$ is a quandle homomorphism, for $x, y \in X$ and $s, t \in S$, we have
\begin{equation}\label{ext-homo-condition1}
\tau_{x*y}\big(\alpha_{x, y}(s, t)\big)=\alpha_{\phi(x), \phi(y)}\big(\tau_x(s),~ \tau_y(t)\big).
\end{equation}
Further, since $\phi \in \Aut^{x_0}(X)$ and $\theta \in \Sigma_S$, we can replace $x, y$ by $\phi^{-1}(x),\phi^{-1}(y)$ and $s, t$ by $\theta^{-1}(s),\theta^{-1}(t)$, respectively,  in \eqref{ext-homo-condition1}. This gives
\begin{equation}\label{ext-homo-condition2}
\tau_{\phi^{-1}(x*y)}\Big(\alpha_{\phi^{-1}(x), \phi^{-1}(y)}\big(\theta^{-1}(s), ~\theta^{-1}(t)\big)\Big)=\alpha_{x, y}\Big(\tau_{\phi^{-1}(x)}\big(\theta^{-1}(s)\big), ~\tau_{\phi^{-1}(y)}\big(\theta^{-1}(t)\big)\Big).
\end{equation}
Define a map $\lambda: X \to \Sigma_S$ by setting $\lambda_x:=\theta \tau^{-1}_{\phi^{-1}(x)}$. Then, equation \eqref{ext-homo-condition2} takes the form
\begin{equation}\label{ext-homo-condition3}
\lambda_{x*y}^{-1} ~\theta \Big(\alpha_{\phi^{-1}(x), ~\phi^{-1}(y)}\big(\theta^{-1}(s), ~\theta^{-1}(t)\big)\Big)=\alpha_{x, y}\big(\lambda_x^{-1}(s), ~\lambda_y^{-1}(t) \big),
\end{equation}
which is further equivalent to
\begin{equation}\label{ext-homo-condition4}
^{(\phi, \theta)}\alpha_{x, y}(s, t)=\theta \Big(\alpha_{\phi^{-1}(x), ~\phi^{-1}(y)}\big(\theta^{-1}(s), ~\theta^{-1}(t)\big)\Big)= \lambda_{x*y} \Big(\alpha_{x, y}\big(\lambda_x^{-1}(s), ~\lambda_y^{-1}(t) \big) \Big).
\end{equation}
This shows that $\im(\Phi)\subseteq \big( \Aut^{x_0}(X) \times \Sigma_S \big)_{[\alpha]}$.
\para
For the converse, let $(\phi, \theta) \in \big( \Aut^{x_0}(X) \times \Sigma_S \big)_{[\alpha]}$. Then, there exists a map $\lambda: X \to \Sigma_S$ such that \eqref{ext-homo-condition4} holds. Define $\psi: E \to E$ by setting
$$\psi(x, s)= \big(\phi(x),~ \lambda_{\phi(x)}^{-1} \theta (s)\big).$$
Since $\phi$ and $\theta$ are bijective, so is $\psi$. By replacing $x, y$ by $\phi(x),\phi(y)$ and $s, t$ by $\theta(s),\theta(t)$, respectively, in \eqref{ext-homo-condition4}, we obtain
\begin{equation}\label{ext-homo-condition5}
\lambda_{\phi(x)*\phi(y)}^{-1}~\theta \big(\alpha_{x, y}(s, ~t)\big)=  \alpha_{\phi(x), \phi(y)}\big(\lambda_{\phi(x)}^{-1}\theta(s), ~\lambda_{\phi(y)}^{-1}\theta(t) \big).
\end{equation}
Now, we compute
\begin{eqnarray*}
\psi \big((x, s)*(y, t) \big) & = & \psi \big(x*y, ~\alpha_{x, y}(s, t) \big) \\
&  =&  \Big(\phi(x)*\phi(y), ~\lambda_{\phi(x)*\phi(y)}^{-1} \theta \big(\alpha_{x, y}(s, t)\big) \Big) \\
&  =&  \Big(\phi(x)*\phi(y), ~\alpha_{\phi(x), \phi(y)}\big(\lambda_{\phi(x)}^{-1}\theta(s), ~\lambda_{\phi(y)}^{-1}\theta(t) \big) \Big),~ \textrm{by}~\eqref{ext-homo-condition5}\\
&  =&  \big(\phi(x), ~\lambda_{\phi(x)}^{-1}\theta(s) \big)* \big(\phi(y), ~\lambda_{\phi(y)}^{-1}\theta(t) \big)\\ 
&  =& \psi (x, s)*\psi (y, t).
\end{eqnarray*}
Thus, $\psi \in\Aut^{x_0}_S(E)$ and $\Phi(\psi)=(\phi, \theta)$, which completes the proof of the proposition.
$\blacksquare$    \end{proof}          

\begin{proposition}\label{kernel Phi description}
$\ker(\Phi) \cong \Big\{\lambda: X \to \Sigma_S \, \mid \, \lambda_{x_0}=\id_S~\textrm{and}~\alpha_{x, y}(s, t)=\lambda_{x*y} \big(\alpha_{x, y}\big(\lambda_x^{-1}(s),\lambda_y^{-1}(t)\big)\big) \Big\}$.
\end{proposition}
\begin{proof}
Note that $\psi \in \ker(\Phi)$ if and only if $\Phi(\psi)=(\id_X, \id_S)$. In view of \eqref{expression-tau}, we have $$\psi(x, s)=\big(x, \lambda_x^{-1}(s)\big),$$ and $\lambda_{x_0}=\id_S$. Further, by \eqref{ext-homo-condition1}, $\psi$ is a quandle homomorphism if and only if $$\alpha_{x, y}(s, t)=\lambda_{x*y} \big(\alpha_{x, y}\big(\lambda_x^{-1}(s),\lambda_y^{-1}(t)\big)\big)$$ for all $x, y \in X$ and $s,t \in S$. Thus, $\ker(\Phi)$ is the desired set via the map $\psi \mapsto \lambda$. Here, in view of \eqref{product-psi}, the right hand side is a group with operation $(\lambda\lambda')_x :=\lambda_x \lambda'_x$ for all $x \in X$.
$\blacksquare$    \end{proof}          

Combining propositions \ref{image of phi equals kernel of Omega} and \ref{kernel Phi description}, we obtain the following exact sequence \cite[Theorem 5.4]{MR4282648}, which we refer to  as a Wells-type exact sequence following \cite{MR0272898}.

\begin{theorem}
Let $X$ be a quandle, $x_0 \in X$, $S$ a set, $\alpha\in \mathcal{Z}^2_{\rm Q}(X; S)$ and $E=X \times_\alpha S$ the extension of $X$ by $S$ using $\alpha$. Then there exists an exact sequence
\begin{equation}\label{well-sequence}
1 \longrightarrow \ker(\Phi) \longrightarrow \Aut^{x_0}_S(E) \stackrel{\Phi}{\longrightarrow} \Aut^{x_0}(X) \times \Sigma_S \stackrel{\Omega}{\longrightarrow} \mathcal{H}^2_{\rm Q}(X; S),
\end{equation}
where exactness at $ \Aut^{x_0}(X) \times \Sigma_S$ means that $\im(\Phi)=\Omega^{-1}\big([\alpha]\big)$.
\end{theorem}
\medskip

As a consequence, we obtain the following short exact sequence.

\begin{corollary}
Let $X$ be a quandle, $x_0 \in X$, $S$ a set, $\alpha\in \mathcal{Z}^2_{\rm Q}(X; S)$ and $E=X \times_\alpha S$ the extension of $X$ by $S$ using $\alpha$. Then there exists a short exact sequence of groups
\begin{equation}\label{der-aut-short-exact}
1 \longrightarrow \ker(\Phi) \longrightarrow \Aut^{x_0}_S(E) \stackrel{\Phi}{\longrightarrow} \big(\Aut^{x_0}(X) \times \Sigma_S\big)_{[\alpha]} \longrightarrow 1.
\end{equation}
\end{corollary}
\medskip

It is worthwhile to investigate the conditions under which the short exact sequence \eqref{der-aut-short-exact} splits.

\begin{proposition}
Let $X$ and $S$ be quandles and $x_0 \in X$. If $\alpha \in \mathcal{Z}^2_{\rm Q}(X; S)$ is the 2-cocycle given by $\alpha_{x, y}(s, t)= s*t$ for all $x, y \in X$ and $s, t \in S$, then the short exact  sequence 
\begin{equation}\label{der-aut-short-exact2}
1 \longrightarrow \ker(\Phi) \longrightarrow \Aut^{x_0}_S(E) \stackrel{\Phi}{\longrightarrow} \big(\Aut^{x_0}(X) \times \Aut(S)\big)_{[\alpha]} \longrightarrow 1
\end{equation}
 splits.
\end{proposition}

\begin{proof}
For the given 2-cocycle $\alpha$, the quandle operation \eqref{genralised-quandle-operation} on $E=X \times_\alpha S$ becomes $$(x, s)* (y,t)= (x* y, s* t ),$$ which is just the product quandle structure. Further, in this case, we have
$$\ker(\Phi) \cong \Big\{\lambda: X \to \Aut(S) \, \mid \, \lambda_{x_0}=\id_S~\textrm{and}~\lambda_{x*y}(s*t)=\lambda_x(s) * \lambda_y(t)\Big\}$$
and
$$\Aut^{x_0}_S(E)=\Big\{ \psi \in \Aut(E) \, \mid \, \psi(x, s)=\big(\phi(x),~ \tau_x(s)\big)~\textrm{for some}~\phi \in \Aut^{x_0}(X)~\textrm{and}~\tau: X \to \Aut(S) \Big\}.$$
Now, for any $(\phi, \theta) \in \Aut^{x_0}(X) \times \Aut(S)$, we see that
$$^{(\phi, \theta)}\alpha_{x, y}(s, t)= \theta \Big(\alpha_{\phi^{-1}(x), \phi^{-1}(y)}\big(\theta^{-1}(s), ~\theta^{-1}(t)\big)  \Big)=\theta \big(\theta^{-1}(s)*\theta^{-1}(t)\big)= s*t=\alpha_{x, y}(s, t)$$
for $x, y \in X$ and $s, t \in S$. Thus, we have $\big(\Aut^{x_0}(X) \times \Aut(S) \big)_{[\alpha]}=\Aut^{x_0}(X) \times \Aut(S)$. Define 
$$\xi:  \Aut^{x_0}(X) \times \Aut(S) \to \Aut^{x_0}_S(E)$$ by setting
$\xi(\phi, \theta)=\psi$, where $\psi(x, s)= \big(\phi(x), \theta(s)\big)$ for $x \in X$ and $s \in S$. Then $\xi$ is a group homomorphism with $\Phi \, \xi$ being the identity map, and sequence \eqref{der-aut-short-exact2} splits.
$\blacksquare$    \end{proof}          
\bigskip
\bigskip

