\section{Wells-type exact sequence for quandle cohomology}\label{abelian-quandle-cohomology-section}
Upon specializing to the standard quandle cohomology with coefficients in an abelian group and applying certain appropriate modifications, the exact sequence \eqref{well-sequence} assumes a simpler and more usable form, which we derive in this section. First, we briefly review the quandle cohomology theory presented in Chapter \ref{chapter homology YBE}.
\para

Let $X$ be a quandle and $A$ an abelian group. Let $C_n^{\rm R}(X)$ be the free abelian group generated by $n$-tuples of elements of $X$. Define a homomorphism
$\partial_{n}: C_n^{\rm R}(X) \to C_{n-1}^{\rm R}(X)$ by 

\begin{eqnarray*}
\partial_{n}(x_1, x_2, \dots, x_n)  & = & \sum_{i=2}^{n} (-1)^{i} \big( (x_1, x_2, \dots, x_{i-1}, x_{i+1},\dots,  x_n)\\
& & - (x_1 \ast x_i, x_2 \ast x_i, \dots, x_{i-1}\ast x_i, x_{i+1},x_{i+2},  \dots, x_n) \big)
\end{eqnarray*}
for $n \geq 2$ and $\partial_n=0$ for $n \leq 1$. Then $\{C_n^{\rm R}(X), \partial_n \}$ forms a chain complex. For $n \geq 2$, let $C_n^{\rm D}(X)$ be the free abelian subgroup of $C_n^{\rm R}(X)$ generated by degenerate $n$-tuples $(x_1, \dots, x_n)$ with $x_{i}=x_{i+1}$ for some $1 \le i \le n-1$. Set $C_n^{\rm D}(X)=0$   for $n \leq 1$. It can be checked that if $X$ is a quandle, then $\partial_n\big(C_n^{\rm D}(X)\big) \subseteq C_{n-1}^{\rm R}(X)$. Setting $C_n^{\rm Q}(X) = C_n^{\rm R}(X)/ C_n^{\rm D}(X)$, we see that $\{C_n^{\rm Q}(X), \partial_n \}$ forms a chain complex, where by abuse of notation, $\partial_n$ also denotes the induced homomorphism.  Define $C^n_{\rm Q}(X;A) := \Hom \big(C_n^{\rm Q}(X), A\big)$ and $\delta^n :C^n_{\rm Q}(X;A) \to C^{n+1}_{\rm Q}(X;A)$ given by
$$\delta^n(f)= (-1)^n (f \, \partial_{n+1}).$$ 
This turns $\{C^n_{\rm Q}(X;A), \delta^n \}$ into a cochain complex, and $\Ho^n_{\rm Q}(X;A)$ is the $n$-th quandle cohomology group of  $X$ with coefficients in $A$. We denote the group of $n$-th cocycles and the group of $n$-th coboundaries by  $Z^n_{\rm Q}(X;A)$ and $B^n_{\rm Q}(X;A)$, respectively.
\medskip

Following Remark \ref{dynamical to ordinary cocycle}, we see that $Z^2_{\rm Q}(X;A)$ can be identified with the set of maps $\alpha: X \times X \to A$ satisfying the 2-cocycle conditions \eqref{group-coefficient-cocycle-condition1} and \eqref{normalised-cocycle-condition}. In other words, 
$$\alpha_{x, y}~\alpha_{x*y, z}= \alpha_{x, z}~\alpha_{x* z, y*z}$$
and $$\alpha_{x, x}=1$$
for $x, y, z \in X$.  Further, two 2-cocycles $\alpha, \beta \in Z^2_{\rm Q}(X;A)$ are cohomologous if there exists a 1-cochain $\lambda \in C^1(X;A)$ such that $\beta ~\delta^1 (\lambda)= \alpha $, that is, $$\beta_{x, y}=\lambda_{x*y} \lambda_x^{-1}\alpha_{x, y}$$ for $x, y \in X$. 
\medskip

For $(\phi, \theta) \in \Aut(X) \times \Aut(A)$  and $\alpha \in Z^2_{\rm Q}(X;A)$, we define
\begin{equation}\label{abelian-action}
^{(\phi, \theta)}\alpha_{x, y}:= \theta \big(\alpha_{\phi^{-1}(x), \phi^{-1}(y)}  \big)
\end{equation}
for $x,y \in X$. We prove the following result \cite[Proposition 6.1]{MR4282648}.

\begin{proposition}
The group $\Aut(X) \times \Aut(A)$ acts by automorphisms on $\Ho^2_{\rm Q}(X; A)$ as
$$^{(\phi, \theta)}[\alpha] := [^{(\phi, \theta)}\alpha]$$ 
for $(\phi, \theta) \in \Aut(X) \times \Aut(A)$ and $[\alpha]\in \Ho^2_{\rm Q}(X; A)$.
\end{proposition}

\begin{proof}
Equation  \eqref{abelian-action} defines an action of $\Aut(X) \times \Aut(A)$ on $Z^2_{\rm Q}(X;A)$ follows along the lines of proof of Lemma \ref{aut action on cocycles}. Let $(\phi, \theta) \in \Aut(X) \times \Aut(A)$  and $\alpha, \beta \in Z^2_{\rm Q}(X;A)$. For $x, y \in X$, we see that
\begin{eqnarray*}
^{(\phi, \theta)}(\alpha \beta)_{x, y} &= & \theta \big({(\alpha\beta)}_{\phi^{-1}(x), \phi^{-1}(y)}  \big)\\
&= & \theta \big(\alpha_{\phi^{-1}(x), \phi^{-1}(y)}~\beta_{\phi^{-1}(x), \phi^{-1}(y)}  \big)\\
&= & \theta \big(\alpha_{\phi^{-1}(x), \phi^{-1}(y)}\big) ~ \theta\big(\beta_{\phi^{-1}(x), \phi^{-1}(y)}  \big), ~\textrm{since}~\theta \in \Aut(A)\\
&= &  ^{(\phi, \theta)}\alpha_{x, y} ~^{(\phi, \theta)}\beta_{x, y}\\
&= &  (^{(\phi, \theta)}\alpha ~^{(\phi, \theta)}\beta)_{x, y},
\end{eqnarray*}
and hence the action is by automorphisms. Let $\alpha,\beta \in Z^2_{\rm Q}(X;A)$ be two cohomologous quandle 2-cocycles. Then there exists a map $\lambda:X \to A$ such that $$\beta_{x, y}=\alpha_{x, y}~\lambda_x~ \lambda_{x*y}^{-1}$$
for all $x, y \in X$. If we set $\lambda'_x:=\theta (\lambda_{\phi^{-1}(x)})$, then
\begin{eqnarray*}
^{(\phi, \theta)}\beta_{x, y} &=& \theta \big(\beta_{\phi^{-1}(x), \phi^{-1}(y)}  \big)\\
 &=& \theta \big(\alpha_{\phi^{-1}(x), \phi^{-1}(y)} \lambda_{\phi^{-1}(x)} \lambda_{\phi^{-1}(x*y)}^{-1} \big)\\
 &=& ^{(\phi, \theta)}\alpha _{x, y} ~\theta \big(\lambda_{\phi^{-1}(x)} \big) \theta \big(\lambda_{\phi^{-1}(x*y)}^{-1} \big)\\
 &=& ^{(\phi, \theta)}\alpha _{x, y} ~ \lambda'_x ~{\lambda'_{x*y}}^{-1}
\end{eqnarray*}
for all $x, y \in X$. Thus, the group $\Aut(X) \times \Aut(A)$ acts by automorphisms on  $\Ho^2_{\rm Q}(X; A)$.
$\blacksquare$    
\end{proof}          


Let $X$ be a finite quandle and $A$ a finite abelian group. Let $\alpha: X\times X \to A$ be a quandle 2-cocycle and $\big(\Aut(X) \times \Aut(A)\big)_{[\alpha]}$ the stabilizer of the action of  $\Aut(X) \times \Aut(A)$ at $[\alpha]$. Then the cardinality of the orbit of $[\alpha]$ equals
$$\frac{|\Aut(X) \times \Aut(A)|}{|\big(\Aut(X) \times \Aut(A)\big)_{[\alpha]}|}.$$
This yields the following result.

\begin{corollary}
If $X$ is a finite quandle, $A$ a finite abelian group and $\alpha: X\times X \to A$ a quandle 2-cocycle, then
$$|\Ho^2_{\rm Q}(X; A)| \ge \frac{|\Aut(X) \times \Aut(A)|}{|\big(\Aut(X) \times \Aut(A)\big)_{[\alpha]}|}.$$
\end{corollary}
\medskip


Let $X$ be a quandle and $\alpha\in Z^2_{\rm Q}(X; A)$ a fixed quandle 2-cocycle. Note that the group $\Ho^2_{\rm Q}(X; A)$ acts freely and transitively on itself by left multiplication. For any $(\phi, \theta) \in \Aut(X) \times \Aut(A)$, since $[\alpha]$ and $^{(\phi, \theta)}[\alpha]$ are elements of $\Ho^2_{\rm Q}(X; A)$, there exists a unique element $\Theta_{[\alpha]} (\phi, \theta) \in \Ho^2_{\rm Q}(X; A)$ such that
\begin{equation}\label{abelian-wells-map}
^{\Theta_{[\alpha]}  (\phi, \theta)} \big(^{(\phi, \theta)}[\alpha] \big)= [\alpha].
\end{equation}
This defines a map $$\Theta_{[\alpha]} : \Aut(X) \times \Aut(A) \to \Ho^2_{\rm Q}(X; A).$$ 
For convenience of notation, we denote $\Theta_{[\alpha]}$ by $\Theta$. By Remark \ref{dynamical to ordinary cocycle}, the map $\alpha': X \times X \to \Map(A\times A, A)$ given by $\alpha'_{x, y}(s, t)=s~\alpha_{x, y}$, where $x, y \in X$ and $s, t \in A$,  is a dynamical 2-cocycle. Thus, by Proposition \ref{set-cocycle}, the binary operation
\begin{equation}\label{abelian-extension-operation}
(x, s)*(y, t):=(x*y,~s~\alpha_{x, y})
\end{equation}
defines a quandle $E:= X \times_\alpha A$, called the {\it abelian extension} of $X$ by $A$  through $\alpha$. Next, we define
\begin{small}
$$\Aut_A(E)=\Big\{ \psi \in \Aut(E) \, \mid \, \psi(x, s)=\big(\phi(x),~ \lambda_x\theta(s)\big)~\textrm{for some}~(\phi, \theta) \in \Aut(X)\times \Aut(A)~\textrm{and map}~\lambda:X \to A \Big\}.$$
\end{small}

With the preceding set-up, we have the following result.

\begin{proposition}
Let $X$ be a quandle, $A$ an abelian group and $\alpha\in Z^2_{\rm Q}(X; A)$ a quandle 2-cocycle. If $E$ is the abelian extension of $X$ by $A$ through $\alpha$,  then $\Aut_A(E)$ is a subgroup of $\Aut(E)$.
\end{proposition}

\begin{proof}
Let $\psi \in\Aut_A(E)$ such that $\psi(x, s)=\big(\phi(x),~ \lambda_x\theta(s)\big)$ for $x \in X$ and $s \in A$. Define $\varphi(x,s) := \big(\phi^{-1}(x), ~\theta^{-1} \big(\lambda_{\phi^{-1}(x)}^{-1}s\big)\big)$. Since $\phi$ and $\theta$ are bijections, it follows that $\varphi$ is also a bijection. Further, since $\psi$ is a quandle homomorphism, for $x, y \in X$ and $s, t \in S$, we have
\begin{equation}\label{abelian-homo-condition}
\lambda_{x*y} ~\theta (\alpha_{x, y})=\lambda_x~ \alpha_{\phi(x), \phi(y)},
\end{equation}
which is equivalent to
\begin{equation}\label{useful-in-abelian-subgroup}
\theta^{-1} \big(\lambda_{\phi^{-1}(x*y)}^{-1} ~\alpha_{x, y}\big)=\theta^{-1} \big(\lambda_{\phi^{-1}(x)}^{-1}\big)  ~\alpha_{\phi^{-1}(x), \phi^{-1}(y)}.
\end{equation}

Next, we see that
\begin{eqnarray*}
\varphi \big( (x, s)*(y, t) \big) &=& \varphi \big(x*y,~ s ~\alpha_{x, y} \big)\\
 &=&  \big(\phi^{-1}(x*y), ~\theta^{-1} \big(\lambda_{\phi^{-1}(x*y)}^{-1} s ~\alpha_{x, y}\big)\big)\\
  &=&    \big(\phi^{-1}(x)*\phi^{-1}(y), ~\theta^{-1} \big(\lambda_{\phi^{-1}(x)}^{-1}s\big)  ~\alpha_{\phi^{-1}(x), \phi^{-1}(y)}  \big),\\
  & &~\textrm{due to}~ \eqref{useful-in-abelian-subgroup}~\textrm{and the fact that $A$ is abelian}\\
  &=&    \big(\phi^{-1}(x), ~\theta^{-1} \big(\lambda_{\phi^{-1}(x)}^{-1}s\big)\big)* \big(\phi^{-1}(y), ~\theta^{-1} \big(\lambda_{\phi^{-1}(y)}^{-1}t\big) \big)\\
  &=&  \varphi(x,s) * \varphi(y,t).
\end{eqnarray*}
Thus, $\varphi \in \Aut_A(E)$ and a direct check shows that $\varphi$ is the inverse of $\psi$. Further, given $\psi(x, s)=\big(\phi(x), ~\lambda_x \theta(s)\big)$ and $\psi'(x, s)=\big(\phi'(x),~ \lambda'_x \theta'(s)\big)$, we see that
\begin{equation}\label{product-psi-abelian}
\psi \psi'(x, s)=\psi \big( \phi'(x), ~\lambda'_x \theta'(s) \big)=\big(\phi\big( \phi'(x)\big), ~\lambda_{\phi'(x)} \theta \big(\lambda'_x \theta'(s) \big) \big)=\big(\phi \phi'(x), ~\lambda_{\phi'(x)} ~\theta (\lambda'_x) ~\theta\theta'(s) \big),
\end{equation}
and hence $\Aut_A(E)$ is a subgroup of $\Aut(E)$.
$\blacksquare$    \end{proof}          
\medskip


The definition of $\Aut_A(E)$ lead to the natural restriction map $$\Psi: \Aut_A(E) \to \Aut(X) \times \Aut(A)$$ given by $\Psi(\psi)=(\phi, \theta)$.

\begin{proposition}
The map $\Psi$ is a group homomorphism and $\im(\Psi)=\Theta^{-1}(0)$.
\end{proposition}

\begin{proof}
It is clear from \eqref{product-psi-abelian} that $\Psi$ is a group homomorphism. Observe that $$\Theta^{-1}(0)=\big(\Aut(X) \times \Aut(A) \big)_{[\alpha]}.$$  If $(\phi, \theta)\in \big(\Aut(X) \times \Aut(A) \big)_{[\alpha]}$, then there exists a map $\lambda:X \to A$ such that
\begin{equation}\label{showing-psi-kernel}
\theta \big(\alpha_{\phi^{-1}(x), \phi^{-1}(y)} \big)=\alpha_{x, y}~\lambda_x~ \lambda_{x*y}^{-1}
\end{equation}
for all $x, y \in X$. Define $\psi: E \to E$ by setting $\psi(x, s)= \big(\phi(x), \lambda_{\phi(x)} \theta(s)\big)$. Clearly, $\psi$ is bijective and is a quandle homomorphism due to \eqref{showing-psi-kernel}. Further, $\Psi(\psi)=(\phi, \theta)$, and hence $\big(\Aut(X) \times \Aut(A) \big)_{[\alpha]} \subseteq \im(\Psi)$.
\par
For the converse, if $(\phi, \theta)\in \im(\Psi)$, then there exists a map $\lambda: X \to A$ such that \eqref{showing-psi-kernel} holds. But this is equivalent to $^{(\phi, \theta)}[\alpha]=[\alpha]$, which is desired.
 $\blacksquare$    
 \end{proof}          

The next result identifies kernel of $\Psi$ and the group of quandle 1-cocycles.

\begin{proposition}
$\ker(\Psi) \cong Z^1_{\rm Q}(X;A) =\{\lambda: X \to A \, \mid \, \lambda_x=\lambda_{x*y}~\textrm{for all}~x, y \in X\}$.
\end{proposition}

\begin{proof}
Note that $\psi \in \ker(\Psi)$ if and only if $\Psi(\psi)=(\id_X, \id_S)$. This gives $\psi(x, s)=\big(x, \lambda_x~ s\big)$ for all $x \in X$ and $s \in A$. Further, by \eqref{abelian-homo-condition}, $\psi$ is a quandle homomorphism if and only if $\lambda_x=\lambda_{x*y}$. Hence, $\ker(\Psi)$ is the desired group $Z^1_{\rm Q}(X;A)$ of 1-cocycles identified via the map $\psi \mapsto \lambda$.
$\blacksquare$    \end{proof}          
\medskip


The preceding results lead to the following theorem \cite[Theorem 6.6]{MR4282648}.

\begin{theorem}\label{abelian extension main theorem}
Let $X$ be a quandle, $A$ an abelian group, $\alpha\in Z^2_{\rm Q}(X; A)$ and $E=X \times_\alpha A$ the abelian extension of $X$ by $A$ through $\alpha$. Then there exists an exact sequence
\begin{equation}\label{abelian-well-sequence}
1 \longrightarrow Z^1_{\rm Q}(X;A) \longrightarrow \Aut_A(E) \stackrel{\Psi}{\longrightarrow} \Aut(X) \times \Aut(A) \stackrel{\Theta}{\longrightarrow} \Ho^2_{\rm Q}(X; A),
\end{equation}
where exactness at $ \Aut(X) \times \Aut(A)$ means that $\im(\Psi)=\Theta^{-1}(0)$.
\end{theorem}

Theorem \ref{abelian extension main theorem} can be reformulated as follows.

\begin{corollary}
Let $X$ be a quandle, $A$ an abelian group, $\alpha\in Z^2_{\rm Q}(X; A)$ and $E=X \times_\alpha A$ the abelian extension of $X$ by $A$ through $\alpha$. Then there exists a short exact sequence
\begin{equation}\label{abelian-well-sequence reformulattion}
1 \longrightarrow Z^1_{\rm Q}(X;A) \longrightarrow \Aut_A(E) \stackrel{\Psi}{\longrightarrow} \big(\Aut(X) \times \Aut(A)\big)_{[\alpha]} \longrightarrow 1.
\end{equation}
\end{corollary}


Restricting the action of $\Aut(X) \times \Aut(A)$ on $\Ho^2_{\rm Q}(X; A)$ to that of its subgroups $\Aut(X)$ and $\Aut(A)$ gives the following result.

\begin{corollary}
Every automorphism in $\Aut(X)_{[\alpha]}$ and $\Aut(A)_{[\alpha]}$ can be extended to an automorphism in $\Aut_A(E)$.
\end{corollary}
\bigskip


Next, we investigate the map $\Theta$ in detail. Let $X$ be a quandle and $A$ an abelian group. Since the group $\Aut(X) \times \Aut(A)$ acts on the group $\Ho^2_{\rm Q}(X; A)$, we have the semi-direct product group $\Ho^2_{\rm Q}(X; A) \rtimes \big(\Aut(X) \times \Aut(A) \big)$. Further, note that the group $\Ho^2_{\rm Q}(X; A)$ acts on itself by left multiplication.

\begin{proposition}
For $(\phi, \theta) \in  \Aut(X) \times \Aut(A)$ and $[\alpha], [\beta]\in  \Ho^2_{\rm Q}(X; A)$ setting
$$^{[\alpha](\phi, \theta)} [\beta]=~^{[\alpha]}{(^{(\phi, \theta)} [\beta])}$$
defines an action of $~\Ho^2_{\rm Q}(X; A) \rtimes \big(\Aut(X) \times \Aut(A) \big)$ on $\Ho^2_{\rm Q}(X; A)$.
\end{proposition}

\begin{proof}
Let $ (\phi_1, \theta_1), (\phi_2, \theta_2) \in \Aut(X) \times \Aut(A)$ and $[\alpha_1], [\alpha_2], [\beta] \in \Ho^2_{\rm Q}(X; A)$. Then, we see that
\begin{eqnarray*}
^{\big([\alpha_1](\phi_1, \theta_1)\big)\big([\alpha_2](\phi_2, \theta_2)\big)}[\beta] & = & ^{\big([\alpha_1]~^{(\phi_1, \theta_1)}[\alpha_2] \big) \big((\phi_1, \theta_1)(\phi_2, \theta_2)\big)}[\beta]\\
& = & ^{\big([\alpha_1]~^{(\phi_1, \theta_1)}[\alpha_2]\big)}{\big(^{\big((\phi_1, \theta_1)(\phi_2, \theta_2)\big)}[\beta] \big)}\\
& = & ^{[\alpha_1]}{\big(^{^{(\phi_1, \theta_1)}{[\alpha_2]}}{\big(^{(\phi_1, \theta_1)}{\big(^{(\phi_2, \theta_2)}[\beta]\big)} \big)} \big)}\\
& = & ^{[\alpha_1]}{\big({^{(\phi_1, \theta_1)}{[\alpha_2]}}{\big(^{(\phi_1, \theta_1)}{\big(^{(\phi_2, \theta_2)}[\beta]\big)} \big)} \big)},\\
& &  \textrm{since}~^{(\phi_1, \theta_1}{[\alpha_2]} \in  \Ho^2_{\rm Q}(X; A),~\textrm{which acts on itself by left translation}\\
& = & ^{[\alpha_1]}{\big({^{(\phi_1, \theta_1)}{\big([\alpha_2] \big(^{(\phi_2, \theta_2)}[\beta]\big)}} \big)\big)},\\
&  & \textrm{since}~\Aut(X) \times \Aut(A)~\textrm{acts by automorphisms on}~\Ho^2_{\rm Q}(X; A)\\
& = & ^{\big([\alpha_1](\phi_1, \theta_1)\big)}{\big(^{\big([\alpha_2](\phi_2, \theta_2)\big)}[\beta] \big)},\\
& & ~ \textrm{since}~\Ho^2_{\rm Q}(X; A)~\textrm{acts on itself by left translation}.
\end{eqnarray*}
Hence, the group $\Ho^2_{\rm Q}(X; A) \rtimes \big(\Aut(X) \times \Aut(A) \big)$ acts on $\Ho^2_{\rm Q}(X; A)$.
$\blacksquare$    \end{proof}          
\medskip

To understand the map $\Theta$, we recall some group cohomology (see Section \ref{obstruction to SLB arising from RBG} of Chapter \ref{chap RBG and YBE}). Let $A$ be an abelian group and $G$ a group acting on $A$ from left by automorphisms.  The first cohomology of $G$ with coefficients in $A$ is defined as $\Ho^1_{\rm Grp}(G; A)=Z^1(G; A)/B^1(G; A)$, where
$$Z^1(G; A) =  \big\{f:G  \to A \, \mid \,  f(xy)= f(x)~{^{x}}f(y)~ \textrm{for all}\ x,y\in G\big\}$$
is the group of  1-cocycles and
$$B^1(G;A) = \big\{f:G\to A \, \mid \, \textrm{there exists}~a \in A~\textrm{such that}~ f(x)=({^x}a)a^{-1}~\textrm{for all}~x\in G \big\}$$
is the group of 1-coboundaries.
\medskip

Further, a complement of a subgroup $H$ in a group $G$ is another subgroup $K$ of $G$ such that $G=HK$ and $H\cap K=1$.  The following result relating 1-cocycles and complements is well-known \cite[11.1.2]{MR1357169}.

\begin{lemma}\label{1-cocycle-complement}
Let $G$ be a group acting on an abelian group $H$ by automorphisms. Then the map $f \mapsto \{f(g)g \, \mid \, g \in G \}$ gives a bijection from the set $\Z^1(G; H)$ of 1-cocycles to the set $\big\{K \, \mid \, G=HK~\textrm{and}~H \cap K=1 \big\}$ of complements of $H$ in $G$. 
\end{lemma}

The following result gives a description of the map $\Theta$ \cite[Theorem 7.3]{MR4282648}.

\begin{theorem}
The map $\Theta: \Aut(X) \times \Aut(A) \to \Ho^2_{\rm Q}(X; A)$ is a group-theoretical 1-cocycle. Further, if $\Theta$ and $\Theta'$ correspond to two  quandle 2-cocycles, then $\Theta$ and $\Theta'$ differ by a group-theoretical 1-coboundary.
\end{theorem}

\begin{proof}
Suppose that $\Theta=\Theta_{[\alpha]}$ for $[\alpha] \in \Ho^2_{\rm Q}(X; A)$ and $\mathbf{g} \in \Ho^2_{\rm Q}(X; A) \rtimes \big( \Aut(X) \times \Aut(A)\big)$. Then for elements $[\alpha], ~^{\mathbf{g}}[\alpha] \in \Ho^2_{\rm Q}(X; A)$, there exists a unique $[\beta] \in \Ho^2_{\rm Q}(X; A)$ such that $~^{[\beta]}[\alpha]=~^{\mathbf{g}}[\alpha]$. This shows that $[\beta]^{-1}\mathbf{g} \in \mathbb{H}$, where $\mathbb{H}$ is the stabilizer subgroup of $\Ho^2_{\rm Q}(X; A) \rtimes \big( \Aut(X) \times \Aut(A) \big)$ at $[\alpha]$. This shows that
$$ \Ho^2_{\rm Q}(X; A) \rtimes \big( \Aut(X) \times \Aut(A) \big)= \Ho^2_{\rm Q}(X; A)\mathbb{H}.$$ Further, since $\Ho^2_{\rm Q}(X; A)$ acts freely on itself, it follows that $\mathbb{H}$ is the complement of $\Ho^2_{\rm Q}(X; A)$ in the group $\Ho^2_{\rm Q}(X; A) \rtimes \big(\Aut(X) \times \Aut(A) \big)$. By Lemma \ref{1-cocycle-complement}, let $f:\Aut(X) \times \Aut(A) \to \Ho^2_{\rm Q}(X; A)$ be the unique 1-cocycle corresponding to the complement $\mathbb{H}$ of $\Ho^2_{\rm Q}(X; A)$ in $\Ho^2_{\rm Q}(X; A) \rtimes \big(\Aut(X) \times \Aut(A)\big)$. Then, we have 
$$\mathbb{H}= \big\{f(\phi, \theta)(\phi, \theta) \, \mid \, (\phi, \theta) \in \Aut(X) \times \Aut(A) \big\},$$
that is, $$[\alpha]=~^{f(\phi, \theta)(\phi, \theta)}[\alpha]=~^{f(\phi, \theta)}{\big(^{(\phi, \theta)}[\alpha]\big)}.$$
It now follows from the definition of $\Theta$ (see \eqref{abelian-wells-map}) that $f(\phi, \theta)=\Theta (\phi, \theta)$, and hence $\Theta$ is a group-theoretical 1-cocycle.
\para

For the second assertion, let $\Theta=\Theta_{[\alpha]}$ and $\Theta'=\Theta'_{[\alpha']}$, where $[\alpha], [\alpha'] \in \Ho^2_{\rm Q}(X; A)$. Then for any $(\phi, \theta) \in \Aut(X) \times \Aut(A)$, we have 
$$ ^{\Theta(\phi, \theta)} \big(^{(\phi, \theta)}[\alpha] \big)= [\alpha]~\textrm{and}~ ^{\Theta'(\phi, \theta)} \big(^{(\phi, \theta)}[\alpha'] \big)= [\alpha'].$$
Since $\Ho^2_{\rm Q}(X; A)$ acts transitively on itself by left multiplication, there exists a unique $[\beta] \in \Ho^2_{\rm Q}(X; A)$ such that $ ^{[\beta]}[\alpha']=[\alpha]$. This gives 
$$ ^{[\beta]^{-1}}{\big(^{\Theta(\phi, \theta)} \big(^{^{(\phi, \theta)}{[\beta]}}{\big(^{(\phi, \theta)}[\alpha'] \big)} \big)\big)}= ^{\Theta'(\phi, \theta)} \big(^{(\phi, \theta)}[\alpha'] \big).$$
Further, since $[\beta]^{-1} \Theta(\phi, \theta) {^{(\phi, \theta)}{[\beta]}}$, $\Theta'(\phi, \theta)$ and  $^{(\phi, \theta)}[\alpha']$ all lie in $\Ho^2_{\rm Q}(X; A)$, which acts freely on itself, we must have $$[\beta]^{-1} \Theta(\phi, \theta) {^{(\phi, \theta)}{[\beta]}}= \Theta'(\phi, \theta).$$
Thus, $\Theta$ and $\Theta'$ differ by a group-theoretical 1-coboundary, which completes the proof.
$\blacksquare$    \end{proof}          

\begin{remark}
{\rm 
Subsequent to Theorem \ref{abelian extension main theorem}, many works, such as \cite{MR4889273, MR4644858, MR4688775, MR4604853}, have established Wells-type exact sequences for various other solutions to the Yang--Baxter equation.}
\end{remark}

