\section{Quandle extensions arising from group extensions}\label{groups-to-quandles-extensions-section}
In this section, we relate extensions of groups to extensions of quandles by applying the functors described in Section \ref{adjoint-functor-section} of Chapter \ref{chapter-adjoint-groups-quandles}. We begin with the following result \cite[Proposition 9.1]{MR4282648}.

\begin{proposition}\label{core conj extension}
Let $1 \to A \to E \to G \to 1$ be an extension of groups and $w(x,y) = y x^{-1} y$ or $y^{-n} x y^n$ for some $n \in \mathbb{Z}$. Then $ Q_w(E) \cong Q_w(G) \times_\alpha Q_w(A)$ for some dynamical 2-cocycle $\alpha$. 
\end{proposition}

\begin{proof}
Let $\pi:E \to G$ be the quotient homomorphism and $\kappa: G \to E$ a set-theoretic section such that $\kappa(1)=1$. By functoriality, 
we have a surjective quandle homomorphism $Q_w(\pi): Q_w(E) \to Q_w(G)$ such that
$$\pi \big (\kappa(x)*\kappa(y) \big)= Q_w(\pi) \big (\kappa(x)*\kappa(y) \big)= x*y= Q_w(\pi) \big (\kappa(x*y) \big)= \pi \big (\kappa(x*y) \big)$$
for all $x, y\in G$. Thus, there exists a unique element, say, $\mu(x, y) \in A$ such that $$\kappa(x)*\kappa(y)= \kappa(x*y)~\mu(x, y).$$
Note that $\mu(x, x)=1$ for all $x \in G$. Further, every element of $E$ can be written uniquely as $\kappa(x)s$ for some $x \in G$ and $s \in A$. For each $x \in G$, there is a bijection $\gamma_x: Q_w(\pi)^{-1}(x) \to A$ given by $\gamma_x\big(\kappa(x)s\big)=s$.  Hence, by Proposition \ref{AGlemma}, we have an isomorphism
$$ Q_w(E) \cong Q_w(G) \times_\alpha A,$$ where $\alpha$ is the dynamical 2-cocycle given by $\alpha_{x, y}(s, t)= \gamma_{x*y} \big(\gamma_x^{-1}(s)* \gamma_y^{-1}(t) \big)$ for $x, y \in G$ and $s, t \in A$. 

\begin{enumerate}
\item[Case 1:] If $w(x,y) = y x^{-1} y$, then
\begin{eqnarray*}
\alpha_{x, y}(s, t) &=& \gamma_{x*y} \big(\gamma_x^{-1}(s)* \gamma_y^{-1}(t) \big)\\
 &=& \gamma_{x*y} \big( \big(\kappa(x)s \big)* \big(\kappa(y)t \big)\big)\\
&=& \gamma_{x*y} \big( \kappa(y)t ~s^{-1}\kappa(x)^{-1} ~\kappa(y)t \big)\\
&=& \gamma_{x*y} \big( \kappa(y)\kappa(x)^{-1} \kappa(y) ~^{\kappa(x)^{-1} \kappa(y)}(t s^{-1}) ~t \big)\\
&=& \gamma_{x*y} \big( \big(\kappa(x)*\kappa(y)\big) ~^{\kappa(x)^{-1} \kappa(y)}(t s^{-1}) ~t \big)\\
&=& \gamma_{x*y} \big( \kappa(x*y)~\mu(x, y) ~^{\kappa(x)^{-1} \kappa(y)}(t s^{-1}) ~t \big)\\
&=&  \mu(x, y) ~^{\kappa(x)^{-1} \kappa(y)}(t s^{-1}) ~t.
\end{eqnarray*}
Recall that the quandle operation in $Q_w(G) \times_\alpha A$ is given by $(x, s)*(y, t)=\big(x*y, \alpha_{x, y}(s, t)\big)$ for $x, y \in G$ and $s, t \in A$. For each fixed $x \in G$, we have $$(x, s)*(x, t)=\big(x, \alpha_{x, x}(s, t)\big)=(x, ts^{-1}t)=(x, s*t),$$ which agrees with the quandle operation in $Q_w(A)$.
\para

\item[Case 2:] If $w(x,y) = y^{-n} x y^n$ for some $n \in \mathbb{Z}$, then
\begin{eqnarray*}
\alpha_{x, y}(s, t) &=& \gamma_{x*y} \big( \gamma_x^{-1}(s)* \gamma_y^{-1}(t) \big)\\
 &=& \gamma_{x*y} \big( \big(\kappa(x)s \big)* \big(\kappa(y)t \big)\big)\\
&=& \gamma_{x*y} \big( (\kappa(y)t)^{n} (\kappa(x)s) (\kappa(y)t)^{-n} \big)\\
&=& \gamma_{x*y} \Big( \big(\kappa(y)^n\kappa(x)\kappa(y)^{-n}\big)~\big(^{\kappa(y)^n\kappa(x)^{-1}\kappa(y)^{-n+1}}t\big)~\big(^{\kappa(y)^n\kappa(x)^{-1}\kappa(y)^{-n+2}}t \big)\cdots\\
& & \cdots \big(^{\kappa(y)^n\kappa(x)^{-1}}t \big)~\big(^{\kappa(y)^n}{(st^{-1})} \big)~\big(^{\kappa(y)^{n-1}}{t^{-1}} \big) \cdots \big(^{\kappa(y)^2}{t^{-1}} \big)~\big(^{\kappa(y)}{t^{-1}} \big) \Big)\\
&=& \gamma_{x*y} \Big( \big(\kappa(x)* \kappa(y) \big)~\big(^{\kappa(y)^n\kappa(x)^{-1}\kappa(y)^{-n+1}}t\big)~\big(^{\kappa(y)^n\kappa(x)^{-1}\kappa(y)^{-n+2}}t \big)\cdots\\
& & \cdots \big(^{\kappa(y)^n\kappa(x)^{-1}}t \big)~\big(^{\kappa(y)^n}{(st^{-1})} \big)~\big(^{\kappa(y)^{n-1}}{t^{-1}} \big) \cdots \big(^{\kappa(y)^2}{t^{-1}} \big)~\big(^{\kappa(y)}{t^{-1}} \big) \Big)\\
&=&  \mu(x, y) ~ \Big(\big(^{\kappa(y)^n\kappa(x)^{-1}\kappa(y)^{-n+1}}t\big)~\big(^{\kappa(y)^n\kappa(x)^{-1}\kappa(y)^{-n+2}}t \big)\cdots\\
& & \cdots \big(^{\kappa(y)^n\kappa(x)^{-1}}t \big)~\big(^{\kappa(y)^n}{(st^{-1})} \big)~\big(^{\kappa(y)^{n-1}}{t^{-1}} \big) \cdots \big(^{\kappa(y)^2}{t^{-1}} \big)~\big(^{\kappa(y)}{t^{-1}} \big) \Big).
\end{eqnarray*}
Taking $x=y=1$ and using the facts that $\mu(1, 1)=1=\kappa(1)$, we obtain $$(1, s)*(1, t)=\big(1, \alpha_{1, 1}(s, t)\big)=\big(1, t^{n}st^{-n}\big)=(1, s*t),$$ which agrees with the quandle operation in $Q_w(A)$. Hence, we have $Q_w(E) \cong Q_w(G) \times_\alpha Q_w(A)$.
\end{enumerate}
This completes the proof.
$\blacksquare$    \end{proof}          

An immediate consequence of Proposition \ref{core conj extension} is the following result, which generalises \cite[Proposition 3.9]{MR3544543}.

\begin{corollary}
If $G$ and $A$ are groups, then 
$$ \Core(G \times A) \cong \Core(G) \times \Core(A) \quad \textrm{and} \quad  \Conj_n(G \times A) \cong \Conj_n(G) \times \Conj_n(A)$$
for each $n \in \mathbb{Z}$.
\end{corollary}

Next, we prove an analogous result for generalised Alexander quandles \cite[Proposition 9.3]{MR4282648}.

\begin{proposition}\label{Alex-prop}
Let $1 \to A \to E \to G \to 1$ be an extension of groups and $f \in \Aut(E)$ such that $f(A)=A$. If $f_1\in \Aut(G)$ and $f_2 \in \Aut(A)$ are the automorphisms induced by $f$,  then $\Alex(E, f) \cong \Alex(G, f_1) \times_\alpha \Alex(A, f_2)$ for some dynamical 2-cocycle $\alpha$. 
\end{proposition}

\begin{proof}
Let $\pi: E \to G$, $\kappa:G \to E$ and $\mu: G \times G \to A$ be as in Proposition \ref{core conj extension}, that is, $\kappa(x)*\kappa(y)= \kappa(x*y)~\mu(x, y)$ for all $x, y \in G$. Note that $\Alex(\pi): \Alex(E, f) \to \Alex(G, f_1)$ is a surjective quandle homomorphism. For each $x \in G$, define a bijection $\gamma_x: \Alex(\pi)^{-1}(x) \to A$ by $\gamma_x \big(\kappa(x)s\big)=s$.  Again, by Proposition \ref{AGlemma}, we obtain
$$ \Alex(E, f) \cong \Alex(G, f_1) \times_\alpha A,$$ where $\alpha$ is the dynamical 2-cocycle given by $\alpha_{x, y}(s, t)= \gamma_{x*y} \big(\gamma_x^{-1}(s)* \gamma_y^{-1}(t) \big)$ for $x, y \in G$ and $s, t \in A$. We check that
\begin{eqnarray*}
\alpha_{x, y}(s, t) &=& \gamma_{x*y} \big( \big(\kappa(x)s \big)* \big(\kappa(y)t \big)\big)\\
&=& \gamma_{x*y} \Big(f \big( \kappa(x)s t^{-1}\kappa(y)^{-1} \big)\big(\kappa(y)t \big) \Big)\\
&=& \gamma_{x*y} \Big(f \big(\kappa(x)\kappa(y)^{-1}\big)\kappa(y)~^{\kappa(y)^{-1}f(\kappa(y))}{f(st^{-1})}~t\Big)\\
&=&\gamma_{x*y} \Big(\big(\kappa(x)*\kappa(y)\big)~^{\kappa(y)^{-1}f(\kappa(y))}{f(st^{-1})}~t\Big)\\
&=& \gamma_{x*y} \Big( \kappa(x*y)~\mu(x, y)~^{\kappa(y)^{-1}f(\kappa(y))}{f(st^{-1})}~t\Big)\\
&=&  \mu(x, y)~^{\kappa(y)^{-1}f(\kappa(y))}{f_2(st^{-1})}~t.
\end{eqnarray*}
Taking $x=y=1$ and using the facts that $\mu(1, 1)=1=\kappa(1)$, we get $$(1, s)*(1, t)=\big(1, \alpha_{1, 1}(s, t)\big)=\big(1, f_2(st^{-1})t\big)=(1, s*t),$$ which is the desired quandle structure on $\Alex(A, f_2)$.
$\blacksquare$    \end{proof}          

As a consequence of Proposition \ref{Alex-prop}, we recover the following special case of \cite[Proposition 3.7]{MR3544543}.

\begin{corollary}
If $G$ and $A$ are groups and  $(f_1, f_2) \in \Aut(G) \times \Aut(A)$, then 
$$\Alex_{(f_1, f_2)}(G \times A) \cong \Alex_{f_1}(G) \times \Alex_{f_2}(A).$$
\end{corollary}
\medskip

It is natural to ask whether an extension of quandles induces a corresponding extension of their adjoint groups. The following example show that this is not the case in general.

\begin{example}{\rm 
Let $\R_4 = \{ 0, 1, 2, 3 \}$ be the dihedral quandle of order four. If $X = \{ u, v \}$ is the two element trivial quandle, then there is a surjective quandle homomorphism $\pi: \R_4 \to X$ given by $\pi(0)=\pi(2)=u$ and $\pi(1)=\pi(3)=v$. Then, by Proposition \ref{AGlemma}, we have 
$$\R_4 \cong X \times_\alpha S,$$ where $\alpha$ is a dynamical 2-cocycle  and $S$ is a set of two elements. Since both $X$ and $S$ are two element trivial quandles, we have $\Adj(X) \cong \Adj(S) \cong \mathbb{Z} \times \mathbb{Z}$.  We claim that $\Adj(\R_4)$ is not an extension of $\mathbb{Z} \times \mathbb{Z}$ by $\mathbb{Z} \times \mathbb{Z}$.
\para
We write $\R_4 = Y_0 \sqcup Y_1$ as a disjoint union of fibers, where $Y_0 = \{0, 2\}$ and $Y_1 = \{1, 3 \}$. Both $Y_1, Y_2$ are the connected components as well as trivial subquandles of $\R_4$. Note that $S_{0} = S_{2}$ with
$$
S_{0}(1) = 3  ~ \textrm{and}~  S_{0}(3) = 1.
$$
Similarly, $S_{1} = S_{3}$ with
$$
S_{1}(0) = 2  ~ \textrm{and}~ S_{1}(2) = 0.
$$
Since  $Y_0,Y_1$ and $X$ are trivial quandles, we have
\begin{eqnarray*}
\Adj(Y_0) &=& \big\langle \textswab{a}_0, \textswab{a}_2 \, \mid \, \textswab{a}_0 \textswab{a}_2 = \textswab{a}_2 \textswab{a}_0 \big\rangle, \\
\Adj(Y_1) &=& \big\langle \textswab{a}_1, \textswab{a}_3 \, \mid \, \textswab{a}_1 \textswab{a}_3 = \textswab{a}_3 \textswab{a}_3 \big\rangle,\\
\Adj(X) &=& \big\langle f_u, f_v \, \mid \, f_u f_v = f_v f_u \big\rangle.
\end{eqnarray*}
Note that the group $\Adj(\R_4)$ is generated by its subgroups $\Adj(Y_0), \Adj(Y_1)$ and has relations
$$
\textswab{a}_1^{-1} \textswab{a}_0 \textswab{a}_1 = \textswab{a}_2,~~~\textswab{a}_1^{-1} \textswab{a}_2 \textswab{a}_1 = \textswab{a}_0,~~~ \textswab{a}_0^{-1} \textswab{a}_1 \textswab{a}_0 = \textswab{a}_3,~~~\textswab{a}_2^{-1} \textswab{a}_1 \textswab{a}_2 = \textswab{a}_3,~~~ \textswab{a}_3^{-1} \textswab{a}_0 \textswab{a}_3 = \textswab{a}_2,~~~\textswab{a}_3^{-1} \textswab{a}_2 \textswab{a}_3 = \textswab{a}_0.
$$
Clearly, the elements $b_0:=\textswab{a}_0 \textswab{a}_2^{-1}$ and  $b_1:=\textswab{a}_1 \textswab{a}_3^{-1}$ lie in the kernel of the homomorphism
$$
\Adj(\pi) : \Adj(\R_4) \to \Adj(X).
$$
We remove the generators $\textswab{a}_2$ and $\textswab{a}_3$ using the equalities $\textswab{a}_2 = \textswab{a}_0 b_0^{-1}$ and $\textswab{a}_3 = \textswab{a}_1 b_1^{-1}$. It follows that the other relations have the form
$$
b_0 = \textswab{a}_1^{-1} \textswab{a}_0^{-1} \textswab{a}_1 \textswab{a}_0,~~b_1 = \textswab{a}_0^{-1} \textswab{a}_1^{-1} \textswab{a}_0 \textswab{a}_1,~~b_1 = b_0^{-1},~~b_0^2 = 1,~~\textswab{a}_0^{-1}b_0 \textswab{a}_0 = b_0,~~\textswab{a}_1^{-1}b_1 \textswab{a}_1 = b_1.
$$
Hence, $\Adj(\R_4)$ has a presentation
$$
\Adj(\R_4) = \big\langle \textswab{a}_0, \textswab{a}_1, b_0 \, \mid \, b_0^2 = 1,~~\textswab{a}_1 \textswab{a}_0 = \textswab{a}_0 \textswab{a}_1 b_0,~~\textswab{a}_1^{-1} \textswab{a}_0 = \textswab{a}_0 \textswab{a}_1^{-1} b_0,~~ [\textswab{a}_0, b_0] =   [\textswab{a}_1, b_0] = 1 \big\rangle
$$
and there is an exact sequence
$$
1 \to \mathbb{Z}_2 \to \Adj(\R_4) \to  \mathbb{Z} \times \mathbb{Z} \to 1,
$$
where $\mathbb{Z}_2 = \langle b_0 \rangle$ and $\mathbb{Z} \times \mathbb{Z}= \langle f_u, f_v \rangle$.}
\end{example}
