\section{Maps from group cohomology to quandle cohomology}\label{Homomorphism group cohomology to quandle cohomology}
In view of Remark \ref{remark on trunk map}, if $X$ is a quandle and $\mathcal{A}$ is the category of abelian groups, then a trunk map $A: \mathcal{T}'(X) \to \mathcal{A}$ assigns an abelian group $A_x$ to each $x \in X$ and  group homomorphisms $\eta_{x,y} \colon A_x \rightarrow A_{x*y}$ and $\xi_{x,y} \colon A_y \rightarrow A_{x*y}$ such that 
\begin{equation}\label{homo-quandle-module-1}
\eta_{x*y,z}\, \eta_{x,y}=\eta_{x*z,y*z} \, \eta_{x,z} \quad \textrm{and} \quad 
\eta_{x*y,z}\, \xi_{x,y} = \xi_{x*z,y*z} \, \eta_{x,z}
\end{equation}
for all $x,y,z \in X$.
\para 

A \index{quandle module}{\it quandle module} over $X$ is a trunk map
$A: \mathcal{T}'(X) \to \mathcal{A}$ such that each
$\eta_{x,y}$ is an isomorphism and the identities
\begin{equation}\label{homo-quandle-module-3}
\xi_{x*y, z}(s) =  \big(\eta_{x*z,y*z}\, \xi_{x, z}(s)\big)~ \big(\xi_{x*z, y*z}\, \xi_{y, z}(s)\big)
\end{equation}
and 
\begin{equation}\label{homo-quandle-module-4}
\eta_{z, z}(s)~\xi_{z, z}(s)=s
\end{equation}
hold for all $x,y,z \in X$ and $s \in A_z$. A quandle module over $X$ is called {\it homogeneous} if $A_x=A$ for all $x \in X$. Further, a homogeneous quandle module is called {\it trivial} if $\eta_{x,y}$ is the identity map and $\xi_{y, x}$ is the trivial map for all $x, y \in X$.
\para

\begin{example}\label{homogen-module-example}
{\rm 
Any abelian group $A$ can be turned into a homogeneous quandle module over a quandle $X$ by taking $\eta_{x,y}(s)=s^{-1}$ and $\xi_{x,y}(s)=s^2$ for all $x, y \in X$ and $s \in A$.}
\end{example}


For the rest of this section, we consider only homogeneous quandle modules over a quandle. If $A$ is a homogeneous quandle module over $X$, then a {\it factor set} is a map $\mu: X \times X \to A$ satisfying
\begin{equation}\label{factor-set-def-condition}
\mu(x*y,z) ~ \eta_{x*y,z}\big(\mu(x,y)\big) = \eta_{x*z,y*z}\big(\mu(x,z)\big)  ~\mu(x*z,y*z)~ \xi_{x*z, y*z}\big(\mu(y,z)\big)
\end{equation}
and 
\begin{equation}\label{factor-set-def-condition-2}
\mu(x,x) = 1
\end{equation}
for all $x,y,z \in X$. Identities \eqref{homo-quandle-module-1}-\eqref{homo-quandle-module-4} imply that each factor set $\mu$ defines a quandle extension $E=X \times_\alpha A$ of $X$ by $A$, where
\begin{equation}\label{factor-set-quandle-operation}
(x, s)* (y, t)= \big(x*y, ~\eta_{x,y}(s)~\mu(x, y)~\xi_{x,y}(t) \big)
\end{equation}
for all $x, y \in X$ and $s, t \in A$. Conversely, it follows from \cite[Proposition 3.1]{MR2155522} that every extension of a quandle $X$ by a homogeneous quandle module $A$ over $X$ is determined by a factor set. 
\para

Two factor sets $\mu_1,\mu_2: X \times X \to A$ are {\it cohomologous} if there exists a map $\lambda:X \to A$ such that
\begin{equation}\label{factor-set-equivalence}
\mu_2(x, y) = \mu_1(x, y)~\eta_{x,y} \big(\lambda(x) \big)~\xi_{x,y} \big(\lambda(y) \big)~\lambda(x*y)^{-1}
\end{equation}
 for all $x,y \in X$. It is not difficult to see that two factor sets are cohomologous if and only if the corresponding extensions are equivalent  \cite[Theorem 3.6]{MR2155522}. Thus, the set $\mathcal{H}^2_{\rm Q}(X;A)$ of cohomology classes of factor sets, which forms an abelian group with point-wise multiplication,  is in bijective correspondence with the set of equivalence classes of quandle extensions of $X$ by $A$. When $A$ is a trivial homogeneous quandle module over $X$, then $\mathcal{H}^2_{\rm Q}(X;A)=\Ho^2_{\rm Q}(X;A)$ and the quandle operation \eqref{factor-set-quandle-operation} agrees with \eqref{abelian-extension-operation}.
\para

We recall some group cohomology required for our final two results (see Section \ref{obstruction to SLB arising from RBG} of Chapter \ref{chap RBG and YBE}). Let $G$ be a group acting on an abelian group $A$ from the left by automorphisms. The second cohomology of $G$ with coefficients in $A$ is defined as $\Ho^2_{\rm Grp}(G; A)=Z^2(G; A)/B^2(G; A)$, where
$$Z^2(G; A) =\big\{\nu:G \times G \to A  \, \mid \,   \big(x \cdot \nu(y,z) \big)\nu(x, yz)= \nu(xy, z)\nu(x, y)~ \textrm{for all}\ x, y, z\in G\big\}$$
is the group of  2-cocycles and
$$B^2(G;A) = \big\{\nu:G \times G \to A  \, \mid \,  \textrm{there exists}~\lambda:G \to A~\textrm{with}~ \nu(x, y)=~ \big(x \cdot \lambda(y) \big)\lambda(xy)^{-1} \lambda(x)~\textrm{for all}~x, y\in G \big\}$$
is the group of 2-coboundaries.
\para

It is well-known that $\Ho^2_{\rm Grp}(G;A)$ classifies extensions of groups $1 \to A \to E \to G \to 1$ that give rise to the given action of $G$ on $A$. In particular, $E$ is abelian if and only if any group-theoretical  2-cocycle $\nu$ classifying the extension is symmetric, that is, 
$$\nu(x, y)=\nu(y, x)$$ for all $x, y \in G$. Since any group-theoretical 2-cocycle cohomologous to a symmetric group-theoretical 2-cocycle is itself symmetric, we can consider the set $\Ho^2_{\rm SGrp}(G;A)$ of all symmetric group-theoretical cohomology classes of degree 2. In fact, it turns out that $\Ho^2_{\rm SGrp}(G;A)$ is a subgroup of $\Ho^2_{\rm Grp}(G;A)$. With this set-up, we prove the following result \cite[Theorem 10.2]{MR4282648}.


\begin{theorem}\label{homo from group cohom  to quandle cohom}
Let $G$ and $A$ be abelian groups with $A$ viewed as a trivial $G$-module. Then there is a natural group homomorphism $\Lambda:\Ho^2_{\rm SGrp}(G;A) \to \mathcal{H}^2_{\rm Q} \big(\Core(G);A\big )$ given by $\Lambda \big([\nu] \big) = [\check{\nu}]$.
\end{theorem}

\begin{proof}
Let $1 \to A \to E \to G \to 1$ be an extension of abelian groups and $\kappa:G \to E$ a set-theoretic section with $\kappa(1)=1$. Let  $\nu: G \times G \to A$ be a symmetric group-theoretical 2-cocycle corresponding to the  set-theoretic section $\kappa$, that is, 
\begin{equation}\label{tau-nu}
\kappa(x)\kappa(y)= \kappa(xy)~\nu(x, y)
\end{equation}
for all $x, y \in G$. Define $\check{\nu}: G \times G \to A$ by 
$$\kappa(x)*\kappa(y)=\kappa(x*y)~\check{\nu}(x, y)$$
for all $x, y \in G$. Then, we see that
\begin{eqnarray}\label{mu-nu-relation}
\nonumber \check{\nu}(x, y) &=& \big( \kappa(x)*\kappa(y) \big)\kappa(x*y)^{-1}\\
\nonumber &=& \kappa(y)\kappa(x)^{-1} \kappa(y)\kappa(yx^{-1}y)^{-1}\\
\nonumber  &=& \kappa(y)\kappa(x)^{-1} \kappa(yx^{-1})^{-1} ~\nu(yx^{-1}, y),~\textrm{using \eqref{tau-nu} and the fact that $E$ is abelian}\\
 &=& \nu(yx^{-1}, x)^{-1}~ \nu(yx^{-1}, y).
\end{eqnarray}
As in Example \ref{homogen-module-example}, we view $A$ as a homogeneous quandle module over $\Core(G)$ by taking $\eta_{x,y}(s)=s^{-1}$ and $\xi_{y,x}(s)=s^2$ for all $x, y \in G$ and $s \in A$. By Proposition \ref{core conj extension}, $\Core(E)$ is a quandle extension of $\Core(G)$ by the homogeneous quandle module $A$. Further, $\check{\nu}$ is the factor set of the extension $\Core(E)$ relative to the set-theoretic section $\kappa$ in the sense of \eqref{factor-set-def-condition}. 
\para

We claim that if $\nu_1, \nu_2: G \times G \to A$ are cohomologous  group-theoretical  2-cocycles, then the corresponding factor sets $\check{\nu_1}, \check{\nu_2}$ are cohomologous in the sense of \eqref{factor-set-equivalence}. Let $\lambda:G \to A$ be a map such that $\nu_2(x, y)=\nu_1(x,y) \lambda(x)\lambda(xy)^{-1}\lambda(y)$ for all $x, y \in G$. Then, using \eqref{mu-nu-relation}, we have 
\begin{eqnarray*}
\check{\nu_2}(x, y) &=& \nu_2(yx^{-1}, x)^{-1} \nu_2(yx^{-1}, y)\\
 &=& \big(\nu_1(yx^{-1}, x)^{-1}~  \nu_1(yx^{-1},y) \big) \lambda(y)^2 \lambda(x)^{-1} \lambda(yx^{-1}y )^{-1}\\
 &=& \check{\nu_1}(x, y) \lambda(y)^2 \lambda(x)^{-1} \lambda(x*y )^{-1}\\
 &=& \check{\nu_1}(x, y) ~\xi_{x,y}\big( \lambda(y) \big)~\eta_{x,y} \big(\lambda(x)\big) ~\lambda(x*y )^{-1}
\end{eqnarray*}
for all $x, y \in G$. Thus, by \eqref{factor-set-equivalence}, $\check{\nu_1}$ and $\check{\nu_2}$ are cohomologous and determine equivalent extensions. This defines a map $$\Lambda:\Ho^2_{\rm SGrp}(G;A) \to \mathcal{H}^2_{\rm Q} \big(\Core(G);A\big)$$ given by $\Lambda\big([\nu] \big)= [\check{\nu}]$. If $[\nu_1], [\nu_2] \in \Ho^2_{\rm SGrp}(G;A)$, then we see that
\begin{eqnarray*}
\Lambda\big([\nu_1][\nu_2] \big) &=& \Lambda\big([\nu_1\nu_2] \big) \\
&=& [\check{(\nu_1\nu_2)}]\\
&=& [\check{\nu_1}\check{\nu_2}]\\
&=& [\check{\nu_1}][\check{\nu_2}]\\
&=& \Lambda\big([\nu_1]\big) \Lambda\big( [\nu_2] \big),
\end{eqnarray*}
and hence $\Lambda$ is a group homomorphism. 
\para

For naturality of  $\Lambda$, let $G_1, G_2, A_1, A_2$ be abelian groups and $f:G_2 \to G_1$, $h:A_1 \to A_2$ be group homomorphisms. For each group-theoretical 2-cocycle $\nu:G_1 \times G_1 \to A_1$, we define
$$\nu'(x, y)=h \big(\nu\big(f(x), f(y)\big) \big)$$ for all $x, y \in G_2$. A routine check shows that $\nu \mapsto \nu'$ induces a group homomorphism $\Ho^2_{\rm SGrp}(G_1;A_1) \to \Ho^2_{\rm SGrp}(G_2;A_2)$ given by $[\nu] \mapsto [\nu']$. Similarly, for each factor set $\mu: \Core(G_1) \times \Core(G_1) \to A_1$, define 
$$\mu'(x, y)=h \big(\mu\big(f(x), f(y)\big) \big)$$ for all $x, y \in \Core(G_2)$. A direct check shows that $\mu'$ satisfies the factor set conditions \eqref{factor-set-def-condition} and \eqref{factor-set-def-condition-2}. Since cohomologous factor sets are mapped to cohomologous factor sets, we obtain a group homomorphism  $\mathcal{H}^2_{\rm Q} \big(\Core(G_1); A_1\big) \to \mathcal{H}^2_{\rm Q} \big(\Core(G_2); A_2\big)$ given by $[\mu] \mapsto [\mu']$. Finally, it follows from the construction of the preceding maps that the diagram 
$$
\xymatrix{
\Ho^2_{\rm SGrp}(G_1;A_1) \ar[r]^{[\nu] \mapsto [\nu']} \ar[d]^{\Lambda} & \Ho^2_{\rm SGrp}(G_2;A_2) \ar[d]^{\Lambda} \\
\mathcal{H}^2_{\rm Q} \big(\Core(G_1); A_1\big) \ar[r]^{[\mu] \mapsto [\mu']}  & \mathcal{H}^2_{\rm Q} \big(\Core(G_2); A_2\big)}
$$
commutes, and the map $\Lambda$ is natural.
$\blacksquare$    \end{proof}          

Let $G$ be a group and $A$ a trivial $G$-module. For a group-theoretical 2-cocycle $\nu \in Z^2(G;A)$, define $\breve{\nu}:G \times G \to A$  by 
\begin{equation}\label{nu-nu-breve-relation}
\breve{\nu}(x, y)=\nu(x, y)~ \nu(y, y^{-1}xy)^{-1}
\end{equation}
 for $x, y \in G$. It has been proved in \cite[Theorem 7.1]{MR1990571} that $\breve{\nu} \in Z^2_{\rm Q}\big( \Conj(G);A\big)$. We establish the following analogue of Theorem \ref{homo from group cohom  to quandle cohom}.

\begin{theorem}\cite[Theorem 10.3]{MR4282648}
Let $G$ be a group and $A$ an abelian group viewed as a trivial $G$-module. Then there is a natural group homomorphism $\Gamma:\Ho^2_{\rm Grp}(G;A) \to \Ho^2_{\rm Q}\big(\Conj(G);A\big)$ given by $\Gamma \big([\nu] \big) = [\breve{\nu}]$.
\end{theorem}

\begin{proof}
Let $\nu_1, \nu_2$ be cohomologous  group-theoretical  2-cocycles. Then there exists a map $\lambda:G \to A$ such that $\nu_2(x, y)=\nu_1(x,y) \lambda(x)\lambda(xy)^{-1}\lambda(y)$ for all $x, y \in G$. Using \eqref{nu-nu-breve-relation}, we obtain 
\begin{eqnarray*}
\breve{\nu_2}(x, y) &=& \nu_2(x, y) ~\nu_2(y, y^{-1}xy)^{-1}\\
 &=& \big(\nu_1(x,y) ~\nu_1(y, y^{-1}xy)^{-1} \big)\lambda(x)\lambda(y^{-1}xy)^{-1}\\
 &=& \breve{\nu_1}(x, y)\lambda(x)\lambda(x*y)^{-1}
\end{eqnarray*}
for all $x, y \in G$. Thus, $\breve{\nu_1}$ and $\breve{\nu_2}$ are cohomologous quandle 2-cocycles. This defines a map $$\Gamma:\Ho^2_{\rm Grp}(G;A) \to \Ho^2_{\rm Q} \big(\Conj(G);A\big)$$ given by $\Gamma\big([\nu] \big)= [\breve{\nu}]$. If $[\nu_1], [\nu_2] \in 
\Ho^2(G;A)$, then we see that
\begin{eqnarray*}
\Gamma\big([\nu_1][\nu_2] \big) &=& \Gamma\big([\nu_1\nu_2] \big) \\
&=& [\breve{(\nu_1\nu_2)}]\\
&=& [\breve{\nu_1}\breve{\nu_2}]\\
&=& [\breve{\nu_1}][\breve{\nu_2}]\\
&=& \Gamma\big([\nu_1]\big) \Gamma\big( [\nu_2] \big),
\end{eqnarray*}
and $\Gamma$ is a group homomorphism. The naturality of $\Gamma$ follows in a manner similar to that of $\Lambda$  in Theorem  \ref{homo from group cohom  to quandle cohom}.
$\blacksquare$    \end{proof}          

\begin{remark}
{\rm 
We note that a relation between group extensions of a group $G$ and quandle extensions of the quandle $\Alex(G,\iota_x)$ has been obtained in \cite{MR4203539}, where $\iota_x$ is the inner automorphism of $G$ induced by an element $x$.
}    
\end{remark}
