		\begin{enumerate}
			\item If $n=6n_0+4$ or $n=6n_0+7$ with $n_0\in\mathbb{N}$ (equivalently, if $n=3k_0+1$ with $k_0\in\mathbb{N}\setminus\{0\}$), then
			\begin{itemize}
				\item $\gamma=4$,
				\item $\begin{pmatrix} s_v & P_v \\ s_{v+1} & P_{v+1} \end{pmatrix} =
				\begin{pmatrix} \frac{f_{n+2}}{2} & \frac{f_{n-1}}{2} \\ f_n & f_n \end{pmatrix}$,
				\item $\mathrm{PF}(S(n)) = \left\{ \left(\frac{f_{n+2}}{2}-1\right)f_{n+1}^2 + \left(\frac{f_{n-2}+f_n}{2}-1\right)f_{n+2}^2, \left( \frac{f_{n-1}}{2}-1\right)f_{n+1}^2 + (f_n-1)f_{n+2}^2 \right\} - f_n^2$.
			\end{itemize}

			\item If $n=6n_0+5$ or $n=6n_0+8$ with $n_0\in\mathbb{N}$ (equivalently, if $n=3k_0+2$ with $k_0\in\mathbb{N}\setminus\{0\}$), then
			\begin{itemize}
				\item $\gamma=3$,
				\item $\begin{pmatrix} s_v & P_v \\ s_{v+1} & P_{v+1} \end{pmatrix} =
				\begin{pmatrix} f_{n+2} & f_{n-1} \\ \frac{f_n+f_{n+2}}{2} & \frac{f_{n+1}}{2} \end{pmatrix}$,
				\item $\mathrm{PF}(S(n)) = \left\{ (f_{n+2}-1)f_{n+1}^2 + \left(\frac{f_{n-2}}{2}-1\right)f_{n+2}^2, \left(\frac{f_{n+1}}{2}-1\right)f_{n+1}^2 + \left(\frac{f_{n+1}}{2}-1\right)f_{n+2}^2 \right\} - f_n^2$.
			\end{itemize}

			\item If $n=6n_0+6$ or $n=6n_0+9$, with $n_0\in\mathbb{N}$ (equivalently, if $n=3k_0+3$ with $k_0\in\mathbb{N}\setminus\{0\}$), then
			\begin{itemize}
				\item $\gamma=1$,
				\item $\begin{pmatrix} s_v & P_v \\ s_{v+1} & P_{v+1} \end{pmatrix} =
				\begin{pmatrix} \frac{f_{n+3}}{2} & \frac{f_{n-3}}{2} \\ \frac{f_n}{2} & \frac{f_n}{2} \end{pmatrix}$,
				\item $\mathrm{PF}(S(n)) = \left\{ \left(\frac{f_{n+3}}{2}-1\right)f_{n+1}^2 + (f_{n-2}-1)f_{n+2}^2, (f_{n+1}-1)f_{n+1}^2 + \left(\frac{f_n}{2}-1\right)f_{n+2}^2 \right\} - f_n^2$.
			\end{itemize}
		\end{enumerate}
		Moreover, in any case, $\mathrm{F}(S(n)) = \max(\mathrm{PF}(S(n)))$.
	\end{corollary}



	\section{Algorithmic process by Tripathi}\label{tri}

	Although \cite{tripathi} discusses ``formulae for the Frobenius number in three variables'', we opt for the term algorithmic process. This is because deriving the coefficients for Tripathi's proposed formulas necessitates the use of computationally non-trivial preceding algorithms, as demonstrated in Subsection~\ref{tri-app}.

	\subsection{Preliminaries}\label{tri-pre}

	Once again, let $S$ be the numerical semigroup generated by the pairwise relatively prime positive integers $a<b<c$ such that $\mathrm{e}(S)=3$.

	We define $\kappa:=\left\lfloor \frac{c}{b} \right\rfloor$ and $\ell :\equiv cb^{-1} \pmod{a}$ (where $\ell$ is the smallest non-negative integer satisfying the congruence).

	From the proof of Lemma~2 in \cite{tripathi}, we have the following result.

	\begin{lemma}\label{lem01tri}
		Let $a<b<c$ be pairwise relatively prime positive integers such that $S=\langle a,b,c\rangle$ is a numerical semigroup with $\mathrm{e}(S)=3$. Then $\ell > \kappa$.
	\end{lemma}

	We define $q:=\left\lfloor \frac{a}{a-\ell} \right\rfloor$, $r:=a-q(a-\ell)$, $\overline{q}:=\left\lfloor \frac{a}{\ell} \right\rfloor$, and $\overline{r}:=a-\overline{q}\ell$, (with $q,\overline{q}\geq1$, $0\leq r<a-\ell$, and $0\leq \overline{r}<\ell$).

	The following results are Theorem~3 and Theorem~4 from \cite{tripathi}, respectively.

	\begin{theorem}\label{thm02tri3}
		If $\ell > \kappa$ and $br<cq$, then
		\[ \mathrm{F}(\langle a,b,c \rangle) = \begin{cases} b\{ (\lambda+1)(a-\ell)+r-1 \}-a, \mbox{ if } \lambda \geq \frac{c(q-1)-br}{b(a-\ell)+c}, \\[3pt]
			b(a-\ell-1) + c(q-\lambda-1)-a, \mbox{ if } \lambda \leq \frac{c(q-1)-br}{b(a-\ell)+c}, \end{cases} \]
		where $\lambda:= \left\lfloor \frac{c(q-1)-br}{b(a-\ell)+c} \right\rfloor$.
	\end{theorem}

	\begin{theorem}\label{thm03tri4}
		If $\ell > \kappa$ and $b(\ell-\overline{r}) < c(\overline{q}-1)$, then
		\[ \mathrm{F}(\langle a,b,c \rangle) = \begin{cases} b(\ell-1) + c(\overline{q}-1) - a, \mbox{ if } 0 \leq \overline{r} < \ell-\kappa, \\
			b(\overline{r}-1) + c\overline{q} - a, \mbox{ if } \ell-\kappa \leq \overline{r} < \ell. \end{cases} \]
	\end{theorem}

	We define $A:=br-cq$ and $B:=b(a-\ell-r)+c(q+1)$. Furthermore, let $\mu'$ be the largest non-negative integer $m$ such that $\left\lfloor \frac{Bi}{A} \right\rfloor = \left\lfloor \frac{(a-\ell-r)i}{r} \right\rfloor$ for all $i\in\{0,\dots,m\}$.

	\begin{remark}\label{rem04tri}
		 To avoid ambiguity, the definition of $\mu'$ has been slightly modified from that in \cite{tripathi}: we define $\mu'$ as the largest non-negative integer $m$ such that $\left\lfloor \frac{Bm}{A} \right\rfloor = \left\lfloor \frac{(a-\ell-r)m}{r} \right\rfloor$. By this definition, in Example~5 of \cite{tripathi}, we would get $\mu'=9$. However, the correct value is $\mu'=4$, which agrees with our definition and, moreover, is the one given in \cite{tripathi}. This fact was also pointed out in Remark~5.17 of \cite{suhajda}.
	\end{remark}

	The following claim will be necessary for Theorem~\ref{thm08tri5}. Set $\mathcal{X} = \{ x_i \mid 0\leq i \leq \mu' \}$, where $x_i=r-\left((a-\ell)i\pmod{r}\right)$.

	\begin{claim}\label{claim05tri}
		Let $\ell > \kappa$ and $br > cq$. Let $\mathcal{X}_{ord}$ be the set formed by the ordered elements of $\mathcal{X}$, and let $\mathcal{X}_{dist}$ be the set formed by the distances between two consecutive elements of $\mathcal{X}_{ord}$. If $\mu'> \left\lfloor \frac{r}{u} \right\rfloor$, then $\mathcal{X}_{dist}$ has exactly two elements, $d_1<d_2$.		
	\end{claim}

	\begin{remark}\label{rem06tri}
		In Theorem~5 of \cite{tripathi}, $d_1 = \left\lceil \frac{r}{u} \right\rceil u-r$ is defined. However, this equality is incorrect, as demonstrated in Example~5.18 of \cite{suhajda}.
	\end{remark}

	\begin{remark}\label{rem07tri}
		In \cite{suhajda}, it is conjectured that $d_2$ always corresponds to $\mu'$. We have preferred to be cautious and define $d_2$ as the second possible value in $\mathcal{X}_{dist}$. Moreover, we believe that it will be easier to prove Claim~\ref{claim05tri} than Theorem~5.16 in \cite{suhajda}.
	\end{remark}

	The following result is a reformulation of Theorem~5 in \cite{tripathi} that takes into account the above two remarks.

	\begin{theorem}\label{thm08tri5}
		Let $\ell > \kappa$ and $br > cq$. Let $u \equiv (a-\ell)\pmod{r}$.
		\begin{itemize}
			\item[(a)] If $\mu'< \left\lfloor \frac{r}{u} \right\rfloor$, then $\mathrm{F}(\langle a,b,c \rangle) =$ 
			\[ \max\left\{ b(r-\mu'u-1), b(u-1)+c\left(\mu' + \left( \left\lfloor \frac{(a-\ell)\mu'}{r} \right\rfloor+1 \right)q \right) \right\} + cq\left\lfloor \frac{a-\ell-1}{r} \right\rfloor -a. \]

			\item[(b)] Let $\mu'> \left\lfloor \frac{r}{u} \right\rfloor$. Let $d_1$, $d_2$ be the numbers given by Claim~\ref{claim05tri}, and let $p_i$ be the largest positive integer such that $x_{p_i}+d_i\in\mathcal{X}$ for $i=1,2$. Then
			\[ \mathrm{F}(\langle a,b,c \rangle) = \max\{b(d_1-1)+cy_{p_1}, b(d_2-1)+cy_{p_2} \} + cq\left\lfloor \frac{a-\ell-1}{r} \right\rfloor -a, \]
			where $y_{p_i} = q\left(\left\lfloor \frac{(a-\ell)p_i}{r} \right\rfloor +1\right) + p_i$ for $i=1,2$.
		\end{itemize} 
	\end{theorem}

	\begin{remark}\label{rem09tri}
		Regarding Claim~\ref{claim10tri} and Theorem~\ref{thm11tri6}, similar remarks to Remarks~\ref{rem04tri}, \ref{rem06tri}, and \ref{rem07tri} can be made.  
	\end{remark}

	We define $\overline{A}:=b(\ell-\overline{r})-c(\overline{q}-1)$ and $\overline{B}=b\overline{r}+c\overline{q}$. Furthermore, let $\overline{\mu}'$ be the largest non-negative integer $m$ such that $\left\lfloor \frac{\overline{B}i}{\overline{A}} \right\rfloor = \left\lfloor \frac{\overline{r}i}{\ell-\overline{r}} \right\rfloor$ for all $i\in\{0,\dots,m\}$.

	Set $\overline{\mathcal{X}} = \{ x_i \mid 0\leq i \leq \overline{\mu}' \}$, where $x_i=(\ell-\overline{r})-\left(\overline{r}i\pmod{(\ell-\overline{r})}\right)$.

	\begin{claim}\label{claim10tri}
		Let $\ell > \kappa$ and $b(\ell-\overline{r}) > c(\overline{q}+1)$. Let $\overline{\mathcal{X}}_{ord}$ be the set formed by the ordered elements of $\overline{\mathcal{X}}$, and let $\overline{\mathcal{X}}_{dist}$ be the set formed by the distances between two consecutive elements of $\overline{\mathcal{X}}_{ord}$. If $\overline{\mu}'> \left\lfloor \frac{\ell-\overline{r}}{\overline{u}} \right\rfloor$, then $\overline{\mathcal{X}}_{dist}$ has exactly two elements $d_1<d_2$.		
	\end{claim}

	\begin{theorem}\label{thm11tri6}
		Let $\ell > \kappa$ and $b(\ell-\overline{r}) > c(\overline{q}+1)$. Let $\overline{u} \equiv \overline{r}\pmod{(\ell-\overline{r})}$.
		\begin{itemize}
			\item[(a)] If $\overline{\mu}'< \left\lfloor \frac{\ell-\overline{r}}{\overline{u}} \right\rfloor$, then $\mathrm{F}(\langle a,b,c \rangle) =$ 
			\[ \max\left\{ b(\ell-\overline{r}-\overline{\mu}'\overline{u}-1), b(\overline{u}-1)+c\left( \left(\left\lfloor \frac{\ell\overline{\mu}'}{\ell-\overline{r}} \right\rfloor+1 \right)\overline{q} + \left\lfloor \frac{\overline{r}\overline{\mu}'}{\ell-\overline{r}} \right\rfloor+1 \right) \right\} + \]
			\[ c\left((\overline{q}+1)\left\lfloor \frac{\ell-1}{\ell-\overline{r}} \right\rfloor-2\right) -a. \]

			\item[(b)] Let $\overline{\mu}'> \left\lfloor \frac{\ell-\overline{r}}{\overline{u}} \right\rfloor$. Let $d_1$, $d_2$ be the numbers given by Claim~\ref{claim10tri}, and let $p_i$ be the largest positive integer such that $x_{p_i}+d_i\in\overline{\mathcal{X}}$ for $i=1,2$. Then
			\[ \mathrm{F}(\langle a,b,c \rangle) = \max\{b(d_1-1)+cy_{p_1}, b(d_2-1)+cy_{p_2} \} + c\left((\overline{q}+1)\left\lfloor \frac{\ell-1}{\ell-\overline{r}} \right\rfloor-2\right) -a, \]
			where $y_{p_i} = \overline{q}\left(\left\lfloor \frac{\ell p_i}{\ell-\overline{r}} \right\rfloor +1 \right) + \left\lfloor \frac{\overline{r} p_i}{\ell-\overline{r}} \right\rfloor+1$ for $i=1,2$.
		\end{itemize} 
	\end{theorem}


	\subsection{Application to $S(n)$}\label{tri-app}

	Let us now apply the results from the previous subsection to $S(n)=\langle f_n^2, f_{n+1}^2, f_{n+2}^2 \rangle$ for $n\geq 4$, where $f_n$, $f_{n+1}$, $f_{n+2}$ are three consecutive Fibonacci numbers.

	\begin{lemma}\label{lem12tri}
		If $n\geq 4$, then $\kappa = 2$ and
		\[ \ell = \begin{cases} f_nf_{n-3}+1 \mbox{ if $n$ is even,} \\[3pt] 2f_nf_{n-2}+1 \mbox{ if $n$ is odd.}
		\end{cases} \]
	\end{lemma}

	\begin{proof}
		For $\kappa$, we have that
		\[ 2 < \frac{f_{n+2}^2}{f_{n+1}^2} < 3 \Longleftrightarrow 2 < \frac{f_{n+2}^2 - f_{n+1}^2}{f_{n+1}^2} + 1 < 3 \Longleftrightarrow f_{n+1}^2 < 2f_{n+1}f_n + f_n^2 < 2f_{n+1}^2. \]
		Observe that
		\begin{itemize}
			\item the left inequality $f_{n+1}^2 < 2f_{n+1}f_n + f_n^2\,$ is true because $f_{n+1} < 2f_n$,
			\item and the right inequality $2f_{n+1}f_n + f_n^2 < 2f_{n+1}^2$ is equivalent to $f_n^2 < 2f_{n+1}f_{n-1}$, which is true because $f_n < 2f_{n-1}$.
		\end{itemize}
		Therefore, $\kappa=2$.

		Now, for $\ell$, recalling that $f_{n+1}f_{n-1}-f_n^2=(-1)^n$ (Cassini's identity), we derive that
		\[ f_{n+1}^2f_{n-1}^2 = (f_{n+1}f_{n-1})^2 = (f_n^2+(-1)^n)^2 = f_n^4 + 2(-1)^nf_n^2 +1 \equiv 1 \pmod{f_n^2} \Longrightarrow b^{-1}=f_{n-1}^2. \]
		Then
		\[ cb^{-1} = f_{n+2}^2f_{n-1}^2 = f_{n+1}^2f_{n-1}^2 + 2f_{n+1}f^nf_{n-1}^2 + f_n^2f_{n-1}^2 = \]
		\[ (f_n^2+(-1)^n)^2 +2(f_n^2+(-1)^n)f_nf_{n-1} + f_n^2f_{n-1}^2 = \]
		\[ f_n^4 + 2(-1)^nf_n^2 + 1 +2f_n^3f_{n-1} + 2(-1)^nf_nf_{n-1} + f_n^2f_{n-1}^2 \equiv (2(-1)^nf_nf_{n-1}+1) \pmod{f_n^2}. \]
		Thus, if $n$ is even, then
		\[ \ell = 2f_nf_{n-1}+1 - f_n^2 = f_nf_{n-3}+1\]
		and, if $n$ is odd,
		\[ \ell = -2f_nf_{n-1}+1 + 2f_n^2 = 2f_nf_{n-2}+1.\]
	\end{proof}

	\begin{lemma}\label{lem13tri}
		If $n$ is even, then $q=1$, $r=\ell$,
		\[ \overline{q} = \begin{cases} 2, \mbox{ if } n=4, \\ 3, \mbox{ if } n=6, \\ 4, \mbox{ if } n\geq 8, \end{cases} \]
		and
		\[ \overline{r} = \begin{cases} 1, \mbox{ if } n=4, \\ 13, \mbox{ if } n=6, \\ f_nf_{n-6}-4, \mbox{ if } n\geq 8. \end{cases}  \]

		If $n$ is odd, then
		\[ q = \begin{cases} 6, \mbox{ if } n=5, \\ 4, \mbox{ if } n\geq 7, \end{cases} \]
		\[ r = \begin{cases} 1, \mbox{ if } n=5, \\ f_nf_{n-6}+4, \mbox{ if } n\geq 7, \end{cases}  \]
		$\overline{q}=1$, and $\overline{r}=f_nf_{n-3}-1$.
	\end{lemma}

	\begin{proof}
		Let us suppose that $n$ is even. For $n=4$ and $n=6$, we check the equalities by direct computation. Therefore, let us assume that $n\geq 8$.

		For $q$, we need to prove that
		\[1 < \frac{f_n^2}{f_n^2-f_nf_{n-3}-1} < 2,\]
		which is equivalent to
		\[ f_nf_{n-3}+1 < 2f_nf_{n-3}+2 < f_n^2. \]
		The left inequality is trivial, and the right one follows from the equality $f_n=3f_{n-3}+2f_{n-4}$.

		Now, since $q=1$, then $r=\ell$ from their definitions.

		For $\overline{q}$, we need to prove that
		\[ 4 < \frac{f_n^2}{f_nf_{n-3}+1} < 5, \]
		which (using again the equality $f_n=3f_{n-3}+2f_{n-4}$) is equivalent to
		\[ f_nf_{n-3}+4 < 2f_nf_{n-4} < 2f_nf_{n-3}+5. \]
		Here, the right inequality is trivial, and the left one follows from the inequality $4<f_nf_{n-6}$.

		Finally, $\overline{r} = f_n^2 - 4(f_nf_{n-3}-1) = f_n(f_n-4f_{n-3}) + 4 = f_nf_{n-6} + 4$.

		Using arguments similar to those already presented, the result follows for odd $n$.
	\end{proof}

	\begin{corollary}\label{cor14tri}
		Let $n\geq4$.
		\begin{itemize}
			\item If $n$ is even, then $br>cq$, and therefore we can apply Theorem~\ref{thm08tri5}.
			\item If $n=5$, then $br<cq$, and therefore we can apply Theorem~\ref{thm02tri3}.
			\item If $n\geq7$ is odd, then $br>cq$, and therefore we can apply Theorem~\ref{thm08tri5}.
		\end{itemize}
	\end{corollary}

	\begin{proof}
		If $n\geq4$ is even, then we have that
		\[ br>cq \Longleftrightarrow f_{n+1}^2(f_nf_{n-3}+1) > f_{n+2}^2\cdot1 \Longleftrightarrow f_{n+1}^2f_{n-3} > f_{n+3} \Longleftrightarrow f_{n+1}f_{n-3} > 2 + \frac{f_n}{f_{n+1}}, \]
		which is true since $f_{n+1}f_{n-3} > 3$ for all $n\geq4$.

		For $n=5$, we have that $br=64\cdot1<169\cdot6=cq$.

		Finally, if $n\geq7$ is odd, then
		\[ br>cq \Longleftrightarrow f_{n+1}^2(f_nf_{n-6}+4) > f_{n+2}^2\cdot1 \Longleftrightarrow f_nf_{n-6}+3 > 2\frac{f_n}{f_{n+1}} + \left(\frac{f_n}{f_{n+1}}\right)^2, \]
		which is true since $f_nf_{n-6}>0$ and $3 > 2\frac{f_n}{f_{n+1}} + \left(\frac{f_n}{f_{n+1}}\right)^2$ for all $n\geq7$.
	\end{proof}

	\begin{lemma}\label{lem15tri}
		If $n$ is even, then
		\[ u = \begin{cases} 1, \mbox{ if } n=4, \\ 13, \mbox{ if } n=6, \\ f_nf_{n-6}-4, \mbox{ if } n\geq 8.
		\end{cases}\]

		If $n\geq 7$ is odd, then
		\[ u = \begin{cases} 4, \mbox{ if } n=7, \\ 55, \mbox{ if } n=9, \\ f_nf_{n-9}-17, \mbox{ if } n\geq 11.
		\end{cases}\]
	\end{lemma}

	\begin{proof}
		If $n\in\{4,6,7,9\}$, then we deduce the result by direct calculation.

		If $n\geq8$ is even, then
		\[ f_n^2 - (f_nf_{n-3}+1) = 4f_nf_{n-3} + f_nf_{n-6} - (f_nf_{n-3}+1) = 3(f_nf_{n-3}+1) +(f_nf_{n-6} - 4), \]
		and the result follows from $0 < f_nf_{n-6} - 4 < f_nf_{n-3}+1$.

		If $n\geq11$ is odd, then
		\[ f_n^2 - (2f_nf_{n-2}+1) = f_nf_{n-3} - 1 = 4(f_nf_{n-6}+4) +(f_nf_{n-9} - 17). \]
		Since $0 < f_nf_{n-9} - 17 < f_nf_{n-6}+4$, the result is proved.
	\end{proof}

	\begin{claim}\label{claim16tri}
		If $n\geq 4$ is even, then
		\[ \mu' = \begin{cases} f_{n-3}-1, \mbox{ if } n\equiv 1 \pmod{3}, \\ \frac{f_{n-3}}{2}-1, \mbox{ if } n\equiv 0 \pmod{3}, \\ \frac{f_{n-2}}{2}-1, \mbox{ if } n\equiv 2 \pmod{3}.
		\end{cases}\]

		If $n\geq 7$ is odd, then
		\[ \mu' = \begin{cases} f_{n-6}-1, \mbox{ if } n\equiv 1 \pmod{3}, \\ \frac{f_{n-6}}{2}-1, \mbox{ if } n\equiv 0 \pmod{3}, \\ \frac{f_{n-5}}{2}-1, \mbox{ if } n\equiv 2 \pmod{3}.
		\end{cases}\]
	\end{claim}

	\begin{corollary}\label{cor17tri}
		It holds that:
		\begin{itemize}
			\item If $n\in\{4,6,8\}$, then $\mu'<\left\lfloor \frac{r}{u} \right\rfloor$, and therefore we can apply Theorem~\ref{thm08tri5}(a).
			\item If $n\geq 10$ is even, then $\mu'>\left\lfloor \frac{r}{u} \right\rfloor$, and therefore we can apply Theorem~\ref{thm08tri5}(b).
			\item If $n\in\{7,9,11\}$, then $\mu'<\left\lfloor \frac{r}{u} \right\rfloor$, and therefore we can apply Theorem~\ref{thm08tri5}(a).
			\item If $n\geq13$ is odd, then $\mu'>\left\lfloor \frac{r}{u} \right\rfloor$, and therefore we can apply Theorem~\ref{thm08tri5}(b).
		\end{itemize}
	\end{corollary}

	\begin{proof}
		If $n\in\{4,6,7,8,9,11\}$, we deduce the result by direct calculation.

		For $n\geq10$ even, we have that $\mu'>13$. Moreover,
		\[ \left\lfloor \frac{r}{u} \right\rfloor = \left\lfloor \frac{f_nf_{n-3}+1}{f_nf_{n-6}-4} \right\rfloor = 3+\left\lfloor \frac{2f_nf_{n-7}+13}{f_nf_{n-6}-4} \right\rfloor. \]
		Now,
		\[ 10 > \frac{2f_nf_{n-7}+13}{f_nf_{n-6}-4} \Longleftrightarrow 10f_nf_{n-6} > 2f_nf_{n-7}+53, \]
		which is true since $8f_nf_{n-6} > 53$ for all $n\geq10$.		

		For $n\geq13$ odd, we have that $\mu'>12$. Moreover,
		\[ \left\lfloor \frac{r}{u} \right\rfloor = \left\lfloor \frac{f_nf_{n-6}+4}{f_nf_{n-9}-17} \right\rfloor = 3+\left\lfloor \frac{2f_nf_{n-10}+55}{f_nf_{n-9}-17} \right\rfloor. \]
		Now,
		\[ 9 > \frac{2f_nf_{n-10}+55}{f_nf_{n-9}-17} \Longleftrightarrow 9f_nf_{n-9} > 2f_nf_{n-10}+208 \]
		which is true since $7f_nf_{n-9} > 208$ for all $n\geq13$.
	\end{proof}

	\begin{claim}\label{claim18tri}
		If $n\geq 10$ is even, then the applicable values in Theorem~\ref{thm08tri5}(b) are
		\[ \begin{cases} d_1 = \frac{f_{n-1}}{2},\, d_2 = \frac{f_{n+2}}{2},\, p_1 = f_{n-3}-1,\, p_2 = \frac{f_{n-3}+f_{n-5}}{2}-1, \mbox{ if } n\equiv 1 \pmod{3}, \\[3pt] d_1 = f_{n+1},\, d_2 = \frac{f_{n+3}}{2},\, p_1 = \frac{f_{n-3}}{2}-1,\, p_2 = f_{n-5}-1, \mbox{ if } n\equiv 0 \pmod{3}, \\[3pt] d_1 = \frac{f_{n+1}}{2},\, d_2 = f_{n+2},\, p_1 = \frac{f_{n-2}}{2}-1,\, p_2 = \frac{f_{n-5}}{2}-1, \mbox{ if } n\equiv 2 \pmod{3}.
		\end{cases}\]

		If $n\geq 13$ is odd, then the applicable values in Theorem~\ref{thm08tri5}(b) are
		\[ \begin{cases} d_1 = \frac{f_{n-1}}{2},\, d_2 = \frac{f_{n+2}}{2},\, p_1 = f_{n-6}-1,\, p_2 = \frac{f_{n-6}+f_{n-8}}{2}-1, \mbox{ if } n\equiv 1 \pmod{3}, \\[3pt] d_1 = f_{n+1},\, d_2 = \frac{f_{n+3}}{2},\, p_1 = \frac{f_{n-6}}{2}-1,\, p_2 = f_{n-8}-1, \mbox{ if } n\equiv 0 \pmod{3}, \\[3pt] d_1 = \frac{f_{n+1}}{2},\, d_2 = f_{n+2},\, p_1 = \frac{f_{n-5}}{2}-1,\, p_2 = \frac{f_{n-8}}{2}-1, \mbox{ if } n\equiv 2 \pmod{3}.
		\end{cases}\]
	\end{claim}

	\begin{remark}\label{rem19tri}
