	\section{Algorithmic process by Rosales and Garc{\'i}a-S{\'a}nchez}\label{rgs}

	First, we present the key result for this section.

	\begin{lemma}\label{lem02rgs}
		If $n\geq8$, then
		\begin{enumerate}
			\item $f_{n+4}f_n^2 = f_{n+1}f_{n+1}^2 + f_{n-2}f_{n+2}^2$.
			\item $f_{n+2}f_{n+1}^2 = f_{n+2}f_n^2 + f_{n-1}f_{n+2}^2$.
			\item $f_n f_{n+2}^2 = f_{n+3} f_n^2 + f_n f_{n+1}^2$.
		\end{enumerate}
	\end{lemma}

	\begin{proof}
		\begin{enumerate}
			\item Since $f_{n+1} f_{n+1}^2 = f_{n+1}^3 = (f_{n+2}-f_n)^3 = f_{n+2}^3 - 3f_{n+2}^2 f_n + 3f_{n+2} f_n^2 - f_n^3 = (3f_{n+2} - f_n)f_n^2 + (f_{n+2}-3f_n)f_{n+2}^2 = f_{n+4}f_n^2 - f_{n-2}f_{n+2}^2$, we deduce the equality.

			\item Since $f_{n+1}^2 = (f_{n+2}-f_n)^2 = f_{n+2}^2 - 2f_{n+2} f_n + f_n^2 = (f_{n+2}-2f_n)f_{n+2} + f_n^2 = f_{n-1} f_{n+2} + f_n^2$, then we have that $f_{n+2} f_{n+1}^2 = f_{n+2} f_n^2 + f_{n-1} f_{n+2}^2$.

			\item Since $f_{n+2}^2 = (f_{n+1}+f_n)^2 = f_{n+1}^2 + 2f_{n+1}f_n + f_n^2 = f_{n+1}^2 + (2f_{n+1}+f_n)f_n = f_{n+1}^2 + f_{n+3}f_n$, it follows that 
			$f_n f_{n+2}^2 = f_{n+3} f_n^2 + f_n f_{n+1}^2$.

			Expression 3 can also be obtained by adding Expressions 1 and 2 and then rearranging the terms of the resulting expression.
		\end{enumerate}
	\end{proof}

	As usual, $\#A$ represents the cardinality of the set $A$.

	\begin{lemma}\label{lem03rgs}
		$\#\big\{ \{0,\dots,f_{n+2}-1\} \times \{0,\dots,f_n-1\} \setminus \{f_{n+1},\dots,f_{n+2}-1\} \times \{f_{n-2},\dots,f_n-1\} \big\} = 2f_n^2$.
	\end{lemma}

	\begin{proof}
		$\#\big\{ \{0,\dots,f_{n+2}-1\} \times \{0,\dots,f_n-1\} \setminus \{f_{n+1},\dots,f_{n+2}-1\} \times \{f_{n-2},\dots,f_n-1\} \big\} = f_{n+2}f_n - \left( f_{n+2}-f_{n+1} \right) \left( f_n-f_{n-2} \right) = f_{n+2}f_n - f_nf_{n-1} = f_n \left( f_{n+2}-f_{n-1} \right) = 2f_n^2$.
	\end{proof}

	\begin{remark}\label{rem04rgs}
		As a consequence of Lemma~\ref{lem02rgs}, we have that $\mathrm{Ap}(S(n),f_n^2) \subseteq \big\{ \lambda f_{n+1}^2 + \mu f_{n+2}^2 \mid (\lambda,\mu)\in \{0,\dots,f_{n+2}-1\} \times \{0,\dots,f_n-1\} \setminus \{f_{n+1},\dots,f_{n+2}-1\} \times \{f_{n-2},\dots,f_n-1\} \big\}$. However, the equality is not true as a consequence of Lemma~\ref{lem03rgs}.
	\end{remark}

	\begin{example}\label{exmp05rgs}
		For $S(4)=\langle 9,25,64 \rangle$, we have that
		\[ \mathrm{Ap}(S(4),9) = \{ 0,64,128,75,139,50,114,25,89\}. \]
		Moreover, by Remark~\ref{rem04rgs}, it follows that
		\[ \mathrm{Ap}(S(4),9) \subseteq \big\{ \lambda f_{n+1}^2 + \mu f_{n+2}^2 \mid (\lambda,\mu)\in \{(0,0), (0,1), (0,2), (1,0), (1,1), (1,2), (2,0), (2,1), (2,2), \] \[ (3,0), (3,1), (3,2), (4,0), (4,1), (4,2), (5,0), (6,0), (7,0)\} \big\} = \]
		\[ \{ 0, 64, 128, 25, 29,153, 50, 114, 178, 75, 139, 203, 100, 164, 228, 125, 150, 175 \}. \]
		Observe that for each $i\in\{0,1,\dots,8\}$ there appear two elements congruent to $i$ modulo $9$.
	\end{example}

	The following result is easy to prove by induction on $k$.

	\begin{lemma}\label{lem06rgs}
		If $k\in\mathbb{N}$, then $f_{3k}$ is even, while $f_{3k+1}$ and $f_{3k+2}$ are odd.
	\end{lemma}

	To improve Lemma~\ref{lem02rgs}, we analyse three cases that depend on the parity of $f_n$, $f_{n+1}$, and $f_{n+2}$. We begin with the case where $f_n$ is even (and therefore $f_{n+1}$ and $f_{n+2}$ are odd).

	\begin{lemma}\label{lem14rgs}
		If $f_n$ is even (that is, $n=3k$ with $k\in\mathbb{N}\setminus\{0,1\}$), then
		\begin{enumerate}
			\item $f_{n+4}f_n^2 = f_{n+1}f_{n+1}^2 + f_{n-2}f_{n+2}^2$.
			\item $\frac{f_{n+3}}{2}f_{n+1}^2 = \frac{f_{n+2}+f_{n+4}}{2} f_n^2 + \frac{f_{n-3}}{2}f_{n+2}^2$.
			\item $\frac{f_n}{2}f_{n+2}^2 = \frac{f_{n+3}}{2}f_n^2 + \frac{f_n}{2}f_{n+1}^2$.
		\end{enumerate}
	\end{lemma}

	\begin{proof}
		Expression 1 is Expression 1 of Lemma~\ref{lem02rgs}.

		On the other hand, since $f_n$ is even, then$f_{n+3}$ is also even (Lemma~\ref{lem06rgs}). This allows us to deduce Expression 3 from Expression 3 of Lemma~\ref{lem02rgs}.

		Finally, considering that $f_{n-3}$ is even and, by Lemma~\ref{lem06rgs}, that $f_{n+2}$ and $f_{n+4}$ are odd (and therefore $f_{n+2}+f_{n+4}$ is even), then (adding Expressions 1 and 3)
		\[ f_{n+4}f_n^2 + \frac{f_n}{2} f_{n+2}^2 = f_{n+1}f_{n+1}^2 + f_{n-2}f_{n+2}^2 + \frac{f_{n+3}}{2} f_n^2 + \frac{f_n}{2} f_{n+1}^2 \Rightarrow \]
		\[ \left(f_{n+4} - \frac{f_{n+3}}{2} \right)f_n^2 + \left(\frac{f_n}{2} - f_{n-2}\right)f_{n+2}^2 = \left(f_{n+1}+\frac{f_n}{2}\right)f_{n+1}^2, \]
		from which follows Expression 2.
	\end{proof}

	\begin{proposition}\label{prop15rgs}
		If $f_n$ is even (that is, $n=3k$ with $k\in\mathbb{N}\setminus\{0,1\}$), then
		\[ \mathrm{Ap}(S(n),f_n^2) = \left\{ \lambda f_{n+1}^2 + \mu f_{n+2}^2 \mid (\lambda,\mu)\in C_1 \times C_2 \setminus C_3 \times C_4 \right\}, \]
		where
		\[ C_1=\left\{0,\dots,\frac{f_{n+3}}{2}-1\right\}, \;\;
		C_2=\left\{0,\dots,\frac{f_n}{2}-1\right\}, \]
		\[ C_3=\left\{f_{n+1},\dots,\frac{f_{n+3}}{2}-1\right\}, \;\; C_4=\left\{f_{n-2},\dots,\frac{f_n}{2}-1\right\}. \]
	\end{proposition}

	\begin{proof}
		By Lemma~\ref{lem14rgs}, we have that $\mathrm{Ap}(S(n),f_n^2) \subseteq \left\{ \lambda f_{n+1}^2 + \mu f_{n+2}^2 \mid (\lambda,\mu)\in C_1 \times C_2 \setminus C_3 \times C_4 \right\}$.

		On the other hand,
		\[ \#\left[ \left\{0,\dots,\frac{f_{n+3}}{2}-1 \right\} \times \left\{0,\dots,\frac{f_n}{2}-1 \right\} \setminus \left\{f_{n+1},\dots,\frac{f_{n+3}}{2}-1 \right\} \times \left\{f_{n-2},\dots,\frac{f_n}{2}-1 \right\} \right] = \]
		\[ \frac{f_{n+3}}{2} \times \frac{f_n}{2} - \left( \frac{f_{n+3}}{2} - f_{n+1} \right) \times \left( \frac{f_n}{2} - f_{n-2} \right) = \frac{f_{n+3}f_n - f_nf_{n-3}}{4} = f_n\frac{f_{n+3} - f_{n-3}}{4} = f_n^2. \]
		Since $\#\mathrm{Ap}(S(n),f_n^2)=f_n^2$, the result is proved.
	\end{proof}

	\begin{example}\label{exmp16rgs}
		For $n=6$, we have that $S(6)=\langle 64,169,441 \rangle$ and, by applying Proposition~\ref{prop15rgs},
		\[ \mathrm{Ap}(S(6),64) = \big\{ 169\lambda + 441\mu \mid (\lambda,\mu)\in \{0,\dots,16\} \times \{0,1,2,3\} \setminus \{13,14,15,16\} \times \{3\} \big\}. \]
	\end{example}

	Let us now see what happens when $f_{n+1}$ is even (and therefore $f_n$ and $f_{n+2}$ are odd).

	\begin{lemma}\label{lem11rgs}
		If $f_{n+1}$ is even (that is, if $n=3k-1$ with $k\in\mathbb{N}\setminus\{0,1\}$), then
		\begin{enumerate}
			\item $\frac{f_{n+4}}{2}f_n^2 = \frac{f_{n+1}}{2}f_{n+1}^2 + \frac{f_{n-2}}{2}f_{n+2}^2$.
			\item $f_{n+2}f_{n+1}^2 = f_{n+2}f_n^2 + f_{n-1}f_{n+2}^2$.
			\item $\frac{f_{n+1}}{2}f_{n+2}^2 = \frac{f_{n+1}}{2}f_n^2 + \frac{f_n+f_{n+2}}{2}f_{n+1}^2$.
		\end{enumerate}
	\end{lemma}
	\begin{proof}
		Expression 2 is Expression 2 of Lemma~\ref{lem02rgs}.

		On the other hand, since $f_{n+1}$ is even, then $f_{n-2}$ and $f_{n+4}$ are also even (Lemma~\ref{lem06rgs}). Thereby, we can deduce Expression 1 from Expression 1 of Lemma~\ref{lem02}.

		Finally, having in mind that $f_n$ and $f_{n+2}$ are odd (Lemma~\ref{lem06rgs}), then $f_n+f_{n+2}$ is even. Therefore (adding Expressions 1 and 2)
		\[ \frac{f_{n+4}}{2}f_n^2 + f_{n+2}f_{n+1}^2 = \frac{f_{n+1}}{2}f_{n+1}^2 + \frac{f_{n-2}}{2}f_{n+2}^2 + f_{n+2}f_n^2 + f_{n-1}f_{n+2}^2 \Rightarrow \]
		\[ \left(\frac{f_{n+4}}{2} - f_{n+2} \right)f_n^2 + \left(f_{n+2} - \frac{f_{n+1}}{2}\right)f_{n+1}^2 = \left(\frac{f_{n-2}}{2} + f_{n-1}\right)f_{n+2}^2, \]
		from which we deduce Expression 3.
	\end{proof}

	\begin{proposition}\label{prop12rgs}
		If $f_{n+1}$ is even (that is, if $n=3k-1$ with $k\in\mathbb{N}\setminus\{0,1\}$), then
		\[ \mathrm{Ap}(S(n),f_n^2) = \left\{ \lambda f_{n+1}^2 + \mu f_{n+2}^2 \mid (\lambda,\mu)\in C_1 \times C_2 \setminus C_3 \times C_4 \right\}, \]
		where
		\[ C_1=\{0,\dots,f_{n+2}-1\}, \;\; C_2=\left\{0,\dots,\frac{f_{n+1}}{2}-1\right\} \]
		\[ C_3=\left\{\frac{f_{n+1}}{2},\dots,f_{n+2}-1\right\}, \;\; C_4=\left\{\frac{f_{n-2}}{2},\dots,\frac{f_{n+1}}{2}-1\right\}. \]
	\end{proposition}

	\begin{proof}
		By Lemma~\ref{lem11rgs}, we have that $\mathrm{Ap}(S(n),f_n^2) \subseteq \left\{ \lambda f_{n+1}^2 + \mu f_{n+2}^2 \mid (\lambda,\mu)\in C_1 \times C_2 \setminus C_3 \times C_4 \right\}$.

		Since
		\[ \#\left[ \{0,\dots,f_{n+2}-1\} \times \left\{0,\dots,\frac{f_{n+1}}{2}-1\right\} \setminus \left\{\frac{f_{n+1}}{2},\dots,f_{n+2}-1\right\} \times \left\{\frac{f_{n-2}}{2},\dots,\frac{f_{n+1}}{2}-1\right\} \right] = \]
		\[ f_{n+2} \times \frac{f_{n+1}}{2} - \left( f_{n+2} - \frac{f_{n+1}}{2} \right) \times \left( \frac{f_{n+1}}{2} - \frac{f_{n-2}}{2} \right) = \frac{f_{n+2}f_{n-2}}{2} + \frac{f_{n+1}(f_{n+1}-f_{n-2})}{4} = \]
		\[ \frac{f_{n+1}f_{n-2} + f_{n}f_{n-2}}{2} + \frac{f_{n+1}f_{n-1}}{2} = \frac{f_{n+1}f_n + f_{n}f_{n-2}}{2} = f_n\frac{f_{n+1} + f_{n-2}}{2} = f_n^2, \]
		the result is proved.
	\end{proof}

	\begin{example}\label{exmp13rgs}
		For $n=5$, we have that $S(5)=\langle 25,64,169 \rangle$ and, by applying Proposition~\ref{prop12rgs}, we conclude that
		\[ \mathrm{Ap}(S(5),25) = \big\{ 64\lambda + 169\mu \mid (\lambda,\mu)\in \{0,\dots,12\} \times \{0,1,2,3\} \setminus \{4,\dots,12\} \times \{1,2,3\} \big\}. \]
	\end{example}

	Finally, we show the case when $f_{n+2}$ is even (and therefore $f_n$ and $f_{n+1}$ are odd).

	\begin{lemma}\label{lem07rgs}
		If $f_{n+2}$ is even (that is, if $n=3k-2$ with $k\in\mathbb{N}\setminus\{0,1\}$), then
		\begin{enumerate}
			\item $\frac{f_{n+5}}{2}f_n^2 = \frac{f_{n-1}}{2}f_{n+1}^2 + \frac{f_{n-2}+f_n}{2}f_{n+2}^2$.
			\item $\frac{f_{n+2}}{2}f_{n+1}^2 = \frac{f_{n+2}}{2}f_n^2 + \frac{f_{n-1}}{2}f_{n+2}^2$.
			\item $f_nf_{n+2}^2 = f_{n+3}f_n^2 + f_nf_{n+1}^2$.
		\end{enumerate}
	\end{lemma}
	\begin{proof}
		Expression 3 is Expression 3 of Lemma~\ref{lem02rgs}.

		On the other hand, since $f_{n+2}$ is even, then $f_{n-1}$ is also even (Lemma~\ref{lem06rgs}). Therefore, we deduce Expression 2 from Expression 2 of Lemma~\ref{lem02rgs}.

		At last, since $f_{n+5}$ is even and $f_{n-2}$ are $f_n$ odd (Lemma~\ref{lem06rgs}) (and, consequently, $f_{n-2}+f_n$ is even), then (adding Expressions 2 and 3)
		\[ \frac{f_{n+2}}{2}f_{n+1}^2 + f_nf_{n+2}^2 = \frac{f_{n+2}}{2}f_n^2 + \frac{f_{n-1}}{2}f_{n+2}^2 + f_{n+3}f_n^2 + f_nf_{n+1}^2 \Rightarrow \]
		\[ \left(\frac{f_{n+2}}{2} - f_n \right)f_{n+1}^2 + \left(f_n - \frac{f_{n-1}}{2}\right)f_{n+2}^2 = \left(\frac{f_{n+2}}{2} + f_{n+3}\right)f_n^2, \]
		from we get Expression 1.
	\end{proof}

	\begin{proposition}\label{prop08rgs}
		If $f_{n+2}$ is even (that is, if $n=3k-2$ with $k\in\mathbb{N}\setminus\{0,1\}$), then
		\[ \mathrm{Ap}(S(n),f_n^2) = \left\{ \lambda f_{n+1}^2 + \mu f_{n+2}^2 \mid (\lambda,\mu)\in C_1 \times C_2 \setminus C_3 \times C_4 \right\}, \]
		where
		\[ C_1=\left\{0,\dots,\frac{f_{n+2}}{2}-1\right\}, \;\; C_2=\{0,\dots,f_n-1\}, \]
		\[ C_3=\left\{\frac{f_{n-1}}{2},\dots,\frac{f_{n+2}}{2}-1\right\}, \;\; C_4=\left\{\frac{f_{n-2}+f_n}{2},\dots,f_n-1\right\}. \]
	\end{proposition}

	\begin{proof}
		By Lemma~\ref{lem07rgs}, we have that $\mathrm{Ap}(S(n),f_n^2) \subseteq \left\{ \lambda f_{n+1}^2 + \mu f_{n+2}^2 \mid (\lambda,\mu)\in C_1 \times C_2 \setminus C_3 \times C_4 \right\}$.

		Since
		\[ \#\left[ \left\{0,\dots,\frac{f_{n+2}}{2}-1\right\} \times \{0,\dots,f_n-1\} \setminus \left\{\frac{f_{n-1}}{2},\dots,\frac{f_{n+2}}{2}-1\right\} \times \left\{\frac{f_{n-2}+f_n}{2},\dots,f_n-1\right\} \right] = \]
		\[ \frac{f_{n+2}}{2} \times f_n - \left( \frac{f_{n+2}}{2} - \frac{f_{n-1}}{2} \right) \times \left( f_n - \frac{f_{n-2}+f_n}{2} \right) = \frac{f_{n+2}}{2}f_n - f_n\frac{f_n-f_{n-2}}{2} = f_n\frac{f_{n+2} - f_{n-1}}{2} = f_n^2, \]
		we have the result.
	\end{proof}

	\begin{example}\label{exmp09rgs}
		For $n=4$, we have that $S(4)=\langle 9,25,64 \rangle$ and, by applying Proposition~\ref{prop08rgs},
		\[ \mathrm{Ap}(S(4),9) = \big\{ 25\lambda + 64\mu \mid (\lambda,\mu)\in \{0,1,2,3\} \times \{0,1,2\} \setminus \{1,2,3\} \times \{2\} \big\}. \]
	\end{example}

	By Proposition~\ref{prop15rgs}, \ref{prop12rgs}, and \ref{prop08rgs}, we deduce the main result of this section.

	\begin{theorem}\label{thm17rgs}
		Let $n\geq4$.
		\begin{enumerate}
			\item If $f_n$ is even (that is, if $n=3k$ with $k\in\mathbb{N}\setminus\{0,1\}$), then $\mathrm{PF}(S(n)) =$
			\[ \left\{ (f_{n+1}-1)f_{n+1}^2 + \left(\frac{f_n}{2}-1\right)f_{n+2}^2 - f_n^2, \left(\frac{f_{n+3}}{2}-1\right)f_{n+1}^2 + (f_{n-2}-1)f_{n+2}^2 - f_n^2 \right\}. \]
			\item If $f_{n+1}$ is even (that is, if $n=3k-1$ with $k\in\mathbb{N}\setminus\{0,1\}$), then $\mathrm{PF}(S(n)) =$
			\[ \left\{ \left(\frac{f_{n+1}}{2}-1\right)f_{n+1}^2 + \left(\frac{f_{n+1}}{2}-1\right)f_{n+2}^2 - f_n^2, (f_{n+2}-1)f_{n+1}^2 + \left(\frac{f_{n-2}}{2}-1\right)f_{n+2}^2 - f_n^2 \right\}. \]
			\item If $f_{n+2}$ is even (that is, if $n=3k-2$ with $k\in\mathbb{N}\setminus\{0,1\}$), then $\mathrm{PF}(S(n)) =$
			\[ \left\{ \left(\frac{f_{n-1}}{2}-1\right)f_{n+1}^2 + (f_n-1)f_{n+2}^2 - f_n^2, \left(\frac{f_{n+2}}{2}-1\right)f_{n+1}^2 + \left(\frac{f_{n-2}+f_n}{2}-1\right)f_{n+2}^2 - f_n^2 \right\}. \]
		\end{enumerate}
	\end{theorem}

	The solution to the proposed Frobenius problem is derived directly from the above theorem.

	\begin{corollary}\label{cor18rgs}
		Let $n\geq4$.
		\begin{enumerate}
			\item If $f_n$ is even (that is, if $n=3k$ with $k\in\mathbb{N}\setminus\{0,1\}$), then
			\[ \mathrm{F}(S(n)) = \left(\frac{f_{n+3}}{2}-1\right)f_{n+1}^2 + (f_{n-2}-1)f_{n+2}^2 - f_n^2. \]
			\item If $f_{n+1}$ is even (that is, if $n=3k-1$ with $k\in\mathbb{N}\setminus\{0,1\}$), then
			\[ \mathrm{F}(S(n)) = (f_{n+2}-1)f_{n+1}^2 + \left(\frac{f_{n-2}}{2}-1\right)f_{n+2}^2 - f_n^2. \]
			\item If $f_{n+2}$ is even (that is, if $n=3k-2$ with $k\in\mathbb{N}\setminus\{0,1\}$), then
			\[ \mathrm{F}(S(n)) = \left(\frac{f_{n+2}}{2}-1\right)f_{n+1}^2 + \left(\frac{f_{n-2}+f_n}{2}-1\right)f_{n+2}^2 - f_n^2. \]
		\end{enumerate}
	\end{corollary}

	\begin{proof}
		\begin{enumerate}
			\item We have that
			\[ (f_{n+1}-1)f_{n+1}^2 + \left(\frac{f_n}{2}-1\right)f_{n+2}^2 - f_n^2 < \left(\frac{f_{n+3}}{2}-1\right)f_{n+1}^2 + (f_{n-2}-1)f_{n+2}^2 -f_n^2 \Longleftrightarrow \]
			\[ 2f_{n+1}f_{n+1}^2 + f_nf_{n+2}^2 < f_{n+3}f_{n+1}^2 + 2f_{n-2}f_{n+2}^2 \Longleftrightarrow f_{n-3}f_{n+2}^2 < f_nf_{n+1}^2 \Longleftrightarrow \]
			\[ 2f_{n-3}f_nf_{n+1} + f_{n-3}f_n^2 < 2f_{n-2}f_{n+1}^2 \Longleftrightarrow f_{n-3}f_n^2 < 2(f_{n-4}f_n+f_{n-2}f_{n-1})f_{n+1}. \]
			Since $f_n < 2f_{n-1}$ for all $n\geq 4$, then $f_{n-3}\cdot f_n\cdot f_n < f_{n-2}\cdot 2f_{n-1}\cdot f_{n+1}$ and the result is proved.

			\item We have that
			\[ \left(\frac{f_{n+1}}{2}-1\right)f_{n+1}^2 + \left(\frac{f_{n+1}}{2}-1\right)f_{n+2}^2 - f_n^2 < (f_{n+2}-1)f_{n+1}^2 + \left(\frac{f_{n-2}}{2}-1\right)f_{n+2}^2 - f_n^2 \Longleftrightarrow \]
			\[ f_{n+1}f_{n+1}^2 + f_{n+1}f_{n+2}^2 < 2f_{n+2}f_{n+1}^2 + f_{n-2}f_{n+2}^2 \Longleftrightarrow f_{n+1}^3 < f_{n-1}f_{n+1}f_{n+2} + f_{n-2}f_{n+2}^2 \Longleftrightarrow \]
			\[ 2f_{n-1}f_{n+1}^2 < f_{n-1}f_{n+1}f_{n+2} + 2f_{n-2}f_nf_{n+1} + f_{n-2}f_n^2 \Longleftrightarrow f_{n-1}^2f_{n+1} < 2f_{n-2}f_nf_{n+1} + f_{n-2}f_n^2. \]
			Since $f_{n-1} < 2f_{n-2}$ for all $n\geq 4$, then $f_{n-1}\cdot f_{n-1}\cdot f_{n+1} < 2f_{n-2}\cdot f_n\cdot f_{n+1}$ and the result is proved.

			\item We have that
			\[ \left(\frac{f_{n-1}}{2}-1\right)f_{n+1}^2 + (f_n-1)f_{n+2}^2 - f_n^2 < \left(\frac{f_{n+2}}{2}-1\right)f_{n+1}^2 + \left(\frac{f_{n-2}+f_n}{2}-1\right)f_{n+2}^2 - f_n^2 \Longleftrightarrow \]
			\[ f_{n-1}f_{n+1}^2 + 2f_nf_{n+2} < f_{n+2}f_{n+1}^2 + (f_{n-2}+f_n)f_{n+2}^2 \Longleftrightarrow f_{n-1}f_{n+2}^2 < 2f_nf_{n+1}^2 \Longleftrightarrow \]
			\[ f_{n-1}f_{n+1}^2 + f_{n-1}f_n^2 < 2f_n^2f_{n+1} \Longleftrightarrow 2f_{n-1}^2f_n + f_{n-1}^3 < 2f_n^3 \Longleftrightarrow f_{n-1}^3 < 2f_{n-2}f_nf_{n+1}. \]
			Since $f_{n-1} < 2f_{n-2}$ for all $n\geq 4$, then $f_{n-1}\cdot f_{n-1}\cdot f_{n-1} < 2f_{n-2}\cdot f_n\cdot f_{n+1}$ and the result is proved.
		\end{enumerate}
	\end{proof}

	We finish with an illustrative example.

	\begin{example}\label{exmp19rgs}
		\begin{enumerate}
			\item $S(4)=\langle 9,25,64 \rangle$, $\mathrm{PF}(S(4))=\{119,130\}$, and $\mathrm{F}(S(4))=130$.			
			\item $S(5)=\langle 25,64,169 \rangle$, $\mathrm{PF}(S(5))=\{674,743\}$, and $\mathrm{F}(S(5))=743$.
			\item $S(6)=\langle 64,169,441 \rangle$, $\mathrm{PF}(S(6))=\{3287,3522\}$, and $\mathrm{F}(S(6))=3522$.
		\end{enumerate}
	\end{example}



	\section{Conclusions}\label{conclusions}

	After reviewing Sections \ref{rar}, \ref{tri}, and \ref{rgs}, we believe that the algorithmic process proposed by Rosales and Garc{\'i}a-S{\'a}nchez is more convenient than those by Ram{\'i}rez Alfons{\'i}n and R{\o}dseth or Tripathy for finding a general formula to solve the Frobenius problem for a family of numerical semigroups. In fact, all steps in Section \ref{rgs} have been rigorously proven. However, in Sections \ref{rar} and \ref{tri}, we have not been able to demonstrate all the results. Furthermore, we even had to propose alternative statements for some results in Subsection \ref{tri-pre} because several errors were detected in the original paper (\cite{tripathi}). These results were also mentioned, without proofs, in \cite{suhajda}.

	As future work, we propose to provide rigorous proofs for all claims in Section \ref{rar} (we suspect this will require using continued fractions and difference equations) and Subsection \ref{tri-app} (currently, we have no ideas about possible tools to use). Additionally, we aim to prove the alternative statements of the theorems in Subsection \ref{tri-app}, for which we also lack immediate ideas on the necessary tools.



