\subsection{The Defender's Strategy}
\label{sec:def_strategy}
 First we start by restating Lorden's asymptotic optimality results on $T^*(\mu)$. Consider a sequence $U_1, U_2, \ldots$ where $U_1,U_2, \ldots, U_{\nu-1}$ are i.i.d samples from $F_0$ and $U_{\nu},U_{\nu+1},\ldots$ are i.i.d. samples from a parameterized distribution $F_\theta$ with an unknown parameter $\theta\in\Theta$. Proposition \ref{prop:sprt_to_GenCusum} shows how to construct an optimal change detection scheme from one-sided tests, which clarifies the relation between Definition \ref{def:GenSPRT} and Definition \ref{def:Gen_cusum}, and explains the motivation behind defining $T^*$ in Definition \ref{def:Gen_cusum}. Proposition \ref{prop:exponent_family} presents sufficient conditions for one-sided tests to satisfy the requirements of Proposition \ref{prop:sprt_to_GenCusum}. Note that here the optimality criteria are in Lorden's sense, i.e., minimizing the mean detection delay $$W_\theta(T)=\sup_{\nu\geq1} \text{ess sup } \mathbb{E}^{(\nu)}_\theta[(T-\nu+1)^+|U_1,...,U_{\nu-1}],$$  where $\mathbb{E}^{(\nu)}_\theta$ denotes the expectation when the change of distribution to $F_\theta$ happens at time $\nu$. In the sequel, $\mathbb{E}_\theta$ is equivalent to $\mathbb{E}^{(0)}_\theta$.

\begin{proposition}
\label{prop:sprt_to_GenCusum}
(Theorem 1 in \cite{lorden1971_change}) Assume that there exists a class of one-sided tests $\lbrace \Bar{T}^\alpha\rbrace$ such that for all $0<\alpha<1$, 
\begin{equation}
\label{eq:flase-positive_condition}
    P(\Bar{T}^\alpha<\infty|\nu=\infty)\leq \alpha
\end{equation}
Moreover, assume that for all $\theta\in \Theta$, as $\alpha\rightarrow 0$ we have 
\begin{equation}
\label{eq:log_condition}
    \mathbb{E}_\theta[ \Bar{T}^\alpha] \sim \frac{|\log \alpha |}{D_{KL}(f_\theta||f_0)}, \ \ D_{KL}(f_\theta||f_0)<\infty
\end{equation}
For $\gamma\geq 1$, let $\alpha=\gamma^{-1}$ and define $T^\gamma=min_{k>1}\lbrace  \Bar{T}^\alpha_k+k-1\rbrace$, where $ \Bar{T}^\alpha_k$ is $ \Bar{T}^\alpha$ applied to $U_k,U_{k+1},\ldots$. Then $T^\gamma$ is a stopping variable with $\mathbb{E}^{(\infty)}[T]\geq\gamma$ that minimizes $W_\theta(T)$ for all $\theta \in \Theta$ as $\gamma \rightarrow \infty$, and we have 
\begin{equation}
\label{eq:GenCusum_performance}
    \mathbb{E}_\theta[T^\gamma] \sim  \frac{\log \gamma }{D_{KL}(f_\theta||f_0)}\quad  \text{as } \gamma \rightarrow \infty.
\end{equation}
\end{proposition}

\begin{proposition}
\label{prop:exponent_family}
    Suppose $F_\theta$'s are members of an exponential family of distributions such that 
    \begin{equation}
    \label{eq:exponential_dist}
        dF_\theta(x)= \exp (\theta x - b(\theta)) dF_0(x), \ \ \ \theta \in \Theta\cup{0} 
    \end{equation}
where $\Theta=[\theta_{min}, \infty)$ is an interval in $\mathbb{R}^+$, and $b(0)=0$.  Furthermore, let us define
\begin{equation}
\label{eq:threshold_expression}
    \mu_\alpha = \log(3 (D_{KL} (f_{\theta_{min}}||f_0)+1)^2)-\log(\alpha|\log \alpha|).
\end{equation}
 Then $\Bar{T}(\mu_\alpha)$ (defined by Definition \ref{def:GenSPRT} with $l^\theta(U)=\log(\frac{f_{\theta}(U)}{f_0(U)})$ satisfies (\ref{eq:flase-positive_condition}) and (\ref{eq:log_condition}).   
\end{proposition}

