\subsection{Implementation of the Detection Mechanism}
For a practical implementation of $T^*(\mu)$, we adapt the procedure proposed by \cite{lorden1971_change}. Note that $\Bar{T}(\mu)$ in (\ref{eq:gen_ratiotest}) can be considered as stopping  at the first time for which
\begin{equation}
\label{eq:gen_ratiotest_secondform}
     \sup_{\theta \in \Theta}\left\lbrace -\theta S_t - tb(\theta)\right\rbrace> \mu,
\end{equation}
where $S_t=U_1+\dots+U_t$. Equivalently, (\ref{eq:gen_ratiotest_secondform}) can be rewritten as
\begin{equation}
\label{eq:gen_ratiotest_thirdform}
     S_t < -\inf_{\theta \in \Theta}\left\lbrace \frac{\mu}{\theta}+ t\frac{b(\theta)}{\theta} \right\rbrace .
\end{equation}

It can be shown that the infimum in (\ref{eq:gen_ratiotest_thirdform}) is attained at $\theta_{\text{min}}$ for $t\geq \frac{\mu}{d(\theta_{\text{min}})}$, and at $\theta^{(t)}$ satisfying $d(\theta^{(t)})=\frac{\mu}{t}$ for $t< \frac{\mu}{d(\theta_{\text{min}})}$. Then for a recursive implementation of $T^*(\mu)$ in (\ref{eq:Gen_cusum}) we define a set of $M=\lfloor\frac{\mu}{d(\theta_{\text{min}})}\rfloor$ thresholds as
\begin{equation}
\label{eq:dynamic_thresholds}
    z^{(k)} =  -\frac{\mu}{\theta^{(k)}}- k\frac{b(\theta^{(k)})}{\theta^{(k)}}, \quad k=1,2,\dots, M 
\end{equation}
Moreover, we define 
$
    Q^{(k)}= U_t+\dots+U_{t-k+1} , \quad k=1,\dots, \min\lbrace M,t\rbrace
$. 
Then, $T^*(\mu)$ is equivalent to the following procedure: at each step,  perform a CUSUM test against $\theta_{\text{min}}$ with threshold $\mu$ by computing $R_t$ (see (\ref{eq:CUSUM})). Additionally, we compute $Q^{(k)}$ and we stop if $Q^{(k)}<z^{(k)}$. Note that $Q^{(k)}$ can be updated recursively as 
\begin{equation}
\label{eq:Q_update}
    Q^{(k)\prime}=\left\lbrace
    \begin{array}{cc}
       U_t + Q^{(k-1)}   &,  t-t_1\geq k\\
        0 &, t-t_1<k
    \end{array}
    \right.
\end{equation}
where $Q^{(k)\prime}$ denotes the updated value of $Q^{(k)}$ after observing $U_t$, and $t_1$ is the last time that $R_{t_1}=0$  . Whenever $R_t=1$, all previous observations can be neglected and a new cycle be started by resetting $t_1$ and setting $Q^{(k)}=0$. 
\begin{algorithm}[t]
\caption{Detection Strategy}\label{alg:Defense_alg}
\begin{algorithmic}
    \REQUIRE $\epsilon, \alpha$
    \STATE \textbf{Initialization:}
    \STATE Find ${\theta_\text{min}}$ such that $u_{\theta_\text{min}}=u_{\boldsymbol{\pi}}-\epsilon$
    \STATE Compute $\mu_{\alpha}$ as in (\ref{eq:threshold_expression})
    \STATE Find $\theta^{(k)}$ such that $d(\theta^{(k)})=\frac{\mu_\alpha}{k}, \quad k=1,\dots, M$
    \STATE Compute $z^{(k)}$ as in (\ref{eq:dynamic_thresholds}), $\quad k=1,\dots, M$
    \STATE Set $R=0,\ Q^{(k)}=0, \quad k=1,\dots, M$
    \STATE \textbf{Repeated Play Procedure:}
    \WHILE{not STOP}
    \STATE Receive $s_t$, play $a_t=s_t$, and observe $U_t$
    \STATE Compute $l_t=\log(\frac{\boldsymbol{\tau}_{\theta}(U_t)}{\boldsymbol{\pi}(U_t)})$ with $\theta=\theta_{\text{min}}$
    \STATE Update $R$ with $R\leftarrow(R+l_t)^+$
    \IF{ $R > \mu_\alpha$}
    \STATE {STOP}
    \ELSIF{$R>0$}
    \STATE Update $Q^{(k)}$ as in (\ref{eq:Q_update}), $\quad k=1,\dots, M$
        \IF{$Q^{(k)}<z^{(k)}$ for any $k$}
        \STATE STOP
        \ENDIF
    \ELSE
    \STATE Reset $R=0,\ Q^{(k)}=0, \quad k=1,\dots, M$
    \ENDIF
    \ENDWHILE



\end{algorithmic}
\end{algorithm}


