\section{Proof}

\begin{proof}[Proof of Theorem \ref{thm:eqlm}]
We show that the model defined by equations (\ref{eq:value}) and (\ref{eq:price}) has a unique equilibrium for the vector of dealer values $\{v_{ikt}\}_i$ given $\{c_{ikt},u_{ikt}\}_{i,k,t}$ and $\{\pi_{ijkt}\}_{i,j,k,t}$ at time $t$ and asset $k$. Fix the time $t$ and asset $k$, and suppress these indices to simplify notation: write $v_i$ for $v_{ikt}$, $c_i$ for $c_{ikt}$, $u_i$ for $u_{ikt}$, and $p_{ij}$ for $p_{ijkt}$. Define the vector $\boldsymbol{v} = (v_1, \dots, v_n) \in \mathbb{R}^n$.
\par Define the mapping $T: \mathbb{R}^n \to \mathbb{R}^n$ such that the $i^{th}$ component of $T(\boldsymbol{v}): \mathbb{R}^n \to \mathbb{R}$ is given by
\begin{equation*}
    T_i(\boldsymbol{v}) = -c_i + \max\left\{ \max_{j \in \mathcal{N}(i)} \left\{ \pi_{ij} v_i + (1 - \pi_{ij}) v_j \right\}, u_i \right\}.
\end{equation*}
\par We want to show that $T$ is a contraction mapping. Suppose all $\pi_{ij} \in [\varepsilon, 1 - \varepsilon]$ for some $\varepsilon > 0$.

\par Let $\boldsymbol{v}, \boldsymbol{v}' \in \mathbb{R}^n$. For each $i$, define
\[
    p_{ij} = \pi_{ij} v_i + (1 - \pi_{ij}) v_j, \quad p_{ij}' = \pi_{ij} v_i' + (1 - \pi_{ij}) v_j'.
\]
\par Then for any $j\in \mathcal{N}(i)$,
\[
    |p_{ij} - p_{ij}'| 
    \leq \max\{\pi_{ij}, 1 - \pi_{ij}\} \cdot \|\boldsymbol{v} - \boldsymbol{v}'\|_\infty 
    \leq (1 - \varepsilon)\|\boldsymbol{v} - \boldsymbol{v}'\|_\infty.
\]
\par Since $T_i(\boldsymbol{v})$ takes a maximum over $u_i$ and the $\{p_{ij}\}_{j\in \mathcal{N}(i)}$ terms, we have
\[
    |T_i(\boldsymbol{v}) - T_i(\boldsymbol{v}')| 
    \leq \max_{j \in \mathcal{N}(i)} |p_{ij} - p_{ij}'| 
    \leq \|\boldsymbol{v} - \boldsymbol{v}'\|_\infty.
\]
\par So,
\[
    \|T(\boldsymbol{v}) - T(\boldsymbol{v}')\|_\infty 
    = \max_i |T_i(\boldsymbol{v}) - T_i(\boldsymbol{v}')|
    \leq (1 - \varepsilon) \|\boldsymbol{v} - \boldsymbol{v}'\|_\infty.
\]

\par Hence, $T$ is a contraction mapping on the complete metric space $(\mathbb{R}^n, \|\cdot\|_\infty)$.
\par By the Banach fixed point theorem, $T$ has a unique fixed point. That is, there exists a unique vector $\boldsymbol{v}^* \in \mathbb{R}^n$ such that $T(\boldsymbol{v}^*) = \boldsymbol{v}^*$. This proves the model has a unique equilibrium. Furthermore, we can find the equilibrium $\boldsymbol{v}^*$ by starting with an arbitrary element  $\boldsymbol{v}^*\in\mathbb{R}^n$, and define a sequence $\{\boldsymbol{v}^{(\ell)}\}_{\ell\in \mathbb{N}}$ by $\boldsymbol{v}^{(\ell)}=T(\boldsymbol{v}^{(\ell-1)})$ for $n\geq 1$. Then $\lim_{\ell\rightarrow \infty} \boldsymbol{v}^{(\ell)} = \boldsymbol{v}^*$.
\par It is easy to see that $v_{min}^*\equiv\min_i\{v_{ikt}\}\geq \min_i\{u_{ikt}-c_{ikt}\}$ as the lowest outside option is $\min_i\{u_{ikt}-c_{ikt}\}$. Let $v_{max}^*\equiv\max_i\{{v}_{ikt}\}$. As $v_{max}^*\geq \max \{p_{ijkt}\}_{i,j}$ and $c_{ikt}>0$, it's impossible for $v_{max}=\max_i\{-c_{ikt}+\max_{j\in\mathcal{N}(i)}\{p_{ijkt}\}_j\}$, so $v_{max}^* =  \max_i \{u_{ikt}-c_{ikt}\}$. Intuitively, the dealer buyer with the highest value does not sell to dealers and has a resale value of $ \max_i \{u_{ikt}-c_{ikt}\}$ to its customers. 
\par Given $\boldsymbol{v}^*$, seller $i$ sells the asset $k$ at price $ p_{ikt}^*=\max\left\{ \max_{j \in \mathcal{N}(i)} \left\{ \pi_{ijkt} v_{ikt}^* + (1 - \pi_{ijkt}) v_{jkt}^* \right\}, u_{ikt} \right\}$ at time $t$, with counterparty $j=\arg\max_{j \in \mathcal{N}(i)} \left\{ \pi_{ijkt} v_{ikt}^* + (1 - \pi_{ijkt}) v_{jkt}^* \right\}$ if $p_{ikt}^*>u_{ikt}$ and with customers otherwise.
\end{proof}

