		\title[  Liouville theorem for $\Delta u+f(u)=0$ ]{A New proof of Liouville type theorems for a class of semilinear elliptic equations }
		\author{Chen Guo and Zhengce Zhang}
		\date{\today}
		\address[Chen Guo]{School of Mathematics and Statistics, Xi'an Jiaotong University, Xi'an, 710049, P. R. China}
		\email{jasonchen123@stu.xjtu.edu.cn}

		\address[Zhengce Zhang]{School of Mathematics and Statistics, Xi'an Jiaotong University, Xi'an, 710049, P. R. China}
		\email{zhangzc@mail.xjtu.edu.cn}
		\thanks{Corresponding author: Zhengce Zhang}
		\thanks{Keywords: Invariant tensor; Semilinear elliptic equation; Liouville-type theorem.  }
		\thanks{2020 Mathematics Subject Classification: 35B53, 35J61, 35R01.}



		\begin{abstract}
			We study  certain typical   semilinear elliptic equations in Euclidean space $\bR^{n}$ or on a closed manifold $M$ with nonnegative Ricci curvature. Our proof is based on a crucial integral identity constructed by the invariant tensor method. Together with  suitable integral estimates, some classical Liouville theorems will be reestablished.
		\end{abstract}
		\maketitle		
		\section{Introduction}\label{Introduction}
		The study of Liouville theorems constitutes a central topic in the theory of partial differential equations. It is well-known that any bounded harmonic function in $\bR^{n}$ is actually constant. For  general Riemannian manifolds, Yau \cite{Y1} proved that every positive harmonic function on a complete Riemannian manifold $M$ with nonnegative Ricci curvature must be constant.
		 Later, Wang and Zhang \cite{WZ} generalized the Liouville theorem to $p$-harmonic functions by deriving the local gradient estimate (also see\cite{KN} under extra assumption on the sectional curvature).
		 Again by gradient estimates, Brighton\cite{B1} establishes the Liouville type result for bounded $f$-harmonic functions on complete smooth metric measure spaces with nonnegative Bakry-Emery curvature.
		 In addition, the moving plane method is also widely used to prove Liouville theorems\cite{CL,CDQ}. There are variations of this approach such as the moving sphere method. Towards the supercritical case, the monotonicity formula is an efficient way to study  Liouville theorems for (stable) solutions (see \cite{DGW,DFP}). To conclude this topic,  we refer to a very recent paper \cite{QS} for a detailed discussion about various approaches to derive Liouville theorems.

		In this paper, we are concerned about the Liouville type theorem for the following semilinear equation 
		\begin{equation}\label{main equ}
			\Delta u+f(u)=0
		\end{equation}
		either in Euclidean space $\bR^{n}$ or on an $n$-dimensional closed manifold $M$ with nonnegative Ricci curvature with $n>2$.

		  Equation \eqref{main equ} is fully considered by many researchers and has plenty of conclusions. Owing to the vastness and depth of this topic, we only review some of them here.
		  A typical example of \eqref{main equ} is
		  \begin{equation}\label{power equ}
		  		\Delta u+u^{p}=0.
		  \end{equation}

		    Gidas and Spruck's classical result \cite{GS} shows  that any nonnegative $C^{2}$ solution of \eqref{power equ} in $\bR^{n}$ is identical to zero provided $1< p< \frac{n+2}{n-2}$.
		  It also holds in complete Riemannian manifolds with nonnegative Ricci curvature. In the borderline case $p=\frac{n+2}{n-2}$, Chen and Li \cite{CL} removed the growth restriction at infinity in \cite{GNN} and  proved that \eqref{power equ} has nontrivial radially symmetric solutions  (see also \cite{CGS}). We note that in \cite[Theorem 6.1]{GS}, the authors derive some Liouville type results for more general nonlinearity  $f(x,u)$ with some extra assumptions on the behavior of $f$. 

		  Serrin and Zou \cite{SZ} loosed some technical conditions such as $f(u)>0$ for $u>0$ in \cite{GS}  and extended the conclusion to the quasilinear equation $\Delta_{m}u+f(u)=0$ in $\bR^{n}$. See \cite[Theorem II]{SZ} for details.  They introduced the following subcritical condition. 
		  \begin{defn}\label{subcritical condition1}
		  	The function $f$ is subcritical if $n>m$ and there exists some $\beta\in (0,\frac{nm}{n-m}-1)$ such that
		  	\begin{equation}\label{subcritical formula}
		  		f(u)\ge 0, \quad \beta f(u)-uf'(u)\ge 0, \quad \text{for}\;u>0.
		  	\end{equation}
		  \end{defn}

		  When $m=2$, \eqref{subcritical formula} implies that $u^{-\beta}f(u)$ is non-increasing in $(0,\infty)$ for some $\beta\in (0,\frac{n+2}{n-2})$. Especially, a result involving Laplacian case ($m=2$) is also given.
		  \begin{thm}{\rm(\hspace{-0.03em}\cite[Theorem 4]{SZ})}\label{thm1.1} The following truths hold for \eqref{main equ}.
		  \begin{enumerate}[(i)]
		  \item Let $n=3$ and $f$ is subcritical. Then every solution of \eqref{main equ} is constant.
		  \item Suppose $n\ge 4$. Assume that $f$ is subcritical and the condition 
		  \begin{equation}\label{superpower}
		  	f(u)\ge u^{\alpha}
		  \end{equation}
		  holds for  sufficiently large $u$ with $\alpha>1$. Then \eqref{main equ} only admits the trivial solution $u\equiv 0$. The same conclusion also holds for $\alpha\in (0,1]$ provided $0<\beta\le 1$ in \eqref{subcritical formula}. 
		  \end{enumerate}
		  \end{thm}
%		  With extra restrictions on $f$, they obtain the following conclusion. We only state the case $m=2$ here.
%		   \begin{thm}{\rm(\hspace{-0.03em}\cite[Theorem III]{SZ})}\label{thm 1.2} Assume $f$ is subcritical and that $f(u)>0$ for all $u>0$. Then every bounded solution of $\eqref{main equ}$ in $\bR^{n}\,(n>2)$ is trivial. 
%		  \end{thm}

		  Afterwards, Li and Zhang \cite{LZ} investigated \eqref{main equ} by the moving sphere method. They found that the solution has two different behaviors, depending on whether $\bar{\lambda}(x)$ is infinite or not (see \cite{LZ}, page 37 for its definition).
		  \begin{thm}{\rm(\hspace{-0.03em}\cite[Theorem 1.3]{	LZ})}\label{thm 1.3} Assume $f$ is locally bounded in $(0,\infty)$ and the function $f(u)u^{-\frac{n+2}{n-2}}$ is non-increasing in $(0,\infty)$. Let $u$ be a solution of \eqref{main equ} in $\bR^{n}$ with $n>2$. Then either $u\equiv a$ for some positive constant $a$  satisfying $f(a)=0$; or for some $b>0$,
		  \begin{equation*}
		  	bu=\left(\frac{\mu}{1+\mu^{2} |x-\bar{x}|^{2}}\right)^{\frac{n-2}{2}},
		  \end{equation*}
		  where $\mu>0,\bar{x}\in \bR^{n}$ and $f(s)s^{-\frac{n+2}{n-2}}\equiv n(n-2)b^{4/(n-2)}$ on $(0,\max_{\bR^{n}} u]$.
		  \end{thm}

		     Since in the critical case $p=\frac{n+2}{n-2}$, no sign assumption of $f$ and also ``super-power'' condition \eqref{superpower}  are required in \thmref{thm 1.3}. One may wonder whether  \thmref{thm1.1} holds by only assuming the subcritical condition for sign-changing $f$.  We attempt to prove them through a
		    totally different way.

		  	In the following discussion, we always suppose that $f\in C^{1}(0,\infty)\bigcap C[0,\infty)$, which may change its sign but has at least one  zero point in $[0,\infty)$. Instead of \eqref{subcritical formula},  we only require $f$ satisfies
		  	\begin{equation}\label{subcritical}
		  		\beta f(u)-uf'(u)\ge 0, \quad \text{for}\;u>0,
		  	\end{equation}
		  	  which implies the function $u^{-\beta} f(u)$ is non-increasing in $(0,\infty)$ for some $\beta\in I$. Here $I$ is an 
		  	  appropriate interval.  For a more intuitive understanding, we conveniently say $f$ is subcritical if $f$ satisfies $\eqref{subcritical}$.
%and could be changed towards different theorems. For a more intuitive understanding, we conveniently think $\eqref{subcritial}$  is identical to the decreasing property of $u^{-\beta} f(u)$. (Although this is not strictly equivalent.)

		  	  In addition, the solution $u$ of \eqref{main equ} is required at least $C^{3}$. For simplicity, we consider $C^{\infty}$ functions in our theorems. Now we state the main results of this paper. The first theorem investigates the  closed manifold case.

		  	\begin{thm}\label{mainthm1}
		  		Let $u$ be a smooth positive solution of $\eqref{main equ}$  on an $n$-dimensional closed  manifold $(M,g)$ with nonnegative Ricci curvature. Suppose  $f$ is subcritical for some $\beta\in (0,\frac{n+2}{n-2})$. Then $u$ is constant. The same conclusion also holds if $u^{-\frac{n+2}{n-2}} f(u)$  strictly decreases in $(0,\infty)$.
		  	\end{thm}

		  	 While considering similar issues in $\bR^{n}$, it turns out that we have to impose the super-power condition about $f$ to handle the integral estimate. It is worthy mentioning that this condition is necessary and can not be removed. 

		  	 \begin{thm}\label{mainthm2}
		  	 		Let $u$ be a smooth positive solution of $\eqref{main equ}$ in $\bR^{n}$. Suppose $f$ is subcritical for some $\beta\in (1,\frac{n+2}{n-2})$ and 
		  	 		\begin{equation}\label{condition of mainthm2}
		  	 			|f(u)|\ge c_{1}u^{\beta},
		  	 		\end{equation}
		  	 		where $c_{1}$ is some positive constant dependent on $n,\beta$. Then \eqref{main equ} only admits the trivial solution $u\equiv 0$.
		  	 \end{thm}

		  	 \begin{thm}\label{mainthm3}
		  	 		Let $u$ be a smooth positive solution of $\eqref{main equ}$ in $\bR^{n}$. Suppose $f$ is subcritical for some $\beta\in (1,\frac{n+2}{n-2})$.   Then the following conclusions hold.
		  	 	\begin{enumerate}[\rm(\roman{enumi})]
		  	 		\item Let $n=3$ and assume $u$ is bounded, then every solution of $u$ is constant.
		  	 		\item Provided $n\ge 4$ and  there exists some $\alpha>1$ such that
		  	 		\begin{equation}\label{condition of mainthm3}
		  	 			f(u)\ge u^{\alpha}  
		  	 		\end{equation}
		  	 		holds for sufficiently large $u$. Then \eqref{main equ} admits no positive solution. Moreover, the only trivial solution is $u\equiv 0$.
		  	 	\end{enumerate}
		  	 \end{thm}

		  	 \begin{rmk}
		  	 	\thmref{thm1.1} requires no boundedness assumption of $u$ for $n=3$ with the help of the weak Harnack inequality  and a crucial integral estimate, see \rm(\hspace{-0.03em}\cite[Lemma 3.2]{SZ}) and \rm(\hspace{-0.03em}\cite[Lemma 3.3]{SZ}) respectively. We temporarily lack a similar estimate and 
		  	  	this question will be considered in the future.
		  	 \end{rmk}

		  	 \begin{rmk}
		  	    The requirement $\alpha>1$ in Theorem 1.6 {\rm(ii)} originates from the use of Young's inequality.
%		  	     and condition \eqref{condition of mainthm3} can be loosed. More precisely, if there exist some large $u_{0}$ and $\alpha>1$ such that $f(u_{0})> 0$ and
%		  	 	$|f(u)|\ge u^{\alpha}$ holds for $u\ge u_{0}$, then Theorem 1.5 {\rm(ii)} is still valid.

		  	 \end{rmk}
		  	  The soul of our proof is  to derive some important identity.   Gidas and Spruck \cite{GS} made use of the vector field $V$ 
		  	  \begin{equation*}
		  	  	V^{i}=w^{-(n-1)}\left\{w_{ij}w_{j}-\frac{1}{n}w_{i}\Delta w\right\},
		  	  \end{equation*}
		  	  where $w=u^{-\frac{2}{n-2}}$, to  derive some integral identity. It is firstly appeared in  Obata's paper \cite{Obata}.   Different from their approach, we use the following tensor
		  	  \begin{equation*}
		  	  	E_{ij}=u_{ij}+c\frac{u_{i}u_{j}}{u}-\frac{1}{n}\left(\Delta u+c\frac{|\nabla u|^{2}}{u}\right)g_{ij},
		  	  \end{equation*}
		  	  where $c$ is to be determined later. This tensor is firstly introduced by Ma and Wu in \cite{MW} and it is useful to seek for the key identity in Section 2. 

		  	  Ma and Ou \cite{MO1} generalized Jerison-Lee's identity \cite{JL1} for the CR Yamabe problem and used their new crucial identity (see Propostion 2.1 of \cite{MO1}) to prove the Liouville theorem for the following equation 
		  	  \begin{equation*}
		  	  	 -\Delta_{\mathbb{H}^{n}}u=2n^{2}u^{q}
		  	  \end{equation*}
		  	  on Heisenberg group $\mathbb{H}^{n}$, where $1<q<\frac{Q+2}{Q-2}$ and $Q=2n+2$ is the homogeneous dimension of $\mathbb{H}^{n}$. Later on, Ma, Ou and Wu \cite{MOW} found the invariant tensor on $\mathbb{H}^{n}$ and sucessfully answered the question asked in \cite{JL1} about the possible theoretical framework to establish such an explicable identity systematically from a perspective. For more relevant studies on the applications of various  (integral) identities, we refer  readers to \cite{CFR,DEL,LM1,LO}  and the references therein.

		  	  This paper is organized as follows. In Section 2, we give some necessary notations and establish the significant identity by choosing suitable $c$ in the expression of $E_{ij}$. Then we give the proof of \thmref{mainthm1} in Section 3. Theorems \ref{mainthm2} and \ref{mainthm3} will be proved in Section 4.
\section{ A crucial identity}
\subsection{Notations}
 We introduce some necessary notations at first. Notations in the below adhere Einstein's summation convention, where repeated indices represent sums. Using the standard notation in Riemannian geometry, we  set $\Delta f=f_{i}^{i}$ and $|\nabla u|^{2}=u^{i}u_{i}=g^{ij}u_{i}u_{j}$. $R_{ij}$ denotes  Ricci curvature tensor and $g_{ij}$ represents the common metric tensor. For a second-order tensor $A_{ij}$, its norm $|A_{ij}|$ is defined by $$|A_{ij}|^{2}\triangleq g^{ik}g^{jl}A_{ij}A_{kl}=A_{ij}A^{ij}.$$ From the usual Ricci identity,  the following truth holds
 \begin{equation}\label{Ricci identity}
   f_{ij}^{i}-(\Delta f)_{j}=R_{ij}f^{i}.
 \end{equation}

 In addition, $C(\cdot)$ always denotes some positive constant depending on parameters in the bracket, which may change the value from line to line.

 \subsection{Derivation of the identity}
 Our crucial identity is given as follows.
 \begin{prop}\label{prop1}
 	\begin{equation}\label{keyidentity}
 			\begin{aligned}
 			u^{\frac{2\beta}{n+2}}\left(u^{-\frac{2\beta}{n+2}}E_{ij}u^{j}\right)^{i}=&|E_{ij}|^{2}+\frac{n-1}{n+2}\beta\left(1-\frac{n-2}{n+2}\beta\right)\frac{|\nabla u|^{4}}{u^{2}}\\
 			&+R_{ij}u^{i}u^{j}-\frac{n-1}{n}\left(f'(u)-\beta\frac{f(u)}{u}\right)|\nabla u|^{2}.
 		\end{aligned}
 	\end{equation}
 \end{prop}
 \noindent{\bf Proof of Proposition 2.1}\\
   Recall
   \begin{equation}\label{tensorEij}
   	 E_{ij}=u_{ij}+c\frac{u_{i}u_{j}}{u}-\frac{1}{n}\left(\Delta u+c\frac{|\nabla u|^{2}}{u}\right)g_{ij}.
   \end{equation}

   Then a straightforward calculation shows
   \begin{equation}\label{div1}
   	E_{ij}^{i}=\frac{n-1}{n}(\Delta u)_{j}+R_{ij}u^{i}+c\frac{\Delta u u_{j}}{u}+\frac{n-2}{n}c\frac{u_{ij}u^{i}}{u}-\frac{n-1}{n}c\frac{
   	|\nabla u|^{2}}{u^{2}}u_{j},
   \end{equation}
   where we have used \eqref{Ricci identity}.

    By using the fact $(\Delta u)_{j}=-f'(u)u_{j}$ and replacing $u_{ij}$ by $E_{ij}$,  a combination of \eqref{tensorEij} and \eqref{div1} leads to
    \begin{equation}\label{div2}
    	\begin{aligned}
    		E_{ij}^{i}=&-\frac{n-1}{n}f'(u)u_{j}+R_{ij}u^{i}+\frac{(n-1)(n+2)}{n^{2}}c\frac{\Delta u u_{j}}{u}\\
    		&+\frac{n-2}{n}c\frac{E_{ij}u^{i}}{u}-\frac{n-1}{n}c\left(1+\frac{n-2}{n}c\right)\frac	{|\nabla u|^{2}}{u^{2}}u_{j}.
    	\end{aligned}
   \end{equation}
   Interpolate the term $$\frac{n-1}{n}\beta\frac{f(u)}{u}u_{j}$$ into \eqref{div2}, it yields
   \begin{equation}\label{div3}
   	\begin{aligned}
   		E_{ij}^{i}=&-\frac{n-1}{n}\left(f'(u)-\beta\frac{f(u)}{u}\right)u_{j}+R_{ij}u^{i}+\frac{n-2}{n}c\frac{E_{ij}u^{i}}{u}\\
   		&+\left(\frac{(n-1)(n+2)}{n^{2}}c+\frac{n-1}{n}\beta\right)\frac{\Delta u u_{j}}{u}-\frac{n-1}{n}c\left(1+\frac{n-2}{n}c\right)\frac	{|\nabla u|^{2}}{u^{2}}u_{j}.
   	\end{aligned}
   \end{equation}
   In order to eliminate the mixed term $\frac{\Delta u u_{j}}{u}$, we set $	c=-\frac{n\beta}{n+2}$ and \eqref{div3} becomes
   \begin{equation}\label{divfinal}
   	\begin{aligned}
   		E_{ij}^{i}=&-\frac{n-1}{n}\left(f'(u)-\beta\frac{f(u)}{u}\right)u_{j}+R_{ij}u^{i}\\&-\frac{n-2}{n+2}\beta\frac{E_{ij}u^{i}}{u}+\frac{n-1}{n+2}\beta(1-\frac{n+2}{n-2}\beta)\frac{|\nabla u|^{2}}{u^{2}}u_{j}.
   	\end{aligned}
   \end{equation}
%   \begin{equation}
%	E_{ij}^{i}=-\frac{n-1}{n}\left(f'(u)-\beta\frac{f(u)}{u}\right)u_{j}+R_{ij}u^{i}-\frac{n-2}{n+2}\beta\frac{E_{ij}u^{i}}{u}+\frac{n-1}{n+2}\beta(1-\frac{n+2}{n-2}\beta)\frac{|\nabla u|^{2}}{u^{2}}u_{j}.
%   \end{equation}
   Due to trace free property of $E_{ij}$, we combine $\eqref{tensorEij}$ and \eqref{divfinal} to obtain
    \begin{equation}\label{equ 2.8}
    	\begin{aligned}
    	\left(E_{ij}u^{j}\right)^{i}=&|E_{ij}|^{2}+\frac{2\beta}{n+2}\frac{E_{ij}u^{i}u^{j}}{u}-\frac{n-1}{n}\left(f'(u)-\beta\frac{f(u)}{u}\right)|\nabla u|^{2}\\
    	&+\frac{n-1}{n+2}\beta(1-\frac{n-2}{n+2}\beta)\frac{|\nabla u|^{4}}{u^{2}}+R_{ij}u^{i}u^{j}
    	\end{aligned}
   \end{equation}
%   \begin{equation}\label{equ 2.8}
%   	\left(E_{ij}u^{j}\right)^{i}=|E_{ij}|^{2}+\frac{2\beta}{n+2}\frac{E_{ij}u^{i}u^{j}}{u}+R_{ij}u^{i}u^{j}-\frac{n-1}{n}\left(f'(u)-\beta\frac{f(u)}{u}\right)|\nabla u|^{2}+\frac{n-1}{n+2}\beta(1-\frac{n-2}{n+2}\beta)\frac{|\nabla u|^{4}}{u^{2}}
%   \end{equation}

   With the purpose of removing the second term in the right hand side of \eqref{equ 2.8}, we introduce a certain power of $u$ to accomplish it. Notice that
    \begin{equation}\label{equ 2.9}
    	u^{\frac{2\beta}{n+2}}\left(u^{-\frac{2\beta}{n+2}}E_{ij}u^{j}\right)^{i}=\left(E_{ij}u^{j}\right)^{i}-\frac{2\beta}{n+2}\frac{E_{ij}u^{i}u^{j}}{u}.
    \end{equation}
   We immediately get \eqref{keyidentity} by substituting \eqref{equ 2.8} into \eqref{equ 2.9}. \qed 

