%   	$$f'(u)-\beta\frac{f(u)}{u}\le 0 \quad \text{and} \quad \beta\left(1-\frac{n-2}{n+2}\beta\right)>0.$$
%   \end{rmk}


\section{Proof of Theorem 1.4}
%   The proof of \thmref{mainthm1} is an  adaptation of \cite{MW}. For the completeness of this paper, we sketch the proof. 
   We  prove \thmref{mainthm1} at first. It follows from \propref{prop1} that
  	\begin{equation}\label{identity}
  	\begin{aligned}
  		\left(u^{-\frac{2\beta}{n+2}}E_{ij}u^{j}\right)^{i}=&u^{-\frac{2\beta}{n+2}}|E_{ij}|^{2}+\frac{n-1}{n+2}\beta\left(1-\frac{n-2}{n+2}\beta\right)u^{-\frac{2\beta}{n+2}-2}|\nabla u|^{4}\\
  		&+u^{-\frac{2\beta}{n+2}}R_{ij}u^{i}u^{j}-\frac{n-1}{n}\left(f'(u)-\beta\frac{f(u)}{u}\right)u^{-\frac{2\beta}{n+2}}|\nabla u|^{2}.
  	\end{aligned}
  \end{equation}

  In the treatment of the closed manifold, we just integrate \eqref{identity} over $M$ and use the divergence theorem to obtain
%   \[
%   \begin{blockarray}[l]
%   		 \biggl[0=\int_{M}|E_{ij}|^{2}+\frac{n-1}{n+2}\beta\left(1-\frac{n-2}{n+2}\beta\right)\frac{|\nabla u|^{4}}{u^{2}}\\
%   		  	+R_{ij}u^{i}u^{j}-\frac{n-1}{n}\left(f'(u)-\beta\frac{f(u)}{u}\right)|\nabla u|^{2}]. \biggr]
%   \end{blockarray}
%   \]
  \begin{equation}\label{final1}
      \begin{aligned}
      		0=&\int_{M}\Big[u^{-\frac{2\beta}{n+2}}|E_{ij}|^{2}+\frac{n-1}{n+2}\beta\left(1-\frac{n-2}{n+2}\beta\right)u^{-\frac{2\beta}{n+2}-2}|\nabla u|^{4}\\
      		&+u^{-\frac{2\beta}{n+2}}R_{ij}u^{i}u^{j}-\frac{n-1}{n}\left(f'(u)-\beta\frac{f(u)}{u}\right)u^{-\frac{2\beta}{n+2}}|\nabla u|^{2} \Big].
      \end{aligned}
   \end{equation}

   Notice that the coefficient $\beta\left(1-\frac{n-2}{n+2}\beta\right)$ keeps positive when $\beta\in (0,\frac{n+2}{n-2})$. Using \eqref{subcritical}  and the non-negativity of the Ricci curvature, \eqref{final1} implies
   \begin{equation}
   	0\ge \int_{M} \frac{n-1}{n+2}\beta\left(1-\frac{n-2}{n+2}\beta\right)u^{-\frac{2\beta}{n+2}-2}|\nabla u|^{4},
   \end{equation}
   which enforces $u$ to be constant.

   Furthermore, if $u^{-\frac{n+2}{n-2}}f(u)$ is strictly decreasing in $(0,\infty)$, we can easily get
   \begin{equation}\label{equ 3.4}
   	f'(u)-\frac{n+2}{n-2}\frac{f(u)}{u}<0.
   \end{equation}

   Setting $\beta=\frac{n+2}{n-2}$ in \eqref{final1}, the second term in the right hand side vanishes and we retain that
   \begin{equation}\label{final2}
   	0\ge -\int_{M} \frac{n-1}{n}\left(f'(u)-\frac{n+2}{n-2}\frac{f(u)}{u}\right)u^{-\frac{2}{n-2}}|\nabla u|^{2} .
   \end{equation}
   As a consequence of \eqref{equ 3.4} and \eqref{final2}, $u$ should be constant.  This ends the proof.
   \section{The Euclidean case: Proofs of Theorems 1.5 and  1.6}
   Next, we deal with the Euclidean case. At this point, the covariant derivative degenerates into the usual partial derivative in $\bR^{n}$, $g_{ij}=\delta_{ij}$ and $R_{ij}=0$. We always assume  $1< \beta<\frac{n+2}{n-2}$ in this section. Since we are going to derive some integral estimates, in order to be consistent with the standard notation in partial differential equations, we will uniformly adopt subscripts below.
   \subsection{Some integral estimates} We prove the following integral estimates at the beginning. They are necessary in our proof. 
   At first, we choose a cut-off function $\eta\in C^{\infty}_{0}(R^{n})$ satisfying 
  \begin{equation*}
  	 0\le\eta\le 1,\; \eta\equiv\,1\;\text{in}\;B_{R},\; \eta=0 \;\text{outside}\; B_{2R}\;\,\text{and}\;|\nabla \eta|\le \frac{C(n)}{R}.
  \end{equation*}
  Multiplying both sides of \eqref{identity} by $\eta^{\gamma}$ and integrating over $\bR^{n}$, we obtain
  \begin{equation}\label{indentity for RN}
  	\begin{aligned}
  &\int_{\bR^{n}}u^{-\frac{2\beta}{n+2}}|E_{ij}|^{2}\eta^{\gamma}+\int_{\bR^{n}}\frac{n-1}{n+2}\beta\left(1-\frac{n-2}{n+2}\right)u^{-\frac{2\beta}{n+2}-2}|\nabla u|^{4}\eta^{\gamma}\\
  =&\int_{\bR^{n}}\left(u^{-\frac{2\beta}{n+2}}E_{ij}u_{j}\right)_{i}\eta^{\gamma}+\int_{\bR^{n}}\frac{n-1}{n}\left(f'(u)-\beta\frac{f(u)}{u}\right)u^{-\frac{2\beta}{n+2}}|\nabla u|^{2}\eta^{\gamma}.
  	\end{aligned}
  \end{equation}

  Here $\gamma$ relies on $n,\beta$ and will be chosen later. We denote $A=\beta\left(1-\frac{n-2}{n+2}\right)>0$. For simplicity, in the below the integration region is always ignored when integrating in the whole space. A
  direct integration by parts yields that
  \begin{equation*}
  	\int\left(u^{-\frac{2\beta}{n+2}}E_{ij}u_{j}\right)_{i}\eta^{\gamma}
  =-\gamma \int u^{-\frac{2\beta}{n+2}}E_{ij}u_{j}\eta^{\gamma-1}\eta_{i}.
  \end{equation*}
  Using  Cauchy-Schwarz's inequality, we have
  \begin{equation}\label{equ 4.2}
  	\begin{aligned}
  		&-\gamma \int u^{-\frac{2\beta}{n+2}}E_{ij}u_{j}\eta^{\gamma-1}\eta_{i}\\
  		&\le
  		 \frac{1}{2}\int u^{-\frac{2\beta}{n+2}}|E_{ij}|^{2}\eta^{\gamma}
  		+C(n,\beta)\int u^{-\frac{2\beta}{n+2}} |\nabla u|^{2}\eta^{\gamma-2}|\nabla \eta|^{2}\\
  		&\le  \frac{1}{2}\int u^{-\frac{2\beta}{n+2}}|E_{ij}|^{2}\eta^{\gamma}
  		+\frac{A}{2}\int u^{-\frac{2\beta}{n+2}}|\nabla u|^{4}\eta^{\gamma}
  		+C(n,\beta)\int u^{-\frac{2\beta}{n+2}+2}\eta^{\gamma-4}|\nabla \eta|^{4}.
  	\end{aligned}
  \end{equation}
  With the help of \eqref{subcritical}, we combine \eqref{indentity for RN} and \eqref{equ 4.2} to get
  \begin{equation}\label{first integral inequ}
  	\int u^{-\frac{2\beta}{n+2}-2}|\nabla u|^{4}\eta^{\gamma}\le C(n,\beta)\int u^{-\frac{2\beta}{n+2}+2}\eta^{\gamma-4}|\nabla \eta|^{4}.
  \end{equation}
  From equation \eqref{main equ}, we have
  \begin{equation}\label{identity from mainequ}
            \int u^{-\frac{2\beta}{n+2}} f^{2}(u)\eta^{\gamma}=-\int u^{-\frac{2\beta}{n+2}} f(u)\eta^{\gamma}\Delta u.
  \end{equation}
  Integrate by parts to obtain
  \begin{equation}\label{integration by parts1}
  	\begin{aligned}
  		 -\int u^{-\frac{2\beta}{n+2}} f(u)\eta^{\gamma}\Delta u
  		 =&\int \gamma\eta^{\gamma-1}u^{-\frac{2\beta}{n+2}}f(u)\nabla\eta\cdot \nabla u+\int u^{-\frac{2\beta}{n+2}} f'(u)|\nabla u|^{2}\eta^{\gamma}\\
  		 &-\int \frac{2\beta}{n+2}u^{-\frac{2\beta}{n+2}-1} f(u)|\nabla u|^{2}\eta^{\gamma}.
  	\end{aligned}
  \end{equation}
 By reapplying \eqref{subcritical} and combining it with \eqref{identity from mainequ} and \eqref{integration by parts1}, we derive that
 \begin{equation}\label{equ 4.6}
 		 \int u^{-\frac{2\beta}{n+2}} f^{2}(u)\eta^{\gamma}\le \frac{n\beta}{n+2}\int u^{-\frac{2\beta}{n+2}-1} f(u)|\nabla u|^{2}\eta^{\gamma}+\gamma\int \eta^{\gamma-1}u^{-\frac{2\beta}{n+2}}f(u)\nabla\eta\cdot \nabla u.
 \end{equation}
 Note that
 \begin{equation}\label{equ 4.7}
 	\begin{aligned}
 		\left| \frac{n\beta}{n+2}\int u^{-\frac{2\beta}{n+2}-1} f(u)|\nabla u|^{2}\eta^{\gamma} \right|&\le \int u^{-\frac{2\beta}{n+2}-1} |f(u)| |\nabla u|^{2}\eta^{\gamma}\\
 		&\le \frac{1}{4}  \int u^{-\frac{2\beta}{n+2}} f^{2}(u)\eta^{\gamma}
 		+C(n,\beta)\int  u^{-\frac{2\beta}{n+2}+2}\eta^{\gamma-4}|\nabla \eta|^{4},
 	\end{aligned}
 \end{equation}
 \begin{equation}\label{equ 4.8}
 	\begin{aligned}
 		\left| \gamma\int \eta^{\gamma-1}u^{-\frac{2\beta}{n+2}}f(u)\nabla\eta\cdot \nabla u \right|&\le  \gamma\int u^{-\frac{2\beta}{n+2}}|f(u)| |\nabla\eta| |\nabla u| \eta^{\gamma-1}\\
 		&\le \frac{1}{4}  \int u^{-\frac{2\beta}{n+2}} f^{2}(u)\eta^{\gamma}
 		+\gamma^{2}\int  u^{-\frac{2\beta}{n+2}}|\nabla u|^{2}|\nabla \eta|^{2}\eta^{\gamma-2},
 	\end{aligned}
 \end{equation}
 and
 \begin{equation}\label{equ 4.9}
 	\begin{aligned}
 		\gamma^{2}\int  u^{-\frac{2\beta}{n+2}}|\nabla u|^{2}|\nabla \eta|^{2}\eta^{\gamma-2}&\le \frac{1}{4} \int u^{-\frac{2\beta}{n+2}-2}|\nabla u|^{4}\eta^{\gamma}+\gamma^{4} \int  u^{-\frac{2\beta}{n+2}+2}\eta^{\gamma-4}|\nabla \eta|^{4}\\
 		&\le C(n,\beta)\int  u^{-\frac{2\beta}{n+2}+2}\eta^{\gamma-4}|\nabla \eta|^{4},
 	\end{aligned}
 \end{equation}
  where we have used \eqref{first integral inequ} in the second inequality of \eqref{equ 4.9}.

   \noindent Substituting \eqref{equ 4.7}, \eqref{equ 4.8} and \eqref{equ 4.9} into \eqref{equ 4.6}, it yields
   \begin{equation}\label{second integral inequality}
   	\int u^{-\frac{2\beta}{n+2}} f^{2}(u)\eta^{\gamma}\le C(n,\beta)\int  u^{-\frac{2\beta}{n+2}+2}\eta^{\gamma-4}|\nabla \eta|^{4}.
   \end{equation}

   We have now rigorously established the target integral inequalites via the preceding analysis.
   \begin{rmk}\label{rmk4.1}
   	Both \eqref{first integral inequ} and \eqref{second integral inequality} still hold for a complete noncompact manifold with nonnegative Ricci curvature. Instead of \eqref{indentity for RN}, we have
   	\begin{equation}\label{identity for mfd}
   		\begin{aligned}
   			\int_{M}u^{-\frac{2\beta}{n+2}}R_{ij}u^{i}u^{j}&+\int_{M}u^{-\frac{2\beta}{n+2}}|E_{ij}|^{2}\eta^{\gamma}+\int_{M}\frac{n-1}{n+2}\beta\left(1-\frac{n-2}{n+2}\right)u^{-\frac{2\beta}{n+2}-2}|\nabla u|^{4}\eta^{\gamma}\\
   			&=\int_{M}\left(u^{-\frac{2\beta}{n+2}}E_{ij}u_{j}\right)_{i}\eta^{\gamma}+\int_{M}\frac{n-1}{n}\left(f'(u)-\beta\frac{f(u)}{u}\right)u^{-\frac{2\beta}{n+2}}|\nabla u|^{2}\eta^{\gamma}.
   		\end{aligned}
   	\end{equation}

   	The first term in the left hand side of \eqref{identity for mfd} could be dropped due to the condition $Ric(M)\ge 0$. Then a comparable process also produces these two formulae.
   \end{rmk}
   \begin{rmk}
   	It can be easily seen that
   	\begin{equation*}
   			\int u^{-\frac{2\beta}{n+2}-2}|\nabla u|^{4}\eta^{\gamma}+\int u^{-\frac{2\beta}{n+2}} f^{2}(u)\eta^{\gamma}\le C(n,\beta)\int  u^{-\frac{2\beta}{n+2}+2}\eta^{\gamma-4}|\nabla \eta|^{4}.
   	\end{equation*}
   	 The above formula is a special case of \rm(\hspace{-0.03em}\cite[Lemma 5.3]{he2025optimalliouvilletheoremslaneemden}).
   \end{rmk}
   \subsection{Proof of Theorem 1.5} From \eqref{second integral inequality} and \eqref{condition of mainthm2}, we immediately get
   \begin{equation}\label{integrate estimate for thm1.4}
   			\int u^{\frac{2n+2}{n+2}\beta} \eta^{\gamma}\le C(n,\beta)\int  u^{-\frac{2\beta}{n+2}+2}\eta^{\gamma-4}|\nabla \eta|^{4}.
   \end{equation}

   Now the same argument as in \cite{MW} is available.  We sketch the proof here. Since  $1<\beta<\frac{n+2}{n-2}$ suggests $2-\frac{2\beta}{n+2}>2-\frac{2}{n-2}>0$ and $\frac{2n+2}{n+2}\beta+\frac{2\beta}{n-2}-2=2\beta-2>0$, Young's inequality implies that
   \begin{equation*}
   	     C(n,\beta)\int  u^{-\frac{2\beta}{n+2}+2}\eta^{\gamma-4}|\nabla \eta|^{4}\le \frac{1}{2} \int u^{\frac{2n+2}{n+2}\beta} \eta^{\gamma}
   	     +C_{1}(n,\beta)\int \eta^{\gamma-\frac{4(n+1)\beta}{(n+2)(\beta-1)}}
   	     |\nabla \eta|^{\frac{4(n+1)\beta}{(n+2)(\beta-1)}}.
   \end{equation*}
   Consequently, we choose $\gamma=1+\frac{4(n+1)\beta}{(n+2)(\beta-1)}$ to obtain that
   \begin{equation}\label{finalestimate1}
   		\int_{B_{R}} u^{\frac{2n+2}{n+2}\beta} \le C_{1}(n,\beta)R^{n-\frac{4(n+1)\beta}{(n+2)(\beta-1)}}.
   \end{equation} 
   Since
   \begin{equation*}
   	n-\frac{4(n+1)\beta}{(n+2)(\beta-1)}=\frac{(n^{2}-2n-4)\beta-n(n+2)}{(n+2)(\beta-1)}
   \end{equation*} 
   and
   \begin{equation*}
   	(n^{2}-2n-4)\beta-n(n+2)<-\frac{4(n+2)}{n-2}<0,
   \end{equation*} we know the right hand side of \eqref{finalestimate1} tends to zero as $R\to \infty$.
   This contracts the positivity of $u$ and suggests \eqref{main equ} admits no positive solution. Recall $f(u)$ possesses at least one root in $[0,\infty)$, \eqref{condition of mainthm2} means the only zero point of $f$ is $u=0$. Thus the only trivial solution of \eqref{main equ} is $u\equiv 0$. This completes the proof. \qed

   \subsection{Proof of Theorem 1.6}
   	  We first prove (ii). Since $f$ is subcritical, \eqref{subcritical} implies 
   	   \begin{equation}\label{subcritical2}
   	   	\left(u^{-\beta}f(u)\right)'\le 0,
   	   \end{equation}
   	   where the derivative is with respect to $u$. Meanwhile, \eqref{condition of mainthm3} suggests there exist some  $u_{0}$ sufficiently large such that 	$f(u)\ge u^{\alpha}$ holds for $u\ge u_{0}$ (Without loss of generality, we choose $u_{0}>1$). Therefore $f(u_{0})>0$. Integrate \eqref{subcritical2} from $u_{0}$ to $u$ to get
   	   \begin{equation}\label{inequ for u large}
   	   	    u^{\alpha}\le f(u)\le \frac{f(u_{0})}{u_{0}^{\beta}}u^{\beta},\qquad u\ge u_{0}.
   	   \end{equation}

   	   It is worthy mentioning that \eqref{inequ for u large} suggests $\alpha\le \beta$ (See \cite{SZ}, page 102). Proceeding in a similar manner, we also derive 
   	   \begin{equation}\label{inequ for u small}
   	    f(u)\ge \frac{f(u_{0})}{u_{0}^{\beta}}u^{\beta},\qquad u< u_{0}.
   	   \end{equation}

   	    We use a trick in the proof of \cite[Theorem 2.8]{he2025optimalliouvilletheoremslaneemden}. Decompose $\bR^{n}$ into two disjoint parts $\{u<u_{0}\}$ and $\{u\ge u_{0}\}$. More precisely,
   	    \begin{equation*}
   	    	\{u\ge u_{0}\}\triangleq \{x\in \bR^{n}:\; u(x)\ge u_{0}\}.
   	    \end{equation*}
   	    Now we aim to derive an integral estimate similar to \eqref{second integral inequality}. Note that
   	    $$ -\frac{2\beta}{n+2}+2=\frac{2\beta}{n+2}\cdot \frac{n+2-\beta}{\beta}$$
   	    and 
   	    \begin{equation*}
   	    	p_{1}=\frac{(n+1)\beta}{n+2-\beta}>1,\qquad q_{1}=\frac{(n+1)\beta}{(n+2)(\beta-1)}>0.
   	    \end{equation*}
   	    By virtue of H\"{o}lder's inequality with the respective exponent pair $(p_{1},q_{1})$, it yields 
   	    \begin{equation}\label{estimate for small}
   	    	\begin{aligned}
   	    		\int_{\{u<u_{0}\}} u^{-\frac{2\beta}{n+2}+2} \eta^{\gamma-4} |\nabla\eta|^{4}
   	    		&\le \left( \int_{\{u<u_{0}\}} u^{\frac{(2n+2)\beta}{n+2}} \eta^{\gamma} \right)^{\frac{n+2-\beta}{(n+1)\beta}} \\
   	    		&\quad \times \left( \int_{\{u<u_{0}\}} \eta^{\gamma-\frac{(4n+4)\beta}{(n+2)(\beta-1)}} |\nabla \eta|^{\frac{(4n+4)\beta}{(n+2)(\beta-1)}} \right)^{\frac{(n+2)(\beta-1)}{(n+1)\beta}} \\
   	    		&\le C(n,\beta) \left( \int_{\{u<u_{0}\}} f^{2}(u) u^{-\frac{2\beta}{n+2}} \eta^{\gamma} \right)^{\frac{n+2-\beta}{(n+1)\beta}} \\
   	    		&\quad \times \left( \int_{\{u<u_{0}\}} \eta^{\gamma-\frac{(4n+4)\beta}{(n+2)(\beta-1)}} |\nabla \eta|^{\frac{(4n+4)\beta}{(n+2)(\beta-1)}} \right)^{\frac{(n+2)(\beta-1)}{(n+1)\beta}}. \\
   	    	\end{aligned}
   	    \end{equation}
