				 &\quad +C(n,\beta) \left( \int_{\{u\ge u_{0}\}} f^{2}(u)u^{-\frac{2\beta}{n+2}} \eta^{\gamma} \right)^{\frac{n+2-\beta}{(n+2)\alpha-\beta}} \\
				 &\quad \times \left( \int_{\{u\ge u_{0}\}} \eta^{\gamma-4\frac{(n+2)\alpha-\beta}{(n+2)(\alpha-1)}} |\nabla \eta|^{4\frac{(n+2)\alpha-\beta}{(n+2)(\alpha-1)}} \right)^{\frac{(n+2)(\alpha-1)}{(n+2)\alpha-\beta}}.
		\end{aligned}
	\end{equation}
  	We choose $$\gamma=\max\left\{ 1+\frac{(4n+4)\beta}{(n+2)(\beta-1)},1+4\frac{(n+2)\alpha-\beta}{(n+2)(\alpha-1)} \right\}  $$
  	in \eqref{equ 4.19} and use Young's inequality. By the definition of $\eta$, it provides
  	\begin{equation}\label{finalestimate2}
  		\int_{B_{R}}  u^{-\frac{2\beta}{n+2}} f^{2}(u) \le C(n,\alpha,\beta)\left[R^{n-4\frac{(n+1)\beta}{(n+2)(\beta-1)}}+R^{n-4\frac{(n+2)\alpha-\beta}{(n+2)(\alpha-1)}}\right].
  	\end{equation}

  We claim that the exponents in the right hand side of \eqref{finalestimate2} are both negative. For $n=3$, the first exponent becomes
  \begin{equation*}
  	3-\frac{16\beta}{5(\beta-1)}=\frac{-\beta-15}{5(\beta-1)}<0.
  \end{equation*}
  For $n\ge 4$, we have
  \begin{equation*}
  	n-4\frac{(n+1)\beta}{(n+2)(\beta-1)}< n-\frac{4(n+1)}{n+2}\left(1+\frac{n-2}{4}\right)=-1<0.
  \end{equation*}
  Thus the first exponent is negative. Concerning the second index, we have
  \begin{equation*}
  	n-4\frac{(n+2)\alpha-\beta}{(n+2)(\alpha-1)}=\frac{n(n+2)(\alpha-1)-4(n+2)\alpha+4\beta}{(n+2)(\alpha-1)}.
  \end{equation*}
  A straightforward computation shows
  \begin{equation}\label{determiant}
  	n(n+2)(\alpha-1)-4(n+2)\alpha+4\beta=(n^{2}-2n-8)\alpha-n^{2}-2n+4\beta.
  \end{equation}
  For $n=3$, we use the fact $\beta<5$ and $\alpha>1$ and \eqref{determiant} becomes
  \begin{equation*}
  	 -5\alpha-9-6+4\beta<-5\alpha+5<0.
  \end{equation*}
  For  $n\ge 4$, since $n^{2}-2n-8\ge 0$, we have that
  \begin{align*}
  	(n^{2}-2n-8)\alpha-n^{2}-2n+4\beta&\le (n^{2}-2n-4)\beta-n^{2}-2n \\
  	&<  (n^{2}-2n-4)\frac{n+2}{n-2}-n^{2}-2n\\
  	&<0.
  \end{align*}  

   Therefore, the negativity of \eqref{determiant} implies that the second exponent is also negative. Letting $R\to \infty$, \eqref{finalestimate2}
   suggests that $f(u)\equiv 0$ which contracts \eqref{condition of mainthm3}.
   Consequently, \eqref{main equ} admits no positive solution. Furthermore, \eqref{inequ for u large} suggests $f$ has no zero point in $[u_{0},\infty)$. If $f(u)$  vanishes at a nonzero  $\xi\in (0,u_0)$,
    then take $u=\xi$ in \eqref{inequ for u small} to derive
    $$  0=f(\xi)\ge \frac{f(u_{0})}{u_{0}^{\beta}}\xi^{\beta}>0,$$
   which is impossible. The above discussion indicates that the unique zero point of $f$ is $u=0$ and the only trivial solution of \eqref{main equ} is $u\equiv 0$. This proves (ii).

   For the special case $n=3$, a stronger conclusion holds if  $u$ is bounded, i.e. $u\le L$. We note that the derivation of \eqref{second integral inequality} does not require super-power condition like \eqref{superpower}. In this case, directly from \eqref{second integral inequality},
   we set $\gamma=4$, $n=3$  and easily get 
   \begin{equation}\label{finalestimate3}
   	   \int_{B_{R}} u^{-\frac{2\beta}{n+2}} f^{2}(u)\le C(n,\beta,L)R^{-1}.
   \end{equation}
   Hence $f(u)\equiv 0$ and the classical Liouville theorem for harmonic functions implies that $u$ is constant.  This proves (i). \qed
