	\arrow["{(4)}", equals, from=2-3, to=2-2]
	\arrow["{(6)}"', equals, from=2-3, to=2-4]
	\arrow["{(1)}"', equals, from=1-1, to=2-1]
\end{tikzcd}\]
\begin{multicols}{2}
    \begin{enumerate}
        \item \cite[Remark 3.4]{campionmaehara}
        \item \ref{prop:comparaison of gray tensor product}
        \item \cite[Remark 1.4.19]{Effectivity}
        \item \cite[Remark 1.4.19]{Effectivity} 
