\noindent As of yet,  no proof of \cite[Proposition 10.4.5.4]{GR}  has appeared in the literature. Its demonstration will be our second and last contribution of this paper:

\begin{thmintro}
    \label{thmintro:comparison}
    Let $\C,\D$ and $\E$ be $(\infty,2)$-categories. There exists a natural equivalence 
    $$
    \map(\C_h\times \D_v,\Sq(\E))\simeq \map(\C\otimes \D,\E).
    $$
\end{thmintro}

The proof of this result will be the subject of \ref{section:comparison}.
As will be explained in \ref{section:cech and sq}, the functor $\Sq$ admits a left adjoint that we will denote by $\Gr$. By the Yoneda lemma, the previous theorem is then formally equivalent to asserting the existence of an equivalence
    $$
    \Gr(\C_h \times \D_v) \simeq \C \otimes \D
    $$
that is natural in $(\infty,2)$-categories $\C$ and $\D$.

It should be noted that the original conjecture is slightly different as it stipulates not only that there exists such an equivalence, but that it is realized through the comparison map defined by Gaitsgory and Rozenblyum in \cite[Subsection 10.4.5]{GR}. However, we will show in \ref{prop:auto of gray} that any natural transformation $(-)\otimes(-)\to (-)\otimes(-)$ must be the identity. Consequently, the original comparison map constructed by Gaitsgory and Rozenblyum, and the one considered here necessarily coincide.



\subsection*{Conventions} We will make use of the following notation and terminology throughout the article:
\begin{itemize}
    \item We will write $\infty\Cat$ and $\S$ for the $\infty$-categories of $\infty$-categories and spaces (or $\infty$-groupoids).
    \item The functor $\tau_{0}:\infty\Cat\to \S$ denotes the functor that carries an $\infty$-category to its underlying $\infty$-groupoid, i.e.\ the right adjoint to the inclusion $\S \subset \infty\Cat$. We will write $\tau_{0}^i:\infty\Cat\to \S$ for the left adjoint to this inclusion, called the \textit{groupoidification functor}.
    \item  If $\C$ is an $\infty$-category, we will write $\PSh(\C) := \fun(\C^\op, \S)$ for the $\infty$-category of presheaves on $\C$, and $\PSh_{\mathrm{Set}}(\C):= \fun(\C^\op, \mathrm{Set}) \subset \PSh(\C)$ for the full subcategory of set-valued presheaves on $\C$.
    \item Throughout the text, we will use the \textit{oplax} variant of the Gray tensor product for 2- and $(\infty,2)$-categories. We recall the definitions in \ref{section:prelims}.
    \item We will say that a a subcategory $\C$ of an $\infty$-category $\D$ is \textit{dense} when the induced nerve functor $\D\to \PSh(\C)$, obtained by restricting the Yoneda embedding on $\D$, is fully faithful. In all the situations that we will encounter, $\C$ is a small and $\D$ is cocomplete. In such case, this implies that $\D$ is a reflective subcategory of $\PSh(\C)$, and that any object $x\in\D$ can be canonically expressed as the colimit of the functor $\C_{/x}\to \C \to \D$.
\end{itemize}

\section{Two-dimensional $\infty$-categories}\label{section:prelims}

We will commence by briefly collecting the basic definitions and aspects of $(\infty,2)$-categories and double $\infty$-categories.

\subsection{Shapes for $(\infty,2)$-categories} We recall that, on account of \cite{JoyalTierney}, the full inclusion of the subcategory $\Delta \to \infty\Cat$ is dense. The essential image of the induced inclusion $\infty\Cat \to \PSh(\Delta)$ selects the \textit{Segal spaces} that are \textit{complete} in the sense of Rezk \cite{RezkSeg}. We collect these two notions here:

\begin{definition}\label{def:segal spaces}
    A presheaf $\C : \Delta^\op \to \S$ is called a Segal space if for every $n \geq 0$, the canonical map 
    $$
    \C([n]) \to \C([1]) \times_{\C([0]} \dotsb \times_{\C([0])} \C([1])
    $$
    is an equivalence. Let $J$ be the simplicial set defined by the pushout square 
    \[ \begin{tikzcd}
        {[1] \sqcup [1]} \arrow[rr, "{(\{0 \leq 2\}, (\{1\leq 3\})}"]\arrow[d] && {[3]} \arrow[d] \\
        {[0] \sqcup [0]} \arrow[rr] && J
    \end{tikzcd}
    \] 
    in $\PSh(\Delta)$.
    The Segal space $\C$ is said to be \textit{complete} if it is local with respect to the map $J \to [0]$, i.e. $\C([0]) = \map_{\PSh(\Delta)}([0], \C) \to \map_{\PSh(\Delta)}(J, \C)$ is an equivalence.
\end{definition} 

\begin{remark}
    Let $\C$ be a Segal space.
    The inclusion $[1] \xrightarrow{\{0\leq 1\}} [3] \to J$ induces a monomorphism $\map_{\PSh(\Delta)}(J,\C) \to \map_{\PSh(\Delta)}([1], \C) = \C([1])$ that selects those arrows that are equivalences. This is the content of \cite[Theorem 6.2]{RezkSeg}.
\end{remark}

We may similarly define $(\infty,2)$-categories as presheaves on a suitable collection of 2-categorical shapes. 

\begin{definition}
A (strict) 2-category is called \textit{gaunt} if the only invertible 1- and 2-cells are identities. We will write $2\Gaunt$ for the full subcategory of the category of strict 2-categories spanned by the gaunt 2-categories.
\end{definition}

Important examples of gaunt 2-categories are Joyal's \textit{globular sums}:

\begin{definition}\label{def:glob sums}
Suppose that $n$ is a non-negative integer. Consider a tuple $\overline{m} = (m_0,...,m_{n-1})$ of non-negative integers. Then we will write
$[n;\overline{m}]$ for the gaunt $2$-category whose objects are given by $0, 1, ..., n$ and such that for any $0\leq i,j \leq n$, 
$$[n;\overline{m}](i,j):=\begin{cases}
[m_i]\times \dotsb \times [m_{j-1}] & \text{if $i \leq j$,} \\
\emptyset & \text{otherwise.}
\end{cases}$$
We will write $\Theta_2$ for the full subcategory of $2\Gaunt$ whose objects are of the shape $[n;\overline{m}]$ for some $n$ and tuple $m$. 
The objects in $\Theta_2$ are referred to as \textit{globular sums}. Note that we have full inclusion 
$\Delta\to \Theta_2$ sending $[n]$ onto the globular sum $[n;(0,...,0)]$.
\end{definition}




\begin{definition}
A presheaf $\C :\Theta_2^\op \to \S$ is called an \textit{$(\infty,2)$-category} if:
\begin{itemize}
    \item for any tuple $\overline{m}=(m_0,...,m_{n-1})$, the canonical map 
    $$\C([n;\overline{m}])\to \C([1;m_0])\times_{\C([0])}...\times_{\C([0])}\C([1;m_{n-1}])$$ is an equivalence,
    \item for any $n \geq 0$, the canonical map 
    $$\C([1;n])\to \C([1;1])\times_{\C([1])}...\times_{\C([1])}\C([1;1])$$
    is an equivalence,
    \item $\C$ is local with respect to the maps $J \to [0]$ and $[1;J] \to [1]$, where $[1;J]$ is defined by the pushout square
    \[ \begin{tikzcd}
        {[1;1] \sqcup [1;1]} \arrow[rr, "{[1;(\{0 \leq 2\}, (\{1\leq 3\})]}"]\arrow[d] && {[1;3]} \arrow[d] \\
        {[1] \sqcup [1]} \arrow[rr] && {[1;J]}
    \end{tikzcd}
    \] 
    in $\PSh(\Theta_2)$.
\end{itemize}
We will write $(\infty,2)\Cat \subset \PSh(\Theta_2)$ for the full subcategory spanned by the $(\infty,2)$-categories. 
\end{definition}

\begin{construction}
The involutions $\op : 2\Gaunt \to 2\Gaunt$ and $\co : 2\Gaunt \to 2\Gaunt$ given by reversing the directions of 1- and 2-cells respectively, both restrict to involutions $\op, \co : \Theta_2 \to \Theta_2$ of $\Theta_2$. In turn, these induce functors $\op^*, \co^* : \PSh(\Theta_2) \to \PSh(\Theta_2)$ that restrict to involutions $$(-)^\op, (-)^\co : (\infty,2)\Cat \to (\infty,2)\Cat,$$
respectively.
\end{construction}

\begin{notation}
We follow the notation in \cite[Definition 1.1.5]{Effectivity}. There is a canonical inclusion 
$\iota : \infty\Cat \rightarrow (\infty,2)\Cat$ that is obtained by left Kan extending the functor $\Delta \rightarrow (\infty,2)\Cat$ along the inclusion $\Delta \to \infty\Cat$. We will leave the notation of $\iota$ implicit throughout this paper. The functor $\iota$ admits a right adjoint $$\tau_{1}:(\infty,2)\Cat\to \infty\Cat,$$ called the \textit{$1$-truncation} that forgets the $2$-cells. Moreover, $\iota$ admits a left adjoint $$\tau^i_{ 1}:(\infty,2)\Cat\to \infty\Cat$$ that is called the \textit{intelligent $1$-truncation} or \textit{$1$-core}, and inverts the $2$-cells.
We will simply write $\tau_{0}$ and $\tau^i_{0}$ for the functors $(\infty,2)\Cat\to \S$ given by the composites $\tau_{0}\tau_{1}$ and $\tau^i_{0}\tau^i_{ 1}$ respectively.
\end{notation}

\begin{construction}\label{def:discrete}
The canonical inclusion 
$\Theta_2\to 2\Gaunt$ gives rise to an adjunction
\[
	{\Str:(\infty,2)\Cat} \rightleftarrows {2\Gaunt:N}.
\]
The resulting functor $N$ is fully faithful, and its essential image is spanned by the \textit{discrete} $(\infty,2)$-categories, i.e.\ those $(\infty,2)$-categories $\C$ for which $\C([n;\overline{m}])$ is a set for all $[n;\overline{m}] \in \Theta_2$. We will leave the notation of $N$ implicit in what follows.
\end{construction}




\begin{construction}
For the sake of simplicity, we will write $[n;m]$ for the globular sum $[n;(m,...,m)]$. We will write $[\Delta;\Delta]$ for the 1-category that fits in the pushout square
\[\begin{tikzcd}
	{\{[0]\}\times \Delta} & {\Delta\times \Delta} \\
	{\{[0]\}} & {[\Delta;\Delta]}
	\arrow[from=1-1, to=1-2]
	\arrow[from=1-1, to=2-1]
	\arrow[from=1-2, to=2-2]
	\arrow[from=2-1, to=2-2]
\end{tikzcd}\]
of strict categories, which is in fact also a pushout square of $\infty$-categories.
One readily verifies that the bicosimplicial object $\Delta^{\times 2} \rightarrow 2\Gaunt : ([n],[m]) \mapsto [n;m]$ factors to a functor $[\Delta;\Delta]\to 2\Gaunt$.
By \cite[Remark 1.1.10]{Effectivity} or \cite[Remark 3.10]{CompJaco}, the (non-full) subcategories
$$[\Delta;\Delta] \to 2\Gaunt \quad \mbox{and} \quad [\Delta;\Delta]\to 2\Gaunt \to  (\infty,2)\Cat$$
are dense.
\end{construction}



\subsection{The Gray tensor product for gaunt 2-categories} In this subsection, we gather the basics of the oplax Gray tensor product for gaunt $2$-categories.



\begin{notation}
We will write $$(-) \otimes_G (-):2\Gaunt\times 2\Gaunt \to 2\Gaunt$$ for the oplax Gray tensor product of gaunt 2-categories. This operation was originally defined by Gray in \cite{gray2006formal}.  
\end{notation}


\begin{remark}
Given two gaunt 2-categories $A$ and $B$, $A \otimes_G B$ is generated by $k$-cells of shape $a\otimes_G b$ where $a$ is a $(k-i)$-cell of $A$ and $b$ is an $i$-cell of $B$. The composition of these cells is subject to several coherence equations, as described, for example, in \cite[Section 3.1]{maehara2021gray}.
\end{remark}

\begin{remark}
\label{rem:when factor throug tau1}
A functor $\phi:A\otimes_GB\to E$ between gaunt 2-categories factors through $A \otimes_G\tau^i_1B$ if and only if for any $0$-cell $a$ in $A$ and any $2$-cell $b$ in $B$, $\phi(a\otimes_G b)$ is an identity 2-cell.
\end{remark}

\begin{proposition}
\label{prop:auto of gray gaunt}
The functor $\otimes_G$, viewed as an object of  $\fun(2\Gaunt\times 2\Gaunt,2\Gaunt)$, admits no non-trivial endomorphism.
\end{proposition}
\begin{proof}
Let $\phi:\otimes_G\to \otimes_G$ be an endomorphism. We will show that for any pair of gaunt $2$-categories $A$ and $B$, the component $\phi_{A,B}:A\otimes_G B\to A \otimes_G B$ is given by the identity.


\textit{The functor $\phi_{A,B}$ is the identity on objects.} Note that $[0] \otimes_G [0] = [0]$, so that $\phi_{[0],[0]}= \id_{[0]}$. Suppose that we have objects $a\in A$, $b\in B$, then commutativity of the naturality square
\[\begin{tikzcd}
	{[0]\otimes_G[0]} & {A\otimes_G B} \\
	{[0]\otimes_G[0]} & {A\otimes_G B}
	\arrow["{a\otimes_G b}", from=1-1, to=1-2]
	\arrow[equals, from=1-1, to=2-1]
	\arrow["{\phi_{A,B}}", from=1-2, to=2-2]
	\arrow["{a\otimes_G b}"', from=2-1, to=2-2]
\end{tikzcd}\]
implies that $\phi(a\otimes_G b)=a\otimes_G b$.

\textit{The functor $\phi_{A,B}$ is the identity on $1$-cells.} Note that $[1] \otimes_G [0] = [1]$. Hence $\phi_{[1], [0]}$ is an endofunctor of $[1]$ that acts as the identity on objects on account of the previous step. Since $[1]$ is a poset, this implies that $\phi_{[1],[0]}$ is the identity. Similarly, one deduces that $\phi_{[0],[1]}$ is the identity.
Suppose now that we are given a $1$-cell $f : a \to a'\in A$, and an object $b\in B$.
The commutativity of the naturality square
\[\begin{tikzcd}
	{[1]\otimes_G[0]} & {A\otimes_G B} \\
	{[1]\otimes_G[0]} & {A\otimes_G B}
	\arrow["{f\otimes_G b}", from=1-1, to=1-2]
	\arrow[equals, from=1-1, to=2-1]
	\arrow["{\phi_{A,B}}", from=1-2, to=2-2]
	\arrow["{f\otimes_G b}"', from=2-1, to=2-2]
\end{tikzcd}\]
implies that $\phi(f\otimes_G b)=f\otimes_G b$. We can show similarly that $\phi(a\otimes_G g)=a\otimes_G g$ for any object $a \in A$ and any $1$-cell $g: b\to b' \in B$. 
As every $1$-cell of $A\otimes_G B$ can be expressed as a composite of $1$-cells of the shape $f\otimes_G b$ or $a\otimes_G g$, this implies that $\tau_1\phi_{A,B}:\tau_1(A\otimes_G B)\to \tau_1(A\otimes_G B)$ is the identity.

\textit{The functor $\phi_{A,B}$ is the identity on $2$-cells.} We now remark that the gaunt 2-categories $[1]\otimes_G [1], [1;1] \otimes_G [0]$ and $[0]\otimes_G [1;1]$ share the following property: for any pair of parallel $1$-cells, there exists at most one $2$-cell between them. 
As we already established that the components of $\phi$ are the identity on $1$-cells, this implies that $\phi_{[1],[1]}$, $\phi_{[1;1],[0]}$
and $\phi_{[0],[1;1]}$ are identities. Using the same naturality argument as before, this implies that $\phi_{A,B}(f\otimes_G g)=f\otimes_G g$ where $f$ is a $k$-cell of $A$ and $g$ a $(2-k)$-cell of $B$. The natural transformation $\phi_{A,B}$ then acts as the identity on the generating $2$-cells of $A\otimes_G B$, and therefore must be the identity on $2$-cells as well.
\end{proof}


\subsection{The Gray tensor product for $(\infty,2)$-categories} 
We will follow here the approach of Maehara \cite{maehara2021gray}, but adapted to space-valued presheaves instead of set-valued presheaves on $\Theta_2$. We refer to  \ref{subsection:introduction on Gray} of the introduction for an overview of the different definitions of this operations, and the links they maintain.



\begin{construction}[Maehara]The functor
$$
\Theta_2 \times \Theta_2 \to (\infty,2)\Cat : (a,b) \mapsto a \otimes_G b
$$
extends to a unique functor $\PSh(\Theta_2) \times \PSh(\Theta_2) \rightarrow (\infty,2)\Cat$ that preserves colimits in both variables. This then restricts to a functor
$$(-)\otimes(-):(\infty,2)\Cat\times (\infty,2)\Cat \to (\infty,2)\Cat$$
that will be called the \textit{(oplax) Gray tensor product}.
\end{construction}


\begin{theorem}[Maehara]
\label{theo:Gray tensor product preserves colimits}
The Gray tensor product preserves colimits in both variables.
\end{theorem}

\begin{proof}
The extension $\PSh(\Theta_2) \times \PSh(\Theta_2) \rightarrow (\infty,2)\Cat$ preserves colimits in both variables and sends each spine inclusion and completeness extension to an equivalence on account of \cite[Subsection 6]{maehara2021gray}.
\end{proof}

\begin{theorem}[Maehara]
\label{theo:Gray tensor of globular sums}
The canonical map
$$a_0\otimes a_1\otimes...\otimes a_n\to a_0\otimes_Ga_1\otimes_G ...\otimes_G a_n$$
is an equivalence for every sequence $a_0, a_1,...,a_n$ of globular sums.
\end{theorem}

\begin{proof}
This is the content of  \cite[Corollary 7.11]{maehara2021gray}.
\end{proof}

\begin{corollary} 
The Gray tensor product extends to a monoidal structure on $(\infty,2)\Cat$ such that $\Str:(\infty,2)\Cat\to 2\Gaunt$ is a (strong) monoidal functor.
\end{corollary}

\begin{proof}
Let $\left<\Theta_2 \right>$ be the smallest full subcategory of $2\Gaunt$ that includes $\Theta_2$ and that is stable under the Gray tensor product $\otimes_G$. As $\left<\Theta_2 \right>$ includes $\Theta_2$, it is again a dense subcategory of $(\infty,2)\Cat$. The associated fully faithful functor $(\infty,2)\Cat \rightarrow \PSh(\left<\Theta_2 \right>)$ given by restricting the Yoneda embedding admits a left adjoint
$$L:\PSh(\left<\Theta_2 \right>)\to (\infty,2)\Cat$$ that is given by $L'i^*$ where $L'$ is the left adjoint to the inclusion $(\infty,2)\Cat \rightarrow \PSh(\Theta_2)$.

By Day convolution (\cite[Proposition 4.8.1.10]{LurieHigherAlgebra} or \cite[Proposition 2.14]{glasman2016day}), the monoidal structure on $\left<\Theta_2\right>$ induces a monoidal structure on $\PSh(\left<\Theta_2\right>)$ whose tensor product will be denoted by $\widehat{\otimes}_G$. It has the property that  $\widehat{\otimes}_G$ commutes with colimits in both variables, and the Yoneda embedding $\left<\Theta_2\right> \to \PSh(\left<\Theta_2\right>)$ upgrades to a monoidal functor. If $X, Y \in \PSh(\left<\Theta_2\right>)$, then there is a natural equivalence $L(X \widehat{\otimes}_G Y) \simeq LX \otimes LY$ in $(\infty,2)\Cat$. This follows from the observation that both sides commute with colimits in the variables $X$ and $Y$, so that we may reduce checking for $X, Y \in \left< \Theta_2\right>$ by density. The desired conclusion then follows from \ref{theo:Gray tensor of globular sums}. We may  then use \ref{theo:Gray tensor product preserves colimits} to deduce that the localization functor $L$ is compatible with the monoidal structure on $\PSh(\left< \Theta_2 \right>)$ in the sense of \cite[Definition 2.2.1.6]{LurieHigherAlgebra}. Thus \cite[Proposition 2.2.1.9]{LurieHigherAlgebra} implies that the monoidal structure on $\PSh(\left<\Theta_2\right >)$ transfers to a monoidal structure on $(\infty,2)\Cat$ so that $L$ is monoidal. 


To see that $\Str$ is monoidal, note that the monoidal inclusion $\left<\Theta_2\right> \to 2\Gaunt$ extends to a monoidal functor $\PSh(\left<\Theta_2\right>) \to 2\Gaunt$ by the universal property of Day convolution. This then derives to a monoidal functor $(\infty,2)\Cat \to 2\Gaunt$ whose underlying functor is precisely $\Str$.
\end{proof}


\begin{proposition}
\label{prop:auto of gray}
The functor $\otimes$, viewed as an object of $\fun((\infty,2)\Cat\times (\infty,2)\Cat,(\infty,2)\Cat)$, has no non-trivial endomorphism.
\end{proposition}
\begin{proof}  
As $\Theta_2$ is a dense subcategory of $2\Gaunt$ and $(\infty,2)\Cat$, the two functors
\begin{gather*}
\fun(2\Gaunt\times 2\Gaunt,2\Gaunt) \to \fun(\Theta_2 \times \Theta_2, 2\Gaunt), \\
\fun((\infty,2)\Cat\times (\infty,2)\Cat,(\infty,2)\Cat) \to \fun(\Theta_2 \times \Theta_2, (\infty,2)\Cat)
\end{gather*}
given by restriction are both fully faithful when restricted to functors that are cocontinuous in each variable.
Since the inclusion $2\Gaunt\to (\infty,2)\Cat$ is fully faithful, we obtain the following equivalences between mapping spaces:
\begin{align*}
\map_{\fun((\infty,2)\Cat^{\times 2},(\infty,2)\Cat)}(\otimes, \otimes) &\simeq \map_{\fun(\Theta_2^{\times 2}, (\infty,2)\Cat)}(\otimes|\Theta_2^{\times 2},\otimes|\Theta_2^{\times 2}) \\
&\simeq \map_{\fun(\Theta_2^{\times 2},2\Gaunt)}(\otimes_G|\Theta_2^{\times 2},\otimes_G|\Theta_2^{\times 2}) \\
&\simeq \map_{\fun(2\Gaunt^{\times 2},2\Gaunt)}(\otimes_G,\otimes_G).
\end{align*}
Hence  \ref{prop:auto of gray gaunt} implies that the space of endomorphisms of $\otimes$ is contractible.
\end{proof}



We record the following facts that will be of use later:


\begin{proposition}
For any two $(\infty,2)$-categories $\C$ and $\D$, there are natural equivalences
$$(\C\otimes \D)^{\op}\simeq \D^{\op}\otimes \C^{\op} ~~ \text{and} ~~ (\C\otimes \D)^\co \simeq \D^\co\otimes \C^\co.$$
\end{proposition}
\begin{proof}
We may reduce to the case that $\C$ and $\D$ are globular sums. As the Gray tensor product of globular sums is gaunt, the result follows from \cite[Proposition A.20]{ara2020joint}.
\end{proof}

