\[\begin{tikzcd}
	{[1;[n]\times\{0\}\times [m]]} && {[1;[n]\times\{1\}\times [m]]} \\
	{[2;n,m]} & {[1;[n]\times[1]\times [m]]} & {[2;m,n]}
	\arrow[from=1-1, to=2-1]
	\arrow[from=1-1, to=2-2]
	\arrow[from=1-3, to=2-2]
	\arrow[from=1-3, to=2-3]
\end{tikzcd}\]
of gaunt 2-categories in $(\infty,2)\Cat$. 
Let $F_{n,m} : M \to 2\Gaunt$ be the functor that shapes the above diagram.
On account of \ref{lemma:square as a colimit}, there is an equivalence 
$$
\tau_2^i([1]\otimes^{\omega}_L[1])\simeq \colim(M \xrightarrow{F_{0,0}} 2\Gaunt \to (\infty,2)\Cat \to \PSh(\Theta_2)).
$$
in $\PSh(\Theta_2)$. As the natural transformation $F_{n,m}\to F_{1,1}$ is cartesian, \cite[Proposition 2.2.1.27]{loubaton2024categorical} implies that there is an equivalence 
$$
\tau_2^i([1;n]\otimes^{\omega}_L[1;m])\simeq \colim(M \xrightarrow{F_{n,m}} 2\Gaunt \to (\infty,2)\Cat \to \PSh(\Theta_2))
$$
in $\PSh(\Theta_2)$.
The composite $2\Gaunt \to (\infty,2)\Cat \to \PSh(\Theta_2)$ factors  through the inclusion $\PSh_{\mathrm{Set}}(\Theta_2) \to \PSh(\Theta_2)$ that is induced by the functor $\mathrm{Set} \to \S$; see \ref{def:discrete}. Now \cite[Lemma 2.1.1.5]{loubaton2024categorical} implies that
\begin{align*}
\tau_2^i([1;m]\otimes^{\omega}_L[1;n]) &\simeq \colim(M \xrightarrow{F} 2\Gaunt \to \PSh_{\mathrm{Set}}(\Theta_2) \to \PSh(\Theta_2)) 
\\&\simeq \colim(M \xrightarrow{F} 2\Gaunt \to \PSh_{\mathrm{Set}}(\Theta_2)) 
\end{align*}
in $\PSh(\Theta_2)$. So $\tau_2^i([1;m]\otimes^{\omega}_L[1;n])$ is discrete, and thus gaunt.
\end{proof}





\subsection{Double $\infty$-categories}\label{subsection:dbl cats} We now recall the necessary material on double $\infty$-categories.

\begin{definition}
    A bisimplicial space $\P : \Delta^\op \times \Delta^\op \to \S$ is called a \textit{double $\infty$-category} if:
    \begin{itemize}
        \item the restrictions $\P([n],-) : \Delta^\op \to \S$ is a complete Segal space for every $n \geq 0$
        \item the restriction $\P(-,[m]) : \Delta^\op \to \S$ is a Segal space for every $m \geq 0$. 
    \end{itemize}
    We will write $\DbliCat \subset \PSh(\Delta^{\times 2})$ for the full subcategory spanned by the double $\infty$-categories.
\end{definition}

\begin{notation}
    The Yoneda embedding $\Delta^{\times 2} \to \PSh(\Delta^{\times 2})$ factors through $\DbliCat$. We will write $\langle n,m \rangle$ for the double $\infty$-category given by the image of $([n],[m])$.

    This was previously denoted by $[n,m]$ in \cite{JacoThesis} and \cite{CompJaco}, but we have opted for this notation here to make it better distinguishable from the objects of $[\Delta;\Delta]$.
\end{notation}

\begin{remark}
    Equivalently, a double $\infty$-category $\P$ is the datum of a functor $\P_\bullet :  \Delta^\op \to \infty\Cat$ so that the canonical functor $\P_n \to \P_1 \times_{\P_0} \dotsb \times_{\P_0} \P_1$ is an equivalence, where $\P_n$ is defined by the formula: $$\map_{\infty\Cat}([m], \P_n) =  \map_{\DbliCat}(\langle n,m \rangle, \P).$$
\end{remark}

\begin{definition}
   A double $\infty$-category $\P$ is called \textit{locally complete} if for every two objects $x,y \in \P$, the Segal space  
   $
   \P(-,[1]) \times_{\P(-,[0]) \times \P(-,[0])} \{(x,y)\}
   $
   is complete. More strongly, we will say that $\P$ is \textit{complete} if $\P(-,[1])$ is complete. We will write $\CDbliCat \subset \DbliCat$ for the full subcategory spanned by the complete double $\infty$-categories. 
\end{definition}

\begin{remark}
    The subcategory $\CDbliCat \subset \DbliCat$ is reflective. 
\end{remark}


\begin{remark}
    The $\infty$-categories $\DbliCat$ and $\CDbliCat$ (and also, the full subcategory spanned by the locally complete double $\infty$-categories) inherit the cartesian product from $\PSh(\Delta^{\times 2})$, and they are cartesian closed on account of \cite[Proposition 3.44]{CompJaco}.
\end{remark}

\begin{construction}\label{cons:dualities for double}
    We recall the following duality operations from \cite[Section 3]{CompJaco}.
There are involutions $\hop := \op \times \id, \vop := \id \times \op :\Delta\times \Delta \to \Delta \times \Delta$  that induce functors $\hop^*, \vop^* : \PSh(\Delta\times \Delta) \to \PSh(\Delta\times \Delta)$ and restrict to the \textit{horizontal} and \textit{vertical opposite} involutions $$(-)^\hop, (-)^\vop :\DbliCat\to \DbliCat,$$
respectively. 
We will also consider the \textit{transpose} duality. This is defined similarly. The functor $\tp : \Delta \times \Delta \to \Delta \times \Delta$ that swaps the coordinates, induces a functor $\tp^* : \PSh(\Delta\times \Delta)\to\PSh(\Delta\times\Delta)$ that restricts to an involution
$$
(-)^\tp : \CDbliCat \to \CDbliCat.
$$
We note that the strong completeness assumption is important here.
\end{construction}

\begin{notation}\label{not: vertical horizontal inclusion}
    We recall from \cite[Subsection 3.3]{CompJaco} that there are fully faithful functors
    $
    (-)_h, (-)_v : \PSh([\Delta;\Delta]) \to \PSh(\Delta^{\times 2})
    $
    that preserve colimits, and are determined by the fact that there are natural pushout squares 
    \[
    \begin{tikzcd}
	{\coprod_{k=0}^n\langle 0,m \rangle} & {\langle n,m \rangle} & {\coprod_{k\leq n}\langle m, 0 \rangle}^\hop & {\langle m,n\rangle}^\hop \\
	{\coprod_{k=0}^n\langle 0, 0 \rangle} & {[n;m]_h} & {\coprod_{k\leq n}\langle 0, 0\rangle} & {[n;m]_v}.
	\arrow[from=1-1, to=1-2]
	\arrow[from=1-1, to=2-1]
	\arrow[from=1-2, to=2-2]
	\arrow[from=1-3, to=1-4]
	\arrow[from=1-3, to=2-3]
	\arrow[from=1-4, to=2-4]
	\arrow[from=2-1, to=2-2]
	\arrow[from=2-3, to=2-4]
	\end{tikzcd}
	\]
	Since $[\Delta;\Delta]$ is dense in $(\infty,2)\Cat$, we may restrict these functors to $(\infty,2)$-categories. It follows from \cite[Subsection 3.4]{CompJaco} 
	that the functors  restrict to fully faithful and colimit preserving functors $$(-)_h, (-)_v : (\infty,2)\Cat \to \CDbliCat.$$
	These are called the \textit{horizontal} and \textit{vertical inclusion} functors respectively.
\end{notation}

\section{The directed \v{C}ech nerve and the squares construction}\label{section:cech and sq}

Given a morphism $f:A\to B$ between spaces, its \v{C}ech nerve, denoted by $\Cn(f)$, is defined to be the simplicial space that in degree $n$ corresponds to the $n$-fold iterated pullback
$$\Cn(f)_n = A\times_BA\times_B\dotsb \times_BA\;$$
see \cite[Subsection 6.1.2]{HTT}.
We will focus here on the categorification of this notion of \v{C}ech nerve that was introduced by the first author in \cite{Effectivity}. As a special case, we will recover the \textit{squares construction} that plays a fundamental role in the $(\infty,2)$-categorical set up of Gaitsgory and Rozenblyum \cite[Section 10.4]{GR}.

\begin{definition}
We will consider the full subcategory
$
\Filt \subset \fun([1], (\infty,2)\Cat)
$
of \textit{(1,1)-filtrations}, or simply, \textit{filtrations}, that is spanned by those functors $\C \to \D$ so that $\C$ is a $(\infty,1)$-category.

We will write 
$
\Filt^\twoheadrightarrow \subset \Filt
$ 
for the full subcategory spanned by the \textit{eso} (\textit{essentially surjective on objects}) filtrations $\C \to \D$, i.e. for which $\C \to \tau_{1}\D$ is essentially surjective.
\end{definition}

\begin{remark}\label{rem: trivial filtration}
    The functor $\Filt \to (\infty,2)\Cat$ given by evaluation at $1$ admits a right adjoint that carries an $(\infty,2)$-category $\C$ to the filtration $\tau_1\C \to \C$.
\end{remark}

\begin{construction}\label{cons: realization-nerve adjunction}
Let us consider the bicosimplicial filtration
$$
\textstyle \Delta \times \Delta \rightarrow \Filt : ([n],[m]) \mapsto  (\tau_0[n] \otimes [m] \rightarrow [n] \otimes [m]).
$$
The $\infty$-category $\Filt$ is cocomplete, and hence we obtain an  adjunction
$
 \PSh(\Delta \times \Delta) \rightleftarrows \Filt : \Cn(-)
$
so that the left functor is Kan extended from the bicosimplicial filtration.
For a filtration $f : \C \rightarrow \D$, $\Cn(f)$ is computed level-wise by 
$$
\textstyle \Cn(f)_{n,m} = \map_\Filt(\tau_0[n] \otimes [m] \rightarrow [n] \otimes [m], \C \xrightarrow{f} \D),
$$
and thus sits in a pullback square \[\begin{tikzcd}[ampersand replacement=\&]
	{\Cn(f)_{n,m}} \& \map_{(\infty,2)\Cat}([n] \otimes [m], \D) \\
	\prod_{k=0}^n\map_{(\infty,2)\Cat}(\{k\} \otimes [m], \C) \& \prod_{k=0}^n\map_{(\infty,2)\Cat}(\{k\} \otimes [m], \D).
	\arrow[from=1-1, to=1-2]
	\arrow[from=1-1, to=2-1]
	\arrow[from=1-2, to=2-2]
	\arrow[from=2-1, to=2-2]
\end{tikzcd}\]
Since the Gray tensor product is cocontinuous in both variables, $\Cn(f)$ is a double $\infty$-category, and the above adjunction derives 
to an adjunction
$$
|-| :  \DbliCat \rightleftarrows \Filt : \Cn(-).
$$
If $f$ is a filtration, then the double $\infty$-category $\Cn(f)$ is called the \textit{directed \v{C}ech nerve of $f$}. If $\P$ is a double $\infty$-category, then $|\P|$ is called the \textit{realization of $\P$}. The domain of $|\P|$ is always given by the vertical $\infty$-category $\P_0$. 

After composing the above realization-nerve adjunction with the adjunction of \ref{rem: trivial filtration}, we obtain another adjunction 
$$
\Gr : \DbliCat \rightleftarrows (\infty,2)\Cat : \Sq.
$$
The left adjoint carries a double $\infty$-category $\P$ to the codomain $|\P|_1$ of its realization. The right adjoint carries an $(\infty,2)$-category $\C$ to its \textit{double $\infty$-category of squares in $\C$}, and it is level-wise described by 
    $$\map_{\DbliCat}(\langle n,m\rangle, \Sq(\C))= \map_{(\infty,2)\Cat}([n] \otimes [m], \C).$$
\end{construction}

\begin{example}
    \label{exemple:realization of vertical and horizontal inclusion}
    Let $\C$ be an $(\infty,2)$-category. In \cite[Construction 3.57]{CompJaco}, canonical inclusions
    $\C_h \to \Sq(\C)$ and $\C_v \to \Sq(\C)$ were constructed. These inclusions are adjoint to equivalences $\Gr(\C_h) \simeq \C$ and $\Gr(\C_v) \simeq \C$ as argued in \cite[Proposition 3.58]{CompJaco}. One can use these observations to show that 
    $|\C_h| \simeq \tau_0\C \to \C$ and  $|\C_v| \simeq \tau_1\C \to \C$.
\end{example}

\begin{remark}
\label{remark:Gr and completion}
It is readily verified that the double $\infty$-category $\Sq(\C)$ is always complete, 
for every $(\infty,2)$-category $\C$. By adjunction, this implies that $\Gr$ factors through the completion functor $\DbliCat \to \CDbliCat$ that is left adjoint to the inclusion. In particular, the restriction $\Gr: \CDbliCat \to (\infty,2)\Cat$ preserves colimits.
\end{remark}

\begin{remark}
    The double $\infty$-category of squares was first introduced by Gaitsgory and Rozenblyum \cite{GR}. It has been studied by Abell\'an in \cite{abellan2023comparing}, and by the second author in \cite{CompJaco} as well. For strict 2-categories and double categories, the construction dates back to Ehresmann \cite{ehresmann}.
\end{remark}

\subsection{The universal property of the \v{C}ech nerve and squares}\label{subsection:uni prop} Using the results of \cite{Effectivity}, we may characterize the directed \v{C}ech nerve in terms of \textit{companions}. This notion makes an appearance in the work of Gaitsgory--Rozenblyum as well \cite[Subsection 10.5.1]{GR}, but under a different name. 

\begin{definition}\label{def:comp}
	Let $f : x \rightarrow y$ be a vertical arrow of a double $\infty$-category $\P$. A horizontal arrow 
	$F : x \rightarrow y$ of $\P$ is called the \textit{companion} of $f$  
	if there exist cells
	\[
		\eta = \begin{tikzcd}
			x\arrow[d, equal] \arrow[r, equal, ""name=f] & x\arrow[d, "f"] \\
			x \arrow[r, "F"'name=t] & y
			\arrow[from=f,to=t,Rightarrow, shorten <= 6pt, shorten >= 6pt]
		\end{tikzcd} 
		\quad 
		\text{and}
		\quad
		\epsilon = \begin{tikzcd}
			x \arrow[r, "F"name=f]\arrow[d, "f"' ] & y \arrow[d, equal] \\
			y \arrow[r, equal, ""'name=t] & y
			\arrow[from=f,to=t,Rightarrow, shorten <= 6pt, shorten >= 6pt]
		\end{tikzcd}
	\] 
	that satisfy the following two \textit{triangle identities}:
	\[
		\begin{tikzcd}
			x\arrow[d, equal] \arrow[r, equal, ""'name=h1] & x\arrow[d, "f"] \\
			x \arrow[r, ""name=h2]\arrow[d, "f"'] & y \arrow[d, equal] \\
			y \arrow[r, equal, ""'name=h3] & y
			\arrow[from=h1, to=h2, phantom, "\scriptstyle\eta"]
			\arrow[from=h2, to=h3, phantom, "\scriptstyle\epsilon"]
		\end{tikzcd}
		\simeq
		\begin{tikzcd}
			x\arrow[r,equal] \arrow[d, "f"'name=t1] & x \arrow[d, "f"name=f1] \\
			y \arrow[r, equal]  & y,
			\arrow[from=f1, to=t1, equal, shorten <= 14pt, shorten >= 14pt]
		\end{tikzcd}
		\quad 
		\begin{tikzcd}
			x \arrow[r, equal, ""name=h1]\arrow[d, equal] & x \arrow[d] \arrow[r, "F"name=h3] & y\arrow[d, equal] \\
			x \arrow[r, "F"'name=h2] & y \arrow[r, equal, ""'name=h4] & y
			\arrow[from=h1, to=h2, phantom, "\scriptstyle\eta"]
			\arrow[from=h3, to=h4, phantom, "\scriptstyle\epsilon"]
		\end{tikzcd}
		\simeq
		\begin{tikzcd}
			x\arrow[d,equal] \arrow[r, "F"name=f1] & y \arrow[d,equal] \\
			x \arrow[r, "F"'name=t1] & y.
			\arrow[from=f1, to=t1, equal, shorten <= 12pt, shorten >= 10pt]
		\end{tikzcd}
	\]
    The cells $\eta$ and $\epsilon$ are called the \textit{companionship unit} and \textit{counit} respectively.
\end{definition}

\begin{remark}
    It is shown by the second author in \cite{CompJaco} that companions are unique up to contractible choice if they exist, and that $\Sq([1])$ is the universal double $\infty$-category that contains a single companionship. Moreover, it is shown that the spaces of companionship units and counits for a vertical arrow with a companion are always contractible.
\end{remark}

\begin{remark}
    Examples of companions may be found in \cite[Section 4]{CompJaco}. As explained in \cite[Example 4.5]{CompJaco}, every vertical arrow in the squares construction $\Sq(\C)$ on an $(\infty,2)$-category $\C$ admits a companion, and each horizontal arrow is a companion. This in particular implies that \v{C}ech nerves of filtrations admit all companions; see also \cite[Lemma 2.6.7]{Effectivity}.
\end{remark}

\begin{remark}
    One may readily verify that if $f:x\to y$ and $g:y\to z$ are vertical arrows  in a double $\infty$-category $\P$ that admit companions $F$ and $G$ respectively, then the composite $GF$ is the companion of $gf$.
\end{remark}

We will use the main theorem of \cite{Effectivity} to show the following result:


\begin{theorem}\label{thm:uni prop of cech}
    Let $\P$ be a double $\infty$-category. Then restriction along the unit $\P \to \Cn|\P|$ gives a monomorphism 
    $$
    \map_{\DbliCat}(\Cn|\P|, \Q) \to \map_{\DbliCat}(\P, \Q)
    $$
    for every double $\infty$-category $\Q$. The image is given by the subspace of functors $\P \to \Q$ so that every vertical arrow of $\P$ is carried to a vertical arrow in $\Q$ that admits a companion.
\end{theorem}

The theorem specializes to the following result that appeared as a conjecture in \cite[Section 2.7]{JacoThesis} before, and generalizes \cite[Theorem 4.13]{CompJaco}:

\begin{corollary}\label{cor:uni prop squares vert}
    Let $\C$ be an $(\infty,2)$-category, and $\Q$ be a double $\infty$-category. Then the canonical map $\C_v \to \Sq(\C)$ induces a monomorphism 
     $$
    \map_{\DbliCat}(\Sq(\C), \Q) \to \map_{\DbliCat}(\C_v, \Q)
    $$
    whose image is given by the functors $\C_v \to \Q$ that carry every arrow in $\C$ to a vertical arrow of $\Q$ that admits a companion.
\end{corollary}
\begin{proof}
    On account of the example \ref{exemple:realization of vertical and horizontal inclusion}, $|\C_v|$ corresponds to the filtration $\tau_1\C\to \C$, and we then have $\Cn|\C_v|\sim \Sq(\C)$. The result then follows from  \ref{thm:uni prop of cech}.
\end{proof}

We will need an auxiliary definition.

\begin{construction}
    Suppose that $\P$ is a double $\infty$-category. Then for non-negative integers $n$ and $m$, we may consider subspaces
    $
    (\tau_\mathrm{vcomp}\P)_{n,m}, (\tau_\mathrm{hcomp})_{n,m} \subset \P_{n,m}
    $
    which are defined so that for every $\sigma : \langle n,m \rangle \to \P$, the following holds:
    \begin{enumerate}
        \item $\sigma$ belongs to $ (\tau_\mathrm{vcomp}\P)_{n,m}$ if and only if for every map $f : [1]_v \to \langle n,m \rangle$, the restriction $\sigma|f$ selects a vertical arrow that admits a companion,
        \item $\sigma$ belongs to $(\tau_\mathrm{hcomp}\P)_{n,m}$ if and only if for every map $f : [1]_h \to \langle n,m \rangle$, the restriction $\sigma|f$ selects a horizontal arrow that is a companion.
    \end{enumerate}
    These subspaces assemble to bisimplicial subspaces $\tau_\mathrm{vcomp}\P$ and $\tau_\mathrm{hcomp}\P$ of $\P$. With these definitions, note that for any bisimplicial space $X$, the maps
    $$
    \map_{\PSh(\Delta \times \Delta)}(X, \tau_\mathrm{vcomp}\P),~\map_{\PSh(\Delta \times \Delta)}(X, \tau_\mathrm{hcomp}\P) \to \map_{\PSh(\Delta \times \Delta)}(X, \P)
    $$
    are monomorphisms whose image correspond to the maps $\sigma : X \to \P$ that carry every vertical arrow (resp.\ horizontal arrow) of $X$ to a vertical arrow (resp.\ horizontal arrow) of $\P$ that admits (resp.\ is given by) a companion.
\end{construction}

\begin{lemma}
    Suppose that $\P$ is a double $\infty$-category. Then $\tau_\mathrm{vcomp}\P$ and $\tau_\mathrm{hcomp}\P$ are double $\infty$-categories.
\end{lemma}
\begin{proof}
    One may readily verify that the Segal conditions in both simplicial directions are met. It remains to check that both objects are local with respect to $[J]_v \to [0]_v$. Let us consider the commutative diagram
     \[
    \begin{tikzcd}[column sep = small, row sep = small]
        \map_{\PSh(\Delta^{\times 2})}([0]_v, \tau_\mathrm{vcomp}\P) \arrow[d, "\simeq"'] \arrow[r] & \map_{\DbliCat}([J]_v, \tau_\mathrm{vcomp}\P) \arrow[d]  \\
        \map_{\PSh(\Delta^{\times 2})}([0]_v, \P)  \arrow[r, "\simeq"] & \map_{\PSh(\Delta^{\times 2})}([J]_v, \P)   \\ 
        \map_{\DbliCat}([0]_v,\tau_\mathrm{hcomp}\P) \arrow[r]\arrow[u, "\simeq"] &  \map_{\DbliCat}([J]_v, \tau_\mathrm{hcomp}\P) \arrow[u, "\simeq"],
    \end{tikzcd}
    \]
    where we marked all the equivalences that follow either by construction or assumption. The top right vertical arrow is a monomorphism by construction, and must be essentially surjective as well. Thus all horizontal arrows are equivalences by 2-out-of-3.
\end{proof}

\begin{proof}[Proof of \ref{thm:uni prop of cech}]
    We equivalently have to show that $$\map_{\DbliCat}(\Cn|\P|, \tau_{\mathrm{vcomp}}\Q) \to \map_{\DbliCat}(\P, \tau_\mathrm{vcomp}\Q)$$
    is an equivalence. On account of \cite[Theorem 3.4.1]{Effectivity}, there exists an eso filtration $f$ so that $\tau_\mathrm{comp}\Q \simeq \Cn(f)$. The total composite in the factorization 
     $$\map_{\Filt}(|\P|, f) \to \map_{\DbliCat}(\Cn|\P|, \Cn(f)) \to \map_{\DbliCat}(\P, \Cn(f))$$
     is an equivalence by adjunction. The first map is an equivalence on account of \cite[Theorem 3.4.1]{Effectivity}, thus the desired result follows from 2-out-of-3.
\end{proof}

There is a version of \ref{cor:uni prop squares vert}, where the vertical inclusion is replaced by the horizontal inclusion into the squares construction. In this case, we need an additional completeness assumption (cf.\ \cite[Corollary 4.15]{CompJaco}).

\begin{theorem}\label{thm:uni prop squares hor}
    Let $\C$ be an $(\infty,2)$-category, and $\Q$ be a locally complete double $\infty$-category. Then the canonical map $\C_h \to \Sq(\C)$ induces a monomorphism 
     $$
    \map_{\DbliCat}(\Sq(\C), \Q) \to \map_{\DbliCat}(\C_h, \Q)
    $$
    whose image is given by the functors $\C_h \to \Q$ that carry every arrow in $\C$ to a horizontal arrow of $\Q$ that is a companion.
\end{theorem}

To prove this, we need the following input: 
\begin{lemma}\label{lem:comp core is complete}
    Suppose that $\P$ is a locally complete double $\infty$-category. Then the sub double $\infty$-category $\Q := \tau_\mathrm{vcomp}\P \times_\P \tau_\mathrm{hcomp}\P$ of $\P$ is a complete double $\infty$-category.
\end{lemma}
\begin{proof}
    For brevity, let us write $\Q := \tau_\mathrm{vcomp}\P \times_\P \tau_\mathrm{hcomp}\P$.
    One readily verifies that $\Q$ is again locally complete. It remains to check that it is local with respect to $[J]_h \to [0]_h$. To this end, we may consider the commutative diagram 
    \[
    \begin{tikzcd}[column sep = small, row sep = small]
        \map_{\DbliCat}([0,0], \Q) \arrow[d,equal] \arrow[r] & \map_{\DbliCat}([1]_v, \Q)' \arrow[r, hook] & \map_{\DbliCat}([1]_v, \Q)  \\
        \map_{\DbliCat}([0,0], \Q) \arrow[d,equal] \arrow[r] & \map_{\DbliCat}(\Sq([1]), \Q)' \arrow[r, hook] \arrow[u] \arrow[d] & \map_{\DbliCat}(\Sq([1]), \Q)\arrow[u] \arrow[d]  \\ 
        \map_{\DbliCat}([0,0], \Q) \arrow[r] &  \map_{\DbliCat}([1]_h, \Q)' \arrow[r, hook] & \map_{\DbliCat}([1]_h, \Q).
    \end{tikzcd}
    \] 
    Here, $\map_{\DbliCat}([1]_i, \Q)' \simeq \map_{\DbliCat}(J_i, \Q)$ denotes the subspace of equivalences for $i \in \{v,h\}$. We wrote $\map_{\DbliCat}(\Sq([1]), \Q)'$ for the subspace of maps $f : \Sq([1]) \to \Q$ so that the restrictions $f|[1]_v$ and $f|[1]_h$ select equivalences. But one readily verifies that $f|[1]_v$ is an equivalence if and only if $f|[1]_h$ is an equivalence. So the top and bottom right squares in the above diagram are pullback squares. The legs of the right span in the diagram are equivalences on account of \cite[Theorem 4.13]{CompJaco}. Here we used that $\Q$ is locally complete. From the above, it now follows that the legs of the middle span are equivalences as well. We conclude that all the left horizontal maps in the diagram are equivalences by 2-out-of-3.
\end{proof}

\begin{proof}[Proof of \ref{thm:uni prop squares hor}]
    Since $\Sq(\C)$ has all companions, we equivalently have to show that 
    $$
    \map_{\DbliCat}(\Sq(\C), \Q') \to \map_{\DbliCat}(\C_h, \Q')
    $$
    is a monomorphism with the prescribed image where $\Q' := \tau_\mathrm{hcomp}\Q \times_\Q \tau_\mathrm{vcomp}\Q$. The horizontal inclusion $\C_h \to \Sq(\C)$ is equivalent to the inclusion 
    $$
       (\C^\op)_v^{\tp, \hop,\vop} \to \Sq(\C^\op)^{\tp, \hop, \vop},
    $$
    as can be shown from \cite[Construction 3.57]{CompJaco}.
    On account of \ref{lem:comp core is complete}, $\Q'$ is a complete double $\infty$-ca\-te\-gory. Hence, we can apply dualities to identify the above map with 
    $$
    \map_{\DbliCat}(\Sq(\C^\op), (\Q')^{\tp, \hop, \vop}) \to \map_{\DbliCat}((\C^\op)_v, (\Q')^{\tp, \hop, \vop}).
    $$
    Thus the desired conclusion follows from \ref{cor:uni prop squares vert}.
\end{proof}



\section{The Gray tensor product via squares}\label{section:comparison}

As announced in the introduction, we will now settle the following description of the Gray tensor product that was conjectured by Gaitsgory--Rozenblyum in \cite[Subsection 10.4.5]{GR}:

\begin{theorem}\label{theo:comparaison of gray tensor}
    Let $\C$ and $\D$ be $(\infty,2)$-categories. Then there exists a unique natural equivalence 
    $$
    \Gr(\C_h \times \D_v) \simeq \C \otimes \D.
    $$
\end{theorem}

We note that the unicity will be automatic on account of \ref{prop:auto of gray}.
To prove the above result, we will employ several density arguments to reduce to easier shapes. As an easy case, we have the following intermediate result:

\begin{lemma}
\label{lemma:comparaions step 0.5}
The desired natural equivalence of \ref{theo:comparaison of gray tensor} exists if $\C$ and $\D$ are $\infty$-categories.
\end{lemma}
\begin{proof}
Since $\Delta$ is dense in $\infty\Cat$, and the bifunctors $\otimes$ and $\Gr((-)_h \times (-)_v)$ preserve colimits in each variable, we may reduce to the case that $\C = [n]$ and $\D = [m]$ for some non-negative integers $n,m$. In this case, it directly follows from \ref{cons: realization-nerve adjunction}.
\end{proof}

Before moving to the general case, the next step will be to prove \ref{theo:comparaison of gray tensor} in case that either $\C$ or $\D$ is an $\infty$-category. We recall the following facts:

\begin{lemma}
\label{lemma:easy diagram chasing}
Suppose that we are given a commutative diagram
% https://q.uiver.app/#q=WzAsNixbMCwwLCJhIl0sWzAsMSwiYiJdLFsxLDAsImMiXSxbMSwxLCJkIl0sWzIsMCwiZSJdLFsyLDEsImYiXSxbMCwyLCJ1Il0sWzIsNF0sWzEsMywidiIsMl0sWzMsNV0sWzQsNV0sWzAsMV0sWzIsM11d
\[\begin{tikzcd}
	a & c & x \\
	b & d & y
	\arrow["u", from=1-1, to=1-2]
	\arrow[from=1-1, to=2-1]
	\arrow[from=1-2, to=1-3]
	\arrow[from=1-2, to=2-2]
	\arrow[from=1-3, to=2-3]
	\arrow["v"', from=2-1, to=2-2]
	\arrow[from=2-2, to=2-3]
\end{tikzcd}\]
in an $\infty$-category with pushouts.
If the outer square is a pushout square, and if both $u$ and $v$ are epimorphisms, then the right square is a pushout square as well.
\end{lemma}

\begin{proof}
This is an easy diagram chase using the pasting law for pushout squares.
\end{proof}

\begin{lemma}
\label{lemma:important epis}
Let $a$ and $b$ be globular sums. Then the  canonical maps $a \otimes b \to a \times b$ and $a \times b \to b$ are both epimorphisms in $(\infty,2)\Cat$.
\end{lemma}
\begin{proof}
It follows from \cite[Lemma 1.6.12]{Effectivity} that the map $a \otimes b \to a \times b$ is obtained by localizing all the cells of the shape $x\otimes y$ where $x,y$ are cells of non-negative dimension of respectively $a$ and $b$. The desired result then follows from \cite[Proposition 2.2.1.50]{loubaton2024categorical}. 


For the second map, it suffices to show that $a\to [0]$ is an epimorphism as the cartesian product preserves colimits. This map witnesses a groupoidification, so it follows again from \cite[Proposition 2.2.1.50]{loubaton2024categorical}. 
\end{proof}

\begin{construction}\label{cons:funny equation}
We will now construct natural pushout squares
\[
    \begin{tikzcd}
	\tau_0[n]\times ([m]\times [k]) & {[n]\otimes ([m]\times [k])} \\
	\tau_0[n] \times [k] & {[n;m]\otimes [k]},
	\arrow[""{name=0, anchor=center, inner sep=0}, from=1-1, to=1-2]
	\arrow[from=1-1, to=2-1]
	\arrow[from=1-2, to=2-2]
	\arrow[from=2-1, to=2-2]
\end{tikzcd} \quad 
\begin{tikzcd}
 {[k]}\times [m]^\op \times \tau_0[n] & {([k]\times [m]^\op)\otimes[n]} \\
 {[k]} \times \tau_0[n]& {[k]\otimes[n;m]}.
	\arrow[""{name=0, anchor=center, inner sep=0}, from=1-1, to=1-2]
	\arrow[from=1-1, to=2-1]
	\arrow[from=1-2, to=2-2]
	\arrow[from=2-1, to=2-2]
\end{tikzcd}
\]
in $(\infty,2)\Cat$. We will just construct the left one, the construction of the right one is formally dual.

The first step will be to construct the collapse map $[n] \otimes ([m]\times [k]) \to [n;m] \otimes [k]$. Let $\psi : [n]\otimes[m] \to [n;m]$ be the map that appears in the square of \ref{lemma:globular sum as quotient of Gray}. Then we demonstrate that the dashed factorization of $(\infty,2)$-categories displayed in the left-hand side triangle exists:
\[
\begin{tikzcd}
        {[n]} \otimes [m] \otimes [k] \arrow[r, "{\psi \otimes [k]}"]\arrow[d] & {[n;m]} \otimes [k] \\ 
        {[n]} \otimes ([m] \times [k]) \arrow[ur, dashed]
\end{tikzcd} \quad
\Leftrightarrow \quad 
\begin{tikzcd}
        {[n]} \otimes_G [m] \otimes_G [k] \arrow[r, "{\psi \otimes_G [k]}"]\arrow[d] & {[n;m]} \otimes_G [k]. \\ 
        {[n]} \otimes_G ([m] \times [k]) \arrow[ur, dashed]
\end{tikzcd}
\]
This factorization will be unique since the left vertical map is an epimorphism by \ref{lemma:important epis}.
By \ref{theo:Gray tensor of globular sums}, $[n;m] \otimes [k]$ is 2-gaunt. So, by the adjunction $\Str\dashv N$ of \ref{def:discrete} and the monoidality of $\Str$, a triangle on the left-hand side in $(\infty,2)\Cat$ corresponds precisely to a triangle on the right-hand side in $2\Gaunt$. Let $u$ be a $0$-cell in $[n]$ and $v$ a $2$-cell in $[m]\otimes_G[k]$. Tracing through the construction of $\psi$, one 
sees that $u\otimes v$ is carried to an identity by $\psi \otimes_G [k]$. So it follows from \ref{rem:when factor throug tau1} that the desired dashed factorization exists.

Similar reasoning shows that the produced factorization fits in a canonical commutative diagram 
\[ 
\begin{tikzcd}
	{\tau_0[n] \times [m]\otimes [k]}\arrow[d]\arrow[r] & {[n]\otimes[m]\otimes[k]} \arrow[d] \\
	{\tau_0[n]\times [m]\times [k]}\arrow[d]\arrow[r] & {[n]\otimes([m]\times[k])} \arrow[d] \\
	{\tau_0[n]\otimes [k]} \arrow[r] & {[n;m]\otimes [k]},
\end{tikzcd}
\]
and the bottom square is uniquely determined since the top left and top right maps are epimorphisms. 
\end{construction}

\begin{lemma}
\label{lemma:funny equation}
The squares constructed in \ref{cons:funny equation} are pushout squares.
\end{lemma}
\begin{proof}
    This follows directly from applying \ref{lemma:globular sum as quotient of Gray} and \ref{lemma:easy diagram chasing}. 
\end{proof}

We now have the following intermediate result:

\begin{lemma}
\label{lemma:comparaions step 1}
The desired natural equivalence of \ref{theo:comparaison of gray tensor} exists if $\C$ is an $\infty$-category and $\D$ is an $(\infty,2)$-category.
\end{lemma}
\begin{proof}
By density, we may reduce to the case that $\C = [k] \in \Delta$ and $\D = [n;m] \in [\Delta;\Delta]$. It follows from the construction of the vertical and horizontal inclusion
that $\C_h\times \D_v$ is naturally the colimit of the span
\[
\begin{tikzcd}
    {[k]_h} \times \tau_0[n]_v & \arrow[l]  ([k] \times [m]^\op)_h \times \tau_0[n]_v \arrow[r] & ([k] \times [m]^\op)_h \times [n]_v.
\end{tikzcd}
\]
On account of \ref{lemma:comparaions step 0.5}, the functor $\Gr$ carries this to the colimit of the span
\[
\begin{tikzcd}
     {[k]} \times \tau_0[n] & \arrow[l]  [k] \times [m]^\op \times \tau_0[n] \arrow[r] & ([k] \times [m]^\op)\otimes [n],
\end{tikzcd}
\]
and this is computed by $[k] \otimes [n;m]$ on account of \ref{lemma:funny equation}.
\end{proof}

To prove \ref{theo:comparaison of gray tensor}, we need some additional combinatorial input.

\begin{lemma}
\label{lemma:crush product}
Let $n,m,k$ be non negative integers.
All squares in the canonical commutative diagram
\[\begin{tikzcd}
	{\tau_1[n;m]\otimes [k]} & {\tau_1[n;m]\times [k]} & {\tau_1[n;m]} \\
	{[n;m] \otimes [k]} & {[n;m] \times [k]} & {[n;m]}
	\arrow[from=1-1, to=1-2]
	\arrow[from=1-1, to=2-1]
	\arrow[from=1-2, to=1-3]
	\arrow[from=1-2, to=2-2]
	\arrow[from=1-3, to=2-3]
	\arrow[from=2-1, to=2-2]
	\arrow[from=2-2, to=2-3]
\end{tikzcd}\]
are pushout squares in $(\infty,2)\Cat$.
\end{lemma}
\begin{proof}
Recall that \ref{lemma:important epis} implies that the horizontal maps in the left-hand  square are epimorphisms, so that it suffices that the outer square is a pushout square by \ref{lemma:easy diagram chasing}.


The inclusion $\tau_1[n;m] \to [n;m]$ is given by the canonical map $[n] \times \tau_0[m] \to [n;m]$.  Using \ref{cons:funny equation}, we may construct a canonical commutative cube
\[
	\begin{tikzcd}[column sep = 0pt, row sep = small]
			[n] \otimes (\tau_0[m] \times [k]) \arrow[dr, "\simeq"']\arrow[rr]\arrow[dd] && {[n]} \times \tau_0[m] \arrow[dr,equal]\arrow[dd] \\
			& |[alias=f]|([n] \times \tau_0[m]) \otimes [k] \arrow[rr, crossing over] && {[n]} \times \tau_0[m] \arrow[dd]\\ 
			{[n]} \otimes ([m] \times [k]) \arrow[dr]\arrow[rr] && {[n]}\otimes [m]\arrow[dr] \\
			& |[alias=t]| {[n;m]} \otimes [k] \arrow[rr] &&  {[n;m]},
			\arrow[from=f,to=t, crossing over]
	\end{tikzcd}
\]
so that the front face is precisely the square we are interested in. The bottom face is a pushout on account of \ref{lemma:funny equation}. Thus it suffices to check that the back face is a pushout square. But this follows from the fact that the square 
\[
    \begin{tikzcd}
        \tau_0[m] \times [k] \arrow[r]\arrow[d] &  \tau_0[m] \arrow[d] \\
        {[m]} \times [k] \arrow[r] & {[m]},
    \end{tikzcd}
\]
is a pushout in $\infty\Cat$, as can be directly verified by reducing to $m=k=1$. 
\end{proof}

\begin{lemma}

\label{lemma:comparaions step 3}
Let $n,m,k,l$ be non-negative integers.
Then the canonical commutative square
\[\begin{tikzcd}
	{\tau_0[n]_h \times [m]_v \times\tau_1[k;l]_v} & {\langle n,m \rangle \times [k;l]_v} \\
	{\tau_0[n]_h\times\tau_1[k;l]_v} & {[n;m]_h\times[k;l]_v}
	\arrow[""{name=0, anchor=center, inner sep=0}, from=1-1, to=1-2]
	\arrow[""{name=0p, anchor=center, inner sep=0}, phantom, from=1-1, to=1-2, start anchor=center, end anchor=center]
	\arrow[from=1-1, to=2-1]
	\arrow[from=1-2, to=2-2]
	\arrow[from=2-1, to=2-2]
\end{tikzcd}\]
is a pushout in $\CDbliCat$.
\end{lemma}
\begin{proof}
We may expand the commutative square to the commutative diagram
\[\begin{tikzcd}
	{\tau_0[n]_h\times [m]_v \times\tau_1[k;l]_v} & {\tau_0[n]_h \times [m]_v \times[k;l]_v} & {\langle n,m \rangle \times [k;l]_v} \\
	{\tau_0[n]_h\times\tau_1[k;l]_v} & {\tau_0[n]_h\times[k;l]_v} & {[n;m]_h\times[k;l]_v,}
	\arrow[from=1-1, to=1-2]
	\arrow[from=1-1, to=2-1]
	\arrow[from=1-2, to=1-3]
	\arrow[from=1-2, to=2-2]
	\arrow[from=1-3, to=2-3]
	\arrow[from=2-1, to=2-2]
	\arrow[from=2-2, to=2-3]
\end{tikzcd}\]
of which the outer square is of our interest. 
Note that the right square is a pushout square. Thus we must demonstrate that the left square is a pushout square. This follows directly from \ref{lemma:crush product} and the fact that the vertical inclusion $(-)_v : (\infty,2)\Cat \to \CDbliCat$ preserves colimits.
\end{proof}


We have the following extension of \ref{lemma:funny equation}:

\begin{lemma}
\label{lemma:comparaions step 2}
Suppose that $\P$ is a double $\infty$-category, and $\C$ an $\infty$-category.
Then there exists a natural equivalence
$$\textstyle   \P_0 \bigcup_{\P_0\times \C} \Gr(\P \times \C_v) \simeq \P_0\bigcup_{\C^{\op}\otimes \P_0}\C^{\op}\otimes \Gr(\P)$$
of $(\infty,2)$-categories.
\end{lemma}
\begin{proof}
    Both sides are indexed by functors $\DblCat_\infty \times \Cat_\infty \to \DblCat_\infty$ that preserve colimits in each variable. Hence, by density, we may reduce to the case that $\P = \langle n,m \rangle$ and $\C = [k]$. In this case, the inclusion $\P_0 \to \Gr(\P)$ of the vertical $\infty$-category is given by the obvious map $\tau_0[n] \times [m] \to [n]\otimes[m]$. Since $\Gr$ preserves colimits, the left-hand side is computed by 
    $$\textstyle \tau_0[n]\times [m] \bigcup_{\tau_0[n]\times ([m]\times[k])}[n]\otimes([m]\times [k]).$$
    This pushout is computed by $[n;k]\otimes[m]$ by \ref{lemma:funny equation}.
    The right-hand part of the equation corresponds to the pushout 
    $$\textstyle \tau_0[n]\times [m] \bigcup_{[k]^{\op}\otimes \tau_0[n]\otimes[m]}[k]^{\op}\otimes [n]\otimes[m].$$
    As the Gray tensor product commutes with colimits in both variables, \ref{lemma:globular sum as quotient of Gray} implies that this pushout is also  naturally equivalent to $[n;k]\otimes[m]$.
\end{proof}

We are now ready to complete the proof of \ref{theo:comparaison of gray tensor}.

\begin{proof}[Proof of \ref{theo:comparaison of gray tensor}]
The unicity follows from \ref{prop:auto of gray}.
By density, we may reduce to the case where $\C$ is of shape $[n;m] \in [\Delta;\Delta]$ and $\D$ of shape $[k;l]\in [\Delta;\Delta]$. We set $\P:= [n]_h\times [k;l]_v$. Note that the inclusion $(\P_0)_v \to \P$ is equivalent to the inclusion $\tau_0[n]_h \times \tau_1 [k;l]_v \to [n]_h \times [k;l]_v$.
We may use \ref{lemma:comparaions step 3} and \ref{remark:Gr and completion} to write  $\Gr(\C_h \times \D_v)$ as the colimit of the natural span
\[\begin{tikzcd}
	{\P_0} & {\P_0 \times [m]} & {\Gr(\P \times [m]_v)}.
	\arrow[from=1-2, to=1-1]
	\arrow[from=1-2, to=1-3]
\end{tikzcd}\]

It follows from \ref{lemma:comparaions step 1} and \ref{lemma:comparaions step 2} that there is a natural equivalence between $\Gr(\C_h \times \D_v)$ and the colimit of the span
\[\begin{tikzcd}
	\tau_0[n] \times \tau_{1}[k;l] & {[m]}^{\op}\otimes \tau_0[n] \otimes \tau_1[k;l] & {[m]^{\op}\otimes[n]\otimes [k;l]}.
	\arrow[from=1-2, to=1-1]
	\arrow[from=1-2, to=1-3]
\end{tikzcd}\]
By \ref{lemma:crush product}, this colimit is equivalent to the colimit of the span
\[\begin{tikzcd}
	{\tau_0[n]\times [k;l]} & {[m]^{\op}\otimes\tau_0[n]\otimes [k;l]} & {[m]^{\op}\otimes[n]\otimes[k;l]}.
	\arrow[from=1-1, to=1-2]
	\arrow[from=1-2, to=1-3]
\end{tikzcd}\]
We may now apply \ref{lemma:globular sum as quotient of Gray} to conclude that $\Gr(\C_h \times \D_v)$ is computed by $\C \otimes \D = [n;m]\otimes [k;l]$. Since all steps in the comparison depended naturally on $\C$ and $\D$, the naturality of the comparison is also witnessed.
\end{proof}




