$$  + \frac{1}{2}  e^{-rt_{i+1}} ( \nu^2 -\sigma^2  )X_{t_i}^2\frac{\partial^2 C_{\nu}}{\partial^2 x}(X_{t_i},t_i) \Delta t +O(\Delta t^{\frac{3}{2}})$$
 and finally, 
\begin{equation} \label{eq:approx}
 Z_T=    \frac{1}{2}  \sum\limits_{i=1}^n e^{-rt_{i+1}} \frac{\partial^2 C_{\nu}}{\partial^2 x} (X_{t_i},t_i) X_{t_i}^2  \left[  \nu^2 \Delta t -\left(\frac{X_{t_{i+1}} - X_{t_i}}{X_{t_i}}\right)^2  \right]  - C_0^{\nu} +O(\sqrt{\Delta t})
 \end{equation}
 which is equivalent to Leland's Formula \citep{Leland}.

\section{Appendix}
\label{appendix:proof2}

We consider the log normal model:
\begin{align}
 dX_t = \mu X_tdt + \sigma X_t dW_t  \mbox{ with } \sigma>0,
\end{align}

where $(W_t)_{t\geq 0}$ is a Brownian motion in the probability space $(\Omega, P)$.\\
We provide here a short proof of the result by \citet{Soner} which states that for a fixed implied volatility $\nu$ (not dependent on $\Delta t$), if one uses the Black \& Scholes deltas,  the transactions costs incurred tend to infinity when $\Delta t$ tends to zero. We demonstrate the limit almost surely. Without loss of generality, we consider an option of maturity $T=1$. 
We note 

\begin{equation}f(s,b)= exp\left(\sigma b +(\mu - \frac{\sigma^2}{2})s\right),\end{equation}
and we have, 
$$X_s = f(s,W_s).$$

For $x \in \R$ we note $[x]$ the integer part of $x$.

\begin{lemma} $\forall T >0$
\begin{equation} \label{eq1:lemma}
\sum\limits_{i=0}^{[nT]-1} \left|W_{\frac{i+1}{n}}-W_{\frac{i}{n}}\right|^2 \xrightarrow[n \to \infty]{} T \quad  \mbox{ almost surely.} \end{equation}
\begin{equation} \label{eq2:lemma} \sum\limits_{i=0}^{[nT]-1} \left|W_{\frac{i+1}{n}}-W_{\frac{i}{n}}\right| \xrightarrow[n \to \infty]{} + \infty \mbox{ almost surely.} \end{equation} 
\label{lemma}
\end{lemma}

\begin{proof}


The maximum lengths of the intervals in step $n$ that form the partition $0<\frac{1}{n}< \cdots < \frac{[nT]}{n}$  are $\lambda_n =\frac{1}{n}$ and satisfy the condition
$\lambda_n =o (1/log(n))$, which according to \cite[Thm. 4.5 page 89]{Dudley} 
proves the almost sure convergence in Equation (\ref{eq1:lemma}). 


\vspace{0.5 cm}
For the second  point, almost surely:
\begin{equation} 
\label{qv}
\sum\limits_{i=0}^{[nT]-1} \left|W_{\frac{i+1}{n}}-W_{\frac{i}{n}}\right|^2 \leq
\sup\limits_{|s-t|<\frac{1}{n}, s,t \in [0,T]} \left|W_s-W_t\right|\cdot
\sum\limits_{i=0}^{[nT]-1} \left|W_{\frac{i+1}{n}}-W_{\frac{i}{n}}\right|.
\end{equation}

Now, for any $\omega \in \Omega$, $W_s(\omega)$ is continuous in $s$ in $[0,T]$, which is compact, therefore it is also absolutely continuous and,
$$\sup\limits_{|s-t|<\frac{1}{n}, s,t \in [0,T]} \left|W_s(\omega)-W_t(\omega)\right| 
\xrightarrow[n \to \infty]{}  0 \mbox{ almost surely,} $$
and as 
$$\sum\limits_{i=0}^{[nT]-1} \left|W_{\frac{i+1}{n}}-W_{\frac{i}{n}}\right|^2 
\xrightarrow[n \to \infty]{}  T \mbox{ almost surely,} $$

then necessarily, 
$\sum\limits_{i=0}^{[nT]-1} \left|W_{\frac{i+1}{n}}-W_{\frac{i}{n}}\right|$ tends to $+ \infty$, for the inequality of  Equation (\ref{qv}) to be satisfied. Therefore, Equation (\ref{eq2:lemma}) is satisfied.


\end{proof}



The transaction costs are $\alpha V_n$ with $\alpha>0$ and,
$$V_n = \sum\limits_{i=0}^{n-1}  \left| \frac{\partial C}{\partial x}\left(X_{\frac{i+1}{n}} , \frac{i+1}{n}\right)- \frac{\partial C}{\partial x}\left(X_{\frac{i}{n}}, \frac{i}{n}\right)\right|X_{\frac{i+1}{n}}.$$ According to Taylor's formula with integral residue:

$$ \frac{\partial C}{\partial x}(X_{\frac{i+1}{n}}, \frac{i+1}{n})- \frac{\partial C}{\partial x}(X_{\frac{i}{n}}, \frac{i}{n})$$
$$ = \frac{\partial^2 C}{\partial^2 x}(X_{\frac{i}{n}}, \frac{i}{n})\left(X_{\frac{i+1}{n}}-X_{\frac{i}{n}}\right)
+ \frac{\partial^2 C}{\partial x \partial t}(X_{\frac{i}{n}}, \frac{i}{n})\frac{1}{n}$$
$$+ \int_0^1 (1-s) \Delta_{i,n}^{T} H\left(\frac{\partial C}{\partial x}\right) 
\left(X_{\frac{i}{n}}+ s(X_{\frac{i+1}{n}}-X_{\frac{i}{n}}), \frac{i+s}{n} \right) \Delta_{i,n}ds.$$
where  $ \Delta_{i,n}^T = (X_{\frac{i+1}{n}}-X_{\frac{i}{n}} , \frac{1}{n})  $ and $H$ is the Jacobian operator.


\vspace{0.2 cm}
Let $D_{\eta}= \{(x,s) , |x-X_0|<\eta \mbox{ and } |s|<\eta \}$
and let $\epsilon >0$  be such that $\forall (x,s) \in D_{\epsilon}$ we have:
\[
\left\{
\begin{array}{ll}
\frac{\partial^2 C}{\partial^2 x}(x,s) \geq  
\frac{1}{2} \frac{\partial^2 C}{\partial^2 x}(X_0,0)\\ \\
|\frac{\partial^2 C}{\partial x \partial t}(x,s)| \leq 1+ |\frac{\partial^2 C}{\partial x \partial t}(X_0,0)|\\ \\
\|H(\frac{\partial C}{\partial x})(x,s)\| \leq 1+ \|H(\frac{\partial C}{\partial x})(X_0,0) \|, 
\end{array}
\right.
\]
where $\| \cdot\|$ is the spectral norm for which $|z^{T}Mz| \leq \| M\| \|z\|^2$ (here $z^T$ is the transpose of $z$); note that $\epsilon$ exists because of the continuity of the functions considered. Note also that $D_{\epsilon }$ is convex and therefore,
$$(X_{i/n},i/n) \mbox{ and } (X_{(i+1)/n},(i+1)/n)  \in D_{\epsilon}$$
$$ \Longrightarrow \forall s \in [0,1], (X_{i/n}+s ( X_{(i+1)/n}- X_{i/n}   ), (i+s)/n ) \in D_{\epsilon}.$$

\vspace{0.2 cm}
Now, let 
$\tau_1= \inf \{s\in \R^+ , (X_s,s) \notin D_{\epsilon} \mbox{ or } X_s \notin [\frac{1}{2} |X_0| ,2|X_0| ]\}$ 
then, 
$$V_n \geq \sum\limits_{i=0}^{n-1} 1_{\frac{i+1}{n} 
\leq \tau_1} \left| \frac{\partial C}{\partial x}(X_{\frac{i+1}{n}, \frac{i+1}{n}}) - \frac{\partial C}{\partial x}(X_{\frac{i}{n}, \frac{i}{n}})\right| X_{\frac{i+1}{n}}$$

$$ \geq A_n + B_n +C_n,$$

where,
\begin{align} \label{eq:An}
& A_n = \sum\limits_{i=0}^{n-1} 1_{\frac{i+1}{n}\leq \tau_1} \frac{X_0}{4} \cdot \frac{\partial^2 C}{\partial^2 x} (X_0, 0) \cdot \left| X_{\frac{i+1}{n}} - X_{\frac{i}{n}} \right|, \\
& B_n = - \sum\limits_{i=0}^{n-1} 1_{\frac{i+1}{n}\leq \tau_1} 
 \frac{2X_0}{n} \cdot \left(1+ \left| \frac{\partial^2 C}{\partial x \partial t}(X_0, 0) \right| \right),  
\\ & C_n = - \sum\limits_{i=0}^{n-1} 1_{\frac{i+1}{n}\leq \tau_1} 
 2X_0 \cdot \left(1+\left\| H\left(\frac{\partial C}{\partial x}\right)(X_0,0) \right\| \right)
\left( \int\limits_0^1 (1-s) ds \right)
\left(\frac{1}{n^2} +  \left| X_{\frac{i+1}{n}} - X_{\frac{i}{n}} \right|^2\right).
\end{align}

For $B_n$ we have:
\begin{equation} B_n \geq -2 X_0 \cdot \left(1+\left|\frac{\partial^2 C}{\partial x \partial t}(X_0,0)\right|\right).
\end{equation}

For $C_n$ we have: 
$$- \sum\limits_{i=0}^{n-1} 1_{\frac{i+1}{n}\leq \tau_1} \cdot \frac{1}{n^2} \geq - \frac{1}{n},$$
and


$$
- \sum\limits_{i=0}^{n-1} 1_{\frac{i+1}{n}\leq \tau_1} 
\left|X_{\frac{i+1}{n}}-X_{\frac{i}{n}}\right|^2  
\geq  - \sum\limits_{i=0}^{n-1}  \left|X_{\frac{i+1}{n}}-X_{\frac{i}{n}}\right|^2. 
$$
Let, 
\begin{equation}
\label{eq:sum}
S_n=  - \sum\limits_{i=0}^{n-1} 
\left|X_{\frac{i+1}{n}}-X_{\frac{i}{n}}\right|^2. 
\end{equation}

According to the mean value theorem,
$\exists$ $\xi_{i,n} \in \left[ \left( \frac{i}{n} , W_{\frac{i}{n}}\right),\left( \frac{i+1}{n}, W_{\frac{i+1}{n}}\right)\right]:$
\begin{equation} \label{MVT}
X_{\frac{i+1}{n}}-X_{\frac{i}{n}} = \nabla f(\xi_{i,n}). 
\begin{pmatrix} 
\frac{1}{n} \\ 
W_{\frac{i+1}{n}} -W_{\frac{i}{n} } 
\end{pmatrix},
\end{equation}
where $\left[ \left( \frac{i}{n} , W_{\frac{i}{n}}\right),\left( \frac{i+1}{n}, W_{\frac{i+1}{n}}\right)\right]$ is the $\R^2$ the segment between the two points 
$\left( \frac{i}{n} , W_{\frac{i}{n}}\right) $ and $\left( \frac{i+1}{n} , W_{\frac{i+1}{n}}\right) $.

\vspace{0.5cm}
Let $\omega \in \Omega$ and  
$\mathcal{B}(w)= [0,1] \times [\inf\limits_{s \in [0,1]}  W_s(w) , \sup\limits_{s \in [0,1]}W_s(w)] $ 
and 
\begin{equation} M(w) = \sup\limits_{\xi \in \mathcal{B}(w) } \| \nabla f(\xi) \|.
\end{equation}
The $\sup$ is reached as $\mathcal{B}(w)$  is compact and $\nabla f$ is continuous. Therefore, 
$$M(\omega) < +\infty.$$ Using Cauchy Schwartz, 
$$
\forall n \in \mathbb{N},\ \forall i \in \llbracket 0,\ n - 1 \rrbracket, 
|    X_{\frac{i+1}{n}} -X_{\frac{i}{n}}    |^2 \leq M^2 
\left( \frac{1}{n^2} + |W_{\frac{i+1}{n}} -W_{\frac{i}{n}}    |^2   \right) 
$$

So,
$$S_n \geq  - \frac{M^2}{n } - M^2 \sum\limits_{i=0}^{n-1} 
\left|W_{\frac{i+1}{n}}-W_{\frac{i}{n}}\right|^2,$$

and therefore according to Lemma \ref{lemma}.
$$
\lim\inf\limits_{n \longrightarrow  +\infty} S_n \geq -M^2 T \mbox{ almost surely},
$$
and as a consequence, 
\begin{equation}
\lim\inf\limits_{n \longrightarrow  +\infty} C_n \geq -X_0 \left(1+\left\| H\left(\frac{\partial C}{\partial x}\right)(X_0,0) \right\| \right)M^2 T \mbox{ almost surely}.
\end{equation}

\vspace{0.5cm}

For $A_n$ defined in Equation (\ref{eq:An}), 
let $\tilde{D}_{\eta}= \{(s,w) , |w|<\eta \mbox{ and } |s|<\eta \}$ and 
let $\tilde{\epsilon}>0$ be such that $\forall \xi \in  \tilde{D}_{\tilde{\epsilon}}$ 
\begin{equation} \label{ineq2}
\left\{
\begin{array}{ll}
\frac{\partial f}{\partial b}(\xi) \geq  
\frac{1}{2}\frac{\partial f}{\partial b}(0) = \frac{\sigma}{2}\\ \\
|\frac{\partial f}{\partial s}(\xi)| \leq 1+ |\frac{\partial f}{\partial s}(0)|. 
\end{array}
\right.
\end{equation}

Now, let 
$\tau= \inf \{s\in \R^+ , (s, W_s) \notin \tilde{D}_{\tilde{\epsilon}}\}$, let $\tau_2 = \inf(\tau_1,\tau)$ and let 
$$\Theta_m = \left\{ \omega \in \Omega, \tau_2 \geq  \frac{1}{m} \right\}.$$


We have $\bigcup\limits_{m \in \mathbb{N}} \Theta_m = \Omega $ almost surely by the continuity of $X_s$ and $W_s$.
Let, 
\begin{equation}V_n= \sum\limits_{i=0}^{n-1} 1_{\frac{i+1}{n}\leq \tau_1} \left|X_{\frac{i+1}{n}}-X_{\frac{i}{n}}\right|,
\end{equation}
then, $ \forall m\in \mathbb{N}, \forall n\in \llbracket m, +\infty \rrbracket$,
$$ V_n 
\geq   1_{\tau_2\geq \frac{1}{m}} \sum\limits_{i=0}^{n-1} 1_{\frac{i+1}{n}\leq \tau_1}  \left|X_{\frac{i+1}{n}}-X_{\frac{i}{n}}\right|
 \geq  \sum\limits_{i=0}^{n-1} 
 1_{\frac{i+1}{n}\leq \frac{1}{m}} 1_{\tau_2\geq \frac{1}{m}} \left|X_{\frac{i+1}{n}}-X_{\frac{i}{n}}\right|.
$$

Now, according to Equation (\ref{MVT}) and Equation (\ref{ineq2}), 
$$  1_{\frac{i+1}{n}\leq \frac{1}{m}\leq \tau_2}\left|X_{\frac{i+1}{n}}-X_{\frac{i}{n}}\right|  \geq 
 1_{\frac{i+1}{n}\leq \frac{1}{m} \leq \tau_2} 
\left(  \frac{\sigma}{2} \left|W_{\frac{i+1}{n}}-W_{\frac{i}{n}}\right|       
- \left(1+ |\frac{\partial f}{\partial s}(0)| \right) \frac{1}{n} \right), $$

So,
\begin{equation} 
V_n \geq 
- \left(1+ |\frac{\partial f}{\partial s}(0)| \right) +
1_{\tau_2\geq \frac{1}{m}} 
\frac{\sigma}{2}
\sum\limits_{i=0}^{n-1} 1_{\frac{i+1}{n}\leq \frac{1}{m}} \left|W_{\frac{i+1}{n}}-W_{\frac{i}{n}}\right|. 
\end{equation}


Now,
\begin{equation}
\sum\limits_{i=0}^{n-1} 1_{\frac{i+1}{n}\leq \frac{1}{m}} \left|W_{\frac{i+1}{n}}-W_{\frac{i}{n}}\right|   
= \sum\limits_{i=0}^{[\frac{n}{m}]-1}  \left|W_{\frac{i+1}{n}}-W_{\frac{i}{n}}\right|, 
\end{equation}
and according to Lemma (\ref{lemma}): 
$$\forall m \in \mathbb{N}, \sum\limits_{i=0}^{[\frac{n}{m}]-1}  \left|W_{\frac{i+1}{n}}-W_{\frac{i}{n}}\right|   \xrightarrow[n \to \infty]{}  +\infty \mbox{ almost surely }. $$


So, 
\begin{equation}
\label{eq:final}
\forall \omega \in \Omega, \forall m\in \mathbb{N}: 
\lim\limits_{n \longrightarrow +\infty}V_n \geq  
\left( 1_{\tau_1\geq \frac{1}{m}} \right) 
\cdot (+ \infty),
\end{equation}

but: 
$$\lim\limits_{m \longrightarrow +\infty}   1_{\tau_1\geq \frac{1}{m}}  =1_{\Omega}
\mbox{ almost surely}.$$

So, taking the limit in $m$ in Equation (\ref{eq:final}), we get

$$\lim\limits_{n \longrightarrow +\infty} V_n = +\infty
\mbox{ almost surely},$$

and therefore, 
$$\lim\limits_{n \longrightarrow +\infty} A_n = +\infty
\mbox{ almost surely},$$

which finishes the proof.

