\begin{appendices}

\section{Proofs}\label{app:proofs}
This section provides the proofs of the propositions and theorems from the main text.
\subsection{Proposition~\ref{prop:MPSA_kappa}: number of parameters for the MPSA models}
\begin{proof}
The parameters of the MPSA model of types $\gamma$ are $\pi_1, \mu_1, \Sigma_1, \dots, \pi_C, \mu_C, \Sigma_C$, with the constraints $\pi_c \in \R_{\geq 0}, \sum_{c=1}^C \pi_c = 1$, $\mu_c \in \R^p$ and $\Sigma_c \in \Sym_+(\gamma_c)$.
The number of free parameters for $\pi_1, \dots, \pi_C$ (belonging to the \textit{standard simplex}) is $C-1$, since the last mixture proportion $\pi_C$ is automatically determined from the $C-1$ other ones, via $\pi_C = 1 - \sum_{c=1}^{C-1} \pi_c$.
Then for each $c \in [\![1, C]\!]$, the parameters $\mu_c$ and $\Sigma_c$ describe a PSA model of type $\gamma_c$. Therefore, the number of free parameters is $\kappa(\gamma_c)$, as defined in Equation~\eqref{eq:PSA_kappa}. Since neither the means nor the covariance matrices are shared between the mixture components, the number of parameters for $\mu_1, \Sigma_1, \dots, \mu_C, \Sigma_C$ is simply the sum $\sum_{c=1}^C \kappa(\gamma_c)$.
Eventually, since the mixture proportions are independent from the means and covariance matrices, the total number of parameters is ${\kappa(\gamma) = C - 1 + \sum_{c=1}^C \kappa(\gamma_c)}$.
\end{proof}



\subsection{Theorem~\ref{thm:E_step}: E-step of the EM}
\begin{proof}
The posterior log-probabilities can be rewritten using Bayes' theorem:
\begin{multline}\label{eq:posterior}
    \ln\mathbb{P}(\,y=c \mid x, \theta\,) = \ln\lrp{\pi_c \, \mathcal{N}(\, x \mid \mu_c, \Sigma_c\,)}\\
    - \ln\lrp{\sum_{c'=1}^C \pi_{c'} \, \mathcal{N}(\,  x \mid \mu_{c'}, \Sigma_{c'}\,)}.
\end{multline}
Let us now develop the operand using the eigendecomposition of the sample covariance matrices, $~{\Sigma_c = \sum_{k=1}^{d_c} \lambda_{ck} \Pi_{ck}}$, where $\lambda_{ck}$ are the (ordered decreasing) eigenvalues of $\Sigma_c$ and $\Pi_{ck}$ are the associated eigenspaces, of dimension $\gamma_{ck}$.
One has $~{\ln| \Sigma_c| = \sum_{k=1}^{d_c} \gamma_{ck}\ln{\lambda_{ck}}}$, and via classical trace tricks, one gets 
\begin{align}
    \operatorname{d}^2_{\Sigma_c}(x, \mu_c) &\coloneqq (x-\mu_c)\T\Sigma_c^{-1}(x-\mu_c),\\ 
    &= \tr{\Sigma_c^{-1}(x-\mu_c)(x-\mu_c)\T},\\
    &= \sum_{k=1}^{d_c} \tr{\lambda_{ck}^{-1} \Pi_{ck}(x-\mu_c)(x-\mu_c)\T},\\
    &= \sum_{k=1}^{d_c}\frac{(x - \mu_c)\T \Pi_{ck} (x - \mu_c)}{\lambda_{ck}}.
\end{align}
Consequently, one has 
\begin{multline}
    \ln(\pi_c \, \mathcal{N}(\,  x \mid \mu_c, \Sigma_c \,)) = \ln\pi_c - \frac{p}{2}\ln 2\pi\\
    - \frac{1}{2} \sum_{k=1}^{d_c} \lrp{\gamma_{ck}\ln{\lambda_{ck}}+ \frac{(x - \mu_c)\T \Pi_{ck} (x - \mu_c)}{\lambda_{ck}}}.
\end{multline}
Let us define the cost function $K_c$ similarly as in~\cite{bouveyron_high-dimensional_2007} via the following relationship: $\ln(\pi_c \, \mathcal{N}(\,  x \mid \mu_c, \Sigma_c \,)) = -\frac{K_c(x) + p \ln 2\pi}{2}$. 
Re-injecting $K_c$ in the posterior probabilities yields
\begin{align}
	\mathbb{P}(\,y=c \mid x, \theta\,) &= \frac{\exp\lrp{- \frac{K_c(x) + p \ln 2\pi}{2}}}{\sum_{c'=1}^C \exp\lrp{-\frac{K_{c'}(x) + p \ln 2\pi}{2}}},\\
	&= \frac{1}{\sum_{c'=1}^C \exp\lrp{\frac{K_c(x) - K_{c'}(x)}2}}.
\end{align}
Re-injecting $K_c$ in the log-likelihood yields
\begin{align}
\operatorname{LL}(\theta) &= \sum_{i=1}^n \ln\lrp{\sum_{c=1}^C \pi_c \, \mathcal{N}( \, x_i \mid \mu_c, \Sigma_c \,)},\\
	&= \sum_{i=1}^n \ln\lrp{\sum_{c=1}^C \exp\lrp{-\frac{K_c(x_i) + p \ln 2\pi}{2}}}.
\end{align}
\begin{remark}
    The second term in~\eqref{eq:posterior} is independent of $c \in [\![1, C]\!]$. Therefore, only the first term intervenes in the cluster assignment problem, which can be rewritten as $~{y = \argmax_{c \in [\![1, C]\!]} \ln\lrp{\pi_c \, \mathcal{N}(\,  x \mid \mu_c, \Sigma_c \,)}}$. 
    Then one has $y = \argmin_{c \in [\![1, C]\!]}\, K_c(x)$, which makes the implementation more efficient.
\end{remark}
\end{proof}



\subsection{Theorem~\ref{thm:M_step}: M-step of the EM}
\begin{proof}
The optimal mixture proportions are
\begin{equation}
    \hat\pi_1, \dots, \hat\pi_C = \argmax_{\substack{\pi_c \geq 0\\ \sum_{c=1}^C \pi_c = 1}} \sum_{c=1}^C \lrp{\ln\pi_c \sum_{i=1}^n  t_{ci}},
\end{equation}
whose solutions are given by $\hat\pi_c = \frac1n \sum_{i=1}^n t_{ci}$.
For each $c \in [\![1, C]\!]$, let us write $~{S_c \coloneqq \frac1{n \hat \pi_c} \sum_{i=1}^n t_{ci} \lrp{x_i - \mu_c} \lrp{x_i - \mu_c}\T \in \Sym(p)}$. Then one can rewrite the objective function as
\begin{multline}
    \mathbb{E}_{\,y\mid x, \theta\,} [\ln\mathcal{L}_{\mathrm{c}}((\hat\pi_c, \mu_c, \Sigma_c)_{c=1}^C)] = \text{const}\\
    - \frac{1}{2} \sum_{c=1}^C n\hat\pi_c \lrp{\ln|\Sigma_c| + \tr{ \Sigma_c^{-1} S_c}}.
\end{multline}
Consequently, the M-step on the mean and covariance parameters can be decomposed into the following independent minimization problems for $c \in [\![1, C]\!]$:
\begin{equation}
    \hat\mu_c, \hat\Sigma_c = \argmin_{\substack{\mu_c\in\R^p\\ \Sigma_c\in\Sym_+(\gamma_c)}} \,  \ln|\Sigma_c|  + \tr{ \Sigma_c^{-1} S_c}.
\end{equation}
The solutions to such problems are given in the maximum likelihood estimation theorem of~\cite{szwagier_curse_2024}. One has
$\hat\mu_c = \frac1{n \hat \pi_c} \sum_{i=1}^n t_{ci} \, x_i$ and $\hat\Sigma_c = \sum_{k=1}^{d_c} \hat\lambda_{ck}(t_c, \gamma_c) \, \hat \Pi_{ck}(t_c, \gamma_c)$, where 
$\hat\lambda_{ck}$ and $\hat \Pi_{ck}$
are the block-averaged eigenvalues and eigenspaces of $S_c$.
\end{proof}


\subsection{Theorem~\ref{thm:CPEM}: monotonicity of the CPEM}
\begin{proof}
Let $\mathbb{E}_{\,y\mid x,\theta\,} [\ln\mathcal{L}_{\mathrm{c}}(\cdot)]$ be the {expected} complete-data log-likelihood~\eqref{eq:expected_ll}. Then one has
\begin{equation}
    \mathbb{E}_{\,y\mid x,\theta\,} [\ln\mathcal{L}_{\mathrm{c}}(\theta(\gamma'))] = \sum_{c=1}^C \Psi_c(\gamma_c') + \text{const},
\end{equation}
and 
\begin{equation}
    \kappa(\gamma') = \sum_{c=1}^C \kappa(\gamma_c') + \text{const}.
\end{equation}
Therefore, summing the inequality~\eqref{eq:component_increase} from the theorem statement over $c \in [\![1, C]\!]$ and adding the constants yields
\begin{multline}\label{eq:CPEM_ineq_1}
    \mathbb{E}_{\,y\mid x,\theta\,} [\ln\mathcal{L}_{\mathrm{c}}(\theta(\gamma'))] - \alpha \, \kappa(\gamma')\\ 
    \geq
    \mathbb{E}_{\, y \mid  x, \theta\, } [\ln\mathcal{L}_{\mathrm{c}}(\theta(\gamma))] - \alpha \, \kappa(\gamma),
\end{multline}
where $~{\theta(\gamma) \coloneqq (\hat\pi_c(t_c), \hat\mu_c(t_c), \hat\Sigma_c(t_c, \gamma_c))_{c}\in\Theta(\gamma)}$.
Additionally, by definition of $\theta(\gamma)$, that is $\theta(\gamma) \coloneqq \argmax_{\theta'\in\Theta(\gamma)}\mathbb{E}_{\, y \mid  x, \theta\, } [\ln\mathcal{L}_{\mathrm{c}}(\theta')]$, 
one has
\begin{multline}\label{eq:CPEM_ineq_2}
    \mathbb{E}_{\, y \mid  x, \theta\, } [\ln\mathcal{L}_{\mathrm{c}}(\theta(\gamma))] - \alpha \, \kappa(\gamma)\\ \geq
    \mathbb{E}_{\, y \mid  x, \theta\, } [\ln\mathcal{L}_{\mathrm{c}}(\theta)] - \alpha \, \kappa(\gamma).
\end{multline}
The two previous equations (\ref{eq:CPEM_ineq_1}, \ref{eq:CPEM_ineq_2}) simply mean that a classical EM iteration for the MPSA model of types $\gamma$ increases the expected complete-data penalized log-likelihood $\mathbb{E}_{\, y \mid  x, \theta\, }  [\ln\mathcal{L}_{\mathrm{c}}(\cdot)] - \alpha \, \kappa(\gamma)$, and that an adapted change of types from $\gamma$ to $\gamma'$ increases this quantity even more.
Using Gibbs' inequality as classically done in the proof of the EM monotonicity~\citep{dempster_maximum_1977}, one gets
\begin{multline}
    \ln \mathcal{L}(\theta(\gamma')) - \ln \mathcal{L}(\theta)\\
    \geq \mathbb{E}_{\, y \mid  x, \theta\, } [\ln\mathcal{L}_{\mathrm{c}}(\theta(\gamma'))] - \mathbb{E}_{\, y \mid  x, \theta\, } [\ln\mathcal{L}_{\mathrm{c}}(\theta)].
\end{multline}
We conclude the proof by subtracting $\alpha(\kappa(\gamma') - \kappa(\gamma))$ on both sides and using (\ref{eq:CPEM_ineq_1}, \ref{eq:CPEM_ineq_2}):
\begin{multline}
    (\ln \mathcal{L}(\theta(\gamma')) - \alpha \, \kappa(\gamma')) - (\ln \mathcal{L}(\theta) - \alpha \, \kappa(\gamma))\geq\\
    (\mathbb{E}_{\, y \mid  x, \theta\, } [\ln\mathcal{L}_{\mathrm{c}}(\theta(\gamma'))] - \alpha \, \kappa(\gamma'))\\
    - (\mathbb{E}_{\, y \mid  x, \theta\, } [\ln\mathcal{L}_{\mathrm{c}}(\theta)]  - \alpha \, \kappa(\gamma)) \geq 0.
\end{multline}
\end{proof}


\subsection{Proposition~\ref{prop:denoising}: GMM-based single-image denoising}
\begin{proof}
The Proposition~1 of~\cite{houdard_high-dimensional_2018} proves that $\mathbb{E}(\,  x \mid \tilde x\,) = \sum_{c=1}^C w_c \psi_c(\tilde x) $ with $~{\psi_c(\tilde x) \coloneqq \mu_c + (I_p - \sigma^2 {\Sigma_c}^{-1})(\tilde x - \mu_c)}$. Then, using the eigendecomposition of the sample covariance matrices, $\Sigma_c = \sum_{k=1}^{d_c} \lambda_{ck} \Pi_{ck}$, where $\lambda_{ck}$ are the (ordered decreasing) eigenvalues of $\Sigma_c$ and $\Pi_{ck}$ are the associated eigenspaces, one can rewrite:
\begin{align}
	\psi_c(\tilde x) &= {\mu_c + \lrp{I_p - \sigma^2 \sum_{k=1}^{d_c} \lambda_{ck}^{-1}\Pi_{ck}}(\tilde x - \mu_c)}\\
	&= {\mu_c + \lrp{\sum_{k=1}^{d_c} \Pi_{ck} - \sigma^2 \sum_{k=1}^{d_c} \lambda_{ck}^{-1}\Pi_{ck}}(\tilde x - \mu_c)},\\
	&= {\mu_c + \sum_{k=1}^{d_c} \lrp{1 - \frac{\sigma^2}{\lambda_{ck}}}\Pi_{ck}(\tilde x - \mu_c)},\\
	&= {\mu_c + \sum_{k=1}^{d_c - 1} \lrp{1 - \frac{\sigma^2}{\lambda_{ck}}}\Pi_{ck}(\tilde x - \mu_c)}.
\end{align}
Let us insist on the last line, which is due to the constraints $\lambda_{cd_c} = \sigma^2$ for all $c \in [\![1, C]\!]$ and which shows that the patches are actually projected to the low-dimensional subspaces $~{\mathcal{V}_c \coloneqq \operatorname{Span}(\sum_{k=1}^{d_c - 1} \Pi_{ck})}$. This represents an important computational gain in high dimensions (from $O(p^3)$ to $O(p^2)$) for the same reasons as outlined in Section~\ref{subsec:complexity}.
\end{proof}

