\section{Polyra Swarms}
We will now describe Polyra Swarms mathematically and prove that they can approximate arbitrary shapes. Since our notation is extensive, we provide an overview in Appendix~\ref{app:notation}.

\begin{definition}[Shape]
    We consider a shape $Q$ to be a measurable, bounded subset of space $Q\subseteq \mathbb{R}^{dim}$ with a finite length border. A shape can be represented through an indicator function $q$.
    \begin{equation}
        q(x)=\begin{cases}
                \TRUE,\hspace{3em} x\in Q\\
                \FALSE,\hspace{2.6em} x\notin Q
            \end{cases}
            \label{eqn:indicator}
    \end{equation}
    \label{def:shape}
\end{definition}
We use capital letters to denote shapes, and lowercase letters to refer to indicator functions.

\begin{definition}[Shape Approximation]
    Given a set of samples $X_{train}$, which all lie in a shape $Q$ ($x\in Q,\;\forall x\in X_{train}$), the task of shape approximation is to learn an indicator function $f(x)$ so that the approximation error $\eta=\int_{\mathbb{R}^{dim}} \|f(x)-q(x)\| \,dx$ is minimal.
    \label{def:shapeApprox}
\end{definition}

\begin{definition}[Polytope]
    A common way of describing convex shapes is through polytopes. These are defined through $K$ constraint vectors $M_A \in \mathbb{R}^{K \times dim}$ defining directions and connected $b_A \in \mathbb{R}^K$ bounds that represent the maximum value along this direction inside the shape. Thus a polytope $A$ can be described by Equation~\ref{eqn:polytope}.
    \begin{equation}
        A = \bigcap_{j=1}^{K} \left\{ x \in \mathbb{R}^n : (M_A)^j \cdot x \leq (b_A)^j \right\}
        \label{eqn:polytope}
    \end{equation}
\end{definition}

\begin{definition}[Polyra Swarm]
    A \emph{Polyra Swarm}\footnote{Polyra is a portmanteau of "Polytope" and "Piranha". See Appendix~\ref{app:name}.} $P$ is the conjunction of many base shapes, as shown in Equation~\ref{eqn:merge}.
    \begin{equation}
        p(x)=\bigwedge_{i=0}^N f_i(x),\hspace{5em} P=\bigcap_{i=0}^N F_i
        \label{eqn:merge}
    \end{equation}
    A sample $x$ is in the shape approximated by a given Polyra Swarm, when it lies in each of the base shapes $F_i$
    \label{def:polyra}
\end{definition}

\begin{definition}[Polyra base shapes]
    We use base shapes $F_i$ defined by the logical conjunction of two polytopes (Equation~\ref{eqn:submodel}). If a sample lies in the condition polytope $A_i$, it also has to lie in the consequent polytope $B_i$.
    \begin{equation}
        f_i(x)=(x \in A_i \Rightarrow x \in B_i) \Leftrightarrow f_i(x)= (x \notin A_i \vee x\in B_i) \Leftrightarrow F_i=A_i^{\complement} \cup B_i
        \label{eqn:submodel}
    \end{equation}
    Here $A^{\complement}$ represents the complement shape to A ($a^{\complement}(x)=1-a(x)$).
    Effectively, each base shape excludes the shape $A_i \cap B_i^{\complement}$ from the shape approximated by the Polyra Swarm. 
    \label{def:submodel}
\end{definition}



\begin{theorem}
    For every measurable shape $Q$ and every $\epsilon > 0$, there exists a Polyra Swarm $P$ such that $\int_{\mathbb{R}^d} |p(x) - q(x)| dx < \epsilon$.
\end{theorem}
\begin{proof}
    $(Sketch)$ We can select arbitrarily small dim-simplices using the condition polytopes $A_i$ and remove the volume outside of $Q$ volume using the consequent polytopes $B_i$. $Full\;proof:$ Appendix~\ref{app:usaproof}
\end{proof}

% $Theorem:$ For every measurable shape $Q$ and every $\epsilon > 0$, there exists a Polyra Swarm $P$ such that $\int_{\mathbb{R}^d} |p(x) - q(x)| dx < \epsilon$.

% $Proof\;Sketch:$ We can select arbitrarily small dim-simplices using the condition polytopes $A_i$ and remove the volume outside of $Q$ volume using the consequent polytopes $B_i$. $Full\;proof:$ Appendix~\ref{app:usaproof}.



We now propose an algorithm based on largely random initialization to learn such a swarm of conditional polytopes to approximate the shape containing a set of observed points $X_{train}$ in Equation~\ref{eqn:rnd}. Here $\mathcal{N}$ refers to a normal distribution and $\mathcal{U}$ represents a uniform distribution. Additionally, we leave $(K_A)_i$, $(K_B)_i$ and $N$ as hyperparameters to be discussed in Appendices~\ref{app:h:adim},~\ref{app:h:bdim},~\ref{app:hyper:ensemblesize}.


\begin{equation}
    (M_A)_i^{\mu\nu}, (M_B)_i^{\mu\nu} \overset{\text{i.i.d.}}{\sim} \mathcal{N}(0, 1) \hspace{3em}  (b_A)_i^{\mu} \overset{\text{i.i.d.}}{\sim} \mathcal{U}(\min_{x\in X_{train}}(M_A)_i^\mu\cdot x, \max_{x\in X_{train}}(M_A)_i^\mu\cdot x)
    \label{eqn:rnd}
\end{equation}

We reject those base shapes where $A_i$ does not contain any of the training samples (Appendix~\ref{app:h:minpoi}), and select $(b_B)_i$ from the most extreme values allowed in the condition polytope $A_i$.
\begin{equation}
    (b_B)_i^\mu=\max_{(x\in X_{train}) \;\cup\; ((M_A)_i\cdot x\leq (b_A)_i)} (M_B)_i^\mu\cdot x
    \label{eqn:maximaB}
\end{equation}
For symmetry reasons, we also include the second consequent region induced by $(M_A)_i\rightarrow-(M_A)_i$.

This setup can be learned quickly, is easily parallelized, and guarantees that $p(x)=True\;\forall x\in X_{train}$ ($Proof:$ Appendix~\ref{app:alltrueproof}).




