\section{The local structure of $DR_K$}
\label{s2}
This section proves some preparatory results on the semigroup structure of $DR_K$. To this end, let us start with recalling some basic constructions of idempotents in profinite monoids. Throughout this paper, for a number field $K$, we shall denote by $P_K$ the set of maximal ideals of $K$ and by $I_K$ the monoid of non-zero integral ideals of $K$. For the definition of the Deligne-Ribet monoids, the reader is referred to \cite{Cornelissen_Li_Marcolli_Smit} or \cite{Deligne_Ribet}; also for some concepts and facts in semigroup theory, we refer the reader to \cite{Rhodes_Steinberg}. 

\begin{defn}[cf.\ \cite{Rhodes_Steinberg}]
For a profinite monoid $M$ and an arbitrary element $a \in M$, the sequence $(a^{n!})_{n \in \nat}$ in $M$ converges to an idempotent in $M$ which is denoted by $a^\omega$: That is,
\begin{eqnarray}
a^\omega &:=& \lim_{n \to \infty} a^{n!}.
\end{eqnarray}
\end{defn}

\begin{rem}[cf.\ \cite{Rhodes_Steinberg}]
It is well-known that $a \in M$ is invertible if and only if $a^\omega = 1$, which we shall use below. In particular, for any $s \in G_K^{ab}$, we have $[1, s]^\omega = 1$ in $DR_K$. 
\end{rem}

\begin{defn}[normal form of idempotents]
Let $S \subseteq P_K$ be any subset of $P_K$. Then define the idempotent $e_S \in \ee_K$ as follows:
\begin{eqnarray}
 e_S &:=& [1_S, 1],
\end{eqnarray}
where $1_S \in \hat{O}_K$ is such that $(1_S)_\idp = 1$ if $\idp \in S$ and $(1_S)_\idp = 0$ otherwise. 
\end{defn}

\begin{prop}[classification of idempotents]
\label{classification of idempotents}
For an idempotent $e \in \ee_K$, let $S_e \in \pp(P_K)$ be defined as follows: denoting $e = [\rho_e, s_e] \in \hat{O}_K \times_{\hat{O}_K^\times} G_K^{ab}$, 
\begin{eqnarray}
 S_e &:=& \bigl\{ \idp \in P_K \mid v_\idp (\rho_{e, \idp}) = 0\}. 
\end{eqnarray}
Then the correspondences $e \mapsto S_e$ and $S \mapsto e_S$ are mutually inverse. 
\end{prop}
\begin{proof}
The equality $S=S_{e_S}$ holds since $v_\idp (0) = \infty > 0$ and $v_\idp (1) = 0$. Conversely, we shall prove the equality $e = e_{S_e}$ for any idempotent $e \in DR_K$. Denote $e = [\rho_e, s_e] \in \hat{O}_K \times_{\hat{O}_K^\times} G_K^{ab} \simeq DR_K$ for some $\rho_e \in \hat{O}_K$ and $s_e \in G_K^{ab}$. Since $e = e^\omega$, we have:
\begin{eqnarray}
 e &=& [\rho_e, s_e]^\omega \\
 &=& [\rho_e, 1]^\omega \cdot [1, s_e]^\omega \\
&=& [\rho_e, 1]^\omega.
\end{eqnarray}
Notice here that the $\idp$-component $[\rho_{e, \idp}, 1]^{n!}$ converges to $0$ if and only if $v_\idp (\rho_{e, \idp}) > 0$, that is, if and only if $\idp \not \in S$; otherwise, $[\rho_{e, \idp}, 1]^{n!}$ converges to $1$ because $\rho_{e, \idp} \in O_\idp^\times$ then. This proves that $e = e_{S_e}$ as requested. 
\end{proof}

\begin{lem}
For any $S, S' \subseteq P_K$, we have:
\begin{eqnarray}
 e_S \cdot e_{S'}  &=& e_{S \cap S'}.
\end{eqnarray}
In particular, $e_S \leq e_{S'}$ if and only if $S \subseteq S'$. 
\end{lem}
\begin{proof}
The first claim is clear from the definition of $e_S$, from which the second claim also readily follows. 
\end{proof}

\begin{cor}[maximal idempotents and maximal ideals]
\label{maximal idempotents and maximal ideals}
An idempotent $e \in DR_K$ is maximal if and only if the complement $P_K \setminus S_e$ of the corresponding $S_e$ within $P_K$ is a singleton. Therefore the following map gives a bijection $e \mapsto \idp_e$ from the maximal idempotents of $DR_K$ to the maximal ideals of $O_K$:
\begin{eqnarray}
 e &\longmapsto& P_K \setminus S_e = \{\idp_e\}. 
\end{eqnarray}
\end{cor}

\begin{prop}
Let $S \subseteq P_K$ be any subset of $P_K$; denote by $S^c := P_K \setminus S$ its complement. Then we have the following isomorphism of profinite groups:
\begin{eqnarray}
 (e_{S^c} \cdot DR_K)^\times &\simeq& G_{K, S}^{ab},
\end{eqnarray}
where $G_{K, S}^{ab}$ denotes the maximal abelian Galois group with all $\idp \in S$ unramified. 
\end{prop}
\begin{proof}
To see this, first define $\bar{e}_S$ for $S \subseteq P_K$ by:
\begin{eqnarray}
 \bar{e}_S &:=& \prod_{\idp \in S} \idp^\omega.
\end{eqnarray}
This converges to an idempotent in $DR_K$; and we have $\bar{e}_S \cdot DR_K = e_{S^c} \cdot DR_K$, which can be proved similarly to Proposition \ref{classification of idempotents}. Thus it suffices to prove that we have an isomorphism $(\bar{e}_S \cdot DR_K)^\times \simeq G_{K, S}^{ab}$. But this can be proved by noting that, for each conductor $\idf \in I_K$, we have:
\begin{eqnarray}
 (\bar{e}_S \cdot DR_\idf)^\times &\simeq& C_{\idf'}; 
\end{eqnarray}
where $\idf'$ is the quotient of $\idf$ by $\idp^{v_\idp(\idf)}$'s for all $\idp \mid \idf$ with $\idp \in S$; and thus, $(\bar{e}_S \cdot DR_K)^\times$ is isomorphic to the inverse limit of the ray class groups $C_{\idf'}$, where $\idf'$ run over all conductors prime to any $\idp \in S$. This proves the claim. 
\end{proof}

\begin{lem}
\label{unramified primes}
Let $H \leq G_K^{ab}$ be a clopen subgroup and $K' := (K^{ab})^H$ the corresponding finite abelian extension of $K$. Then a prime $\idp \in P_K$ is unramified in $K'$ if and only if $H$ contains the kernel of the following surjective homomorphism of profinite groups:
\begin{eqnarray}
 G_K^{ab} &\twoheadrightarrow& (\idp^\omega \cdot DR_K)^\times \\
 \sigma &\longmapsto& \idp^\omega \cdot \sigma.
\end{eqnarray}
\end{lem}
\begin{proof}
Composing this map with the above-constructed isomorphism $(\idp^\omega \cdot DR_K)^\times \simeq G_{K, \idp}^{ab}$, we see that this surjection is isomorphic to the projection $G_K^{ab} \twoheadrightarrow G_{K, \idp}^{ab}$, hence the claim. 
\end{proof}

