\section{Proof of the main result}
\label{s3}
\noindent
Based on the above results on the structure of $DR_K$, this section proves our main result:

\begin{thm}
\label{main result}
Two number fields $K, L$ are isomorphic as fields if and only if their Deligne-Ribet monoids $DR_K, DR_L$ are isomorphic as topological monoids. 
\end{thm}

The only-if part is trivial; we prove the if part by (ii) Theorem 3.1 \cite{Cornelissen_deSmit_Li_Marcolli_Smit}: according to the theorem, it is sufficient to construct (I) a norm-preserving isomorphism $\bar{\phi}: I_K \rightarrow I_L$ of monoids; and (II) an isomorphism $\psi: G_K^{ab} \rightarrow G_L^{ab}$ of profinite groups such that, for every finite abelian extension $K' = (K^{ab})^H / K$ (where $H \leq G_K^{ab}$ is a clopen subgroup) and correspondingly $L' := (L^{ab})^{\psi(H)}/L$, $\bar{\phi}$ gives a bijective correspondence between the unramified primes of $K'/K$ and $L'/L$ in such a way that we have $\psi (\sigma_\idp) = \sigma_{\bar{\phi}(\idp)}$, where $\sigma_\idp \in Gal(K'/K)$ denotes the Frobenius for $\idp$. To this end, let $\phi: DR_K \rightarrow DR_L$ be a given isomorphism of topological monoids, from which we shall construct the above $\bar{\phi}: I_K \rightarrow I_L$ and $\psi: G_K^{ab} \rightarrow G_L^{ab}$. 


We put $\psi = \phi |_{DR_K^\times}$, which clearly defines an isomorphism $\psi: G_K^{ab} \rightarrow G_L^{ab}$ of profinite groups;  then we construction of $\bar{\phi}: I_K \rightarrow I_L$ as follows: 

\begin{prop}
Given an isomorphism $\phi: DR_K \rightarrow DR_L$ of topological monoids, we also have an isomorphism $\bar{\phi}: I_K \rightarrow I_L$ of monoids in a canonical way.
\end{prop}
\begin{proof}
By Corollary \ref{maximal idempotents and maximal ideals}, the isomorphism $\phi: DR_K \rightarrow DR_L$ gives a bijective map from the maximal idempotents of $DR_K$ to those of $DR_L$, thus from $P_K$ to $P_L$ too, which extends to an isomorphism $I_K \rightarrow I_L$ of monoids because $I_K, I_L$ are generated freely by $P_K, P_L$ as abelian monoids; we shall denote this isomorphism $I_K \rightarrow I_L$ by $\bar{\phi}$. 
\end{proof}

\begin{lem}
\label{phi and phibar are compatible}
Let $\phi: DR_K \rightarrow DR_L$ be an isomorphism of topological monoids; and $\bar{\phi}: I_K \rightarrow I_L$ be as above, which is generated by $\bar{\phi}: P_K \rightarrow P_L$ by definition. Then, for any $S \subseteq P_K$, we have:
\begin{eqnarray}
 \phi (e_S) &=& e_{\bar{\phi}(S)}. 
\end{eqnarray}
\end{lem}
\begin{proof}
We first prove this for a singleton $S = \{\idp\}$ for $\idp \in P_K$; let us put $e^\idp := e_{P_K \setminus \{\idp\}}$. Then, by definition, $\phi(e^\idp)$ is the maximal idempotent that corresponds to $\bar{\phi}(\idp) \in P_L$, that is, $\phi(e^\idp) = e^{\bar{\phi}(\idp)}$. The general case follows from this and $e_S \leq e_\idp$ if and only if $\idp \not \in S$. 
\end{proof}

\begin{lem}
Let $\phi: DR_K \rightarrow DR_L$ and $\bar{\phi}: I_K \rightarrow I_L$ be as above. Then, for any $\idp \in P_K$, we have:
\begin{eqnarray}
\label{compatibility with rec}
 \phi (\rec_K(O_\idp^\times)) &=& \rec_L(O_{\bar{\phi}(\idp)}^\times),
\end{eqnarray}
where $\rec_K: \Ad_K^\times \rightarrow G_K$ denotes the artin reciprocity map. 
\end{lem}
\begin{proof}
In view of the above Lemma \ref{phi and phibar are compatible}, the proof is completely the same as that of Lemma 7.5 and Corollary 7.6 \cite{Cornelissen_Li_Marcolli_Smit}, where we just replace $\phi(\idp)$ with $\bar{\phi}(\idp)$ and Lemma 7.3 \cite{Cornelissen_Li_Marcolli_Smit} with our Lemma \ref{phi and phibar are compatible}. 
\end{proof}

\begin{lem}
For any topological-monoid isomorphism $\phi: DR_K \rightarrow DR_L$, the associated isomorphism $\bar{\phi}: I_K \rightarrow I_L$ preserves the norms. 
\end{lem}
\begin{proof}
By the above isomorphism $\phi: \rec_K(O_\idp^\times) \simeq \rec_L(O_{\bar{\phi}(\idp)}^\times)$, the same argument as Proposition 4.1 \cite{Cornelissen_deSmit_Li_Marcolli_Smit} proves the claim. 
\end{proof}


Now we prove our main result:

\begin{proof}[Proof of Theorem \ref{main result}]
We need to prove that $\bar{\phi}: I_K \rightarrow I_L$ gives a bijective correspondence between the unramified primes of the finite extensions $K'/K$ and $L'/L$, where $K' = (K^{ab})^H$ with $H \leq G_K^{ab}$ a clopen subgroup and $L' = (L^{ab})^{\psi(H)}$; and $\psi(\sigma_\idp) = \sigma_{\bar{\phi}(\idp)}$ for all $\idp$ unramified in $K'/K$. To see the first claim, consider the following commutative diagram:
\begin{equation}
\xymatrix{H \ar@{->}[r] \ar[d]^\psi & G_K^{ab} \ar[d]^\psi  \ar@{->>}[r] & (\idp^\omega \cdot DR_K)^\times \ar[d]^\phi \\
\psi(H) \ar@{->}[r] & G_L^{ab} \ar@{->>}[r] & (\bar{\phi}(\idp)^\omega \cdot DR_L)^\times
}
\end{equation}
This diagram, together with Lemma \ref{unramified primes}, shows that $\idp$ is unramified in $K'/K$ if and only if $\bar{\phi}(\idp)$ is unramified in $L'/L$. (Here note that $\phi$ indeed maps $(\idp^\omega \cdot DR_K)^\times$ to $(\bar{\phi}(\idp)^\omega \cdot DR_L)^\times$ because we have $\phi(\idp^\omega \cdot DR_K) = \phi( e_{P_K \setminus \idp} \cdot DR_K) = e_{P_L \setminus \bar{\phi}(\idp)} \cdot DR_L = \bar{\phi}(\idp)^\omega \cdot DR_L$.)

To see the second claim, consider the isomorphisms $(\idp^\omega \cdot DR_K)^\times \simeq G_{K, \idp}^{ab}$ and $(\bar{\phi}(\idp)^\omega \cdot DR_L)^\times \simeq G_{L, \bar{\phi}(\idp)}^{ab}$; also, choose the $\pi_\idp$ and $\pi_{\bar{\phi}(\idp)}$ as those constructed in the same way as Lemma 7.8 \cite{Cornelissen_Li_Marcolli_Smit}. Then note that $\idp^\omega \cdot [\pi_\idp, 1] = \idp^\omega \cdot [1, \pi_\idp] \in (\idp^\omega \cdot DR_K)^\times$ and similarly $\bar{\phi}(\idp)^\omega \cdot [\pi_{\bar{\phi}(\idp)}, 1] = \bar{\phi}(\idp)^\omega \cdot [1, \pi_{\bar{\phi}(\idp)}] \in (\bar{\phi}(\idp)^\omega \cdot DR_L)^\times$; and these correspond to each other under $\phi$. In other words, regarding them as in $G_{K, \idp}^{ab}$ and $G_{L, \bar{\phi}(\idp)}^{ab}$, this proves that $\psi(\sigma_\idp) = \sigma_{\bar{\phi}(\idp)}$ for $\idp \in P_K$ unramified in $K'/K$. This completes the proof. 
\end{proof}

