\section{Jacobi Equation and Polynomials}\label{appendix:Jacobi}
The Jacobi differential equation is given by
\begin{equation}
\label{eq:Jacobi-eq}
(1-x^2) y''(x) + \left(\beta - \alpha - (\alpha + \beta +2)x\right) y'(x) + \nu(\nu + \alpha + \beta + 1)y(x)\,,
\end{equation}
and is equivalent to the hypergeometric equation with a change of variables. The equation is symmetric under $\nu\to -\nu-\alpha - \beta -1$, therefore without loss of generality we can assume that $2\nu \geq -\alpha-\beta -1$. Frobenius theory gives us two independent solutions to~\eqref{eq:Jacobi-eq}, with many special cases depending on the values of $\alpha, \beta, \nu$ \cite{bateman_bateman}. In the main text we always have integer $\alpha, \beta, \nu$ with the conditions that $\alpha+\nu\geq0$, $\beta+\nu\geq 0$ and $\alpha+\beta\geq0$. For such parameters, the Frobenius solutions can be split into 2 types, based on the sign of $\nu$, which we describe below. See~\cite{bateman_bateman} for an extensive treatment of all the cases.

\subsection*{Case 1:  Non-negative integer $\nu$}
The first solution of Eq.~\eqref{eq:Jacobi-eq} in the case where $\nu \geq 0$ are the Jacobi polynomials $P_\nu^{(\alpha, \beta)}(x)$, which are polynomials or order $\nu$. If $\alpha>-1$ and $ \beta>-1$ they are orthogonal on the interval $[-1,1]$ with respect to the weight $(1-x)^\alpha(1+x)^\beta$. However, they are defined for all $\alpha$ and $\beta$. Explicitly, the Jacobi polynomials are given by the Rodriguez formula
\begin{equation}
\label{eq:Rodriguez}
P_{\nu}^{(\alpha, \beta)}(x) = \frac{(-1)^\nu}{2^\nu \nu!}(1-x)^{-\alpha}(1+x)^{-\beta} \frac{d^\nu}{dx^\nu}\left((1-x)^{\alpha + \nu}(1+x)^{\beta+\nu}\right)\,,
\end{equation}
and satisfy the recurrence relation
\begin{align}
\label{eq:Jacobi-recurrence}
2\nu&(\nu+\alpha +\beta )(2\nu+\alpha +\beta -2)P_{\nu}^{(\alpha ,\beta )}(x)\nonumber \\
&=(2\nu+\alpha +\beta -1)\left[(2\nu+\alpha +\beta )(2\nu+\alpha +\beta -2)x+\alpha^{2}-\beta^{2}\right] P_{\nu-1}^{(\alpha ,\beta )}(x) \nonumber\\
&-2(\nu+\alpha -1)(\nu+\beta -1)(2\nu+\alpha +\beta )P_{\nu-2}^{(\alpha ,\beta )}(x)\,.
\end{align}
The second solution to Eq.~\eqref{eq:Jacobi-eq} can be given by the Jacobi function of the second kind, $Q_\nu^{(\alpha, \beta)}(x)$. Let us now describe the structure of this solution. We first analyse the case for $\alpha, \beta > -1$, returning to the other cases later. If $\alpha,\beta > -1$, the Jacobi function of the second kind can be expressed as the integral
\begin{equation}
\label{eq:JacobiQ1}
Q_\nu^{(\alpha, \beta)}(x)= \frac{1}{2(x-1)^{\alpha}(1+x)^\beta} \int_{-1}^1 \frac{(1-t)^\alpha (1+t)^\beta P_{\nu}^{(\alpha, \beta)}(t)}{x-t} \, \mathrm{d}t\,.
\end{equation}
By adding and subtracting $P_\nu^{(\alpha, \beta)}(x)$ in the integrand, we get
\begin{equation}
\label{eq:Q-sec}
Q_\nu^{(\alpha, \beta)}(x)= P_\nu^{(\alpha, \beta)}(x) Q_0^{(\alpha, \beta)}(x) - \frac{1}{2(x-1)^\alpha(1+x)^\beta} q_\nu^{(\alpha, \beta)}(x)\,,
\end{equation}
where  $q_\nu^{(\alpha, \beta)}(x)$ are the secondary Jacobi polynomials given by
\begin{equation}
\label{eq:seconday-jacobi}
q_\nu^{(\alpha, \beta)}(x) = \int_{-1}^1 \frac{P_\nu^{(\alpha, \beta)}(x) - P_\nu^{(\alpha, \beta)}(t)}{x-t} (1-t)^\alpha (1+t)^\beta \,\mathrm{d}t\,.
\end{equation}
It can be shown that $q_\nu^{(\alpha, \beta)}(x)$ are $\nu-1$ order polynomials that satisfy the same recurrence relation~\eqref{eq:Jacobi-recurrence}  as the Jacobi polynomials, but with different initial conditions. Namely,
\begin{align}
q_{0}^{(\alpha, \beta)}(x) &= 0\,,\\
q_{1}^{(\alpha, \beta)}(x) &= \frac{1}{2}(2+\alpha+\beta)2^{\alpha+\beta+1}\frac{\Gamma(\alpha+1)\Gamma(\beta+1)}{\Gamma(\alpha+\beta+2)}\,,
\end{align}
which follows from Eq.~\eqref{eq:seconday-jacobi}. Thus, the structure of $Q_\nu^{(\alpha, \beta)}$ can be ascertained from an expression for $Q_0^{(\alpha,\beta)}$. To obtain an explicit equation we use the equation
\begin{align}
    \label{eq:JacobiQ-derivative}
    Q_0^{(\alpha, \beta) \,\prime}(x) &= -\frac{2^{\alpha+\beta}\Gamma(\alpha +1)\Gamma(\beta +1) }{\Gamma(\alpha +\beta +1)(x -1)^{\alpha +1}(x +1)^{\beta+1}}  \,,
\end{align}
which can be derived from the Wronskian of the Jacobi equation.
This can be integrated using Feynman's technique, by introducing parameters $r$ and $t$, and then writing the right-hand side of~\eqref{eq:JacobiQ-derivative} as a term proportional to the derivatives of  $(x-t)^{-1}(x+r)^{-1}$ with respect to $r$ and $t$, evaluated at $r=t=1$. This expression can be easily integrated, by commuting the integral with the derivatives, to give us the expression
\begin{equation}
    \label{eq:Q0}
    Q_0^{(\alpha, \beta)}(x) = \frac{(-1)^{\beta+1 } 2^{\alpha+\beta} }{\Gamma(\alpha +\beta +1)} \frac{d^\alpha}{d t^\alpha} \frac{d^\beta}{dr^\beta}\left(\frac{\log(\frac{t-x}{r+x})}{r+t}\right)\bigg|_{r=1,t=1}\,,
\end{equation}
where the constant of integration can be verified to be 0. From this expression it can be easily verified that $Q_0^{(\alpha, \beta)}(x)$ is of the form
\begin{equation}
\label{eq:Q0-2}
    Q_0^{(\alpha, \beta)}(x) = \frac{(-1)^\alpha}{2}\log\left(\frac{1-x}{1+x}\right) + \frac{p^{(\alpha,\beta)}(x)}{(1-x)^\alpha(1+x)^\beta}\,,
\end{equation}
where $p^{(\alpha,\beta)}(x)$ is some polynomial that can be computed using~\eqref{eq:Q0}. Thus for non-negative integers $\alpha$ and $\beta$, we can use~\eqref{eq:Q-sec} and~\eqref{eq:Q0-2} to obtain the analytic structure of the secondary solutions. 

Now we describe the structure for $\alpha<0, \beta>0$ and $\beta<0,\alpha>0$. We obtain this by using the `raising' and `lowering' operators
\begin{subequations}
\begin{align}
    (1-x)\frac{d}{dx}P^{(\alpha,\beta)}_{\nu}(x) - \alpha P^{(\alpha,\beta)}_{\nu}(x) &= -(\alpha+\nu)P^{(\alpha-1,\beta+1)}_{\nu}(x) \label{eq:alpha-down-P}\\
    (1-x)\frac{d}{dx}Q^{(\alpha,\beta)}_{\nu}(x) - \alpha Q^{(\alpha,\beta)}_{\nu}(x) &= (\alpha+\nu)Q^{(\alpha-1,\beta+1)}_{\nu}(x) \label{eq:alpha-down-Q}\\
    (1+x)\frac{d}{dx}P^{(\alpha,\beta)}_{\nu}(x) + \beta P^{(\alpha,\beta)}_{\nu}(x) &= (\beta+\nu)P^{(\alpha+1,\beta-1)}_{\nu}(x)\\
    (1+x)\frac{d}{dx}Q^{(\alpha,\beta)}_{\nu}(x) + \beta Q^{(\alpha,\beta)}_{\nu}(x) &= -(\beta+\nu)Q^{(\alpha+1,\beta-1)}_{\nu}(x)
\end{align}

First, we analyse the $\alpha<0, \beta>0$ case. Recall that we assume $\alpha+\beta>0$. By the previous analysis we know that the $Q^{(0,\alpha+\beta)}_\nu(x)$ is of the form
\begin{equation}
    \label{eq:Q0aplusb}
    Q^{(0,\alpha+\beta)}_\nu(x) = (-1)^\alpha P_\nu^{(0,\alpha+\beta)}(x)\log\left(\frac{1-x}{1+x}\right) + \frac{\tilde{p}^{(0,\alpha+\beta)}_\nu (x)}{(1+x)^{\alpha+\beta}}\,,
\end{equation}
where $\tilde{p}^{(0,\alpha+\beta)}$ is a polynomial. Now, the application of the operator $(1-x)\tfrac{d}{dx} - \alpha$ to~\eqref{eq:Q0aplusb} $|\alpha|$ times gives us
\begin{equation}
    Q^{(\alpha, \beta)}_\nu(x) = (-1)^\alpha P_\nu^{(\alpha,\beta)}(x)\log\left(\frac{1-x}{1+x}\right) + \frac{\tilde{p}^{(\alpha,\beta)}_\nu (x)}{(1+x)^{\beta}}\,,
\end{equation}
where we have used~\eqref{eq:alpha-down-P} and~\eqref{eq:alpha-down-Q} at each step. Similarly, it is easy to show that for $\alpha>0,\beta<0$, we get $Q^{(\alpha,\beta)}_{\nu}(x)$ of the form
\begin{equation}
    Q^{(\alpha, \beta)}_\nu(x) = (-1)^\alpha P_\nu^{(\alpha,\beta)}(x)\log\left(\frac{1-x}{1+x}\right) + \frac{\tilde{p}^{(\alpha,\beta)}_\nu (x)}{(1-x)^{\alpha}}\,,
\end{equation}

\end{subequations}
\subsubsection{Asymptotics}
The asymptotics of the Jacobi Polynomials as $x\to \pm1$ can be easily seen by expanding the Rodriguez formula~\eqref{eq:Rodriguez}. If $\nu \geq 0$ and either $\alpha \geq 0$, or $\alpha + \nu < 0$ the Jacobi polynomials have non-zero values at $x = 1$ given by
\begin{equation}
P_\nu ^{(\alpha, \beta)}(1) = \frac{(\alpha+1)_\nu}{\nu!} \,.
\end{equation}
Similarly, if $\nu \geq 0$ and either $\beta \geq 0$ or $\beta + \nu < 0$, the Jacobi polynomials have non-zero values at $x = -1$ given by
\begin{equation}
P_\nu ^{(\alpha, \beta)}(-1) = \frac{(\beta+1)_\nu}{\nu!}\,.
\end{equation}
If, on the other hand, $\alpha < 0$ and $\alpha + \nu \geq 0$, the asymptotics of the Jacobi Polynomial as $x$ approaches $1$ are
\begin{equation}
P_\nu ^{(\alpha, \beta)}(x) \sim (1-x)^{-\alpha}+ O\left((1-x)^{-\alpha+1} \right)\,.
\end{equation}
Similarly, if $\beta\leq0$ and $\beta+\nu \geq 0$, the asymptotics of the Jacobi Polynomial as $x$ approaches $-1$ are
\begin{equation}
P_\nu ^{(\alpha, \beta)}(x) \sim (1+x)^{-\beta}+ O\left((1+x)^{-\beta+1} \right)\,.
\end{equation}

For the Jacobi function of the second kind $Q_{\nu}^{(\alpha,\beta)}(x)$, note that the coefficient of the $\log$ term is the Jacobi polynomial $P_{\nu}^{(\alpha,\beta)}(x)$. Therefore, the asymptotics of the Jacobi polynomial above can be used to obtain its asymptotics. Furthermore, the non-log terms go as $(1-x)^{-\textrm{max}(0,\alpha)}$ for $x\to1$ and $(1+x)^{-\textrm{max}(0,\beta)}$ for $x\to-1$.



\subsection{Case 2: negative integer $\nu$}
In this case $\nu<0$ is a negative integer and $\nu > - \alpha - \beta - 1$, so $\nu$ cannot be transformed to a positive number using the symmetries of the Jacobi equation. The Jacobi equation then has the following 2 linearly independent solutions:
\begin{equation}
\label{eq:neg-nu-first}
\frac{P^{(\alpha, -\beta)}_{\beta+\nu}(x)}{(1+x)^\beta}\,,
\end{equation}
and
\begin{equation}
\label{eq:neg-nu-second}
\frac{P^{(-\alpha, \beta)}_{\alpha+\nu}(x)}{(1-x)^\alpha}\,.
\end{equation}
These are both rational functions of $x$. Using the asymptotics of the Jacobi Polynomial above, we can obtain the asymptotics of the solutions. First, note that by assumption $\alpha + \nu \geq 0$ and $\beta + \nu \geq 0$, implying in particular that $\alpha>0$ and $\beta>0$. Thus, this tells use that that the first solution~\eqref{eq:neg-nu-first} goes as $(1+x)^{-\beta}$ as $x\to-1$  and $(1-x)^{0}$ for $x\to1$. Similarly, for the second solution we get $(1+x)^{0}$ for $x\to-1$  and $(1-x)^{-\alpha}$ for $x\to1$.

\section{A GHP solution to the Penrose wave equation}
\label{appendix:gen_sol}
Here, we will derive a GHP solution to the spin-$s$ wave equation \eqref{eq:GHP_wave_a}. As a starting point, let us first consider the lowest $\ell = s - k$ mode of $\phi_k$, which satisfies $\eth'\eth\phi_{k,\ell m} = 0$ if $\ell = s - k \geq 0$, and $\eth\eth'\phi_{k,\ell m} = 0$ if $\ell = s - k \leq 0$. It follows that these modes satisfy
\begin{subequations}
\begin{align}
    \th_c'\th_c\phi_{k,\ell m} &= 0 & &\textrm{if} \; \ell = s - k \geq 0 \,, \\
    \th_c\th_c'\phi_{k,\ell m} &= 0 & &\textrm{if} \; \ell = s - k \leq 0 \,. 
\end{align}
\end{subequations}
GHP solutions to these equations satisfying
\begin{subequations}
\begin{align}
    \th_c\phi_{k,\ell m} &= (\th - [2s-k+1]\rho)\phi_{k,\ell m} = 0 & &\textrm{if} \; \ell = s - k \geq 0 \,, \\
    \th_c'\phi_{k,\ell m} &= (\th' - [k+1]\rho')\phi_{k,\ell m} = 0 & &\textrm{if} \; \ell = s - k \leq 0 \,, 
\end{align}
\end{subequations}
are given by
\begin{subequations}
\begin{align}
    \phi_{k,\ell m} &= \rho^{2s-k+1}U_{\ell m}(u){}_{s-k}Y_{\ell m} & &\textrm{if} \; \ell = s - k \geq 0 \,, \\
    \phi_{k,\ell m} &= \rho^{k+1}V_{\ell m}(v){}_{k-s}Y_{\ell m} & &\textrm{if} \; \ell = s - k \leq 0 \,, 
\end{align}
\end{subequations}
where $U$ and $V$ are arbitrary functions, which can be easily seen from the fact that $\th\rho = \rho^2$ and $\th'\rho = \rho\rho'$. 

The operators $\eth'^\dagger\th_c$ and $\eth^\dagger\th_c'$, defined in Eq.~\eqref{eq:ladder} of the main text, can be used to derive higher mode solutions to the spin-$s$ wave equation \eqref{eq:GHP_wave_a}. These operators have the important property that they commute with the wave operator $\Ro$. To establish this, we first need the important commutators
\begin{subequations}
\begin{align}
    \Ro - \Ro' &= 0 \\
    [\th_c, \eth] &= 0 \\
    [\th_c, \eth^\dagger] &= 0 \,.
\end{align}
\end{subequations}
The first two of these easily follow from \eqref{eq:conformal_commutators}. The last can be seen by first noting that the radial dependence of $\eth^\dagger$ is $\eth^\dagger = r\mathring{\eth}^\dagger = A\rho^{-1}\mathring{\eth}^\dagger$ for some (weighted) constant $A$ (cf.~\eqref{eq:eth_dagger}), and where $\mathring{\eth}^\dagger$ is a purely angular operator. Hence, since $\th r = A\th\rho^{-1} = -A = -r\rho$, 
\begin{align}
    \th_c\eth^\dagger\eta &= (\th - [1 + s + \tfrac{1}{2}(p-q+2)]\rho)(r\mathring{\eth}^\dagger\eta) = r\mathring{\eth}^\dagger(\th - [1 + s + \tfrac{1}{2}(p-q)]\rho)\eta = \eth^\dagger\th_c\eta \,.
\end{align}
We can now compute
\begin{align}
    [\Ro, \eth^\dagger\th'_c] &= (\th_c\th'_c - \eth\eth')\eth^\dagger\th'_c - \eth^\dagger\th'_c(\th_c\th'_c - \eth\eth') \nonumber \\
    &= (\th_c\th'_c - \eth\eth')\eth^\dagger\th'_c - (\th'_c\th_c - \eth'\eth)\eth^\dagger\th'_c \\
    &= (\Ro - \Ro')\eth^\dagger\th'_c = 0 \,. \nonumber
\end{align}
Since $\eth'^\dagger\th_c$ and $\eth^\dagger\th_c$ raise and lower spin respectively, if $s - k \geq 0$ it follows that the $\ell = s - k + 1$ mode of $\phi_k$ satisfies
\begin{align}
    \th_c'\th_c\eth'^\dagger\th_c\phi_{k,\ell=s-k+1} &= 0 \,,
\end{align}
which has a GHP solution
\begin{align}
\label{eq:ladder_phi}
    \eth'^\dagger\th_c\phi_{k,\ell=s-k+1} &= \rho^{2s-k+2}U_{\ell=s-k+1}(u){}_{s-k+1}Y_{\ell=s-k+1} \,.
\end{align}
$\phi_{k,\ell=s-k+1}$ can be recovered by applying $\eth^\dagger\th_c'$ to Eq.~\eqref{eq:ladder_phi}, since
\begin{align}
    \eth^\dagger\th_c'\eth'^\dagger\th_c\phi_{k,\ell=s-k+1} = \eth^\dagger\eth'^\dagger\th_c'\th_c\phi_{k,\ell=s-k+1} = \eth^\dagger\eth'^\dagger\eth'\eth\phi_{k,\ell=s-k+1} = \phi_{k,\ell=s-k+1} \,.
\end{align}
Generalizing, we find that for any $\ell$-mode, a GHP solution to $\Ro\phi_{k,\ell} = 0$ is given by
\begin{align}
\label{eq:GHP_sol_1}
    \phi_{k,\ell m} &= (\eth^\dagger\th_c')^{\ell-s+k}(\rho^{\ell+s+1}U_{\ell m}(u){}_\ell Y_{\ell m}) \,,
\end{align}
where without loss of generality we assume $s - k \geq 0$. A second solution can be obtained by noting that, by the massless free-field equations \eqref{eq:massless_f}, $\phi_k = (\eth'^\dagger\th_c)^{2(s-k)}\phi_{2s-k}$, where we choose the solution
\begin{align}
    \phi_{2s-k,\ell m} &= (\eth'^\dagger\th_c)^{\ell-s+k}(\rho^{\ell+s+1}V_{\ell m}(v){}_{-\ell}Y_{\ell m}) \,,
\end{align}
so that
\begin{align}
\label{eq:GHP_sol_2}
    \phi_{k,\ell m} &= (\eth'^\dagger\th_c)^{\ell+s-k}(\rho^{\ell+s+1}V_{\ell m}(v){}_{-\ell}Y_{\ell m}) \,.
\end{align}
The general solution will be a linear combination of the two solutions \eqref{eq:GHP_sol_1} and \eqref{eq:GHP_sol_2}: 
\begin{align}
    \phi_{k,\ell m} &= (\eth^\dagger\th_c')^{\ell-s+k}(\rho^{\ell+s+1}U_{\ell m}(u){}_\ell Y_{\ell m}) + (\eth'^\dagger\th_c)^{\ell+s-k}(\rho^{\ell+s+1}V_{\ell m}(v){}_{-\ell}Y_{\ell m}) \nonumber \\
    &= \bigl[\th_c'^{\ell-s+k}(\rho^{2s-k+1}\tilde{U}_{\ell m}(u)) + \th_c^{\ell+s-k}(\rho^{k+1}\tilde{V}_{\ell m}(v))\bigr]{}_{s-k}Y_{\ell m} \,,
\end{align}
where $U$ and $\tilde{U}$, and $V$ and $\tilde{V}$ differ by a numerical factor. 
