\title{A Plea for History and Philosophy of Statistics and Machine Learning}

\author{Hanti Lin \\\\UC Davis \\ika@ucdavis.edu}

%\author{Abstract: 148 Words \\Body Text: less than 15,000 Words}

\date{} %blind
%\date{\small{February 22, 2018}}
%\date{June 24, 2025}
