\begin{restatable}{proposition}{propunind}
The closed formula of \autoref{eq: wnricdef}, is:
\begin{align}\label{eq: Wnclose}
    \Wt_n(q, S) = \sum_{h=1}^{n}(\prod_{i=1}^{h-1}(\prj{1_{t_i}})\! \cdot\! \prj{0_{t_h}} \! \cdot\! \prod_{i=n-h}^{n-2}(\bev(q,n-i)\,S) \cdot \bev(q,1)) + \prod_{i=1}^{n}\prj{1_{t_i}} \!\cdot\! \prod_{i=0}^{n-1}S\bev(q,n-i).
\end{align}
\end{restatable}
The proof is given in \autoref{appx}.

Given a $\whle{q}{s}$ statement, we can build the chain of finite unitary approximation $\{\Wt(q,\unSem{s}\}_n$.
To define the semantics of the general construct, we must now consider the case of an infinite loop.
However, we can show that there is no limit to this sequence.
From~\cite{vanini_analysis_nodate}, we recall the notion of \emph{strong convergence} and an important theorem about the convergence of an infinite sequence of operators.
% 
\begin{definition}\label{def: strongconv}
    Let $T_n$ and $T$ be linear operators from $\Dom$ to itself.
    If $\|T_n \ket{\psi} - T \ket{\psi}\| \to 0$ as $n \to \infty$, $\forall \ket{\psi} \in \Dom$, then the sequence of operators $\{T_n\}$ is \textbf{strongly convergent} to $T$ (denoted as $T_n \to T$).
\end{definition}
% 
\begin{theorem}\label{th: strongconv}
    Let $\{T_n\}_n$ be a sequence of bounded linear operators from $X \to Y$, where $X$ and $Y$ are Banach spaces.
    $T_n \to T$ if and only if the sequence $\{\|T_n\|\}_n$ is bounded and the sequence $\{T_n x\}_n$ is a Cauchy sequence in $Y$ for all $x \in M \subset X$, where the span of $M$ is dense in $X$.
\end{theorem}
% 
We recall that a sequence $\{x_n\}_n$ in a Hilbert space is said to be a Cauchy sequence if, for any positive real number $\epsilon > 0$, there exists a positive integer $N$ such that for all positive integers $m$ and $n$ greater than $N$, the distance $\|x_m - x_n\| < \epsilon$.

As an example, consider the quantum program $\whle{q}{\skp}$, evaluated on $\ket{\psi}_P = \ket{0\dots}_T\ket{1}_q$.
This loop corresponds to the following chain:
\begin{equation}\label{eq: esUni3}
    \begin{aligned}
    \Wt_0(q, X_q)\ket{0\dots}_T\ket{1}_q &= \ket{0\dots}_T\ket{1}_q, \\
    \Wt_1(q, X_q)\ket{0\dots}_T\ket{1}_q &= \ket{10\dots}_T\ket{1}_q, \\
    % \Wt_2(q, X_q)\ket{0\dots}_T\ket{1}_q &= \ket{110\dots}_T\ket{1}_q, \\
    \Wt_n(q, X_q)\ket{0\dots}_T\ket{1}_q &= \ket{1^{\otimes n}0\dots}_T\ket{1}_q.
\end{aligned}
\end{equation}
We see that for all $n$, $\|\Wt_{n+1}(q, X_q)\ket{\psi}_P - \Wt_n(q, X_q)\ket{\psi}_P\| = 2$. More in general, if 
$$
\ket{\psi}_P = \ket{0\dots}_T(\alpha\ket{0} + \beta\ket{1})_q,
$$
we have 
$$
\Wt_n(q, X_q)\ket{\psi}_P = \alpha\ket{0\dots}_T\ket{0}_q + \beta\ket{1^{\otimes n}0\dots}_T\ket{1}_q,
$$
and for all $n$, $\|\Wt_{n+1}(q, X_q)\ket{\psi}_P - \Wt_n(q, X_q)\ket{\psi}_P\| = 2\beta^2$.
Since for infinite vectors the distance between the element of $\{\Wt_n(q, X_q)\ket{\psi}_P\}_n$ is constant, the sequence $\{\Wt_n(q, X_q)\ket{\psi}_P\}_n$ is not Cauchy, and for \autoref{th: strongconv} the sequence $\{\Wt_n(q, X_q)\}_n$ is not strongly convergent.
The unitary semantics is therefore only able to model a while statement limited to a certain finite number of iterations $k$, which we will denote by $\whleB{q}{s}$.
The semantics for this statement is defined as follows:
$$
\unSem{\whleB{q}{s}} = \Wt_k(q,\unSem{s}).
$$
This unitary operator can be represented by the circuit in \autoref{fig:whileBcirc}.


\subsection{Examples}\label{sec: unsem ex}
We show how the operator $\Wt_n$ works by means of some examples.

First we consider $\whleB{q}{X(q)}$ with the state $\ket{\psi} = \sfrac{1}{\sqrt{2}}\ket{0\dots}_{T}(\ket{0}_q+\ket{1}_q))$ as input:
\begin{equation}\label{eq: esUni1}
    \begin{aligned}
    \Wt_0(q,X_q)\ket{\psi} &= \sfrac{1}{\sqrt{2}}\ket{0\dots}_{T}(\ket{0}_q+\ket{1}_q)\\
    \Wt_1(q,X_q)\ket{\psi} &= \sfrac{1}{\sqrt{2}}(\ket{0\dots}_{T}\ket{0}_q + \ket{10\dots}_{T}\ket{0}_q)\\
    \Wt_2(q,X_q)\ket{\psi} &= \sfrac{1}{\sqrt{2}}(\ket{0\dots}_{T}\ket{0}_q + \ket{10\dots}_{T}\ket{0}_q)\\
    \dots
    \end{aligned}
\end{equation}
Note that with this input, the while loop fully terminates, and in fact, $\Wt_n(q, X_q)$ reaches a fixpoint.

Things are different when non-termination is involved, as in the loop $\whle{q}{H(q)}$ with the same input $\ket{\psi}$:
\begin{equation}\label{eq: esUni2}
    \begin{aligned}
    \Wt_0(q,H_q)\ket{\psi} &= \sfrac{1}{\sqrt{2}}\ket{0\dots}_{T}(\ket{0}_q+\ket{1}_q)\\
    \Wt_1(q,H_q)\ket{\psi} &= \sfrac{1}{\sqrt{2}}\ket{0\dots}_{T}\ket{0}_q + \sfrac{1}{2}(\ket{10\dots}_{T}\ket{0}_q - \ket{10\dots}_{T}\ket{1}_q)\\
    \Wt_2(q,H_q)\ket{\psi} &= \sfrac{1}{\sqrt{2}}\ket{0\dots}_{T}\ket{0}_q + \sfrac{1}{2}\ket{10\dots}_{T}\ket{0}_q \\
    &+ \sfrac{1}{\sqrt{8}}(\ket{110\dots}_{T}\ket{0}_q - \ket{110\dots}_{T}\ket{1}_q)\\
    \Wt_3(q,H_q)\ket{\psi} &= \sfrac{1}{\sqrt{2}}\ket{0\dots}_{T}\ket{0}_q + \sfrac{1}{2}\ket{10\dots}_{T}\ket{0}_q \\
    &+ \sfrac{1}{\sqrt{8}}\ket{110\dots}_{T}\ket{0}_q +
    \sfrac{1}{4}(\ket{1110\dots}_{T}\ket{0}_q - \ket{1110\dots}_{T}\ket{1}_q)\\
    \Wt_n(q,H_q)\ket{\psi} &= \Sigma_{i=0}^{n}\sfrac{1}{\sqrt{2^{i+1}}} \ket{1^{\otimes i}0\dots}_{T}\ket{0}_q - 
    \sfrac{1}{\sqrt{2^{n+1}}} \ket{1^{\otimes n}0\dots}_{T}\ket{1}_q.
    \end{aligned}
\end{equation}  
% 
% 
Since each $t_j$ controls the execution of the $j$-th iteration, $t_j = 1$ indicates that the $j$-th iteration has been executed (see \autoref{fig:whileBcirc} and \autoref{fig:whileCirc}). 
During each iteration of $\wt_n$, the terminating part of the state—where $q$ equals $\ket{0}$—is gradually increased. In contrast, the portion corresponding to non-termination, where $q$ equals $\ket{1}$, decreases but never fully reaches zero.

Finally, consider again the while loop $\whle{q}{\skp}$, evaluated on $\ket{0\dots}_T\ket{1}_q$ in \autoref{eq: esUni3}.
Here for a divergent loop, each $\wt_n$ differs from the previous ones, reflecting that the unitary semantics corresponds to the partial results of the divergent loop computation.




\section{Linear Semantics}\label{sec: lnSem}
To model infinite computation in quantum computing, we need to enlarge the domain of denotations so as to include an appropriate limit.
To this purpose, we observe that a unitary operator is also bounded and, therefore, can be seen as an element of the Banach Space of linear bounded operators on $\Dom$.


We start by defining the linear semantics for each statement in $SL$, except the \texttt{while} statement.
% 
\begin{definition}
    Let $\Bnd(\Dom)$ be the space of linear bounded operators from $\Dom$ to $\Dom$ equipped with the operator norm $\|A\| = \sup_{\|\ket{\psi}\| = 1} \|A\ket{\psi}\|$.
    The linear semantics is a function $\lnSem{\cdot}: s \to \Bnd(\Dom)$, defined by:
    \begin{enumerate}
        \item $\lnSem{\skp} = \Ident_{\Dom}$;
        \item $\lnSem{U(\arrw{q})} = \arrw{U}$, where $\arrw{U} = \Ident \otimes U \otimes \Ident$, i.e. the extension of $U$ on $\Dom$;
        \item $\lnSem{s_1;\, s_2} = \lnSem{s_2}\cdot\lnSem{s_1}$;
\end{enumerate}
\end{definition}
% 
Note that the linear semantics of these statements is exactly the same as the unitary semantics defined in \autoref{def:unSem}.
For the \texttt{while} statement, we need instead to introduce a new bounded linear operator, which will allow us to give a meaning also to infinite computations.

Let $S$ be a bounded linear operator and $q \in Q_s$. We define the operator $\lt_n(q,S)$ by:
\begin{equation}\label{eq: lnricdef}
    \begin{aligned}
        \lt_0(q,S) &= \textit{0}\\
        \lt_n(q,S) &= (\prj{0_{t_1}} + \prj{1_{t_1}} \cdot \cS(\lt_{n-1}(q,S)) \cdot S) \bev(q,1),\\
    \end{aligned}
\end{equation}
where $\textit{0}$ is the zero operator in $\Dom$, $\cS$ produces the shift $t_n \rightarrow t_{n+1}$, and the controlled operation is represented by the operator defined in \autoref{prop: ctrl}.

It is easy to see that for $n>0$, the operator $\lt_n(q, S)$ is equivalent to the operator $\wt_n(q, S)$ as defined in \autoref{eq: wnricdef}; in fact, $\lt_n(q, S)$ is defined as the composition of the controlled-not gate, which evaluates the guard, and the operator corresponding to the composition of the semantics of the loop body $S$ and $\lt_{n-1}(q, S)$ shifted by $\cS$.


\begin{proposition}\label{prop: boundln}
    For all $n$, if $S$ is bounded then $\lt_n(q,S)$ is bounded. 
\end{proposition}
\begin{proof}
    Let's consider $\lt_n(q,S)$ and a vector $\ket{\psi}$ such that $\| \psi \| = 1$:
    \begin{align*}
        \| (\prj{0_{t_1}} + \prj{1_{t_1}} \cdot \cS(\lt_{i-1}(q,S)) \cdot S)\bev(q,1)\ket{\psi} \|^2 = \\
        &\text{(since }\bev(q,1) \text{ is unitary)}\\
        = \| (\prj{0_{t_1}} + \prj{1_{t_1}} \cdot \cS(\lt_{i-1}(q,S)) \cdot S)\ket{\psi} \|^2 = \\ 
         = \| \prj{0_{t_1}}\ket{\psi} + \prj{1_{t_1}} \cdot \cS(\lt_{i-1}(q,S)) \cdot S\ket{\psi} \|^2 =\\ 
        \hspace{10em}
        &\text{($\prj{0_{t_1}}\!\!\ket{\psi}$ and $\prj{1_{t_1}}\!\cS(\lt_{i-1}(q,S)) S\!\ket{\psi}$ are orthogonal \cite{heinosaari2008guidemathematical})}\\
        = \| \prj{0_{t_1}}\ket{\psi} \|^2 + \| \prj{1_{t_1}} \cS(\lt_{i-1}(q,S)) S)\ket{\psi} \|^2 \le \\
        &(\cS(\lt_{i-1}(q,S)) S) \text{ is bounded)}\\
        \le \| \prj{0_{t_1}}\ket{\psi} \|^2 + \| \prj{1_{t_1}} \ket{\psi} \|^2 =\\
        = \| (\prj{0_{t_1}} + \prj{1_{t_1}})\ket{\psi} \|^2 =\| \ket{\psi} \|^2 = 1.
    \end{align*}
    Since $\|\lt_n(q,S) \ket{\psi} \|^2 \le 1$ also $\|\lt_n(q,S) \ket{\psi} \| \le 1$.
\end{proof}


\begin{restatable}{proposition}{proplnind}
The closed formula of \autoref{eq: lnricdef} is:
\begin{align}\label{eq: Lnclose}
    \Lt_n(q,S) = \sum_{k=1}^{n}(\prod_{i=1}^{k-1}(\prj{1_{t_i}}) \cdot \prj{0_{t_k}} \cdot \prod_{i=n-k}^{n-2}(\bev(q,n-i)\cdot S) \cdot \bev(q,1)).
\end{align}
\end{restatable}
A proof by induction is given in \autoref{appx}.


Now, given the $\whle{q}{s}$ statement, we can define a chain of linear operator $\{\Lt_n(q,\lnSem{s})\}_n$ that represent the linear semantics of all finite executions of the while loop.
\begin{proposition}\label{prop: boundlnsem}
    For all $n$, $\Lt_n(q,\lnSem{s})$ is bounded.
\end{proposition}
\begin{proof}
    The proof follows by means of a structural induction on $s$ and \autoref{prop: boundln}
\end{proof}
To define the semantics of the whole construct, we now must include the case of an infinite loop, which, as we will show later, is captured by the limit of the sequence $\{\Lt_n(q,\lnSem{s})\}_n$.

From \autoref{th: strongconv}, we know that if we prove that the sequence $\{\|\Lt_n(q, \lnSem{s})\|\}$ is bounded and that, for all $\ket{\psi} \in \Dom$, the sequence $\{\Lt_n(q, \lnSem{s}) \ket{\psi}\}$ is a Cauchy sequence in $\Dom$, then we can conclude that the sequence $\{\Lt_n(q,\lnSem{s})\}_n$ has a limit.
So, let's first prove that $\{\|\Lt_n(q,\lnSem{s})\|\}_n$ is bounded.

\begin{proposition}\label{prop: lnseqbound}
    The sequence $\{\|\Lt_n(q, \lnSem{s})\|\}$ is bounded.
\end{proposition}

\begin{proof}
    From \autoref{prop: boundlnsem}, we know that for all $n$, $\|\Lt_n(q, \lnSem{s})\| \le 1$, thus the sequence $\{\|\Lt_n(q, \lnSem{s})\|\}$ is bounded above~\cite{mattuck2013introduction}.
\end{proof}

We will now show that, for all $\ket{\psi} \in \Dom$, the sequence $\{\Lt_n(q, \lnSem{s}) \ket{\psi}\}$ is Cauchy. To this purpose, we state some support lemmas.

\begin{lemma}\label{prop: diffVect}
    For all $n > 0$, $\Lt_n(q, \lnSem{s}) = \sum_{i=1}^n \left( \Lt_i(q, \lnSem{s}) - \Lt_{i-1}(q, \lnSem{s}) \right)$.
\end{lemma}

\begin{proof}
    In general, given a sequence $A_n$, by induction on $n$ and by straightforward arithmetic simplifications, we can prove that $A_n = \sum_{i=1}^n (A_i - A_{i-1}) + A_0$.  
    In our case, $\Lt_0(q, \lnSem{s}) = 0$, thus $\Lt_n(q, \lnSem{s}) = \sum_{i=1}^n \left( \Lt_i(q, \lnSem{s}) - \Lt_{i-1}(q, \lnSem{s}) \right)$.
    % For instance, $\Lt_2(q, \lnSem{s})\!=\! \sum_{i=1}^2\!\left( \Lt_i(q, \lnSem{s}) - \Lt_{i-1}(q, \lnSem{s}) \right) = \Lt_2(q, \lnSem{s}) - \Lt_1(q, \lnSem{s}) + \Lt_1(q, \lnSem{s})$.
\end{proof}


\begin{lemma}\label{prop: orthoDiff}
    For every $n \neq m$, $\Lt_n(q, \lnSem{s}) - \Lt_{n-1}(q, \lnSem{s})$ and $\Lt_m(q, \lnSem{s}) - \Lt_{m-1}(q, \lnSem{s})$ are orthogonal.
\end{lemma}

\begin{proof}
    From \autoref{eq: Lnclose}, we can compute:
    \begin{equation*}
        \begin{gathered}
        \Lt_n(q, \lnSem{s}) - \Lt_{n-1}(q, \lnSem{s}) = \prod_{i=1}^{n-1} \left( \prj{1_{t_i}} \right) \cdot \prj{0_{t_n}} \cdot \prod_{i=0}^{n-2} \left( \bev(q, n - i) \cdot S \right) \cdot \bev(q, 1), \\
        \Lt_m(q, \lnSem{s}) - \Lt_{m-1}(q, \lnSem{s}) = \prod_{i=1}^{m-1} \left( \prj{1_{t_i}} \right) \cdot \prj{0_{t_m}} \cdot \prod_{i=0}^{m-2} \left( \bev(q, n - i) \cdot S \right) \cdot \bev(q, 1).
        \end{gathered}
    \end{equation*}
    Clearly, if $n \neq m$, $\prod_{i=1}^{n-1} \left( \prj{1_{t_i}} \right) \prj{0_{t_n}}$ and $\prod_{i=1}^{m-1} \left( \prj{1_{t_i}} \right) \prj{0_{t_m}}$ are orthogonal, and thus $\Lt_n(q, \lnSem{s}) - \Lt_{n-1}(q, \lnSem{s})$ and $\Lt_m(q, \lnSem{s}) - \Lt_{m-1}(q, \lnSem{s})$ are orthogonal.
\end{proof}

\begin{lemma}\label{prop: increasing}
    For every $n, m$, if $n \leq m$, then $\|\Lt_n(q, \lnSem{s}) \ket{\psi}\| \leq \|\Lt_m(q, \lnSem{s}) \ket{\psi}\|$.
\end{lemma}

\begin{proof}
    From \autoref{eq: Lnclose}, we observe that if $n \leq m$, the summation corresponding to $\Lt_m(q, \lnSem{s})$ contains all the terms of $\Lt_n(q, \lnSem{s})$ plus additional terms.  
    Recall that each term in the summation consists of projectors that are mutually orthogonal, and the sum of all projectors is different from the identity.  
    Thus, if $\Lt_n(q, \lnSem{s}) \ket{\psi} = \sum \alpha_i \ket{e_i}$ and $\Lt_m(q, \lnSem{s}) \ket{\psi} = \sum \beta_i \ket{e_i}$, where $\ket{e_i}$ is a standard basis of $\Dom$, then $\forall i, \, \alpha_i \neq 0 \Rightarrow \beta_i = \alpha_i$.
    In other words, $\Lt_n(q, \lnSem{s}) \ket{\psi}$ is a substate of $\Lt_m(q, \lnSem{s}) \ket{\psi}$ since $\Lt_m(q, \lnSem{s})$ projects the state on `more basis vectors' that $\Lt_n(q, \lnSem{s})$.
\end{proof}

\begin{theorem}
    For all vectors $\ket{\psi} \in \Dom$, the sequence $\{\Lt_n(q, \lnSem{s}) \ket{\psi}\}_n$ is Cauchy.
\end{theorem}
\begin{proof}
    By \autoref{prop: diffVect}, $\Lt_n(q,\lnSem{s})\ket{\psi} = \Sigma_{i=1}^n (\Lt_i(q,\lnSem{s}) - \Lt_{i-1}(q,\lnSem{s}))\ket{\psi}$.
    By \autoref{prop: orthoDiff} and \cite[Exercise 2]{heinosaari2008guidemathematical} it holds that:
    $$
    \|\Lt_n(q,\lnSem{s})\ket{\psi}\|^2 = \Sigma_{i=1}^n \|( \Lt_i(q,\lnSem{s}) - \Lt_{i-1}(q,\lnSem{s}))\ket{\psi} \|^2.
    $$
    Let us consider the sequence of partial sums $\{\Sigma_{j=1}^n \|( \Lt_i(q,\lnSem{s}) - \Lt_{i-1}(q,\lnSem{s}))\ket{\psi} \|^2 \}_n$.  
    By \autoref{prop: boundlnsem} and \autoref{prop: increasing}, we know that all partial sums are bounded and that the sequence of partial sums is increasing.   
    Since the sequence of partial sums is both increasing and bounded above, it must converge~\cite{mattuck2013introduction}.
    This implies that the infinite sum $\Sigma_{j=1}^{\infty} \|( \Lt_i(q,\lnSem{s}) - \Lt_{i-1}(q,\lnSem{s}))\ket{\psi} \|^2$ also converges~\cite{spivak08}.
    We have that $\Sigma_{i=1}^{\infty} \| ( \Lt_i(q, \lnSem{s}) - \Lt_{i-1}(q, \lnSem{s}) ) \ket{\psi} \|^2$  
    converges, and for all $i$,  
    $ \| ( \Lt_i(q, \lnSem{s}) - \Lt_{i-1}(q, \lnSem{s}) ) \ket{\psi} \|^2 > 0$.  
    Thus, $\lim_{i \rightarrow \infty} \left( \| ( \Lt_i(q, \lnSem{s}) - \Lt_{i-1}(q, \lnSem{s}) ) \ket{\psi} \|^2 \right) = 0$, which implies that $\lim_{i \rightarrow \infty} \left( \| \Lt_i(q, \lnSem{s}) \ket{\psi} - \Lt_{i-1}(q, \lnSem{s}) \ket{\psi} \| \right) = 0$.  
    This ensures that the sequence $\{ \Lt_i(q, \lnSem{s}) \ket{\psi} \}_i$ is a Cauchy sequence in $\Dom$.
\end{proof}

Having shown that, for all $\ket{\psi} \in \Dom$, 
$\{\Lt_n(q,\lnSem{s} \ket{\psi}\}_n$ is a Cauchy sequence,
by \autoref{th: strongconv} we can conclude that the sequence $\{\Lt_n(q,\lnSem{s})\}$ has a limit.
Thus, we use that limit to define the semantics of the quantum loop:
$$
\lnSem{\whle{q}{s}} = \lim_{n \to \infty} \Lt_n(q, \lnSem{s}).
$$
Moreover, the following proposition shows that this limit corresponds to a well-defined linear operator on $\Dom$.
\begin{proposition}
    Let $\{\ket{e_i}\}_i$ be the set of standard basis of $\Dom$, and let $\cL(q,\lnSem{s})$ be the linear operator defined as $\cL(q,\lnSem{s}) \ket{e_i} = \lim_{n \to \infty}\Lt_n(q,\lnSem{s}) \ket{e_i}$, $\forall \ket{e_i}$. Then 
    \[
    \cL(q,\lnSem{s})= \lim_{n \to \infty}\{\Lt_n(q,\lnSem{s})\}_n
    \].
\end{proposition}
\begin{proof}
    By definition, for all basis $\ket{e_i}$ of $\Dom$, $\cL(q,\lnSem{s}) \ket{e_i} = \lim_{n \to \infty} \Lt_n(q,\lnSem{s}) \ket{e_i}$, thus $\|\Lt_n(q,\lnSem{s}) \ket{e_i} - \cL(q,\lnSem{s}) \ket{e_i}\| \to 0$ as $n \to \infty$.
    Therefore, for all $\ket{\psi} \in \Dom$, $\|\Lt_n(q,\lnSem{s}) \ket{\psi} - \cL(q,\lnSem{s}) \ket{\psi}\| \to 0$ as $n \to \infty$.    
\end{proof}



\section{Relation between Unitary and Linear Semantics}
So far, we have introduced two semantics:
\begin{description}
    \item[-] The unitary semantics models exactly the behavior of quantum computation, and
    \item[-] the linear semantics allows us to define a fixpoint and define the semantics of the infinite loops.
\end{description}

In this section, we investigate the relationship between these two semantics.

Let us consider the examples introduced in \autoref{sec: unsem ex}.
We can construct the semantics of the program $\whle{q}{X(q)}$, starting from the state $\ket{\psi} = \sfrac{1}{\sqrt{2}}\ket{0\dots}_{T}(\ket{0}_q+\ket{1}_q)$, as follows:
% Let's consider the various $\Lt_n(q,X_q)$:
\begin{equation}\label{eq: esLni1}
    \begin{aligned}
    \Lt_0(q,X_q)\ket{\psi} &= 0\\
    \Lt_1(q,X_q)\ket{\psi} &= \sfrac{1}{\sqrt{2}}\ket{0\dots}_{T}\ket{0}_q\\
    \Lt_2(q,X_q)\ket{\psi} &= \sfrac{1}{\sqrt{2}}(\ket{0\dots}_{T}\ket{0}_q + \ket{10\dots}_{T}\ket{0}_q)\\
    \Lt_3(q,X_q)\ket{\psi} &= \sfrac{1}{\sqrt{2}}(\ket{0\dots}_{T}\ket{0}_q + \ket{10\dots}_{T}\ket{0}_q)
    \end{aligned}
\end{equation}    
We see that we have 'collected' the sub-state that corresponds to the terminating execution, and since the program is fully terminating, the fixpoint is a state with a norm equal to $1$.
Comparing the examples in the previous sections (\autoref{eq: esUni1}), it is easy to see that when the loop terminates, the two semantics coincide, specifically $\Lt_{n+1} = \Wt_n$. 
In this case, the linear semantics is `behind' the unitary semantics because the latter also includes the component that corresponds to executions that `keep going.'

Now consider the program $\whle{q}{H(q)}$ and the construction of its semantics:
\begin{equation}\label{eq: esLni2}
    \begin{aligned}
        \Lt_0(q,H_q)\ket{\psi} &= 0\\
        \Lt_1(q,H_q)\ket{\psi} &= \sfrac{1}{\sqrt{2}}\ket{0\dots}_{T}\ket{0}_q\\
        \Lt_2(q,H_q)\ket{\psi} &= \sfrac{1}{\sqrt{2}}\ket{0\dots}_{T}\ket{0}_q + \sfrac{1}{2}\ket{10\dots}_{T}\ket{0}_q\\
        \Lt_3(q,H_q)\ket{\psi} &= \sfrac{1}{\sqrt{2}}\ket{0\dots}_{T}\ket{0}_q + \sfrac{1}{2}\ket{10\dots}_{T}\ket{0}_q + \sfrac{1}{\sqrt{8}} \ket{110\dots}_{T}\ket{0}_q)\\
        \Lt_n(q,H_q)\ket{\psi} &= \sum_{i=1}^{n}\sfrac{1}{\sqrt{2^n}} \ket{1^{\otimes i}0\dots}_{T}\ket{0}_q.
    \end{aligned}    
\end{equation}
Here, we see that in each approximation $\Lt_n$, we obtain a state with a norm less than 1, which corresponds to the part of the execution that terminates in at most $n-1$ iterations.
If we compare the linear semantics in \autoref{eq: esLni2} with the corresponding unitary semantics in \autoref{eq: esUni2}, we observe that the linear semantics has a `missing' part in the output states—specifically, the portion of the state representing the execution that `keeps going'.  


Finally, consider the while loop $\whle{q}{skip}$, evaluated on $\ket{0\dots}_{T}\ket{1}_q$:
\begin{equation}\label{eq: esLni3}
    \begin{aligned}
    \Lt_0(q,\Ident)\ket{0\dots}_{T}\ket{1}_q &= 0\\
    \Lt_1(q,\Ident)\ket{0\dots}_{T}\ket{1}_q &= \prj{0_{t_1}}\ket{10\dots}_{T}\ket{1}_q = 0\\
    \Lt_2(q,\Ident)\ket{0\dots}_{T}\ket{1}_q &= \prj{0_{t_1}}\ket{10\dots}_{T}\ket{1}_q + \prj{1_{t_1}}\prj{0_{t_2}}\ket{110\dots}_{T}\ket{1}_q = 0.\\
    \end{aligned}
\end{equation}
When dealing with a loop that diverges for the whole quantum state, the linear semantics in \autoref{eq: esLni3} evaluates to $0$.
%as the linear semantics of a non-terminating loop is the zero operator. 
On the other hand, the unitary semantics (\autoref{eq: esUni3}) computes all partial executions of the divergent loop.
% We see that the unitary semantics compute a partial evaluation of the at every step.

More generally, in all examples, the unitary operator $\Wt_n$ returns the portion of the state corresponding to executions that terminate after less than $n$ iterations, along with the partial results of computations that are still ongoing. In contrast, the linear semantics can separate the terminating portion of the computation.
In fact, by examining the definition of $\Wt_n$ (\autoref{eq: Wnclose}), we can identify two key components:
$$
\prj{0_{t_h}} \cdot \prod_{i=n-h}^{n-2} \big( \bev(q, n-i) S \big) \cdot \bev(q, 1),
$$
which is also present in the linear semantics (\autoref{eq: Lnclose}), and the final term is given by:
$$
\prod_{i=1}^n \prj{1_{t_i}} \cdot \prod_{i=0}^{n-1} S \bev(q, n-i).
$$
The first part corresponds to computations where the guard becomes $0$ after the $(n-1)$-th execution, indicating the terminating of the. 
The second part represents the non-terminating portion, where the guard remains true, meaning that the loop is still in progress.
The linear semantics, therefore, returns a sub-state of the result of the unitary semantics.  
For this reason, we can consider the linear semantics as an \textit{under-approximation} of the unitary semantics.  
By discarding part of the result, the linear semantics allows the definition of a limit and, therefore, gives meaning to infinite behaviors.

