        &=\! \sum_{k=2}^{n+1}(\prod_{i=1}^{k-1} (\prj{1_{t_{i}}}) \prj{0_{t_{k}}} \prod_{i=n-(k-1)}^{n-2} (\bev(q,(n+1)-i)\unSem{s}) \bev(q,2)) + \prod_{i=1}^{n+1}\prj{1_{t_{i}}} \prod_{i=0}^{n-1}\unSem{s}\bev(q,(n+1)-i).\\
    \end{aligned}
\end{equation*}   
Secondly, let's consider $\wt'' = \wt' \cdot \unSem{s} \cdot \bev(q,1)$, it result in:
\begin{equation*}
