        \wt'' &=\! \Big( \sum_{k=2}^{n+1}(\prod_{i=1}^{k-1} (\prj{1_{t_{i}}}) \prj{0_{t_{k}}} \prod_{i=n-(k-1)}^{n-2} (\bev(q,(n+1)-i)\unSem{s}) \bev(q,2))\\
