\begin{equation*}
    \wt_{n+1} = \sum_{k=1}^{n+1}(\prod_{i=1}^{k-1} (\prj{1_{t_{i}}}) \prj{0_{t_{k}}} \prod_{i=(n+1)-k}^{n-1} (\bev(q,(n+1)-i)\unSem{s}) \bev(q,1)) + \prod_{i=1}^{n+1}\prj{1_{t_{i}}} \prod_{i=0}^{n}\unSem{s}\bev(q,(n+1)-i),
\end{equation*}
i.e., we write $\Wt_{n+1}$ in the form of \autoref{eq: Wnclose}.

\end{proof}

\proplnind*
\begin{proof}
If $n=0$, $\lt_0 = 0$ and $\Lt = \sum_{k=1}^{0}(\dots) = 0$.
By inductive hypothesis,
\begin{equation*}
    \lt_n = \sum_{k=1}^{n}(\prod_{i=1}^{k-1}(\prj{1_{t_i}}) \cdot \prj{0_{t_k}} \cdot \prod_{i=n-k}^{n-2}(\bev(q,n-i)\lnSem{s}) \cdot \bev(q,1)).
\end{equation*}
Let's consider $\lt_{n+1} = (\prj{0_{t_1}} + \prj{1_{t_1}} \cdot \mathcal{S}(\lt_{n}) \cdot \lnSem{s}) \bev(q,1)$.
By inductive hypothesis $\lt_n = \Lt_n$.
First we compute $\mathcal{S}(\Lt_{n})$, in particular,
\begin{equation*}
    \mathcal{S}(\Lt_{n}) = \sum_{k=1}^{n}(\prod_{i=1}^{k-1}(\prj{1_{t_{i+1}}}) \cdot \prj{0_{t_{k+1}}} \cdot \prod_{i=n-k}^{n-2}(\bev(q,n-i+1)\lnSem{s}) \cdot \bev(q,2)).
\end{equation*}
The initial and final values of the first product can be updated to remove the $+1$ from the indices, resulting in:
\begin{equation*}
    \mathcal{S}(\Lt_{n}) = \sum_{k=1}^{n}(\prod_{i=2}^{(k+1)-1}(\prj{1_{t_{i}}}) \cdot \prj{0_{t_{k+1}}} \cdot \prod_{i=n-k}^{n-2}(\bev(q,(n+1)-i)\lnSem{s}) \cdot \bev(q,2)).
\end{equation*}
Then, the $k+1$ can be collected, and the summation indices can be updated, resulting in the following:
\begin{equation*}
    \mathcal{S}(\Lt_{n}) = \sum_{k=2}^{n+1}(\prod_{i=2}^{k-1}(\prj{1_{t_{i}}}) \cdot \prj{0_{t_{k}}} \cdot \prod_{i=n-(k-1)}^{n-2}(\bev(q,(n+1)-i)\lnSem{s}) \cdot \bev(q,2)).
\end{equation*}
Now we sobstitude this equation in $\lt_{n+1} = \prj{0_{t_1}} \cdot \bev(q,1) + \prj{1_{t_1}} \cdot \mathcal{S}(\Lt_{n}) \cdot \lnSem{s} \cdot \bev(q,1)$.
Initially, we compute $\lt' = \prj{1_{t_1}} \cdot \mathcal{S}(\Lt_{n})$, in particular:
\begin{equation*}
    \begin{aligned}
        &\lt' =\! \prj{1_{t_1}} \big( \sum_{k=2}^{n+1}\prod_{i=2}^{k-1} (\prj{1_{t_{i}}}) \prj{0_{t_{k}}}  \prod_{i=n-(k-1)}^{n-2} (\bev(q,(n+1)-i)\lnSem{s}) \bev(q,2) \big)\\
        &=\! \sum_{k=2}^{n+1}(\prj{1_{t_1}} \prod_{i=2}^{k-1} (\prj{1_{t_{i}}}) \prj{0_{t_{k}}} \prod_{i=n-(k-1)}^{n-2} (\bev(q,(n+1)-i)\lnSem{s}) \bev(q,2))\\
        &=\! \sum_{k=2}^{n+1}(\prod_{i=1}^{k-1} (\prj{1_{t_{i}}}) \prj{0_{t_{k}}} \prod_{i=n-(k-1)}^{n-2} (\bev(q,(n+1)-i)\lnSem{s}) \bev(q,2)).\\
    \end{aligned}
\end{equation*}   
Secondly, let's consider $\lt'' = \lt' \cdot \lnSem{s} \cdot \bev(q,1)$, it result in:
\begin{equation*}
    \begin{aligned}
        \lt'' &=\! \Big( \sum_{k=2}^{n+1}\prod_{i=1}^{k-1} (\prj{1_{t_{i}}}) \prj{0_{t_{k}}} \prod_{i=n-(k-1)}^{n-2} (\bev(q,(n+1)-i)\lnSem{s}) \bev(q,2) \Big) \lnSem{s}\bev(q,1) =\\
        &=\! \sum_{k=2}^{n+1}\prod_{i=1}^{k-1} (\prj{1_{t_{i}}}) \prj{0_{t_{k}}} \prod_{i=n-(k-1)}^{n-2} (\bev(q,(n+1)-i)\lnSem{s} \big) \bev(q,2) \lnSem{s} \bev(q,1).\\
    \end{aligned}
\end{equation*}


If we consider the second product, we can include $\bev(q,2)\lnSem{s}$ by updating the indices.
Specifically, when $i=n-2$, $n+1-n+2=3$, therefore, by setting $n-1$ as the upper limit of the product, we can include $\bev(q,2)\lnSem{s}$ in the product.
So finally, we can write $\lt''$ as:
\begin{equation*}
    \lt'' = \sum_{k=2}^{n+1}\prod_{i=1}^{k-1} (\prj{1_{t_{i}}}) \prj{0_{t_{k}}} \prod_{i=n-(k-1)}^{n-1} (\bev(q,(n+1)-i)\lnSem{s}) \bev(q,1).
\end{equation*}
Finally, since $\lt_{n+1} = \prj{0_{t_1}} \bev(q,1) + \lt''$ and $(\prod_{i=1}^{k-1} (\prj{1_{t_{i}}}) \prj{0_{t_{k}}} \prod_{i=n-(k-1)}^{n-1} (\bev(q,(n+1)-i)\lnSem{s}) \bev(q,1))_{k=1} = \prj{0_{t_1}} \cdot \bev(q,1)$ we can write:
\begin{equation*}
    \lt_{n+1} = \sum_{k=1}^{n+1}\prod_{i=1}^{k-1} (\prj{1_{t_{i}}}) \prj{0_{t_{k}}} \prod_{i=(n+1)-k}^{n-1} (\bev(q,(n+1)-i)\lnSem{s}) \bev(q,1),
\end{equation*}
i.e., we have writen $\lt_{n+1}$ in the form of \autoref{eq: Lnclose}.

\end{proof}


