\begin{figure}
    \centering
    \begin{minipage}{.47\textwidth}
        \centering
    \begin{lstlisting}[language=Rust]
    // Rust
    fn try_fold<B, F, R>(&mut self, 
                         init: B, mut f: F) 
       -> ControlFlow<R, B>
    where F: FnMut(B, Self::I, Self::V) 
             -> ControlFlow<R, B>,
    {
        let mut acc = init;
        while self.valid() {
            if self.ready() {
                let i = self.index();
                let v = self.value();
                self.next();
                acc = f(acc, i, v)?;
            } else {
                self.next();
