        \begin{lstlisting}
    // Morphic
    pub fold(f: (m,k,v) -> m, 
             s: Stream k v, acc: m): m =
        let Stream(valid, index, seek, 
                   ready, value) = s in
        if valid() {
          let r = ready() in
          let i = index() in
          let acc_ = if r { 
              f(acc, i, value()) 
            } else { acc } in
          fold(f, seek(i, r), acc_)
        } else {
          acc
        }
