\section{Preliminaries}
\label{sec:preliminaties}
\begin{definition}[Differential rings and ideals]
\begin{itemize}
    \item A \emph{differential ring} $(R, \;')$ is a commutative ring with a derivation $': R \rightarrow R$, that is, a map such that, for all $a,b \in R$, $(a+b)' = a' +b'$ and $(ab)' = a'b + ab'$.  
    For $i > 0$, $a^{(i)}$ denotes the $i$-th order derivative of $a \in R$.
   \item A \emph{differential field} is a differential ring which is a field.
   \item Let $R$ be a differential ring. An ideal $I \subset R $ is called a \emph{differential ideal} if $a' \in I$ for every $a \in I$.
\end{itemize}
\end{definition}

For the rest of the paper, $\mathbb{K}$ will be a differential field of characteristic zero.

Let $x$ be an element of a differential ring. 
We denote $x^{(\infty)} := \{x,x',x'',x^{(3)},\ldots\}.$


\begin{definition}[Differential polynomials]
    Let $R$ be a differential ring. Consider a ring of
polynomials in infinitely many variables
\[
R[x^{(\infty)}] := R[x, x', x'', x^{(3)},\ldots]
\]
and extend \cite[§ 9, Prop. 4]{bourbaki1950elements} the derivation from $R$ to this ring by $(x^{(j)})':= x^{(j+1)}$. The resulting differential ring is called the \emph{ring of differential polynomials in $x$ over $R$}.
The ring of differential polynomials in several variables is defined by iterating this construction.
\end{definition}

\begin{notation}
    One can verify that $\ideal{f_1^{(\infty)},\ldots, f_s^{(\infty)}}$ is a differential ideal 
    for every $f_1, \ldots , f_s \in  R[x_1^{(\infty)},\ldots, x_n^{(\infty)}] $. Moreover, this is the minimal differential ideal containing $f_1, \ldots , f_s$,
    and we will denote it by $\ideal{f_1,\ldots, f_s}^{(\infty)}$.
\end{notation}

\begin{notation}[Saturation]
Let $I$ be an ideal in ring $R$, and $a \in R$. Denote
$$
I : a^{\infty} := \{ b \in R\; | \; \exists N \colon\, a^Nb \in I\}.
$$
The set $I : a^{\infty}$  is also an ideal in $R$.
If $I$ is a differential ideal, than $I : a^{\infty}$ is also a differential ideal.
\end{notation} 




 \begin{definition}
    Let $P \in \mathbb{K}[\bx^{(\infty)}]$ be a differential polynomial in $\bx = \tuple{x_1, \ldots, x_n}$.
    \begin{enumerate}
        \item For every $1 \leqslant i \leqslant n$, we will call the largest $j$ such that $x_i^{(j)}$ appears in $P$ the \emph{order} of $P$ 
        respect to $x_i$ and denote it by $\ord_{\!x_i} P$; if $P$ does not involve $x_i$, we set $\ord_{\!x_i} P := -1$.

        \item For every $1 \leqslant i \leqslant n$ such that $x_i$ appears in $P$, the \emph{initial} of $P$ with respect to $x_i$ is the
        leading coefficient of $P$ considered as a univariate polynomial in $x_i^{(\ord_{\!x_i} P)}$. 
        We denote it by $\init_{\!x_i} P$.

        \item The \emph{separant} of $P$ with respect to $x_i$ is
        $$
        \sep_{\!x_i} P := \dfrac{\partial P}{\partial x_{i}^{(\ord_{\!x_i} P)}} .
        $$
    \end{enumerate}
    \end{definition}

    \begin{notation}\label{not:Ifg}
          Consider an ODE system (in the \emph{state-space form}): 
          \begin{equation}\label{eq:ode_main}
          \bx' = \bg(\bmu, \bx), \quad y = f(\bmu, \bx),
          \end{equation}
          where $\bx = [x_1, \ldots, x_n]^T$, $\bmu = [\mu_1, \ldots, \mu_r]^T$, $g_1, \ldots, g_n, f \in \mathbb{K}[ \bmu, \bx]$.
          These differential equations can be viewed as differential polynomials in the differential polynomial ring $\mathbb{K}[\bmu, \bx^{(\infty)}, y^{(\infty)}]$ over a differential ring $\mathbb{K}[\bmu]$ (equipped with derivation via $\bmu' = 0$).
          The differential ideal $(\bx - \bg, y - f)^{(\infty)} \in \mathbb{K}[\bmu, \bx^{(\infty)}, y^{(\infty)}]$ describing the solutions of this system will be denoted by $I_{\bg, f}$.
    \end{notation}

    By~\cite{Moog1990} (see also~\cite[Lemma~3.2]{hong2020global}), the ideal $I_{\bg, f}$ is prime.
    The elimination problem we study in this paper is, for a system~\eqref{eq:ode_main}, to eliminate all the $\bx$-variables. 
    In other words, we want to describe a differential ideal
	\begin{equation} \label{id}
		I = I_{\bg, f} \cap \mathbb{K}[\bmu, y^{(\infty)}].
	\end{equation}
    Since $I_{\bg, f}$ is prime, the elimination ideal is prime as well.

    \begin{definition}[Minimal polynomial]\label{not:minpoly}
        The \emph{minimal polynomial} $f_{\min}$ of the prime ideal~\eqref{id} is a polynomial in~\eqref{id} of the minimal order and then the minimal total degree.
        It is unique up to a constant factor \cite[Proposition 1.27]{pogudin2023differential}.
    \end{definition}

    \begin{proposition}[{{\cite[Proposition~1.15]{pogudin2023differential}}}]\label{prop::idealstructure} 
        The prime ideal~\eqref{id} is uniquely determined by its minimal polynomial $f_{\min}$. %(polynomials are compared first w.r.t. the order and then w.r.t. the total degree).
        More precisely:
        \begin{equation*} \label{diff_ideal}
            I = \ideal{f_{\min}}^{(\infty)} : (\sep_{\!y}(f_{\min}) \,\init_{\!y}(f_{\min}))^{\infty}.
        \end{equation*}
    \end{proposition}

\begin{example}
For a simple example of such representation consider the elimination problem for the following model with parameters $\mu_1$ and $\mu_2$:
\[ x'_1 = \mu_1 x_2, \quad x'_2 = \mu_2 x_1, \quad y = x_1 + x_2. \]
$f_{\min}$ can be obtained via double differentiation: 
\[ (y - (x_1 + x_2))'' = (y' - \mu_1 x_2 - \mu_2 x_1)' = y'' - \mu_1 \mu_2 (x_1 + x_2) = y'' - \mu_1 \mu_2 y.\] Thus, $f_{\min} = y'' - \mu_1 \mu_2 y$.

\end{example}

\begin{example}[Closure properties of D-algebraic functions]\label{ex:dalg_functions}
    Consider the tangent $\tan (t)$ and hyperbolic tangent $\tanh(t)$ functions. 
    They both are known to satisfy first-order differential equations $\tan'(t) = 1 + \tan^2(t)$ and $\tanh'(t) = 1 - \tanh^2(t)$ (in other words, they are \emph{D-algebraic}).
    We can now, following~\cite{AitElManssour2025,TeguiaTabuguia2025}, find a differential equation satisfied, for example, by their product $\tan(t) \tanh(t)$ by considering the elimination problem for the following model:
    \[
    x_1' = 1 + x_1^2, \quad x_2' = 1 - x_2^2, \quad y = x_1 x_2.
    \]
    The triple $(x_1, x_2, y) = (\tan(t), \tanh(t), \tan(t) \tanh(t))$ is a solution of this system.
    A computation using any differential elimination algorithm (in particular, the one we describe in Section~\ref{sec:algorithm}) shows that the minimal differential equation satisfied by the $y$-component of every solution (and, thus, vanishing at $\tan(t) \tanh(t)$) is:
    \[
    y^6 - y^4 y'' + y^4 + 2 y^3 (y')^2 + \frac{1}{4}(y^2 - 1) (y'')^2 - y^2 - y (y')^2 y'' - 2 y (y')^2 + (y')^4 + y''_2 - 1 = 0.
    \]
\end{example}

