\section{Main Result}
\label{sec:main}

\begin{theorem} \label{th::bound-param}
  Let $f, g_1, \ldots, g_n$ be polynomials in $\mathbb{K}[\mu_1, \ldots, \mu_r, x_1, \ldots, x_n] = \mathbb{K}[\bmu, \bx]$.
   Denote
   \[
   d_\alpha := \deg_{\alpha} f\quad \text{ and }\quad D_\alpha := \max_{1 \leqslant i \leqslant n} \deg_{\alpha} g_i \quad\text{ for } \alpha = \bmu \text{ or } \alpha = \bx,
   \]
   and assume that $d_x, D_x > 0$.
   Let $f_{\min}$ be the minimal polynomial of $I_{\bg, f} \cap \mathbb{K}[\bmu, y^{(\infty)}]$ (see Notation~\ref{not:Ifg} and~\ref{not:minpoly}).

  Consider a positive integer $\nu$ such that $\ord f_{\min} \leqslant \nu$ ($\nu = n$ can always be used).
  Then for every monomial $\left(\prod\limits_{i=1}^{r} \mu_i^{\ell_i}\right) y^{e_0} (y')^{e_1} \ldots (y^{(\nu)})^{e_{\nu}}$ in $f_{\min}$
  the following inequalities hold:
  \begin{align} 
    \label{eq::bound_multi} & \sum\limits_{i=0}^{r} \ell_i + \sum\limits_{i=0}^{\nu}(d_{\mu} + i D_{\mu}) e_i \leqslant \sum\limits_{i=0}^{\nu}(d_{\mu} + i D_{\mu}) 
      \prod\limits_{j = 0, j \neq i}^{\nu}(d_x + j(D_x-1)), \\
    \label{eq::bound_bezout_global}& \sum\limits_{i=0}^{r} \ell_i + \sum\limits_{i=0}^{\nu}(d_x + i(D_x-1) ) e_i \leqslant
      \prod_{i=0}^{\nu}( d_x + d_{\mu} + i(D_x + D_{\mu} - 1)),\\
    \label{eq::bezout_y_only}&  \sum\limits_{i=0}^{\nu}(d_x + i(D_x-1) ) e_i \leqslant
      \prod\limits_{i = 0}^{\nu}(d_x + i(D_x - 1)).
  \end{align}

  % + Bezeaut bound? (no!)
  % \begin{equation}
  %   \sum\limits_{i=0}^{r} \ell_i + \sum\limits_{i=0}^{\nu}(d + i (D-1)) e_i \leqslant \sum\limits_{i=0}^{\nu}(d_{\mu} + i D_{\mu}) 
  %     \prod\limits_{j = 0, j \neq i}^{\nu}(d + j(D-1)).
  % \end{equation}

\end{theorem} 

\begin{corollary} \label{cor::bound}
  Let $f, g_1, \ldots, g_n$ be polynomials in $\mathbb{K}[x_1, \ldots, x_n] = \mathbb{K}[\bx]$
  such that $d := \deg f > 0$ and $D := \max_{1 \leqslant i \leqslant n} \deg g_i > 0$.
  Let $f_{\min}$ be the minimal polynomial of $I_{\bg, f} \cap \mathbb{K}[y^{(\infty)}]$ (see Notation~\ref{not:Ifg} and~\ref{not:minpoly}).
  Consider a positive integer $\nu$ such that $\ord f_{\min} \leqslant \nu$ ($\nu = n$ can always be used).
  Then for every monomial $y^{e_0} (y')^{e_1} \ldots (y^{(\nu)})^{e_{\nu}}$ in $f_{\min}$ the following inequality holds:
  \begin{equation}
    \sum\limits_{k=0}^{\nu}\bigl( d + k(D-1)\bigr)e_k \leqslant \prod\limits_{k=0}^{\nu}(d + k(D-1)).
  \end{equation}
\end{corollary}

\begin{proof}(Corollary~\ref{cor::bound})
Corollary~\ref{cor::bound} is a special case of Theorem \ref{th::bound-param}, obtained by setting $r = 0$ and $d_{\mu} = D_{\mu} = 0$.
\end{proof}

\section{Experimental results}\label{sec:experimental}

In this section, we report the results of computational experiments aiming at evaluating the bounds given by Theorem~\ref{th::bound-param} and Corollary~\ref{cor::bound}.
For each of the experiments, we fixed some values (in the notation of Theorem~\ref{th::bound-param}) of $n, |\bmu|, d_x, D_x, d_{\mu}, D_{\mu}$ and generated random dense parametric ODE models $\bx' = \bg(\bmu, \bx), y = f(\bmu, \bx)$ with the corresponding dimensions and degrees by sampling the coefficients uniformly at random from $[-1000, 1000] \cap \mathbb{Z}$.
For each such case, we report the following quantities:
\begin{itemize}
    \item \emph{\# terms in the bound}: the number of integer points inside the Newton polytope predicted by Theorem~\ref{th::bound-param};
    \item \emph{\# terms in the NP of $f_{\min}$}: the number of lattice points in the Newton polytope of the actual minimal polynomial (computed using the algorithm described in Section~\ref{sec:algorithm});
    \item \emph{\# terms in $f_{\min}$}: the number of monomials in the actual minimal polynomial;
    \item \emph{\%}: the ratio between the number of monomials in $f_{\min}$ and the number of monomials in the bound from Theorem~\ref{th::bound-param}. 
\end{itemize}


