\section{Reduction to polynomial elimination}\label{sec:proof1} 
In this section we will explain how we reduce the differential elimination problem 
to a polynomial elimination problem using the approach similar to~\cite{mukhina2025projecting}. 
We will fix some notation used throughout the rest of the paper.

For vectors $\balpha = [\alpha_1, \ldots, \alpha_r]^T \in \mathbb{Z}_{\geqslant 0}^r, \bbeta = [\beta_1, \ldots, \beta_n]^T \in \mathbb{Z}_{\geqslant 0}^n$ we denote
\[ 
    \bmu^{\balpha} \bx^{\bbeta} := \prod\limits_{i = 1}^r \mu_i^{\alpha_i} \prod_{j = 1}^n x_j^{\beta_j}, \quad |\balpha| := \sum_{i=1}^r \alpha_i \text{ and } |\bbeta| := \sum_{i=1}^n \beta_i.
\]

In the present paper, we consider an ODE system with parameters
\begin{equation} \label{eq::ODE-1}
  \bx' = \bg(\bmu, \bx) \text{ with } \bx = [x_1, \ldots, x_n]^T, \bmu = [\mu_1, \ldots, \mu_r]^T, g_1, \ldots, g_n \in \mathbb{K}[
  \bmu, \bx],
\end{equation}
and the problem of finding a differential equation for 
\begin{equation} \label{eq::ODE-2}
  y = f(\bmu, \bx).
\end{equation}


\begin{notation} \label{not::LieOperator}
  Consider a polynomial vector field $ \bx' = \bg(\bmu, \bx)$ with  $\bx = [x_1, \ldots, x_n]^T$, $\bmu = [\mu_1, \ldots, \mu_r]^T$, $g_1, \ldots, g_n \in \mathbb{K}[\bmu, \bx]$.
  \begin{itemize}
     \item  For a polynomial $q := \sum\limits_{\balpha, \bbeta} k_{\balpha, \bbeta}  \bmu^{\balpha} \bx^{\bbeta} \in \mathbb{K}[\bmu, \bx]$ with $k_{\balpha} \in \mathbb{K}$, we denote $q^{\partial} := \sum\limits_{\balpha, \bbeta} k_{\balpha, \bbeta}'  \bmu^{\balpha} \bx^{\bbeta}$.
    \item We denote the Lie derivative operator $\mathcal{L}_{\bg} \colon \mathbb{K}[\bmu, \bx] \mapsto \mathbb{K}[\bmu, \bx]$
  by $\mathcal{L}_{\bg}(q) := \sum\limits_{i=1}^n g_i \dfrac{\partial q}{\partial x_i} + q^{\partial}.$
  \end{itemize}
\end{notation}


\begin{lemma}[{{cf.~\cite[Lemma~1]{mukhina2025projecting}}}] \label{lem::ideal-equivalence}
  For the system \eqref{eq::ODE-1}-\eqref{eq::ODE-2} for every $s \geqslant 0$:
  \[ 
  (y - f, y - \mathcal{L}_{\bg}(f), \ldots, y^{(s)} - \mathcal{L}^s_{\bg}(f)) = 
  I_{\bg, f} \cap \mathbb{K}[\bmu, \bx, y^{(\leqslant s)}].
  \]
\end{lemma}
\begin{proof}
  We denote 
  \[ J :=  (y - f, y - \mathcal{L}_{\bg}(f), \ldots, y^{(s)} - \mathcal{L}^s_{\bg}(f)). \]
  and 
  \[ I := I_{\bg, f} \cap \mathbb{K}[\bmu, \bx, y^{(\leqslant s)}]. \]
  First, we prove that for every $0 \leqslant k \leqslant s$, we have $y^{(k)} - \mathcal{L}_{\bg}^{(k)} \in I$.
  We show this via induction on $k$. For the base case $k = 0$, we have $y - f \in I$. By the induction hypothesis
  for some $0 \leqslant k \leqslant s-1$ we have $p := y^{(k)} - \mathcal{L}^{k}_{\bg}(f) \in I$.
  We note that $p' \in I$ and $p' = y^{(k+1)} - \sum_{i=1}^n x_i' \frac{\partial}{\partial x_i} \mathcal{L}_{\bg}^k(f) - (\mathcal{L}_{\bg}^k(f))^{\partial}$. 
  Since $x'_i \equiv g_i \pmod I$, we get $p' = y^{(k+1)} - \mathcal{L}_{\bg}^{k+1}(f) \in I$.
  Hence, all generators of the ideal $J$ belong to $I$, so $J \subset I$.

  For the reverse inclusion, we assume the contradiction. 
  Let $p$ be a polynomial in the ideal $I$ such that $p \notin J$.
  We fix the monomial ordering on $\mathbb{K}[\bmu, \bx, y^{(\leqslant s)}]$ to be the lexicographic monomial
  ordering with
  \[ 
  y^{(s)} > y^{(s-1)} > \ldots > y > x_1 > x_2 > \ldots > x_n > \mu_1 \ldots > \mu_r.
  \]
  The leading term of $y^{(i)} - \mathcal{L}_{\bg}^i(f)$ is $y^{(i)}$, so the leading terms of all generators of $J$ are distinct variables.
  Hence this set is a Gr\"obner basis of $J$ by the first Buchberger criterion~\cite{buchberger1979criterion}. 
  The result of the reduction of $p$ with respect to 
  the Gr\"obner basis belongs to $\mathbb{K}[\bmu, \bx]$ and is distinct from zero. 
  Thus, we get a contradiction 
  with $p \in I$ because $I \cap \mathbb{K}[\bmu, \bx] = {0}$ by \cite[Lemmas 3.1 and 3.2]{hong2020global}.
\end{proof}

\begin{corollary}
 The minimal differential polynomial $f_{\min}$ in $I_{\bg, f} \cap \mathbb{K}[\bmu, y^{(\infty)}]$ with $s := \ord f_{\min}$ is the generator of the
   principal ideal $(y - f, y' - \mathcal{L}_{\bg}(f), \ldots, y^{(s)} - \mathcal{L}_{\bg}^s(f)) \cap \mathbb{K}[\bmu, y^{(\infty)}]$.
\end{corollary}



\begin{lemma} \label{lem::monom-bound-param}
  For every monomial $\bmu^{\balpha} \bx^{\bbeta}$ and every monomial $ \bmu^{\tilde{\balpha}} \bx^{\tilde{\bbeta}}\in 
  \mathcal{L}_{\bg}(\bmu^{\balpha}\bx^{\bbeta})$
  the following inequalities hold:
  \[ |\tilde{\balpha}| \leqslant |\balpha| + D_{\mu} \quad \text{ and } \quad |\tilde{\bbeta}| \leqslant |\bbeta| + D_x - 1.\]
\end{lemma}

\begin{proof}
 Since $\mathcal{L}_{\bg}(\bmu^{\balpha} \bx^{\bbeta}) = \bmu^{\balpha} \sum\limits_{i=1}^n g_i \frac{\partial}{\partial x_i} \bx^{\bbeta}$, 
 then $\bmu^{\tilde{\balpha}} \bx^{\tilde{\bbeta}} = \bmu^{\balpha} m \frac{\partial}{\partial x_i} \bx^{\bbeta}$ 
 for some $1 \leqslant i \leqslant n$ 
 and some monomial $m$ in $g_i$. So, $|\tilde{\balpha}| \leqslant |\balpha| + D_{\mu}$ and $|\tilde{\bbeta}| \leqslant |\bbeta| + D_x - 1$.
\end{proof}


\begin{corollary} \label{cor::monom-bound-param}
 For every monomial $\bmu^{\balpha} \bx^{\bbeta}$ in $\mathcal{L}_{\bg}^{i}(f)$, the following inequalities hold:
 \[ |\balpha| \leqslant d_{\mu} + i D_{\mu} \quad \text{ and } \quad |\bbeta| \leqslant d_x + i(D_x - 1).\]
\end{corollary}
\begin{proof}
 The corollary follows by an $i$-fold application of Lemma~\ref{lem::monom-bound-param} to the polynomial $f$ of degree $d_{\mu}$ in variables $\bmu$
 and degree $d_x$ in variables $\bx$.
\end{proof}

\section{Auxiliary facts from algebraic geometry}

\begin{lemma} \label{lem:dominate}
  Let $m,n$ and $k$ be positive integers such that $n = m+k$. Let
  $X \subset \mathbb{A}^{n} = \mathbb{A}^m \times \mathbb{A}^k$ be an
 equidimensional variety of dimension $D$ and let
  $\pi : \mathbb{A}^{n} \rightarrow \mathbb{A}^{k}$ be the projection onto the
  last $k$ coordinates. 
  Denote $Y := \overline{\pi(X)}$ and suppose that $Y$
  is equidimensional of dimension $d \leqslant D$. 
  Then, for a general affine space
  $L$ in $\mathbb{A}^m$ of codimension $D - d$, we have that $X \cap L$
  projects dominantly to $Y$ and $\dim (X \cap L) = \dim Y$.
\end{lemma}

\begin{proof}
  We work by induction over the quantity $D-d$, if $D = d$ there is nothing to prove. 

  Choose an irreducible component $Z$ of $Y$ and an irreducible
  component $W$ of $X$ projecting dominantly to $Z$. 
  By \cite[Theorem
  1.25(ii)]{shafarevich1994basic} there is
  an open subset $U$ of $Z$ such that for all $\by^{\ast}\in U$ we have
  $\dim(\pi^{-1}(\by^{\ast})\cap W) = D - d$. 
  Viewing
  $\pi^{-1}(\by^{\ast}) \cap W$ as a variety in $\mathbb{A}^m$, for a
  hyperplane $H$ in $\mathbb{A}^m$ chosen from an open subset $\widetilde{U}$ of
  all hyperplanes in $\mathbb{A}^m$ we have that $H$ intersects
  $\pi^{-1}(\by^{\ast}) \cap W$ transversally so that
  $\dim(\pi^{-1}(\by^{\ast}) \cap W\cap H) = D - d - 1$. In particular there is
  $\bx^{\ast}\in W$ such that $H(\bx^{\ast})\neq 0$. Since $W$ is irreducible
  this implies that $W\cap H$ is equidimensional of dimension $D-1$. This implies, using the theorem of
  dimension of base and fiber \cite[Theorem 10.10]{eisenbudCommutativeAlgebra1995}, that we have
  \[
  \dim(\pi(W\cap H)) \geqslant \dim(W\cap H) - \dim(\pi^{-1}(\by^{\ast}) \cap W\cap H) = (D - 1) - (D - d - 1) = d.
  \]
  Hence, by the irreducibility of $Z$, $\pi(W\cap H)$ is
  dense in $Z$. 
  Potentially shrinking the open subset $\widetilde{U}$ out of which
  $H$ is chosen, these assertions hold simultaneously for all
  irreducible components $W$ of $X$ projecting dominantly to $Z$ with
  the same choice of $H\in \widetilde{U}$. 
  Potentially shrinking $\widetilde{U}$ further, these
  assertions hold simultaneously for all irreducible components $W$ of $X$ that project dominantly to some component of $Y$ with the same choice of $H\in \widetilde{U}$.

  In order to ensure the dimensionality drop on the whole $X$, we
  choose a point $\bx^{\ast}_{W}\in W$ for each $W$ an irreducible component of $X$ that does not project
  dominantly to some irreducible component of $Y$. 
  After potentially shrinking
  $\widetilde{U}$ we have $H(\bx^{\ast}_{W})\neq 0$ for all $H\in \widetilde{U}$ and all such $W$. 
  By construction, for each component $W$ of $X$ either $H$ intersects $W$ transversally or $W\cap H= \emptyset$. 
  This implies that $X\cap H$ is equidimensional of dimension $D - 1$
  and projects dominantly to $Y$. 
  We now conclude using the induction
  hypothesis, replacing $X$ with $X\cap H$.
\end{proof}

\begin{lemma}
\label{lem:fiberdim}
  Let $m,n$ and $k$ be positive integers such that $n = m+k$. Let
  $X \subset \mathbb{A}^{n} = \mathbb{A}^m \times \mathbb{A}^k$ be a
 variety of dimension $d$ and let
  $\pi : \mathbb{A}^{n} \rightarrow \mathbb{A}^{k}$ be the projection onto the
  last $k$ coordinates. 
  Denote $Y := \overline{\pi(X)}$ and suppose that $Y$
  is equidimensional of dimension $d$. 
  Then there is a Zariski open dense subset $U$ of $Y$
  such that for all $\by^{\ast}\in U$ we have that the fiber $\pi^{-1}(\by^{\ast})\cap X $ is finite and non-empty.
\end{lemma}

\begin{proof}
Without loss of
  generality, we may replace $X$ by the union $X'$ of all irreducible
  components of $X$ that project dominantly to some irreducible
  component of $Y$. Indeed, for a general $\by^{\ast}\in Y$ we have
  $\pi^{-1}(\by^{\ast})\cap X = \pi^{-1}(\by^{\ast})\cap X'$.

  Let $Z$ be an irreducible component of $Y$. Each irreducible
  component $W$ of $X$ projecting dominantly to $Z$ necessarily has dimension $D$, and so by \cite[Theorem
  1.25(ii)]{shafarevich1994basic}, there is an open subset $U_W$ of
  $Z$ such that for every $\by^{\ast}\in U_W$ we have
  $\dim(\pi^{-1}(\by^{\ast}) \cap W) = 0$. After possible shrinking $U_W$ the fiber $\pi^{-1}(\by^{\ast}) \cap W$ is in addition non-empty by \cite[Lemma~4.3(i)]{hong2020global}.
  Let $U_Z$ be the intersection
  of all such $U_W$. We then have
  $\dim(\pi^{-1}(\by^{\ast}) \cap X) = 0$ for all
  $\by^{\ast}\in U_Z$. Taking the union over all $U_Z$, with $Z$ running
  over the irreducible components of $Y$, we obtain a dense open
  subset $U$ of $Y$ such that for every $ \by^{*}\in U$ we have
  $\dim(\pi^{-1}(\by^{\ast}) \cap X) = 0$ for all $\by^{\ast}\in U$ and $\pi^{-1}(\by^{\ast}) \cap X$ is non-empty.
\end{proof}

\begin{definition}
    For a polynomial $f(\mathbf{x}) \in \mathbb{K}[x_1, \ldots, x_m]$ of degree $d$, we define its \emph{homogenisation in $\mathbf{x}$} using an additional variable $z$ as
	\begin{equation*}
			f^h(x_1, \ldots, x_m, z) := z^{d} f(\dfrac{x_1}{z}, \ldots, \dfrac{x_m}{z}). 
	\end{equation*}
\end{definition}

\begin{lemma} \label{lem::degree-new} Let $m$, $k$ be positive
  integers and $\bx = [x_1, \ldots, x_{m}]^T$,
  $\by = [y_1, \ldots, y_{k}]^T$. 
  Denote by $\pi_{\by}$ the projection map
  corresponding to the inclusion
  $\mathbb{K}[\by]\hookrightarrow \mathbb{K}[\bx,\by]$. 
  Let
  $p_1, \ldots, p_{m+1}$ be polynomials in $\mathbb{K}[\bx, \by]$ such that
  $\deg_{\bx} p_i = d_{ix} \in \mathbb{Z}_{> 0}$ and
  $\deg_{\by} p_i = d_{iy} \in \mathbb{Z}_{\geqslant 0}$.  Suppose in adddition that the ideal 
  $I:=(p_1,\dots,p_{m+1})$ has dimension $k-1$, suppose that
  $I \cap \mathbb{K}[\by] = (g)$ for some square-free $g\in \mathbb{K}[\by]$.

  Then,
  \begin{equation} \label{eq::mult-bound-new}
    \deg g \leqslant \sum_{i=1}^{m + 1} d_{iy} \prod\limits_{j=1, j \neq i}^{m+1} d_{ix}. 
  \end{equation}
\end{lemma}

\begin{proof}
Let $X = \mathbb{V}(I)$. 
Denote by $\pi_{\by}\colon \mathbb{A}^{m + k} \to \mathbb{A}^k$ the projection map
  corresponding to the inclusion
  $\mathbb{K}[\by]\hookrightarrow \mathbb{K}[\bx,\by]$. 
We will find an affine line $L$ in $\mathbb{A}^k$ such that
\begin{align*}
  (1)& \quad \forall \by^\ast \in L \cap \mathbb{V}(g)\colon \pi_{\by}^{-1}(\by^{\ast}) \cap X \text{ is finite and nonempty},\\
  (2) & \quad \# (L \cap \mathbb{V}(g)) = \deg g.
\end{align*}
We note that $\pi(X) = \mathbb{V}(I \cap \mathbb{K}[\by]) = \mathbb{V}(g)$, 
so $\pi(X)$ is equidimentional of dimention $k - 1$. By Lemma~\ref{lem:fiberdim} there exists a Zariski open dence subset $U$
of $\pi(X)$ such that for all $\by^{\ast} \in U$ the fiber $\pi^{-1}(\by^{\ast}) \cap \mathbb{V}(I)$
is finite and non-empty.

Since $g$ is a nonzero square-free polynomial, by \cite[ Chapter 9, \S 4, Exercise~12]{cox1997ideals} the second property is true for a generic $L$ (that is, it holds on a nonempty open subset in the set of lines).
After possibly shrinking this open subset of lines, $L$ intersects $\mathbb{V}(g)$ only in $U$ and so the first property holds as well. 

Fix one such $L$.
Due to the finiteness and nonemptyness of the fibers, the set $L \cap \mathbb{V}(I)$ is finite and its cardinality is at least $\#(L \cap \mathbb{V}(g)) = \deg g$. 
The cardinality of $L \cap \mathbb{V}(I)$ is bounded by the number
of isolated solutions of the bihomogeneous
systems of equations consisting of $p_1^h=0,\dots,p_{m+1}^h=0$, where $\bullet^h$ denotes bihomogenization with respect to the variables $\bx$ and $\by$, and the homogenized (only in $\by$) defining equations of $L$. 
This number is in turn bounded by the multi-homogeneous B\'ezout bound associated to this system \cite[p. 106]{morgan1987homotopy}. 
Thus, we have  
\[
  \deg g = \#(L \cap \mathbb{V}(g)) \leqslant \coeff_{v^{m} u^{k}} P(u, v),
\]
 where $P(v, u) = u^{k-1}\prod\limits_{i=1}^{m+1} (d_{ix} v + d_{iy} u )$.
To find the coefficient that corresponds to the monomial $v^{m} u^{k}$ we choose exactly $m$ of $m + 1$ factors in the product of linear forms
to contribute the term $d_{ix} v$ and the remaining one to contribute the term $d_{iy} u$. 
This gives the desired
\[ 
\deg g = \#(\mathbb{V}(g) \cap L)\leqslant \sum_{i=1}^{m + 1} d_{iy} \prod\limits_{j=1, j \neq i}^{m+1} d_{ix}.
\]
\end{proof}

\section{Proof of the bound}\label{sec:proof2}


\begin{proof}[Theorem~\ref{th::bound-param}]
  Let us denote by $\nu$ the order of the minimal polynomial $f_{\min}$ and recall that $\nu \leqslant n$ by~\cite[Theorem 3.16 and Corollary 3.21]{hong2020global}.
  By Lemma~\ref{lem::ideal-equivalence}, we get 
  \[ 
  J := (y - f, y' - \mathcal{L}_{\bg}(f) \ldots, y^{(\nu)} - \mathcal{L}_{\bg}^{\nu}(f)) \cap \mathbb{K}[\bmu, y^{(\leqslant \nu)}] = I_{\bg, f} \cap \mathbb{K}[\bmu, y^{(\leqslant \nu)}] 
  \]
  and $I_{\bg, f} \cap \mathbb{K}[\bmu, y^{(\leqslant \nu)}] = (f_{\min})$. Thus, the ideal $J = (f_{\min})$
  is prime and principal.

 Consider some $[\omega_1, \dots, \omega_{\nu}]^T \in \mathbb{Z}_{\geqslant 0}^{\nu}$ (to be specified later) and  define a homomorphism $\varphi : \mathbb{K}[\bmu,\bx,  y^{(\leqslant \nu)}] \mapsto \mathbb{K}[\bmu,\bx, z_0, z_1, \ldots, z_{\nu}]$, such that
  \begin{align*}
    \mu_i & \mapsto \mu_i, \\
    x_i & \mapsto x_i, \\
    y^{(i)} & \mapsto p_i(z_i), \; p_i \in \mathbb{K}[z_i] \text{ and }\deg p_i(z_i) = \omega_i.
  \end{align*}
  According to~\cite[Lemma~4]{mukhina2025projecting} we can choose $p_i$ such that $\tilde{f}_{\min} := \varphi(f_{\min})$ is square-free.
  We define $\tilde{f}_i := \varphi(y^{(i)} - \mathcal{L}_{\bg}^{i}(f))$ for $0 \leqslant i \leqslant \nu$. 
  By Corollary~\ref{cor::monom-bound-param} for every $0 \leqslant i \leqslant \nu$ we have  $\deg_{ \bmu} \mathcal{L}_{\bg}^{i}(f) \leqslant d_{\mu} + i D_{\mu}$ and $\deg_{\bx} \mathcal{L}_{\bg}^{i}(f) \leqslant d_x + i(D_x-1).$
  Thus, 
  \[ \deg_{\by} \tilde{f}_k \leqslant \omega_k,\;\; \deg_{\bmu} \tilde{f}_k  \leqslant d_{\mu} + k D_{\mu}\; \text{ and } \;\deg_{ \bx} \tilde{f}_k  \leqslant  d_x + (k -1) D_x.\]

The rest of the proof will be divided into three cases corresponding to different inequalities among~\eqref{eq::bound_multi}-\eqref{eq::bezout_y_only}.     
    \paragraph{Case 1.} Let $\omega_i = d_{\mu} + i D_{\mu}$ for $i = 1, \ldots, \nu$. 
    Then, $\deg_{\bmu, \by} \tilde{f}_k \leqslant d_{\mu} + k D_{\mu}$.

    Consider the ideal $\tilde{I} := (\tilde{f}_0, \ldots, \tilde{f}_{\nu})$.
    We fix the monomial ordering on $\mathbb{K}[\bmu, \bx, \bz]$ to be the lexicographic monomial ordering with 
      \[ z_{\nu} > \ldots > z_1 > z_0 > x_n > \ldots > x_1 > \mu_1 > \ldots > \mu_{r}.\]
    Then $\initial(\tilde{f}_i) = c_i z_i^{\omega_i}$ for some $c_i \in \mathbb{K}$ and
    $\initial(\tilde{f}_0), \ldots, \initial(\tilde{f}_{\nu})$ form a regular sequence. 
    Thus, by \cite[Pr.~15.15]{eisenbudCommutativeAlgebra1995} $\tilde{f}_0, \ldots, \tilde{f}_{\nu}$
    form a regular sequence as well.  
    Since $\tilde{f}_0, \ldots, \tilde{f}_{\nu}$ is a regular sequence, 
     $\dim \tilde{I} = 2 n + r - \nu$ and the ideal $\tilde{I}$ is equidimensional.
    We denote by $\pi : \mathbb{A}^{2n + r + 1} \rightarrow \mathbb{A}^{n+r+1}$ the projection onto $[\bmu, \bz]^T$
    coordinates and let $Y := \pi(\mathbb{V}(\tilde{I})) = \mathbb{V}(\tilde{I} \cap \mathbb{K}[\bmu, \bz]) =  \mathbb{V}(\tilde{f}_{\min})$.
    Then $Y$ is equidimensional of dimension $n + r$.
    By Lemma~\ref{lem:dominate} for a general affine space $L$ in $\mathbb{A}^{n}$ of codimension $n - \nu$, the projection of
    $\mathbb{V}(\tilde{I}) \cap L$ to $Y$ is dominant and $\dim (\mathbb{V}(\tilde{I}) \cap L) = \dim Y = n + r$. 
    We can rewrite $L$ as $\mathbb{V}(h_1, \ldots, h_{n-\nu})$ for some polynomials $h_i$ in $\mathbb{K}[\bx]$ of degree one.
    Thus, the ideal $\tilde{I} + I(L) = (\tilde{f}_0, \ldots, \tilde{f}_{\nu}, h_1, \ldots, h_{n-\nu})$
    has dimension $n + r$.
    Applying  Lemma~\ref{lem::degree-new}
     with $p_i = \tilde{f}_i$ for $0 \leqslant i \leqslant \nu$, $p_{\nu + j} = h_j$ for $1 \leqslant j \leqslant n - \nu$
    with the two sets of variables $G_1 = [\bx]$ and $G_2 = [\bmu, \bz]^T$, we obtain
  \[
  \deg \tilde{f}_{\min} \leqslant
  \sum\limits_{i=0}^{n + 1}d_{iy} \prod\limits_{j = 0, j \neq i}^{n + 1}d_{ix},
  \]
  here $d_{iy} = \deg_{\bmu, \bz} p_i$ and $d_{ix} = \deg_{\bx} p_i$. 
  We note that
  \[
    d_{iy} = \begin{cases}
        d_{\mu} + i D_{\mu}, \text{ for } 0 \leqslant i \leqslant \nu,\\
        0, \text{ for } i > \nu
    \end{cases}\quad\text{ and }\quad
    d_{ix} = \begin{cases}
        d_{x} + i (D_{x} - 1), \text{ for } 0 \leqslant i \leqslant \nu,\\
        1, \text{ for } i > \nu
    \end{cases}
  \]
  Hence, we have
  \[
  \deg \tilde{f}_{\min} \leqslant
  \sum\limits_{i=0}^{\nu}(d_{\mu} + i D_{\mu}) \prod\limits_{j = 0, j \neq i}^{\nu}(d_x + j(D_x-1)).
  \]
  By applying the homomorphism $\varphi$ to a monomial $m = \bmu^{\bm{\ell}} y^{e_0} (y')^{e_1} \ldots (y^{(\nu)})^{(e_{\nu})}$ in the support 
  of $f_{\min}$ we get $\varphi(m) = c \bmu^{\bm{\ell}}z_0^{\omega_0 e_0} z_1^{\omega_1 e_1} \ldots z_{\nu}^{\omega_{\nu} e_{\nu}} + q(\bmu, \bz)$
  with $c \in \mathbb{K}^\ast$ and $\deg q < \sum_{i = 1}^{r} \ell_i + \sum_{i=0}^{\nu} \omega_i e_i$. 
  Using the established degree bound for
  $\tilde{f}_{\min}$, we obtain \eqref{eq::bound_multi}:
  \[ \sum_{i = 1}^{r} \ell_i  + \sum_{i=0}^{\nu} \omega_i e_i = \sum_{i = 1}^{r} \ell_i  + \sum_{i=0}^{\nu} (d_{\mu} + i D_{\mu}) e_i \leqslant 
  \sum\limits_{i=0}^{\nu}(d_{\mu} + i D_{\mu}) 
      \prod\limits_{j = 0, j \neq i}^{\nu}(d_x + j(D_x - 1)). \]

     \paragraph{Case 2.} Now we consider $\omega_i = d_x + i (D_x - 1)$. In this case $\deg_{\bmu} \tilde{f}_k \leqslant d_{\mu} + k D_{\mu}$ and $\deg_{\bx, \bz} \tilde{f}_k \leqslant d_x + k (D_x - 1)$ and, thus, the total degree 
     \[
    \deg \tilde{f}_k \leqslant d_x + d_{\mu} + k(D_x + D_{\mu} - 1).
    \]
    Using~\cite[Lemma~5]{mukhina2025projecting} with $p_i = \tilde{f}_i$
  we get $\deg \tilde{f}_{\min} \leqslant \prod_{i=0}^{\nu} \deg \tilde{f}_i$.

  By applying the homomorphism $\varphi$ to a monomial $m = \bmu^{\bm{\ell}} y^{e_0} (y')^{e_1} \ldots (y^{(\nu)})^{(e_{\nu})}$ in the support 
  of $f_{\min}$ we get $\varphi(m) = c \bmu^{\bm{\ell}} z_0^{\omega_0 e_0} z_1^{\omega_1 e_1} \ldots z_{\nu}^{\omega_{\nu} e_{\nu}} + q(\bmu, \bz)$
  with $c \in \mathbb{K}^\ast$ and $\deg q < \sum_{i = 1}^{r} \ell_i + \sum_{i=0}^{\nu} \omega_i e_i$.
  Using the established degree bound for
  $\tilde{f}_{\min}$, we obtain \eqref{eq::bound_bezout_global}:
  \[ \sum_{i = 1}^{r} \ell_i +\sum_{i=0}^{\nu} \omega_i e_i = \sum_{i = 1}^{r} \ell_i + \sum_{i=0}^{\nu} (d_x + i(D_x-1)) e_i \leqslant \prod_{i=0}^{\nu} (d_x + d_{\mu} + i(D_x + D_{\mu} - 1)). \]

  \paragraph{Case 3.} 
  Let us consider the system over field $\mathbb{K}(\bmu)$, that is, the parameters will be a part of the coefficient field.
  Then we can apply the result of the previous case having $r = 0$, $d_{\bmu} = D_{\bmu} = 0$.
  This gives us precisely~\eqref{eq::bezout_y_only}.
\end{proof}


\section{Algorithm}\label{sec:algorithm}

In this section, we show how the bounds from Theorem~\ref{th::bound-param} and Corollary~\ref{cor::bound} can be used to compute the minimal differential equation for $y = f(\bmu, \bx)$ for a system of differential equations of the form
\begin{equation} \label{eq::ODE}
    \bx' = \bg(\bmu, \bx),
\end{equation}
where $\bx = [x_1, \ldots, x_n]^T$, $\bmu = [\mu_1, \ldots, \mu_r]^T$, $\bg \in \KK[\bmu, \bx]^n$, and $f \in \KK[\bmu, \bx]$. 

Our algorithm~\cite[Algorithm 1, 2]{mukhina2025projecting} together with the proofs of the termination and correctness extends straightforwardly to the more general case we consider in this paper once a bound on the support of the output has been established.
Therefore, instead of repeating the formal description of the algorithm and technical details from~\cite{mukhina2025projecting}, we will explain how it works with the new bound on a simple example.


 \begin{algorithmic}[1]
    \Require  A system
    \begin{equation*}
        \begin{cases}
            x_1'  = x_1 + 8 x_2,\\
            x_2'  = 7 x_1 + x_2,\\
            y = x_1 + x_2.
        \end{cases}
    \end{equation*}
    \Ensure the minimal polynomial $f_{\min} \in (x_1' - x_1 - 8 x_2, x_2'  - 7 x_1 - x_2)^{(\infty)} \cap\mathbb{Q}[y^{(\infty)}]$

    \State Compute the order of $f_{\min}$ via $\nu :=  \operatorname{rank}(\frac{\partial}{\partial x_j}\mathcal{L}_{\bg}^{i - 1}(f))_{i, j = 1}^2 = 2$ (see Notation~\ref{not::LieOperator}).

    \State Support $S$ of $f_{\min}$ using Corollary~\ref{cor::bound} and $\nu$: $S := \{1, y, y', y'' \}$.

    \State Make an anzats $f_{\min} = \gamma_1 + \gamma_2 y + \gamma_3 y' + \gamma_4 y''$.

    \State Choose random points $p_1, p_2, p_3, p_4 \in \mathbb{Q}^2$.

    \State Express $y, y'$ and $y''$ via $x_1, x_2$: 
    \[y = x_1 + x_2, \quad y' = x_1' + x_2' = 8 x_1 + 9 x_2, \quad y'' = 8 x_1' + 9 x_2' = 71 x_1 + 73 x_2.\]

    \State Evaluate $y(p_i), y'(p_i), y''(p_i)$ for each $1 \leqslant i \leqslant 4$ and plug in $f_{\min}$.

    \State Solve the resulting linear system
    \[ \begin{pmatrix}
        1& 3 & 26 & 217\\
        1& 11 & 95 & 795\\
        1& 16 & 139 & 1158\\
        1& 12 & 105 & 870\\
        \end{pmatrix}
        \begin{pmatrix}
            \gamma_1\\
            \gamma_2\\
            \gamma_3\\
            \gamma_4
        \end{pmatrix} = 
        \begin{pmatrix}
            0\\
            0\\
            0\\
            0
        \end{pmatrix}
            \]
    The solution space is spanned by $\gamma_1 = 0, \gamma_2 = - 55, \gamma_3 = -2, \gamma_4 = 1$.

   \Return $f_{\min} = -55 y - 2 y' + y''$.
 \end{algorithmic}


\begin{remark}
  If the input system has parameters (i.e. $r \neq 0$), then in Step 2 of our algorithm, we replace the bound from Corollary~\ref{cor::bound} with that from Theorem \ref{th::bound-param}. 
  Moreover, if $r = 0$, and $y$ is equal to one of $\bx$, we instead use the bound given in \cite[Theorem~1]{mukhina2025projecting}.
\end{remark}




\section{Implementation and performance}\label{sec:implementation}

We used the new bounds given by Theorem~\ref{th::bound-param} and Corollary~\ref{cor::bound} as described in Section~\ref{sec:algorithm} to extend the proof-of-concept implementation, DiffMinPoly, of a differential elimination algorithm from~\cite{mukhina2025projecting} (based on Oscar~\cite{OSCAR}, Nemo~\cite{10.1145/3087604.3087611}, and Polymake~\cite{gawrilow2000polymake} libraries) to the larger class of systems considered in this paper. 
The source code and instructions for this new version of software together with the models used in this section are publicly available at

\begin{center}
    \url{https://github.com/ymukhina/Loveandsupport/tree/y-input}
\end{center}

The goal of the present section is to show that this implementation can perform differential elimination in reasonable time on commodity hardware for some instances which are out of reach for the existing state-of-the-art software thus pushing the limits of what can be computed.
Note that we are not aiming here at comprehensive benchmarking of differential elimination algorithms and we have deliberately chosen benchmarks allowing us to highlight the advantages of the present method. We discuss the limitations of our approach at the end of the section.

We will use four sets of models:
\begin{itemize}
    \item \emph{Dense models}.
    For fixed $n, D, d$ we define $\operatorname{Dense}_n(D, d)$
    to be a system of the form $\bx' = \bg(\bx),\;  y = f(\bx)$, where the dimension of $\bx$ is $n$, $f$ is a random dense polynomial of degree $d$ and $g_1, \ldots, g_n$ are random dense polynomials of degree $D$, where the coefficients are sampled independently uniformly at random from $[-100,100]$.
    Here is, for example, an instance of $\operatorname{Dense}_2(1,2)$:
    \begin{align*}
        x_1' &=  - 29 x_1 + 43 x_2 - 5,\\
        x_2' &= 5 x_1 - 87 x_2 - 36,\\
        y &= 32 x_1^2 - 16 x_1 x_2 + 8 x_1 - 92 x_2^2 + 3 x_2 + 67.
    \end{align*}

    \item \emph{$\mu_0$--Dense models}.
    For fixed $n, D_x, d_x, |\bmu|,$ we define $\operatorname{\mu_0--Dense}_n(D_x, d_x, |\bmu|)$ 
    to be a system of the form $\bx' = \bg(\bmu, \bx), \; y = f(\bmu, \bx)$, where 
    \begin{itemize}
        \item the dimension of $\bx$ is $n$;
        \item $f$ is a random dense polynomial with degree $d_x$ in $\bx$ and degree $0$ in $\bmu$;
        \item $g_1, \ldots, g_n$ are random dense polynomials of degree $D_x$ in $\bx$ and degree $1$ in $\bmu$;
        \item all polynomial coefficients are sampled independently uniformly at random from $[-100,100]$.
    \end{itemize}
   For example, an instance of $\operatorname{\mu_0--Dense}_2(1,2,1)$:
    \begin{align*}
        x_1' &= 37 a_1 x_1 - 9 x_1 - 28 a_1 x_2 + 52 x_2 + 73 a_1 - 46,\\
        x_2' &= 69 x_1 a_1 - 43 x_1 - 36 a_1 x_2 + 91 x_2 + 79 a_1 - 69,\\
        y &= 31 x_1^2 - 34 x_1 x_2 + 60 x_1 - 74 x_2^2 + 96 x_2 + 58.
    \end{align*}

    \item \emph{$\mu_1$--Dense models} are defined in the same way as $\mu_0$--Dense models with the only difference that $f$ is of degree 1 in $\bmu$.


    \item \emph{Competing species with nonlinear observations.} 
    We will start with the following parametric model used, for example, to model populational dynamics of competing species:
    \begin{equation}\label{eq:LV}
    \begin{cases}
        x_1' = x_1(a_1 + a_2 x_1 + a_3 x_2),\\
        x_2' = x_2(b_1 + b_2 x_1 + b_3 x_2).
    \end{cases}
    \end{equation}
    We will consider the following test cases involving this model:
    \begin{itemize}
        \item[CS1:] We will take all the parameters except for $a_3$ and $b_2$ (inter-species interaction rates) to be random numbers from $\{\frac{1}{10}, \ldots, \frac{10}{10}\}$ and set $a_3 = -b_2 = a$ to be an unknown parameter.
        The minimal differential equation will be computed for the nonlinear observation function $y = a_2 x_1^2 + b_3 x_2^2$ corresponding to the intra-species interactions.

        \item[CS2-3:] We use the model~\eqref{eq:LV} now with all the parameters to be fixed to random scalars from $\{\frac{1}{10}, \ldots, \frac{10}{10}\}$.
        We will compute minimal differential equation for nonlinear observations following the power law $y = x_1^3 + x_2^2$ for CS2 and $y = x_1^4 + x_2^4$ for CS3.
        We do not claim any biological interpretation for these observation functions, they are used as examples of sparse nonlinear expressions.
    \end{itemize}
\end{itemize}

The specific randomly generated instances used for the experiments can be found in the repository.
For comparison, we used the following software packages allowing to perform (among other things) differential elimination: DifferentialThomas~\cite{bachler2012algorithmic} (part of Maple, we used Maple 2023), DifferentialAlgebra~\cite{diffalg} (written in C++ and Python, we used version 4.1), and StructuralIdentifiability~\cite{Dong2023} (written in Julia, we used version 0.5.12). All computations were performed on a single core of an Apple M2 Pro processor with 32 GB of memory.


