In the exterior region, the metric is given by
\begin{equation}
ds^2 = -\left(1 - \frac{2M}{r} \right) dt^2 + \left(1-\frac{2M}{r} \right)^{-1} dr^2 + r^2 d\Omega^2,
\end{equation}
i.e., it is the Schwarzschild metric with mass $M$.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection*{Shell}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

Within the shell,
\begin{eqnarray}
m_S(r) & = & M_C + \frac{4 \pi}{3} \rho_S (r^3 - R_I^3) , \\
\phi_S(r) & = & A_S + \int \frac{m_S(r) + 4 \pi r^3 P(r)}{r [r-2 m_S(r)]} dr
\end{eqnarray}
with $A_S$ such that 
\begin{equation}
e^{2 \phi_S(R_E)} = \left(1 - \frac{2M}{R_E} \right) 
\end{equation}
and, to ensure continuity of $P(r)$ and $F(r)$ at $R_I$ and $R_E$, $P(r)$ satisfying
\begin{eqnarray}
P(R_I) & = & 0, \\
P(R_E) & = & 0, \\
\left. \left( \frac{dP}{dr} \right) \right\rvert_{R_I^+} & = & \frac{M_C \rho_S}{\left(2 M_C - R_I \right) R_I} , \\
\left. \left( \frac{dP}{dr} \right) \right\rvert_{R_E^-} & = & \frac{M \rho_S}{\left(2 M - R_E \right) R_E} .
\end{eqnarray}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection*{Interior region}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

In the interior region, the metric is given by
\begin{equation}
ds^2 = - e^{2 \phi_S(R_I)} \left(1 - \frac{2M_C}{R_I} \right)^{-1} \left(1 - \frac{2M_C}{r} \right) dt^2 + \left(1-\frac{2M_C}{r} \right)^{-1} dr^2 + r^2 d\Omega^2 .
\end{equation}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection*{Core}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
Within the core, 
\begin{eqnarray}
m_C(r) & = & \frac{4 \pi}{3} \rho_C r^3 , \\
\phi_C(r) & = & A_C + \int \frac{m_C(r) + 4 \pi r^3 P(r)}{r [r-2 m_C(r)]} dr .
\end{eqnarray}
with $A_C$ such that 
\begin{equation}
e^{2 \phi_C(R_C)} = e^{2 \phi_S(R_I)} \left(1 - \frac{2M_C}{R_I} \right)^{-1} \left(1 - \frac{2M_C}{R_C} \right) 
\end{equation}
and, to ensure continuity of $P(r)$ and $F(r)$ at $R_C$, $P(r)$ satisfying
\begin{eqnarray}
P(R_C) & = & 0, \\
\left. \left( \frac{dP}{dr} \right) \right\rvert_{R_C^-} & = & \frac{M_C \rho_C}{\left(2 M_C - R_C \right) R_C} .
\end{eqnarray}

