\caption{Decomposing OOS Performance: A Trend-based Probability Framework}
\label{alg:1}
\textbf{INPUT:} $r_t$, $r_{t+1}$, $\hat{r}_{t+1}$, $\hat{r}_{\text{benchmark}, t+1}$ \\
\textbf{OUTPUT:} $\text{TrendClass}$, $\text{PerfClass}$ \\[0.5em]
\textbf{STEP 1: Compute Trend Classification}
{\footnotesize
\begin{algorithmic}[1]
    \IF{$r_{t+1} \ge r_t$} 
        \IF{$\hat{r}_{t+1} < r_t$}
            \STATE $\text{TrendClass} \gets \text{False Trend (FT)}$
        \ELSIF{$r_t \le \hat{r}_{t+1} < r_{t+1}$}
            \STATE $\text{TrendClass} \gets \text{Right Weak Trend (RWT)}$
        \ELSE
            \STATE $\text{TrendClass} \gets \text{Right Strong Trend (RST)}$
        \ENDIF
    \ELSE 
        \IF{$\hat{r}_{t+1} > r_t$}
            \STATE $\text{TrendClass} \gets \text{False Trend (FT)}$
        \ELSIF{$r_{t+1} < \hat{r}_{t+1} \le r_t$}
            \STATE $\text{TrendClass} \gets \text{Right Weak Trend (RWT)}$
        \ELSE
            \STATE $\text{TrendClass} \gets \text{Right Strong Trend (RST)}$
        \ENDIF
    \ENDIF
\end{algorithmic}
} % end small

\vspace{0.5em}
\textbf{STEP 2: Compute Benchmark-Based Performance Classification}

{\footnotesize
\begin{algorithmic}[1]
    \STATE $L \gets r_{t+1} - |\hat{r}_{\text{benchmark}, t+1} - r_{t+1}|$
    \STATE $U \gets r_{t+1} + |\hat{r}_{\text{benchmark}, t+1} - r_{t+1}|$

    \IF{$\hat{r}_{t+1} < L$}
        \STATE $\text{PerfClass} \gets \text{Downward Loss (DL)}$
    \ELSIF{$L \le \hat{r}_{t+1} < r_{t+1}$}
        \STATE $\text{PerfClass} \gets \text{Downward Gain (DG)}$
    \ELSIF{$r_{t+1} < \hat{r}_{t+1} \le U$}
        \STATE $\text{PerfClass} \gets \text{Upward Gain (UG)}$
    \ELSE
        \STATE $\text{PerfClass} \gets \text{Upward Loss (UL)}$
    \ENDIF
\end{algorithmic}
} % end small
\end{algorithm}



