\title{Multilevel Decomposition of Generalized Entropy Measures Using Constrained Bayes Estimation: An Application to Japanese Regional Data}

\author{
Yuki Kawakubo\footnote{Graduate School of Social Sciences, Chiba University, (E-mail: \texttt{kawakubo@chiba-u.jp})} \ and
Kazuhiko Kakamu\footnote{Graduate School of Data Science, Nagoya City University, (E-mail: \texttt{kakamu@ds.nagoya-cu.ac.jp})}
